INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18696, 497, 0, 5, 1, NULL, NULL, NULL, 'Jelaskan perbedaan antara hak dan kewajiban!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Hek memiliki pengertian tentang sesuatu hal yang benar, milik, kepunyaan, kewenagan, kekuasaan untuk berbuat sesuatu (karena telah ditentukan oleh undang-undang, aturan, dsb), kekusasaan yang benar atas sesuatu atau untuk menuntut sesuatu, derajat atau martabat. Sedangkan kewajiban adalah sesuatu yang diwajibkan, yang harus dilaksanakan, pekerjaan, tugas menurut hukum segala sesuatu yang menjadi tugas manusia. Jadi, hak dan kewajiban warga negara berarti kekuasaan yang benar atas sesuatu dan haru dilakukan oleh penduduk sebuah negara.</div>', 1696898966, 1696898966, 1, '', 1, 0, 0, '71e0eaee-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
