INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18700, 497, 0, 5, 5, NULL, NULL, NULL, 'Sebutkan beberapa contoh pelanggaran hak warga negara menurut UU!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Berikut ini beberapa contoh pelanggaran hak warga negara menurut UU yaitu sebagai berikut:</div><ul><li>Penagkapan dan penahanan seseorang demi menjaga stabilitas, tanpa berdasarkan hukum.</li><li>Penerapan budaya kekerasan untuk menindak warga masyarakat yang dianggap ekstrem dan dinilai oleh pemerintah mengganggu stabilitas keamanan yang akan membahayaka kelangsungan pembangunan.</li><li>Pembungkaman kebebasan pers dengan cara pencabutan SIUP, khususnya terhadap pers yang dinilai mengkritisi kebijkan pemerintah, dengan dalih mengganggu stabilitas keamanan.</li><li>Menimbulkan rasa ketakutan dimasyarakat luas terhadap pemerintah karena takut dicurigai sebagai oknum pengganggu stabilitas atau oppsan pemerintah (ekstrem). Hilangnya rasa aman ini merupakan salah satu bentuk pelanggaran hak asasi warga negara.</li><li>Pembatasan hak berserikat dan berkumpul serta menyatakan pendapat karena dikhawatirkan akan menjadi oposan terhadap pemerintah.</li></ul>', 1696898966, 1696898966, 1, '', 1, 0, 0, '71e0ef1b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
