INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18730, 498, 0, 4, 10, NULL, NULL, NULL, 'Sikap seseorang yang selalu menuntut haknya, sementara kewajibannya sering diabaikan merupakan pelanggaran Hak Asasi Manusia yang disebabkan oleh faktor ....', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'internal', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e113a9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18731, 498, 0, 1, 5, NULL, NULL, NULL, '<p>Perhatikan isi Pasal 28A UUD NRI Tahun 1945 berikut ini!</p><p>Setiap orang berhak untuk hidup serta berhak mempertahankan hidup dan kehidupannya.</p><p>Makna yang terkandung dalam pasal 28A UUD&nbsp; NRI Tahun 1945 adalah ....</p>', 'setiap orang bebas memeluk agama', 'setiap warga negara Indonesia memiliki hak yang sama untuk membentuk keluarga dan melanjutkan keturunan melalui perkawinan yang sah', 'setiap anak sejak dia lahir memiliki hak untuk hidup, tumbuh, berkembang, serta berhak atas perlindungan dari kekerasan dan diskriminasi', 'tidak ada satu orang pun yang bisa membeli nyawa orang lain atau menghilangkan nyawa orang lain dengan alasan apapun', 'setiap orang berhak untuk mengembangkan diri dalam hal pendidikan, teknologi dan pengetahun serta seni budaya untuk meningkatkan kualitas hidupnya dan demi kesejahteraan manusia, terutama rakyat Indonesia', NULL, NULL, NULL, NULL, NULL, 'd', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e11467-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18732, 498, 0, 5, 1, NULL, NULL, NULL, 'Apakah upaya perlindungan dan pemajuan HAM hanya berpedoman pada Pancasila?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Penegakan Hak Asasi Manusia tentu berpedoman pada Pancasila. Namun selain Pancasila hak asasi manusia juga diatur secara lebih dirin didalam peraturan perundang-undangan nasional. Selain itu norma dalam masyarakat pun dapat menjadi pediman dalam penegakan hak asasi manusia, juga dari segi hati nurani dan agama. Jadi pedoman hak asasi manusia Pancasila, peraturan perundang-undangan, norma masyarakat, hingga agama.<br>', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e115ed-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18733, 498, 0, 5, 2, NULL, NULL, NULL, 'Untuk melindungi, menjamin, dan memajukan hak asasi manusia dibutuhkan instrumen HAM berupa peraturan perundangan dan lembaga penegakan HAM (Seperti KOMNAS HAM). Apa saja 4 fungsi instrumen penegakan HAM?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Fungsi instrumen HAM, diantaranya adalah sebagai berikut :</div><ul><li>Pencegahan pelanggaran HAM</li><li>Jaminan pemajuan HAM</li><li>Perlindungan HAM</li><li>Penegakan HAM</li></ul>', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e116bb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18734, 498, 0, 5, 3, NULL, NULL, NULL, 'Upaya Pemerintah dalam membangun supremasi hukum dalam upaya penegakan HAM sangatlah penting. Menurut anda, bagaimanakan kondisi supremasi hukum Indonesia saat ini?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>Gambaran Supremasi Hukum di Indonesia diantaranya sebagai berikut:</p><ul><li>masih maraknya budya kekerasan korupsi, kolusi dan nepotisme di institusi penegak hukum</li><li>masih rendahnya budaya hukum yang menghormati HAM</li></ul>', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e11775-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18735, 498, 0, 5, 4, NULL, NULL, NULL, 'Setelah menerima pengaduan tentang pelanggaran HAM, Komnas&nbsp; HAM kemudian melakukan pemeriksaan. LAngkah seperti apa yang dilakukan oleh Komnas HAM dalam melakukan pemeriksaan?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tahap pemeriksaan dilakukan dengan memanggil pengadu, saksi atau pihak lain yang terkait. Tujuannya adalah untuk menentukan dilanjutkan atau tidaknya pemeriksaan berdasarkan bukti dalam pemeriksaan.<br>', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e118e5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18736, 498, 0, 5, 5, NULL, NULL, NULL, 'Mengapa perlindungan dan penegakan HAM membutuhkan perlindungan ketentuan hukum?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Supaya keputusan HAM dapat mempunyai kemampuan hukum yang lebih kuat (ada kepastian hukum). Negara bisa melakukan perlindungan, pemenuhan ataupun penegakan HAM pada warganya karena sudah ada dasar hukumnya. Demikian juga orang-orang/ individu bida menikmati maupun menegakkan HAM nya.<br>', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e1199e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18737, 498, 0, 3, 2, NULL, NULL, NULL, 'Kelompokan pelanggaran hak asasi manusia dibawah ini berdasarkan faktor-faktor penyebabnya!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:8:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:15:\"Faktor Internal\";i:2;s:16:\"Faktor Eksternal\";}i:1;a:3:{i:0;s:49:\"Sikap egois dan terlalu mementingkan diri sendiri\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:24:\"Penyalahgunaan Kekuasaan\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:35:\"Ketidaktegasan Aparat Penegak Hukum\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:37:\"Rendahnya Kesadaran Hak Asasi Manusia\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:24:\"Penyalahgunaan Teknologi\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:42:\"Kesenjangan sosial dan ekonomi yang tinggi\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:7;a:3:{i:0;s:19:\"Sikap tidak toleram\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1696898987, 1696984498, 1, '', 1, 0, 0, '71e11a5a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18738, 498, 0, 1, 6, NULL, NULL, NULL, '<p>Perhatikan isi Pasal 29 ayat (2) UUD NRI Tahun 1945 berikut ini!</p><p>Negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan untuk beribadat menurut agamanya dan kepercayaannya itu.</p><p>Makna yang terkandung dalam Pasal 29 ayat (2) UUD NRI Tahun 1945 adalah ....</p>', 'hanya ada lima agama yang diakui negara', 'negara berdasarkan atas Ketuhanan Yang Maha Esa', 'adanya jaminan hukum kebebasan dalam beragama oleh negara', 'hak hidup dan mempertahankan hidup dan kehidupannya', 'negara yang rakyatnya beriman dan bertakwa kepada Tuhan Yang Maha Esa', NULL, NULL, NULL, NULL, NULL, 'c', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e11bd2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18739, 498, 0, 1, 7, NULL, NULL, NULL, 'Pelanggaran HAM dapat terjadi karena ada faktor yang menjadi penyebabnya, baik itu internal amupun eksternal. Contoh fakta yang tidak menyebabkan pelanggaran HAM adalah ....', 'terjadinya penyalahgunaan kekuasaan', 'kurang tegasnya aparat penegak hukum', 'terjadinya penyalahgunaan teknologi', 'kesenjangan sosial dan ekonomi yang tinggi', 'tegasnya aparat penegak hukum dalam menindak pelanggaran', NULL, NULL, NULL, NULL, NULL, 'e', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e11c95-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18740, 498, 0, 1, 8, NULL, NULL, NULL, '<p>Banyak faktor yang menyebabkan pelanggaran HAM, baik faktor internal baik yang disebabkan oleh sang pelaku itu sendiri ataupun faktor eksternal yang disebabkan oleh keluarga, teman, saudara dan lingkungan tempat sipelaku tinggal.</p><p>Contoh faktor internal yang dapat menyebabkan pelanggaran HAM adalah ....</p>', 'sikap mementingkan kepentingan umum', 'sikap egois yang tinggi', 'tingginya sikap toleransi', 'tingginya kesadaran HAM', 'tegasnya aparat penegak hukum', NULL, NULL, NULL, NULL, NULL, 'b', 1696898987, 1696898987, 1, '', 1, 0, 0, '71e11d55-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
