INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (18985, 526, 0, 1, 2, NULL, NULL, NULL, '<p style=\"text-align: center; \"><b>WABAH TIFUS DI CIREBON PADA MASA HINDIA BELANDA\r\n</b></p><p style=\"text-align: justify; \">\r\nPada tahun 1911  hingga tahun 1940 terjadi wabah tifus di Cirebon. Beberapa kajian dilakukan oleh dokter di rumah sakit Hindia Belanda untuk menemukan  penyaki dari wabah. Hasil penelitian dari dokter Grijin menyatakan wabah tifus terjadi karena faktor lingkungan yang tidak Higienis sebagai akibat dari pembangunan infrastruktur yang dilakukan  oleh pemerintah  Hindia Belanda. Air bersih yang bersumber dari gunung Ciremai telah tercemar akibat pembangunan. wabah semakin meluas, juga dipengaruhi oleh jumlah penduduk yang semakin banyak serta terbatasnya akses penduduk pribumi untuk mendapatkan air bersih dan pelayanan kesehatan.\r\n</p><p style=\"text-align: justify;\">\r\nBanyak korban berjatuhan dari peristiwa wabah tersebut. Sosialisasi hidup sehat dan kebersihan lingkungan  menjadi program kerja pemerintah Hindia Belanda kala itu untuk menekan agar wabah tidak semakin meluas. Beberapa catatan ketidakadilan terjadi terkait penanganan wabah., akses yang terbatas bagi penduduk pribumi untuk mendapatkan layanan kesehatan dan tingkat kesejahteraan yang rendah. hal ini terjadi karena pemerintah Hindia Belanda mengabaikan kesejahteraan penduduk demi menguntungkan perusahaan asing kala itu.\r\n</p><p style=\"text-align: justify;\">\r\nHikmah yang&nbsp; diambil dari cerita di atas adalah.....</p>', 'bagaimana masyarakat mengelola atau daur&nbsp; ulang sampah yang berfaedah', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">bagaimana masyarakat kita saat ini dapat menjaga kebersihan diri dan lingkungannya agar tidak terserang penyakit tifus seperti pada masyarakat Cirebon masa dulu</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">bagaimana masyarakat Cirebon  memberantas penyakit tifus yang terjadi  agar tidak berdampak luas  pada masyarakat yang lain</span></div>', 'Masyarakat Cirebon harus&nbsp; lebih serius menangani kasus sampah', 'Akibat wabah Tifus banyak masyarakat Cirebon meninggal dunia', NULL, NULL, NULL, NULL, NULL, 'b', 1696914470, 1729837653, 1, '', 1, 0, 0, '71e12c81-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
