INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (19447, 558, 0, 5, 1, NULL, NULL, NULL, '<p class=\"MsoListParagraph\" style=\"\"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Jelaskan apa yang anda ketahui tentang spektrum\r\nelektromagnetik!</span><o:p></o:p></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoListParagraph\"><span xss=removed>spektrum elektromagnetik adalah  ragam gelombang elektromagnetik yang\r\ndikategorikan berdasarkan rentang panjang gelombang atau frekuensinya</span><o></o></p>', 1697000156, 1697000156, 1, '', 1, 0, 0, '71e2308a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (19448, 558, 0, 5, 2, NULL, NULL, NULL, '<p class=\"MsoListParagraph\" style=\"\">Sebutkan sifat-sifat radiasi gelombang\r\nelektromagnetik!<o:p></o:p></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<ul><li>Merupakan perambatan getaran medan listrik\r\ndan medan magnet yang saling tegaklurus terhadap arah rambatnya.</li><li>Kecepatannya konstan di ruang hampa,\r\nyaitu sebesar 3 × 108 m/s.</li><li>Tidak dipengaruhi oleh medan listrik dan\r\nmedan magnet karena tidak</li><li>Dapat dipantulkan, dibiaskan, interferensi,\r\ndan polarisasi.</li><li>Dapat merambat dalam ruang hampa atau\r\nvakum.</li><li>Merupakan gelombang transversal</li><li>Dapat bersifat sebagai partikel dan\r\nmemiliki energi yang bergantung pada frekuensi sesuai dengan persamaan</li></ul><p class=\"MsoListParagraphCxSpLast\"><o></o></p>', 1697000156, 1697000156, 1, '', 1, 0, 0, '71e232ec-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (19449, 558, 0, 5, 3, NULL, NULL, NULL, '<p class=\"MsoListParagraph\" style=\"\">Perhatikan gambar berikut!&nbsp;</p><p class=\"MsoListParagraph\" style=\"\"><img src=\"http://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20221118085018.jpg\" style=\"width: 495px;\"></p><p class=\"MsoListParagraph\">Urutan Radiasi gelombang elektromagnetik yang\r\nmemiliki frekuensi (ƒ) tertinggi ke terendah adalah …&nbsp;<o:p></o:p></p><p class=\"MsoListParagraph\" style=\"\"><o:p></o:p></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'gelombang radio - gelombang mikro - infra merah - cahaya tampak - ultraviolet - sinar-x - sinar gamma', 1697000156, 1697000156, 1, '', 1, 0, 0, '71e2341e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (19450, 558, 0, 5, 4, NULL, NULL, NULL, 'Sebutkan 5 manfaat gelombang mikro!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<ul><li>Pemanas microwave. </li><li>Komunikasi radar (radio detection and ranging). </li><li>Menganalisis struktur atomik dan molekul. </li><li>Mengukur kedalaman laut. </li><li>Mendeteksi suatu objek. </li><li>Memandu pendaratan pesawat terbang. </li><li>Membantu pengamatan di kapal laut dan pesawat terbang pada malam \r\nhari atau cuaca kabut, serta menentukan arah dan posisi yang tepat<br></li></ul>', 1697000156, 1697000156, 1, '', 1, 0, 0, '71e23663-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
