INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (19712, 498, 0, 1, 20, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Pemerintah Indonesia saat ini\r\ntengah menggalakan program wajib belajar bagi warga negara Indonesia usai\r\nsekolah dasar. Tidak boleh ada anak usia sekolah dasar yang putus sekolah.\r\nUntuk mewujudkan hal itu, Pemerintah menetapkan kebijakan BOS (Bantuan Operasional\r\nSekolah) dan berbagai bantuan lain bagi warga kurang mampu. Hal ini menunjukan\r\nbahwa Pemerintah tengah memajukan Hak Asasi warga negara yang dilindungi oleh\r\nkonstitusi (UUD NRI Tahun 1945) dalam pasal ....</p>', '<p style=\"line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">29 ayat (2</p>', '<p style=\"line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">30 ayat (1)</p>', '<div><span style=\"font-size: 0.875rem;\">31 ayat (1)</span><br></div>', '<p style=\"line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; ba