INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (20426, 528, 0, 3, 1, NULL, NULL, NULL, '<p>Hidrokarbon alifatik dibagi menjadi alkana, alkena dan alkuna. Alkana merupakan senyawa hidrokarbon alifatik jenuh, yaitu hidrokarbon dengan rantai terbuka dan semua ikatan karbonnya merupakan ikatan tunggal,dengan rumus CnH2n + 2. Alkena adalah hidrokarbon alifatik tak jenuh yang memiliki satu ikatan rangkap (C = C) sedangkan Alkuna adalah senyawa hidrokarbon alifatik tak jenuh yang mengandung ikatan rangkap tiga.</p><p>\r\n\r\n\r\n\r\n \r\n\r\nBerdasarkan rumus molekul berikut tentukanlah yang termasuk alkana, alkena atau alkuna.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:9:{i:0;a:4:{i:0;s:1:\"#\";i:1;s:6:\"Alkana\";i:2;s:6:\"Alkena\";i:3;s:6:\"Alkuna\";}i:1;a:4:{i:0;s:5:\"C5H12\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:2;a:4:{i:0;s:4:\"C3H6\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:3;a:4:{i:0;s:5:\"C7H12\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:4;a:4:{i:0;s:6:\"C11H22\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:5;a:4:{i:0;s:5:\"C8H16\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:6;a:4:{i:0;s:4:\"C4H6\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"1\";}i:7;a:4:{i:0;s:5:\"C7H16\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:8;a:4:{i:0;s:4:\"C2H2\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}}}', 1697154983, 1697155255, 1, '', 1, 0, 0, '71e2eaf5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
