INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (20476, 583, 0, 1, 17, NULL, NULL, NULL, 'Dalam rangka mempertahankan Jawa dari kekuasaan Inggris, Daendels melakukan langkah-langkah sebagai berikut kecuali.....', 'membangun benteng-benteng pertahanan baru seperti benteng Mester Cornelis', 'membangun pangkalan angkatan laut di Anyer dan ujungkulon', 'meningkatkan jumlah tentara dengan mengambil orang-orang pribumi', 'membangun jalan raya dari Anyer (awa) barat ) sampai Panurukan (Jawa Timur)', 'meningkatkan transportasi laut', NULL, NULL, NULL, NULL, NULL, 'e', 1697155758, 1729149499, 1, '', 1, 0, 0, '71e3678d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
