INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (20503, 583, 0, 2, 4, NULL, NULL, NULL, 'Dalam bidang ekonomi Daendels melakukan beberapa tindakan untuk mendatangkan keuntungan bagi pemerintah kolonial yaitu:', 'a:5:{s:1:\"a\";s:103:\"<p>meningkatkan usaha pemasukan uang dengan cara pemungutan pajak dan penjualan tanah kepada swasta</p>\";s:1:\"b\";s:76:\"<p>meningkatkan penanaman tanaman yang hasilnya  laku di pasaran dunia.</p>\";s:1:\"c\";s:73:\"<p>rakyat diwajibkan menyerahkan hasil pertaniannya kepada pemerintah</p>\";s:1:\"d\";s:46:\"<p>rakyat bebas melakukan usaha ekonominya</p>\";s:1:\"e\";s:104:\"<p>pemerintah wajib membagi tanah-tanah pemerintah  yang bebas atau belum digarap kepada  rakyat </p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"c\";i:3;N;}', 1697155758, 1700623599, 1, '', 1, 0, 0, '71e39ad4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:17', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
