INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21511, 604, 0, 3, 3, NULL, NULL, NULL, 'Urutan Mekanisme penyusunan APBD yang benar adalah ...&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:7:{i:0;s:1:\"#\";i:1;s:1:\"1\";i:2;s:1:\"2\";i:3;s:1:\"3\";i:4;s:1:\"4\";i:5;s:1:\"5\";i:6;s:1:\"6\";}i:1;a:7:{i:0;s:160:\"APBD yang telah ditetapkan dengan Perda disampaikan kepada gubernur bagi pemerintah kota/kabupaten dan kepada presiden melalui Mendagri bagi pemerintah provinsi\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"1\";}i:2;a:7:{i:0;s:91:\"Perubahan APBD ditetapkan dengan Perda paling lambat tiga bulan sbelum berakhirnya anggaran\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"0\";}i:3;a:7:{i:0;s:84:\"Pemerintah daerah menyusun RAPBD (Rancangan Anggaran Pendapatan dan Belanja Daerah).\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:4;a:7:{i:0;s:121:\"Pemerintah daerah akan mengajukan RAPBD tersebut kepada DRPD untuk dirapatkan apakan RAPBD tersebut disetujui atau tidak.\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:5;a:7:{i:0;s:75:\"APBD ditetapkan dengan perda paling lambat satu bulan setelah APBN disahkan\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:6;a:7:{i:0;s:83:\"Jika DPRD memutuskan untuk menyetujui RAPBD, maka RAPBD akan disahkan menjadi APBD.\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}}}', 1697191888, 1699869090, 1, '', 1, 0, 0, '71e55451-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21512, 604, 0, 3, 4, NULL, NULL, NULL, 'Perhatikan beberapa pernyataan tentang indeks harga di bawah ini, Tentukan mana pernyataan yang benar!\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:5:\"Benar\";i:2;s:5:\"Salah\";}i:1;a:3:{i:0;s:106:\"Angka indeks harga dapat dijadikan standar/pedoman untuk melakukan perbandingan harga dari waktu ke waktu.\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:98:\"Angka indek harga menunjukkan perubahan-perubahan yang terjadi atas harga pada pasar-pasar primer.\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:109:\"Indek harga merupakan petunjuk/indikator yang dapat digunakan untuk mengukur pertumbuhan ekonomi secara umum.\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:95:\"Indek harga pedagang besar dapat memberikan gambaran/trend dalam perdagangan di tingkat eceran.\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:184:\"Indeks harga konsumen adalah ukuran statistik yang dapat menunjukkan perubahan- perubahan yang terjadi pada harga eceran barang dan jasa yang diminta oleh konsumen dari waktu ke waktu.\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1697191888, 1699869085, 1, '', 1, 0, 0, '71e55662-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21513, 604, 0, 3, 5, NULL, NULL, NULL, '<div>Inflasi memengaruhi masyarakat, baik yang berpenghasilan tetap atau tidak tetap. Adapun dampak inflasi terhadap penghasilan masyarakat adalah sebagai berikut.</div><div>a.<span style=\"white-space:pre\">	</span>Dalam masa inflasi, nilai harta tetap mengalami kenaikan harga melebihi kenaikan inflasi. Pendapatan riil penduduk berpenghasilan tidak tetap mengalami penurunan atau merosot. Dengan demikian inflasi akan memperlebar kesenjangan distribusi pendapatan di antara anggotamasyarakat.</div><div>b.<span style=\"white-space:pre\">	</span>Inflasi merugikan masyarakat yang berpendapatan tetap, karena upah/gaji yang diperoleh tidak dapat mengikuti/menyesuaikan kenaikan harga, sehingga semakin berat dirasakan oleh masyarakat.</div><div>c.<span style=\"white-space:pre\">	</span>Inflasi menyebabkan orang-orang enggan untuk menabung dan mendorong untuk mencari pinjaman dalam rangkamenyesuaikan pendapatan. Hal ini akan menghambat perkembangan dunia usaha.</div><div><img src=\"http://pas.id/siswa/uploads/bank_soal/file_20220329020238.jpg\" style=\"width: 532px;\"></div><div><br></div><b><i>Inflasi menimbulkan dampak Pihak yang diuntungkan dan dirugikan&nbsp; berikut ini.... (pilih yang sesuai)\r\n</i></b>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:9:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:17:\"Pihak di Utungkan\";i:2;s:16:\"Pihak di Rugikan\";}i:1;a:3:{i:0;s:22:\"Eksportir atau Penjual\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:21:\"Importir atau pembeli\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:35:\"Debitur / pihak yang memiliki utang\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:38:\"Kreditur / pihak yang memiliki piutang\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:31:\"Speklulan / berani berspekulasi\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:6;a:3:{i:0;s:20:\"Berpenghasilan tetap\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:7;a:3:{i:0;s:27:\"Berpenghasilan tinggi/besar\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:8;a:3:{i:0;s:30:\"Berpenghasilan rendah / miskin\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1697191888, 1699869071, 1, '', 1, 0, 0, '71e55877-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21514, 604, 0, 4, 1, NULL, NULL, NULL, 'APBN oleh pemerintah digunakan sebagai alat untuk memelihara dan mengupayakan keseimbangan fundamental perekonomian, dalam hal ini pemerintah melaksanakan fungsi . . . .', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'stabilisasi', 1697191888, 1697191888, 0, '', 1, 0, 0, '71e55aec-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
