INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21554, 605, 0, 1, 1, 'a:0:{}', NULL, NULL, '<p style=\"margin-top: 0pt; margin-bottom: 0pt;\">Kata ekonomi berasal dari oikonomia, yang berarti .... </p> <p></p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">kebutuhan manusia</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">pengaturan rumah tangga</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">pengaturan kekayaan</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">kelangkaan</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">kemakmuran </p>', NULL, NULL, NULL, NULL, NULL, 'a', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5a188-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21555, 605, 0, 1, 2, 'a:0:{}', NULL, NULL, '<p style=\"margin-top: 0pt; margin-bottom: 0pt;\"><b>Penyebab Kelangkaan Minyak Goreng di Indonesia</b></p><p style=\"margin-top: 0pt; margin-bottom: 0pt;\"><b><br></b></p> <p style=\"margin-top: 0pt; margin-bottom: 0pt;\">Jakarta - Kelangkaan minyak goreng di Indonesia masih terus terjadi. Ketersediaan di berbagai warung hingga toserba sampai saat ini masih sulit ditemukan.Pakar ekonomi Universitas Airlangga (Unair) Rossanto Dwi Handoyo SE MSi PhD menyebutkan bahwa kelangkaan minyak goreng di pasaran tidak terlepas dari mekanisme penawaran dan permintaan.\'Minyak goreng merupakan salah satu komoditas penting di Indonesia. Berdasarkan IHK (Indeks Harga Konsumen) Indonesia, minyak goreng memiliki kontribusi yang besar. Hal tersebut karena minyak goreng merupakan salah satu barang yang dikonsumsi masyarakat setiap harinya. Bobot terhadap inflasinya juga cukup tinggi,\' ucap Rossanto dikutip dari laman resmi Unair.Kelangkaan minyak goreng disebabkan karena ada kenaikan dari sisi permintaan (demand) dan penurunan dari sisi penawaran (supply). Beberapa faktor berikut menjadi penyebab penurunan supply, utamanya produsen mengalami penurunan dalam memasarkan minyak goreng di dalam negeri. Di antaranya adalah sebagai berikut.Penyebab Kelangkaan Minyak Goreng di Indonesia:</p><p style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-size: 0.875rem;\">1. Naiknya Harga Minyak Nabati</span><br></p> <p style=\"margin-top: 0pt; margin-bottom: 0pt;\">2. Pemerintah Mencanangkan Program B30</p> <p style=\"margin-top: 0pt; margin-bottom: 0pt;\">3. Pandemi Covid-19 Belum Usai</p> <p style=\"margin-top: 0pt; margin-bottom: 0pt;\">4. Proses Distribusi dan Logistik</p> <p style=\"margin-top: 0pt; margin-bottom: 0pt;\">Rossanto mengungkapkan, naiknya harga minyak goreng ini juga akan mendorong inflasi secara umum. Dampak yang ditimbulkan dapat memengaruhi beberapa sektor, di antaranya sektor industri makanan, rumah tangga, dan semua produksi yang menggunakan bahan baku minyak goreng.</p> <p style=\"margin-top: 0pt; margin-bottom: 0pt;\">\'Oleh karena itu dampaknya juga akan lebih terasa terhadap inflasi terutama dari segi IHK,\' tutur pakar ekonomi Unair itu.</p> <p style=\"margin-top: 0pt; margin-bottom: 0pt;\"><br></p><p style=\"margin-top: 0pt; margin-bottom: 0pt;\"><i>Apa yang anda ketahui tendang kelangkaan ....</i></p> <p></p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">suatu kondisi ketika sesuatu barang atau jasa banyak tersedia saat musim panen tetapi tidak ada saat bukan musim panen</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">suatu kondisi dimana sesuatu barang tersedia dalam jumlah tidak terbatas di suatu tempat, tetapi barang tersebut sulit dicari pada tempat lain</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">suatu kondisi ketika manusia memiliki sumber daya ekonomi yang terbatas untuk memenuhi kebutuhan yang tidak terbatas</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">suatu keadaan dimana barang tersedia dalam jumlah tidak terbatas, namun sulit terbeli karena tidak memiliki uang</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">suatu keadaan dimana banyak uang yang tersedia tetapi barang dan jasa yang akan dibeli tidak ada. </p>', NULL, NULL, NULL, NULL, NULL, 'e', 1697191904, 1700731437, 1, '', 8, 0, 0, '71e5a2fc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21556, 605, 0, 1, 3, 'a:0:{}', NULL, NULL, '<p>Kawasan \'Lembah Hijau\' dikenal memiliki potensi sumber daya alam yang luar biasa, mulai dari lahan pertanian subur, cadangan mineral yang beragam, hingga potensi energi terbarukan yang signifikan. Namun, studi komprehensif yang dilakukan oleh Kementerian Perencanaan Pembangunan Nasional menemukan bahwa meskipun memiliki kekayaan alam tersebut, tingkat kemiskinan dan kelangkaan akses terhadap barang dan jasa esensial masih relatif tinggi di beberapa komunitas.</p><p>Laporan tersebut menyoroti bahwa sebagian besar sumber daya alam di Lembah Hijau dieksploitasi dengan metode tradisional yang kurang efisien, serta terdapat keterbatasan investasi dalam teknologi pengolahan modern dan pengembangan kapasitas sumber daya manusia lokal untuk mengelola dan mengoptimalkan pemanfaatan kekayaan alam tersebut secara berkelanjutan.</p><p>Menganalisis kondisi yang dihadapi oleh Kawasan Lembah Hijau, faktor fundamental yang paling signifikan dalam menjelaskan fenomena kelangkaan barang dan jasa, meskipun sumber daya alam tersedia melimpah, adalah refleksi dari...</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">melimpahnya sumber daya alam yang tersedia</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">seimbangnya antara kemajuan ilmu pengetahuan dan teknologi dengan peningkatan kebutuhan</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">terbatasnya kemampuan yang dimiliki manusia dalam mengolah sumber daya alam yang ada</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">melimpahnya tenaga ahli</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">kreativitas manusia dalam penciptaan kebutuhan baru</p></body></html>', NULL, NULL, NULL, NULL, NULL, 'c', 1697191904, 1766372490, 1, '', 8, 0, 0, '71e5a53f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21557, 605, 0, 1, 4, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Mayoritas penduduk Indonesia mengkonsumsi beras, tetapi produksi beras saat ini menurun. Di kota-kota tertentu sudah terasa kelangkaan terjadi sehingga beras melambung tinggi. Hasil penelitian sementara menyatakan permasalahan ini diakibatkan mahalnya bibit padi. Untuk pemecahan masalah kelangkaan tersebut yang tepat adalah .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>berhenti berproduksi padi, beralih kepada produksi pangan alternatif</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>memberikan penyuluhan kepada petani cara meningkatkan produksi padi</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>memberikan subsidi kepada petani dan mengurangi konsumsi beras</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>memberikan subsidi kepada petani untuk membeli bibit dan membuka lahan pertanian baru</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>memberlakukan program transmigrasi ke daerah yang kosong atau baru </p>', NULL, NULL, NULL, NULL, NULL, 'D', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5a749-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21558, 605, 0, 1, 5, 'a:0:{}', NULL, NULL, '<p><b>STUDI KASUS: Krisis Energi di Pulau Seruni</b></p><p>Pulau Seruni, sebuah pulau terpencil di wilayah timur Indonesia, sedang menghadapi krisis energi yang serius. Selama tiga minggu terakhir, pasokan Bahan Bakar Minyak (BBM) bersubsidi ke pulau tersebut terhambat signifikan. Situasi diperparah oleh kerusakan mendadak pada kapal pengangkut BBM reguler dan kondisi cuaca ekstrem yang menunda pengiriman alternatif melalui jalur laut.</p><p>Akibatnya, antrean panjang kendaraan roda dua dan empat terpantau mengular di satu-satunya Stasiun Pengisian Bahan Bakar Umum (SPBU) yang tersisa. Aktivitas ekonomi masyarakat mulai lumpuh; nelayan kesulitan melaut karena ketiadaan bahan bakar untuk perahu mereka, para pedagang mengeluhkan kenaikan drastis biaya transportasi barang dari dan ke pasar lokal, serta layanan transportasi umum terganggu. Pemerintah daerah setempat telah menerima banyak keluhan dari warga yang resah atas kelangsungan hidup dan usaha mereka.</p><p>Melihat urgensi situasi dan dampak ekonomi yang semakin meluas, sebagai Kepala Dinas Perdagangan dan Perindustrian Kabupaten yang membawahi Pulau Seruni, langkah strategis jangka pendek paling efektif yang dapat Anda usulkan untuk segera mengatasi kelangkaan BBM bersubsidi tersebut adalah ....</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">mengurangi pasokan bbm bersubsidi agar masyarakat tidak tergantung</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">memperbanyak bbm nonsubsidi agar masyarakat pindah dari bbm bersubsidi</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">membatasi pembelian oleh masyarakat agar tidak lagi terjadi kelangkaan</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">memperbaiki saluran distribusi sehingga tidak terjadi keterlambatan</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">mendatangkan pasokan bbm bersubsidi dari daerah lain yang berlebih </p></body></html>', NULL, NULL, NULL, NULL, NULL, 'e', 1697191904, 1766372574, 1, '', 8, 0, 0, '71e5a95c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21559, 605, 0, 1, 6, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Berikut ini adalah pasangan barang-barang</p> <p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>(1) Gula dan kopi</p> <p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>(2) Mobil dan ban</p> <p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>(3) Kemeja dan dasi</p> <p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>(4) Beras dan jagung</p> <p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>(5) Ikan-daging dan tahu-tempa </p> <p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Pasangan barang yang termasuk barang komplementer adalah ....</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(1), (2), dan (3)</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(1), (2), dan (4)</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(1), (4), dan (5)</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(2). (4), dan (5)</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(3), (4), dan (5) </p>', NULL, NULL, NULL, NULL, NULL, 'A', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5ac19-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21560, 605, 0, 1, 7, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Kebutuhan menurut intensitas adalah kebituhan dibedakan menurut .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>waktu pemenuhannya</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>pelaku yang menggunakan alat pemenuhannya</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>pemenuhan fisik dan jiwa</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>tingkat pendidikan dan peradaban</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>tingkat keutamaan pemenuhannya </p>', NULL, NULL, NULL, NULL, NULL, 'E', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5ae16-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21561, 605, 0, 1, 8, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0; margin-bottom: 0;\'>Keluarga Pak Anton memenuhi beberapa kebutuhan, diantaranya: </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(1) Membeli kebutuhan pokok sehari-hari </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(2) Pergi nonton wayang kulit dengan dalang Ki Anom Suroto </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(3) Makan bakso sapi dengan keluarga </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(4) Pergi rekreasi ke Candi prambanan </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(5) Membeli jaket saat musim dingin </p> <p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Jika ditinjau dari sifatnya, yang termasuk kebutuhan jasmani adalah ....</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(1), (2), dan (3)</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(1), (3), dan (5)</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(2), (3), dan (4)</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(2), (4), dan (5)</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>(3), (4), dan (5) </p>', NULL, NULL, NULL, NULL, NULL, 'B', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5af67-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21562, 605, 0, 1, 9, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Prinsip ekonomi yang diterapkan dalam produksi adalah dengan .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>modal yang kecil memperoleh keuntungan yang besar</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>pekerja yang sedikit memproduksi barang dalam jumlah banyak</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>cara produksi tertentu membuat konsumen rugi</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>modal maksimal memperoleh hasil yang maksimal</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>modal usaha tertentu memperoleh hasil maksimal </p>', NULL, NULL, NULL, NULL, NULL, 'E', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5b168-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21563, 605, 0, 1, 10, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Penggunaan uang yang diberikan orangtua dengan cara bijak terlihat dalam contoh .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Irma menggunakan sebagian uang jajannya untuk menabung di koperasi sekolah</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Raisa mentraktir teman-teman sekelasnya dengan uang yang diberikan ayahnya</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Karin membeli makanan sehat di kantin sekolah setiap hari</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Nino menggunakan uangnya untuk bermain games online di rental dekat sekolahnya</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Andri meminjamkan uangnya pada Sandi untuk membayar iuran sekolah </p>', NULL, NULL, NULL, NULL, NULL, 'A', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5b28c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21564, 605, 0, 1, 11, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Hadi membuka usaha pangkas rambut. Pada akhir bulan ia menghitung seluruh penerimaan yang didapatkan selama 1 bulan dan pengeluaran termasuk biaya untuk tempat usahanya, walaupun ia buka usaha di garasi rumahnya. Biaya yang dihitung Hadi merupakan biaya .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>eksplisit</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>sesungguhnya</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>peluang</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>sehari-hari</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>implisit </p>', NULL, NULL, NULL, NULL, NULL, 'D', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5b475-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21565, 605, 0, 1, 12, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Robert memutuskan untuk pergi berlibur ke Danau Kelimutu. Dibutuhkan biaya transportasi Rp200.000,00. Untuk biaya jajan diperlukan Rp100.000,00. Untuk kunjungan stand-stand yang dipilih perlu biaya Rp250.000,00. Jika sekiranya Sanusi tidak berlibur ke Danau Kelimutu maka ia dapat bekerja di suatu konveksi dengan pendapatan Rp300.000,00. Biaya peluang dari liburan Sanusi ke Danau Kelimutu adalah .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Rp300.000,00</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Rp250.000,00 </p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Rp200.000,00 </p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Rp100.000,00 </p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Rp50.000,00 </p>', NULL, NULL, NULL, NULL, NULL, 'A', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5b619-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21566, 605, 0, 1, 13, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Berikut ini yang merupakan contoh tindakan efisien adalah .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Fitri lebih suka belanja di pasar daripada di supermarket karena harganya lebih murah dengan kualitas yang sama</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Dini berangkat ke sekolah menggunakan taksi padahal masih ada angkutan umum</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Hadi tidak pernah menawar harga barang setiap kali berbelanja</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Gani setiap hari membeli mainan baru</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Dedi tidak dapat berhemat dalam menggunakan uang jajannya </p>', NULL, NULL, NULL, NULL, NULL, 'A', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5b7b6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21567, 605, 0, 1, 14, 'a:0:{}', NULL, NULL, '<p>Saudara Fani, seorang lulusan baru dari program studi Manajemen Bisnis, berada di persimpangan jalan dalam menentukan jenjang kariernya. Setelah melalui serangkaian wawancara dan proses rekrutmen yang ketat, Fani menerima beberapa tawaran pekerjaan dari berbagai sektor.</p><p>Tawaran pertama datang dari sebuah ritel fesyen ternama sebagai penjaga toko dengan gaji pokok sebesar Rp1.500.000,00 per bulan. Tawaran kedua adalah posisi sebagai sales representatif untuk perusahaan kosmetik multinasional dengan potensi penghasilan tetap sebesar Rp1.200.000,00 per bulan ditambah komisi penjualan. Sementara itu, tawaran ketiga yang paling menarik dari sisi finansial adalah sebagai karyawan administrasi di sebuah perusahaan swasta besar, dengan gaji bulanan yang ditawarkan sebesar Rp2.000.000,00.</p><p>Di sisi lain, Fani memiliki impian dan rencana matang untuk memulai usaha sendiri di bidang kuliner, sebuah peluang yang diyakini dapat memberikan kebebasan finansial dan kreativitas dalam jangka panjang, meskipun dengan risiko awal yang lebih tinggi.</p><p>Apabila Saudara Fani pada akhirnya memutuskan untuk merealisasikan impiannya menjadi seorang wirausaha di bidang kuliner, berapakah biaya peluang (<i>opportunity cost</i>) yang secara rasional dikorbankan dari pilihan-pilihan karier pekerjaan yang tersedia?</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp1.200.000,00</p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp1.500.000,00 </p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp2.000.000,00 </p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp3.500.000,00 </p></body></html>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp4.700.000,00 </p></body></html>', NULL, NULL, NULL, NULL, NULL, 'c', 1697191904, 1766372416, 1, '', 8, 0, 0, '71e5b917-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21568, 605, 0, 1, 15, 'a:0:{}', NULL, NULL, '<p style=\"margin-top: 0pt; margin-bottom: 0pt;\">Tn. Abu ingin membuka usaha dari uang pensiunan. Jika ia membuka usaha sablon dengan omset Rp 80.000,00/hari, usaha foto copy dengan omset Rp 60.000,00/hari dan usaha salon dengan omset Rp70.000,00/hari. (1 bulan = 30 hari). Tn Abu harus memilih salah satu dari semua kemungkinan karena ada keterbatasan modal. Setelah dipertimbangkan, Tn Abu ingin membuka usaha sablon. </p> <p style=\"margin-top: 0pt; margin-bottom: 0pt;\">Besar biaya peluang perbulan adalah … </p> <p></p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp1.800.000,00</p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp2.100.000,00 </p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp2.400.000,00 </p>', '<p style=\"margin-top: 0; margin-bottom: 0;\">Rp4.500.000,00 </p>', 'Rp4.000.000,00', NULL, NULL, NULL, NULL, NULL, 'b', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5bb1b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21569, 605, 0, 1, 16, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Saat ini persaingan usaha sangat ketat, terutama di bidang produksi plastik. Plastik dari Cina di pasar dalam negeri dijual dengan harga yang sangat murah. Pak Yuda seorang pengusaha plastik ingin mengembangkan usaha agar dapat bersaing dan meningkatkan keuntungan perusahaannya. Masalah ekonomi modern yang dihadapi Pak Yuda adalah .... </p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Untuk siapa barang tersebut diproduksi</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Berapa banyak dana untuk produksi</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Kapan barang akan diproduksi</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Barang apa yang harus diproduksi</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Bagaimana cara memproduksi barang </p>', NULL, NULL, NULL, NULL, NULL, 'E', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5bc1b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21570, 605, 0, 1, 17, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Bu Andri adalah produsen kerupuk udang yang berusaha menekan biaya produksi sehingga menghasilkan kerupuk udang dengan harga murah namun tetap berkualitas. Hal ini dilakukan karena daya beli masyarakat yang menurun. Dari ilustrasi tersebut, masalah ekonomi yang dihadapi adalah .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Untuk siapa barang diproduksi?</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Berapa barang yang diproduksi?</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Barang apa yang akan diproduksi?</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Mengapa barang diproduksi?</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Bagaimana cara memproduksi? </p>', NULL, NULL, NULL, NULL, NULL, 'E', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5bd66-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21571, 605, 0, 1, 18, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Chandra baru memulai usaha berupa sepatu olahraga. Chandra hanya melayani pembelian dalam jumlah besar yang dilakukan oleh pedagang besar. Pedagang besar akan menjual kepada pengecer dan pengecer akan menjual kepada konsumen. Hal tersebut mengakibatkan harga sepatu olahraga menjadi tinggi ketika sampai kepada konsumen. Masalah pokok ekonomi klasik yang dihadapi Chandra adalah .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Mahalnya harga yang diberikan pihak pengecer kepada konsumen</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Barang yang diproduksi tidak sesuai dengan kebutuhan masyarakat</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Chandra tidak tepat dalam memilih jenis barang yang diproduksi</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Saluran distribusi yang panjang menyebabkan penurunan jumlah penjualan</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Murahnya harga sepatu olahraga yang dijual chandra kepada pedagang besar </p>', NULL, NULL, NULL, NULL, NULL, 'D', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5bf61-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21572, 605, 0, 1, 19, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Bapak Untung merupakan produsen tas dan sepatu lukis. Dalam memasarkan produknya ia menitipkan hasil produksinya di outlet-outlet pusat perbelanjaan dan toko. Akan tetapi, harga barang menjadi tinggi sehingga jumlah konsumen menurun. Oleh karena terjadi penurunan keuntungan, Bapak Untung memutuskan untuk memasarkan produknya secara online. Berdasarkan ilustrasi tersebut, masalah pokok ekonomi klasik yang dihadapi Bapak Untung adalah .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Distributor kurang menguasai teknik pemasaran yang baik</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Harga yang ditawarkan produsen dan distributor terlalu mahal</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Produsen tidak memanfaatkan kemajuan teknologi secara baik</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Penyaluran barang dari produsen kepada konsumen tidak tepat</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>Barang tidak sesuai dengan selera pengunjung </p>', NULL, NULL, NULL, NULL, NULL, 'D', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5c1bf-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21573, 605, 0, 1, 20, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0pt; margin-bottom: 0pt;\'>Kegiatan ekonomi yang dilakukan rumah tangga produsen adalah .... </p> <p></p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>membayar pajak rumah tangga</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>memiliki tabungan</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>menggunakan faktor produksi untuk berproduksi</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>membeli barang jadi untuk karyawannya</p>', '<p style=\'margin-top: 0; margin-bottom: 0;\'>menginvestasikan dana pada lembaga keuangan </p>', NULL, NULL, NULL, NULL, NULL, 'C', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5c313-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21574, 605, 0, 2, 1, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0; margin-bottom: 0;\'>Berikut adalah kegiatan dalam tindakan ekonomi </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(1) Pengusaha warteg Suminah membeli ayam langsung ke peternak ayam </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(2) Berbelanja di pasar tradisional </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(3) Berbelanja di pasar modern super mewah </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(4) Membeli barang tanpa tawar menawar di Pasar tradisional </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(5) Selalu berusaha terlebih dahulu memenuhi kebutuhan primer </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>Pernyataan di atas yang termasuk tindakan yang berdasarkan prinsip ekonomi ditunjukkan nomor ....</p> <p style=\'margin-top: 0; margin-bottom: 0;\'><span style=\'color: #000000; font-weight: bold;\'>Berilah tanda centang (√) pada setiap pernyataan yang benar!</span><br> </p>', 'a:5:{s:1:\"a\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(1)</p>\";s:1:\"b\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(2)</p>\";s:1:\"c\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(3)</p>\";s:1:\"d\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(4)</p>\";s:1:\"e\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(5)</p>\";}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"e\";}', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5c4bf-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21575, 605, 0, 2, 2, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0; margin-bottom: 0;\'><span style=\'font-style: italic;\'>Perhatikan pernyataan berikut ini! </span></p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(1) Ekonomi mikro membahas tentang kegiatan produksi, sedangkan ekonomi makro membahas tentang perdagangan kecil </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(2) Ekonomi mikro membahas tentang kegiatan konsumsi, sedangkan ekonomi makro membahas tentang pengangguran </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(3) Ekonomi mikro membahas tentang penerimaan perusahaan, sedangkan ekonomi makro membahas tentang inflasi </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(4) Ekonomi mikro mempelajari tentang peran produsen dan konsumen, sedangkan ekonomi makro membahas tentang pendapatan perkapita </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(5) Ekonomi mikro membahas tentang pertumbuhan ekonomi, sedangkan ekonomi makro membahas tentang kebijakan pemerintah dalam bidang ekonomi </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>Perbedaan yang paling tepat antara ekonomi mikro dan ekonomi makro adalah ....</p> <p style=\'margin-top: 0; margin-bottom: 0;\'><span style=\'color: #000000; font-weight: bold;\'>Berilah tanda centang (√) pada setiap pernyataan yang benar!</span><br> </p>', 'a:5:{s:1:\"a\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(1)</p>\";s:1:\"b\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(2)</p>\";s:1:\"c\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(3)</p>\";s:1:\"d\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(4)</p>\";s:1:\"e\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(5)</p>\";}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"b\";i:1;s:1:\"c\";i:2;s:1:\"d\";}', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5c630-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21576, 605, 0, 2, 3, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0; margin-bottom: 0;\'>Perhatikan pernyataan berikut. </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(1) Penerbit mencetak buku cerita berwarna agar menarik minat anak-anak </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(2) Bu Anis menjual kebutuhan pokok di tokonya karena jauh dari pasar </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(3) Deni menjual Yoguht buatannya langsung ke konsumen. </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(4) Selain menjadi petani pisang, Pak Agus menjadi produsen keripik pisang. </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(5) Pak Aris menggunakan mesin baru untuk mengembangkan usahanya </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>Masalah pokok ekonomi klasik terdapat pada pernyataan nomor .... </p> <p style=\'margin-top: 0; margin-bottom: 0;\'><span style=\'color: #000000; font-weight: bold;\'>Berilah tanda centang (√) pada setiap pernyataan yang benar!</span></p>', 'a:5:{s:1:\"a\";s:105:\"<p style=\'margin-top: 0; margin-bottom: 0;\'><span style=\'font-family: \'Times New Roman\';\'>(1) </span></p>\";s:1:\"b\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(2)</p>\";s:1:\"c\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(3)</p>\";s:1:\"d\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(4)</p>\";s:1:\"e\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(5)</p>\";}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"b\";i:1;s:1:\"c\";i:2;s:1:\"d\";}', 1697191904, 1697191904, 1, '', 8, 0, 0, '71e5c88e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21577, 605, 0, 2, 4, 'a:0:{}', NULL, NULL, '<p style=\"margin-top: 0; margin-bottom: 0;\">Berikut ini beberapa masalah yang dihadapi oleh pelaku ekonomi </p> <p style=\"margin-top: 0; margin-bottom: 0;\">(1) Bapak Suhadi sedang berfikir barang apa yang akan diproduksi dalam rangka membuka usaha baru </p> <p style=\"margin-top: 0; margin-bottom: 0;\">(2) Ibu Mimin sedang memilih-milih barang apa yang akan ia beli sewaktu berbelanja di Mall </p> <p style=\"margin-top: 0; margin-bottom: 0;\">(3) Bapat Toto sedang menghitung-hitung berapa jumlah pesanan kaos pada bulan ini, untuk menetukan jumlah kaos yang akan dibuat </p> <p style=\"margin-top: 0; margin-bottom: 0;\">(4) Pabrik Sepeda sedang merencanakan bagaimana dapat memproduksi sepeda dengan harga di bawah Rp5.000.000,00 agar terjangkau untuk masyarakat lapisan terbawah </p> <p style=\"margin-top: 0; margin-bottom: 0;\">(5) CV Kenari sedang melaksanakan rapat pimpinan untuk memprediksi jumlah keuntungan yang akan diraih tahun ini </p> <p style=\"margin-top: 0; margin-bottom: 0;\">Yang merupakan masalah ekonomi modern adalah ....</p> <p style=\"margin-top: 0; margin-bottom: 0;\"><span style=\"color: #000000; font-weight: bold;\">Berilah tanda centang (√) pada setiap pernyataan yang benar!</span><br> </p>', 'a:5:{s:1:\"a\";s:51:\"<p style=\"margin-top: 0; margin-bottom: 0;\">(1)</p>\";s:1:\"b\";s:51:\"<p style=\"margin-top: 0; margin-bottom: 0;\">(2)</p>\";s:1:\"c\";s:51:\"<p style=\"margin-top: 0; margin-bottom: 0;\">(3)</p>\";s:1:\"d\";s:51:\"<p style=\"margin-top: 0; margin-bottom: 0;\">(4)</p>\";s:1:\"e\";s:51:\"<p style=\"margin-top: 0; margin-bottom: 0;\">(5)</p>\";}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;N;}', 1697191904, 1764228574, 1, '', 8, 0, 0, '71e5ca33-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
