INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21580, 605, 0, 2, 7, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0; margin-bottom: 0;\'>Berikut ini kebaikan dan kelemahan sistem ekonomi: </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(1) Adanya persaingan untuk maju menjadi lebih inovatif </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(2) Konsumen merasa puas karena barang berkualitas </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(3) Hak milik individu atas faktor-faktor usaha diakui</p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(4) Adanya pemisah antara yang kaya dan yang miskin </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(5) Kecenderungan terjadinya monopoli </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>Yang merupakan kebaikan sistem ekonomi pasar adalah ....</p> <p style=\'margin-top: 0; margin-bottom: 0;\'><span style=\'color: #000000; font-weight: bold;\'>Berilah tanda centang (√) pada setiap pernyataan yang benar!</span></p>', 'a:5:{s:1:\"a\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(1)</p>\";s:1:\"b\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(2)</p>\";s:1:\"c\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(3)</p>\";s:1:\"d\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(4)</p>\";s:1:\"e\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(5)</p>\";}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"c\";}', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5ce7c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21581, 605, 0, 2, 8, 'a:0:{}', NULL, NULL, '<p style=\'margin-top: 0; margin-bottom: 0;\'>Perhatikan kebaikan sistem ekonomi berikut ini: (</p> <p style=\'margin-top: 0; margin-bottom: 0;\'>1) Hubungan diantara individu sangat erat </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(2) Kebutuhan masyarakat terpenuhi secara merata </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(3) Pelayanan terhadap konsumen lebih meningkat </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(4) Hak individu atas alat-alat produksi diakui </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(5) Pemerintah mudah melakukan pengawasan </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(6) Kebebasan individu diakui </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(7) Jarang terjadi krisis ekonomi </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>(8) Negara bertanggungjawab penuh terhadap perekonomian </p> <p style=\'margin-top: 0; margin-bottom: 0;\'>Yang termasuk kebaikan sistem ekonomi terpusat adalah:</p> <p style=\'margin-top: 0; margin-bottom: 0;\'><span style=\'color: #000000; font-weight: bold;\'>Berilah tanda centang (√) pada setiap pernyataan yang benar!</span><br> </p>', 'a:8:{s:1:\"a\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(1)</p>\";s:1:\"b\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(2)</p>\";s:1:\"c\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(3)</p>\";s:1:\"d\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(4)</p>\";s:1:\"e\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(5)</p>\";s:1:\"f\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(6)</p>\";s:1:\"g\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(7)</p>\";s:1:\"h\";s:51:\"<p style=\'margin-top: 0; margin-bottom: 0;\'>(8)</p>\";}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"b\";i:1;s:1:\"e\";i:2;s:1:\"h\";}', 1697191904, 1697191904, 0, '', 8, 0, 0, '71e5cf9c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
