INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21587, 605, 0, 3, 4, 'a:0:{}', NULL, NULL, '<p style=\"margin-top: 0; margin-bottom: 0;\"><img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231203065033.jpg\" style=\"width: 597px;\"><span style=\"font-size: 0.875rem;\"><br></span></p><p style=\"margin-top: 0; margin-bottom: 0;\"><span style=\"font-size: 0.875rem;\">Ketika kamu mau membeli suatu barang, pasti ingin harga barang tersebut sesuai dengan budget yang Anda miliki atau lebih murah dari harga aslinya, kan?</span><br></p> <p style=\"margin-top: 0; margin-bottom: 0;\"><span style=\"font-family: \" times=\"\" new=\"\" roman\';\'=\"\">Nah, ketika harga barang tersebut tidak sesuai dengan keinginan Anda, Anda akan cenderung melakukan tawar menawar agar barang tersebut bisa lebih murah. Kalau penjualnya deal atau setuju dengan harga yang Anda inginkan, sisa uang untuk membeli barang tadi bisa digunakan untuk membeli kebutuhan yang lain dan Anda akan lebih hemat.</span></p> <p style=\"margin-top: 0; margin-bottom: 0;\"><span style=\"font-family: \" times=\"\" new=\"\" roman\';\'=\"\">Nah, tawar menawar merupakan suatu tindakan ekonomi yang dilakukan oleh penjual dan pembeli untuk menentukan suatu barang. Setiap orang harus memiliki pedoman atau arahan dalam melakukan tindakan ekonomi yang disebut dengan prinsip ekonomi.</span></p> <p style=\"margin-top: 0; margin-bottom: 0;\"><br> <span style=\"font-family: \" times=\"\" new=\"\" roman\';\'=\"\">Jadi, dengan adanya prinsip ekonomi ini, kita bisa memperhitungkan keuntungan dan kerugian saat melakukan tindakan ekonomi. Contohnya seperti kasus tawar menawar yang sudah dijelaskan di atas tadi.</span></p> <p style=\"margin-top: 0; margin-bottom: 0;\"><br> <span style=\"font-family: \" times=\"\" new=\"\" roman\';\'=\"\">Ciri-ciri prinsip ekonomi adalah sebagai berikut:</span></p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:5:\"Benar\";i:2;s:5:\"Salah\";}i:1;a:3:{i:0;s:71:\"<p>Mengutamakan kebutuhan yang sifatnya lebih penting dan mendesak</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:56:\"<p>Bersikap hemat dan tidak boros dalam tindakannya</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:66:\"<p>Melakukan tindakan ekonomi dengan pertimbangan yang matang</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:95:\"<p>Mempertimbangkan keuntungan dan kerugian dari setiap tindakan ekonomi yang dilakukannya</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:62:\"<p>Membeli barang sesuai dengan keinginan bukan kebutuhan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:76:\"<p>TIdak melakukan penawaran harga karena merasa kasihan kepada penjual</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1697191904, 1701561059, 1, '', 8, 0, 0, '71e5d667-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
