INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21595, 605, 0, 1, 22, NULL, NULL, NULL, '<div>Berikut adalah peran konsumen dan produsen</div><div>(1)<span style=\"white-space:pre\">	</span>Sebagai pemakai barang dan jasa untuk memenuhi kebutuhan</div><div>(2)<span style=\"white-space:pre\">	</span>Sebagai penghasil barang dan jasa untuk memenuhi kebutuhan konsumen</div><div>(3)<span style=\"white-space:pre\">	</span>Pihak yang dapat meningkatkan Produk Domestik Bruto</div><div>(4)<span style=\"white-space:pre\">	</span>Membantu peredaran barang dan jasa</div><div>(5)<span style=\"white-space:pre\">	</span>Mempengaruhi kebijakan pemerintah dalam rangka menghasilkan barang.</div><div><br></div><div> Yang termasuk peran produsen ditunjukkan nomor ....</div>', '<div>(1), (2), dan (3)</div>', '<div>(1), (2), dan (4)</div>', '<div>(1), (2), dan (5)</div>', '<div>(2), (3), dan (5)</div>', '(3), (4), dan (5)', NULL, NULL, NULL, NULL, NULL, 'd', 1697191904, 1697191904, 0, '', 1, 0, 0, '71e5def7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21596, 605, 0, 1, 23, NULL, NULL, NULL, '<div>Perhatikan ilustrasi berikut ini!</div><div><br></div><div>(1)<span style=\"white-space:pre\">	</span>Untuk menambah jumlah produksi bawang gorengnya pemilik Bagor Guwe menambah jumlah karyawan</div><div>(2)<span style=\"white-space:pre\">	</span>Untuk menambah jumlah produksi bawang gorengnya pemilik Bagor Guwe membeli alat pengiris bawang yang terbaru</div><div>(3)<span style=\"white-space:pre\">	</span>Untuk menambah jumlah produksinya bawang gorengnya pemilik Bagor Guwe menambah jumlah jam kerja pegawainya</div><div>(4)<span style=\"white-space:pre\">	</span>Untuk&nbsp; menambah jumlah produksi bawang&nbsp; gorengnya pemilik&nbsp; Bagor&nbsp; Guwe membagi tugas karyawannya sesuai dengan keahliannya</div><div>(5)<span style=\"white-space:pre\">	</span>Untuk menambah jumlah penjualan produksi bawang gorengnya pemilik Bagor Guwe mendaftarkan bawang gorengnya untuk mendapatkan ijin PIRT, Halal MUI, dan membuar Label yang menarik.</div><div><br></div><div>Dari kelima ilustrasi tersebut, yang merupakan kegiatan rasionalisasi adalah ....&nbsp;</div><div><br></div>', '<div>(1), (2), dan (3)</div>', '<div>(1), (3), dan (4)</div>', '<div>(2), (3), dan (5)</div>', '<div>(2), (4), dan (5)</div>', '(3), (4), dan (5)', NULL, NULL, NULL, NULL, NULL, 'e', 1697191904, 1697191904, 0, '', 1, 0, 0, '71e5dfd1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
