INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21785, 609, 0, 5, 2, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Apa yang dimaksud dengan gereja yang  kudus ?</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><span xss=\"removed\">Umat Allah yang&nbsp; seluruh&nbsp; kehidupannya selalu&nbsp; &nbsp;selaras dengan kehendak&nbsp; Tuhan yaitu&nbsp; : jujur, setia, taat, lemah lembut dan cinta kasih.</span><br></div></div>', 1697275694, 1700792502, 0, '', 1, 0, 0, '71e63535-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21786, 609, 0, 5, 3, NULL, NULL, NULL, '<p>Apa yang dimaksud dengan Gereja yang  apostolik!&nbsp;</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>Umat Allah yang mempunyai tugas atau misinya&nbsp; membawa kembali orang - orang yang telah berdosa kepada Tuhan unttuk&nbsp; mengikuti kehendakNya.<br></div></div>', 1697275745, 1700793168, 0, '', 1, 0, 0, '71e6362a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
