INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21791, 610, 0, 5, 1, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Manusia unik  atau selalu berbeda&nbsp; satu dengan yang lainnya  baik  jasmani maupun  rohani. Sebutkan perbedaan-perbedaan yang dimaksud!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>Perbedaan Jasmani : </p><ol><li>Bentuk  tubuh, wajah, tipe rambut</li><li> kesehatan</li><li>kemampuan</li><li>berpikir</li></ol><p>Perbedaan Rohani : </p><ol><li>kejujuran</li><li>ketaatan</li><li>kerajinan</li><li>kemalasan</li><li>kecerdasan </li></ol>', 1697276389, 1700708956, 1, '', 1, 0, 0, '71e63923-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
