INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21793, 610, 0, 5, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span lang=\"IN\" style=\"font-size: 0.875rem; line-height: 115%;\">Coba\r\nbandingkan dirimu dengan salah seorang dari teman di kelasmu,&nbsp; &nbsp;apakah\r\nada perbedaan? Jika ada sebutkan perbedaan-perbedaan itu!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span xss=removed>Sifat-sifat yang dimaksud seperti: kejujuran, kesetiaan, kerajinan, kemalasan, kecerdasan, kebodohan dan lain-lain</span><br>', 1697276682, 1697276752, 1, '', 1, 0, 0, '71e63b2e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21794, 610, 0, 5, 4, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Bagaimana sikapmu&nbsp; apabila&nbsp; memiliki kelebihan-kelebihan seperti: bisa bernyanyi,&nbsp; berbahasa Inggris,&nbsp; bermain bola volley dan  bola kaki?&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><span xss=\"removed\">Menggunakan kelebihan-kelebihan   yang dimiliki untuk membangun dan mengembangkan orang lain agar memiliki  kemampuan. </span><br></div>', 1697276753, 1700712501, 1, '', 1, 0, 0, '71e63c50-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21795, 610, 0, 5, 5, NULL, NULL, NULL, 'Laki-laki dan perempuan sama atau setara menurut pandangan Kitab suci atau dari sisi pandang Allah. Dalam hal apa saja kesetaraan   laki-laki dan perempuan dimaksud?&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Dalam hal kedudukan atau posisi dalam masyarakat dan hak dan kewajiban<br></div>', 1697276836, 1700712608, 1, '', 1, 0, 0, '71e63d0e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21796, 610, 0, 5, 6, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pada masayrakat lain, kedudukan laki-laki lebih tinggi dari perempuan. Berikan  salah satu contoh&nbsp; bahwa laki-laki lebih tinggi kedudukannya dari pada perempuan!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><span xss=\"removed\">Pada masyarakat tertentu laki-laki sangat dihargai dan dihormati dan mendapat kedudukan yang tinggi, sedangkan perempuan tidak. Misalnya dalam keluarga laki-laki yang mempunyai hak bicara dan mengambil keputusan sedangkan perempuan tidak. Atau laki-laki mempunyai  bagian hak waris yang  lebih banyak dari  perempuan.</span><br></div>', 1697276903, 1700712942, 1, '', 1, 0, 0, '71e63dc6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (21797, 610, 0, 5, 7, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Manusia sebagai ciptaan  Allah yang luhur dan mulia patut  dihargai, dihormati dan dijunjung tinggi harkat dan martabatnya. Namun  fakta menunjukkan lain, perempuan  sering  disepelekan, diabaikan&nbsp; atau dianggap remeh orang lain. Berikan sebuah contoh bahwa perempuan sering&nbsp; disepelekan atau tidak dihargai, direndahkan harkat dan martabatnya!&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><ol><li><span xss=\"removed\">Perempuan tidak mempunyai hak bicara dan mengambil  keputusan dalam keluarga</span></li><li><span xss=\"removed\">Perempuan tidak boleh menduduki posisi atau jabatan terpenting dalam pemerintahan.</span><br></li></ol></div>', 1697276969, 1700713356, 1, '', 1, 0, 0, '71e63eb1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:18', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
