INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22559, 628, 0, 1, 3, NULL, NULL, NULL, '<div class=\"mt-2\"><div class=\"mt-2\">Salah satu buah Roh ialah Kesabaran, yang artinya ....</div></div>', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">keadaan yang membuat kita rela berbagi dengan orang lain, menolong mereka yang butuh ditolong</span></div>', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">keadaan utuh karena ada pemulihan, har- moni dengan keadaan sekitar</span></div>', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">keadaan yang membuat kita senang, bahagia, diartikan sebagai kondisi yang dicari manusia</span></div>', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">Keadaan ketika kita dapat menanggung hinaan, ejekan, bah- kan tingkah laku merendahkan dan permusuhan dari orang lain</span></div>', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">Keadaan ketika kita ingin membuat orang lain juga merasakan keadaan yang baik</span></div>', NULL, NULL, NULL, NULL, NULL, 'd', 1699405112, 1700182398, 1, '', 1, 0, 0, '71e6d78a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:19', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
