INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22562, 628, 0, 1, 5, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem; text-align: justify;\">Mampu menjalin hubungan dengan Tuhan dan sesama, menggunakan standar nilai yang berlaku universal dan konsisten. Ia mengakui bahwa ia membutuhkan Tuhan, merasa dikasihi Tuhan, bahkan bergantung pada Tuhan dan mengasihi-Nya adalah pengertian dari dewasa secara ....</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Fisik</span></div>', '<div style=\"text-align: justify;\"><div><span style=\"font-size: 0.875rem; text-align: left;\">Intelektual</span></div></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Moral/spiritual</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Emosi</span></div>', 'Sosial', NULL, NULL, NULL, NULL, NULL, 'c', 1699405399, 1700182428, 1, '', 1, 0, 0, '71e6da48-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:19', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22566, 628, 0, 1, 6, NULL, NULL, NULL, '<div class=\"mt-2\"><div style=\"text-align: justify;\"><i style=\"font-size: 0.875rem;\">Sebab aku yakin, bahwa penderitaan zaman sekarang ini tidak dapat dibandingkan dengan kemuliaan yang akan dinyatakan kepada kita.”</i><span style=\"font-size: 0.875rem;\">&nbsp;adalah bunyi ayat yang terdapat dalam kitab ....</span></div></div>', '<div class=\"mt-2\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">2 Petrus 3:2-4</span></div></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Roma 8:18</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Mazmur 139:13- 14</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Ayub 3:11</span></div>', 'Roma 8:38-39', NULL, NULL, NULL, NULL, NULL, 'b', 1699405778, 1700185133, 1, '', 1, 0, 0, '71e6dbb7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:19', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22569, 628, 0, 1, 7, NULL, NULL, NULL, '<div class=\"mt-2\">Damai sejahtera adalah....</div>', '<div class=\"mt-2\">Merasakan kehadiran Tuhan dalam diri sendiri</div>', '<div class=\"mt-2\">Merasakan kasih Tuhan yang bersifat kekal sepanjang masa</div>', '<div class=\"mt-2\">Tidak dipengaruhi oleh apapun yang sedang di alami</div>', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">rendah hati, tidak menganggap diri sendiri penting, tetapi mendahului kepentingan orang lain</span></div>', '<p>Kemampuan menahan diri dari emosi negatif dan dorongan untuk memuaskan diri</p>', NULL, NULL, NULL, NULL, NULL, 'b', 1699405907, 1700185034, 1, '', 1, 0, 0, '71e6dd1e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:19', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22572, 628, 0, 1, 8, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem;\">Berikut ini dari Surat Galatia 5:22-23 adalah ....</span></div>', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">“Tetapi buah Roh ialah: kasih, sukacita, damai sejahtera, kesabaran, kemurahan, kebaikan, kesetiaan, kelemahlembutan, penguasaan diri. Tidak ada hukum yang menentang hal-hal itu.”</span></div>', '“Demikianlah tinggal ketiga hal ini, yaitu iman, pengharapan dan kasih, dan yang paling be- sar di antaranya ialah kasih.”', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">“Damai se-jahtera Kutinggalkan bagimu. Damai sejahtera-Ku Kuberikan kepadamu, dan apa yang Kuberikan tidak seperti yang diberikan oleh dunia kepadamu. Janganlah gelisah dan gentar hatimu.”</span></div>', '“Damai sejahtera Allah, yang melampaui segala akal, akan memelihara hati dan pikiranmu dalam Kristus Yesus”', '<div class=\"mt-2\"><span style=\"font-size: 0.875rem;\">“Janganlah kita jemu-jemu ber- buat baik, karena apabila sudah datang waktunya, kita akan menuai, jika kita tidak menjadi lemah. Karena itu, selama masih ada kesempatan bagi kita, marilah kita berbuat baik kepada semua orang, tetapi terutama kepada kawan-kawan kita seiman.”</span></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1699406122, 1700182480, 1, '', 1, 0, 0, '71e6ddf6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:19', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22574, 628, 0, 1, 9, NULL, NULL, NULL, '<div class=\"mt-2\">Keadaan yang membuat kita senang, bahagia adalah arti dari ...</div>', 'Kasih', 'Sukacita', 'Damai sejahtera', 'Kesabaran', 'Kemurahan', NULL, NULL, NULL, NULL, NULL, 'b', 1699406262, 1700182505, 1, '', 1, 0, 0, '71e6df68-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:19', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22576, 628, 0, 1, 10, NULL, NULL, NULL, '<div class=\"mt-2\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\"Anak yang bijak mendatangkan sukacita kepada ayahnya, tetapi anak yang bebal adalah kedukaan bagi ibunya” adalah pesan Alkitab kepada anak, yang terdapat di dalam kitab ....</span></div></div>', '<div class=\"mt-2\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Amsal 14:1</span></div></div>', '<div class=\"mt-2\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Amsal 13:1</span></div></div>', '<div class=\"mt-2\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Amsal 12:1</span></div></div>', '<div class=\"mt-2\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Amsal 11:1</span></div></div>', '<span style=\"text-align: justify;\">Amsal 10:1</span>', NULL, NULL, NULL, NULL, NULL, 'e', 1699406389, 1700182529, 1, '', 1, 0, 0, '71e6e025-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:19', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22593, 613, 0, 3, 6, NULL, NULL, NULL, '<p><img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231109092929.jpg\" style=\"width: 775px;\"><br></p><p>Membangun sebuah bisnis membutuhkan kecermatan terutama dalam hal strategi keuangan. Manajemen keuangan yang baik akan menunjang keberhasilan suatu bisnis dan begitu pula sebaliknya. Oleh karena itu, sangat penting bagi seseorang yang ingin menjalani karier sebagai business owner atau sebagai profesional di bidang keuangan untuk memahami bidang akuntansi.\r\n\r\nHal spesifik dalam bidang akuntansi yang khusus mengkaji tentang pencatatan dan laporan akuntansi secara mendalam disebut siklus akuntansi.</p><p>Siklus akuntansi ini dibuat dalam suatu periode tertentu untuk menghasilkan yang namanya informasi akuntansi. Proses ini tidak hanya dibutuhkan oleh perusahaan besar tetapi juga perusahaan kecil.</p><p><span style=\"font-size: 0.875rem;\">Nah, siklus akuntansi ini dilakukan secara berulang-ulang, mulai dari pencatatan bukti transaksi hingga penyajian laporan keuangan. Dengan adanya informasi akuntansi, perusahaan bisa mengatur pengeluaran dan pemasukan secara baik, transparan, dan rapi. Apabila suatu hari dibutuhkan, informasi akuntansi sudah siap disajikan.</span></p><p><span style=\"font-size: 0.875rem;\">Urutkanlah tahapan penyusunan siklus akuntansi yang benar dibawah ini!<br></span><br></p>\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:13:{i:0;a:13:{i:0;s:9:\"<p>#</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"2\";i:3;s:1:\"3\