INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22610, 493, 0, 1, 25, NULL, NULL, NULL, '<p>PT. Surya Kimia, sebuah perusahaan manufaktur bahan kimia berskala besar, tengah menghadapi tantangan signifikan untuk beradaptasi dengan regulasi lingkungan yang semakin ketat dan tuntutan pasar akan produk yang berkelanjutan. Untuk mempertahankan daya saing dan memenuhi komitmen terhadap Tujuan Pembangunan Berkelanjutan (SDGs), manajemen PT. Surya Kimia memutuskan untuk secara fundamental mereformasi proses produksinya melalui penerapan prinsip-prinsip Kimia Hijau. Salah satu pilar utama Kimia Hijau yang menjadi fokus adalah <b>penggunaan bahan baku terbarukan</b> sebagai upaya untuk mengurangi ketergantungan pada sumber daya tak terbarukan dan meminimalkan dampak lingkungan.</p><p>Dalam konteks strategi transformasi PT. Surya Kimia menuju produksi yang lebih berkelanjutan dan selaras dengan prinsip Kimia Hijau, langkah konkret manakah yang paling tepat mendefinisikan dan merefleksikan implementasi dari \'penggunaan bahan baku terbarukan\'?</p></body></html>', 'Menggunakan bahan baku yang tidak dapat diperbaharui', 'Menghentikan penelitian dalam pengembangan bahan bakar alternatif', 'Menggunakan bahan baku berbahaya', 'Menggunakan bahan baku yang dapat diperbaharui, seperti biomassa atau energi surya', 'Tidak memperhatikan bahan baku dalam proses produksi', NULL, NULL, NULL, NULL, NULL, 'd', 1699927571, 1766535984, 1, '', 1, 0, 0, '71e6f759-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:19', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
