INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (22835, 628, 0, 1, 18, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem;\">Berikut ini dari Surat Galatia 5:22-23 adalah ....</span></div><div><br></div>', '<div><span style=\"font-size: 0.875rem;\">“Tetapi buah Roh ialah: kasih, sukacita, damai sejahtera, kesabaran, kemurahan, kebaikan, kesetiaan, kelemahlembutan, penguasaan diri. Tidak ada hukum yang menentang hal-hal itu.”</span></div>', '“Demikianlah tinggal ketiga hal ini, yaitu iman, pengharapan dan kasih, dan yang paling be- sar di antaranya ialah kasih.”', '<div><span style=\"font-size: 0.875rem;\">“Damai se-jahtera Kutinggalkan bagimu. Damai sejahtera-Ku Kuberikan kepadamu, dan apa yang Kuberikan tidak seperti yang diberikan oleh dunia kepadamu. Janganlah gelisah dan gentar hatimu.”</span></div>', '<div><span style=\"font-size: 0.875rem;\">“Damai sejahtera Allah, yang melampaui segala akal, akan memelihara hati dan pikiranmu dalam Kristus Yesus”</span></div>', '“Janganlah kita jemu-jemu ber- buat baik, karena apabila sudah datang waktunya, kita akan menuai, jika kita tidak menjadi lemah. Karena itu, selama masih ada kesempatan bagi kita, marilah kita berbuat baik kepada semua orang, tetapi terutama kepada kawan-kawan kita seiman.”', NULL, NULL, NULL, NULL, NULL, 'a', 1700440033, 1700440161, 1, '', 1, 0, 0, '71e75e2c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
