INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23013, 599, 0, 5, 2, NULL, NULL, NULL, 'Pak RT mendapat sumbangan 8 karung beras. Tiap karung beras beratnya 50 kg. Beras dibagikan kepada 20 orang warga. Tiap warga memperoleh beras sebanyak ... Kg.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Jumlah karung beras = 8 karung</div><div>Berat tiap karung = 50 kg</div><div>Total warga = 20 orang</div><div>Beras yang diterima warga = total beras : jumlah warga</div><div>                                                     = 400/ 20</div><div>                                                     = 20 Kg</div>', 1700536610, 1700536806, 1, '', 1, 0, 0, '71e7baba-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23015, 599, 0, 5, 3, NULL, NULL, NULL, 'Untuk mengerjakan 1 unit rumah dibutuhkan waktu 36 hari dengan 12 tenaga kerja. Berapa waktu akan dihabiskan bila menggunakan 24 orang tenaga kerja ?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>36 hari = 12 tenaga kerja</div><div>x hari = 24 tenaga kerja</div><div>36 x 12 = 24 . x</div><div>x = 18</div><div>Berarti waktu yang dihabiskan bila menggunakan 24 pekerja adalah 18 hari</div>', 1700536847, 1700537135, 1, '', 1, 0, 0, '71e7bb7c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23020, 599, 0, 5, 4, NULL, NULL, NULL, 'Jarak rumah Andi dan rumah Feri yang berada di luar kota adalah 2500 km. Apabila Andi pergi ke rumah Feri dengan mobil berkecepatan 100 km/jam, berapa lama waktu perjalanan yang dibutuhkan Andi ?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Jarak rumah Andi ke rumah Feri = 2500 km</div><div>Kecepatan mobil = 100 km/jam</div><div>waktu = jarak : kecepatan</div><div>             = 2500/100</div><div>             = 25 jam</div><div>25 jam x 60 menit = 1500 menit.</div>', 1700537278, 1700537486, 1, '', 1, 0, 0, '71e7bd26-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
