INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23633, 610, 0, 5, 10, NULL, NULL, NULL, 'Demikian sebuah petikan koran Pos Kupang&nbsp; senin 15 November 2023. Terjadi kecolongan di PT Semen Kupang&nbsp; tidak dibayar upah buruh&nbsp; 5 karyawan selama 3 bulan sebesar Rp.25 juta rupiah. hal ini membuat para karyawaan resah dan tidak bersemangat bekerja. Kasus ini sempat diajukan ke Depnaker kota Kupang untuk ditindaklanjuti. Setelah diproses ternyata&nbsp; beberapa oknum di PT. semen terlibat&nbsp; &nbsp;penggelapan upah buruh karyawan demi keuntungan pribadinya. Menyimak berita koran ini bagaimana sikapmu terhadap kasus tersebut?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'kasus tersebut merupakan penyimpangan yang merugikan 5 karyawan PT.Semen Kupang&nbsp;yang telah menyumbangkan tenaga dan waktunya untuk perusahaan. Ditinjau dari&nbsp; aspek rohani&nbsp; bertentangan dengan&nbsp; kehendak Tuhan karena penipuan.', 1700714364, 1700716342, 1, '', 1, 0, 0, '71e8272b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
