INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23951, 657, 0, 1, 9, NULL, NULL, NULL, 'Pemilihan Presiden akan diselenggarakan beberapa minggu lagi. Pak A ingin memperoleh dukungan yang banyak dari kalangan masyarakat menengah ke bawah. Oleh sebab itu, ia membagi-bagikan uang kepada masyarakat tersebut agar bersedia untuk mendukungnya ketika pemilu. Suatu hari, Anda sebagai warga memergoki aksi tersebut. Apa yang akan Anda lakukan?', 'Melapor ke pihak yang berwenang', 'Membiarkan hal itu terjadi', 'Ikut serta mengambil uang tersebut', 'Mengajak teman-teman Anda untuk ikut mengambil uangnya', 'Netral dan tak melakukan apa-apa', NULL, NULL, NULL, NULL, NULL, 'a', 1700897738, 1700897830, 1, '', 1, 0, 0, '71e8da77-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
