INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23995, 670, 0, 1, 2, NULL, NULL, NULL, 'Pak Yunus memiliki suatu kawasan perindustrian yang letaknya ditengah-tengah perkampungan. Limbah-limbah industri yang berasal dari Pak yunus ternyata mengganggu kebersihan dilingkungan sekitar. Warga pun marah kepada Pak yunus. Apa tindakan yang seharusnya Pak yunus&nbsp;lakukan?', 'Menimbun limbah sampai semua warga semakin marah', 'Membuang limbah langsung ke rumahnya', 'Memindahkan limbah ke tempat yang jauh dari perkampungan', 'Berdiskusi dengan warga tentang solusi yang perlu dilakukan', 'Memaksa warga diam dan membiarkan Pak yunus&nbsp;bebas', NULL, NULL, NULL, NULL, NULL, 'd', 1700901970, 1700901970, 1, '', 1, 0, 0, '71e8f2ae-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23996, 670, 0, 1, 3, NULL, NULL, NULL, 'Putri berasal dari Jawa, bersekolah di Jakarta. Sementara Rani merupakan orang Jakarta asli yang memang tinggal di ibu kota. Ketika pelajaran budaya Jakarta, Rani terlalu membanggakan diri bahkan cenderung merendahkan budaya Jawa. Apa yang mesti dilakukan Putri?', 'Mengingatkan bahwa budaya Jawa lebih baik', 'Mengingatkan bahwa budaya Jakarta tidak lebih baik dari daerah asalnya', 'Mengingatkan bahwa setiap budaya daerah memiliki kekhasan masing-masing', 'Memarahi Rani dan menjelekkan asal daerahnya', 'Menerima di rendahkan oleh Rani', NULL, NULL, NULL, NULL, NULL, 'c', 1700901970, 1700901970, 1, '', 1, 0, 0, '71e8f421-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23997, 670, 0, 1, 4, NULL, NULL, NULL, 'Pak Yosua terkenal baik sebagai seorang guru. Hal ini membuat semua muridnya menanti kehadiran beliau. Namun suatu ketika ada kabar bahwa Pak Yosua mesti pindah tugas ke daerah lain. Hal ini menyebabkan murid-murid Pak Yosua sedih. Apa yang mesti dilakukan Pak Yosua?', 'Menasihati murid lamanya dan bertangung jawab memenuhi tugas di sekolah barunya', 'Menolak dipindah tugaskan', 'Pergi langsung tanpa berpamitan kepada murid-muridnya', 'Membiarkan perintah tugas tersebut dan memutuskan berhenti', 'Semua jawaban di atas salah', NULL, NULL, NULL, NULL, NULL, 'a', 1700901970, 1700901970, 1, '', 1, 0, 0, '71e8f512-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23998, 670, 0, 1, 5, NULL, NULL, NULL, 'Pak Dedi punya sebidang tanah yang dekat dengan perkampungan penduduk, pak Dedi memanfaatkan tanahnya dengan memelihara ayam potong. Namun bau kotoran dari kandang pak Dedi mengganggu warga di kampung tersebut. Warga melakukan protes karena pencemaran udara. Tindakan yang harus dilakukan oleh Pak Dedi adalah ...', 'Bermusyawarah dengan warga kampung untuk menyelesaikan permasalahan', 'Menimbun kotoran ayamnya setiap hari', 'Memindahkan kandang ayamnya ke kandang kolektif', 'Memberi biaya ganti rugi setiap bulan terhadap warga yang terdampak', 'Menempuh jalur hukum karena dia merasa bebas melakukan apapun di atas tanahnya', NULL, NULL, NULL, NULL, NULL, 'a', 1700901970, 1700901970, 1, '', 1, 0, 0, '71e8f5ff-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (23999, 670, 0, 1, 6, NULL, NULL, NULL, 'Adam adalah warga Desa Sukamaju, pada saat pemilihan kepala desa, Adam melakukan serangan fajar dalam bentuk membagi-bagikan uang dan sembako agar warga menjatuhkan pilihan terhadap dirinya sebagai kepala desa. Ternyata setelah diadakan penghitungan suara, Adam memeroleh suara mayoritas. Kamu mengetahui bahwa Adam berbuat tidak jujur dalam meraih kemenangan. Bagaimana sebaiknya tindakan kamu untuk melawan ketidakadilan tersebut?', 'Acuh tak acuh karena kamu tidak dirugikan karena bukan kontestan', 'Melapor kepada aparat penegak hukum dan pengawas pemilihan dengan bukti yang kuat', 'Diam saja karena warga kampungmu semua kebagaian uang takutnya kamu jadi sasaran kemarahan warga', 'Memberi tahu kontestan lain yang dirugikan', ' Mendatangi Pincen kalau aksinya ada yang mengetahuinya dan meminta uang diam kalau mau selamat', NULL, NULL, NULL, NULL, NULL, 'b', 1700901970, 1700901970, 1, '', 1, 0, 0, '71e8f7aa-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
