INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24235, 674, 0, 1, 2, NULL, NULL, NULL, 'Kebijakan moneter dapat	memperbaiki	neraca	perdagangan	dan	neraca pembayaran dengan cara....\r\n', 'menyediakan valuta asing untuk kepentingan ekspor impor', '<div>menahan valuta asing untuk cadangan agar harga valuta asing stabil</div>', '<div>mengadakan devaluasi sehingga harga barang ekspor memiliki daya saing tinggi sehingga ekspor meningkat dan dapat memperbaiki neraca perdagangan dan neraca pembayaran</div>', '<div>menyediakan&nbsp; jumlah&nbsp; valuta&nbsp; asing&nbsp; di&nbsp; bank&nbsp; devisa&nbsp; sehingga&nbsp; fluktuasi&nbsp; harga valuta asing stabil</div>', 'menyediakan/mengadakan tabungan valuta asing di bank asing', NULL, NULL, NULL, NULL, NULL, 'd', 1701561860, 1701561860, 0, '', 1, 0, 0, '71e9b56a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24236, 674, 0, 1, 3, NULL, NULL, NULL, '<p>Tabel APBN selama 2 tahun sebagai berikut:</p><p><img src=\"http://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220329011426.jpg\" style=\"width: 547px;\"><br></p><p>Berdasarkan data tersebut, pernyataan berikut ini yang benar adalah …\r\n</p>', '<div>pemerintah menerapkan surplus anggaran dengan jumlah pendapatan lebih besar dari belanja</div>', '<div><span style=\"font-size: 1rem;\">pendapatan&nbsp; negara&nbsp; mengalami&nbsp; penurunan&nbsp; baik&nbsp; penerimaan&nbsp; dalam&nbsp; negeri maupun hibah</span><br></div>', '<div>anggaran&nbsp; negara&nbsp; dalam&nbsp; 2&nbsp; tahun&nbsp; mengalami&nbsp; surplus&nbsp; anggaran&nbsp; disebabkan pendapatan lebih besar dari penegeluaran</div>', '<div>pada&nbsp; &nbsp;tahun&nbsp; &nbsp;2018&nbsp; &nbsp;pemerintah&nbsp; &nbsp;menetapkan&nbsp; &nbsp;kebijakan&nbsp; &nbsp;anggaran&nbsp; &nbsp;surplus, sedangakan pada tahun 2019 anggaran defisit</div>', '<div>belanja negara mengalami peningkatan baik belanja pemerintah pusat maupun untuk transfer ker daerah</div>', NULL, NULL, NULL, NULL, NULL, 'e', 1701561860, 1701561860, 0, '', 1, 0, 0, '71e9b64d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24237, 674, 0, 1, 4, NULL, NULL, NULL, '<div>Menjual&nbsp; surat&nbsp; berharga&nbsp; seperti&nbsp; Surat Berharga Bank Indonesia (SBI)&nbsp; dapat&nbsp; mengurangi&nbsp; jumlah&nbsp; uang&nbsp; beredar, karena....</div><div><br></div>', '<div>harga surat berharga menjadi mahal</div>', '<div>dengan menjual surat berharga uang yang beredar kembali masuk ke dalam sistem perbankan</div>', '<div>menaikkan&nbsp; suku&nbsp; bunga&nbsp; surat&nbsp; berharga&nbsp; dapat&nbsp; memengaruhi&nbsp; jumlah&nbsp; uang beredar</div>', '<div>menurunkan&nbsp; suku&nbsp; bunga&nbsp; surat&nbsp; berharga&nbsp; pikiran&nbsp; orang&nbsp; akan&nbsp; berpengaruh melakukan investasi</div>', 'membeli surat berharga oleh bank sentral akan menambah uang beredar', NULL, NULL, NULL, NULL, NULL, 'b', 1701561860, 1701561860, 0, '', 1, 0, 0, '71e9b848-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24238, 674, 0, 1, 5, NULL, NULL, NULL, '<p>Perhatikan kurva berikut ini</p><p><img src=\"http://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220329010551.png\" style=\"width: 413px;\"></p><p>Berdasarkan kurva di atas telah terjadi inflasi yang disebabkan oleh meningkatnya permintaan agregat, peranan bank sentral (kebijakan moneter) dalam mengatasi kondisi tersebut adalah….</p>', '<div>menaikan pajak atas barang yang diminati sehingga masyarakat menurunkan permintaan atas barang tersebut</div>', '<div>membeli kembali surat-surat berharga yang telah dijual kepada masyarakat sehingga menambah uang beredar dimasyarakat</div>', '<div>menaikan&nbsp; &nbsp;tingkat&nbsp; &nbsp;suku&nbsp; &nbsp;bunga&nbsp; &nbsp;sehingga&nbsp; &nbsp;minat&nbsp; &nbsp;menabung&nbsp; &nbsp;masyarakat meningkat</div>', '<div>mengurangi belanja negara dengan cara mengurangi pembelian barang dan jasa bagi operasional pemerintah sehingga menekan peningkatan harga barang</div>', 'melonggarkan&nbsp; peraturan&nbsp; persyaratan&nbsp; kredit&nbsp; untuk&nbsp; memperoleh&nbsp; pinjaman dari bank sehingga meningkatkan daya beli masyarakat', NULL, NULL, NULL, NULL, NULL, 'c', 1701561860, 1701561860, 0, '', 1, 0, 0, '71e9b93c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24239, 674, 0, 2, 1, NULL, NULL, NULL, '<div>Perhatikan kebijakan moneter berikut:</div><div>1.<span style=\"white-space:pre\">	</span>menaikkan suku bunga bank</div><div>2.<span style=\"white-space:pre\">	</span>menaikkan cadangan kas di bank</div><div>3.<span style=\"white-space:pre\">	</span>membeli Sertifikat Bank Indonesia (SBI)</div><div>4.<span style=\"white-space:pre\">	</span>melonggarkan pemberian kredit</div><div>5.<span style=\"white-space:pre\">	</span>menurunkan tingkat suku bunga bank</div><div><br></div><div>Kebijakan yang termasuk dalam <i>easy money policy</i> adalah . . . .</div>', 'a:5:{s:1:\"a\";s:8:\"<p>1</p>\";s:1:\"b\";s:8:\"<p>2</p>\";s:1:\"c\";s:8:\"<p>3</p>\";s:1:\"d\";s:8:\"<p>4</p>\";s:1:\"e\";s:8:\"<p>5</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"c\";i:1;s:1:\"d\";i:2;s:1:\"e\";i:3;N;}', 1701561860, 1701561860, 1, '', 1, 0, 0, '71e9ba6c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24240, 674, 0, 2, 2, NULL, NULL, NULL, '<div>Berikut ini adalah kebijakan fiskal dan kebijakan moneter.</div><div>1.<span style=\"white-space:pre\">	</span>menaikkan tarif pemungutan pajak</div><div>2.<span style=\"white-space:pre\">	</span>menjual surat-surat berharga seperti SBI</div><div>3.<span style=\"white-space:pre\">	</span>menurunkan tarif pemungutan pajak</div><div>4.<span style=\"white-space:pre\">	</span>menaikkan cadangan kas</div><div>&nbsp;<span style=\"font-size: 1rem;\">5.</span><span style=\"font-size: 1rem; white-space: pre;\">	</span><span style=\"font-size: 1rem;\">memperketat pengeluaran konsumsi pemerintah.</span></div><div><span style=\"font-size: 1rem;\"><br></span></div><div><span style=\"font-size: 1rem;\">Yang merupakan kebijakan fiskal adalah . . . .</span></div><div><br></div>', 'a:5:{s:1:\"a\";s:8:\"<p>1</p>\";s:1:\"b\";s:8:\"<p>2</p>\";s:1:\"c\";s:8:\"<p>3</p>\";s:1:\"d\";s:8:\"<p>4</p>\";s:1:\"e\";s:8:\"<p>5</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"e\";i:3;N;}', 1701561860, 1701561860, 1, '', 1, 0, 0, '71e9bb70-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24241, 674, 0, 2, 3, NULL, NULL, NULL, '<div>Perhatikan beberapa pernyataan tentang indeks harga di bawah ini:</div><div>(1)<span style=\"white-space:pre\">	</span>Angka indeks harga dapat dijadikan standar/pedoman untuk melakukan perbandingan harga dari waktu ke waktu.</div><div>(2)<span style=\"white-space:pre\">	</span>Angka indek harga menunjukkan perubahan-perubahan yang terjadi atas harga pada pasar-pasar primer.</div><div>(3)<span style=\"white-space:pre\">	</span>Indek harga merupakan petunjuk/indikator yang dapat digunakan untuk mengukur pertumbuhan ekonomi secara umum.</div><div>(4)<span style=\"white-space:pre\">	</span>Indek harga pedagang besar dapat memberikan gambaran/trend dalam perdagangan di tingkat eceran.</div><div>(5)<span style=\"white-space:pre\">	</span>Indeks harga konsumen adalah ukuran statistik yang dapat menunjukkan perubahan- perubahan yang terjadi pada harga eceran barang dan jasa yang diminta oleh konsumen dari waktu ke waktu.</div><div><br></div><div>Pernyataan di atas yang yang benar adalah ....&nbsp;</div>', 'a:5:{s:1:\"a\";s:8:\"<p>1</p>\";s:1:\"b\";s:8:\"<p>2</p>\";s:1:\"c\";s:8:\"<p>3</p>\";s:1:\"d\";s:8:\"<p>4</p>\";s:1:\"e\";s:8:\"<p>5</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;s:1:\"e\";i:4;N;}', 1701561860, 1701561860, 1, '', 1, 0, 0, '71e9bd23-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
