INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24309, 674, 0, 5, 6, NULL, NULL, NULL, '<div>Badan Pusat Statistik (BPS) melaporkan, pendapatan penduduk Indonesia yang diukur menurut produk domestik bruto (PDB) per kapita tumbuh 8,5% menjadi Rp 62,2 juta (US$ 4,35 ribu) per tahun pada 2021 dibanding posisi 2020 sebesar 57,3 juta per tahun. Pertumbuhan pendapatan tersebut seiring dengan tumbuhnya perekonomian domestik sebesar 3,69% pada tahun lalu.</div><div><br></div><div>Pendapatan penduduk Indonesia berhasil melampaui capaian sebelum terjadi pandemi Covid-19, yakni pada 2019 yang hanya sebesar Rp 59,1 juta per tahun. Artinya, PDB per kapita nasional mencatat rekor tertinggi pada tahun lalu seperti terlihat pada grafik.</div><div><br></div><div>Ekonomi Indonesia menurut besaran PDB atas dasar harga konstan (ADHK) 2010 berhasil tumbuh 3,69% sepanjang 2021 dibanding tahun sebelumnya yang mengalami kontraksi sebesar 2,07%.</div><div><br></div><div>Dari sisi lapangan usaha, yang menopang pertumbuhan perekonomian domestik tahun lalu, antara lain industri pengolahan yang berkontribusi sebesar 19,25% dari PDB mampu mencatatkan pertumbuhan 3,39%. Diikuti sektor pertanian dengan kontribusi 13,28% berhasil tumbuh 1,84%, serta sektor perdagangan besar dan eceran dengan kontribusi 12,97% tumbuh 4,65%.</div><div><br></div><div>Sementara dari sisi pengeluaran, komponen pengeluaran konsumsi rumah tangga yang berkontribusi 54,42% dari PDB berhasil tumbuh 2,02% pada 2021. Setelahnya ada komponen pembentukan modal tetap bruto (PMTB) yang berkontribusi sebesar 30,81% terhadap PDB mampu tumbuh 3,8%.</div><div><br></div><div><br></div><div><img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231109132847.png\" style=\"width: 761.5px;\"></div><div><br></div><div>Tahun 2015-2019 Pendapatan perkapita Indonesia mengalami peningkatan, akan tetapi pada tahun 2020 mengalami penurunan. Jelaskan mengapa pendapatan perkapita Indonesia pada tahun 2020 mengalami penurunan!<br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>-</div>', 1701561860, 1701561860, 1, '', 1, 0, 0, '71ea1b03-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24310, 674, 0, 5, 7, NULL, NULL, NULL, '<div>Diketahui data perhitungan pendapatan nasional (dalam miliar rupiah) berikut ini:</div><div>➢ Gross national product :1000</div><div>➢ Transfer luar negeri : 250</div><div>➢ Depresiasi : 150</div><div>➢ Pajak tidak langsung : 100</div><div>➢ Laba ditahan : 50</div><div>➢ Pajak perseroan : 25</div><div>➢ Pajak langsung : 50</div><div><br></div><div>Berdasarkan data tersebut, tentukan besarnya Net National Income (NNI)!</div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>GNP = 1.000</div><div>NNP = GNP – depresiasi</div><div>= 1.000 – 150</div><div>= 850</div><div>NNI = NNP – Pajak tidak langsung</div><div>= 850 – 100</div><div>= 750 miliar</div>', 1701561860, 1701561860, 1, '', 1, 0, 0, '71ea1d94-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24311, 674, 0, 5, 8, NULL, NULL, NULL, '<div>Diketahui data suatu negara adalah sebagai berikut (dalam triliun)</div><div>➢ Produk domestik bruto 1700</div><div>➢ Penyusutan 110</div><div>➢ Pajak langsung 330</div><div>➢ Pajak tidak langsung 120</div><div>➢ Pendapatan masyarakat diluar negeri 70</div><div>➢ Pendapatan warga asing di negara tersebut 150</div><div>➢ Pembayaran transfer 170</div><div>➢ Iuran asuransi dan iuran sosial 90</div><div><br></div><div>Berdasarkan data diatas, tentukan besarnya Disposible Income!</div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>GNP = GDP + pendapatan masyarakat di LN – Pendapatan warga asing</div><div>GNP = 1.700 + 70 – 150</div><div>= 1.620</div><div>NNP = GNP – Penyusutan</div><div>= 1.620 – 110</div><div>= 1.510</div><div>NNI = NNP – Pajak tidak</div><div>langsung</div><div>= 1.510 – 120</div><div>= 1.390</div><div>PI = NNI + Transfer Payment –</div><div>Iuran asuransi dan social</div><div>= 1.390 + 170 – 90</div><div>= 1.470</div><div>DI = PI – Pajak Langsung</div><div>= 1.470 – 330</div><div>= 1.140 triliun</div></div>', 1701561860, 1701561860, 1, '', 1, 0, 0, '71ea1f6e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24312, 674, 0, 5, 9, NULL, NULL, NULL, '<div>Dalam suatu perekonomian diketahui memiliki data sebagai berikut (dalam miliar):</div><div>➢ GNP Rp2.000,00</div><div>➢ Transfer payment Rp25,00</div><div>➢ Penyusutan Rp200,00</div><div>➢ Pajak langsung Rp150,00</div><div>➢ Pajak tidak langsung Rp150,00</div><div>➢ Laba ditahan Rp75,00</div><div><br></div><div>Dari data tersebut, hitunglah besarnya personal incomenya!</div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>NNP = GNP – Penyusutan</div><div>= Rp2.000,00 – Rp200,00</div><div>= Rp1.800,00</div><div>NNI = NNP – Pajak tidak</div><div>langsung</div><div>= Rp1.800,00 – Rp150,00</div><div>= Rp1.650,00</div><div><div>PI = NNI + Transfer Payment –</div><div>Laba ditahan</div><div>= Rp1.650,00 + Rp25,00 –</div><div>Rp75,00</div><div>= Rp1.600,00 miliar</div></div></div>', 1701561860, 1701561860, 1, '', 1, 0, 0, '71ea2149-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24313, 674, 0, 5, 10, NULL, NULL, NULL, '<div>Perhatikan data berikut ini (dalam miliar rupiah) !</div><div>➢ GDP Rp8.000</div><div>➢ GNP Rp7.500</div><div>➢ Pajak langsung Rp500</div><div>➢ Pajak tidak langsung Rp1.000</div><div>➢ Transfer payment Rp500</div><div>➢ Penyusutan Rp500</div><div>➢ Laba ditahan Rp200</div><div><br></div><div>Berdasarkan data di atas, tentukan besarnya PI (Personal Income)!</div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>NNP = GNP – Penyusutan</div><div>= Rp8.000,00 – Rp500,00</div><div>= Rp7.500,00</div><div>NNI = NNP – Pajak tidak</div><div>langsung</div><div>= Rp7.500,00 – Rp1.000,00</div><div>= Rp6.500,00</div><div>PI = NNI + Transfer Payment –</div><div>Laba ditahan</div><div>= Rp6.500,00 + Rp500,00 –</div><div>Rp200,00</div><div>= Rp6.800,00 miliar</div></div>', 1701561860, 1701561860, 1, '', 1, 0, 0, '71ea22a9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
