INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24324, 613, 0, 2, 19, NULL, NULL, NULL, '<p>Berikut ini merupakan akun-akun yang terdapat di laporan laba\r\nrugi suatu perusahaan.</p><p><br></p><p></p><div><span style=\"font-size: 0.875rem;\">Pilihlah tiga (3) jawaban yang tepat dengan cara memberikan tanda centang (✓)!&nbsp;</span><br></div><p></p>', 'a:5:{s:1:\"a\";s:22:\"<p>pendapatan sewa</p>\";s:1:\"b\";s:37:\"<p>beban yang masih harus dibayar</p>\";s:1:\"c\";s:17:\"<p>beban gaji</p>\";s:1:\"d\";s:24:\"<p>beban operasional</p>\";s:1:\"e\";s:29:\"<p>piutang pendapatan<br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"e\";i:3;N;}', 1701573328, 1701573559, 1, '', 1, 0, 0, '71ea2d39-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24325, 613, 0, 2, 20, NULL, NULL, NULL, '<p>Berikut ini informasi tepat berkaitan dengan laporan keuangan.</p><p><br></p><p><span style=\"font-size: 0.875rem;\">Pilihlah tiga (3) jawaban yang tepat dengan cara memberikan tanda centang (✓)!&nbsp;</span><br></p>', 'a:5:{s:1:\"a\";s:223:\"<p>ketika nilai pendapatan lebih besar dibandingkan dengan <span style=\"font-size: 0.875rem;\">nilai beban, maka perusahaan mengalami laba akan </span><span style=\"font-size: 0.875rem;\">menambah modal perusahaan</span></p>\";s:1:\"b\";s:138:\"<p>tujuan dari penyusunan laporan neraca adalah untuk <span style=\"font-size: 0.875rem;\">menyeimbangkan antara utang dan modal</span></p>\";s:1:\"c\";s:129:\"<p>akun prive termasuk dalam komponen modal di laporan <span style=\"font-size: 0.875rem;\">neraca atau posisi keuangan</span></p>\";s:1:\"d\";s:326:\"<p>dalam pembuatan laporan keuangan, harus disusun secara <span style=\"font-size: 0.875rem;\">berurutan mulai dari laporan laba rugi, laporan perubahan </span><span style=\"font-size: 0.875rem;\">modal dan yang terakhir adalah penyusunan laporan neraca </span><span style=\"font-size: 0.875rem;\">atau posisi keuangan</span></p>\";s:1:\"e\";s:261:\"<p>apabila dalam laporan neraca atau posisi keuangan kondisi <span style=\"font-size: 0.875rem;\">aktiva dan pasiva belum menunjukkan keseimbangan, maka  </span><span style=\"font-size: 0.875rem;\">dapat dipastikan laporan keuangan tersebut keliru</span><br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"d\";i:2;s:1:\"e\";i:3;N;}', 1701573386, 1701573555, 1, '', 1, 0, 0, '71ea2e03-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24326, 675, 0, 1, 1, NULL, NULL, NULL, 'Berikut ini adalah rumusan matematis keseimbangan akuntansi dimana pada tahap awal pendirian suatu perusahaan baru tersedia informasi mengenai sejumlah uang atau barang yang disetorkan oleh pemilik dan belum melibatkan modal dari luar&nbsp;', 'Neraca = Rugi/Laba&nbsp;', 'Aktiva = Pasiva&nbsp;', 'Pasiva = Aktiva – Modal Pemilik', 'Aktiva = Modal Pemilik – Utang', 'Aktiva = Utang + Modal Pemilik', NULL, NULL, NULL, NULL, NULL, 'b', 1701573931, 1701573931, 1, '', 1, 0, 0, '71ea2fcb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24327, 675, 0, 1, 2, NULL, NULL, NULL, 'Toko batik NIKEN tanggal 1 Maret 2020 membayar utang kepada bank atas pinjaman bulan yang lalu sebesar Rp20.000.000,00, dan bunganya Rp. 500.000,00.&nbsp; Pengaruh transaksi ini dalam persamaan akuntansi adalah….', 'Kas	(-)	Rp20.000.000,00,	Utang	(-)	Rp20.000.000,00,	Modal	(+) Rp500.000,00', 'Kas	(-)	Rp20.500.000,00,	Utang	(-)	Rp20.500.000,00,	Modal	(+) Rp500.000,00', 'Kas (-) Rp20.000.000,00, Utang (-) Rp20.500.000,00, Modal (-) Rp500.000,00', 'Kas (-) Rp20.500.000,00, Utang (-) Rp20.000.000,00, Modal (-) Rp500.000,00 ', 'Kas (-) Rp20.500.000,00, Modal (-) Rp20.500.000,00, Utang (-) Rp500.000,00', NULL, NULL, NULL, NULL, NULL, 'd', 1701573931, 1701573931, 1, '', 1, 0, 0, '71ea310c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24328, 675, 0, 1, 3, NULL, NULL, NULL, '<p><b>Stimulus Kasus:</b></p><p>Ibu Rina adalah seorang pengusaha sukses yang memiliki dan mengelola \"Griya Cantik Pesona,\" sebuah salon kecantikan yang sedang berkembang pesat. Sebagai pemilik, Ibu Rina selalu berusaha menjaga akuntabilitas keuangan usahanya. Pada awal tahun, tepatnya tanggal 5 Januari 2020, untuk memastikan kelancaran operasional dan kualitas layanan prima bagi pelanggannya, Ibu Rina melakukan pembelian sejumlah perlengkapan salon vital (seperti gunting, sisir berkualitas tinggi, mangkuk pewarna, dan persediaan produk sekali pakai) senilai Rp750.000,00. Pembayaran atas pembelian ini dilakukan secara tunai langsung dari kas operasional perusahaan.</p><p><b>Soal:</b></p><p>Berdasarkan skenario di atas, apabila Ibu Rina hendak mencatat transaksi pembelian perlengkapan tersebut ke dalam persamaan dasar akuntansi, analisis dampak paling akurat terhadap komponen-komponen persamaan akuntansi adalah sebagai berikut:</p></body></html>', 'harta  bertambah  berupa  perlengkapan,  utang  bertambah  berupa  Utang usaha', 'harta bertambah berupa perlengkapan, modal bertambah berupa Kas', '<div>harta bertambah berupa perlengkapan, harta berkurang berupa Kas</div></body></html>', 'harta bertambah berupa kas, harta berkurang berupa perlengkapan', 'harta berkurang berupa kas, modal berkurang berupa uang', NULL, NULL, NULL, NULL, NULL, 'c', 1701573931, 1766375085, 1, '', 1, 0, 0, '71ea322b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24329, 675, 0, 1, 4, NULL, NULL, NULL, '<p>Bayu, seorang lulusan baru dari jurusan Ekonomi, memiliki visi untuk mengoptimalkan rantai pasok logistik di Nusa Tenggara Timur. Setelah melakukan studi kelayakan yang komprehensif, ia memutuskan untuk mendirikan PT Ekspres Kupang, sebuah perusahaan rintisan yang fokus pada layanan pengiriman barang dan logistik di Kupang. Sebagai modal awal, Bayu menyuntikkan dana pribadi sebesar Rp105.200.000,00 ke dalam perusahaan.</p><p>Seiring dengan perencanaan operasional, Bayu menyadari adanya kekurangan dana untuk pengadaan armada awal dan sistem manajemen. Untuk mengatasi hal ini, PT Ekspres Kupang berhasil memperoleh fasilitas pinjaman modal kerja dari Bank Mandiri Cabang Kupang sebesar Rp25.000.000,00 yang akan digunakan sepenuhnya untuk kegiatan operasional awal.</p><p>Berdasarkan skenario pendirian PT Ekspres Kupang di atas, sebagai seorang penilai keuangan, berapakah total <b>sumber daya ekonomis (aset)</b> yang secara efektif dikendalikan oleh PT Ekspres Kupang pada awal operasionalnya?</p></body></html>', '<div>Rp105.175.000,00</div></body></html>', 'Rp125.500.000,00', 'Rp130.200.000,00', 'Rp105.250.000,00', 'Rp105.225.000,00', NULL, NULL, NULL, NULL, NULL, 'c', 1701573931, 1766375144, 0, '', 1, 0, 0, '71ea3503-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24330, 675, 0, 1, 5, NULL, NULL, NULL, 'Perusahaan membeli kendaraan sebesar Rp. 120.000.000,00, baru dibayar 50% sisanya dibayar kemudian. Pengaruh transaksi tersebut terhadap persamaan akuntansi adalah.....', 'Kas (-) Rp120.000000,00, kendaraan (+) Rp120.000.000,000', 'Kas (-) Rp120.000.000,00, utang (+) Rp120.000.000,00', 'Kas (-) Rp50.000.000,00, kendaraan   (-) Rp120.000.000,00, dan utang (-) Rp70.000.000,00', '<div>Kas (+) Rp60.000.000,00, kendaraan (+) Rp120.000.000,00, dan utang (+) Rp60.000.000,00</div>', 'Kas (-) Rp. 60.000000,00, kendaraan (+) Rp. 120.000.000,00, dan utang (+) Rp. 60.000.000,00', NULL, NULL, NULL, NULL, NULL, 'e', 1701573931, 1701573931, 1, '', 1, 0, 0, '71ea36a0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24331, 675, 0, 2, 1, NULL, NULL, NULL, '<p>Dibawah ini adalah akun-akun yang terdapat pada laporan keuangan perusahaan jasa.</p><p><i>Yang termasuk dalam akun aset (harta) lancar adalah...</i></p><p>Kamu dapat memilih lebih dari satu jawaban. Beri tanda centang (√) pada setiap pernyataan yang benar!<i><br></i></p>', 'a:6:{s:1:\"a\";s:10:\"<p>Kas</p>\";s:1:\"b\";s:12:\"<p>Utang</p>\";s:1:\"c\";s:14:\"<p>Piutang</p>\";s:1:\"d\";s:12:\"<p>Saham</p>\";s:1:\"e\";s:19:\"<p>Perlengkapan</p>\";s:1:\"f\";s:14:\"<p>Ekuitas</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"e\";i:3;N;}', 1701573931, 1701573931, 1, '', 1, 0, 0, '71ea38ae-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24332, 675, 0, 2, 2, NULL, NULL, NULL, '<p>Berikut ini transaksi pada Bengkel UTAMA MOTOR selama bulan Agustus 2020:\r\n</p><ol><li>1 Agustus 2020 Pak Dimas menginvestasikan uangnya sebesar Rp25.000.000,00 dan peralatan Bengkel Rp10.000.000,00.</li><li>10 Agustus 2020 diterima uang Rp500.000,00 dari Bu Senyum atas pekerjaan service mobilnya.</li><li>15 Agustus 2020 diselesaikan pekerjaan service motor milik Pak Santun senilai Rp1.500.000,00 dan akan dibayar awal bulan depan.</li><li>25 Agustus 2020 dibayar gaji 2 orang karyawan @ Rp750.000,00.</li><li>31 Agustus 2020 perlengkapan bersisa senilai Rp5.000.000,00</li></ol><p><i>Dari transaksi diatas, yang termasuk transaksi intern adalah….</i></p><p><i>\r\n</i></p>Kamu dapat memilih lebih dari satu jawaban. Beri tanda centang (√) pada setiap pernyataan yang benar!', 'a:5:{s:1:\"a\";s:8:\"<p>1</p>\";s:1:\"b\";s:8:\"<p>2</p>\";s:1:\"c\";s:8:\"<p>3</p>\";s:1:\"d\";s:8:\"<p>4</p>\";s:1:\"e\";s:8:\"<p>5</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"d\";i:2;s:1:\"e\";i:3;N;}', 1701573931, 1701573931, 1, '', 1, 0, 0, '71ea3a10-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24333, 675, 0, 2, 3, NULL, NULL, NULL, '<p>Transaksi yang terdapat pada Salon Niken Ayu :\r\n</p><ol><li>	Membeli perlengkapan dari Toko Sakha senilai Rp1.000.000,00 dengan syarat 2/10, n/30.</li><li>Membayar gaji karyawan setiap tanggal 5 senilai Rp5.000.000,00</li><li>Di akhir perode perlengkapan bersisa senilai Rp250.000,00</li><li>Diselesaikan pekerjaan merias pengantin dengan bayaran Rp275.000,00 dan baru diterima Rp100.000,00.</li><li>Peralatan   salon   disusutkan   sebesar   5%   dari   harga   perolehan   senilai Rp15.000.000,00.</li><li>Membayar cicilan dan bunga pinjaman kepada BNI sebesar Rp525.000,00. Berdasarkan transaksi di atas, <i>yang termasuk transaksi<b> ekstern</b> perusahaan jasa adalah...</i>.</li></ol><p>Kamu dapat memilih lebih dari satu jawaban. Beri tanda centang (√) pada setiap pernyataan yang benar!<br></p>', 'a:6:{s:1:\"a\";s:8:\"<p>1</p>\";s:1:\"b\";s:8:\"<p>2</p>\";s:1:\"c\";s:8:\"<p>3</p>\";s:1:\"d\";s:8:\"<p>4</p>\";s:1:\"e\";s:8:\"<p>5</p>\";s:1:\"f\";s:8:\"<p>6</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"d\";i:2;s:1:\"f\";i:3;N;}', 1701573931, 1701573931, 0, '', 1, 0, 0, '71ea3c3d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:23', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
