31, 1701573931, 1, '', 1, 0, 0, '71ea8437-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:24', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
