INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24432, 677, 0, 1, 5, NULL, NULL, NULL, '<div>Seorang anak hendak menaikkan batu bermassa 1 ton dengan alat seperti dibawah ini!</div><div><img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231206140209.png\" style=\"width: 158px;\"></div><div><div class=\"mt-2\"><p>Jika luas penampang pipa besar adalah 250 kali luas penampang pipa kecil dan tekanan cairan pengisi pipa diabaikan, besar gaya yang harus diberikan anak agar batu bisa terangkat adalah ...</p></div></div>', '50 N', '10 N', '30 N', '40 N', '20 N', NULL, NULL, NULL, NULL, NULL, 'd', 1701842483, 1701842578, 1, '', 1, 0, 0, '71ea895e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:24', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24433, 677, 0, 1, 6, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem;\">Seekor ikan berada pada kedalam 15 m dibawah permukaan air!</span></div><div><span style=\"font-size: 0.875rem;\"><br></span><img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231206140352.png\" style=\"width: 116px;\"></div><div>Jika massa jenis air<img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231207114143.png\" style=\"width: 99px;\">, percepatan gravitasi bumi <img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231207114155.png\" style=\"width: 70px;\">, tekanan udara luar <img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231207114205.png\" style=\"width: 70px;\">. Besar Tekanan hidrosatik yang di alami ikan adalah ... Pa<br></div>', '150', '1.500', '15.000', '150.000', '1.500.000', NULL, NULL, NULL, NULL, NULL, 'd', 1701842578, 1701920542, 1, '', 1, 0, 0, '71ea8a34-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:24', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (24434, 677, 0, 1, 7, NULL, NULL, NULL, '<p>Seekor ikan berada pada kedalaman 15 meter di bawah permukaan air!</p><p><img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231206140514.png\" style=\"width: 116px;\"></p><p>Jika massa jenis air <img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231207114236.png\" style=\"width: 99px;\">, Percepatan gravitasi bumi&nbsp;<img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231207114245.png\" style=\"width: 70px;\"> dan tekanan udara luar <img src=\"http://pas.id/siswa/uploads/bank_soal/file_20231207114253.png\" style=\"width: 70px;\">. Besar tekanan total yang dialami ikan adalah ... Pa<br></p>', '150.000', '250.000', '100.000', '150', '250', NULL, NULL, NULL, NULL, NULL, 'b', 1701842690, 1701920577, 1, '', 1, 0, 0, '71ea8ba9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:24', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
