INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25356, 719, 0, 1, 6, NULL, NULL, NULL, 'Adam adalah warga Desa Sukamaju, pada saat pemilihan kepala desa, Adam melakukan serangan fajar dalam bentuk membagi-bagikan uang dan sembako agar warga menjatuhkan pilihan terhadap dirinya sebagai kepala desa. Ternyata setelah diadakan penghitungan suara, Adam memeroleh suara mayoritas. Kamu mengetahui bahwa Adam berbuat tidak jujur dalam meraih kemenangan. Bagaimana sebaiknya tindakan kamu untuk melawan ketidakadilan tersebut?', 'Acuh tak acuh karena kamu tidak dirugikan karena bukan kontestan', 'Melapor kepada aparat penegak hukum dan pengawas pemilihan dengan bukti yang kuat', 'Diam saja karena warga kampungmu semua kebagaian uang takutnya kamu jadi sasaran kemarahan warga', 'Memberi tahu kontestan lain yang dirugikan', ' Mendatangi Pincen kalau aksinya ada yang mengetahuinya dan meminta uang diam kalau mau selamat', NULL, NULL, NULL, NULL, NULL, 'b', 1716480429, 1716480429, 1, '', 1, 0, 0, '71ed5d29-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:24', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
