INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25623, 726, 0, 5, 5, NULL, NULL, NULL, 'Laki-laki dan perempuan sama atau setara menurut pandangan Kitab suci atau dari sisi pandang Allah. Dalam hal apa saja kesetaraan   laki-laki dan perempuan dimaksud?&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Dalam hal kedudukan atau posisi dalam masyarakat dan hak dan kewajiban<br></div>', 1716487238, 1716487238, 0, '', 1, 0, 0, '71edea05-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25624, 726, 0, 5, 6, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pada masayrakat lain, kedudukan laki-laki lebih tinggi dari perempuan. Berikan  salah satu contoh&nbsp; bahwa laki-laki lebih tinggi kedudukannya dari pada perempuan!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><span xss=\"removed\">Pada masyarakat tertentu laki-laki sangat dihargai dan dihormati dan mendapat kedudukan yang tinggi, sedangkan perempuan tidak. Misalnya dalam keluarga laki-laki yang mempunyai hak bicara dan mengambil keputusan sedangkan perempuan tidak. Atau laki-laki mempunyai  bagian hak waris yang  lebih banyak dari  perempuan.</span><br></div>', 1716487238, 1716487238, 0, '', 1, 0, 0, '71edebf3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25625, 726, 0, 5, 7, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Manusia sebagai ciptaan  Allah yang luhur dan mulia patut  dihargai, dihormati dan dijunjung tinggi harkat dan martabatnya. Namun  fakta menunjukkan lain, perempuan  sering  disepelekan, diabaikan&nbsp; atau dianggap remeh orang lain. Berikan sebuah contoh bahwa perempuan sering&nbsp; disepelekan atau tidak dihargai, direndahkan harkat dan martabatnya!&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><ol><li><span xss=\"removed\">Perempuan tidak mempunyai hak bicara dan mengambil  keputusan dalam keluarga</span></li><li><span xss=\"removed\">Perempuan tidak boleh menduduki posisi atau jabatan terpenting dalam pemerintahan.</span><br></li></ol></div>', 1716487238, 1716487238, 0, '', 1, 0, 0, '71edecb5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
