INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25698, 727, 0, 1, 20, NULL, NULL, NULL, 'Hidup mengumat pada dasarnya merupakan hakikat Gereja itu sendiri, sebab hakikat Gereja adalah persaudaraan cinta kasih seperti yang dicerminkan oleh hidup Umat Perdana (lih. Kis 2: 41-47), maka Gereja sebagai Umat Allah mengandung makna, bahwa ....', '<div>Kaum awam tidak mempunyi tanggungjawab untuk perkembangan Gereja.</div>', '<div>Kaum awam lebih mempunyai wewenang untuk mengatur gereja dari pada Hierarki</div>', '<div>Hierarki/pemimpin Gereja mempunyai martabat yang lebih tinggi dari kaum awam.</div>', '<div>Hierarki dan kaum awam mempunyai martabat yang sama dihadapan Allah.</div>', 'Hierarki dan kaum awam mempunyai tugas dan wewenang yang sama.', NULL, NULL, NULL, NULL, NULL, 'e', 1716487249, 1716487249, 0, '', 1, 0, 0, '71ee8b0c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25699, 727, 0, 1, 21, NULL, NULL, NULL, 'Pada saat ini sering dikatakan bahwa Gereja itu hendaknya tidak bersikap eksklusif (tertutup), tetapi inklusif (terbuka), artinya adalah ...', '<div>Gereja harus lebih aktif menawarkan keselamatan kepada orang lain, karena di luar Gereja tidak ada kebenaran atau keselamatan.</div>', '<div>Gereja harus bekerja sama dengan agama-agama lainnya, asalkan agama- agama lain itu mau menerima ajaran dan prinsip-prinsip hidup Kristiani.</div>', '<div>Gereja harus siap menerima kehadiran agama-agama lainnya, dan harus membentengi umatnya agar tidak pindah agama.</div>', '<div>Gereja harus mau menerima ajaran agama-agama lainnya, karena pada prinsipnya semua agama itu sama.</div>', 'Gereja harus selalu siap untuk berdialog dengan agama dan budaya mana pun juga dan tidak hanya untuk umatnya saja.', NULL, NULL, NULL, NULL, NULL, 'e', 1716487249, 1716487249, 0, '', 1, 0, 0, '71ee9014-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25700, 727, 0, 1, 22, NULL, NULL, NULL, 'Paham Gereja sebagai umat Allah dianggap sebagai paham yang cocok atau relevan dengan tuntutan dan perkembangan zaman. Paham ini dinilai memiliki nilai historis dengan umat Allah Perjanjian Lama karena Gereja menganggap diri sebagai Israel Baru, kelanjutan dari Israel yang lama.\r\nSalah satu alasan Gereja dikatakan sebagai Umat Allah adalah….', '<div>Inisiatif pertama datang dari Allah sendiri bukan dari manusia</div>', '<div>Gereja mempunyai tujuan untuk menyelamatkan umat manusia</div>', '<div>Semua anggota Gereja mempunyai tujuan hidup yang sama</div>', '<div>Para pemimpin Gereja merupakan wakil Kristus di dunia</div>', 'Gereja didirikan oleh Kristus', NULL, NULL, NULL, NULL, NULL, 'b', 1716487249, 1716487249, 0, '', 1, 0, 0, '71ee9393-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25701, 727, 0, 1, 23, NULL, NULL, NULL, '<div>Perhatikan pernyataan berikut!</div><div><br></div><div>1. Saling memberi kesaksian hidup sebagi putra-putri Allah</div><div><br></div><div>2. Aktif berpartisipasi dalam kehidupan Gereja</div><div><br></div><div>3. Lebih bersifat jujur dan terbuka satu dengan yang lain</div><div><br></div><div>4. Memperkenalkan anggota-anggota yang sudah hidup secara heroik untuk mencapai kekudusan.</div><div><br></div><div><br></div><div>Usaha-usaha untuk memperjuangkan kekudusan Gereja adalah ....</div>', '1 dan 3', '<div>1 dan 2</div>', '<div>1 dan 4</div>', '<div>2 dan 3</div>', '2 dan 4', NULL, NULL, NULL, NULL, NULL, 'a', 1716487249, 1716487249, 0, '', 1, 0, 0, '71ee968f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (25702, 727, 0, 1, 24, NULL, NULL, NULL, 'Istilah “Umat Allah” sudah digunakan dalam Perjanjian Lama yang kemudian dimunculkan dan dihidupkan kembali oleh Konsili Vatikan II setelah sekian lama Gereja menjadi terlalu hierarkis; didominasi oleh kaum rohaniwan dan awam yang adalah mayoritas dalam Gereja agak terdesak ke pinggir. Dengan paham Gereja sebagai Umat Allah yang di munculkan kembali dalam Konsili Vatikan II hendak diakui kembali kesamaan martabat dan peranan semua anggota Gereja. Semua anggota Gereja memiliki martabat yang sama, hanya berbeda dalam hal fungsi. Maka dengan demikian yang dimaksud dengan umat Allah adalah…', '<div>persekutuan orang-orang yang percaya akan karya keselamatan Allah dalam diri Yesus Kristus</div>', '<div>pilihan pribadi setiap manusia yang taat pada Allah</div>', '<div>setiap orang atau persekutuan yang selalu dipanggil Allah untuk misi tersembunyi</div>', '<div>panggilan untuk orang-orang yang percaya pada dipanggilan Allah untuk menepati janji-Nya</div>', 'panggilan Allah untuk penyelamatan pribadi', NULL, NULL, NULL, NULL, NULL, 'a', 1716487249, 1716487249, 0, '', 1, 0, 0, '71ee98d9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
