INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26545, 737, 0, 1, 9, 'a:0:{}', NULL, NULL, '<p>\"Maka teranglah Tuan-tuan yang terhormat, bahwa jika kita hendak mendirikan negara Indonesia yang sesuai dengan keistimewaan sifat corak masyarakat Indonesia, maka negara kita harus berdasar atas aliran pikiran (staatsidee) negara yang integralistik...\" Di atas adalah kutipan pidato menurut .... </p>\n', '<p>Mr. Soepomo</p>\n', '<p>Ir. Soekarno </p>\n', '<p>Dr. Mohammad Hatta </p>\n', '<p>Ki Bagus Hadikusumo </p>\n', '<p>Mr. Mohammad Yamin </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f10090-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26546, 737, 0, 1, 10, 'a:0:{}', NULL, NULL, '<p>Dalam sidang BPUPK, tokoh ini setuju untuk memisahkan urusan agama dan negara ....</p>\n', '<p>Mohammad Hatta</p>\n', '<p>Soepomo </p>\n', '<p>Kahar Muzakkir </p>\n', '<p>Soekarno </p>\n', '<p>Ki Bagus Hadikusumo </p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f101e8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26547, 737, 0, 1, 11, 'a:0:{}', NULL, NULL, '<p>Makna dari philosophische grondslag adalah ....</p>\n', '<p>Filsafat Norma Dasar</p>\n', '<p>Filsafat Undang-Undang Dasar</p>\n', '<p>Filsafat Pancasila </p>\n', '<p>Filsafat Kehidupan </p>\n', '<p>Filsafat Negara </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f10364-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26548, 737, 0, 1, 12, 'a:0:{}', NULL, NULL, '<p>Menurut Ir. Soekarno, negara merdeka perlu suatu Weltanschauung, makna dari Weltanschauung adalah ....</p>\n', '<p>Dasar bangsa</p>\n', '<p>Dunia hukum </p>\n', '<p>Dasar negara </p>\n', '<p>Pandangan hidup bangsa </p>\n', '<p>Hukum dasar </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f10485-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26549, 737, 0, 1, 13, 'a:0:{}', NULL, NULL, '<p>Dalam pidatonya, Soekarno mengemukakan bahwa negara merdeka harus mempunyai Politieke Onafhankelijkheid. Makna dari politieke Onafhankelijkheid adalah ....</p>\n', '<p>kemerdekaan militer</p>\n', '<p>kemerdekaan bangsa </p>\n', '<p>kemerdekaan politik </p>\n', '<p>kemerdekaan lahir dan batin </p>\n', '<p>kemerdekaan ekonomi </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f1055e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26550, 737, 0, 1, 14, 'a:0:{}', NULL, NULL, '<p>Mengapa usulan perubahan tujuh kata dalam sila pertama Piagam Jakarta begitu mudah dilakukan oleh para pendiri bangsa ....</p>\n', '<p>karena para pendiri bangsa menginginkan agar Jepang memberikan kemerdekaan</p>\n', '<p>karena para pendiri bangsa mengikuti permintaan dari pemerintah Jepang </p>\n', '<p>karena para pendiri bangsa sangat mementingkan nasib dan persatuan bangsa </p>\n', '<p>karena para pendiri bangsa sangat mementingkan pemerintah yang baru berdiri </p>\n', '<p>karena para pendiri bangsa ingin segera merdeka </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f1063b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26551, 737, 0, 1, 15, 'a:0:{}', NULL, NULL, '<p>Berkaitan dengan rancangan asas atau dasar Indonesia Merdeka hasil sidang BPUPK, manakah pernyataan di bawah ini yang benar ....</p>\n', '<p>Soekarno menyebut Mukadimah</p>\n', '<p>Soekarno menyebut Piagam Jakarta </p>\n', '<p>M. Yamin menyebut Mukadimah </p>\n', '<p>M. Yamin menyebut Piagam Jakarta </p>\n', '<p>M. Yamin menyebut Piagam Mukadimah </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f10717-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26552, 737, 0, 1, 16, 'a:0:{}', NULL, NULL, '<p>Agenda setelah rapat BPUPK adalah menyiapkan dan mematangkan serta mengesahkan hal-hal penting untuk mempersiapkan kemerdekaan Indonesia, maka dibentuklah ....</p>\n', '<p>BPUPK</p>\n', '<p>PPKn</p>\n', '<p>PPPKI </p>\n', '<p>PPKI </p>\n', '<p>BPK </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f107ef-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26553, 737, 0, 1, 17, 'a:0:{}', NULL, NULL, '<p>Mengapa sejumlah tokoh Islam yang selama ini mengusulkan Indonesia berasaskan Islam, seperti Ki Bagus Hadikusumo dan K.H.A. Wachid Hasjim menerima usulan penghapusan tujuh kata dalam Piagam Jakarta ....</p>\n', '<p>karena para tokoh Islam tersebut menginginkan untuk duduk dalam pemerintahan</p>\n', '<p>karena para tokoh Islam tersebut menginginkan negara Indonesia menjalankan syariat Islam </p>\n', '<p>karena para tokoh Islam tersebut berusaha untuk menjadi pimpinan tinggi negara </p>\n', '<p>karena para tokoh Islam tersebut menginginkan agar negara Indonesia segera merdeka </p>\n', '<p>karena para tokoh Islam itu berbesar hati dan mendahulukan kepentingan bersama, yakni menjaga keutuhan bangsa </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f109a7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26554, 737, 0, 1, 18, 'a:0:{}', NULL, NULL, '<p>Tujuh kata yang diubah dalam dasar negara Piagam Jakarta semula \"Ketuhanan, dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya\". Menjadi ....</p>\n', '<p>Ketuhanan yang Maha Esa</p>\n', '<p>Kemanusiaan yang adil dan beradab</p>\n', '<p>keadilan sosial bagi seluruh rakyat Indonesia</p>\n', '<p>Kerakyatan yang dipimpin oleh hikmah kebijaksanaan, dalam permusyawaratan perwakilan </p>\n', '<p>Persatuan Indonesia </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f10a8f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26555, 737, 0, 1, 19, 'a:0:{}', NULL, NULL, '<p>Dari pidato Soekarno tanggal 1 Juni 1945, Soekarno menyampaikan 5 prinsip dasar negara Indonesia merdeka yang dinamakan ....</p>\n', '<p>Pancasona</p>\n', '<p>Pancaroba </p>\n', '<p>Pancasila </p>\n', '<p>Pancasakti </p>\n', '<p>Pancadarma </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f10b69-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26556, 737, 0, 1, 20, 'a:0:{}', NULL, NULL, '<p>Geopolitik untuk bangsa Indonesia pertama kali diperkenalkan oleh ....</p>\n', '<p>Mohammad Yamin pada tanggal 29 Mei 1945 saat mengusulkan dasar negara</p>\n', '<p>Pidato Radjiman Widyodiningrat saat membuka rapat sidang pertama BPUPKI </p>\n', '<p>Soekarno pada pidatonya di hadapan sidang BPUPKI tanggal 1 Juni 1945 </p>\n', '<p>Ki Hadi Kusuma pada tanggal 29 Mei 1945 saat mengusulkan dasar negara </p>\n', '<p>Soepomo pada pidatonya tanggal 31 Mei 1945 ketika memberikan usulan lima prinsip dasar negara </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f10c5d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26557, 737, 0, 1, 21, 'a:0:{}', NULL, NULL, '<p>Mengapa Jepang menggunakan sejumlah semboyan, seperti &ldquo;Jepang Pelindung Asia&rdquo;, &ldquo;Jepang Cahaya Asia&rdquo;, dan &ldquo;Jepang Saudara Tua&rdquo;? </p>\n', '<p>untuk menaklukan sekutu</p>\n', '<p>untuk menarik simpati bangsa Eropa </p>\n', '<p>untuk menarik simpati bangsa Belanda </p>\n', '<p>untuk menaklukan Belanda </p>\n', '<p>untuk menarik simpati bangsa Indonesia </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f10d43-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26558, 737, 0, 1, 22, 'a:0:{}', NULL, NULL, '<p>Pada peringatan Pembangunan Djawa Baroe pada 1 Maret 1945, Jepang mengumumkan rencananya untuk membentuk Dokuritsu Zyunbi Tyoosakai atau disebut pula dengan .... </p>\n', '<p>Badan Persiapan Usaha-Usaha Percepatan Kemerdekaan</p>\n', '<p>Badan Penyelidik Untuk Persiapan Kemerdekaan </p>\n', '<p>Badan Penyelidik Usaha-Usaha Persiapan Kemerdekaan </p>\n', '<p>Badan Persiapan Usaha-Usaha Penyelidikan Kemerdekaan </p>\n', '<p>Badan Penyelidik Usaha-Usaha Percepatan Kemerdekaan </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f10e18-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26559, 737, 0, 1, 23, 'a:0:{}', NULL, NULL, '<p>BPUPK diketuai oleh KRT Radjiman Wedyodiningrat dengan Wakil Ketua Ichibangase Yosio dan Raden Pandji Soeroso. BPUPK ini melaksanakan sidang sebanyak .... </p>\n', '<p>dua kali</p>\n', '<p>tiga kali </p>\n', '<p>lima kali </p>\n', '<p>satu kali </p>\n', '<p>empat kali </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f10eef-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26560, 737, 0, 1, 24, 'a:0:{}', NULL, NULL, '<p>Pernyataan yang benar di bawah ini adalah .... </p>\n', '<p>Sidang pertama membahas tentang Dasar Negara. Sidang kedua membahas tentang Rancangan Undang-Undang Dasar</p>\n', '<p>Sidang pertama membahas tentang Undang-Undang Dasar. Sidang kedua membahas tentang Dasar Negara </p>\n', '<p>Sidang pertama membahas penyerahan kekuasaan dari Jepang. Sidang kedua membahas kedulatan</p>\n', '<p>Sidang pertama membahas tentang kedaulatan. Sidang kedua membahas penyerahan kekuasaan dari Jepang </p>\n', '<p>semuanya benar </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f10fc5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26561, 737, 0, 1, 25, 'a:0:{}', NULL, NULL, '<p>Maka teranglah Tuan-tuan yang terhormat, bahwa jika kita hendak mendirikan negara Indonesia yang sesuai dengan keistimewaan sifat corak masyarakat Indonesia, maka negara kita harus berdasar atas aliran pikiran (staatsidee) negara yang integralistik...\" </p><p>Di atas adalah kutipan pidato menurut ....</p>\n', '<p>Mr. Soepomo</p>\n', '<p>Ir. Soekarno </p>\n', '<p>Dr. Mohammad Hatta </p>\n', '<p>Ki Bagus Hadikusumo </p>\n', '<p>Mr. Mohammad Yamin </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f110a6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26562, 737, 0, 1, 26, 'a:0:{}', NULL, NULL, '<p>Makna dari philosophische grondslag adalah .... </p>\n', '<p>Filsafat Norma Dasar</p>\n', '<p>Filsafat Undang-Undang Dasar </p>\n', '<p>Filsafat Pancasila </p>\n', '<p>Filsafat Kehidupan </p>\n', '<p>Filsafat Negara </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f11232-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26563, 737, 0, 1, 27, 'a:0:{}', NULL, NULL, '<p>Menurut Ir. Soekarno, negara merdeka perlu suatu Weltanschauung, makna dari Weltanschauung adalah .... </p>\n', '<p>Dasar bangsa</p>\n', '<p>Dunia hukum </p>\n', '<p>Dasar negara </p>\n', '<p>Pandangan hidup bangsa </p>\n', '<p>Hukum dasar </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f1131a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26564, 737, 0, 1, 28, 'a:0:{}', NULL, NULL, '<p>Dalam pidatonya, Soekarno mengemukakan bahwa negara merdeka harus mempunyai Politieke Onafhankelijkheid. Makna dari politieke Onafhankelijkheid adalah .... </p>\n', '<p>kemerdekaan militer</p>\n', '<p>kemerdekaan bangsa </p>\n', '<p>kemerdekaan politik </p>\n', '<p>kemerdekaan lahir dan batin </p>\n', '<p>kemerdekaan ekonomi </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f1141b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26565, 737, 0, 1, 29, 'a:0:{}', NULL, NULL, '<p>Mengapa usulan perubahan tujuh kata dalam sila pertama Piagam Jakarta begitu mudah dilakukan oleh para pendiri bangsa .... </p>\n', '<p>karena para pendiri bangsa menginginkan agar Jepang memberikan kemerdekaan</p>\n', '<p>karena para pendiri bangsa mengikuti permintaan dari pemerintah Jepang</p>\n', '<p>karena para pendiri bangsa sangat mementingkan nasib dan persatuan bangsa</p>\n', '<p>karena para pendiri bangsa sangat mementingkan pemerintah yang baru berdiri</p>\n', '<p>karena para pendiri bangsa ingin segera merdeka </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f1150e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26566, 737, 0, 1, 30, 'a:0:{}', NULL, NULL, '<p>Mengapa sejumlah tokoh Islam yang selama ini mengusulkan Indonesia berasaskan Islam, seperti Ki Bagus Hadikusumo dan K.H.A. Wachid Hasjim menerima usulan penghapusan tujuh kata dalam Piagam Jakarta .... </p>\n', '<p>karena para tokoh Islam tersebut menginginkan untuk duduk dalam pemerintahan</p>\n', '<p>karena para tokoh Islam tersebut menginginkan negara Indonesia menjalankan syariat Islam </p>\n', '<p>karena para tokoh Islam tersebut berusaha untuk menjadi pimpinan tinggi negara </p>\n', '<p>karena para tokoh Islam tersebut menginginkan agar negara Indonesia segera merdeka </p>\n', '<p>karena para tokoh Islam itu berbesar hati dan mendahulukan kepentingan bersama, yakni menjaga keutuhan bangsa </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f115f5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
