INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26569, 737, 0, 1, 33, 'a:0:{}', NULL, NULL, '<p>Prinsip laut bukan sebagai pemisah, tetapi pemersatu bangsa Indonesia terdapat dalam peraturan negara, yakni .... </p>\n', '<p>Peraturan Pemerintah Pengganti Undang-Undang Nomor 4/PRP/1960</p>\n', '<p>Hukum Laut PBB 1982 tentang UNCLOS </p>\n', '<p>Deklarasi Djuanda pada tanggal 13 Desember 1957 </p>\n', '<p>UUD NRI tahun 1945 pasal 25 A </p>\n', '<p>Undang-undang RI no. 32 tahun 2014 tentang kelautan </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f1197c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
