INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26572, 737, 0, 1, 36, 'a:0:{}', NULL, NULL, '<p>Keberagaman harus membentuk masyarakat Indonesia yang memiliki toleransi dan sikap saling menghargai. Oleh karena itu diperlukan adanya .... </p>\n', '<p>Komitmen persatuan bangsa dalam keberagaman</p>\n', '<p>Komitmen untuk membangun daerahnya masing-masing </p>\n', '<p>Komitmen untuk mensejahterakan rakyat di daerah tertinggal </p>\n', '<p>Komitmen untuk memajukan daerahnya dalam bingkai persatuan </p>\n', '<p>Komitmen persatuan antara sesama umat seagama dengan semangat ukhuwah </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f11df6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
