INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26574, 737, 0, 1, 38, 'a:0:{}', NULL, NULL, '<p>Persatuan dan kesatuan bangsa sangat penting bagi bangsa Indonesia, hal itu karena .... </p>\n', '<p>Bangsa Indonesia adalah bangsa yang toleransi</p>\n', '<p>Bangsa Indonesia adalah bangsa yang beragam </p>\n', '<p>Bangsa Indonesia memiliki semboyan Bhinneka Tunggal Ika </p>\n', '<p>Pengalaman sejarah Bangsa Indonesia pernah dijajah oleh bangsa barat selama 350 tahun </p>\n', '<p>Dengan persatuan dan kesatuan bangsa Indonesia yang majemuk akan menjadi kokoh dan kuat </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f12068-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
