INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26603, 737, 0, 5, 2, 'a:0:{}', NULL, NULL, '<p>Sebutkan tokoh-tokoh yang tergabung dalam Panitia Sembilan!</p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>ir. Soekarno,&nbsp;Moh. Hatta,&nbsp;Moh. Yamin,&nbsp;Acmad Subardjo,&nbsp;Maramis,&nbsp;KH. Wachid Hasyim,&nbsp;KH. Abdul Kahar Moedzakkir,&nbsp;Abi Kusno Tjokrosujoso,&nbsp;H. Agus Salim</p>\n', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f148fa-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26604, 737, 0, 5, 3, 'a:0:{}', NULL, NULL, '<p>Jelaskan nilai-nilai yang terkandung dalam Pancasila Sila Ke 1 ! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Bahwa bangs Indonesia adalah bangsa yang percaya kepada Tuhan Yang Maha Esa, Sehingga dapat melaksanakan ajaran-ajaran agamanya secara nyaman dan seksama tanpa mengalami gangguan.</p>\n', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f14a7a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26605, 737, 0, 5, 4, 'a:0:{}', NULL, NULL, '<p>Jelaskan nilai-nilai yang terkandung dalam Pancasila Sila Ke 2 ! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Bahwa setiap bangsa Indonesia dijunjung tinggi, diakui dan diperlakukan sesuai dengan harkat dan martabatnya selaku ciptaan Tuhan Yang Maha Esa.</p>\n', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f14b4b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26606, 737, 0, 5, 5, 'a:0:{}', NULL, NULL, '<p>Jelaskan nilai-nilai yang terkandung dalam Pancasila Sila Ke 3 ! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Sila ketiga ini memberikan syarat mutlak kepada setiap bangsa Indonesia untuk menjunjung tingggi Persatua.</p>\n', 1717547105, 1717547105, 0, '', 8, 0, 0, '71f14c1f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26607, 737, 0, 5, 6, 'a:0:{}', NULL, NULL, '<p>Bagaimana penerapan Pancasila dalam konteks dalam kehidupan berbangsa? apakah sudah terumplementasi atau belum? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Penerapan Pancasila dalam konteks kehidupan berbangsa dan bernegara adalah upaya untuk mengimplementasikan nilai-nilai Pancasila kedalam kehidupan melalui kehidupan sehari-hari hal ini sesuai dengan tujuan Pancasila yakni menciptakan kehidupan yang aman dalam berbangsa dan bernegara.</p><p>sayangnya, Nilai-nilai Pancasila masih belum dapat terimplemntasi secara maksimal karena adanya tindakan intoleran dibeberapa kalangan masyarakat.</p>\n', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f14d96-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26608, 737, 0, 5, 7, 'a:0:{}', NULL, NULL, '<p>Jelaskan hal yang menjadi tantangan dalam penerapan Pancasila dalam konteks dalam kehidupan berbangsa? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Penerapan Pancasila dalam kontek kehidupan berbangsa masih belum terimplementasi dengan baik. Tantangannya adalah munculnya pemikiran baru yang bertentangan dengan Ideologi Pancasila, Selain itu masuknya budaya asing juga berpotensi mengkikis budaya asli Indonesia.</p>\n', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f14e75-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26609, 737, 0, 5, 8, 'a:0:{}', NULL, NULL, '<p>Apakah kehidupan masyarakat Indonesia telah sesuai dengan nilai-nilai Pancasila? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Sebagai masyarakat sudah mengimplementasikan nilai-nilai Pancasila dalam kehidupan, misalnya seperti hidup rukun dan toleran terhadap sesama warga. Namun masih ada beberap masyarakat yang belum menerapkannya. Contoh perbuatan yang bertentangan dengan nilai-nilai Pancasila yakni seperti tidak memenuhi hak orang lain, tidak hadir dalam kegiatan gotong royong dan lain sebagainya.</p>\n', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f14fec-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26610, 737, 0, 5, 9, 'a:0:{}', NULL, NULL, '<p>Apa saja karakter atau ciri-ciri kehidupan masyarakat yang sesuai dengan nilai-nilia Pancasila? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Beriman dan bertakwa pada Tuhan ang Maha Esa.</p><p>Saling menghormati agama dan kepercayaan masing-masing orang.</p><p>memiliki akhlak yang terpuji</p><p>Tidak suka melakukan diskriminasi atau kekerasan.</p><p>Tidak mudah terpecah belah oleh berbagai gangguan dari luar maupun dari dalam negaranya.</p><p>Senantiasa melakukan musyawarah dan tidak ada yang merasa paling benar.</p><p>Senang bergotong-royong.</p><p>Memiliki toleransi yang tinggi.</p>\n', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f150e1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26611, 737, 0, 5, 10, 'a:0:{}', NULL, NULL, '<p>Tuliskan apa yang ingin kalian ketahui tentag jati diri, kebhinekaan dan kaitannya dengan Pancasila! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Jati diri adalah konsep untuk menggambarkan etika, nilai dan karekteristik yang menjadi ciri khas dari seseorang. Kebhinekaan merupakan ciri yang menjadi ciri khas dalam kehidupan manusia.</p><p>Jati diri adalah bagian penting dari kebhinekaan karena seseorang memiliki jati diri yang berbeda yang ditentukan oleh budaya, kepercayaan, latar belakan, dan banyak faktor lainnya. Dengan begitu jati diri kemungkinan orang untuk mengekspresikan identitas mereka secara unik dan menghormati kebhinekaan dalam kehidupan.</p><p>Pancasila adalah dasar filosofis yang mendasari kehidupan berbangsa dan bernegara di Indonesia yang mencangkup lima sila. Jati diri seseorang berhubungan dengan Pancasila karena Jati Diri menyangkut nilai-nilai dan prinsip-prinsip yang menjadi dasar bagi seseorang untuk mengikuti dan mematuhi Pancasila sebagai dasar filosofis kehidupan.&nbsp;</p>\n', 1717547105, 1717547105, 1, '', 8, 0, 0, '71f152ab-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26702, 738, 0, 1, 1, 'a:0:{}', NULL, NULL, '<p>Hak Asasi Manusia (HAM) adalah seperangkat hak yang melekat pada keberadaan manusia sebagai makhluk Tuhan Yang Maha Esa dan merupakan anugrahnya yang wajib dihormati, dijunjung tinggi, dan dilindungi oleh negara. Hal tersebut mengandung arti bahwa .... </p>\n', '<p>negara menjamin hak setiap warga negara</p>\n', '<p>negara menjamin hak setiap warga negara </p>\n', '<p>setiap tindakan harus sesuai dengan hak asasu manusia </p>\n', '<p>persamaan dalam bidang politik, ekonomi, sosial dan budaya </p>\n', '<p>setiap manusia memiliki persamaan kedudukan dalam hukum </p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f1544b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26703, 738, 0, 1, 2, 'a:0:{}', NULL, NULL, '<p>Hak asasi manusia berkaitan erat dengan hak kemerdekaan, hak hidup, dam hak untuk mempunyai sesuatu yang tidak boleh diganggu gugat. Hal ini karena HAM merupakan sesuatu yang .... </p>\n', '<p>sudah dibawa manusia sejak lahir</p>\n', '<p>sudah diturunkan dari orang tua </p>\n', '<p>bersifat eksklusif dan sangat pribadi </p>\n', '<p>dibawa manusia sejak lahir sebagai anugrah Tuhan </p>\n', '<p>menunjukan eksistensi manusia yang bermartabat </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f155d4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26704, 738, 0, 1, 3, 'a:0:{}', NULL, NULL, '<p>NIlai-nilai Pancasila tentunya harus kita terapkan didalam kehidupan sehari-hari. Berikut ini contoh pelaksanaan hak asasi manusia yang sesuai dengan nilai-nilai Pancasila didalam kehidupan sehari-hari adalah .... </p>\n', '<p>memiliki martabat yang luhur</p>\n', '<p>diberi kebebasan dalam memiliki harta </p>\n', '<p>kebebasan dalam mengemukakan pendapat </p>\n', '<p>hak mememluk agama tanpa batasan </p>\n', '<p>melakukan perubahan sesuai ajaran agama </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f1574f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26705, 738, 0, 1, 4, 'a:0:{}', NULL, NULL, '<p>HAM dalam Pancasila sesungguhnya telah dirumuskan dalam Pembukaan UUD NRI Tahun 1945 yang kemudian diperinci didalam batang tubuhnya yang merupakan hukum dasar, hukum yang konstitusional, dan fundamental bagi Negara Republik Indonesia .... </p>\n', '<p>Melindungi HAM</p>\n', '<p>menghormati hak dan persamaan </p>\n', '<p>meningkatkan patriotisme dalam perjuangan warga negara </p>\n', '<p>mengakui, menghormati dan menegakan HAM </p>\n', '<p>menjamin pelaksanaan HAM </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f158d1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26706, 738, 0, 1, 5, 'a:0:{}', NULL, NULL, '<p>Perhatikan isi Pasal 28A UUD NRI Tahun 1945 berikut ini!</p><p>Setiap orang berhak untuk hidup serta berhak mempertahankan hidup dan kehidupannya.</p><p>Makna yang terkandung dalam pasal 28A UUD&nbsp; NRI Tahun 1945 adalah ....</p>\n', '<p>setiap orang bebas memeluk agama</p>\n', '<p>setiap warga negara Indonesia memiliki hak yang sama untuk membentuk keluarga dan melanjutkan keturunan melalui perkawinan yang sah </p>\n', '<p>setiap anak sejak dia lahir memiliki hak untuk hidup, tumbuh, berkembang, serta berhak atas perlindungan dari kekerasan dan diskriminasi </p>\n', '<p>tidak ada satu orang pun yang bisa membeli nyawa orang lain atau menghilangkan nyawa orang lain dengan alasan apapun </p>\n', '<p>setiap orang berhak untuk mengembangkan diri dalam hal pendidikan, teknologi dan pengetahun serta seni budaya untuk meningkatkan kualitas hidupnya dan demi kesejahteraan manusia, terutama rakyat Indonesia </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f159e2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26707, 738, 0, 1, 6, 'a:0:{}', NULL, NULL, '<p>Perhatikan isi Pasal 29 ayat (2) UUD NRI Tahun 1945 berikut ini!</p><p>Negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan untuk beribadat menurut agamanya dan kepercayaannya itu.</p><p>Makna yang terkandung dalam Pasal 29 ayat (2) UUD NRI Tahun 1945 adalah ....</p>\n', '<p>hanya ada lima agama yang diakui negara</p>\n', '<p>negara berdasarkan atas Ketuhanan Yang Maha Esa </p>\n', '<p>adanya jaminan hukum kebebasan dalam beragama oleh negara </p>\n', '<p>hak hidup dan mempertahankan hidup dan kehidupannya </p>\n', '<p>negara yang rakyatnya beriman dan bertakwa kepada Tuhan Yang Maha Esa </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f15bde-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26708, 738, 0, 1, 7, 'a:0:{}', NULL, NULL, '<p>Pelanggaran HAM dapat terjadi karena ada faktor yang menjadi penyebabnya, baik itu internal amupun eksternal. Contoh fakta yang tidak menyebabkan pelanggaran HAM adalah .... </p>\n', '<p>terjadinya penyalahgunaan kekuasaan</p>\n', '<p>kurang tegasnya aparat penegak hukum </p>\n', '<p>terjadinya penyalahgunaan teknologi </p>\n', '<p>kesenjangan sosial dan ekonomi yang tinggi </p>\n', '<p>tegasnya aparat penegak hukum dalam menindak pelanggaran </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f15cbb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26709, 738, 0, 1, 8, 'a:0:{}', NULL, NULL, '<p>Banyak faktor yang menyebabkan pelanggaran HAM, baik faktor internal baik yang disebabkan oleh sang pelaku itu sendiri ataupun faktor eksternal yang disebabkan oleh keluarga, teman, saudara dan lingkungan tempat sipelaku tinggal.</p><p>Contoh faktor internal yang dapat menyebabkan pelanggaran HAM adalah ....</p>\n', '<p>sikap mementingkan kepentingan umum</p>\n', '<p>sikap egois yang tinggi </p>\n', '<p>tingginya sikap toleransi </p>\n', '<p>tingginya kesadaran HAM </p>\n', '<p>tegasnya aparat penegak hukum </p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f15e8a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26710, 738, 0, 1, 9, 'a:0:{}', NULL, NULL, '<p>Faktor-faktor yang berasal dari luar diri manusia yang mendorong seseorang atau sekelompok orang yang melakukan pelanggaran HAM disebut faktor .... </p>\n', '<p>eksternal</p>\n', '<p>internal </p>\n', '<p>langsung </p>\n', '<p>tidak langsung </p>\n', '<p>sumber </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f15f63-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26711, 738, 0, 1, 10, 'a:0:{}', NULL, NULL, '<p>Peristiwa Tanjung Priok adalah peristiwa yang terjadi pada 12 september 1984 di Tanjung Priok, Jakarta. Kasus termasuk termasuk dalam pelanggaran HAM berat karena .... </p>\n', '<p>pengiriman tenaga kerja wanita secara paksa</p>\n', '<p>perbudakan di negara asing </p>\n', '<p>penangkapan dan penahanan sewenang-wenang </p>\n', '<p>kelalaian pemberian pelayanan kesehatan </p>\n', '<p>pencemaran tanah dan udara </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f16031-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26712, 738, 0, 1, 11, 'a:0:{}', NULL, NULL, '<p>Penegakan HAM menjadi catatan penting dalam upaya membangun demokrasi disuatu negara. Hal itu karena penegakan hak asasi manusia merupakan .... </p>\n', '<p>bentuk penghargaan terhadap kodrat manusia</p>\n', '<p>bentuk penghargaan terhadap jasa para pemain </p>\n', '<p>bentuk penghargaan terhadap takdir tuhan </p>\n', '<p>bentuk penghargaan terhadap pahlawan bangsa </p>\n', '<p>bentuk penghormatan terhadap generasi muda </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f1621f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26713, 738, 0, 1, 12, 'a:0:{}', NULL, NULL, '<p>Komnas HAM berdiri sejak tahun 1993 berdasarkan Keputusan Presiden Nomor 50 Tahun 1993 Tentang Komisi Nasional Hak Asasi Manusia. Lembaga tersebut dibentuk oleh pemerintah dalam rangka untuk .... </p>\n', '<p>kepentingan bangsa dan negara Republik Indonesia</p>\n', '<p>menunjukan bahwa negara Indonesia berdasarkan HAM </p>\n', '<p>memperjuangkan HAM di Indonesia </p>\n', '<p>menghargai HAM sebagai hak asasi manusia sejak lahir </p>\n', '<p>menegakan masalah HAM di Indonesia </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f162f3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26714, 738, 0, 1, 13, 'a:0:{}', NULL, NULL, '<p>KOmnas HAM memiliki kewenangan untuk melakukan penyelidikan terhadap pelanggaran hak asasi manusia. Meski demikian tidak semua kasus dapat menjadi kasus yang tidak termasuk kasus pelanggaran HAM yang harus ditangani oleh Komnas HAM adalah .... </p>\n', '<p>perbudakan</p>\n', '<p>pembunuhan </p>\n', '<p>penyiksaan </p>\n', '<p>penganiayaan </p>\n', '<p>pengkhianatan </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f164c4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
