INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26716, 738, 0, 1, 15, 'a:0:{}', NULL, NULL, '<p>Berikut ini tidak termasuk jenis hak asasi manusia yang harus dihormati dan dijamin pemenuhannya, baik oleh negara maupun setiap warga negara adalah .... </p>\n', '<p>hak untuk meneruskan keturunan</p>\n', '<p>hak untuk mendapatkan pendidikan </p>\n', '<p>hak untuk mendapatkan kesesehatan </p>\n', '<p>hak untuk mendapatkan pekerjaan </p>\n', '<p>melindungi hak asasi orang lain </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f16668-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
