INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26718, 738, 0, 1, 17, 'a:0:{}', NULL, NULL, '<p>Maksud dari pernyataan bahwa hak asasi manusia tidak dapat dibagi adalah ....</p>\n', '<p>tidak dapat dihalangkan atau diserahkan</p>\n', '<p>selalu bertambah sesuai tuntunan zaman </p>\n', '<p>semua orang berhak mendapat semua hak, meliputi hak sispil, politik, ekonomi, sosial dan budaya </p>\n', '<p>berlakuuntuk semua orang tanpa memandang status, suku bangsa, gender, atau perbedaan lainnya </p>\n', '<p>sudah ada sejak lahir </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f16912-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26719, 738, 0, 1, 18, 'a:0:{}', NULL, NULL, '<p>Pengembangan dan pelaksanaan hak asasi manusia di Indonesia harus didasarkan pada ....</p>\n', '<p>Pancasila</p>\n', '<p>TAP MPR </p>\n', '<p>Keputusan Presiden </p>\n', '<p>Pembukaan UUD NRI Tahun 1945 Alenia Ke-3 </p>\n', '<p>Pembukaan UUD NRI Tahun 1945 Alenia Ke-1 </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547823, 1717547823, 0, '', 8, 0, 0, '71f16ae3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
