INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (26759, 738, 0, 1, 58, 'a:0:{}', NULL, NULL, '<p>Sebuah negara dapat disebut sebagai negara yang demokratis apabila di dalam pemerintahan terjadi hal-hal berikut, kecuali &hellip;. </p>\n', '<p>tidak terjadi distribusi pendapatan yang adil</p>\n', '<p>rakyat memiliki persamaan di depan hukum </p>\n', '<p>rakyat berkesempatan untuk berpartisipasi dalam pembuatan keputusan </p>\n', '<p>rakyat memperoleh pendapatan yang layak </p>\n', '<p>rakyat memiliki kebebasan yang bertanggung jawab </p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1717547823, 1717547823, 1, '', 8, 0, 0, '71f1ff8c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:27', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
