INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27007, 741, 0, 2, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Alexander Maclaren, seorang pengkhotbah berkebangsaan Inggris membuat pengelompokan terhadap sembilan buah Roh sebagai berikut:\r\n</span></div><ol><li style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nKasih, sukacita, dan damai sejahtera\r\n</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Kasabaran, kemurahan, kebaikan\r\n</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Kasih, kesabaran, kebaikan\r\n</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Kesetiaan, kelemahlembutan, dan penguasaan diri\r\n</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Kemurahan, Penguasaan diri dan damai sejahtera\r\n</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Kebaikan, Kelemahlembutan, sukacita\r\n</span></li></ol><p style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Dari keenam poin pengelompokan diatas, dua poin pengelompokan yang benar diantaranya adalah ....</span></p>', 'a:3:{s:1:\"a\";s:60:\"<p><span style=\"color: rgb(0, 0, 0);\">1 dan 2</span><br></p>\";s:1:\"b\";s:60:\"<p><span style=\"color: rgb(0, 0, 0);\">3 dan 5</span><br></p>\";s:1:\"c\";s:60:\"<p><span style=\"color: rgb(0, 0, 0);\">2 dan 4</span><br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;N;}', 1728608198, 1728608431, 1, '', 1, 0, 0, '71f29542-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
