INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27012, 741, 0, 3, 1, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Umumnya, para ahli psikologi memahami perkembangan manusia dalam enam aspek, yaitu fisik, intelektual atau kognitif, emosi, sosial, moral/spiri- tual, dan identitas diri.</p><p>Hubungkanlah masing-masing aspek tersebut dengan pengertiannya!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:7:{i:0;s:9:\"<p>#</p>\n\";i:1;s:30:\"<p>Dewasa secara fisik<br></p>\";i:2;s:33:\"<p>Dewasa secara kognitif<br></p>\";i:3;s:34:\"<p>Dewasa secara emosional<br></p>\";i:4;s:31:\"<p>Dewasa secara sosial<br></p>\";i:5;s:45:\"<p>Dewasa secara moral atau spiritual<br></p>\";i:6;s:38:\"<p>Dewasa dalam identitas diri<br></p>\";}i:1;a:7:{i:0;s:146:\"<p>Kemampuan seseorang yang dapat berinteraksi dengan orang lain (lebih muda, sebaya, dan lebih tua) tanpa memanipulasi atau dimanipulasi<br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:2;a:7:{i:0;s:94:\"<p>Tercapainya tinggi badan dan berat badan yang cocok untuk tiap tahapan usia<br></p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:3;a:7:{i:0;s:112:\"<p>Memiliki kemampuan untuk membuat keputusan yang logis dan memahami apa yamg terjadi di lingkungannya<br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:4;a:7:{i:0;s:167:\"<p>Kemampuan menyatakan emosi, baik positif maupun negatif, dengan alasan yang tepat, cara yang tepat, dalam situasi yang tepat, dan terhadap orang yang tepat<br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:5;a:7:{i:0;s:123:\"<p>Mampu menjalin hubungan dengan Tuhan dan sesama, menggunakan standar nilai yang berlaku universal dan konsisten<br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"0\";}i:6;a:7:{i:0;s:119:\"<p>Kesadaran tentang keberadaan diri, bahwa dirinya memiliki beberapa kekuatan, tetapi juga sejumlah kelemahan<br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"1\";}}}', 1728609095, 1728674508, 1, '', 1, 0, 0, '71f2a03a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27013, 750, 0, 1, 1, NULL, NULL, NULL, 'Sel merupakan unit struktural dan fungsional terkecil dari makhluk hidup. Dikatakan unit struktural terkecil dikarenakan….', 'Satuan kehidupan terkecil yang menyusun tubuh mahluk hidup', 'Sel memiliki ukuran yang sangat kecil/mikroskopik', 'Setiap sel memiliki bagian seperti halnya makhluk hidup', 'Sel mengatur pertumbuhan dan perkembangan makhluk hidup', 'Sel berperan sebagai unit pewarisan sifat dari generasi ke generasi', NULL, NULL, NULL, NULL, NULL, 'a', 1728611522, 1728615529, 1, '', 1, 0, 0, '71f2a25d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27014, 750, 0, 1, 2, NULL, NULL, NULL, '<p>Perhatikan gambar struktur sel hewan berikut ini!</p><p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241011095501.jpg\" style=\"width: 244px;\"><br></p><p>Pada gambar tersebut organel yang berfungsi untuk tempat berlangsungnya respirasi aerob ditunjukkan oleh nomor….</p>', '1, nukleus', '2, retikulum endoplasma kasar', '5, mitokondria', '6, sentriol', '3, badan golgi', NULL, NULL, NULL, NULL, NULL, 'c', 1728611634, 1728611756, 1, '', 1, 0, 0, '71f2a400-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27015, 750, 0, 1, 3, NULL, NULL, NULL, 'Yang membedakan antara sel prokaryotik dengan sel eukaryotik adalah ….', 'Sel eukaryotik tidak memiliki membran inti sel', 'Sel prokaryotik memiliki membran inti sel', 'Sel eukaryotik tidak memiliki organel bermembran', 'Sel prokaryotik tidak memiliki membran inti sel', 'Sel prokaryotik contohnya adalah sel hewan', NULL, NULL, NULL, NULL, NULL, 'd', 1728611762, 1728611871, 1, '', 1, 0, 0, '71f2a5f2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27016, 750, 0, 1, 4, NULL, NULL, NULL, '<p>Siswa SMAN 1  Kupang melakukan penelitian merendam kentang ke dalam tiga larutan yang berbeda, yaitu gula dengan konsentrasi 30%, gula dengan konsentrasi 5%, dan air murni/air suling. Terjadi perubahan berat kentang sebelum dimasukkan dan sesudah dimasukkan ke larutan masing-masing sebagaimana data berikut: </p><p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241011095914.jpg\" style=\"width: 416.5px;\"><br></p><p>Dari data tersebut kesimpulan yang tepat adalah….</p>', 'Pada gelas A, udara berdifusi dari kentang ke larutan gula karena larutan gula lebih hipertonis dari pada sel kentang', 'Pada gelas A, udara berosmosis dari kentang ke larutan gula karena larutan gula lebih hipertonis dari pada sel kentang', 'Pada gelas C, udara berdifusi dari kentang ke larutan gula disebabkan larutan gula lebih hipotonis dari pada sel kentang', '&nbsp;Pada gelas C, udara berosmosis dari kentang ke larutan gula karena larutan gula lebih hipertonis dari pada sel kentang', 'Pada gelas B, gula berdifusi dari kentang ke larutan gula disebabkan oleh larutan gula yang lebih hipotonis dari sel kentang', NULL, NULL, NULL, NULL, NULL, 'b', 1728611878, 1728612015, 1, '', 1, 0, 0, '71f2a7ca-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
