INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27077, 752, 0, 1, 16, NULL, NULL, NULL, 'Seorang siswa melakukan pengamatan perkecambahan biji kacang. Dia berpikir bahwa pemberian pupuk urea pada saat perkecambahan akan meningkatkan kecepatan perkecambahan. Untuk membuktikan hal tersebut, dia merancang percobaan dengan menggunakan 3 pot yang berbeda yang ditanami biji dengan spesies dan jumlah yang sama. Pot A ditanam dengan memberikan air biasa, pot B ditambahkan larutan pupuk urea sebesar 5%, dan pot C ditambahkan larutan pupuk ZA sebesar 5%. Kedua pot diletakkan pada tempat yang sama intensitas cahayanya. Setiap hari selama lima hari siswa tersebut melakukan pengukuran pertumbuhan tinggi batang pada kedua pot.\r\n\r\nBerdasarkan data di atas maka dapat diketahui variabel bebas, variabel terikat, dan kontrol secara berurutan dari percobaan tersebut adalah ….', 'penggunaan pupuk, tinggi tanaman, dan intensitas cahaya matahari', 'jenis pupuk, tinggi tanaman, dan intensitas cahaya matahari', 'intensitas cahaya matahari, penggunaan pupuk, dan tinggi tanaman', 'intensitas cahaya matahari, tinggi tanaman, dan jenis pupuk', 'tinggi tanaman, intensitas cahaya matahari, dan kadar pupuk yang digunakan', NULL, NULL, NULL, NULL, NULL, 'b', 1728685285, 1728685427, 1, '', 1, 0, 0, '71f31d62-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
