INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27084, 741, 0, 5, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Umumnya, para ahli psikologi memahami perkembangan manusia dalam enam aspek, yaitu fisik, intelektual atau kognitif, emosi, sosial, moral/spiritual, dan identitas diri. </span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Dari enam aspek perkembangan manusia tersebut, jelaskanlah pengertian dari dewasa secara fisik!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"text-align: justify;\">Dewasa secara fisik merujuk pada tercapainya tinggi badan dan berat badan yang cocok untuk tiap tahapan usia</span><br>', 1728685534, 1728685632, 1, '', 1, 0, 0, '71f33242-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27085, 752, 0, 1, 18, NULL, NULL, NULL, '<p>Seorang siswa melakukan pengamatan pertumbuhan suatu tanaman hias. Media tanaman tersebut ada yang diberi pupuk A, pupuk B, dan pupuk C. Selama 21 hari dilakukan pengukuran tinggi tanaman, jumlah bunga, dan kecerahan warna bunga. Hasil pengamatan ditampilkan pada tabel berikut.</p><p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241012063112.jpg\" style=\"width: 391px;\"><br></p><p>Yang menjadi variabel bebas dari penelitian tersebut adalah ….</p>', '&nbsp;macam-macam pupuk', '&nbsp;kelembaban media tanam', 'kecerahan warna bunga', 'tinggi tanaman', 'warna bunga', NULL, NULL, NULL, NULL, NULL, 'a', 1728685578, 1728685914, 1, '', 1, 0, 0, '71f33516-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27086, 741, 0, 5, 2, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Nilai-nilai Kristen merujuk pada Galatia 5:22-23: \"... Tetapi buah Roh ialah Kasih, sukacita, damai sejahtera, kesabaran, kemurahan, kebaikan, kesetiaan, kelemahlembutan, penguasaan diri. Tidak ada hukum yang menentang hal-hal itu...\".</p><p style=\"text-align: justify; \">Berdasarkan Galatia 5:22-23 tersebut, jelaskanlah pengertian dari Kemurahan!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"text-align: justify;\">Kemurahan adalah keadaan yang membuat kita rela berbagi dengan orang lain, menolong mereka yang butuh ditolong</span><br>', 1728685633, 1728685694, 1, '', 1, 0, 0, '71f33a6f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27087, 741, 0, 5, 3, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Kamus Besar Bahasa Indonesia (KBBI) mengartikan&nbsp;<span style=\"font-weight: bolder;\">Diskriminasi&nbsp;</span>sebagai pembedaan perlakuan terhadap sesama warga negara berdasarkan warna kulit, golongan, suku, ekonomi, agama, dan sebagainya.</p><p style=\"text-align: justify; \">Tuliskanlah 4 hal yang menjadi dasar beberapa pembedaan tersebut!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Beberapa pembedaan didasarkan pada hal berikut:</div><ul><li>Jenis Kelamin</li><li>Ras</li><li>Rasial</li><li>Sosial</li></ul>', 1728685695, 1728685735, 1, '', 1, 0, 0, '71f33bb4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27088, 741, 0, 5, 4, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Jelaskanlah secara singkat yang dimaksud dengan&nbsp;</span><span style=\"font-size: 0.875rem; font-weight: bolder;\">Prasangka</span><span style=\"font-size: 0.875rem;\">!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"font-weight: bolder; text-align: justify;\">Prasangka&nbsp;</span><span style=\"text-align: justify;\">merujuk pada keyakinan, pikiran, perasaan dan sikap yang dimiliki seseorang terhadap suatu kelompok</span><br>', 1728685738, 1728685798, 1, '', 1, 0, 0, '71f33f30-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27089, 741, 0, 5, 5, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Kitab Kejadian 1:1-31 menjelaskan tentang kisah penciptaan alam semesta enam hari lamanya. Kisah Kejadian ini juga ingin menunjukkan bahwa Allah bekerja secara teratur dan sistematis.&nbsp;</p><p style=\"text-align: justify;\">Dalam kisah penciptaan alam semesta, tuliskanlah hasil penciptaan pada hari kelima!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"text-align: justify;\">Pada hari kelima: Allah menciptakan semua binatang laut yang besar, dan binatang air, burung-burung yang beterbangan di udara. Juga binatang-binatang laut yang besar, binatang yang berkeriapan di dalam air</span><br>', 1728685800, 1728685827, 1, '', 1, 0, 0, '71f3409c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27090, 752, 0, 1, 19, NULL, NULL, NULL, '<p>Berikut ini grafik pertumbuhan kecambah kacang hijau hasil percobaan di tempat gelap dan terang:</p><p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241012063616.jpg\" style=\"width: 50%;\"><br></p><p>Kesimpulan dari hasil percobaan tersebut adalah ….</p>', 'pertumbuhan kecambah tidak memerlukan cahaya', 'pertumbuhan kecambah di tempat gelap lebih lambat', 'suhu memengaruhi kecepatan pertumbuhan kecambah', 'cahaya memengaruhi pertumbuhan kecambah', 'cahaya tidak memengaruhi pertumbuhan kecambah', NULL, NULL, NULL, NULL, NULL, 'd', 1728685930, 1728686234, 1, '', 1, 0, 0, '71f341d3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
