INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27226, 747, 0, 3, 1, NULL, NULL, NULL, '<p class=\"MsoQuote\" style=\"text-align: justify; \"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Keterampilan\r\npermainan adalah&nbsp;<mark class=\"QVRyCf\" style=\"padding: 0px 2px; border-radius: 4px;\">kemampuan\r\nuntuk melakukan gerakan dasar dalam olahraga dengan teknik yang efektif dan\r\nefisien untuk menghasilkan hasil yang maksimal</mark>.&nbsp;</span>Keterampilan permainan juga dapat diartikan sebagai kompetisi\r\nyang mengharuskan peserta untuk menerapkan keterampilan tertentu, dan\r\npemenangnya ditentukan berdasarkan metode kualitatif.<span class=\"uv3um\" style=\"\">&nbsp;Dari kesimpulan di atas tentukan manakah yang termasuk\r\ndalam ketrampilan sepak bola dan bola voli.&nbsp;</span><o:p></o:p></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:3:{i:0;a:9:{i:0;s:9:\"<p>#</p>\n\";i:1;s:28:\"<p>Ketrampilan mengumpan</p>\";i:2;s:25:\"<p>Ketrampilan servis</p>\";i:3;s:33:\"<p>Ketrampilan menggiring<br></p>\";i:4;s:30:\"<p>Ketrampilan passing<br></p>\";i:5;s:32:\"<p>Ketrampilan menyundul<br></p>\";i:6;s:28:\"<p>Ketrampilan smash<br></p>\";i:7;s:33:\"<p>Ketrampilan mengontrol<br></p>\";i:8;s:32:\"<p>Ketrampilan menendang<br></p>\";}i:1;a:9:{i:0;s:18:\"<p>Sepak Bola</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"0\";i:7;s:1:\"1\";i:8;s:1:\"1\";}i:2;a:9:{i:0;s:24:\"<p>Bola Voli</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"1\";i:7;s:1:\"0\";i:8;s:1:\"0\";}}}', 1728869116, 1729516811, 1, '', 1, 0, 0, '71f4dc75-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27227, 747, 0, 3, 2, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: center;\"><img src=\"http://asesmen.id/uploads/bank_soal/file_20241021213746.jpg\" style=\"width: 50%;\"><br></p><p class=\"MsoNormal\" style=\"text-align: justify; \">Menurut\r\nA. Martuti (2012;14) Bermain adalah suatu kegiatan menyenangkan dan paling\r\ndigemari oleh anak-anak pada masa prasekolah, dan sebagian waktu anak digunakan\r\nuntuk bermain sehingga para ahli berpendapat bahwa usia prasekolah adalah usia\r\nbermain. Bermain memiliki manfaat yang besar bagi perkembangan anak, dan sarana\r\nuntuk menggali pengalaman belajar yang sangat berguna untuk anak, misalnya\r\npengalaman bersosialisasi dengan teman, menambah pembendaharaan kata,\r\nmenyalurkan perasaan dalam kegiatan permainan. Untuk melakukan permainan dibutuhkan latihan yang baik dan ketrampilan yang mumpuni dari seseorang individu. Dari penjelasan di atas siswa diharapkan perlu memahami pengertian dari masing-masing-masing ketrampilan. Di bawah ini pengertian ketrampilan dari permainan sepak bola, pasangkan pengertian dibawah ini sesuai dengan pengertiannya!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:4:{i:0;a:4:{i:0;s:9:\"<p>#</p>\n\";i:1;s:182:\"<p>Penguasaan bola yang baik akan membantu sebuah tim dalam menguasai bola lebih lama dan juga dapat membuat seorang pemain menempatkan bola ke arah pemain tersebut akan bergerak</p>\";i:2;s:70:\"Berlari mendekati area gawang lawan atau untuk melewati hadangan lawan\";i:3;s:110:\"<p>Mendekati pertahanan lawan dengan kerja sama tim sehingga dapat menciptakan peluang untuk mencetak gol.</p>\";}i:1;a:4:{i:0;s:32:\"<p>Mengumpan/<i>passing</i></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:2;a:4:{i:0;s:38:\"<p>Mengontrol/menghentikan</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:3;a:4:{i:0;s:35:\"<p>Menggiring/<i>dribbling</i></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}}}', 1728869118, 1729517884, 1, '', 1, 0, 0, '71f4df49-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27228, 747, 0, 3, 3, NULL, NULL, NULL, '<div style=\"text-align: center;\"><img src=\"http://asesmen.id/uploads/bank_soal/file_20241015050408.jpg\" style=\"width: 50%;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Permainan adalah aktivitas\r\nyang dilakukan secara sungguh-sungguh, tetapi dalam melakukan permainan bukan\r\nmerupakan suatu kesungguhan. Dalam hal ini aktivitas jasmani adalah gerak\r\nmanusia itu sendiri yang berarti salah satu tanda adanya permainan adalah adanya\r\ngerak/aktivitas jasmani. Filosofi permainan di defnisikan sebagai hasil dari\r\nsejarah manusia yang turun temurun tentunya tanpa membedakan ras, kultur,\r\nsosial, agama. Permainan ditinjau melalui ilmu filsafat, ada dua analisa.\r\nYang pertama melalui tubuh filsafat yakni dalam permainan ini semua orang\r\nterlibat mulai dari usia anak-anak sampai pada orang usia lanjut. Dari penjelasan di atas pasangkan pengertian permainan bola voli sesuai dengan pengertiannya!&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:4:{i:0;a:4:{i:0;s:9:\"<p>#</p>\n\";i:1;s:104:\"<p>Pukulan bola keras di atas net ke arah lapangan lawan dengan satu tangan yang tajam dan mematikan</p>\";i:2;s:82:\"<p>Memukul bola dengan dua tangan yang disatukan dan diayun dari bawah ke atas</p>\";i:3;s:112:\"<p>Pukulan permulaan dengan satu tangan oleh pemain belakang yang dilakukan di daerah ke area lapangan lawan</p>\";}i:1;a:4:{i:0;s:29:\"<p>Servis/<i>service</i></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:2;a:4:{i:0;s:22:\"<p>Passing</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:3;a:4:{i:0;s:26:\"<p><i>Smash/spike</i></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}}}', 1728869119, 1729516900, 1, '', 1, 0, 0, '71f4e256-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27229, 747, 0, 3, 4, NULL, NULL, NULL, '<p style=\"text-align: center; \"><img src=\"http://asesmen.id/uploads/bank_soal/file_20241015050446.jpg\" style=\"width: 50%;\"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><br></span></p><p style=\"text-align: justify; \"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Keterampilan smash adalah&nbsp;</span>gerakan perpaduan fungsi otot secara tepat dan seimbang menjadi pola gerak<span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">. Setiap pemain bola voli harus menguasai teknik dasar smash dengan baik untuk mendukung penampilan keterampilannya pada saat bermain bola voli. Berdasarkan jenis umpan, <i>smash </i>dibedakan menjadi lima macam, pasangkan manakah yang termasuk <i>smash</i> dan manakah bukan termasuk <i>smash!</i></span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:3:{i:0;a:6:{i:0;s:9:\"<p>#</p>\n\";i:1;s:26:\"<p>normal <i>smash</i></p>\";i:2;s:24:\"<p>semi-<i>smash</i></p>\";i:3;s:24:\"<p><i>push smash</i></p>\";i:4;s:21:\"<p><i>felling</i></p>\";i:5;s:24:\"<p>d<i>dropshoot</i></p>\";}i:1;a:6:{i:0;s:20:\"<p><i>Smash</i></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"1\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:2;a:6:{i:0;s:26:\"<p>Bukan Smash</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"1\";}}}', 1728869121, 1729516907, 1, '', 1, 0, 0, '71f4e535-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
