INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27412, 772, 0, 5, 5, NULL, NULL, NULL, '<p>Simbol atau lambang adalah suatu tanda&nbsp; yang digunakan untuk mengartikan&nbsp; suatu hal. Dalam tradisi Katolik digunakan beberapa simbol atau lambang&nbsp; yang mempunyai makna persatuan dan keharmonisan perkawinan&nbsp; yang telah disyahkan. Apa makna dari simbol-simbol berikut?</p><p>a. bahtera</p><p>b. cinccin</p><p>c. peraduan sepasang nuri</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>a. Bahtera melambangkan kehidupan sebuah rumah tangga.</p><p>b. cincin melambangkan perkawinan yang tak tercerai-beraikan</p><p>C. peraduan sepasang nuri melambangkan cinta dan kasih sayang antara kedua pasangan yang romantis.</p>', 1728943527, 1728944475, 1, '', 1, 0, 0, '71f69412-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
