INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27419, 744, 0, 3, 2, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Umumnya, para ahli psikologi memahami perkembangan manusia dalam enam aspek, yaitu fisik, intelektual atau kognitif, emosi, sosial, moral/spiri- tual, dan identitas diri.</p><p>Hubungkanlah masing-masing aspek tersebut dengan pengertiannya!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:7:{i:0;s:9:\"<p>#</p>\n\";i:1;s:89:\"<p><span style=\"font-weight: 700; text-align: center;\">Dewasa secara fisik</span><br></p>\";i:2;s:92:\"<p><span style=\"font-weight: 700; text-align: center;\">Dewasa secara kognitif</span><br></p>\";i:3;s:93:\"<p><span style=\"font-weight: 700; text-align: center;\">Dewasa secara emosional</span><br></p>\";i:4;s:104:\"<p><span style=\"font-weight: 700; text-align: center;\">Dewasa secara moral atau spiritual</span><br></p>\";i:5;s:90:\"<p><span style=\"font-weight: 700; text-align: center;\">Dewasa secara sosial</span><br></p>\";i:6;s:97:\"<p><span style=\"font-weight: 700; text-align: center;\">Dewasa dalam identitas diri</span><br></p>\";}i:1;a:7:{i:0;s:163:\"<p><span style=\"font-weight: 700; text-align: center; font-size: 0.875rem;\">Tercapainya tinggi badan dan berat badan yang cocok untuk tiap tahapan usia</span></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:2;a:7:{i:0;s:212:\"<p><span style=\"font-weight: 700; text-align: center;\">Kemampuan seseorang yang dapat berinteraksi dengan orang lain (lebih muda, sebaya, dan lebih tua) tanpa memanipulasi atau dimanipulasi</span><br></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"0\";}i:3;a:7:{i:0;s:171:\"<p><span style=\"font-weight: 700; text-align: center;\">Memiliki kemampuan untuk membuat keputusan yang logis dan memahami apa yamg terjadi di lingkungannya</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:4;a:7:{i:0;s:226:\"<p><span style=\"font-weight: 700; text-align: center;\">Kemampuan menyatakan emosi, baik positif maupun negatif, dengan alasan yang tepat, cara yang tepat, dalam situasi yang tepat, dan terhadap orang yang tepat</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:5;a:7:{i:0;s:182:\"<p><span style=\"font-weight: 700; text-align: center;\">Mampu menjalin hubungan dengan Tuhan dan sesama, menggunakan standar nilai yang berlaku universal dan konsisten</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:6;a:7:{i:0;s:178:\"<p><span style=\"font-weight: 700; text-align: center;\">Kesadaran tentang keberadaan diri, bahwa dirinya memiliki beberapa kekuatan, tetapi juga sejumlah kelemahan</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"1\";}}}', 1728943958, 1728944352, 1, '', 1, 0, 0, '71f6a182-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:28', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
