INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27540, 766, 0, 3, 2, NULL, NULL, NULL, '<p>Ikatan kovalen adalah ikatan yang terjadi akibat pemakaian bersama pasangan elektron. Berdasarkan jumlah elektron yang dipakai bersama, ikatan kovalen dibagi menjadi tiga jenis.</p><p>Cocokkanlah beberapa contoh dibawah ini manakah yang termasuk ikatan kovalen tunggal, ikatan kovalen rangkap 2 dan ikatan kovalen rangkap 3.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:5:{i:0;a:4:{i:0;s:9:\"<p>#</p>\n\";i:1;s:29:\"<p>Ikatan kovalen Tunggal</p>\";i:2;s:31:\"<p>Ikatan Kovalen Rangkap 2</p>\";i:3;s:31:\"<p>Ikatan Kovalen Rangkap 3</p>\";}i:1;a:4:{i:0;s:11:\"<p>CO2</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:2;a:4:{i:0;s:18:\"<p>HCl</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:3;a:4:{i:0;s:10:\"<p>O2</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:4;a:4:{i:0;s:10:\"<p>N2</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}}}', 1728958288, 1729750813, 1, '', 1, 0, 0, '71f7bea8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27541, 779, 0, 1, 1, NULL, NULL, NULL, '<p>Descriptive Text of Historical Place and Tourism </p><p style=\"text-align: justify;\">Bale Kambang is a small village in the Southern coast of East Java, seventy kilometers from Malang town and two hours’ drive from South. It is well known for its long beautiful white sandy beach as well as the similarity of its temple to the one of Tanah Lot in Bali.\r\nIn Bale Kambang, there are three small rocky islands namely Ismaya Island, Wisanggeni Island, and Anoman Island, those names are taken from “wayang” figures (Java traditional puppets). These islands are surrounded by Indonesian Ocean which huge waves frighten most overseas cruisers.</p><p><span style=\"font-size: 0.875rem;\">What makes Bale Kambang famous?</span></p>', 'Small rocky islands&nbsp;', 'Long beautiful beach', 'Huge waves of ocean', 'Overseas cruisers', 'three small rocky islands', NULL, NULL, NULL, NULL, NULL, 'b', 1728958318, 1729477376, 1, '', 1, 0, 0, '71f7c254-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
