INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27561, 779, 0, 1, 5, NULL, NULL, NULL, '<p>Descriptive text about place</p><p style=\"text-align: justify; \">Kediri is a name of a town. It is situated in a valley between the Kelud and Willis mountains and inhabited by about 1.3 million people. In the Centre of the town there is a large hill which is called the Dathok Mountain. Because of the topography of the region, Kediri is called a chilly town by the locals. There is a big river called Brantas cutting off the Centre of the town. Beside the temples, Kediri is also famous for its products like cigarettes and a special kind of tofu or bean curd. This highly nutritious food is delicacy of Kediri and has a distinctive taste. The cigarettes factory dominates the town economy and employs the majority of the women labor force. Kediri and the cigarettes factory are inseparable and it is considered the biggest cigarette factory in Indonesia. Most of the local people work in this factory. <b>Those</b> who do not work here are farmers or traders.&nbsp;</p><p style=\"margin: 0in 0in 7.5pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 0.875rem;\">Those who do not work here …” (last sentence). The “those” word refers to ….&nbsp;</span><br></p>', 'The local people', 'The factory workers', 'The farmers', 'The traders', 'Woman labour force', NULL, NULL, NULL, NULL, NULL, 'a', 1728959979, 1729474263, 1, '', 1, 0, 0, '71f7f038-e8d9-11f0-a465-0a