INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27563, 766, 0, 3, 4, NULL, NULL, NULL, '<p>Suatu atom dikatakan stabil apabila memiliki konfigurasi elektron seperti gas mulia (VIIIA).</p><p>Kelompokkanlah unsur-unsur dibawah ini manakah yang <b>termasuk</b> dan<b> tidak termasuk</b> golongan VIIIA.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:8:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:15:\"<p>Termasuk</p>\";i:2;s:21:\"<p>Tidak termasuk</p>\";}i:1;a:3:{i:0;s:20:\"<p>Natrium (Na)</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:26:\"<p>Helium (He)</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:22:\"<p>magnesium (Mg)</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:17:\"<p>Neon (Ne)</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:18:\"<p>Argon (Ar)</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:6;a:3:{i:0;s:20:\"<p>Kripton (Kr)</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:7;a:3:{i:0;s:22:\"<p>Aluminium (Al)</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1728960037, 1729750828, 1, '', 1, 0, 0, '71f7f5ac-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27564, 764, 0, 1, 2, NULL, NULL, NULL, 'Hambatan listrik 9 Ohm dirangkai dengan batrei yang memiliki tegangan 6 Volt. Besar nilai kuat arus listrik yang mengalir adalah ... Ampere', '66', '6', '6,6', '0,66', '60', NULL, NULL, NULL, NULL, NULL, 'd', 1728960129, 1728960196, 1, '', 1, 0, 0, '71f7f92d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27565, 779, 0, 1, 6, NULL, NULL, NULL, '<p>Descriptive Text of Historical Place&nbsp;</p><p style=\"text-align: justify; \"> The Suramadu Bridge (Indonesian: JembatanSuramadu), also known as the Surabaya–Madura Bridge, is a bridge with three cable-stayed sections constructed between Surabaya on the island of Java and the town of Bangkalan on the island of Madura in IndonesiA. Opened on June 10, 2009, the 5.4-km bridge is the longest in Indonesia and the first bridge to cross the Madura Strait.\r\nThe cable-stayed portion has three spans with lengths 192 m, 434 m and 192 m. The bridge has two lanes in each direction plus an emergency lane and a dedicated lane for motorcycles. The first toll bridge in Indonesia, fares have been initially set at Rp. 30,000 (US$3 in 2009) for four-wheeled vehicles and Rp. 3,000 (US$0.30) for two-wheelers.\r\nThe bridge was built by a consortium of Indonesian companies PT AdhiKarya and PT WaskitaKarya working with China Road and Bridge Corp. and China Harbor Engineering Co. LtD. The total cost of the project, including connecting roads, has been estimated at 4.5 trillion rupiah (US$445 million).\r\nConstruction was started on August 20, 2003. In July 2004, a girder collapsed, killing one worker and injuring nine others. Work on the bridge halted at the end of 2004 due to lack of funds, but was restarted in November 2005. The main span of the bridge was connected on March 31, 2009, and the bridge was opened to the public in June 10, 2009.Within a week of the opening, it was discovered that nuts and bolts as well as maintenance lamps had been stolen and that there was evidence of vandalism of cables supporting the main span. </p><p>Suramadu’s bridge also known as….</p>', 'Longest bridge', 'sura and madu', 'Surabaya-Madura bridge', 'toll bridge', 'cable bridge', NULL, NULL, NULL, NULL, NULL, 'c', 1728960177, 1729474276, 1, '', 1, 0, 0, '71f7fb2f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
