INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27644, 746, 0, 2, 1, NULL, NULL, NULL, '<div><span style=\"font-weight: bolder; text-align: justify; font-size: 0.875rem;\">Berilah tanda centang pada setiap jawaban yang benar!</span><br></div><div><div class=\"mt-2\"><div class=\"mt-2\"><p style=\"text-align: justify;\">Laut Indonesia yang luasnya mencapai 5,8 juta km persegi menyimpan banyak kekayaan luar biasa, antara lain potensi sumber daya perikanan. Potensi perairan ini dapat dikembangkan untuk ketahanan pangan.</p><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Manakah yang termasuk dalam potensi perairan/kelautan yang dikembangkan untuk ketahanan pangan?</span></p></div></div></div>', 'a:5:{s:1:\"a\";s:59:\"<p>Pengembangan perikanan tangkap di perairan umum.<br></p>\";s:1:\"b\";s:34:\"<p>Budi daya bahan pangan.<br></p>\";s:1:\"c\";s:115:\"<p style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Budi daya air laut.</span></p>\";s:1:\"d\";s:31:\"<p>Budi daya air payau.<br></p>\";s:1:\"e\";s:30:\"<p>Budi daya air tawar<br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;s:1:\"e\";i:4;N;}', 1729017074, 1729017216, 1, '', 1, 0, 0, '71f8ac25-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27645, 746, 0, 2, 2, NULL, NULL, NULL, '<div><br></div><div><div class=\"mt-2\"><div class=\"mt-2\"><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Berilah tanda centang pada setiap jawaban yang benar!</span></p><p style=\"text-align: justify;\">Energi angin merupakn energi yang berasal dari alam. Terjadi angin karena adanya perbedaan tekanan udara. Perbedaan tekanan udara menyebabkan gerakan udara, dan udara yang bergerak disebut angin. Angin merupakam salah satu bentuk energi yang tersedia di alam. Secara teoritis, pembangkit listrik tenaga angin mengonversi energi angin menjadi energi listrik dengan menggunakan turbin angin atau kincir angin. Cara sederhana, yaitu energi angin memutar turbin angin, diteruskan untuk memutar motor pada generator di bagian belakang turbin angin, sehingga menghasilkan energi listrik. Energi listrik ini biasanya disimpan lebih dahulu ke dalam baterai sebelum dimanfaatkan.</p><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Berdasarkan uraian diatas, manakah yang termasuk dalam keuntungan penggunaan energi angin?&nbsp;</span></p></div></div></div>', 'a:5:{s:1:\"a\";s:85:\"<p>Pemilihan lokasi PLTA membutuhkan tenaga, biaya dan waktu yang cukup lama.<br></p>\";s:1:\"b\";s:65:\"<p>Sebagai pembangkit tenaga listrik yang cepat di dunia.<br></p>\";s:1:\"c\";s:228:\"<p style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Energi angin sebagai energi yang murah&nbsp;</span><span style=\"font-size: 0.875rem; text-align: left;\">dibandingkan energi lainnya.</span></p>\";s:1:\"d\";s:74:\"<p>Merupakan sumber energi yang ramah lingkungan dan bebas polusi.<br></p>\";s:1:\"e\";s:53:\"<p>Kondisi angin yang stabil sulit ditemukan.<br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"b\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;N;}', 1729017222, 1729017332, 1, '', 1, 0, 0, '71f8aea5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27646, 774, 0, 1, 16, NULL, NULL, NULL, '<div class=\"mt-2\"><p><img src=\"http://asesmen.id/uploads/bank_soal/file_20221007132540.png\" style=\"width: 375px;\">&nbsp;Tentukan f(4) !</p></div>', '<div>5</div>', '6', '7', '8', '9', NULL, NULL, NULL, NULL, NULL, 'c', 1729017265, 1729017379, 1, '', 1, 0, 0, '71f8b15a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27647, 746, 0, 2, 3, NULL, NULL, NULL, '<div><br></div><div><div class=\"mt-2\"><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Berilah tanda centang pada jawaban yang benar!</span><br></p><p style=\"text-align: justify;\">Survei penduduk sebenarnya memiliki pengertian sama dengan sensus. Artinya, rangkaian kegiatan survei sama dengan pelaksanaan sensus penduduk. Perbedaannya hanya terletak pada sejumlah orang yang dimintai keterangan. Pada sensus penduduk, semua orang atau semua keluarga di seluruh daerah diminta keterangan. Sebaliknya, pada survei penduduk hanya sebagian orang atau keluarga saja yang ditanya atau dimintai keterangan sebagai sampel. Survei penduduk dilakukan karena pertimbangan waktu, biaya, dan tenaga pelaksana. Pada survei penduduk, pertanyaan atau keterangan yang diminta bersifat khusus atau spesifik, seperti kelahiran, kematian, angkatan kerja, dan perpindahan penduduk., sedangkan dalam sensus penduduk, pertanyaan atau keterangan bersifat umum dan menyeluruh.</p><p style=\"text-align: justify;\">Dalam hal ini survei memiliki beberapa keunggulan yaitu</p><p style=\"text-align: justify;\">1) Pertanyaan-pertanyaannya sesuai daftar dan dijawab secara lisan</p><p style=\"text-align: justify;\">2) Pengambilan data terkonsentrasi untuk tujuan tertentu</p><p style=\"text-align: justify;\">3) Biaya lebih hemat sesuai dengan cakupan survei yang dilaksanakan</p><p style=\"text-align: justify;\">4) Pertumbuhan penduduk alami</p><p style=\"text-align: justify;\">5) Dilaksanakan oleh orang yang berbeda dan biasanya terdiri dari tenaga-tenaga yang profesional sesuai dengan sasaran masing-masing dan dilaksanakan dengan cara berbeda pula.</p><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Manakah yang termasuk keunggulan dari survei?</span></p><div><span style=\"font-weight: bolder;\"><br></span></div></div></div>', 'a:5:{s:1:\"a\";s:8:\"<p>4</p>\";s:1:\"b\";s:8:\"<p>2</p>\";s:1:\"c\";s:8:\"<p>1</p>\";s:1:\"d\";s:8:\"<p>5</p>\";s:1:\"e\";s:8:\"<p>3</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"b\";i:1;s:1:\"d\";i:2;s:1:\"e\";i:3;N;}', 1729017336, 1729017399, 1, '', 1, 0, 0, '71f8b2df-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
