INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27652, 746, 0, 2, 5, NULL, NULL, NULL, '<div class=\"mt-2\"><div class=\"mt-2\"><p style=\"text-align: justify;\">Pada tanggal 13 Desember 1957 pemerintah Indonesia menetapkan konsep wilayah perairan laut yang dikenal dengan Deklarasi Djuanda. Inti deklarasi ini adalah laut serta perairan antarpulau menjadi pemersatu dan penghubung antarpulau, dan batas – batas wilayah diukur sejauh 12 mil dari garis dasar pantai pulau terluar. Deklarasi Djuanda akhirnya mendapat pengakuan dunia pada tahun 1982 ketika diadakan Konvensi Hukum Laut Internasional di Jamaika.</p><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Tentukanlah hal – hal yang ditetapkan dalam Konvensi pada tahun 1982!</span></p></div></div>', 'a:5:{s:1:\"a\";s:77:\"<p><span style=\"font-size: 0.875rem;\">Perairan Nusantara&nbsp;</span><br></p>\";s:1:\"b\";s:69:\"<p><span style=\"font-size: 0.875rem;\">Batas Laut&nbsp;</span><br></p>\";s:1:\"c\";s:74:\"<p><span style=\"font-size: 0.875rem;\">Laut Teritorial&nbsp;</span><br></p>\";s:1:\"d\";s:80:\"<p><span style=\"font-size: 0.875rem;\">Batas Landas Kontinen&nbsp;</span><br></p>\";s:1:\"e\";s:39:\"<p>Batas Zona Ekonomi Eksklusif<br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;s:1:\"e\";i:4;N;}', 1729017597, 1729017710, 1, '', 1, 0, 0, '71f8be86-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27653, 758, 0, 1, 29, NULL, NULL, NULL, 'Alat analisis untuk mengetahui batas nilai produksi atau volume produksi suatu usaha untuk mencapai nilai impas disebut.......', 'Analisa SWOT', 'Analisa Break Even Point', 'Analisa pemasaran', 'Analisa keuangan', 'Analisa penjualan', NULL, NULL, NULL, NULL, NULL, 'b', 1729017621, 1729017820, 1, '', 1, 0, 0, '71f8c1e3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27655, 746, 0, 4, 1, NULL, NULL, NULL, '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Dalam konteks pertanian umum, Indonesia memiliki potensi yang luar biasa, yang ditunjukan oleh beberapa komoditas asal Indonesia mulai bergerak menguasai pasar dunia. Namun, dalam konteks produksi pangan, walaupun menduduki posisi ketiga sebagai negara penghasil pangan di dunia, hampir setiap tahun Indonesia masih mengimpor bahan pangan dan beberapa jenis bahan pangan lainnya. Produksi pangan Indonesia yang begitu tinggi belum bisa mencukupi kebutuhan pangan penduduknya, sehingga masih harus mengimpor dari negara lain. Oleh karena itu perlu kebijakan tentang ketahanan pangan.</span><br></div><div><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Ketahanan pangan apa yang dibutuhkan oleh Indonesia sehingga masih juga mengimpornya dari luar?</span></p></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Beras', 1729017763, 1729017787, 1, '', 1, 0, 0, '71f8c3bb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27656, 774, 0, 1, 19, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem;\">Tentukan kedudukan garis x + y = 4 terhadap lingkaran L = x</span><span style=\"position: relative; font-size: 10.5px; line-height: 0; vertical-align: baseline; top: -0.5em;\">2</span><span style=\"font-size: 0.875rem;\">&nbsp;+ y</span><span style=\"position: relative; font-size: 10.5px; line-height: 0; vertical-align: baseline; top: -0.5em;\">2</span><span style=\"font-size: 0.875rem;\">&nbsp;= 3 adalah ... lingkaran</span></div>', '<div><span style=\"font-size: 0.875rem;\">Memotong</span></div>', '<div><span style=\"font-size: 0.875rem;\">Menyinggung</span><br></div><div><span style=\"font-size: 0.875rem;\"><br></span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Tidak menyinggun</span></div>', '<span style=\"font-size: 0.875rem;\">Tidak memotong</span>', 'melewati', NULL, NULL, NULL, NULL, NULL, 'd', 1729017782, 1729017909, 1, '', 1, 0, 0, '71f8c6db-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27657, 746, 0, 4, 2, NULL, NULL, NULL, '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mesin kendaraan dapat menggunakan energi yang berasal dari tumbuhan atau lemak binatang yang masih murni, maupun yang telah dicampur dengan minyak. Energi ini dapat mengurangi polusi, dibandingkan dengan bahan bakar fosil.. Energi ini dibuat dari minyak nabati seperti minyak sawit, kelapa, jarak pagar, kapuk, dan nyamplung. Sedangkan yang lainnya dibuat dari bahan-bahan bergula atau berpati seperti tetes tebu, nira sorgum, nira nipah, singkong, ganyong, ubi jalar, dan tumbuhan lainnya.Penggunaannya sangat efektif sebagai pengganti bahan bakar solar yang tidak dapat diperbaharui. Efek samping hasil pembakaran juga relatif lebih rendah jika dibandingkan dengan penggunan solar.Menggunakan energi ini merupakan tantangan bagi pemerintah sebagai pengganti bahan bakar solar yang lama kelamaan akan habis dari bumi kita ini.</span><br></div><div><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Energi yang dimaksud dalam uraian diatas yang menyatakan energi yang berasal dari tumbuhan atau lemak binatang disebut .....</span></p></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Biodiesel', 1729017791, 1729017832, 1, '', 1, 0, 0, '71f8c8c5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27658, 758, 0, 1, 30, NULL, NULL, NULL, 'Bentuk promosi non personal dengan menggunakan berbagai media yang ditujukan untuk merangsang pembelian disebut.......', 'Periklanan', 'Personal selling', 'Publisitas', 'Promosi penjualan', 'Pemasaran langsung', NULL, NULL, NULL, NULL, NULL, 'a', 1729017825, 1729018158, 1, '', 1, 0, 0, '71f8cc12-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27659, 746, 0, 4, 3, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Batu pualam merupakan batuan hasil proses metamorfosa atau malihan dari batu gamping. Batu pualam Indonesia diperkirakan berumur sekitar 30-60 juta tahun atau berumur Kuarter hingga Tersier. Keberadaan batu pualam akan selalu berasosiasi dengan batu gamping. Persebaran batu pualm di Indonesia antara lain, Sumatra Barat, Jawa, Nusa Tenggara, dan Sulawesi. Batu pualam biasa digunakan untuk pembuatan tempat mandi, meja-meja, dinding, serta untuk seni pahat dan patung.</p><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Nama lain dari Batu Pualam adalah .....</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Marmer', 1729017849, 1729017873, 1, '', 1, 0, 0, '71f8cde5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27661, 746, 0, 4, 4, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Penggunaan dan pemanfaatan energi alternatif selain dari bahan bakar fosil perlu segera ditemukan mengingat semakin terbatasnya sumber energi tersebut. Beberapa sumber energi terbarukan yang sudah dapat dimanfaatkan antara lain adalah energi angin, air, cahaya matahari, dan pasang surut air laut. Namun dari energi alternatif itu terdapat beberapa kendala, contoh energi cahaya matahari (surya) terkendala dalam mahalnya panel surya atau solar cell dan kecilnya energi yang dihasilkan karena sifatnya yang tidak kontinu.</p><p style=\"text-align: justify;\">Energi panas bumi (geotermal) sangat berpotensi, tetapi kendalanya adalah kendala geografis. Demikian juga energi yang berasal dari angin juga sulit untuk diharapkan, karena kecepatan dan arag angin di daerah khatulistiwa tidak menentu. Energi alternatif yang menggantikan posisi energi fosil haruslah juga efisien dan ramah lingkungan, serta harus lebih murah dibandingkan dengan menggunakan listrik. Namun perlu diketahui bahwa pada dasarnya semua energi itu pasti memiliki kekurangan.</p><p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Salah satu energi alternatif yang perlu dipertimbangkan adalah .....</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ' Energi Alternatif', 1729017878, 1729017910, 1, '', 1, 0, 0, '71f8d116-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27662, 774, 0, 1, 20, NULL, NULL, NULL, '<div class=\"mt-2\"><p><img src=\"http://asesmen.id/uploads/bank_soal/file_20221007132204.png\" style=\"width: 375px;\">&nbsp;Tentukan f(0)&nbsp;</p></div>', '<div class=\"mt-2\"><p><span style=\"font-size: 0.875rem;\">-1</span></p></div>', '<div class=\"mt-2\"><p><span style=\"font-size: 0.875rem;\">1</span></p><p><br></p></div>', '<div class=\"mt-2\"><p><span style=\"font-size: 0.875rem;\">2</span></p></div>', '<div class=\"mt-2\"><p><span style=\"font-size: 0.875rem;\">3</span></p></div>', '<div class=\"mt-2\"><p><span style=\"font-size: 0.875rem;\">3</span></p></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729017914, 1729018085, 1, '', 1, 0, 0, '71f8d43d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27663, 746, 0, 4, 5, NULL, NULL, NULL, '<p><span style=\"font-size: 0.875rem; text-align: justify;\">Untuk mencukupi kebutuhan pangan maka perlu banyaknya kegiatan untuk menghasilkan pangan. Kegiatan atau proses menghasilkan, menyiapkan, mengolah, membuat, mengawetkan, mengemas, mengemas kembali, dan/atau mengubah bentuk pangan. Bahan pangan tersebut harus terjangkau oleh masyarakat. Dalam hal ini yang dimaksud terjangkau adalah keadaan di mana rumah tangga secara berkelanjutan mampu mengakses pangan sesuai dengan kebutuhan untuk hidup sehat dan produktif.&nbsp;</span></p><p><span style=\"font-size: 0.875rem; text-align: justify;\"><br></span><span style=\"font-weight: bolder; font-size: 0.875rem; text-align: justify;\">Kegiatan apa yang dimaksud dari uraian diatas?&nbsp;</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ' Produksi Pangan', 1729017928, 1729017959, 1, '', 1, 0, 0, '71f8d64f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27664, 746, 0, 5, 1, NULL, NULL, NULL, '<div class=\"mt-2\">Tuliskan 1 sampai 3 trayek tol laut yang dibuat oleh kementrian perhubungan!</div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"font-weight: bolder;\"><p>Trayek 1: Jakarta, Serui, Nabire, Wasior, Manokwari, Biak, Jakarta</p><p>Trayek 2:&nbsp;Surabaya, Tual, PakPak, Kaimana, Timika, Surabaya</p><p>Trayek 3:&nbsp;Surabaya, Tual, Dobo, Agak, Merauke, Saum, Laki, Surabaya.</p></span>', 1729017972, 1729018009, 1, '', 1, 0, 0, '71f8d969-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27666, 746, 0, 5, 2, NULL, NULL, NULL, 'Apakah yang anda ketahui dari jaringan pelayaran Nusantara kuno? Jelaskan!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div class=\"rTableCell align-top\"><div class=\"mb-2 mt-2\"><span style=\"font-weight: bolder;\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Jalur pelayaran Nusantara Kuno adalah jalur pelayaran yang dilakukan oleh Kerajaan Majapahit dan Sriwijaya untuk melakukan perdagangan antarpulau melalui jalur laut.</span></div></span></div></div><div class=\"rTableCell text-right pt-2\" style=\"width: 60px;\"><a href=\"http://asesmen.id/cbtbanksoal/buatsoal/679?no=3&amp;jns=5\" type=\"button\" class=\"btn btn-sm btn-default mb-2\"><span class=\"fas fa-pencil-alt\"></span></a>&nbsp;</div>', 1729018020, 1729018041, 1, '', 1, 0, 0, '71f8db44-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27667, 746, 0, 5, 3, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem;\">Jelaskan apa yang dimaksud dengan Jalur Sutra Kuno!</span><br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"font-weight: bolder;\">Jalur Sutra adalah nama jalur perdagangan darat yang diberikan Von Richthoven (Jerman) pada Abad 18M, yang menghubungkan Cina dengan Eropa. Sejak lama, Tiongkok dikenal sebagai penghasil kain sutra yang hasilnya diekspor ke barat, terutama melalui jalan ini, sehingga jalur perdagangan ini disebut \"jalan sutra\" (the silk road).</span><br>', 1729018056, 1729018077, 1, '', 1, 0, 0, '71f8e27d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27668, 746, 0, 5, 4, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem;\">Jelaskan secara singkat apa yang dimaksud dengan Pendulum Nusantara!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"font-weight: 700; text-align: justify;\">Pendulum Nusantara bisa juga disebut sebagai \"Tol Laut\". Tol laut adalah konektivitas laut yang efektif, berupa adanya kapal yang melayari secara rutin dan terjadwal dari barat ke timur Indonesia.</span><br>', 1729018083, 1729018139, 1, '', 1, 0, 0, '71f8e54b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
