INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27670, 746, 0, 5, 5, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem;\">Jelaskan bagaimana gagasan Jalur Sutra modern abad ke-21!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div class=\"rTableCell align-top\"><div class=\"mb-2 mt-2\"><span style=\"font-weight: bolder;\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Dewasa ini Tiongkok ingin menghidupkan kembali Jalur Sutra Modern dengan mengusulkan pembangunan Sabuk Ekonomi Jalur Sutra dan Jalur Sutra Maritim Abad ke-21. Kedua gagasan ini kemudian digabungkan menjadi satu dengan nama&nbsp;</span><i style=\"font-size: 0.875rem;\">One Belt</i><span style=\"font-size: 0.875rem;\">,&nbsp;</span><i style=\"font-size: 0.875rem;\">One Road</i><span style=\"font-size: 0.875rem;\">&nbsp;atau Satu Sabuk dan Satu Jalur. Jalur tersebut merupakan rute perdagangan, mulai dari Asia Tengah hingga Eropa dan Afrika, mulai dari Asia Tenggara hingga Jazirah Arab.</span></div></span></div></div><div class=\"rTableCell text-right pt-2\" style=\"width: 60px;\"><a href=\"http://asesmen.id/cbtbanksoal/buatsoal/679?no=2&amp;jns=5\" type=\"button\" class=\"btn btn-sm btn-default mb-2\"><span class=\"fas fa-pencil-alt\"></span></a>&nbsp;</div>', 1729018168, 1729018206, 1, '', 1, 0, 0, '71f8eea9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
