INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27698, 779, 0, 1, 14, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>Why did Ronaldo train very hard?</p>', 'Because he wanted to be rich', 'Because he wanted to be famous&nbsp;', 'Because he knew that a footballer requires good stamina&nbsp;', 'Because he wanted to break a world record', 'Because he knew before', NULL, NULL, NULL, NULL, NULL, 'c', 1729026486, 1729474353, 1, '', 1, 0, 0, '71f90ee1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27699, 779, 0, 1, 15, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nWhat makes Cristiano Ronaldo different from other players in scoring goals?</span></div>', 'He can score goals using his head', 'He can use both of his legs efficiently to make goals', 'He has good stamina', 'He has strong determination', 'He doesn\'t have good energy', NULL, NULL, NULL, NULL, NULL, 'b', 1729026490, 1729474366, 1, '', 1, 0, 0, '71f91271-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
