INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27742, 779, 0, 1, 21, NULL, NULL, NULL, '<p style=\"text-align: justify; \">The game continued scoreless up until the half time interval, but as the second half of the game started, the intensity of the game increased. In the meanwhile, I was getting nervous in the stadium because my team wasn’t exactly playing up to our expectations. In fact, my team was lucky to survive a few scoring chances from the opponent team. Then, suddenly, the ball was passed to the main “striker” of my favorite team from nowhere, and a goal was scored by my team, leaving the supporters of my team completely ecstatic and crazy with the feeling of a possible victory. And, in the end, we were indeed the victorious team.<br></p><p>The word ‘ecstatic’ in paragraph 2 has the closest meaning to …</p>', 'sad', 'angry', 'overjoyed', 'disappointed', 'happy', NULL, NULL, NULL, NULL, NULL, 'c', 1729029285, 1729474426, 1, '', 1, 0, 0, '71f94e30-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27743, 779, 0, 1, 22, NULL, NULL, NULL, '<p style=\"text-align: justify; \">The game continued scoreless up until the half time interval, but as the second half of the game started, the intensity of the game increased. In the meanwhile, I was getting nervous in the stadium because my team wasn’t exactly playing up to our expectations. In fact, my team was lucky to survive a few scoring chances from the opponent team. Then, suddenly, the ball was passed to the main “striker” of my favorite team from nowhere, and a goal was scored by my team, leaving the supporters of my team completely ecstatic and crazy with the feeling of a possible victory. And, in the end, we were indeed the victorious team.<br></p><p>“And, in the end, we were indeed the victorious team.” The word ‘we’ refers to...</p>', 'The writer and his friends', 'The writer and his team&nbsp;', 'The writer and the supporters of his favorite team&nbsp;', 'The writer and the opponent team', 'The writer and his family', NULL, NULL, NULL, NULL, NULL, 'c', 1729029288, 1729474437, 1, '', 1, 0, 0, '71f9507a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
