INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27819, 754, 0, 3, 1, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Tuhan menciptakan manusia terdiri atas laki-laki dan perempuan yang bersuku- suku dan berbangsa- bangsa untuk saling mengenal. Oleh karena itu manusia sejak awal memiliki perbedaan- perbedaan.</p><p style=\"text-align: justify;\">Salah satu perbedaan antara individu dengan individu adalah cara berinteraksi, misalnya interkasi dalam kelompok sosial. kelompok sosial terbentuk apabila di antara individu yang satu dengan individu yang lain bertemu. Pertemuan antara individu yang menghasilkan kelompok sosial haruslah berupa proses interaksi, seperti adanya kontak, komunikasi, kerja sama, akomodasi, asimilasi dan akulturasi untuk mencapai tujuan bersama, bahkan mungkin mengadakan persaingan, pertikaian, dan konflik.</p><p style=\"text-align: justify;\">Kelompok sosial merupakan bagian dari msyarakat, kelompok sosial terbentuk karena manusia yang satu dengan manusia yang lainnya saling membutuhkan, sehingga terbentuklah kelompok sosial.</p><p style=\"text-align: justify;\">Faktor -faktor pembentuk kelompok sosial, yaitu ...</p><div style=\"text-align: justify;\"><br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:80:\"<p><span style=\"font-weight: 700; text-align: center;\">kedekatan</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:87:\"<p><span style=\"font-weight: 700; text-align: center;\">kerinduan</span><br></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:79:\"<p><span style=\"font-weight: 700; text-align: center;\">kesamaan</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:80:\"<p><span style=\"font-weight: 700; text-align: center;\">keinginan</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729051616, 1729573720, 1, '', 1, 0, 0, '71f9d59f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
