INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27868, 754, 0, 3, 2, NULL, NULL, NULL, '<p>Partikularisme kelompok</p><p style=\"text-align: justify; \">Bangsa indonesia salah satu bangsa yang dikenal dengan masyarakat multikultur. Hal ini terlihat ketika bangsa kita ini dengan berbagai macam kebudayaan dan keaneka ragaman suku dari sabang sampai merauke. Hal laim yang menandakan bahwa bangsa ini memang sudah di gariskan sebagai bangsa yang ragam budaya dalah dari salah satu sila yang berbunyi <b>persatuan Indonesia</b>.</p><p style=\"text-align: justify;\">Salah satu yang menunjuka bangsa indonesia sebagai bangsa yang beragam adalah dengan adanya pembagian kelompok yang ada di masyarakat, yaitu masyarakat desa dan kota. Pada dasarnya masyarakat desa dan kota merupakan sekumpulan masyarakat ynag tinggal pada wilayah yang berbeda yang dicirikan dengan pembangunan, sistem sosial, dan kultur yang berbeda.</p><p style=\"text-align: justify;\">Eksklusivisme kelompok</p><p style=\"text-align: justify;\">Selain ada pembagian kelompok sosial dimasyarakat yaitu adanya masyarakat kota yang memiliki ciri partikular, masyarakat desa juga merupakan salah satu ciri dari karakteristik kelompok sosial yang memiliki ciri eksklusiv. Eksklusivisme kelompok adalah sebuah sikap atau keadaan adanya kecenderungan untuk memisahkan diri dari masyarakat.</p><p style=\"text-align: justify;\">salah satu contoh masyarakat ekslusif adalah masyarakat desa.</p><p style=\"text-align: justify;\">Yang termasuk ciri - ciri yang menonjol pada masyarakat kota, yaitu ...</p><div><br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:16:\"<p>Salah<br></p>\";}i:1;a:3:{i:0;s:101:\"<p><span style=\"font-weight: 700; text-align: center;\">Cenderung memikirkan keduniaan</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:125:\"<p><span style=\"text-align: center; font-size: 0.875rem;\">Hubungan kekeluargaan dilakukan secara musyawara</span></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:153:\"<p><span style=\"text-align: center;\">Pembagian kerja diantara warga - warga kota harus lebih tegas dan mempunyai batas - batas yang nyata</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:156:\"<p><span style=\"text-align: center;\">bermata pencaharian&nbsp; di bidang agraris, baik pertanian, perkebunan,&nbsp; perikanan dan peternakan</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:132:\"<p><span style=\"text-align: center;\">Pada umumnya dapat mengurus diri sendiri tanpa harus bergantung pada orang lain</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729053856, 1729752228, 1, '', 1, 0, 0, '71fa65d3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
