INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27899, 780, 0, 1, 5, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">\"Maka teranglah Tuan-tuan yang terhormat,\r\nbahwa jika kita hendak mendirikan negara Indonesia yang sesuai dengan\r\nkeistimewaan sifat corak masyarakat Indonesia, maka negara kita harus berdasar\r\natas aliran pikiran (staatsidee) negara yang integralistik ....\"<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"IN\">Di atas adalah kutipan pidato menurut ....</span></p>', '<p class=\"MsoNormal\"><span lang=\"IN\" style=\"line-height: 14.98px;\">Mr. Soepomo</span></p>', '<p class=\"MsoNormal\"><span lang=\"IN\" style=\"line-height: 14.98px;\">Ir. Soekarno</span></p>', '<div><span style=\"font-size: 0.875rem;\">Dr. Mohammad Hatta</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Ki Bagus Hadikusumo</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Mr. Mohammad Yamin</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729055744, 1729055820, 1, '', 1, 0, 0, '71faae94-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
