INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27902, 746, 0, 3, 5, NULL, NULL, NULL, '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hutan hujan tropis adalah hutan yang berada di daerah tropis, dicirikan dengan hujan yang turun sepanjang tahun, suhu dan kelembapan udara yang tinggi, serta vegetasinya berupa pohon-pohon yang tinggi disertai semak belukar dan tumbuhan merambat. Pada hutan ini produksi serasah organik tinggi.</span><br></div><div><p style=\"text-align: justify;\">Terdapat di negara manakah persebaran hutan ini berada?</p><p style=\"text-align: justify;\">Tentukanlah Benar atau Salah negara-negara yang terdapat persebaran Hutan Hujan Tropis</p></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:8:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:93:\"<p><span style=\"font-weight: 700; text-align: center;\">Indonesia dan Malaysia</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:97:\"<p><span style=\"font-weight: 700; text-align: center;\">Filipina dan Brasil</span><br></p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:87:\"<p><span style=\"font-weight: 700; text-align: center;\">Laos dan Myanmar</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:89:\"<p><span style=\"font-weight: 700; text-align: center;\">India dan Srilanka</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:92:\"<p><span style=\"font-weight: 700; text-align: center;\">Vietnam dan Argentina</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:100:\"<p><span style=\"font-weight: 700; text-align: center;\">Afrika Timur dan Afrika Barat</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:7;a:3:{i:0;s:94:\"<p><span style=\"font-weight: 700; text-align: center;\">Indonesia dan Australia</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729055938, 1729056042, 1, '', 1, 0, 0, '71fab4fb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
