INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27967, 780, 0, 1, 40, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"\">Suka memberi pertolongan\r\nkepada orang lain agar dapat berdiri sendiri merupakan butir pengamalan\r\nPancasila pada ....</span></p>', '<p><span lang=\"IN\" style=\"line-height: 14.98px;\">Sila 5</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Sila 4</span><br></p>', '<div><span style=\"font-size: 0.875rem;\">Sila 3</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Sila 2</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Sila 1</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729058698, 1729059769, 1, '', 1, 0, 0, '71fb486d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27968, 780, 0, 5, 1, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Bagaimana penerapan Pancasilan\r\ndalam konteks kehidupan berbangsa? Apakah sudah terimplementasi atau belum?<span style=\"font-size: 12pt;\"><o:p></o:p></span></span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Penerapan Pancasila dalam kehidupan\r\nberbangsa merupakan suatu upaya yang dilakukan untuk menerapkan nilai-nilai\r\nPancasila dalam perilaku. Hal ini harus sesuai dengan cita-cita dan tujuan\r\nPancasila yaitu menciptakan kehidupan yang aman dalam berbangsa dan bernegara.\r\nAkan tetapi, hingga hari ini masih belum bisa terimplementasi dengan baik\r\nkarena masih adanya tindakan intoleran terhadap perbedaan suku, ras, agama, dan\r\nlainnya.<span style=\"font-size: 12pt;\"><o:p></o:p></span></span></p>', 1729058786, 1729058822, 1, '', 1, 0, 0, '71fb4b03-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27969, 760, 0, 1, 36, NULL, NULL, NULL, 'Negara pertama yang mengatakan pengakuannya terhadap Proklamasi Kemerdekaan Indonesia adalah.....', 'Australia', 'India', 'Belanda', 'Mesir', 'Vatikan', NULL, NULL, NULL, NULL, NULL, 'd', 1729058822, 1729058947, 1, '', 1, 0, 0, '71fb4fd9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27970, 780, 0, 5, 2, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Jika sudah, sebutkan contohnya.\r\nJika belum, sebutkan hal yang menjadi tantangannya?<span style=\"font-size: 12pt;\"><o:p></o:p></span></span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Menurut saya penerapan Pancasila\r\ndalam konteks kehidupan berbangsa masih belum terimplementasi dengan baik.\r\nTantangan yang dihadapkan cukup beragam, mulai dari masih adanya tindakan\r\nintoleran, masih mementingkan kepentingan pribadi, dan lain sebagainya.<span style=\"font-size: 12pt;\"><o:p></o:p></span></span></p>', 1729058825, 1729058888, 1, '', 1, 0, 0, '71fb531d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27971, 744, 0, 4, 10, NULL, NULL, NULL, 'Dalam kesepuluh Firman, bagian&nbsp; ketiga, menyatakan jangan menyebut nama Tuhan, Allahmu, dengan sembarangan. terdapat dalam kitab......', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Keluaran 20: 7', 1729058847, 1729059214, 1, '', 1, 0, 0, '71fb55de-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27972, 754, 0, 3, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Dalam sosiologi, dinamika sosial diartikan sebagai keseluruhan perubahan dari seluruh komponen masyarakat dari waktu ke waktu. Dinamika kelompok berasal dari kata dinamika dan kelompok. keterkaitannya dengan interaksi adalah interaksi mendorong terbentuknya suatu gerak keseluruhan antara komponen masyarakat yang akhirnya menimbulkan perubahan-perubahan dalam masyarakat baik secara progresif ataupun retrogresif.</p><p style=\"text-align: justify;\">Berikut ini yang merupakan faktor pendorong dinamika sosial yang berasal dari dalam</p><div style=\"text-align: justify;\"><br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:108:\"<p><span style=\"font-weight: 700; text-align: center;\">adanya konflik antar anggota kelompok</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:119:\"<p><span style=\"font-weight: 700; text-align: center; font-size: 0.875rem;\">perubahan situasi sosial</span></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:93:\"<p><span style=\"font-weight: 700; text-align: center;\">adanya perbedaan paham</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:99:\"<p><span style=\"font-weight: 700; text-align: center;\">adanya perbedaan kepentingan</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:96:\"<p><span style=\"font-weight: 700; text-align: center;\">perubahan situasi politik</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:96:\"<p><span style=\"font-weight: 700; text-align: center;\">perubahan situasi ekonomi</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729058885, 1729573793, 1, '', 1, 0, 0, '71fb5768-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27973, 780, 0, 5, 3, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Apakah kehidupan masyarakat di\r\nsekitar telah sesuai dengan nilai-nilai Pancasila?<span style=\"font-size: 12pt;\"><o:p></o:p></span></span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Ada sebagian masyarakat yang sudah\r\nmenerapkan hidup sesuai nilai-nilai Pancasila, seperti hidup rukun dan tidak\r\nmembedakan keberagaman. Akan tetapi, di sisi lain masih ada masyarakat yang\r\nbelum menerapkan hidup sesuai nilai-nilai Pancasila, seperti masing banyaknya\r\nberita-berita yang menghasut.<span style=\"font-size: 12pt;\"><o:p></o:p></span></span></p>', 1729058891, 1729058922, 1, '', 1, 0, 0, '71fb599c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:32', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27974, 780, 0, 5, 4, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Apa saja karakter atau ciri-ciri\r\nkehidupan masyarakat yang sesuai dengan nilai-nilai Pancasila?<span style=\"font-size: 12pt;\"><o:p></o:p></span></span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p style=\"text-align: justify;\"><span lang=\"IN\" style=\"line-height: 107%;\">Karakter atau ciri-ciri kehidupan\r\nmasyarakat sesuai nilai-nilai Pancasila di antaranya:</span></p><ul><li style=\"text-align: justify;\">Menghargai perbedaan di masyarakat.</li><li style=\"text-align: justify;\">Berteman dan bergaul tanpa\r\nmembeda-bedakan ras, agama, suku, dan lain sebagainya.</li><li style=\"text-align: justify;\">Menjaga persatuan dan kesatuan\r\ndalam diri masyarakat Indonesia yang beragam.</li><li style=\"text-align: justify;\">Bergotong royong dalam menjalankan\r\nkehidupan di masyarakat.</li></ul>', 1729058925, 1729059008, 1, '', 1, 0, 0, '71fb5b25-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27975, 760, 0, 1, 37, NULL, NULL, NULL, 'Indonesia membutuhkan pengakuan dari bangsa lain secara hukum ( de jure ) untuk berdiri sebagai negara yang berdaulat. Pengakuan berdasarkan kenyataan bahwa suatu negara telah ada disebut.......', 'De facto', 'De facto bersifat sementara', 'De jure bersifat tetap', 'De jure', 'De jure bersifat penuh', NULL, NULL, NULL, NULL, NULL, 'a', 1729058981, 1729059193, 1, '', 1, 0, 0, '71fb5d41-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27976, 780, 0, 5, 5, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Untuk mewujudkan kehidupan\r\nmasyarakat yang harmonis, rukun, tertib, dan damai, selain memahami nilai-nilai\r\nPancasila dan mematuhi hukum diperlukan juga perilaku sesuai dengan norma di\r\nmasyarakat. Berikan tiga contoh perilaku sesuai hukum dan norma di masyarakat!<span style=\"font-size: 12pt;\"><o:p></o:p></span></span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"line-height: 107%;\">Perilaku sesuai\r\nnorma hukum dengan tidak melanggar hukum, misalnya berkendara dengan tertib,\r\nmenghindari penipuan dan pencurian, menghindari kekerasan atau perkelahian, dan\r\nlain-lain. Perilaku sesuai norma kesopanan misalnya sopan santun dalam\r\nberbicara, bijak dalam bermedia sosial, menghormati orang lain, dan lain-lain.</span><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;mso-fareast-language:EN-ID;\r\nmso-no-proof:no\"><o:p></o:p></span></p>', 1729059010, 1729059049, 1, '', 1, 0, 0, '71fb5ebb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27977, 760, 0, 1, 38, NULL, NULL, NULL, 'Pemimpin pemberontakan DI/TII di kalimantan selatan adalah......', 'Kahar Muzakar', 'Kartosuwiryo', 'Daud Beureueh', 'Ibnu Hajar', 'Amir Fatah', NULL, NULL, NULL, NULL, NULL, 'd', 1729059244, 1729122872, 1, '', 1, 0, 0, '71fb60d4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27978, 754, 0, 3, 5, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Tuhan menciptakan manusia terdiri atas laki-laki dan perempuan yang bersuku- suku dan berbangsa- bangsa untuk saling mengenal. Oleh karena itu manusia sejak awal memiliki perbedaan- perbedaan.</p><p style=\"text-align: justify;\">salah satu perbedaan antara individu dengan individu adalah cara berinteraksi, misalnya interkasi dalam kelompok sosial. kelompok sosial terbentuk apabila di antara individu yang satu dengan individu yang lain bertemu. Pertemuan antara individu yang menghasilkan kelompok sosial haruslah berupa proses interaksi, seperti adanya kontak, komunikasi, kerja sama, akomodasi, asimilasi dan akulturasi untuk mencapai tujuan bersama, bahkan mungkin mengadakan persaingan, pertikaian, dan konflik.</p><p style=\"text-align: justify;\">Kelompok sosial merupakan bagian dari msyarakat, kelompok sosial terbentuk karena manusia yang satu dengan manusia yang lainnya saling membutuhkan, sehingga terbentuklah kelompok sosial. Hubungan antar kelompok yang bersifat dinamis, pasti akan menciptakan suatu pola -pola hubungan antar kelompok.</p><p style=\"text-align: justify;\">Menurut referensi yang dapat menyimpulkan bahwa pola -pola hubungan antar kelompok sosial antara lain adalah ....</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:81:\"<p><span style=\"font-weight: 700; text-align: center;\">Akulturasi</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:88:\"<p><span style=\"font-weight: 700; text-align: center;\">Akulturasi</span><br></p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:84:\"<p><span style=\"font-weight: 700; text-align: center;\">Dimensi sikap</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:83:\"<p><span style=\"font-weight: 700; text-align: center;\">Paternalisme</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:86:\"<p><span style=\"font-weight: 700; text-align: center;\">Dimensi sejarah</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:80:\"<p><span style=\"font-weight: 700; text-align: center;\">Integrasi</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729059311, 1729573813, 1, '', 1, 0, 0, '71fb6229-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27979, 795, 0, 1, 1, NULL, NULL, NULL, '<p>&nbsp;Answer the question based on the following dialog from no 1 !\r\n\r\n</p><p>Deki     : Hy, Febi</p><p>\r\n\r\nFebi     : Hy, Deki .What are you doing?\r\n\r\n</p><p>Deki     : Nothing much. Which Would you like to go Timau Mountain, Ikel Stone or Nunuanah\r\n\r\nBeach?\r\n\r\n</p><p>Febi     : I would love to go to Timau mountain, but not right now after I have finished my homework.\r\n\r\n</p><p>Deki    : Ok. How about in the afternoon?\r\n\r\nFebi     : Great! When do we </p><p>want&nbsp;&nbsp; to go?\r\n\r\n</p><p>Deki    : 3 o’clock show.\r\n\r\nDeki    : Okay, see you then!\r\n\r\n</p><p>Febi    : Oke, see you.</p><p>\r\n\r\n1.       What are they talking about?</p>', 'Going to Humon mountain', 'Going to Ikel Stone', 'Going to Nunuanah Beach\r\n\r\n', 'Going to market', '      Going to home.\r\n\r\n', NULL, NULL, NULL, NULL, NULL, 'a', 1729059376, 1729677636, 1, '', 1, 0, 0, '71fb648b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27980, 781, 0, 1, 1, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Ideologi merupakan seperangkat pengetahuan, nilai, keyakinan,\r\ndan pandangan dunia yang menjadi landasan pemikiran dan tindakan seseorang atau\r\nkelompok dalam bidang politik, sosial, ekonomi, dan budaya. Dalam konteks ini,\r\nPancasila sebagai ideologi negara berfungsi untuk ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menentukan kebijakan ekonomi dan sosial di Indonesia</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Menjaga keberagaman budaya Indonesia tanpa ada panduan nilai</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menuntun pemahaman dan perilaku warga negara Indonesia terhadap dunia dan sesamanya</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Menggantikan ideologi lain yang ada di dunia</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membatasi kebebasan beragama di Indonesia</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729059933, 1729059995, 1, '', 1, 0, 0, '71fb65f9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27981, 781, 0, 1, 2, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Koento\r\nWibisono mengidentifikasi tiga unsur esensial dalam ideologi. Salah satu unsur\r\ntersebut adalah keyakinan. </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Dalam</span><span lang=\"IN\"> konteks ideologi Pancasila, keyakinan ini merujuk pada ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Kepercayaan bahwa Pancasila dapat dijadikan sumber keuntungan ekonomi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Gagasan vital yang diyakini kebenarannya sebagai dasar dan strategi mencapai tujuan nasional</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mitos bahwa Pancasila adalah ajaran paling kuno di Indonesia</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Loyalitas tanpa syarat terhadap negara Indonesia</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Keterlibatan optimal dalam kegiatan politik.</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729059997, 1729060078, 1, '', 1, 0, 0, '71fb6844-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27982, 781, 0, 1, 3, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Sebagai\r\nbagian </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">dari</span><span lang=\"IN\">\r\nunsur esensial ideologi, mitos dalam Pancasila diartikan sebagai ….</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Cerita rakyat yang diwariskan secara turun-temurun</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Ajaran optimistis bahwa Pancasila akan menjamin tercapainya tujuan melalui cara tertentu</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Dogma yang tidak dapat diubah oleh generasi berikutnya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Kumpulan ritual dan adat istiadat tradisional</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Simbol-simbol kebudayaan tanpa makna politik</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060079, 1729060146, 1, '', 1, 0, 0, '71fb6a66-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27983, 781, 0, 1, 4, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pancasila\r\nsebagai ideologi negara </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">memberikan</span><span lang=\"IN\"> pandangan dunia yang konsisten dan menyeluruh mengenai manusia,\r\nmasyarakat, budaya, ekonomi, agama, dan kekuasaan. Ini berarti Pancasila ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya berfungsi sebagai landasan budaya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya diterapkan dalam konteks politik</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Mengarahkan semua aspek kehidupan masyarakat Indonesia</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menjaga agar pemerintah tidak campur tangan dalam urusan agama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membatasi kreativitas dan inovasi masyarakat</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729060148, 1729060208, 1, '', 1, 0, 0, '71fb6c88-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27984, 781, 0, 1, 5, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"font-size: 0.875rem;\">Sebagai\r\nsalah satu ciri </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 0.875rem;\">umum</span><span lang=\"IN\" style=\"font-size: 0.875rem;\">\r\nideologi, Pancasila mengandung nilai-nilai dan tujuan yang ingin dicapai. Salah\r\nsatu nilai tersebut adalah keadilan sosial, yang berarti ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Setiap warga negara memiliki hak untuk melakukan apapun tanpa batas</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pemerintah harus memberikan bantuan keuangan kepada semua warga negara</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Setiap warga negara diperlakukan secara adil dan mendapatkan kesempatan yang sama</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Semua bentuk diskriminasi dihapuskan tanpa pengecualian</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya kelompok tertentu yang berhak atas keadilan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729060210, 1729060296, 1, '', 1, 0, 0, '71fb6ece-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27985, 781, 0, 1, 6, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">&nbsp;</span><span lang=\"IN\" style=\"font-size: 0.875rem;\">Dalam\r\nkonteks </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 0.875rem;\">Pancasila</span><span lang=\"IN\" style=\"font-size: 0.875rem;\"> sebagai ideologi negara, pengaruh pada kebijakan berarti bahwa\r\nPancasila ….</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Tidak berpengaruh pada pembentukan kebijakan public</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menjadi dasar pembentukan kebijakan yang menyangkut hajat hidup orang banyak</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengharuskan setiap kebijakan ditentukan oleh satu pihak saja</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menghapus peran rakyat dalam pengambilan keputusan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membatasi kebijakan hanya pada bidang ekonomi</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060299, 1729060368, 1, '', 1, 0, 0, '71fb70fe-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27986, 795, 0, 1, 2, NULL, NULL, NULL, '<p>Deki     : Hy,<span style=\"font-size: 0.875rem;\">Febi</span></p><p><span style=\"font-size: 0.875rem;\">\r\n\r\nFebi     : Hy, Deki . </span></p><p><span style=\"font-size: 0.875rem;\">What are you doing?\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\nDeki     : Nothing much. Which Would you like to go Timau Mountain, Ikel Stone or Nunuanah\r\n\r\nBeach?\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\nFebi     : I would love to go to Timau mountain, but not right now after I have finished my homework.\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\nDeki    : Ok. How about in the afternoon?</span></p><p><span style=\"font-size: 0.875rem;\">\r\n\r\nFebi     : Great! When do we want to go?</span></p><p><span style=\"font-size: 0.875rem;\">\r\n\r\nDeki    : 3 o’clock show.</span></p><p><span style=\"font-size: 0.875rem;\">\r\n\r\nDeki    : Okay, see you then!</span></p><p><span style=\"font-size: 0.875rem;\">\r\n\r\nFebi    : Oke, see you.\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\n\r\n  What time they will go?</span></p>', '1 o’clock', '2 o’clock', '3 o’clock', '&nbsp;4 o’clock', '5 o’clock', NULL, NULL, NULL, NULL, NULL, 'c', 1729060328, 1729677665, 1, '', 1, 0, 0, '71fb73a0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27987, 781, 0, 1, 7, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Sebagai\r\nsumber identitas dan pembeda, </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Pancasila</span><span lang=\"IN\"> ….</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Menyebabkan konflik antara berbagai kelompok etnis di Indonesia</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengharuskan semua warga negara Indonesia untuk memiliki identitas yang sama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menjadi sumber identitas nasional dan membedakan Indonesia dari negara lain</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menghapus identitas kedaerahan dan budaya local</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengarahkan semua individu untuk berpikir dan bertindak secara seragam</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729060369, 1729060443, 1, '', 1, 0, 0, '71fb775e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27988, 781, 0, 1, 8, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pancasila\r\nsebagai ideologi negara </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">juga</span><span lang=\"IN\"> berfungsi sebagai pendorong perubahan sosial. Ini berarti bahwa ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila hanya berfungsi untuk mempertahankan status quo</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menjadi landasan bagi gerakan sosial atau politik yang ingin mencapai perubahan dalam masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila tidak relevan dengan gerakan sosial atau politik</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Semua bentuk perubahan sosial harus dihindari</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Perubahan sosial hanya terjadi melalui intervensi asing</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060448, 1729060526, 1, '', 1, 0, 0, '71fb79e9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27989, 781, 0, 1, 9, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"font-size: 0.875rem;\">Indonesia\r\ntelah menetapkan visi \"Indonesia 2045, Berdaulat, Maju, Adil, dan\r\nMakmur\". </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 0.875rem;\">Dalam</span><span lang=\"IN\" style=\"font-size: 0.875rem;\">\r\nvisi ini, Pancasila ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menjadi dasar bagi negara untuk mencapai kualitas manusia yang unggul dan masyarakat yang maju</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Tidak berpengaruh terhadap pencapaian visi tersebut</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Hanya diterapkan dalam konteks kebudayaan</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengharuskan semua warga negara untuk mengikuti satu cara berpikir saja</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membatasi perkembangan teknologi dan ilmu pengetahuan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729060527, 1729060598, 1, '', 1, 0, 0, '71fb7c5f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27990, 767, 0, 1, 4, NULL, NULL, NULL, 'Pada sebuah reaksi redoks, zat mengalami oksidasi adalah ...', 'Zat yang melepaskan elektron', 'Zat yang menangkap elektron', 'Zat yang melepaskan oksigen', 'Zat yang menyebabkan zat lain teroksidasi', 'Zat Oksidator', NULL, NULL, NULL, NULL, NULL, 'a', 1729060602, 1729060892, 1, '', 1, 0, 0, '71fb7ef0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27991, 781, 0, 1, 10, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"font-size: 0.875rem;\">Sukarno\r\nmenyebut </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 0.875rem;\">Pancasila</span><span lang=\"IN\" style=\"font-size: 0.875rem;\"> sebagai \"meja statis\" dan \"leitstar dinamis\".\r\nSebagai \"leitstar dinamis\", Pancasila ….</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Tidak mampu menyesuaikan diri dengan perubahan zaman</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengarahkan bangsa Indonesia dalam merespons dan mengantisipasi tantangan-tantangan setiap zaman</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membatasi inovasi dan kreativitas dalam masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya berlaku dalam konteks sejarah masa lalu</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menghapus peran individu dalam pembangunan bangsa</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060610, 1729060686, 1, '', 1, 0, 0, '71fb80ae-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27992, 795, 0, 1, 3, NULL, NULL, NULL, '<p>Your friend should attend OSIS meeting, but he also has to pick up his brother.\r\n\r\nYour best suggestion will be....</p>', 'You should attend the meeting and forget about your brother', 'You should pick up your brother and forget about the meeting.', 'If I were you I would ask for permission for minutes to OSIS leader to pick up the brother and then back to attend the meeting', 'Why don’t you attend the meeting until finish and then pick up your brother', 'Don’t forget your brother', NULL, NULL, NULL, NULL, NULL, 'c', 1729060616, 1729677679, 1, '', 1, 0, 0, '71fb83ac-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27993, 781, 0, 1, 11, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pancasila\r\nmemiliki ciri sebagai ideologi yang </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">memberikan</span><span lang=\"IN\"> pandangan dunia secara konsisten dan menyeluruh.\r\nBagaimana implementasi dari pandangan dunia ini bisa dilihat dalam kebijakan\r\npemerintah terkait pluralitas masyarakat Indonesia yang terdiri dari berbagai\r\nmacam etnis, suku, budaya, bahasa, agama, dan kepercayaan ….</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pemerintah menerapkan satu sistem pendidikan yang sama tanpa memperhatikan keberagaman</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pemerintah mengembangkan program yang mendorong keberagaman budaya melalui pendidikan, festival, dan peraturan yang menghormati hak asasi manusia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pemerintah mewajibkan semua masyarakat untuk mengikuti satu agama yang diakui negara</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pemerintah tidak perlu campur tangan dalam urusan keberagaman budaya dan agama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pemerintah fokus hanya pada pembangunan ekonomi tanpa memperhatikan aspek sosial budaya</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060687, 1729060776, 1, '', 1, 0, 0, '71fb8524-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27994, 781, 0, 1, 12, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Koento Wibisono mengemukakan bahwa salah satu\r\nunsur esensial ideologi adalah loyalitas. Bagaimana loyalitas terhadap\r\nPancasila dapat memengaruhi partisipasi masyarakat dalam proses demokrasi di\r\nIndonesia ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Loyalitas terhadap Pancasila mengurangi partisipasi masyarakat karena ideologi tersebut mengatur segala aspek kehidupan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Loyalitas terhadap Pancasila mendorong partisipasi aktif masyarakat dalam proses demokrasi melalui penghargaan terhadap musyawarah dan mufakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Loyalitas terhadap Pancasila membuat masyarakat apatis terhadap proses demokrasi karena dianggap tidak relevan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Loyalitas terhadap Pancasila menyebabkan konflik antara kelompok masyarakat yang berbeda pandangan politik</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Loyalitas terhadap Pancasila tidak berhubungan dengan partisipasi dalam proses demokrasi</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060777, 1729060848, 1, '', 1, 0, 0, '71fb87dc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (27995, 781, 0, 1, 13, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Sebagai <span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">pendorong</span> perubahan sosial, Pancasila\r\nsering kali menjadi landasan bagi gerakan sosial atau politik. Contoh konkret\r\nyang mencerminkan peran Pancasila dalam mendorong perubahan sosial di era\r\nmodern adalah ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Penerapan sistem otoriter untuk menjaga stabilitas nasional</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pembentukan undang-undang yang mendukung hak-hak kelompok marginal dan perlindungan lingkungan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pelarangan semua bentuk protes dan demonstrasi untuk menjaga ketertiban</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Penekanan pada pembangunan infrastruktur tanpa memperhatikan aspek sosial</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pembatasan kebebasan berpendapat demi keamanan negara</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060850, 1729060918, 1, '', 1, 0, 0, '71fb8a51-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
