INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28016, 796, 0, 1, 20, NULL, NULL, NULL, '<div>Contoh tanaman pangan yang\r\ndapat dimakan bijinya adalah!<font face=\"Arial Narrow, sans-serif\"><span style=\"font-size: 14.6667px;\"><br></span></font></div>', 'Jagung, papaya, dan padi', 'Kedelai, padi, dan jagung', 'Kacang tanah, bayam, dan\r\npadi', 'Kacang hijau, jagung, dan\r\napel', 'Apel, papaya, dan bayam', NULL, NULL, NULL, NULL, NULL, 'b', 1729060914, 1729060914, 1, '', 1, 0, 0, '71fbae78-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28017, 796, 0, 3, 1, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Secara garis besar, bahan pangan dapat dikelompokkan menjadi dua yaitu bahan pangan asal tumbuhan (nabati) dan bahan pangan asal hewan (hewani). Bahan pangan nabati adalah bahan-bahan makanan yang berasal dari tanaman (bisa berupa akar, batang, dahan, daun, bunga, buah atau beberapa bagian dari tanaman bahkan keseluruhannya) atau bahan makanan yang diolah dari bahan dasar dari tanaman.  Sumber bahan nabati dapat kita produksi sendiri disekolah maupun dirumah salah satu contohnya adalah dengan berkebun hidroponik disekolah, dengan berkebun hidroponik kita dapat memperoleh bahan nabati seperti sayur dan buah yang segar dan sehat karena tidak menggunakan pestisida. Bahan pangan hewani merupakan bahan-bahan makanan yang berasal dari hewan atau olahan yang bahan dasarnya dari hasil hewan. Kedua bahan pangan ini memiliki karakteristik yang berbeda sehingga memerlukan penanganan dan pengolahan yang berbeda pula. Selanjutnya dalam hal ini yang diuraikan adalah bahan pangan hewani. </p><p>\r\n\r\nBerikut ini tentukan bahan pangan yang termasuk dalam kelompok nabati</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:8:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:6:\"Nabati\";i:2;s:6:\"Hewani\";}i:1;a:3:{i:0;s:16:\"<p>Daun ubi</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:12:\"<p>Tebu</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:12:\"<p>Asam</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:12:\"<p>Susu</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:13:\"<p>Telur</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:11:\"<p>Ubi</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:7;a:3:{i:0;s:12:\"<p>Ikan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729060914, 1729822509, 1, '', 1, 0, 0, '71fbafe3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
