INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28039, 796, 0, 2, 3, NULL, NULL, NULL, '<p>Jenis-jenis tanaman pangan\r\n</p><ol><li>Jagung\r\n</li><li>Kacang\r\n</li><li>Tomat\r\n</li><li>Pisang\r\n</li><li>Kelapa\r\n</li></ol><p>Tentukan tanaman diatas yang proses perkembangbiakan dengan biji!</p>', 'a:3:{s:1:\"a\";s:23:\"<p>Jagung dan tomat</p>\";s:1:\"b\";s:22:\"<p>Kacang dan padi</p>\";s:1:\"c\";s:21:\"<p>Ubi dan kelapa</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1729060914, 1729060914, 1, '', 1, 0, 0, '71fbd869-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28040, 796, 0, 2, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Secara garis besar, bahan pangan dapat dikelompokkan menjadi dua yaitu bahan pangan asal tumbuhan (nabati) dan bahan pangan asal hewan (hewani). Bahan pangan nabati adalah bahan-bahan makanan yang berasal dari tanaman.\r\nBerikut ini beberapa jenis bahan pangan:</p><ol><li>\r\nIkan, telur dan susu\r\n</li><li> Sayur, daun, dan pisang\r\n</li><li>Kelapa, bunga pepaya, dan daun bawang\r\n</li><li>Susu, ayam, dan telur\r\n</li></ol><p>Dari beberapa jenis pangan di atas yan termasuk dalam kelompok tumbuhan nabati adalah:</p>', 'a:3:{s:1:\"a\";s:288:\"<p class=\"MsoNormal\"><span style=\"color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Ikan, telur dan susu</span><o:p></o:p></p>\";s:1:\"b\";s:28:\"<p>Susu, ikan, dan telur</p>\";s:1:\"c\";s:32:\"<p>Sayur, kelapa, dan pisang</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1729060914, 1729822400, 1, '', 1, 0, 0, '71fbd93f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28041, 796, 0, 2, 5, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Bahan makanan yang berasal dari tanaman (bisa berupa akar, batang, dahan, daun, bunga, buah atau beberapa bagian dari tanaman bahkan keseluruhannya) atau bahan makanan yang diolah dari bahan dasar dari tanaman. Bahan pangan hewani merupakan bahan-bahan makanan yang berasal dari hewan atau olahan yang bahan dasarnya dari hasil hewan.\r\n</p><p>\r\nDari penjelasan diatas merupakan pengertian dari!</p>', 'a:4:{s:1:\"a\";s:13:\"<p>Nabati</p>\";s:1:\"b\";s:13:\"<p>Hewani</p>\";s:1:\"c\";s:26:\"<p>Pertumbuhan makanan</p>\";s:1:\"d\";s:20:\"<p>Bahan makanan</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1729060914, 1729822422, 1, '', 1, 0, 0, '71fbdb0a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28042, 781, 0, 1, 14, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Visi \"Indonesia 2045, Berdaulat, Maju,\r\nAdil, dan Makmur\" mencerminkan <span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">aspirasi</span> untuk mencapai kondisi ideal.\r\nBagaimana peran Pancasila sebagai ideologi negara dalam memastikan pencapaian\r\nvisi tersebut ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila hanya digunakan sebagai slogan tanpa implementasi nyata dalam kebijakan pemerintah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menjadi dasar pembentukan kebijakan yang mendukung pembangunan manusia unggul, pemerataan infrastruktur, dan kesejahteraan sosial</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila diterapkan secara selektif hanya pada bidang ekonomi</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Pancasila digantikan oleh ideologi baru yang lebih modern dan progresif</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila tidak relevan dengan visi Indonesia 2045</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060920, 1729060991, 1, '', 1, 0, 0, '71fbdcf4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28043, 767, 0, 1, 5, NULL, NULL, NULL, 'Manakah senyawa yang bilangan oksidasi dari unsur hidrogennya = -1 ?', 'NaH', 'H2O', 'HCl', 'HCl', 'NaOH', NULL, NULL, NULL, NULL, NULL, 'a', 1729060971, 1729061330, 1, '', 1, 0, 0, '71fbde03-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28044, 781, 0, 1, 15, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Sebagai meja statis dan leitstar dinamis, Pancasila memiliki\r\ndua fungsi utama. Dalam konteks tantangan globalisasi, bagaimana Pancasila\r\ndapat berfungsi sebagai leitstar dinamis bagi bangsa Indonesia ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila harus diabaikan karena tidak relevan dengan tantangan globalisasi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila berfungsi sebagai panduan yang fleksibel untuk merespons dinamika global tanpa kehilangan jati diri bangsa</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila hanya diterapkan dalam konteks budaya lokal dan tidak diadaptasi untuk tantangan global</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila membuat Indonesia tertutup terhadap pengaruh global</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Pancasila hanya berfungsi sebagai simbol tanpa aplikasi praktis dalam kebijakan</span></p>', NULL, NULL, NULL, NULL, NULL, 'b', 1729060992, 1729061055, 1, '', 1, 0, 0, '71fbded9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28045, 795, 0, 1, 4, NULL, NULL, NULL, 'You and Your friend have a birthday invitation from David, but your mom expects you and your friend to be at home on time to join the dinner.” Your best suggestion will be ….', 'How about going home early', 'How about go home early', ' What about go home early ', 'What if going home early', 'What about attend the birthday invitation first.', NULL, NULL, NULL, NULL, NULL, 'a', 1729061008, 1729677720, 1, '', 1, 0, 0, '71fbe455-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28046, 791, 0, 1, 14, NULL, NULL, NULL, 'Karya seni rupa yang menguraikan keberadaan rupa dengan kata-kata termasuk dalam aspek...', 'Visual', 'Proses kreasi seni', 'Konseptual', 'Kreativitas', 'Kreasi', NULL, NULL, NULL, NULL, NULL, 'a', 1729061020, 1729061137, 1, '', 1, 0, 0, '71fbe5c0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28047, 781, 0, 1, 16, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pancasila sebagai ideologi negara memberikan\r\narah <span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">dan</span>\r\ntujuan yang ingin dicapai oleh bangsa Indonesia. Dalam situasi konflik\r\nhorizontal di masyarakat, bagaimana nilai-nilai Pancasila dapat diaplikasikan\r\nuntuk meredakan konflik dan membangun harmoni ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengabaikan konflik dan membiarkan masyarakat menyelesaikannya sendiri</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menggunakan kekerasan untuk menyelesaikan konflik dengan cepat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menerapkan nilai-nilai Pancasila seperti kemanusiaan yang adil dan beradab, serta musyawarah untuk mufakat, dalam penyelesaian konflik</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melibatkan pihak asing untuk menyelesaikan konflik di dalam negeri</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menyalahkan satu pihak tanpa mendengarkan semua sudut pandang</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729061056, 1729061123, 1, '', 1, 0, 0, '71fbe6ea-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28048, 781, 0, 1, 17, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Dalam proses pembangunan nasional, Pancasila\r\nmengandung nilai keadilan sosial yang mencita-citakan masyarakat yang adil dan\r\nmakmur. <span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Bagaimana</span>\r\nimplementasi nilai ini dapat dilihat dalam kebijakan redistribusi sumber daya\r\nalam di Indonesia ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Semua sumber daya alam dikuasai oleh pemerintah tanpa memperhatikan kesejahteraan masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Sumber daya alam dimonopoli oleh perusahaan asing demi keuntungan ekonomi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Sumber daya alam dikelola untuk kepentingan bersama dengan memperhatikan keseimbangan lingkungan dan kesejahteraan masyarakat local</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pembagian sumber daya alam hanya menguntungkan kelompok tertentu</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pengelolaan sumber daya alam tidak diatur dalam konteks keadilan sosial</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729061124, 1729061205, 1, '', 1, 0, 0, '71fbe943-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
