INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28080, 797, 0, 3, 3, NULL, NULL, NULL, '<ol start=\"1\" type=\"1\">\r\n </ol><p>Perhatikan\r\n     pernyataan dibawah ini:<u1:p></u1:p><o:p></o:p></p><ol start=\"1\" type=\"1\">\r\n</ol>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;margin-left:.5in\">1)Jagung memiliki batang tunggal<u1:p></u1:p><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;margin-left:.5in\">2) Jagung memiliki batang terdiri\r\ndari buku dan ruas<u1:p></u1:p><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;margin-left:.5in\">3) Jagung memiliki bunga jantan\r\ndan betina yang bersatu<u1:p></u1:p><o:p></o:p></p>\r\n\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;margin-left:.5in\">4) Jagung dapat ditanam dilahan\r\nkering maupun lahan sawah<u1:p></u1:p><o:p></o:p></p>\r\n\r\nTentukan pernyataan yang benar dan salah sesuai jenis tanaman jagung', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:5:\"Benar\";i:2;s:5:\"Salah\";}i:1;a:3:{i:0;s:30:\"Jagung memiliki batang tunggal\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:49:\"jagung memiliki batang terdiri dari buku dan ruas\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:52:\"jagung memiliki bunga jantan dan betina yang bersatu\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:50:\"Jagung dapat di tanam di lahan kering maupun sawah\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:29:\"Jagung memiliki akar tunggang\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729061196, 1729061196, 1, '', 1, 0, 0, '71fc1b55-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28081, 797, 0, 3, 4, NULL, NULL, NULL, '<p>Perhatikan jenis sayuran dan buah-buahan dibawah ini! </p><p>\r\n\r\n1. Apel\r\n</p><p>\r\n2. Tomat </p><p>\r\n\r\n3. Mangga\r\n</p><p>\r\n4. Wortel\r\n</p><p>\r\nTentukan manakah yang termasuk dalam jenis sayur-sayuran dan buah-buahan!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:7:\"SAYURAN\";i:2;s:11:\"BUAH-BUAHAN\";}i:1;a:3:{i:0;s:4:\"Apel\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:5:\"Tomat\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:6:\"Mangga\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:6:\"Wortel\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729061196, 1729061196, 1, '', 1, 0, 0, '71fc1d6d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28082, 797, 0, 3, 5, NULL, NULL, NULL, '<p>Secara garis besar, bahan pangan dapat dikelompokkan menjadi dua yaitu bahan pangan asal tumbuhan (nabati) dan bahan pangan asal hewan (hewani). Bahan pangan nabati adalah bahan-bahan makanan yang berasal dari tanaman (bisa berupa akar, batang, dahan, daun, bunga, buah atau beberapa bagian dari tanaman bahkan keseluruhannya) atau bahan makanan yang diolah dari bahan dasar dari tanaman.  Sumber bahan nabati dapat kita produksi sendiri disekolah maupun dirumah salah satu contohnya adalah dengan berkebun hidroponik disekolah, dengan berkebun hidroponik kita dapat memperoleh bahan nabati seperti sayur dan buah yang segar dan sehat karena tidak menggunakan pestisida.\r\n\r\nBahan pangan hewani merupakan bahan-bahan makanan yang berasal dari hewan atau olahan yang bahan dasarnya dari hasil hewan. Kedua bahan pangan ini memiliki karakteristik yang berbeda sehingga memerlukan penanganan dan pengolahan yang berbeda pula. Selanjutnya dalam hal ini yang diuraikan adalah bahan pangan hewani. </p><p>\r\n\r\nDari pembahasan diatas tentukan jenis pangan Nabati dan Hewani sesuai dengan jenis kelompoknya!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:6:\"Nabati\";i:2;s:6:\"hewani\";}i:1;a:3:{i:0;s:5:\"Sayur\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:4:\"Daun\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:4:\"Susu\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:4:\"Buah\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:4:\"Ikan\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:5:\"Telur\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729061196, 1729061196, 1, '', 1, 0, 0, '71fc2092-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28083, 781, 0, 1, 18, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Salah satu tujuan didirikannya Negara Republik\r\nIndonesia adalah <span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">mewujudkan</span> masyarakat yang adil dan makmur. Bagaimana peran\r\nPancasila dalam upaya mewujudkan tujuan tersebut di tengah tantangan ekonomi\r\nglobal ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila diabaikan dalam pengambilan kebijakan ekonomi karena dianggap tidak relevan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menjadi dasar dalam merumuskan kebijakan ekonomi yang adil dan merata, serta berkelanjutan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila hanya diterapkan dalam kebijakan sosial, bukan ekonomi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menentang globalisasi sehingga menghambat perkembangan ekonomi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila tidak berperan dalam kebijakan ekonomi nasional</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729061207, 1729061265, 1, '', 1, 0, 0, '71fc22dd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28084, 781, 0, 1, 19, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Dalam\r\nkonteks sebagai leitstar dinamis, Pancasila </span><span lang=\"IN\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">harus</span><span lang=\"IN\"> mampu merespons tantangan zaman\r\nyang terus berubah. Bagaimana Pancasila dapat beradaptasi dengan perkembangan\r\nteknologi informasi dan komunikasi yang pesat ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menghambat perkembangan teknologi untuk menjaga nilai tradisional</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menjadi landasan bagi kebijakan yang mendukung pengembangan teknologi secara bertanggung jawab dan etis</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila tidak relevan dengan perkembangan teknologi modern</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila digunakan untuk membatasi akses masyarakat terhadap informasi global</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila hanya berfungsi dalam konteks budaya dan tidak terkait dengan teknologi</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729061269, 1729061331, 1, '', 1, 0, 0, '71fc2515-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28085, 795, 0, 1, 6, NULL, NULL, NULL, '<p>Tedy   : I need to download some files, but I have an unstable internet connection. \r\n</p><p>Venci    : I think you should go to the office of First Senior High School of east Amfoang, there’s a free wifi, the connection is stable.\r\n</p><p>Tedy    : ………. thanks for your suggestion.\r\n</p><p>Vency    : No problem</p>', 'Maybe some other time', 'I’m not sure about that', 'I’d better not', 'That’s a good idea', 'It’s so far from my home.', NULL, NULL, NULL, NULL, NULL, 'd', 1729061305, 1729677824, 1, '', 1, 0, 0, '71fc2757-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28086, 781, 0, 1, 20, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pancasila\r\nsebagai dasar negara telah disepakati oleh para pendiri bangsa Indonesia.\r\nBagaimana penerapan nilai-nilai Pancasila dapat membantu Indonesia menghadapi\r\nisu global seperti perubahan iklim ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila hanya mengatur kehidupan politik dan tidak terkait dengan isu lingkungan</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Pancasila menjadi dasar bagi kebijakan lingkungan yang berkelanjutan dan ramah lingkungan, dengan prinsip gotong-royong dan kesejahteraan Bersama</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila tidak relevan dalam konteks globalisasi dan perubahan iklim</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menghambat perkembangan industri demi menjaga lingkungan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila hanya diterapkan pada aspek sosial budaya, bukan lingkungan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729061336, 1729061422, 1, '', 1, 0, 0, '71fc28c9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28087, 781, 0, 1, 21, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Makna yang\r\nterkandung dalam sila pertama Pancasila, yaitu Ketuhanan Yang Maha Esa, adalah\r\n....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pengakuan atas kebebasan individu untuk memeluk agama dan kepercayaan masing-masing</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Kewajiban negara untuk mendirikan agama resmi bagi seluruh rakyat Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Larangan bagi individu untuk menjalankan ibadah sesuai dengan keyakinannya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Penekanan pada aspek ritual dan ibadah dalam kehidupan beragama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Penegakan nilai-nilai ketuhanan dalam seluruh aspek kehidupan bermasyarakat, berbangsa, dan bernegara</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'e', 1729061424, 1729061484, 1, '', 1, 0, 0, '71fc2afb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28088, 767, 0, 1, 6, NULL, NULL, NULL, 'Diantara reaksi berikut yang merupakan reaksi<b> Redoks</b> adalah ...', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016150323.jpg\" style=\"width: 234px;\"><br></p>', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016150349.jpg\" style=\"width: 212px;\"><br></p>', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016150411.jpg\" style=\"width: 318px;\"><br></p>', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016150433.jpg\" style=\"width: 334px;\"><br></p>', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016150457.jpg\" style=\"width: 355px;\"><br></p>', NULL, NULL, NULL, NULL, NULL, 'a', 1729061442, 1729062311, 1, '', 1, 0, 0, '71fc2cb9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28089, 795, 0, 1, 7, NULL, NULL, NULL, '<p>Complate the following dialogue\r\n</p><p>Student : Good morning, Sir.\r\n</p><p>\r\nTeacher : Good morning, Jack</p><p>\r\n\r\nStudent : May I bring your bag, sir?\r\n</p><p>\r\nTeacher : …………. Just help me with my Motorcycle, can you park my motorcycle?\r\n</p><p>\r\nStudent  : Very well sir.</p>', '&nbsp;Yes, I’d love to<br>', 'That would very nice<br>', 'Yes please', 'Ok thanks', '<p>No, thank you</p>', NULL, NULL, NULL, NULL, NULL, 'e', 1729061484, 1729677837, 1, '', 1, 0, 0, '71fc2ef7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28090, 781, 0, 1, 22, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Sila kedua\r\nPancasila, yaitu Kemanusiaan yang Adil dan Beradab, mengandung makna ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pengakuan atas superioritas satu kelompok manusia di atas kelompok lainnya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Penolakan terhadap perbedaan suku, agama, ras, dan golongan dalam masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Penegakan hukum yang tegas dan tanpa pandang bulu</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Perlindungan terhadap hak-hak asasi manusia tanpa terkecuali</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Penekanan pada aspek materialistik dan hedonistik dalam kehidupan manusia</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'd', 1729061486, 1729061550, 1, '', 1, 0, 0, '71fc3050-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28091, 781, 0, 1, 23, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Sila ketiga\r\nPancasila, yaitu Persatuan Indonesia, menekankan pentingnya ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Kebebasan individu untuk mengekspresikan diri tanpa batasan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Dominasi budaya dan tradisi satu suku bangsa di atas suku bangsa lainnya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Penjagaan keutuhan wilayah dan kedaulatan negara Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pembubaran organisasi-organisasi yang dianggap mengancam persatuan bangsa</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pemaksaan asimilasi budaya dan tradisi bagi seluruh rakyat Indonesia</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729061552, 1729061625, 1, '', 1, 0, 0, '71fc3272-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28092, 781, 0, 1, 24, NULL, NULL, NULL, '<p class=\"MsoNormal\"><span lang=\"IN\">Inti dari\r\nsila keempat Pancasila, yaitu Kerakyatan yang Dipimpin oleh Hikmat\r\nKebijaksanaan dalam Permusyawaratan/Perwakilan, adalah ....</span></p>', '<div><span style=\"font-size: 0.875rem;\">Kebebasan individu untuk bertindak sesuai dengan keinginannya sendiri</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Penyerahan kekuasaan sepenuhnya kepada rakyat tanpa adanya pemimpin</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Pengambilan keputusan berdasarkan suara mayoritas tanpa mempertimbangkan suara minoritas</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Penyelenggaraan pemilihan umum secara berkala untuk memilih pemimpin negara</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Musyawarah mufakat sebagai cara utama untuk mencapai mufakat dalam pengambilan keputusan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'e', 1729061628, 1729061688, 1, '', 1, 0, 0, '71fc33fd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28093, 781, 0, 1, 25, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Cita-cita\r\nyang ingin dicapai oleh bangsa Indonesia melalui pengamalan sila kelima\r\nPancasila, yaitu Keadilan Sosial bagi Seluruh Rakyat Indonesia, adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membangun masyarakat yang serba kekurangan dan tidak memiliki akses terhadap kebutuhan dasar</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Menciptakan kesenjangan sosial yang lebar antara kelompok kaya dan kelompok miskin</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mewujudkan kehidupan yang adil dan makmur bagi seluruh rakyat Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memberikan hak istimewa kepada kelompok tertentu dalam masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membiarkan rakyat Indonesia untuk hidup dalam kemiskinan dan keterbelakangan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729061693, 1729061753, 1, '', 1, 0, 0, '71fc3612-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28094, 781, 0, 1, 26, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Hubungan\r\nantara sila pertama dan sila kedua Pancasila menunjukkan bahwa ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Keberadaan Tuhan Yang Maha Esa tidak relevan dengan kehidupan bermasyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Keyakinan terhadap Tuhan Yang Maha Esa mendorong manusia untuk berperilaku adil dan beradab</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Nilai-nilai kemanusiaan yang adil dan beradab bertentangan dengan ajaran agama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Agama tidak memiliki peran dalam mewujudkan keadilan sosial bagi seluruh rakyat Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Sila pertama dan sila kedua Pancasila tidak memiliki keterkaitan satu sama lain</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729061758, 1729061819, 1, '', 1, 0, 0, '71fc375f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28095, 781, 0, 1, 27, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Hubungan\r\nantara sila ketiga dan sila keempat Pancasila menunjukkan bahwa ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia dapat dicapai dengan cara memaksakan kehendak mayoritas kepada minoritas</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Demokrasi di Indonesia harus dijalankan dengan mengedepankan musyawarah mufakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia hanya dapat dicapai dengan cara membubarkan organisasi-organisasi yang dianggap mengancam persatuan bangsa</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Demokrasi di Indonesia harus dijalankan dengan cara memberikan hak istimewa kepada kelompok tertentu dalam masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia dan demokrasi di Indonesia merupakan dua konsep yang saling bertentangan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729061822, 1729061901, 1, '', 1, 0, 0, '71fc399c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28096, 781, 0, 1, 28, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Hubungan\r\nantara sila keempat dan sila kelima Pancasila menunjukkan bahwa ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Demokrasi di Indonesia hanya dapat dijalankan dengan cara menindas kelompok minoritas</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Demokrasi di Indonesia harus dijalankan dengan tujuan untuk mewujudkan keadilan sosial bagi seluruh rakyat Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Keadilan sosial bagi seluruh rakyat Indonesia dapat dicapai dengan cara mengabaikan prinsip-prinsip demokrasi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Demokrasi di Indonesia dan keadilan sosial bagi seluruh rakyat Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Demokrasi di Indonesia sebagai cara melakukan tindak Korupsi</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729061904, 1729061967, 1, '', 1, 0, 0, '71fc3b01-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28097, 795, 0, 1, 8, NULL, NULL, NULL, '<p>Student : Good morning, Sir. </p><p>\r\nTeacher : Good morning, Jack</p><p>\r\nStudent : May I bring your bag, sir?</p><p>\r\nTeacher : …………. Just help me with my Motorcycle, can you park my motorcycle?</p><p>\r\nStudent  : Very well sir.</p>', 'Yes, I’d love too\r\n', 'That would very nice ', '.	Yes please \r\n', 'Ok thanks \r\n', 'No, thank you.\r\n', NULL, NULL, NULL, NULL, NULL, 'e', 1729061947, 1729677849, 1, '', 1, 0, 0, '71fc3d1f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28098, 781, 0, 1, 29, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Bagaimana\r\nketerkaitan antara sila pertama (Ketuhanan Yang Maha Esa) dengan sila kedua\r\n(Kemanusiaan yang Adil dan Beradab) dalam konteks kehidupan bermasyarakat di\r\nIndonesia ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Sila pertama mendorong kehidupan yang adil, sementara sila kedua menekankan pada persatuan Bangsa</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pengamalan nilai ketuhanan dalam sila pertama harus terlihat dalam sikap kasih sayang dan keadilan terhadap sesama manusia sebagaimana diatur dalam sila kedua</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Sila pertama dan kedua tidak memiliki hubungan yang signifikan karena keduanya berdiri sendiri</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Sila kedua menuntut penghormatan terhadap hak asasi manusia, sedangkan sila pertama menekankan pada pengamalan ajaran agama masing-masing tanpa saling terkait</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Sila pertama lebih berfokus pada kebebasan beragama, sedangkan sila kedua pada keadilan ekonomi</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729061972, 1729062032, 1, '', 1, 0, 0, '71fc3e71-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28099, 781, 0, 1, 30, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Dalam\r\nimplementasi sila ketiga (Persatuan Indonesia), apa saja langkah konkret yang\r\nbisa dilakukan untuk memperkuat rasa cinta tanah air di tengah keberagaman\r\nsuku, agama, dan budaya ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengadakan festival budaya daerah tanpa melibatkan komunitas lain</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membentuk komunitas eksklusif berdasarkan suku atau agama</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Melakukan kegiatan bersama yang melibatkan seluruh elemen masyarakat dengan latar belakang berbeda untuk memupuk persatuan</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menekankan penggunaan bahasa daerah di seluruh instansi pemerintahan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menghindari pembahasan isu-isu kebangsaan yang dapat menimbulkan perdebatan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729062037, 1729062105, 1, '', 1, 0, 0, '71fc41eb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28100, 781, 0, 1, 31, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Sila\r\nkeempat (Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam\r\nPermusyawaratan/Perwakilan) mengajarkan kita tentang pentingnya prinsip\r\ndemokrasi&nbsp;</span><span style=\"font-size: 0.875rem;\">dalam kehidupan berbangsa dan bernegara. Bagaimana sebaiknya prinsip ini\r\nditerapkan dalam konteks pemilihan pemimpin di sekolah ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengangkat pemimpin sekolah berdasarkan penunjukan langsung oleh guru</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melakukan pemilihan pemimpin melalui musyawarah yang melibatkan seluruh siswa untuk mencapai kesepakatan bersama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memilih pemimpin sekolah berdasarkan popularitas tanpa mempertimbangkan kompetensi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengadakan pemungutan suara tertutup hanya di kalangan guru dan staf sekolah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menetapkan pemimpin berdasarkan prestasi akademik saja</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729062108, 1729062190, 1, '', 1, 0, 0, '71fc442a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28101, 781, 0, 1, 32, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Bagaimana\r\nketerkaitan antara sila ketiga (Persatuan Indonesia) dengan sila kelima\r\n(Keadilan Sosial bagi Seluruh Rakyat Indonesia) dalam pembangunan nasional ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia hanya mementingkan kesatuan budaya, sementara keadilan sosial hanya mementingkan aspek ekonomi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia mendasari upaya bersama seluruh rakyat untuk mencapai kesejahteraan yang merata dan adil bagi semua</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Keadilan sosial hanya dapat dicapai jika tidak ada keberagaman budaya di Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia dan keadilan sosial tidak berhubungan langsung dalam pembangunan nasional</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia lebih berfokus pada aspek politik, sedangkan keadilan sosial pada aspek ekonomi</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729062191, 1729062259, 1, '', 1, 0, 0, '71fc464d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28102, 781, 0, 1, 33, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Dalam\r\nkaitannya dengan sila pertama (Ketuhanan Yang Maha Esa), bagaimana seharusnya\r\nbangsa Indonesia menerapkan nilai-nilai keagamaan dalam menjaga kelestarian\r\nlingkungan hidup ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melarang semua bentuk aktivitas ekonomi yang dapat merusak lingkungan</span></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Menggalakkan kegiatan keagamaan yang juga mengajarkan pentingnya menjaga alam ciptaan Tuhan</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengutamakan pertumbuhan ekonomi tanpa memedulikan dampak lingkungan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menyerahkan sepenuhnya urusan lingkungan kepada pemerintah tanpa melibatkan masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengadakan acara-acara religius di kawasan hutan tanpa memperhatikan dampaknya</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729062261, 1729062325, 1, '', 1, 0, 0, '71fc48b8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28103, 781, 0, 1, 34, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Di tengah\r\nmasyarakat yang majemuk, terdapat kelompok-kelompok yang memiliki keyakinan dan\r\ntradisi yang berbeda-beda. Dalam konteks sila pertama Pancasila, sikap yang\r\ntepat untuk mewujudkan toleransi dan kerukunan antarumat beragama adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memaksakan keyakinan pribadi kepada orang lain</span><br></div><div><p></p></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengadakan dialog antarumat beragama untuk saling memahami dan menghargai perbedaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melarang praktik ibadah agama tertentu yang dianggap bertentangan dengan norma sosial</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membentuk organisasi keagamaan yang ekslusif dan hanya menerima anggota dari satu agama</span><br></div>', '<div><span style=\"font-size: 0.875rem; text-align: justify;\">Mengucilkan individu atau kelompok yang berbeda keyakinan dari kehidupan sosial</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729062329, 1729062396, 1, '', 1, 0, 0, '71fc4a59-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28104, 781, 0, 1, 35, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">&nbsp;</span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Persatuan\r\nIndonesia merupakan salah satu pilar penting dalam mewujudkan cita-cita\r\nkemerdekaan bangsa. Dalam kehidupan sehari-hari, wujud nyata dari pengamalan\r\nsila ketiga Pancasila adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengikuti kegiatan gotong royong membersihkan lingkungan bersama-sama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mempelajari dan melestarikan budaya daerah lain di Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menonton pertandingan sepak bola tim nasional Indonesia dengan penuh semangat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membeli produk-produk buatan dalam negeri</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Semua jawaban benar</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'e', 1729062401, 1729062458, 1, '', 1, 0, 0, '71fc4c8f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28105, 781, 0, 1, 36, NULL, NULL, NULL, '<p class=\"MsoNormal\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Demokrasi\r\ndi Indonesia merupakan hasil perjuangan para pahlawan dan pendiri bangsa.</span></div><span lang=\"IN\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Dalam konteks sila keempat Pancasila, demokrasi yang ideal di Indonesia\r\nharuslah ....</span></div></span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Diterapkan secara langsung oleh rakyat, tanpa melibatkan perwakilan rakyat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Diberlakukan dengan sistem mayoritas absolut, di mana suara mayoritas selalu menentukan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Dilaksanakan dengan mengedepankan musyawarah mufakat untuk mencapai mufakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Diterapkan dengan sistem otoriter, di mana pemimpin memiliki kekuasaan absolut</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Dilaksanakan dengan mengedepankan kepentingan individu di atas kepentingan bersama</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729062460, 1729062519, 1, '', 1, 0, 0, '71fc4df8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28106, 767, 0, 1, 7, NULL, NULL, NULL, '<p>Perhatikan persamaan reaksi berikut.</p><p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016150926.jpg\" style=\"width: 487px;\"></p><p>Reaksi tersebut merupakan reaksi <b>autoredoks</b> karena ...</p><p><br></p>', 'HCl Mengalami reduksi dan oksidasi', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016151156.jpg\" style=\"width: 82px;\">&nbsp;mengalami reduksi sekaligus oksidasi<br></p>', 'H2O merupakan hasil reduksi dan hasil oksidasi', 'Unsur O merupakan reduktor sekaligus oksidator', 'SO2 merupakan hasil reduksi dan hasil oksidasi', NULL, NULL, NULL, NULL, NULL, 'b', 1729062499, 1729062839, 1, '', 1, 0, 0, '71fc531c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28107, 781, 0, 1, 37, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Apa yang\r\nterjadi jika salah satu sila Pancasila dihilangkan ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila tetap utuh</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Makna kesatuan Pancasila hilang</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menjadi lebih kuat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya sila yang dihilangkan yang berkurang maknanya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Tidak ada perubahan signifikan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729062520, 1729062578, 1, '', 1, 0, 0, '71fc54eb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28108, 781, 0, 1, 38, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Apa makna\r\ndari \"Ketuhanan Yang Maha Esa\" dalam konteks Pancasila ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara berdasarkan agama tertentu</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara sekuler tanpa agama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara yang menjamin kebebasan beragama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara yang tidak mempedulikan kepercayaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara yang hanya mengakui satu agama</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729062580, 1729062634, 1, '', 1, 0, 0, '71fc568c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28109, 781, 0, 1, 39, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Apa arti\r\ndari \"Kemanusiaan yang Adil dan Beradab\" ….</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Mengedepankan\r\nkepentingan pribadi</span><br></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memperlakukan semua manusia dengan martabat yang sama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengabaikan norma-norma sosial</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya berlaku untuk kelompok tertentu</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menyebarkan budaya tertentu saja</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729062638, 1729062733, 1, '', 1, 0, 0, '71fc5948-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
