INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28112, 791, 0, 1, 18, NULL, NULL, NULL, 'Karya seni rupa yang hadir sebelum zaman industry yang berarti muncul sebelum zaman modern disebut...', 'Pramodern', 'Modern', 'Konseptual', 'Postmodern', 'Kontemporer', NULL, NULL, NULL, NULL, NULL, 'a', 1729062707, 1729063091, 1, '', 1, 0, 0, '71fc5cc5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28113, 781, 0, 1, 40, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Apa tujuan\r\ndari sila \"Persatuan Indonesia\" ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mewujudkan perpecahan di antara suku dan agama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengembangkan kerukunan hidup dalam masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memisahkan berbagai budaya di Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mendorong individualisme di kalangan masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menyebarkan ideologi asing</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729062734, 1729062796, 1, '', 1, 0, 0, '71fc5e13-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28114, 781, 0, 5, 1, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Berikan\r\nargumentasi yang menjelaskan bahwa sila-sila dalam Pancasila memiliki\r\nketerkaitan!</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Mohammad Hatta dalam tulisannya berjudul Pengertian Pancasila (1977) menjelaskan bahwa sila-sila Pancasila tidak berdiri sendiri dan saling terpisah. Kelima sila tersebut membentuk satu kesatuan sebagai dasar dan ideologi negara yang makna dan penerapannya tidak bisa dipisah-pisah. Dalam konteks ini, sebagai sila pertama, Ketuhanan Yang Maha Esa hadir menjadi sila yang memimpin atau menjiwai seluruh sila-sila lainnya. Untuk itu, pengamalan sila ketuhanan dalam Pancasila tidak hanya dalam bentuk-bentuk peribadatan agama/keyakinan seseorang, tetapi lebih luas dalam bentuk sikap mengasihi sesama manusia, membangun persatuan bangsa, aktif berdemokrasi, hingga mewujudkan kesejahteraan bersama sebagaimana diajarkan dalam sila kedua sampai kelima.</span><br></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Begitu pun sebaliknya, pengamalan seseorang terhadap sila kemanusiaan, persatuan, kerakyatan, dan keadilan sosial dalam Pancasila, mesti dilihat sebagai bentuk keimanan dan ketakwaannya terhadap Tuhan Yang Maha Esa sebagaimana diajarkan oleh sila pertama.<br></span></p>', 1729062802, 1729062835, 1, '', 1, 0, 0, '71fc6002-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28115, 781, 0, 5, 2, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Jelaskan\r\nbentuk keterkaitan antara sila pertama dan sila kelima Pancasila!</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Keterkaitan antara sila pertama dan kelima melahirkan prinsip ketuhanan yang diamalkan dalam bentuk perilaku adil terhadap sesama serta berempati pada orang lain yang berada dalam kondisi kekurangan atau membutuhkan bantuan, seperti kemiskinan dan sebagainya. Sebaliknya, berbagai perilaku yang mencerminkan empati atau sikap kepedulian sosial tersebut harus dianggap sebagai bentuk perwujudan keimanaan dan ketakwaannya kepada Tuhan Yang Maha Esa.</span></p>', 1729062840, 1729062878, 1, '', 1, 0, 0, '71fc6135-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28116, 781, 0, 5, 3, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Jelaskan\r\ndan berikan contoh perilaku yang menunjukkan pengamalan Pancasila dalam\r\nkehidupan sehari-hari!</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Sebagai dasar dan ideologi negara serta pandangan hidup bangsa, Pancasila seharusnya diaktualisasikan oleh setiap individu bangsa Indonesia dalam kehidupan sehari-hari. Namun demikian, dalam realitanya seringkali hal itu sulit praktikkan. Ini membuktikan bahwa terkadang masyarakat masih mengabaikan pengamalan sila-sila Pancasila.</span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Ada beberapa contoh perilaku yang memperlihatkan bentuk pengamalan sila-sila Pancasila dalam kehidupan sehari-hari, yaitu:<o:p></o:p></span></p><ul><li style=\"text-align: justify;\"><span lang=\"IN\">Sila pertama, menghormati perbedaaan agama atau keyakinan lain<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Sila kedua, menolong masyarakat yang sedang tertimpa musibah bencana alam<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Sila ketiga, mempergunakan produk-produk buatan dalam negeri<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Sila keempat, menghargai pendapat orang lain saat berdiskusi dalam sebuah rapat<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Sila kelima, tidak melakukan tindakan yang bersifat pemborosan dan gaya hidup mewah</span></li></ul></div>', 1729062879, 1729062945, 1, '', 1, 0, 0, '71fc62e9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28117, 781, 0, 5, 4, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Mengapa\r\nPancasila berkedudukan sebagai ideologi Negara Republik Indonesia?</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pancasila berkedudukan sebagai ideologi Negara Republik Indonesia karena Pancasila merupakan orientasi yang memandu negara Indonesia untuk mencapai tujuannya, yakni merdeka, bersatu, berdaulat, adil, dan Makmur sebagaimana dinyatakan dalam Pembukaan UUD NRI Tahun 1945. Nilai-nilai ketuhanan, kemanusiaan, persatuan, musyawarah mufakat, dan keadilan sosial yang tercermin sebagai ekspresi budaya, corak perekonomian, kehidupan sosial, dan spiritualitas masyarakat yang terdapat di dalam Pancasila merupakan modal sekaligus penuntun bagi terwujudnya cita-cita tersebut.</span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Jika Pancasila sebagai ideologi negara ditinggalkan, mustahil tujuan atau cita-cita tersebut dapat terwujud. Dengan demikian, Pancasila niscaya berkedudukan sebagai Ideologi Negara Republik Indonesia.</span></p></div>', 1729062947, 1729062993, 1, '', 1, 0, 0, '71fc647e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28118, 781, 0, 5, 5, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Jelaskan\r\napa yang dimaksud dengan Pancasila sebagai Leitstar dinamis!</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pancasila sebagai Leitstar dinamis memiliki maksud bahwa Pancasila merupakan bintang penuntun yang menggerakkan dan mengarahkan bangsa Indonesia dalam merespons dan mengantisipasi tantangan-tantangan setiap zaman yang terus berubah. Pancasila mampu membuat negara Indonesia mengatasi tantangan dan tuntutan yang ada serta mampu membuat negara Indonesia adaptif terhadap tantangan zaman tanpa harus meninggalkan prinsip-prinsip yang mendasarinya dan cita-cita yang ingin dicapai olehnya. Dalam hal ini pula, Pancasila menyediakan cita-cita, kemauan, dan kemampuan untuk mewujudkannya.</span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Nilai ketuhanan mencita-citakan masyarakat yang mengejar kebajikan dan kebaikan serta dapat menjalankan ibadah tanpa hambatan. Nilai kemanusiaan mencita-citakan masyarakat yang memperlakukan sesamanya secara adil dan beradab. Nilai kebangsaan mencita-citakan masyarakat yang berwatak persatuan, gotong-royong, dan mencintai tanah air. Nilai kerakyatan/demokrasi mencita-citakan kedaulatan rakyat dengan asas permusyawaratan melalui lembaga perwakilan. Nilai keadilan sosial mencita-citakan masyarakat yang adil dan makmur.</span></p>', 1729062996, 1729063036, 1, '', 1, 0, 0, '71fc67db-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
