INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28125, 782, 0, 1, 2, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pengingkaran terhadap hak asasi manusia\r\nterkadang kita lakukan tanpa disadari. Berikut yang termasuk pelanggaran hak\r\ndalam kehidupan sehari-hari adalah ....</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Membatasi orang lain untuk beribadah</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Tidak membayar pajak atas harta kekayaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menghargai orang lain dalam beribadah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Meminta upah kerja yang terlalu tinggi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Tidak mengikuti setiap kegiatan sosial di masyarakat</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729063240, 1729063295, 1, '', 1, 0, 0, '71fc7143-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28126, 782, 0, 1, 3, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Polisi merupakan aparat penegak hukum. Mereka\r\nmemiliki tugas dan kewenangan tertentu, diantanya ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melaksanakan putusan hakim</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melakukan penuntutan di sidang pengadilan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membuat putusan pengadilan bersama hakim</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melakukan penangkapan, penahanan, penggeledahan, dan penyitaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Koordinasi dengan kejaksaan dalam upaya penegakan hukum</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'd', 1729063296, 1729063354, 1, '', 1, 0, 0, '71fc7339-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
