INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28131, 782, 0, 1, 6, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Tidak mau mematuhi dan menaati peraturan yang\r\nberlaku merupakan perilaku yang menunjukkan adanya ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pelanggaran hak</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pengingkaran hak</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Kesadaran hukum</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pengingkaran kewajiban</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Ketertiban hukum</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'd', 1729063558, 1729063615, 1, '', 1, 0, 0, '71fc78fb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28132, 782, 0, 1, 7, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Undang-Undang Dasar Negara Republik Indonesia\r\nTahun 1945 memberikan jaminan hak politik kepada warga negara. Contoh hak\r\npolitik warga negara yang terdapat dalam Undang-Undang Dasar Negara Republik\r\nIndonesia Tahun 1945 adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mendapat perlakuan baik dari pemerintah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mencalonkan diri menjadi anggota KPU</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">menjadi pegawai negeri sipil</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mengikuti pemilihan umum</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mendirikan yayasan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'd', 1729063618, 1729063676, 1, '', 1, 0, 0, '71fc7cad-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28133, 782, 0, 1, 8, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Salah satu titik fokus pasal 27 ayat (1)\r\nUndang- Undang Dasar Negara Republik Indonesia Tahun 1945 menyatakan bahwa\r\nsegala warga negara bersamaan kedudukannya di dalam hukum. Maksud pernyataan\r\ntersebut adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">warga negara yang baik akan diperlakukan baik oleh hukum</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">pemerintah memberi hukuman kepada semua warga negara</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">setiap warga negara harus diperlakukan sama di hadapan hukum</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">orang yang melanggar hukum akan masuk lembaga pemasyarakatan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">pemerintah dapat membebaskan warga negara yang baik dari hukuman</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729063680, 1729063737, 1, '', 1, 0, 0, '71fc7e1f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28134, 767, 0, 1, 10, NULL, NULL, NULL, 'Reaksi berikut yang merupakan reaksi <b>Redoks</b> adalah ...', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016152941.jpg\" style=\"width: 282px;\"><br></p>', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016153007.jpg\" style=\"width: 281px;\"><br></p>', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016153110.jpg\" style=\"width: 232px;\"><br></p>', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016153134.jpg\" style=\"width: 217px;\"><br></p>', '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241016153206.jpg\" style=\"width: 252px;\"><br></p>', NULL, NULL, NULL, NULL, NULL, 'b', 1729063690, 1729063939, 1, '', 1, 0, 0, '71fc80a2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28135, 782, 0, 1, 9, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Dalam mewujudkan persamaan di bidang ekonomi\r\npemerintah berupaya mengembangkan system ekonomi kerakyatan yang bertumpu pada\r\nmekanisme pasar, sehingga diarahkan pada ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">upaya mendorong pertumbuhan ekonomi yang melibatkan kreattifitas rakyat seperti industri rakyat yang sifatnya kecil dan menengah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mendukung usaha yang sifatnya konglomerasi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya memberi kemudahan kepada pengusaha yang masih berhubungan darah dengan para pejabat supaya mudah memantau perkembangannya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mendukung usaha koperasi yang didanai BUMN yang korporasi besar</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mendukung perusahaan skala nasional dan internasional dimana keuntungan yang dihasilkan semakin besar</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729063738, 1729063823, 1, '', 1, 0, 0, '71fc81e6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28136, 782, 0, 1, 10, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Aspek persamaan kedudukan warga negara yang\r\ndiwujudkan dalam aspek hukum yaitu ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">memiliki hak untuk mendapatkan cuti</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">kebebasan untuk memeluk agama sesuai dengan keyakinannya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">memiliki hak untuk memajukan kebudayaan daerah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">memiliki hak yang sama untuk didampingi pembela dan pemeriksaan di pengadilan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">memiliki hak untuk berkomunikasi dan memperoleh informasi</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'd', 1729063825, 1729063887, 1, '', 1, 0, 0, '71fc8445-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28137, 782, 0, 1, 11, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Undang-Undang Dasar Negara Republik Indonesia\r\nTahun 1945 menjamin hak setiap warga negara. Hak warga negara yang terdapat\r\ndalam pasal 29 ayat (2) Undang-Undang Dasar Negara Republik Indonesia Tahun\r\n1945 adalah ....</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">mendapatkan pekerjaan yang layak serta mendapat imbalan dan perlakuan yang adil</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">melaksanakan ibadah sesuai agama dan kepercayaannya masing-masing</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">memajukan diri dalam memperjuangkan haknya secara kolektif</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">memperoleh kesempatan yang sama dalam pemerintahan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">menganut berbagai macam agama yang diakui negara</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729063891, 1729063951, 1, '', 1, 0, 0, '71fc85e0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28138, 791, 0, 1, 23, NULL, NULL, NULL, 'Seni rupa yang tidak terbatas pada kebudayaan suatu adat atau daerah, namun tetap berdasarkan sebuah filosofi dan aliran-aliran seni rupa disebut...', 'Pramodern', 'Konseptual', 'Postmodern', 'Kontemporer', 'Modern', NULL, NULL, NULL, NULL, NULL, 'e', 1729063929, 1729064409, 1, '', 1, 0, 0, '71fc8984-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28139, 782, 0, 1, 12, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pemerintah memberikan jaminan pendidikan\r\nkepada semua warga negara. Hal ini merupakan bentuk keseriusan pemerintah dalam\r\nmemperhatikan dan memenuhi kebutuhan akan pemenuhan hak pendidikan warga\r\nnegara. Kasus yang menunjukkan keseriusan pemerintah dalam memenuhi hak warga\r\nnegara dalam hal pendidikan adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Kadir dan Ahmad bersekolah di sekolah yang mewah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Semua peserta didik SMK Bhakti Adi Husodo berhasil lulus Ujian Nasional</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Semua peserta didik di kelas XII Farmasi mendapat nilai bagus</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Sovia mendapat penghargaan dari pemerintah dalam bidang kalpataru</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Paula mendapat beasiswa di perguruan tinggi negeri karena memiliki nilai terbaik dalam Ujian Nasional</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'e', 1729063979, 1729064039, 1, '', 1, 0, 0, '71fc8ad0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28140, 782, 0, 1, 13, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Faktor-faktor integratif bangsa sebagai\r\nperekat persatuan adalah ....</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">patriotisme</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">UUD NRI Tahun 1945</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">cinta tanah air</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">rela berkorban untuk kepentingan bangsa dan negara</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">tidak kenal menyerah</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1729064043, 1729064111, 1, '', 1, 0, 0, '71fc8c2f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28141, 782, 0, 1, 14, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pasal 1 ayat (1) UUD Negara Republik Indonesia\r\nTahun 1945 yang merupakan naskah asli mengandung prinsip bahwa ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">\"Negara Indonesia ialah negara kesatuan, yang berbentuk Republik.”</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">“Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-undang Dasar\"</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">“Negara Indonesia adalah negara hukum”</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">“Lagu Kebangsaan ialah Indonesia Raya”</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">“Lambang Negara ialah Garuda Pancasila dengan semboyan Bhineka Tunggal Ika”</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729064113, 1729064175, 1, '', 1, 0, 0, '71fc8e54-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28142, 782, 0, 1, 15, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Prinsip kesatuan dalam Negara Kesatuan\r\nRepublik Indonesia dipertegas dalam Pembukaan UUD Negara Republik Indonesia\r\nTahun 1945 yaitu ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">“…. dalam upaya membentuk suatu Pemerintahan negara Indonesia yang melindungi segenap bangsa Indonesia dan seluruh tumpah darah Indonesia”</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">“.... memajukan kesejahteraan umum, mencerdaskan kehidupan bangsa”</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">“.... ikut melaksanakan ketertiban dunia yang berdasarkan kemerdekaan\"</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">“.... perdamaian abadi dan keadilan sosial”</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">“.... berkehidupan kebangsaan yang bebas</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729064179, 1729064242, 1, '', 1, 0, 0, '71fc8fbc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28143, 782, 0, 1, 16, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Adapun faktor-faktor yang berpotensi\r\nmenghambat persatuan dan kesatuan bangsa Indonesia di antaranya ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">kebhinnekaan/keberagaman pada masyarakat Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">bhinneka Tunggal Ika</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">sumpah pemuda</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">pancasila</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">UUD NRI 1945</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729064244, 1729064304, 1, '', 1, 0, 0, '71fc91b7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28144, 782, 0, 1, 17, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Yang bukan merupakan faktor pendukung\r\nintegrasi nasional adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Adanya rasa senasib sepenanggungan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Adanya semangat persatuan dan kesatuan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Adanya kepribadian dan pandangan hidup yang sama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Adanya jiwa dan semangat gotong royong, toleransi yang kuat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Adanya ketidak puasan terhadap ketimpangan pemerataan hasil pembangunan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'e', 1729064306, 1729064369, 1, '', 1, 0, 0, '71fc92e6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28145, 782, 0, 1, 18, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Contoh nilai patriotism dalam hidup berbangsa\r\ndan bernegara dalam bidang hankamnas yaitu&nbsp;\r\n….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">rela berkorban untuk mengamankan wilayah negara</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mengorbankan jiwa raga dalam menghadapi musuh</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">membantu TNI/Polri untuk memberantas kejahatan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">berjuang untuk meraih cita-cita masa depan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">memberikan harta benda demi bangsa dan negara</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729064370, 1729064428, 1, '', 1, 0, 0, '71fc94f4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28146, 782, 0, 1, 19, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Berikut ini adalah contoh sikap yang\r\nmencerminkan komitmen persatuan dalam kehidupan di sekolah yaitu ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengadakan bakti sosial</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Tidak membedakan SARA</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Ikut serta dalam kegiatan kerjabakti</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Meningkatkan semangat Bhinneka Tunggal Ika</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Tidak membedakan teman dalam bergaul di kelas</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'e', 1729064429, 1729064487, 1, '', 1, 0, 0, '71fc9666-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28147, 782, 0, 1, 20, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Setiap warga negara mempunyai hak yang dijamin\r\ndalam Undang-Undang Dasar Negara Republik Indonesia Tahun 1945. Contoh hak yang\r\ndiatur secara eksplisit dalam pasal 31 Undang-Undang Dasar Negara Republik Indonesia\r\nTahun 1945 adalah ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">memperoleh pendidikan</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">menjadi anggota legislatif</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mendapat kesejahteraan sosial</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mempelajari berbagai kebudayaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mempunyai hak pilih dalam pemilihan umum</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729064489, 1729064546, 1, '', 1, 0, 0, '71fc9892-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28148, 782, 0, 1, 21, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Undang-Undang Dasar Negara Republik Indonesia\r\nTahun 1945 memberikan jaminan hak politik kepada warga negara. Contoh hak\r\npolitik warga negara yang terdapat dalam Undang-Undang Dasar Negara Republik\r\nIndonesia Tahun 1945 adalah ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mendapat perlakuan baik dari pemerintah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mencalonkan diri menjadi anggota KPU</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">menjadi pegawai negeri sipil</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mengikuti pemilihan umum</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">mendirikan yayasan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'd', 1729064548, 1729064608, 1, '', 1, 0, 0, '71fc99d7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
