INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28170, 782, 0, 1, 36, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Dalam penegakan hukum Indonesia dibantu oleh\r\nsalah satu komisi yaitu Komisi Pemberantas Korupsi (KPK). Pelaksanaan tugas KPK\r\nini didasari oleh undang-undang .…</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">UU RI No. 30 Tahun 2002</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">UU RI No. 50 Tahun 2003</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">UU RI No. 70 Tahun 2002</span><br></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">UU RI No. 20 Tahun 2004</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">UU RI No. 40 Tahun 2022</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729065473, 1729065535, 1, '', 1, 0, 0, '71fcc1dc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28171, 782, 0, 1, 37, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Kewenangan yang dimiliki pihak kepolisian dalam\r\nmenjalankan tugasnya antara lain adalah .…</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Berhak melakukan 4P (Penangkapan, Penggeledahan, Penyitaan dan juga Penahanan)</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melakukan pemutusan sidang</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menentukan hukuman yang didapatkan oleh pelanggar hukum</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memberikan pembelaan kepada tersangka yang belum ditetapkan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Tidak menerima laporan kejahatan dan lain sebagainya saat malam hari</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729065536, 1729065597, 1, '', 1, 0, 0, '71fcc477-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28172, 782, 0, 1, 38, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Pembatasan terhadap kemerdekaan mutlak pers\r\nitu justru perlu diadakan dengan alasan sebagai berikut, kecuali ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">untuk melindungi kehormatan dan nama baik individu maupun kelompok</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">melindungi nilai-nilai yang berlaku dalam masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">meningkatkan ancaman subversi maupun agresi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">melindungi ketertiban keamanan, baik yang datang dari dalam mapun datang dari luar</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">melindungi keamanan, baik yang datang dari dalam maupun datang dari luar</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729065601, 1729065673, 1, '', 1, 0, 0, '71fcc6cd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28173, 791, 0, 1, 29, NULL, NULL, NULL, 'Prinsip atau kaidah-kaidah umum yang digunakan dengan menempatkan unsur-unsur fisik diebut unsur ….. ', 'Non fisik', 'Seni rupa', 'Visual', 'Seni&nbsp; kriya', 'Karya seni', NULL, NULL, NULL, NULL, NULL, 'a', 1729065608, 1729065773, 1, '', 1, 0, 0, '71fcc984-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28174, 791, 0, 1, 30, NULL, NULL, NULL, 'Dibawah ini yang bukan merupakan cabang-cabang seni adalah...', 'Tari', 'suara', 'Rupa', 'Bela diri', 'Peran', NULL, NULL, NULL, NULL, NULL, 'd', 1729065612, 1729066393, 1, '', 1, 0, 0, '71fccb04-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28175, 782, 0, 1, 39, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Setelah berperan serta dalam upaya\r\nmengembangkan kesadaran nasional untuk memperjuangkan kemerdekaan massa\r\nsebelumnya, pers nasional menunjukkan tanggung jawab sosialnya sebagai bagian\r\ndari negara baru yang berdaulat, tidak mengherankan jika pers pada masa itu\r\ndisebut ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">sebagai pers modern</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">pers pemberani</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">sebagai pers pejuang</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">pers pers dalam alam kemerdekaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">pers Pancasila</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1729065674, 1729065738, 1, '', 1, 0, 0, '71fccc63-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28176, 782, 0, 1, 40, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Bagi kita, semua bentuk kemajuan teknologi\r\ntermasuk teknologi komunikasi dan informasi, kita sikapi ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">dengan senang sebagai sarana untuk meningkatkan kesejahteraan hidup</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">biasa, karena yang meamjukan teknologi bukan bangsa Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">dengan bangga, karena semua kemajuan itu dicapai atas nama kemanusiaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">rasa syukur dan kita manfaatkan untuk kemajuan dan kesejahteraan hidup</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">dengan sedih dan kecewa, karena tidak dikembangkan oleh bangsa kita</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'a', 1729065739, 1729065793, 1, '', 1, 0, 0, '71fccec3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28177, 782, 0, 5, 1, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Jelaskan\r\nkonsep hak asasi, hak warga negara, kewajiban asasi, dan kewajiban warga\r\nnegara. Uraikan perbedaan dan persamaan konsep-konsep tersebut!</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Konsep Hak Asasi: Hak asasi adalah hak-hak yang melekat pada setiap individu secara universal dan inheren sebagai manusia. Hak asasi meliputi hak-hak dasar seperti hak untuk hidup, kebebasan berpendapat, kebebasan beragama, dan hak untuk tidak disiksa. Hak asasi diberikan tanpa pandang bulu dan harus dihormati oleh pemerintah dan masyarakat.</span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Konsep Hak Warga Negara: Hak warga negara adalah hak-hak yang dimiliki oleh individu sebagai anggota suatu negara atau kewarganegaraan. Ini termasuk hak untuk memilih, hak untuk mendapat perlindungan hukum, dan hak untuk memperoleh layanan publik.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Konsep Kewajiban Asasi: Kewajiban asasi adalah tanggung jawab moral yang melekat pada individu sebagai manusia. Ini mencakup kewajiban untuk menghormati hak-hak orang lain dan tindakan yang sesuai dengan nilai-nilai etika dan moral.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Konsep Kewajiban Warga Negara: Kewajiban warga negara adalah tanggung jawab hukum yang harus dipatuhi oleh individu sebagai warga negara suatu negara. Ini mencakup kewajiban untuk membayar pajak, mematuhi hukum, dan memenuhi&nbsp;<a href=\"https://pontianak.tribunnews.com/tag/tugas\" title=\"tugas\">tugas</a>-tugas sipil seperti pemilihan umum.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Perbedaan: Hak asasi dan kewajiban asasi adalah konsep moral yang bersifat universal, sedangkan hak warga negara dan kewajiban warga negara berkaitan dengan status hukum individu dalam suatu negara tertentu. Hak asasi dan hak warga negara dapat bersinggungan, tetapi hak warga negara lebih terbatas pada hak-hak yang diberikan oleh negara. Kewajiban asasi adalah tanggung jawab moral, sementara kewajiban warga negara adalah kewajiban hukum.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Persamaan: Persamaan antara konsep-konsep ini adalah bahwa mereka semua berkaitan dengan hak-hak dan tanggung jawab individu dalam masyarakat. Mereka juga mencerminkan nilai-nilai dasar tentang martabat manusia dan hubungan antara individu dan negara.</span></p></div>', 1729065810, 1729065842, 1, '', 1, 0, 0, '71fcd147-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28178, 782, 0, 5, 2, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Kemukakan\r\nhak dan kewajiban warga negara yang terdapat dalam UUD NRI Tahun 1945!</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><b>Hak dan Kewajiban Warga Negara dalam UUD NRI Tahun 1945:</b></span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Beberapa hak warga negara yang dijamin oleh UUD NRI Tahun 1945 antara lain:<o:p></o:p></span></p><ul><li style=\"text-align: justify;\"><span lang=\"IN\">Hak untuk berpendapat dan berpendapat (Pasal 28E).<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Hak atas kebebasan berserikat dan berkumpul (Pasal 28E).<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Hak untuk bekerja dan memilih pekerjaan (Pasal 27).<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Hak atas pendidikan (Pasal 31).<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Hak atas lingkungan hidup yang baik (Pasal 28H).<o:p></o:p></span></li></ul><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Kewajiban Warga Negara: Kewajiban warga negara yang diatur oleh UUD NRI Tahun 1945 meliputi:<o:p></o:p></span></p><ul><li style=\"text-align: justify;\"><span lang=\"IN\">Kewajiban membela negara (Pasal 27).<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Kewajiban membayar pajak (Pasal 23).<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Kewajiban mematuhi hukum dan peraturan (Pasal 27).<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Kewajiban untuk mematuhi kewajiban sosial (Pasal 27).<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Kewajiban untuk menghormati hak asasi manusia (Pasal 28I).</span></li></ul></div>', 1729065844, 1729065937, 1, '', 1, 0, 0, '71fcd3d6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28179, 782, 0, 5, 3, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Jelaskan\r\nfaktor-faktor penyebab terjadi pelanggaran hak dan pengingkaran kewajiban warga\r\nnegara baik yang bersifat internal maupun eksternal!</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify; \">Faktor-faktor\r\nPenyebab Pelanggaran Hak dan Pengingkaran Kewajiban Warga Negara:<br></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Internal:<o:p></o:p></span></p>\r\n\r\n<ul><li style=\"text-align: justify;\"><span lang=\"IN\">Kurangnya\r\npemahaman tentang hak dan kewajiban warga negara.</span></li><li style=\"text-align: justify; \"><span lang=\"IN\">Kekurangan\r\npendidikan yang memadai tentang nilai-nilai kewarganegaraan.</span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Ketidakpuasan\r\nterhadap pemerintah atau sistem yang dapat mendorong tindakan melanggar hukum.</span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Budaya\r\nkorupsi yang meresap dalam masyarakat.<o:p></o:p></span></li></ul>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">eksternal:<o:p></o:p></span></p>\r\n\r\n<ul><li style=\"text-align: justify;\"><span lang=\"IN\">Konflik dan\r\nperang yang dapat mengganggu pelaksanaan hak dan kewajiban.</span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Intervensi\r\nasing atau tekanan internasional yang mengganggu kedaulatan negara.</span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Ketidakstabilan\r\npolitik yang menghambat penerapan hukum dan hak-hak warga negara.<o:p></o:p></span></li></ul></div>', 1729065939, 1729066118, 1, '', 1, 0, 0, '71fcd7a5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28180, 782, 0, 5, 4, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Menurut\r\nAnda, apa yang harus dilakukan pemerintah dalam menyelesaikan persoalan\r\npelanggaran hak dan pengingkaran keajiban sebagai warga negara?</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Tindakan Pemerintah untuk Menyelesaikan Pelanggaran Hak dan Pengingkaran Kewajiban Warga Negara:</span></p><ul><li style=\"text-align: justify;\"><span lang=\"IN\">Memperkuat sistem hukum dan keadilan untuk menindak pelanggaran hak.<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Meningkatkan pendidikan kewarganegaraan dan kesadaran hak asasi manusia.<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Mendorong partisipasi aktif warga negara dalam proses politik dan pembuatan kebijakan.<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Mengatasi kemiskinan dan ketidaksetaraan sosial yang dapat menjadi akar penyebab pelanggaran hak.<o:p></o:p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Menegakkan hukum dan tindakan tegas terhadap korupsi dan ketidakpatuhan terhadap kewajiban warga negara.</span></li></ul></div>', 1729066017, 1729066071, 1, '', 1, 0, 0, '71fcdca2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28181, 782, 0, 5, 5, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Bagaiamanakah\r\ncara Anda untuk menghindari melakukan pelanggaran terhadap hak orang lain dan\r\npengingkaran terhadap kewajiban dalam kehdupan sehari-hari?</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Cara Menghindari Pelanggaran Hak dan Pengingkaran Kewajiban dalam Kehidupan Sehari-hari:</span></p><ul><li style=\"text-align: justify;\"><span lang=\"IN\">Pendidikan : Pelajari hak asasi manusia dan kewajiban warga negara.</span></li><li style=\"text-align: justify;\">Partisipasi : Berpartisipasi dalam pemilihan umum dan proses politik lainnya.</li><li style=\"text-align: justify;\">Toleransi : Hormati hak dan keyakinan orang lain, bahkan jika berbeda dengan Anda.</li><li style=\"text-align: justify;\">Kepatuhan Hukum : Patuhi hukum dan peraturan yang berlaku.</li><li style=\"text-align: justify;\">Kesadaran Sosial : Peduli terhadap isu-isu sosial dan lingkungan serta berkontribusi pada perbaikan masyarakat.</li></ul>', 1729066119, 1729066232, 1, '', 1, 0, 0, '71fce459-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
