INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28297, 795, 0, 4, 1, NULL, NULL, NULL, '<p align=\"center\">OBAMA\r\n</p><p align=\"justify\">Obama was born on August 4,1961 in Kapi’olani Maternity &amp; Gynecological Hospital in Honolulu, Hawaii and is the first President to have been born in Hawaii.\r\nHis father was a black exchange student from Kenya named Barack Obama Sr. His mother was a white woman from Kansas named Ann Dunham, who was an anthropologist and died from cancer. His mother married Barack Obama Sr. In 1961 and divorced him in 1964. His stepfather was from Indonesia named Lolo Soetoro after his mother merried him in 1965. She divorced 1980.\r\nHe spent most of his childhood in Hawaii and chicago, although he lived in Indonesia with his mother and stepfather from age 6 to age 10.&nbsp;</p><p align=\"justify\"> Where was Obama born?\r\n</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Hawaii', 1729084751, 1729085631, 1, '', 1, 0, 0, '71fe34c6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
