INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28319, 743, 0, 1, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Ketika Allah bertanya kepada Salomo apakah yang ia minta dari-Nya, maka Salomo meminta hikmat sebagai hadiah dari Allah. Sebagai seorang raja, Salomo sadar bahwa hikmat dibutuhkan bukan  hanya sebagai bekal untuk memimpin rakyatnya. Namun terutama supaya ia dapat  membuat keputusan yang adil dan benar. Tidak mudah  bagi manusia untuk memiliki kemampuan bertindak  benar dan adil jika Tuhan tidak memberikan hikmat-Nya. Allah memenuhi permintaannya,  hikmat Allah pun dianugrahkan bagi Salomo, memiliki hikmat dari Allah membuat Salomo mampu  mengambil keputusan adil dan benar. Hal itu terbukti ketika orang membawa kepadanya dua orang perempuan yang memperebutkan bayi, Salomo mampu mengambil keputusan yang adil benar,  dengan hikmat yang berasal dari Tuhan, ia tahu manakah diantara dua orang perempuan itu yang merupakan  ibu dari bayi yang sedang diperebutkan.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nBerdasarkan teks diatas, kita dapat mengetahui alasan Salomo meminta hikmat dari Allah ialah ….&nbsp;</span></div>', '<span style=\"text-align: justify;\">Agar ia dapat menghukum rakyatnya dengan sesuka hati&nbsp;</span>', '<span style=\"text-align: justify;\">Supaya ia mampu mengambil keputusan-keputusan yang adil dan benar terhadap rakyatnya dalam kepemimpinannya sebagai raja Israel&nbsp;</span>', '<span style=\"text-align: justify;\">Agar ia dapat memilih banyak isteri Agar ia mampu membangun hubungan dengan banyak kerajaan Agar ia mampu membangun bait Allah yang megah</span>', '<span style=\"text-align: justify;\">Agar ia mampu membangun hubungan dengan banyak kerajaan&nbsp;</span>', '<span style=\"text-align: justify;\">Agar ia mampu membangun bait Allah yang megah</span>', NULL, NULL, NULL, NULL, NULL, 'b', 1729125083, 1729125335, 1, '', 1, 0, 0, '71fe5257-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
