INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28321, 791, 0, 5, 2, NULL, NULL, NULL, '<p>Secara teoritik menurut  Brent G. Wilson dalam bukunya Evaluation Of Learning In Art Education; Apresiasi seni memiliki tiga domain, yakni: perasaan (feeling), dalam konteks ini terkait dengan perasaan keindahan, penilaian (valuing) terkait dengan nilai seni, dan empati (emphatizing), terkait dengan sikap hormat kepada dunia seni rupa, termasuk kepada profesi seniman, yaitu perupa (pelukis, pematung, penggrafis, penggeramik, pendesain, pengriya, dan lain-lain).\r\n</p><p>\r\nSeni memiliki tiga domain yakni...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>1. Perasaan(feeling)</div><div>2. Keindahan, penilaian (valuing)</div><div>3. Empati (emphatizing)</div>', 1729125096, 1729125535, 1, '', 1, 0, 0, '71fe540d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28322, 791, 0, 5, 3, NULL, NULL, NULL, '<p>Pengertian analisis dalam konteks apresiasi adalah pengkajian yang cermat terhadap karya seni rupa untuk mengetahui keberadaan yang sebenarnya. penelaah secara mendalam dilakukan dengan cara menguraikan masalah pokok dengan bagian-bagian karya seni, termasuk hubungan antar bagian dengan keseluruhan, sehingga kita memperoleh kesimpulan yang tepat ketika mengkaji karya seni rupa.</p><p>Sebutkan komponen pengamatan dalam menganalisis...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>1.Konsep</p><p>2. Unsur</p><p>3. Prinsip</p><p>4. Bahan</p><p>5. Teknik</p>', 1729125100, 1729126198, 1, '', 1, 0, 0, '71fe54ef-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
