INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28336, 780, 0, 3, 5, NULL, NULL, NULL, '<p>Dalam menjaga keutuhan Bangsa dan Negara Indonesia setiap Warga Negara Indonesia wajib memiki jiwa patriotisme dan cinta tanah air. Maka dari itu setiap warga negara harus menanamkan dan menjunjung tinggi pilar-pilar kebangsaan dan instrumen pemersatu bangsa.</p><p>Kelompokkanlah pilar-pilar kebangsaan dan instrumen pemersatu bangsa dibawah ini!&nbsp;</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:10:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:23:\"<p>Pilar Kebangsaan</p>\";i:2;s:33:\"<p>Instrumen Pemersatu Bangsa</p>\";}i:1;a:3:{i:0;s:17:\"<p>Pancasila</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:28:\"<p>Lagu Nasional</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:28:\"<p>Peraturan Pemerintah</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:24:\"<p>Bahasa Indonesia</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:30:\"<p>UUD NRI Tahun 1945<br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:6;a:3:{i:0;s:21:\"<p>Bahasa Daerah</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:7;a:3:{i:0;s:27:\"<p>Bhineka Tunggal Ika</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:8;a:3:{i:0;s:32:\"<p>Adat Istiadat dan Budaya</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:9;a:3:{i:0;s:12:\"<p>NKRI</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729125825, 1729126012, 1, '', 1, 0, 0, '71fe63ae-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28337, 798, 0, 1, 3, NULL, NULL, NULL, '<p>Dasar kategorisasi kelompok dalam (in-group) dan kelompok luar (out-group) ialah......</p>', 'besar kecilnya jumlah keanggotaan', '&nbsp;identitas yang dimiliki antaranggota', '&nbsp;kekuatan atau pengaruh yang diberikan', 'tingkat keeratan hubungan antaranggota', 'pembagian kerja atau peran antaranggota', NULL, NULL, NULL, NULL, NULL, 'b', 1729125890, 1729751473, 1, '', 1, 0, 0, '71fe6545-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28338, 743, 0, 1, 4, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Perlu Menerapkan Keadilan bagi Semua Insan\r\n\r\nAppolloni dan  McDougall (2011) memberikan  beberapa perspektif  terkait dengan  tema   mengapa  kita  harus   memberikan   perhatian   besar   terhadap keadilan bagi semua, yaitu perspektif Kristiani, ilmiah, dan historis. Istilah keadilan ekologis (ecological justice) merujuk pada  pemahaman bahwa  manusia haruslah hidup  dalam  keadaan  damai  dengan lingkungannya,  serta  menyadari  adanya saling ketergantungan antara  berbagai  unsur di lingkungan.  Dengan  demikian, keadilan ekologis justru mengangkat derajat  manusia  yang memang diberikan tugas  istimewa  oleh  Tuhan  untuk  bertambah banyak,  memenuhi bumi  dan menaklukkannya,  dan  menguasai  binatang (Kejadian 1: 28). Perintah  ini tentu harus  dijalankan  dengan bijak. Misalnya, bila perintah  “beranak  cuculah  dan bertambah banyak” dianggap sebagai  perintah  untuk  memiliki anak sebanyak- banyaknya, ternyata tidaklah tepat  pada masa kini. Dunia dengan isinya memiliki keterbatasan.  Jumlah   manusia   yang   banyak   menyebabkan  makanan   yang tersedia menjadi terbatas. Pemerintah Tiongkok pernah mengeluarkan peraturan bahwa setiap keluarga hanya boleh memiliki satu anak. Peraturan ini dibuat untuk membatasi jumlah penduduk yang terus meningkat,  padahal  sumber  daya alam tidak memadai. Dampak dari peraturan ini adalah, banyak bayi-bayi perempuan yang dibunuh.  Mengapa? Karena budaya  Tionghoa menganut sistim patriarkat, artinya garis keturunan dilanjutkan oleh anak pria. Bila keluarga hanya mempunyai satu  anak  dan  anak  itu  adalah  perempuan,  tentu   tidak  dapat   meneruskan keturunan ayahnya.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nManusia haruslah hidup  dalam  keadaan  damai  dengan lingkungannya,  serta  menyadari  adanya saling ketergantungan antara  berbagai  unsur di lingkungan adalah pemahaman dari ….&nbsp;</span></div>', '<span style=\"text-align: justify;\">Appolloni dan McDougall&nbsp;</span>', '<span style=\"text-align: justify;\">Pemerintah Tiongkok&nbsp;</span>', '<span style=\"text-align: justify;\">Keadilan ekologi&nbsp;</span>', '<span style=\"text-align: justify;\">Budaya Tionghoa&nbsp;</span>', '<span style=\"text-align: justify;\">Keadilan sosial</span>', NULL, NULL, NULL, NULL, NULL, 'c', 1729125936, 1729126200, 0, '', 1, 0, 0, '71fe6611-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
