INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28353, 791, 0, 5, 5, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Pelaksanaan aktivitas kreasi seni lukis adalah kegiatan merealisasikan konsep seni sebagai ekspresi. Konsep yang mendasar sumber inspirasi seni dipetik dari kehidupan psikologi pelaku kreatif. jenis&nbsp; seni ini lebih bersifat subjektif, namun sangat penting dalam membentuk keseimbangan antara kehidupan rohani dan jasmani seseorang.</p><p>Proses kreatif berekspresi ini antara lain, memerlukan persiapan: kanvas ukuran 60 x 60 cm, palet, cat minyak atau cat acrylic,kuas, cucian kuas, kain lap dan perlengkapan lain yang dipandang perlu.</p><p>Pengertian dari berekspresi adalah...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>Salah satu kebutuhan hidup manusia. realitas internal kehidupan spritual siswa membutuhkan penyaluran agar dapat mencapai keseimbangan kehidupan rohaniah yang sehat.</div></div>', 1729126781, 1729481518, 1, '', 1, 0, 0, '71fe78ab-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
