INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28372, 791, 0, 3, 1, NULL, NULL, NULL, '<p>Secara teoritik menurut&nbsp; Brent G. Wilson dalam bukunya Evaluation Of Learning In Art Education; Apresiasi seni memiliki tiga domain, yakni: perasaan (feeling), dalam konteks ini terkait dengan perasaan keindahan, penilaian (valuing) terkait dengan nilai seni, dan empati (emphatizing), terkait dengan sikap hormat kepada dunia seni rupa, termasuk kepada profesi seniman, yaitu perupa (pelukis, pematung, penggrafis, penggeramik, pendesain, pengriya, dan lain-lain).</p><p>Tentukanlah pernyataan yang tepat dan benar</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:130:\"<p>Apresiasi seni rupa adalah aktivitas mengindra karya seni rupa dengan cara merasakan, menikmati, menghayati dan menghargai</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:105:\"<p>Brent G. Wilson adalah seorang penulis buku yang berjudul Evaluation of Learning in Art Education</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:74:\"<p>Seni rupa memiliki 3 unsur yaitu: feeling, valuing dan emphatizing</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:68:\"<p>Pematung dan penggrafis bukan termasuk dalam profesi seniman</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729128254, 1729129055, 1, '', 1, 0, 0, '71fe90ff-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
