INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28376, 743, 0, 3, 2, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><b>Bacalah Matius 20: 1- 16\r\n\r\n1) </b></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"> Adapun hal Kerajaan Sorga sama seperti seorang tuan rumah yang pagi- pagi benar keluar mencari pekerja-pekerja untuk kebun anggurnya. 2) Setelah ia sepakat dengan pekerja-pekerja itu mengenai upah sedinar sehari, ia menyuruh mereka ke kebun anggurnya. 3) Kira-kira pukul sembilan pagi ia keluar pula dan dilihatnya ada lagi orang-orang lain menganggur di pasar.  4)  Katanya kepada mereka: “Pergi jugalah kamu ke kebun anggurku dan apa yang pantas akan kuberikan kepadamu.” Dan merekapun pergi. 5) Kira-kira pukul dua belas dan pukul tiga petang ia keluar pula dan melakukan sama seperti tadi. 6) Kira- kira pukul lima petang ia keluar lagi dan mendapati orang-orang lain pula, lalu katanya kepada mereka: “Mengapa kamu menganggur saja di sini sepanjang hari?” 7) Kata mereka kepadanya: “Karena tidak ada orang mengupah kami.” Katanya kepada mereka: “Pergi jugalah kamu ke kebun anggurku.”  8)  Ketika hari malam tuan itu berkata kepada mandurnya: “Panggillah pekerja- pekerja itu dan bayarkan upah mereka, mulai dengan mereka yang masuk terakhir hingga mereka yang masuk terdahulu.”  9) Maka datanglah mereka yang mulai bekerja kira-kira pukul lima dan mereka menerima masing-masing satu dinar. 10) Kemudian datanglah mereka yang masuk terdahulu, sangkanya akan mendapat lebih banyak, tetapi merekapun menerima masing-masing satu dinar juga.  11) Ketika mereka menerimanya, mereka bersungut-sungut kepada tuan itu, 12) katanya: “Mereka yang masuk terakhir ini hanya bekerja satu jam dan engkau menyamakan   mereka dengan kami yang sehari suntuk bekerja berat dan menanggung panas terik matahari.” 13) Tetapi tuan itu menjawab seorang dari mereka: “Saudara, aku tidak berlaku tidak adil terhadap engkau. Bukankah kita telah sepakat sedinar sehari? 14) Ambillah bagianmu dan pergilah; aku mau memberikan kepada orang yang masuk terakhir ini sama seperti kepadamu.15) Tidakkah aku bebas mempergunakan milikku menurut kehendak hatiku? Atau iri hatikah engkau, karena aku murah hati?” 16) Demikianlah orang yang terakhir akan menjadi yang terdahulu dan yang terdahulu akan menjadi yang terakhir.\r\n</span></div><div style=\"\">\r\nPerhatikan perumpamaan dalam ayat Firman diatas, bahwa sang Pengusaha menerapkan keadilan dan prinsip kasih karunia/belas kasihan.\r\n</div><div style=\"\"><br></div><div style=\"\">\r\nBerdasarkan teks tersebut diatas, hubungkan penerapan prinsip-prinsip tersebut pada masing-masing kelompok pekerja!</div><div style=\"\"><br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:23:\"<p>Prinsip Keadilan</p>\";i:2;s:28:\"<p>Prinsip Kasih Karunia</p>\";}i:1;a:3:{i:0;s:50:\"<div>Pekerja yang masuk jam pagi-pagi benar</div>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:108:\"<div><span lang=\"EN-ID\" style=\"line-height: 14.98px;\">Pekerja yang masuk jam 09.00 pagi</span></div><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:151:\"<span lang=\"EN-ID\" style=\"line-height: 14.98px;\"><span lang=\"EN-ID\" style=\"line-height: 14.98px;\">Pekerja yang masuk jam 12.00 siang</span></span><br>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:101:\"<div><span lang=\"EN-ID\" style=\"line-height: 14.98px;\">Pekerja yang masuk jam 03.00 sore</span></div>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:45:\"<p>Pekerja yang masuk jam 05.00 sore<br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729128453, 1729129712, 1, '', 1, 0, 0, '71fe9367-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28377, 783, 0, 2, 2, NULL, NULL, NULL, '<p>Perhatikan pernyatan dsi bawah ini!</p><p>1. keluarga adalah tempat untuk mencari hiburan dan memberikan suasana yang segar dan gembira di dalam keluarga kristen</p><p>2. Keluarga adalah lingkungan dasar di dalam menerapkan nilai-nilai kehidupan yang sesuai dengan ajaran Kristiani</p><p>3. Keluarga adalah tempat yang nyaman bagi anggota keluarga dan memberikan perlindungan secara fisik, ekonomis maupun psikologis</p><p>4. keluarga adalah tempat pememukan yang bersifat biologis misalnya makan, untuk memenuhi kebutuhan gizi keluarga&nbsp;</p><p>5. Keluarga adalah tempat mengekspresikan kasih sayang, keintiman, perhatian dan rasa aman yang tercipta dalam keluarga&nbsp;</p><p>Keluarga merupakan tempat pembentukan yang utama dan yang pertama bagi kehidupan seseorang ditunjukkan pada nomor....</p>', 'a:3:{s:1:\"a\";s:14:\"<p>1 dan 2</p>\";s:1:\"b\";s:14:\"<p>3 dan 4</p>\";s:1:\"c\";s:14:\"<p>1 dan 5</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;N;}', 1729128522, 1729133659, 1, '', 1, 0, 0, '71fe94d3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
