INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28384, 791, 0, 3, 2, NULL, NULL, NULL, '<p>Pengertian analisis dalam konteks apresiasi adalah pengkajian yang cermat terhadap karya seni rupa untuk mengetahui keberadaan yang sebenarnya. penelaah secara mendalam dilakukan dengan cara menguraikan masalah pokok dengan bagian-bagian karya seni, termasuk hubungan antar bagian dengan keseluruhan, sehingga kita memperoleh kesimpulan yang tepat ketika mengkaji karya seni rupa.</p><p><span style=\"font-size: 0.875rem;\">Komponen dalam menganalisis karya seni rupa dua dimensi adalah...</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:14:\"<p>Konsep</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:21:\"<p>Fungsi</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:13:\"<p>Unsur</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:13:\"<p>Jenis</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:21:\"<p>Nilai estetis</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729129071, 1729130169, 1, '', 1, 0, 0, '71fe990c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
