INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28388, 786, 0, 1, 16, NULL, NULL, NULL, '<p>Bacalah cuplikan teks hasil observasi berikut!\r\n...\r\n</p><p>(1) Setelah dingin, kembali peras-peras daun kemangi. </p><p>(2) Saring dan simpan air sari kemangi di dalam botol. </p><p>(3) Agar lebih awet, simpan dalam kulkas. </p><p>(4) Gunakan dengan bantuan kapas dan oleskan ke seluruh wajah sebelum tidur. </p><p>(5) Biarkan hingga keesokan paginya.\r\n...\r\n</p><p>Kalimat simpleks yang terdapat pada paragraf di atas adalah...</p>', '1 dan 2', '2 dan 3', '3, 4 dan 5', '1, 3, dan 5', '2 dan 4', NULL, NULL, NULL, NULL, NULL, 'd', 1729129438, 1729129614, 1, '', 1, 0, 0, '71fe9bb5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28389, 760, 0, 3, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Untuk menghadapi Indonesia, Belanda melakukan protes PBB dan melakukan langkah - langkah militer seperti mengirim misi militernya ke Irian Barat. Untuk meningkatkan perjuangan maka pada tanggal 17 Desember 1961 Presiden&nbsp; Sukarno mencanangkan Tri Komando Rakyat di Yogyakarta.</p><p>Dari pernyataan&nbsp; di atas yang termasuk isi Tri Komando Rakyat !</p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:70:\"<p>Gagalkan pembentukan negara - negara boneka papua oleh belanda</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:63:\"<p>Kibarkan sang merah putih di seluruh irian barat</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:22:\"<p>Pembubaran PKI</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:43:\"<p>Penurunan harga / perbaikan ekonomi</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:57:\"<p>Pembersihan kabinet dari unsur - unsur G 30 S/PKI</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:37:\"<p>Bersiap untuk mobilisasi umum</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729129454, 1729572846, 1, '', 1, 0, 0, '71fe9c77-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28392, 743, 0, 3, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pelaksanaan Keadilan dan Demokrasi di Indonesia Sejak 1998\r\n\r\nMembahas pelaksanaan demokrasi sebelum tahun 1998 bukan merupakan hal yang perlu dibahas disini karena lebih tepat dibahas di pelajaran Sejarah atau Pendidikan Kewarganegaraan. Kini kita hidup di era reformasi yang diawali dengan ketidakpuasan rakyat terhadap pemerintahan saat itu. Dapat dikatakan bahwa demokrasi di Indonesia menunjukkan perkembangan menuju perbaikan sejak tahun 1998 yang merupakan salah satu tonggak sejarah di Indonesia. Ini adalah tahun dimana pemerintahan Soeharto berakhir dan tampuk pemerintahan beralih ke B.J. Habibie selaku Presiden Republik Indonesia yang ketiga. Pemerintahan Soeharto disebut Orde Baru yang dikecam karena menggunakan pendekatan otoriter walaupun masa itu disebut juga dengan Demokrasi Pancasila. Orde Baru memang menggantikan rezim Orde Lama di bawah pemerintahan Presiden Soekarno.\r\n\r\nReformasi ini diwujudkan dalam kehidupan berpolitik dan bermasyarakat yang sifatnya menjadi lebih bebas dan terbuka (Indonesia-investment, 2013).\r\n\r\nPresiden Habibie digantikan oleh Presiden K.H. Abdurrahman Wahid (Gus Dur) pada tahun 1999. Contoh pembaharuan yang terjadi pada masa ini adalah pengangkatan menteri kabinet yang berasal dari partai politik dan mengurangi peranan dari Tentara Nasional Indonesia (TNI) dan Angkatan Bersenjata Republik Indonesia (ABRI).\r\n\r\nPada tahun 2004 pemerintahan Megawati berakhir dan melalui pemilihan langsung presiden yang pertama kali dilakukan oleh rakyat Indonesia, Susilo Bambang Yudoyono (SBY) menjadi Presiden RI yang kelima.\r\n\r\nSejak masa reformasi pada pemerintahan B.J. Habibie sampai masa demokrasi pada masa pemerintahan Susilo Bambang Yudoyono (SBY), terjadi pembaharuan-pembaharuan yang dicapai oleh masing-masing presiden tersebut.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nBerdasarkan teks diatas, hubungkanlah tokoh presiden dengan masing-masing pencapaian perubahan atau pembaruan yang sesuai berikut!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:4:{i:0;s:9:\"<p>#</p>\n\";i:1;s:18:\"<p>B.J Habibie</p>\";i:2;s:37:\"<p>K.H Abdurahman Wahid (Gus Dur)</p>\";i:3;s:30:\"<p>Susilo Bambang Yudoyono</p>\";}i:1;a:4:{i:0;s:167:\"<div>\r\n<span lang=\"EN-ID\" style=\"line-height: 15.6933px;\">M</span><span lang=\"EN-ID\" style=\"line-height: 15.6933px;\">emberikan&nbsp;kebebasan&nbsp;pers</span>\r\n</div>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:2;a:4:{i:0;s:183:\"<div><span lang=\"EN-ID\" style=\"line-height: 15.6933px;\">Kebebasan&nbsp;pers&nbsp;semakin&nbsp;luas&nbsp;karena&nbsp;Departemen&nbsp;Penerangan&nbsp;dihapuskan<br></span></div><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:3;a:4:{i:0;s:137:\"<p>Di bidang ekonomi, terjadi pertumbuhan sehingga ada stabilitas ekonomi dengan kekuatan ekonomi yang diakui negara-negara lain<br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:4;a:4:{i:0;s:203:\"<p><span lang=\"EN-ID\" style=\"line-height: 14.98px;\">A</span><span lang=\"EN-ID\" style=\"line-height: 14.98px;\">da alokasi Anggaran Pendapatan dan Belanja Negara sebesar 20% untuk pendidikan</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:5;a:4:{i:0;s:196:\"<div>\r\n<span lang=\"EN-ID\" style=\"line-height: 14.98px;\">P</span><span lang=\"EN-ID\" style=\"line-height: 14.98px;\">endirian partai politik dan sejumlah serikat misalnya serikat buruh</span>\r\n</div>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:6;a:4:{i:0;s:210:\"<p><span lang=\"EN-ID\" style=\"line-height: 14.98px;\">M</span><span lang=\"EN-ID\" style=\"line-height: 14.98px;\">engakui Konghucu sebagai salah satu kepercayaan yang ada di kalangan rakyat Indonesia</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}}}', 1729129716, 1729154311, 1, '', 1, 0, 0, '71fe9d90-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
