INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28406, 743, 0, 4, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Perjalanan demokrasi sebagai wujud keadilan di Indonesia menjadi perhatian bagi negara-negara asing, misalnya saja, Amerika Serikat. Secara politik, Indonesia diharapkan berperan untuk menjaga perdamaian di wilayah Asia Tenggara khususnya dan di Asia Pasifik. Beberapa kali Indonesia diminta menjadi mediator di antara pihak-pihak yang berkonflik. Misalnya, Indonesia menjadi mediator untuk perjanjian damai antara MNLF-Filipina sejak 1993. Peran ini berhasil dijalankan dengan baik sampai disepakatinya perjanjian damai pada tanggal 2 September 1996 di Manila, Filipina. Juga, kepemimpinan Indonesia di APEC (Asia Pacific Economy Corporation) membuka peluang untuk kerjasama di bidang ekonomi agar terjadi pertumbuhan ekonomi yang lebih baik di antara negara-negara anggota APEC.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nIndonesia sering dijadikan sasaran untuk pemasaran produk dari luar negeri adalah peran Indonesia dalam bidang ….</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ekonomi', 1729129082, 1729129397, 1, '', 1, 0, 0, '71fead6a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28407, 743, 0, 5, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Ketika Allah bertanya kepada Salomo apakah yang ia minta dari-Nya, maka Salomo meminta hikmat sebagai hadiah dari Allah. Sebagai seorang raja, Salomo sadar bahwa hikmat dibutuhkan bukan  hanya sebagai bekal untuk memimpin rakyatnya. Namun terutama supaya ia dapat  membuat keputusan yang adil dan benar. Tidak mudah  bagi manusia untuk memiliki kemampuan bertindak  benar dan adil jika Tuhan tidak memberikan hikmat-Nya. Allah memenuhi permintaannya,  hikmat Allah pun dianugrahkan bagi Salomo, memiliki hikmat dari Allah membuat Salomo mampu  mengambil keputusan adil dan benar. Hal itu terbukti ketika orang membawa kepadanya dua orang perempuan yang memperebutkan bayi, Salomo mampu mengambil keputusan yang adil benar,  dengan hikmat yang berasal dari Tuhan, ia tahu manakah diantara dua orang perempuan itu yang merupakan  ibu dari bayi yang sedang diperebutkan.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nJelaskanlah secara singkat alasan Salomo meminta hikmat dari Allah!&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"text-align: justify;\">Supaya ia mampu mengambil keputusan yang adil dan benar terhadap rakyatnya</span><br>', 1729129089, 1729132246, 1, '', 1, 0, 0, '71feaeb8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
