INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28410, 749, 0, 4, 3, NULL, NULL, NULL, '<span style=\"line-height: 107%;\">Teknik\r\nmenghentikan bola dengan kaki bagian dalam, maka kaki yang digunakan diputar ke\r\narah!</span>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'luar', 1729129109, 1729129428, 1, '', 1, 0, 0, '71feb1ad-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28411, 743, 0, 4, 2, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pemerintahan Soeharto disebut Orde Baru yang dikecam karena menggunakan pendekatan otoriter walaupun masa itu disebut juga dengan Demokrasi Pancasila. Orde Baru memang menggantikan rezim Orde Lama di bawah pemerintahan Presiden Soekarno.\r\n\r\nReformasi ini diwujudkan dalam kehidupan berpolitik dan bermasyarakat yang sifatnya menjadi lebih bebas dan terbuka (Indonesia-investment, 2013).\r\n\r\nPresiden Habibie digantikan oleh Presiden K.H. Abdurrahman Wahid (Gus Dur) pada tahun 1999. Contoh pembaharuan yang terjadi pada masa ini adalah pengangkatan menteri kabinet yang berasal dari partai politik dan mengurangi peranan dari Tentara Nasional Indonesia (TNI) dan Angkatan Bersenjata Republik Indonesia (ABRI).\r\n\r\nPada tahun 2004 pemerintahan Megawati berakhir dan melalui pemilihan langsung presiden yang pertama kali dilakukan oleh rakyat Indonesia, Susilo Bambang Yudoyono (SBY) menjadi Presiden RI yang kelima.\r\n\r\nSejak masa reformasi pada pemerintahan B.J. Habibie sampai masa demokrasi pada masa pemerintahan Susilo Bambang Yudoyono (SBY), terjadi pembaharuan-pembaharuan yang dicapai oleh masing-masing presiden tersebut.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nPembatasan periode kepresidenan menjadi maksimal dua kali lima tahun, adalah capaian pembaharuan dari presiden ….&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'B.J Habibie', 1729129398, 1729129525, 1, '', 1, 0, 0, '71feb2f0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28412, 749, 0, 4, 4, NULL, NULL, NULL, '<span style=\"line-height: 107%;\">Awal\r\nmula lahirnya formasi 4-2-4 berasal dari negara!</span>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'inggris', 1729129432, 1729129473, 1, '', 1, 0, 0, '71feb473-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28413, 749, 0, 4, 5, NULL, NULL, NULL, '<span style=\"line-height: 107%;\"><i>Man\r\nto man</i> merupakan pola pertahanan satu lawan . . !</span>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'satu', 1729129434, 1729129902, 1, '', 1, 0, 0, '71feb52c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28414, 743, 0, 4, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Presiden Habibie digantikan oleh Presiden K.H. Abdurrahman Wahid (Gus Dur) pada tahun 1999. Contoh pembaharuan yang terjadi pada masa ini adalah pengangkatan menteri kabinet yang berasal dari partai politik dan mengurangi peranan dari Tentara Nasional Indonesia (TNI) dan Angkatan Bersenjata Republik Indonesia (ABRI).\r\n\r\nPada tahun 2004 pemerintahan Megawati berakhir dan melalui pemilihan langsung presiden yang pertama kali dilakukan oleh rakyat Indonesia, Susilo Bambang Yudoyono (SBY) menjadi Presiden RI yang kelima.\r\n\r\nSejak masa reformasi pada pemerintahan B.J. Habibie sampai masa demokrasi pada masa pemerintahan Susilo Bambang Yudoyono (SBY), terjadi pembaharuan-pembaharuan yang dicapai oleh masing-masing presiden tersebut.\r\n\r\nMeninggalkan IMF selaku badan ekonomi yang sebelumnya banyak mendikte apa yang harus dilakukan oleh pemerintahan Indonesia dalam bidang ekonomi, adalah capaian pembaharuan dari presiden ….&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Susilo Bambang Yudoyono (SBY)', 1729129527, 1729129722, 1, '', 1, 0, 0, '71feb5fb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28415, 743, 0, 4, 4, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Makna Kata “Syalom”\r\n\r\nKata syalom dalam bahasa Ibrani biasanya diterjemahkan menjadi ”damai” atau ”damai sejahtera”. Dalam bahasa Yunani, bahasa yang digunakan dalam penulisan Perjanjian Baru, kata ini diterjemahkan menjadi eirene. Kata syalom atau “damai sejahtera” sering dipergunakan untuk memberikan salam kepada sesama. Dalam bahasa Ibrani orang mengucapkan syalom aleikhem, yang artinya “damai sejahtera bagimu”. Ucapan ini dijawab dengan kata-kata aleikhem syalom. Kata ini mirip sekali dengan kata“salam alaikum” atau“assalamu alaikum” dan“wa alaikum salam” dalam bahasa  Arab, bukan? Kita tidak perlu heran. Bahasa Arab memang berasal dari rumpun yang sama dengan bahasa Ibrani seperti halnya bahasa Tagalog dengan bahasa Indonesia. Dalam bahasa Arab kata syalom diterjemahkan menjadi salam, kata yang sama yang dipergunakan dalam bahasa Indonesia yang sangat diperkaya oleh kosakata dari bahasa Arab karena pengaruh agama Islam. Kata ini dapat kita bandingkan dengan salam Horas! di kalangan masyarakat Batak; Ya’ahowu! di dalam masyarakat Nias.\r\n\r\nOrang-orang Ibrani biasanya mengucapkan kata, yang jika diterjemahkan dalam Bahasa Indonesia menjadi “damai sejahtera bagimu” adalah ….&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Syalom aleikhem', 1729129723, 1729132021, 1, '', 1, 0, 0, '71feb7e1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
