INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28432, 749, 0, 5, 6, NULL, NULL, NULL, 'Mengapa sepak bola dikategorikan dalam permainan bola besar?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div style=\"text-align: justify; \">Sepak bola dikategorikan sebagai permainan bola besar karena membutuhkan lapangan yang relatif besar dan melibatkan dua tim yang masing-masing terdiri dari sebelas pemain. Selain itu, bola yang digunakan juga cukup besar dibandingkan dengan olahraga lainnya.</div>', 1729130747, 1729488372, 1, '', 1, 0, 0, '71fec9c6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
