INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28448, 795, 0, 1, 24, NULL, NULL, NULL, '<p>Albert Einstein </p><p>\r\nAlbert Eistein is one of the most notable and influential scientists of the twentieth century. Although he became known as a genius of science and gained considerable fame later in life, as a child he was slow in learning to speak, and had a rebellious nature towards the conventional styles of learning at school, which left many teachers to believe he would amount to little.  \r\n	Inspired by a compass, his “sacred little geometry book”, and classical music, his interest in science and mathematics grew and by the age of sixteen he was writing his first research science paper, and attempting to skip the last few years of high school to enter the swiss institude of tecknology. He failed the entrance exam but set a precedent in his life for thinking outside of the box and challenging the rules.\r\n	His most famous discovery is the theory of relativy, E=MC2 which overturned Isaac Newton’s laws by explaining the relation of energy and mass as a consequence of space and time. First introduced in a 3 page paper in 1905, the theory was so revolusionary it couldn’t be proven until more advanced technology was available years later.\r\n	  Albert Einstein is not only a world renowned scientist who left an indelible mark on the world but also an icon of popular culture whose name and image have come to represent genius and intellect.</p><p>\r\n\r\nSomething good or value that can we learn from a biographical text is called?\r\n</p>', 'Moral lesson', 'General description ', 'Purpose of the text ', 'Language feture ', 'Linking verbs  \r\n', NULL, NULL, NULL, NULL, NULL, 'a', 1729132099, 1729678102, 1, '', 1, 0, 0, '71fee03e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28449, 743, 0, 5, 2, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><b>Bacalah Matius 20: 1- 16\r\n\r\n1) </b></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"> Adapun hal Kerajaan Sorga sama seperti seorang tuan rumah yang pagi- pagi benar keluar mencari pekerja-pekerja untuk kebun anggurnya. 2) Setelah ia sepakat dengan pekerja-pekerja itu mengenai upah sedinar sehari, ia menyuruh mereka ke kebun anggurnya. 3) Kira-kira pukul sembilan pagi ia keluar pula dan dilihatnya ada lagi orang-orang lain menganggur di pasar.  4)  Katanya kepada mereka: “Pergi jugalah kamu ke kebun anggurku dan apa yang pantas akan kuberikan kepadamu.” Dan merekapun pergi. 5) Kira-kira pukul dua belas dan pukul tiga petang ia keluar pula dan melakukan sama seperti tadi. 6) Kira- kira pukul lima petang ia keluar lagi dan mendapati orang-orang lain pula, lalu katanya kepada mereka: “Mengapa kamu menganggur saja di sini sepanjang hari?” 7) Kata mereka kepadanya: “Karena tidak ada orang mengupah kami.” Katanya kepada mereka: “Pergi jugalah kamu ke kebun anggurku.”  8)  Ketika hari malam tuan itu berkata kepada mandurnya: “Panggillah pekerja- pekerja itu dan bayarkan upah mereka, mulai dengan mereka yang masuk terakhir hingga mereka yang masuk terdahulu.”  9) Maka datanglah mereka yang mulai bekerja kira-kira pukul lima dan mereka menerima masing-masing satu dinar. 10) Kemudian datanglah mereka yang masuk terdahulu, sangkanya akan mendapat lebih banyak, tetapi merekapun menerima masing-masing satu dinar juga.  11) Ketika mereka menerimanya, mereka bersungut-sungut kepada tuan itu, 12) katanya: “Mereka yang masuk terakhir ini hanya bekerja satu jam dan engkau menyamakan   mereka dengan kami yang sehari suntuk bekerja berat dan menanggung panas terik matahari.” 13) Tetapi tuan itu menjawab seorang dari mereka: “Saudara, aku tidak berlaku tidak adil terhadap engkau. Bukankah kita telah sepakat sedinar sehari? 14) Ambillah bagianmu dan pergilah; aku mau memberikan kepada orang yang masuk terakhir ini sama seperti kepadamu.15) Tidakkah aku bebas mempergunakan milikku menurut kehendak hatiku? Atau iri hatikah engkau, karena aku murah hati?” 16) Demikianlah orang yang terakhir akan menjadi yang terdahulu dan yang terdahulu akan menjadi yang terakhir.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nJelaskanlah menurut pemahaman kamu, pesan moral yang terapat dalam perumpamaan tersebut!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><span style=\"text-align: justify;\">Pesan moral dalam perumpamaan tersebut antara lain:</span></p><ul><li><span style=\"text-align: justify; font-size: 0.875rem;\">Kita belajar dari tuan kebun tersebut, yang berlaku adil kepada para pekerjanya. Berlakulah adil terhadap setiap orang yang berhak mendapatkan keadilan dari kita. Selain itu, tuan kebun itu juga sangat peduli dan murah hati pada orang yang miskin dan tersingkir. Jika kita berkelebihan atau berkelimpahan, atau apapun keadaan kita, tentu di sekitar kita ada orang yang memerlukan uluran tangan kita. Belajarlah dari si tuan kebun tersebut, yang memperhatikan sesamanya</span></li><li><span style=\"text-align: justify; font-size: 0.875rem;\">Kita juga belajar dari para pekerja. Pertama, jangan suka bersungut-sungut dalam melakukan sesuatu atau mendapat suatu hasil perjuangan yang mengecewakan. Kedua, jangan putus asa jika kita belum mencapai apa yang kita harapkan. Ketiga, bersyukurlah dalam segala keadaan kita karena dengan sikap hati yang penuh syukur, Tuhan akan memberkati kita. Dan jangan lupa berterima kasih kepada orang yang telah berbaik hati pada kita</span></li></ul>', 1729132247, 1729132499, 1, '', 1, 0, 0, '71fee16b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28450, 795, 0, 1, 25, NULL, NULL, NULL, '<p>Albert Einstein \r\n</p><p>Albert Eistein is one of the most notable and influential scientists of the twentieth century. Although he became known as a genius of science and gained considerable fame later in life, as a child he was slow in learning to speak, and had a rebellious nature towards the conventional styles of learning at school, which left many teachers to believe he would amount to little.  \r\n	Inspired by a compass, his “sacred little geometry book”, and classical music, his interest in science and mathematics grew and by the age of sixteen he was writing his first research science paper, and attempting to skip the last few years of high school to enter the swiss institude of tecknology. He failed the entrance exam but set a precedent in his life for thinking outside of the box and challenging the rules.\r\n	His most famous discovery is the theory of relativy, E=MC2 which overturned Isaac Newton’s laws by explaining the relation of energy and mass as a consequence of space and time. First introduced in a 3 page paper in 1905, the theory was so revolusionaryit couldn’t be proven until more advanced technology was available years later.\r\n	  Albert Einstein is not only a world renowned scientist who left an indelible mark on the world but also an icon of popular culture whose name and image have come to represent genius and intellect.\r\n</p><p>The following are the language features of a biographical recount, except…\r\n</p>', 'It tells about a specific figure \r\n', 'It uses words that could link the time ', '	It tells about the events that already happened in a someone’s life \r\n', 'Is uses action verbs \r\n', 'It uses simple past, present and future', NULL, NULL, NULL, NULL, NULL, 'e', 1729132283, 1729678111, 1, '', 1, 0, 0, '71fee31c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
