INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28453, 795, 0, 1, 26, NULL, NULL, NULL, '<p>It’s Julie’s birthday. She gets lots of presents. She gets a dress from her grandmother. It’s red, yellow and orange. She doesn’t like it. It’s too bright. \r\nShe gets some trainers from her aunt. They’re great but she can’t wear them because they’re size 38 and she’s size 39. They aren’t big enough.\r\nShe also gets some trousers from her mom. They’re nice colours but they’re too long. You can’t see her shoes!\r\nHer dad gives her a book about cats because she loves cats. However, it’s in English and she can’t read it. It’s terrible.\r\nSinta, her best friend give her a T-shirt and it’s perfect! It isn’t too big or too small. It’s just right. She’s wearing it now.  </p><p>&nbsp;Whose birthday present that Julie likes most?</p>', 'Her grandmother ', '&nbsp;Her mom ', '&nbsp;Her father ', '&nbsp;Her aunt ', '&nbsp;Her best friend ', NULL, NULL, NULL, NULL, NULL, 'e', 1729132458, 1729678120, 1, '', 1, 0, 0, '71fee5e0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28454, 743, 0, 5, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Presiden Habibie digantikan oleh Presiden K.H. Abdurrahman Wahid (Gus Dur) pada tahun 1999. Contoh pembaharuan yang terjadi pada masa ini adalah pengangkatan menteri kabinet yang berasal dari partai politik dan mengurangi peranan dari Tentara Nasional Indonesia (TNI) dan Angkatan Bersenjata Republik Indonesia (ABRI).\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nSebutkan 3 pencapaian pembaharuan oleh presiden Abdurrahman Wahid (Gus Dur)!&nbsp;</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<ul><li><span style=\"text-align: justify;\">Kebebasan pers semakin luas karena Departemen Penerangan dihapuskan</span></li><li><span style=\"text-align: justify;\">KelompokTionghoa mendapatkan pengakuan lebih besar melalui kemudahan dalam mengurus dokumen kewarganegaraan dan penetapan hari raya Imlek sebagai hari libur nasional</span></li><li><span style=\"text-align: justify;\">Mengakui Konghucu sebagai salah satu kepercayaan yang ada di kalangan rakyat Indonesia</span><br></li></ul>', 1729132501, 1729132693, 1, '', 1, 0, 0, '71fee707-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
