INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28458, 795, 0, 1, 27, NULL, NULL, NULL, '<p>It’s Julie’s birthday. She gets lots of presents. She gets a dress from her grandmother. It’s red, yellow and orange. She doesn’t like it. It’s too bright. \r\nShe gets some trainers from her aunt. They’re great but she can’t wear them because they’re size 38 and she’s size 39. They aren’t big enough.\r\nShe also gets some trousers from her mom. They’re nice colours but they’re too long. You can’t see her shoes!\r\nHer dad gives her a book about cats because she loves cats. However, it’s in English and she can’t read it. It’s terrible.\r\nSinta, her best friend give her a T-shirt and it’s perfect! It isn’t too big or too small. It’s just right. She’s wearing it now.  </p><p>&nbsp;Why does Julie not like the presents from her mom?\r\n</p>', 'They’re nice color', 'They’re too long \r\n', 'They’re perfect enough \r\n', 'They’re too bright \r\n', 'They ‘re too big \r\n', NULL, NULL, NULL, NULL, NULL, 'b', 1729132697, 1729678128, 1, '', 1, 0, 0, '71feeadd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
