INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28490, 743, 0, 5, 9, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berkaitan dengan Hak Asasi Manusia, ada beberapa hal yang masih diperdebatkan hingga saat ini yaitu Hukuman mati, Aborsi, dan Eutanasia! Jelaskanlah arti masing-masing dari ketiga hal tersebut!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<ol><li style=\"text-align: justify; \">Hukuman Mati adalah hukuman yang dijatuhkan kepada seseorang yang dianggap melakukan kejahatan yang berat, seperti pembunuhan yang sadis dan pengkhianatan kepada negara</li><li style=\"text-align: justify; \">Aborsi adalah praktik menghilangkan janin yang ada di dalam kandungan</li><li style=\"text-align: justify; \">Eutanasia adalah praktik yang dipilih untuk membebaskan seseorang dari penderitaan panjang</li></ol>', 1729134747, 1729135626, 1, '', 1, 0, 0, '71ff243c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:33', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
