INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28549, 743, 0, 1, 9, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Hak untuk hidup dan merasa aman, memiliki privasi, berkeluarga, hak milik pribadi, menyatakan pendapat dengan bebas, adalah merupakan ….&nbsp;</span></div>', '<span style=\"text-align: justify;\">Hak-hak Politik&nbsp;</span>', '<span style=\"text-align: justify;\">Hak-hak ekonomi dan social&nbsp;</span>', '<span style=\"text-align: justify;\">Hak-hak religius&nbsp;</span>', '<span style=\"text-align: justify;\">Hak-hak gerejawi&nbsp;</span>', '<span style=\"text-align: justify;\">Hak-hak warga Negara</span>', NULL, NULL, NULL, NULL, NULL, 'e', 1729137980, 1729138089, 1, '', 1, 0, 0, '71ff984d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28550, 749, 0, 3, 1, NULL, NULL, NULL, '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241021142809.jpeg\" style=\"width: 50%;\"><br></p><p>Permainan sepak bola dimainkan di lapangan oleh dua regu atau dua keseblasan yang saling berhadapan. Tujuan permainan sepak bola adalah memasukan bola ke gawang lawan sebanyak-banyaknya dan mempertahankan daerah sendiri dari serangan lawan dengan aturan tertentu. Dari pernyataan diatas tentukan ketrampilan gerak dibawah ini yang termasuk dalam ketrampilan permainan sepak bola dan ketrampilan permainan bola voli!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:3:{i:0;a:9:{i:0;s:9:\"<p>#</p>\n\";i:1;s:13:\"<p>servis</p>\";i:2;s:14:\"<p>passing</p>\";i:3;s:17:\"<p>mengontrol</p>\";i:4;s:16:\"<p>menendang</p>\";i:5;s:12:\"<p>smash</p>\";i:6;s:16:\"<p>menyundul</p>\";i:7;s:12:\"<p>block</p>\";i:8;s:21:\"<p>menggiring<br></p>\";}i:1;a:9:{i:0;s:30:\"<p>Ketrampilan sepak bola</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"1\";i:7;s:1:\"0\";i:8;s:1:\"1\";}i:2;a:9:{i:0;s:29:\"<p>Ketrampilan bola voli</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"0\";i:7;s:1:\"1\";i:8;s:1:\"0\";}}}', 1729138046, 1729492122, 1, '', 1, 0, 0, '71ff99b5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28551, 749, 0, 3, 2, NULL, NULL, NULL, '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241021142704.jpg\" style=\"width: 50%;\"><span style=\"font-size: 0.875rem;\"><br></span></p><p><span style=\"font-size: 0.875rem;\">Manfaat bermain sepak bola diantaranya dapat menjaga kebugaran tubuh apabila dilakukan secara teratur, menjalin kerjasama bermain sepak bola, menumbuhkan kejujuran, dan menambah pengetahuan serta ketrampilan. Dari pernyataan diatas susunlah 4 urutan ketrampilan gerak mengontrol bola menggunakan telapak kaki dengan urutan gerak awal hingga gerak akhir!&nbsp;</span><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:5:{i:0;s:9:\"<p>#</p>\n\";i:1;s:70:\"<p>telapak kaki ditarik kebelakang bersamaan dengan datangnya bola</p>\";i:2;s:39:\"<p>dekati bola yang sedang bergerak</p>\";i:3;s:24:\"<p>Sikap berdiri<br></p>\";i:4;s:40:\"<p>hentikan bola dengan telapak kaki</p>\";}i:1;a:5:{i:0;s:17:\"<p>Gerakan 1</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";}i:2;a:5:{i:0;s:28:\"<p>Gerakan 2<br></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";}i:3;a:5:{i:0;s:21:\"<p>Gerakan 3<br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";}i:4;a:5:{i:0;s:21:\"<p>Gerakan 4<br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";}}}', 1729138048, 1729492036, 1, '', 1, 0, 0, '71ff9bf4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28552, 749, 0, 3, 3, NULL, NULL, NULL, '<p><br><img src=\"http://asesmen.id/uploads/bank_soal/file_20241021141918.jpg\" style=\"width: 50%;\"></p><p>Permainan sepak bola termasuk permainan yang bersifat invasi karena penyerangan dan pertahanan harus senantiasa dilakukan secara bergantian. oleh karena itu, strategi dan taktik penyerangan dan pertahanan dalam permainan sepak bola perlu di pahami baik oleh seorang pemain dalam sebuah team. Dari pernyataan di atas siswa diminta memahami strategi dalam permainan sepak bola. Di bawah ini pengertian dari strategi penyerangan dan pertahanan, tentukan manakah pengertian strategi penyerangan dan pertahanan.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:3:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:180:\"<p>Siasat yang dijalankan oleh perorangan, maupun tim terhadap lawan dengan tujuan memimpin dan mematahkan pertahanan lawan dalam rangka memenangkan pertandingan secara sportif</p>\";i:2;s:186:\"<p>Siasat yang dilakukan baik perorangan, maupun tim terhadap lawan dengan tujuan menahan serangan atau merebut bolah dari lawan agar tidak mengalami kekalahan dalam pertandingan<br></p>\";}i:1;a:3:{i:0;s:18:\"<p>Pertahanan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:26:\"<p>Penyerangan</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729138050, 1729491574, 1, '', 1, 0, 0, '71ff9fb9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28553, 749, 0, 3, 4, NULL, NULL, NULL, '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241021141731.jpg\" style=\"width: 25%;\"><span style=\"line-height: 107%;\"><br></span></p><p><span style=\"line-height: 107%;\">Menurut\r\nKamus Besar Bahasa Indonesia (KBBI),&nbsp;sepak bola&nbsp;adalah&nbsp;permainan&nbsp;beregu\r\ndi lapangan, menggunakan sepak bola dari dua kelompok yang berlawanan\r\nyang masing-masing terdiri atas sebelas pemain, berlangsung selama 2x45 menit,\r\nkemenangan ditentukan oleh selisih gol yang masuk ke gawang lawan.&nbsp;</span><span style=\"text-align: justify;\">Strategi pertahanan dan penyerangan dalam\r\nsepak bola adalah&nbsp;rencana atau pendekatan yang dirancang oleh pelatih\r\nuntuk mencapai tujuan tertentu di lapangan:&nbsp;</span><p class=\"MsoQuote\" style=\"text-align: justify; \"><span style=\"line-height: 107%;\">Strategi pertahanan t</span><span style=\"font-size: 0.875rem;\">ujuannya adalah\r\nmempertahankan gawang dari serangan lawan agar tidak terjadi gol.&nbsp;Beberapa\r\npola pertahanan dalam sepak bola adalah:&nbsp;</span><span style=\"font-size: 0.875rem;\">Zona marking:&nbsp;Setiap\r\npemain bertanggung jawab atas daerah pertahanan yang menjadi kekuasaannya.&nbsp;</span><span style=\"font-size: 0.875rem;\"><i>Man to man marking</i>:&nbsp;Setiap\r\npemain membayangi satu lawan.&nbsp;</span><span style=\"font-size: 0.875rem;\">Pola pertahanan kombinasi:&nbsp;Gabungan\r\ntaktik zona marking dan man to man marking.&nbsp;</span><span style=\"font-size: 0.875rem;\">Strategi penyerangan t</span><span style=\"font-size: 0.875rem;\">ujuannya adalah mencetak\r\ngol dan memenangkan pertandingan.&nbsp;Salah satu strategi penyerangan adalah\r\nserangan balik <i>(counter attack)</i>, yaitu serangan yang dilakukan dengan satu atau\r\ndua sentuhan antar pemain. Dari pernyataan di atas siswa diminta untuk menentukan formasih di bawah ini sesuai dengan penempatan pemain, manakah yang termasuk dalam taktik bertahan dan penyerangan.</span></p></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:3:{i:0;a:6:{i:0;s:9:\"<p>#</p>\n\";i:1;s:26:\"<p>permainan 2 lawan 4</p>\";i:2;s:26:\"<p>permainan 3 lawan 5</p>\";i:3;s:26:\"<p>permainan 4 lawan 3</p>\";i:4;s:26:\"<p>permainan 5 lawan 5</p>\";i:5;s:26:\"<p>permainan 6 lawan 5</p>\";}i:1;a:6:{i:0;s:26:\"<p>Taktik penyerangan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"1\";}i:2;a:6:{i:0;s:30:\"<p>Taktik Bertahan</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}}}', 1729138051, 1729491479, 1, '', 1, 0, 0, '71ffa216-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28554, 749, 0, 3, 5, NULL, NULL, NULL, '<p class=\"MsoQuote\" style=\"text-align: justify; \"><img src=\"http://asesmen.id/uploads/bank_soal/file_20241021141358.jpg\" style=\"width: 50%;\"><br></p><p class=\"MsoQuote\" style=\"text-align: justify; \">Strategi pertahanan dan\r\npenyerangan dalam bola voli adalah&nbsp;posisi pemain dan teknik yang digunakan\r\nuntuk menutup atau menyerang bola di lapangan lawan.&nbsp;<span style=\"font-size: 0.875rem; line-height: 107%;\">Strategi pertahanan t</span><span style=\"font-size: 0.875rem; line-height: 107%;\">ujuannya adalah menutup serangan lawan atau bersiap\r\nmenerima serangan lawan.&nbsp;Strategi pertahanan dalam bola voli dapat\r\ndilakukan dengan cara:&nbsp;</span><span style=\"font-size: 0.875rem;\"><i>Blocking,</i> yaitu teknik yang dilakukan oleh tiga pemain yang\r\nberada di antara garis serang dan net.&nbsp;<i>Blocking</i> dapat dilakukan secara\r\nperseorangan, berkelompok, atau dua orang.&nbsp;</span><span style=\"font-size: 0.875rem;\"><i>Digging</i> atau passing bawah, yaitu teknik yang dilakukan oleh\r\ntiga pemain yang berada di belakang untuk berjaga-jaga jika bola lolos dari\r\nblock.&nbsp;</span><span style=\"font-size: 0.875rem;\">Menempatkan pemain bertahan untuk mengikuti gerakan penyerang\r\nlawan secara langsung.&nbsp;</span><span style=\"font-size: 0.875rem; line-height: 107%;\">Strategi penyerangan</span><span style=\"font-size: 0.875rem; line-height: 107%;\">:&nbsp;Tujuannya adalah mematikan bola di lapangan lawan.&nbsp;</span><span style=\"font-size: 0.875rem;\">Untuk mengembangkan strategi\r\npertahanan dan penyerangan, pelatih dapat menganalisis permainan tim lawan\r\nmelalui rekaman video dan statistik.&nbsp;Analisis ini dapat digunakan untuk\r\nmembuat rencana permainan, termasuk formasi dan strategi yang akan digunakan. Di bawah ini siswa di minta untuk menentukan manakah yang termasuk pola permainan pertahanan dan penyerangan sesuai jumlah pemain depan dan belakang!&nbsp;</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:3:{i:0;a:5:{i:0;s:9:\"<p>#</p>\n\";i:1;s:32:\"<p>permainan 4 lawan&nbsp; 2</p>\";i:2;s:36:\"<p>permainan 4 lawan&nbsp; 3<br></p>\";i:3;s:36:\"<p>permainan 4 lawan&nbsp; 1<br></p>\";i:4;s:36:\"<p>permainan 5 lawan&nbsp; 4<br></p>\";}i:1;a:5:{i:0;s:38:\"<p>Strategi dan taktik pertahanan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"1\";}i:2;a:5:{i:0;s:46:\"<p>Strategi dan taktik penyerangan</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";}}}', 1729138053, 1729491275, 1, '', 1, 0, 0, '71ffa4a4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
