INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28580, 748, 0, 3, 2, NULL, NULL, NULL, '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241017133143.jpg\" style=\"width: 564.005px;\"><br></p><p>Permainan sepak bola dimainkan di lapangan oleh dua regu atau dua keseblasan yang saling berhadapan. Tujuan permainan sepak bola adalah memasukan bola ke gawang lawan sebanyak-banyaknya dan mempertahankan daerah sendiri dari serangan lawan dengan aturan tertentu. Dari pernyataan diatas tentukan ketrampilan gerak dibawah ini yang termasuk dalam ketrampilan permainan sepak bola dan ketrampilan permainan bola voli!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:3:{i:0;a:9:{i:0;s:9:\"<p>#</p>\n\";i:1;s:14:\"<p>service</p>\";i:2;s:14:\"<p>passing</p>\";i:3;s:17:\"<p>mengontrol</p>\";i:4;s:16:\"<p>menendang</p>\";i:5;s:12:\"<p>smash</p>\";i:6;s:16:\"<p>menyundul</p>\";i:7;s:12:\"<p>block</p>\";i:8;s:17:\"<p>menggiring</p>\";}i:1;a:9:{i:0;s:30:\"<p>Ketrampilan sepak bola</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"1\";i:7;s:1:\"0\";i:8;s:1:\"1\";}i:2;a:9:{i:0;s:36:\"<p>Ketrampilan bola voli</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"0\";i:7;s:1:\"1\";i:8;s:1:\"0\";}}}', 1729142571, 1729143140, 1, '', 1, 0, 0, '71ffdf1b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28581, 748, 0, 3, 3, NULL, NULL, NULL, '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241017134933.jpg\" style=\"width: 25%;\"><br></p><p>Permainan bola voli merupakan permainan beregu menggunakan bola besar yang dimainkan oleh dua regu saling berhadapan, masing-masing regu enam orang. Setiap regu diperbolehkan memainkan bola di daerah pertahanannya sebanyak-banyaknya tiga kali pukulan. Tentukan di bawah ini manakah yang termasuk ketrampilan gerak dalam permainan bola voli dan manakah yang bukan termasuk ketrampilan dalam bola voli!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:3:{i:0;a:8:{i:0;s:9:\"<p>#</p>\n\";i:1;s:16:\"<p>menendang</p>\";i:2;s:13:\"<p>servis</p>\";i:3;s:14:\"<p>passing</p>\";i:4;s:14:\"<p>menahan</p>\";i:5;s:12:\"<p>smash</p>\";i:6;s:16:\"<p>menyundul</p>\";i:7;s:12:\"<p>block</p>\";}i:1;a:8:{i:0;s:35:\"<p>Ketrampilan gerak bola voli</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"0\";i:7;s:1:\"1\";}i:2;a:8:{i:0;s:48:\"<p>Bukan ketrampilan gerak bola voli</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"1\";i:7;s:1:\"0\";}}}', 1729142572, 1729144197, 1, '', 1, 0, 0, '71ffe251-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28582, 748, 0, 3, 4, NULL, NULL, NULL, '<p><img src=\"http://asesmen.id/uploads/bank_soal/file_20241017140654.jpg\" style=\"width: 25%;\"><br></p><p>Memvoli dan memantulkan bola ke udarah harus mempergunakan bagian tubuh mana sajah, asalkan dengan pantulan yang sempurnah (tidak ganda). Ketrampilan gerak dalam permainan bola voli antara lain adalah ketrampilan gerak servis, passing, smash dan block. Tentukanlah di bawah ini pengertian ketrampilan bola voli di atas sesuai dengan pengertiannya!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:5:{i:0;s:9:\"<p>#</p>\n\";i:1;s:100:\"<p>Upaya seorang pemain untuk menyebrangkan bola melewati atas net dengan tiga kali sentuhan<br></p>\";i:2;s:146:\"<p>Upaya seorang pemain untuk menyebrangkan bola melewati atas net dari luar garis belakang lapangan yang merupakan awalan dari suatu serangan</p>\";i:3;s:74:\"<p>Usaha melakukan serangan keras yang ditujukan pada pertahanan lawan</p>\";i:4;s:50:\"<p>Upaya mengagalkan serangan dari pihak lawan</p>\";}i:1;a:5:{i:0;s:26:\"<p>Ketrampilan servis</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";}i:2;a:5:{i:0;s:34:\"<p>Ketrampilan passing</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";}i:3;a:5:{i:0;s:25:\"<p>Ketrampilan smash</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";}i:4;a:5:{i:0;s:25:\"<p>Ketrampilan block</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";}}}', 1729142574, 1729145232, 1, '', 1, 0, 0, '71ffe4bc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28583, 748, 0, 3, 5, NULL, NULL, NULL, '<p><span style=\"font-size: 0.875rem;\">Berolahraga secara rutin dapat&nbsp;meningkatkan daya tahan tubuh sehingga tubuh tidak mudah terserang penyakit. Saat berolahraga, tubuh akan lebih bebas bergerak. Hal ini akan memicu proses metabolisme dan sirkulasi darah menjadi lebih lancar. Hasilnya tubuh lebih sehat dan kuat, serta enggak mudah terserang penyakit. Aktivitas olahraga dalam permainan membutuhkan kerja sama team untuk mencapai tujuan yang diharapkanda, tentukan di bawah ini jumlah pemain dalam satu team dalam permainan bola besar!</span><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:4:{i:0;a:4:{i:0;s:9:\"<p>#</p>\n\";i:1;s:15:\"<p>6 pemain</p>\";i:2;s:14:\"<p>5 orang</p>\";i:3;s:16:\"<p>11 pemain</p>\";}i:1;a:4:{i:0;s:18:\"<p>Sepak bola</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:2;a:4:{i:0;s:24:\"<p>Bola voli</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:3;a:4:{i:0;s:19:\"<p>Bola basket</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}}}', 1729142576, 1729473591, 1, '', 1, 0, 0, '71ffe71a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
