INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28602, 783, 0, 3, 5, NULL, NULL, NULL, '<p>Talenta berbeda dengan ketertarikan. Bisa saja seseorang tertarik pada bidang tertentu, tetapi ia sebenarnya tidak memiliki talenta dibidang tersebut. contohnya seseorang yang secara alamiah tidak memiliki bakat seni, tetapi ia memiliki ketertarikan pada bidang seni tersebut sebagai penikmat semata. maka talentanya bukanlah pada pelaku&nbsp; seni. talenta tentunya bisa diasah, dilatih dan dikembangkan.&nbsp;</p><p><b>Maka terjadilah&nbsp; perbedaan antara&nbsp; talenta dan minat tersebut!</b></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:3:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:14:\"<p>Talenta</p>\";i:2;s:12:\"<p>Minat</p>\";}i:1;a:3:{i:0;s:93:\"<p>Perasaan tertarik pada sesuatu hal yang membuat sesorang ingin melakukan hal tersebut</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:116:\"<p><span style=\"font-size: 0.875rem;\">Kemampuan yang dimiliki setiap orang sejak lahir atau bakat</span></p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729150644, 1729562927, 1, '', 1, 0, 0, '71fffd99-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
