INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28610, 743, 0, 1, 25, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Walau Alkitab tidak menuliskan secara sfesifik tentang HAM, namun esensi ajaran kristiani sangat selaras dengan deklarasi HAM seperti nats ini, yaitu…&nbsp;</span></div>', '<span style=\"text-align: justify;\">Manusia adalah gambar Khaliknya&nbsp;</span>', '<span style=\"text-align: justify;\">Manusia adalah gambar ayahnya&nbsp;</span>', '<span style=\"text-align: justify;\">Manusia adalah gambar seterunya&nbsp;</span>', '<span style=\"text-align: justify;\">Manusia adalah gambar gurunya&nbsp;</span>', '<span style=\"text-align: justify;\">Manusia adalah gambar inkarnasi</span>', NULL, NULL, NULL, NULL, NULL, 'a', 1729152030, 1729152199, 1, '', 1, 0, 0, '72000d20-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28611, 743, 0, 1, 26, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Jika HAM ditegakkan akan menimbulkan harmoni di masyarakyat. Hal itu seperti yg tertulis di Kita Mazmur 133, yaitu, kecuali ....&nbsp;</span></div>', '<span style=\"text-align: justify;\">Sungguh baik dan indah&nbsp;</span>', '<span style=\"text-align: justify;\">Berdiam dengan rukun&nbsp;</span>', '<span style=\"text-align: justify;\">Seperti minyak yang baik&nbsp;</span>', '<span style=\"text-align: justify;\">Seperti embun gunung&nbsp;</span><span style=\"text-align: justify;\">Hermon</span>', '<span style=\"text-align: justify;\">&nbsp;Sehingga penuh terror dan intimidasi</span>', NULL, NULL, NULL, NULL, NULL, 'e', 1729152201, 1729152429, 1, '', 1, 0, 0, '72000e73-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28612, 743, 0, 1, 27, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Hak untuk hidup dan merasa aman, memiliki privasi, berkeluarga, hak milik pribadi, menyatakan pendapat dengan bebas merupakan ....&nbsp;</span></div>', '<span style=\"text-align: justify;\">Hak-hak Politik&nbsp;</span>', '<span style=\"text-align: justify;\">Hak-hak warga Negara&nbsp;</span>', '<span style=\"text-align: justify;\">Hak-hak ekonomi dan sosial&nbsp;</span>', '<span style=\"text-align: justify;\">Hak-hak religius&nbsp;</span>', '<span style=\"text-align: justify;\">Hak-hak gerejawi</span>', NULL, NULL, NULL, NULL, NULL, 'b', 1729152430, 1729152544, 1, '', 1, 0, 0, '7200109b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28613, 743, 0, 1, 28, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1729152548, 1729152548, 0, '', 1, 0, 0, '720011cf-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28614, 743, 0, 2, 2, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Menurut Diane Revitch dan Abigail Thernstrom dalam buku “Demokrasi Klasik dan Modern”, pada tahun 1941 Franklin Delano Roosevelt menyampaikan pidatonya yang terkenal mengenai empat kebebasan yang diharapkan dapat diberlakukan di seluruh dunia. Dari keempat kebebasan itu, dua diantaranya adalah ....</span></div>', 'a:3:{s:1:\"a\";s:67:\"<p><span style=\"text-align: justify;\">Kebebasan pers</span><br></p>\";s:1:\"b\";s:120:\"<p><span style=\"text-align: justify;\">Kebebasan berbicara dan berpendapat di mana pun juga di dunia&nbsp;</span><br></p>\";s:1:\"c\";s:166:\"<p><span style=\"text-align: justify;\">Kebebasan kepada setiap orang untuk beribadah kepada Tuhan dengan caranya sendiri di mana pun juga di dunia&nbsp;</span><br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"b\";i:1;s:1:\"c\";i:2;N;}', 1729153564, 1729153681, 1, '', 1, 0, 0, '720012fe-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28615, 743, 0, 2, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berbagai penderitaan yang dialami oleh berbagai komponen rakyat selama 30 tahun, akhirnya melahirkan kesatuan gerakan untuk menghancurkan rezim Orde Baru. Gerakan tersebut dipelopori oleh Lembaga Swadaya Masyarakat dan Mahasiswa dari seluruh Indonesia, mereka menduduki gedung DPR/MPR dan menuntut ....</span></div>', 'a:3:{s:1:\"a\";s:77:\"<p><span style=\"text-align: justify;\">Presiden Soeharto mundur</span><br></p>\";s:1:\"b\";s:69:\"<p>B. J. Habibie harus menjadi presiden menggantikan Soeharto<br></p>\";s:1:\"c\";s:106:\"<p><span style=\"text-align: justify;\">Pelaksanaan Demokrasi dan HAM diterapkan secara total</span><br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;N;}', 1729153684, 1729153852, 1, '', 1, 0, 0, '7200152b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28616, 743, 0, 2, 4, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Reformasi ini diwujudkan dalam kehidupan berpolitik dan bermasyarakat yang sifatnya menjadi lebih bebas dan terbuka (Indonesia-investment, 2013). Kebebasan dalam berpolitik, misalnya adalah kebebasan untuk mendirikan partai politik yang memiliki visi misi yang berbeda dari partai politik yang sudah ada pada kepemimpinan Soeharto. Secara lebih rinci, pencapaian Habibie dalam bidang reformasi ini adalah ....</span></div>', 'a:3:{s:1:\"a\";s:78:\"<p><span style=\"text-align: justify;\">Memberikan kebebasan pers</span><br></p>\";s:1:\"b\";s:121:\"<p><span style=\"text-align: justify;\">Pendirian partai politik dan sejumlah serikat misalnya serikat buruh</span><br></p>\";s:1:\"c\";s:277:\"<p><span style=\"text-align: justify;\">Pemilihan umum yang lebih demokratis, Pemilu Presiden dan Legislatif dilakukan secara langsung oleh rakyat selain memilih Presiden, Wakil Presiden, anggota dewan (DPR/DPRD), juga memilih anggota Dewan Perwakilan Daerah (DPD)</span><br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1729153856, 1729154117, 1, '', 1, 0, 0, '72001795-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28617, 743, 0, 2, 5, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Dalam gereja yang multikultur, setiap orang dapat belajar membangun persekutuan di atas berbagai perbedaan. Jemaat dapat belajar dari saudara seiman yang berasal dari daerah, suku, dan budaya yang berbeda. Nilai-nilai budaya dan suku yang positif dapat memperkaya liturgi dalam ibadah. Pola-pola hubungan antarjemaat yang positif juga dapat diperkaya dari nilai-nilai budaya yang beragam.\r\nAda beberapa nilai yang dapat diwujudkan dalam tindakan untuk memperkuat persatuan sebagai bangsa Indonesia yang multikultur adalah ....</span></div>', 'a:3:{s:1:\"a\";s:128:\"<p><span style=\"text-align: justify;\">Pengakuan masyarakat terhadap berbagai perbedaan dan kompleksitas kehidupan</span><br></p>\";s:1:\"b\";s:171:\"<p><span style=\"text-align: justify;\">Gereja-gereja di Indonesia memiliki anggota yang terbuka dari segi suku, budaya, bahasa, daerah asal maupun kebangsaan</span><br></p>\";s:1:\"c\";s:149:\"<p><span style=\"text-align: justify;\">Perlakuan yang sama terhadap berbagai komunitas dan budaya, baik yang mayoritas maupun minoritas</span><br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;N;}', 1729154118, 1729154260, 1, '', 1, 0, 0, '720019e4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28618, 743, 0, 3, 5, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Arti terdalam dari hak asasi manusia adalah pengakuan terhadap kebebasan dan kemerdekaan manusia yang telah dianugerahkan Tuhan Allah sejak seseorang mulai bertumbuh dalam kandungan ibu. Oleh karena itu, segala macam upaya untuk menghancurkan serta menghilangkan kehidupan serta kebebasan manusia merupakan pelanggaran terhadap hak asasi manusia. Bagaimana dengan kasus hukuman mati, aborsi, dan eutanasia?\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nBerikut ini hubungkanlah masing-masing contoh kasus tersebut dengan pengertiannya!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:4:{i:0;a:4:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"Hukuman Mati\";i:2;s:6:\"Aborsi\";i:3;s:9:\"Eutanasia\";}i:1;a:4:{i:0;s:65:\"<p>Praktik   menghilangkan janin yang ada di dalam kandungan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:2;a:4:{i:0;s:82:\"<p>Praktik yang dipilih untuk  membebaskan seseorang dari penderitaan panjang</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:3;a:4:{i:0;s:263:\"<p>Hukuman  yang  dijatuhkan  kepada  seseorang yang dianggap melakukan  kejahatan  yang  berat,  seperti  pembunuhan yang  kejam dan  sadis,  pengkhianatan  kepada  negara   (makar), dan  di  beberapa  negara, seperti Indonesia, penjual atau pembawa narkoba</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}}}', 1729155104, 1729155584, 1, '', 1, 0, 0, '72001c08-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
