INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28641, 605, 0, 5, 3, NULL, NULL, NULL, 'Apa yang Dimaksud Kebutuhan dan Keinginan? Bagaimana cara membedakannya?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Kebutuhan adalah segala sesuatu yang dibutuhkan oleh manusia untuk mempertahankan hidup dan mencapai kesejahteraan. Ini mencakup kebutuhan dasar seperti makanan, pakaian, tempat tinggal, dan layanan kesehatan. Kebutuhan juga bisa mencakup kebutuhan psikologis dan sosial seperti rasa aman, kasih sayang, dan hubungan sosial yang memadai.</div><div><br></div><div>Di sisi lain, keinginan merupakan hal-hal yang diinginkan oleh seseorang tetapi tidak penting untuk mempertahankan hidup atau mencapai kesejahteraan. Keinginan seringkali lebih bersifat subjektif dan bervariasi antara individu. Ini bisa berupa barang-barang mewah, pengalaman liburan, atau hobi yang mahal.</div>', 1729261478, 1729261617, 1, '', 1, 0, 0, '72004947-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
