INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28714, 755, 0, 1, 10, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Di suatu daerah, masyarakatnya memiliki kebiasaan tidak baik. Sampah dibuang sembarangan,saluran air tersumbat,sering banjir, dan terkesan kumuh. Pemerintah daerah setempat meminta peneliti untuk melakukan kajian bagaimana strategi yang harus ditempuh agar masyarakat memiliki kesadaran dalam menjaga kebersihan lingkungan. Strategi ini akan dituangkan dalam prioritas program kerja pemerintah daerah. Fungsi sosiologi dalam menangani masalah tersebut adalah... .&nbsp;</p>', 'Membantu pemerintah melakukan pembangunan sosial', 'Mengevaluasi proses pembangunan sosial masyarakat', 'Membantu dalam perencanaan pembangunan sosial', 'Memberikan data orang yang berperilaku tidak baik E. Menjaga kebersihan dan kenyamanan lingkungan', 'Menjaga kebersihan dan kenyamanan lingkungan', NULL, NULL, NULL, NULL, NULL, 'c', 1729472854, 1729482942, 1, '', 1, 0, 0, '7200d28c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
