INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28728, 802, 0, 1, 28, NULL, NULL, NULL, '<p>Dany: Good morning Jane, do you want an ice cream?\r\n</p><p>Jane: ………, I’d love one.\r\n</p><p>Dany: Chocolate or Strawberry?\r\n</p><p>Jane: Chocolate, please.\r\n</p><p>The suitable expression to complete the dialogue is …..</p>', '&nbsp;Yes, please ', '&nbsp;No Thanks', 'Don’t bother', 'Never mind', 'I don’t like ice cream\r\n', NULL, NULL, NULL, NULL, NULL, 'a', 1729473554, 1729473710, 1, '', 1, 0, 0, '7200fb12-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28729, 779, 0, 5, 1, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.</p><p>What is the main idea of the text?&nbsp;<br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><div><div>Christiano Ronaldo\'s&nbsp;<span style=\"font-size: 0.875rem;\">skills and determination&nbsp;</span></div></div></div></div>', 1729473655, 1729571817, 1, '', 1, 0, 0, '7200fc46-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28730, 755, 0, 1, 13, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Bacalah artikel di bawah ini dengan cermat!</p><p style=\"text-align: justify; \">\r\n\r\n \r\n\r\nAni hendak berbelanja alat tulis. Sebelum dia memutuskan dimana akan membeli alat tulis, dia memilih toko mana yang menawarkan harga paling murah dengan kualitas barang yang setara. Dia mengecek harga alat tulis yang hendak dibeli melalui katalog daring sehingga dapat membantu dia untuk memutuskan pilihannya. Akhirnya dia memilih untuk membeli alat tulis di toko C, dengan pertimbangan toko tersebut telah menawarkan harga paling rendah dengan kualitas barang yang baik.\r\n</p><p style=\"text-align: justify; \">\r\nBerdasarkan artikel tersebut, tipe tindakan sosial yang dilakukan Ani sesuai dengan teori Max Weber yaitu ......</p><p style=\"text-align: justify; \"><br></p>', 'Tindakan Rasionalitas Instrumental', 'Tindakan Rasional Nilai', 'Tindakan Afektif', 'Tindakan Tradisional', '&nbsp;Tindakan Sosial&nbsp;', NULL, NULL, NULL, NULL, NULL, 'a', 1729473658, 1729474329, 1, '', 1, 0, 0, '7200fe94-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
