INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28761, 742, 0, 3, 1, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Untk menyikapi budaya, dan dalam kaitan hidup iman, kita dapat mempelajari tulisan Richard Niebuhr tentang Kristus dan Kebudayaan (Christ and culture). Niebuhr memberikan gambaran tentang Kristus dan Kebudayaan untuk menegaskan bahwa budaya bisa didekati secara Kristiani.&nbsp;</p><p>Berdasarkan gambaran Niebuhr berikut ini, tentukanlah benar-salah dari pernyataan ini!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:137:\"<p>Kristus lawan kebudayaan (Christ againt culture), artinya dalam konteks ini semua kebudayaan dianggap bertentangan dengan Kristus</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:231:\"<p>Kristus dari kebudayaan (<span style=\"font-size: 0.875rem;\">Christ of culture</span><span style=\"font-size: 0.875rem;\">), artinya disini Kristus tidak dipersepsikan dengan budaya, tidak juga melawan kebudayaan</span></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:222:\"<p>Kristus dan kebudayaan dalam paradoks (Christ and Culture in Paradox), artinya kebudayaan yang tidak sejalan dengan iman Kristiani atau iman Kristiani bertentangan dengan budaya, sehingga harus disikapi dengan arif</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:215:\"<p>Kristus di atas kebudayaan (<span style=\"font-size: 0.875rem;\">Christ above Culture</span><span style=\"font-size: 0.875rem;\">), artinya dalam gambaran ini Kristus pun hadir dalam perjalanan kebudayaan</span></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:221:\"<p>Kristus Pengubah Kebudayaan (<span style=\"font-size: 0.875rem;\">Christ the transformer of Culture</span><span style=\"font-size: 0.875rem;\">), artinya Kristus hadir untuk memberi arah dan membarui kebudayaan</span></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729474658, 1729476740, 1, '', 1, 0, 0, '72013940-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:37', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
