INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (28880, 742, 0, 3, 3, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Hedonisme adalah sebuah gaya hidup yang mengupayakan kesenangan semata. Biasanya kesenangan tersebut diperoleh melalui berbagai uapaya, seperti menikmati hiburan berlebihan, menghamburkan dan memaerkan harta kekayaan, bahkan perilaku hidup tak terpuji. Sementara itu, gaya hidup lain sebagaimana digambarkan dalam doa Bapa Kami adalah gaya hidup sederhana, yang dikenal dengan nama ugahari. Ugahari adalah sebuah gaya hidup sederhana dan berkecukupan.</p><p>Berdasarkan pengertian hedonisme dan ugahari tersebut, berikut ini golongkanlah sikap yang sesuai dengan kedua gaya hidup tersebut!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:3:{i:0;a:7:{i:0;s:9:\"<p>#</p>\n\";i:1;s:35:\"<p>Menunjukkan gaya hidup mewah</p>\";i:2;s:45:\"<p>Terus berbelanja walau harus berhutang</p>\";i:3;s:47:\"<p>Hidup dalam kesederhanaan dan rasa cukup</p>\";i:4;s:27:\"<p>Memiliki mobil mewah</p>\";i:5;s:51:\"<p>Memenuhi kebutuhan hidup, bukan berfoya-foya</p>\";i:6;s:49:\"<p>Berinteraksi dengan orang lain dengan baik</p>\";}i:1;a:7:{i:0;s:17:\"<p>Hedonisme</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"0\";}i:2;a:7:{i:0;s:22:\"<p>Ugahari</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"1\";}}}', 1729481424, 1729484406, 1, '', 1, 0, 0, '7201d858-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
