INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29019, 786, 0, 1, 21, NULL, NULL, NULL, '<p>Perhatikan teks berikut!\r\n</p><p style=\"text-align: left;\">\r\nBencana alam adalah suatu peristiwa alam yang mengakibatkan dampak besar bagi populasi manusia. Bencana alam dapat terjadi dimana pun dan kapan pun, tak terkecuali di Indonesia. Indonesia merupakan negara kepulauan yang rawan bencana alam. Itulah sebabnya Indonesia banyak mengalami bencana alam terutama gempa bumi, gunung meletus, banjir, dan tanah longsor.\r\n</p><p>\r\nDari teks tersebut yang termasuk dalam definisi umum laporan adalah....</p>', 'Bencana alam adalah suatu peristiwa alam yang mengakibatkan dampak besar bagi populasi manusia. ', 'Bencana alam dapat terjadi di manapun dan kapan pun, tak terkecuali di Indonesia.', 'Indonesia merupakan negara kepulauan yang rawan bencana alam', 'Itulah sebabnya Indonesia banyak mengalami bencana ', 'Bencana alam di Indonesia, seperti gempa bumi, gunung meletus, banjir, dan tanah longsor.', NULL, NULL, NULL, NULL, NULL, 'a', 1729489228, 1729489445, 1, '', 1, 0, 0, '7202c34c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
