INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29027, 786, 0, 1, 23, NULL, NULL, NULL, '<p>Perhatikan teks berikut!\r\n</p><p>\r\n\r\nLingkungan RT 03 kurang bersih, karena kurangnya kesadaran masyarakatnya untuk menjaga kebersihan dan kurangnya keberadaaan fasilitas kebersihan, seperti tong sampah. Menjaga kebersihan lingkungan merupakan tanggung jawab seluruh masysrakat RT 03. Kerja sama antara pengurus RT dan masyarakat akan lebih meningkatkan upaya kebersihan lingkungan tersebut. Pengurus RT berperan dalam penyediaan fasiitas kebersihan bersinergi dengan kesadaran masyarakat dalam menjaga kebersihan lingkungan.\r\n</p><p>\r\n\r\nDari teks tersebut yang termasuk dalam definisi umum hasil analisis laporan adalah....\r\n</p>', 'Lingkungan RT 03 kurang bersih', 'Kurangnya kesadaran masyarakatnya untuk menjaga kebersihan', 'Menjaga kebersihan lingkungan merupakan tanggung jawab seluruh masyarakat RT 03', 'Kerja sama antara pengurus RT dan masyarakat akan lebih meningkatkan upaya kebersihan lingkungan tersebut.', 'Pengurus RT berperan dalam penyediaan fasilitas kebersihan bersinergi dengan kesadaran masyarakat dalam menjaga kebersihan lingkungan.', NULL, NULL, NULL, NULL, NULL, 'a', 1729489646, 1729489936, 1, '', 1, 0, 0, '7202c7a4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29028, 802, 0, 3, 2, NULL, NULL, NULL, '<p><p align=\"center\">The Importance of English\r\n</p><p>\r\n	Personally think that English is the world’s most important language. \r\nWhy I do say that?\r\n	Firstly, English is an International language. It is spoken by many \r\npeople all over the world, either as a first or second language.\r\n	Secondly, English is also the key which opens doors to scientific and \r\ntechnical knowledge, which is needed for the economic and political \r\ndevelopment of many countries in the world.\r\n	Thirdly, English is a top requirement of those seeking jobs. Applicants\r\n who master either active or passive English are more favorable than \r\nthose who don’t.\r\n	From the fact above, it is obvious that everybody needs to learn \r\nEnglish to greet the global era.\r\n\r\n\r\n</p>Based on the text above, you can choose option true or false!</p><p>English is an International language.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:3:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:15:\"<p>True<br></p>\";i:2;s:12:\"<p>False</p>\";}i:1;a:3:{i:0;s:44:\"<p>English is an International language</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:19:\"<p><br></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";}}}', 1729489738, 1729490792, 1, '', 1, 0, 0, '7202c966-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
