INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29037, 742, 0, 5, 2, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Untuk menyikapi budaya, dan dalam kaitan hidup iman, kita dapat mempelajari tulisan Richard Niebuhr tentang Kristus dan Kebudayaan. Tuliskanlah 5 pandangan atau tipologi Niebuhr tentang Kristus dan Kebudayaan!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div style=\"text-align: justify; \">Pandangan atau tipologi Richard Niebuhr tentang Kristus dan Kebudayaan:</div><ol><li style=\"text-align: justify;\">Kristus lawan Kebudayaan (Christ against Culture)</li><li style=\"text-align: justify;\">Kristus dari Kebudayaan (Christ of Culture)</li><li style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Kristus di atas Kebudayaan (Christ above Culture)</span></li><li style=\"text-align: justify;\">Kristus dan Kebudayaan dalam paradoks (Christ and Culture in paradox)</li><li style=\"text-align: justify;\">Kristus mengubah Kebudayaan (Christ the transformer of Culture)</li></ol></div>', 1729490195, 1729492365, 1, '', 1, 0, 0, '7202d1a8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
