INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29062, 785, 0, 3, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Pembangunan berkelanjutan di Indonesia ditujukan untuk mengurai angka kemiskinan dan memanfaatkan sumber daya alam secara efisien. Konsep pembangunan berkelanjutan memandang bahwa sumber daya alam merupakan bagian dari ekosisitem. Dengan menjaga fungsi ekosistem, maka kelestarian sumber daya alam akan tetap terjaga.\r\n</p><p style=\"text-align: justify; \">\r\nBerdasarkan uraian diatas, dapat disimpulkan bahwa pembangunan berkelanjutan didasari atas tiga aspek, yaitu aspek sosial, ekonomi dan lingkungan.\r\n</p><p style=\"text-align: justify; \">\r\nTentukanlah manakah yang termasuk dalam aspek sosial, aspek ekonomi, dan aspek lingkungan.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:10:{i:0;a:4:{i:0;s:9:\"<p>#</p>\n\";i:1;s:17:\"Aspek Lingkungan \";i:2;s:13:\"Aspek Sosial \";i:3;s:14:\"Aspek Ekonomi \";}i:1;a:4:{i:0;s:31:\"<p>Pengentasan Kemiskinan </p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:2;a:4:{i:0;s:19:\"<p>Pertumbuhan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:3;a:4:{i:0;s:29:\"<p>Integritas ekosistem </p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:4;a:4:{i:0;s:42:\"<p>Sumber daya manusia berkelanjutan </p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:5;a:4:{i:0;s:19:\"<p>Pemerataan </p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:6;a:4:{i:0;s:37:\"<p>Pelestarian lingkungan hidup </p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:7;a:4:{i:0;s:19:\"<p>Kelembagaan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}i:8;a:4:{i:0;s:18:\"<p>Stabilitas</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:9;a:4:{i:0;s:30:\"<p>Pencegahan pencemaran </p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}}}', 1729491527, 1729679441, 1, '', 1, 0, 0, '7202f077-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29063, 802, 0, 3, 6, NULL, NULL, NULL, '<p align=\"center\">The Importance of English\r\n</p><p>\r\n	Personally think that English is the world’s most important language. \r\nWhy I do say that?\r\n	Firstly, English is an International language. It is spoken by many \r\npeople all over the world, either as a first or second language.\r\n	Secondly, English is also the key which opens doors to scientific and \r\ntechnical knowledge, which is needed for the economic and political \r\ndevelopment of many countries in the world.\r\n	Thirdly, English is a top requirement of those seeking jobs. Applicants\r\n who master either active or passive English are more favorable than \r\nthose who don’t.\r\n	From the fact above, it is obvious that everybody needs to learn \r\nEnglish to greet the global era.\r\n\r\n\r\n</p><p>Based on the text above, you can choose option true or false!</p><p>English is not most important language in the world’s . </p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:3:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:15:\"<p>True<br></p>\";i:2;s:16:\"<p>False<br></p>\";}i:1;a:3:{i:0;s:70:\"<p>English is not most important language in the world&rsquo;s . </p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:19:\"<p><br></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";}}}', 1729491593, 1729492013, 1, '', 1, 0, 0, '7202f30a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
