INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29092, 786, 0, 5, 6, NULL, NULL, NULL, 'Apa pesan yang ingin disampaikan komikus melalui komik <b>“Yang Penting Keren”</b>?&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Apa yang kita lihat di dunia nyata merupakan sesuatu yang fana.<br>', 1729493152, 1729493208, 1, '', 1, 0, 0, '72031a1e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29094, 786, 0, 5, 7, NULL, NULL, NULL, '<p>Suatu anekdot dibentuk oleh orientasi, komplikasi, dan evaluasi.\r\n</p><p>\r\nOrientasi, adalah bagian anekdot yang berisi pengenalan kondisi atau karakter tokoh, penggambaran hal – hal terkait dengan apa, kapan, di mana, siapa, mengapa, bagaimana, dan Gambaran tentang masalah yang akan dihadapi.\r\n</p><p>\r\n \r\n\r\nBerikan salah satu contoh kalimat orientasi dari teks bacaan “Liburan Kuli Bangunan”.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Perkenalkan saya Didi. Disini ada kuli banguna? Wah, berarti saya satu – satunya ya disini. Ngomong – ngomong soal liburan, buat kebanyakan orang, liburan itu obat stres, tapi buat saya malah bikin stres. Datang liburan orang – orang nyiapin rencana mau liburan ke mana. Saya malah sibuk nyari alasan.<br>', 1729493212, 1729493383, 1, '', 1, 0, 0, '72031afb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29095, 804, 0, 1, 4, NULL, NULL, NULL, '<p>Penyebab terjadinya pemberontakan Andi Azis di Makasar adalah…. <br></p>', '&nbsp;Adanya dukungan dari pihak luar\r\n', '&nbsp;Lemahnya pemerintahan RI\r\n', 'Menentang TNI masuk ke Makasar\r\n', '&nbsp;Keinginan mendirikan Negara sendiri\r\n', 'Rasa tidak puas terhadap pemerintah RI 17\r\n', NULL, NULL, NULL, NULL, NULL, 'c', 1729493288, 1729493979, 1, '', 1, 0, 0, '72031d71-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29098, 786, 0, 5, 8, NULL, NULL, NULL, 'Masalah yang dihadapi Didin adalah?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>&nbsp;-Sulitnya menyusun rencana liburan </p><p>-Tidak punya cukup uang untuk liburan </p><p>-Banjir di Jakarta&nbsp;</p><p>-Anak yang jarang liburan </p><p>-Anak yang ingin menjadi kuli bangunan ·</p><p>-Kurangnya kesempatan liburan<br></p>', 1729493389, 1729493470, 1, '', 1, 0, 0, '72031ebd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29099, 786, 0, 5, 9, NULL, NULL, NULL, 'nsur humor yang terdapat pada teks <b>“Liburan Kuli Bangunan”</b> adalah? ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>-Penyampaian monolog dengan gaya stand-up comedy</p><p>-Penggunaan dialog lucu antara komika, anak, dan istri</p><p><span style=\"font-size: 0.875rem;\">-Pembuatan situasi kocak dengan kontras antara harapan liburan dan kenyataan</span></p><p><span style=\"font-size: 0.875rem;\">- Pemilihan kata-kata kocak pada jawaban</span></p>', 1729493479, 1729493599, 1, '', 1, 0, 0, '72031fc6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29101, 786, 0, 5, 10, NULL, NULL, NULL, 'Apa pesan yang ingin disampaikan melalui monolog tersebut?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '&nbsp;Liburan bisa menjadi sumber stres, terutama bagi mereka yang tidak memiliki cukup uang atau kesempatan untuk liburan. Selain itu, kebahagiaan tidak selalu bergantung pada tempat atau hal-hal mewah.<br>', 1729493607, 1729493654, 1, '', 1, 0, 0, '720320a9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29124, 792, 0, 5, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Nilai estetis</span><span style=\"font-size: 0.875rem;\">, identik dengan keindahan dan keunikan sebuah karya seni rupa. nilai estetis sebuah karya seni rupa terutama dipengaruhi oleh keharmonisan dan keselarasan penataan unsur-unsur rupanya. nilai estetis dapat juga bersifat subjektif sesuai dengan selera orang melihatnya. pengalaman pribadi, lingkungan dan budaya di mana seseorang tinggal dapat menyebabkan nilai estetis sebuah karya seni rupa berbeda antara satu orang dengan orang lainnya.</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Sebuah karya seni rupa menjadi indah dan unik karena...</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><div style=\"text-align: justify; \">kemampuan perupanya memilih dan memvisualisasikan objek pada bidang garapannya melalui pengolahan unsur-unsur</div></div></div>', 1729499820, 1729501916, 1, '', 1, 0, 0, '72032227-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
