INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29130, 792, 0, 5, 2, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Berkarya seni rupa dua dimensi adalah kegiatan(proses) menggunakan alat dan bahan tertentu melaui ketrampilan teknik berkarya seni rupa untuk memvisualisasikan gagasan, pikiran dan atau perasaan seorang perupa pada bidang dua dimensi.</p><p>Sebutkan sketsa proses berkarya...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>1. mencari ide atau gagasan berkarya</div><div>2. menemukan ide atau gagasan berkarya</div><div>3. menuangkan ide atau gagasan berkarya ke dalam sketsa</div><div style=\"text-align: justify; \">4. memindahkan sketsa ke atas kanvas</div><div>5. mempresentasikan karya seni</div></div>', 1729500398, 1729501900, 1, '', 1, 0, 0, '720325d4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
