INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29136, 792, 0, 5, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Karya seni rupa tiga dimensi merupakan karya seni yang memiliki ukuran panjang, lebar dan tinggi, sehingga karya dapat dilihat dari segala arah. Simbol merupakan makna yang dikandung dalam karya seni rupa baik dalam wujudnya obyeknya maupun unsur-unsur rupanya.</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berdasarkan fungsinya, karya seni rupa tiga dimensi dibedakan menjadi 2 yaitu...</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>1. karya yang memiliki fungsi pakai (seni rupa terapan - applied art) dan</div><div style=\"text-align: justify; \">2. karya seni rupa yang hanya memiliki fungsi ekspresi saja (seni rupa murni - pure art)</div>', 1729500746, 1729501137, 1, '', 1, 0, 0, '720329f0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29137, 786, 0, 3, 5, NULL, NULL, NULL, 'Identifikasikanlah masalah yang dihadapi Didin dalam monolog <b>“Liburan Kuli Bangunan”</b>.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:8:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:41:\"<p>Sulitnya menyusun rencana liburan</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:43:\"<p>Keinginan anak untuk pergi ke Dufan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:44:\"<p>Tidak punya cukup uang untuk liburan</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:34:\"<p>Noraknya anak dan keluarga</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:45:\"<p>Anak yang ingin menjadi kuli bangunan</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:6;a:3:{i:0;s:55:\"<p>Penyampaian monolog dengan gaya stand-up comedy</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:7;a:3:{i:0;s:36:\"<p>Kurangnya kesempatan liburan</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729500774, 1729749160, 1, '', 1, 0, 0, '72032ad2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29140, 792, 0, 5, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Karya seni rupa tiga dimensi merupakan karya seni yang memiliki ukuran panjang, lebar dan tinggi, sehingga karya dapat dilihat dari segala arah. Simbol merupakan makna yang dikandung dalam karya seni rupa baik dalam wujudnya obyeknya maupun unsur-unsur rupanya. salah satu karya seni rupa tiga dimensi adalah patung. karya seni patung memiliki berbagai ragam dan jenis yang tersusun dari berbagai medium pula.</p><p>\r\n\r\nLangkah - langkah mewujudkan karya seni rupa tiga dimensi adalah...\r\n\r\n</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div style=\"text-align: justify; \">1. mencari dan menemukan ide</div><div>2. membuat sketsa</div><div>3. memilih alat dan bahan</div><div>4. berkarya patung</div>', 1729501138, 1729501510, 1, '', 1, 0, 0, '72032c47-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29141, 792, 0, 5, 5, NULL, NULL, NULL, '<p>Karya seni rupa tiga dimensi beraneka jenis dan ragamnya. karya seni rupa tiga dimensi dapat dikelompokan berdasarkan bahan, teknik pembuatan, gaya perwujudan, tema, fungsi, dan sebagainya.</p><p style=\"text-align: justify; \">Nilai estetis karya seni rupa tiga dimensi tampak secara visual dari wujud karya seni rupa tersebut. nilai objektif terdapat pada karya seni rupa itu sendiri, sedangkan nilai subjektif berada pada penikmatnya.</p><p>Nilai estetis karya seni rupa bersifat...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>objektif dan subjektif</div>', 1729501514, 1729501864, 1, '', 1, 0, 0, '72032d47-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29142, 792, 0, 3, 1, NULL, NULL, NULL, '<p><span style=\"text-align: justify;\">Berkarya seni rupa dua dimensi adalah kegiatan(proses) menggunakan alat dan bahan tertentu melaui ketrampilan teknik berkarya seni rupa untuk memvisualisasikan gagasan, pikiran dan atau perasaan seorang perupa pada bidang dua dimensi. nilai estetis, identik dengan keindahan dan keunikan sebuah karya seni rupa. nilai estetis sebiah karya seni rupa terutama dipengaruhi oleh keharmonisan dan keselarasan penataan unsur-unsur rupanya.</span></p><p style=\"text-align: justify; \">Berdasarkan bahannya, seni yang sesuai dengan ragam karya seni rupa dua dimensi adalah...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:19:\"<p>kriya kulit</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:24:\"<p>seni ukir</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:19:\"<p>kriya logam</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:18:\"<p>kriya kayu</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729501922, 1729502587, 1, '', 1, 0, 0, '72032ed8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29143, 792, 0, 3, 2, NULL, NULL, NULL, '<p><span style=\"font-size: 0.875rem; text-align: justify;\">Nilai estetis</span><span style=\"font-size: 0.875rem; text-align: justify;\">, identik dengan keindahan dan keunikan sebuah karya seni rupa. nilai estetis sebuah karya seni rupa terutama dipengaruhi oleh keharmonisan dan keselarasan penataan unsur-unsur rupanya. nilai estetis dapat juga bersifat subjektif sesuai dengan selera orang melihatnya. pengalaman pribadi, lingkungan dan budaya di mana seseorang tinggal dapat menyebabkan nilai estetis sebuah karya seni rupa berbeda antara satu orang dengan orang lainnya.</span></p><p style=\"text-align: justify; \">Tentukan pernyataan yang sesuai dengan narasi di atas</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:4:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:59:\"<p>Nilai estetis identik dengan keindahan dan keunikan</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:80:\"<p>Karya seni rupa menjadi indah dan unik karena perupa sangat hebat</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:51:\"<p>Nilai estetis dapat juga bersifat subjektif</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729502622, 1729503197, 1, '', 1, 0, 0, '7203307e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
