INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29244, 755, 0, 1, 38, NULL, NULL, NULL, '<p>Perhatikan ciri-ciri sosiologi berikut!\r\n</p><p>\r\n(1) Hasil pengamatan terhadap realitas sosial yang tidak asal-asalan.</p><p>\r\n\r\n(2) Hasil pengamatan disusun dalam bentuk abstraksi.</p><p>\r\n\r\n(3) Realitas sosial bisa diprediksi atau diperkirakan.\r\n</p><p>\r\n(4) Realitas sosial dianalisa tanpa mempersoalkan baik buruknya fakta.\r\n</p><p>\r\n(5) Teori sosiologi berdiri sendiri tanpa mengaitkan dengan teori sebelumnya.</p><p><span style=\"font-size: 0.875rem;\">&nbsp;Dari pernyataan di atas, yang termasuk ciri-ciri sosiologi sebagai ilmu pengetahuan adalah...</span></p><p>\r\n\r\nA.&nbsp;</p><p>\r\n\r\nB.&nbsp;</p><p>\r\n\r\nC.</p><p>\r\n\r\nD.</p><p>\r\n\r\nE.&nbsp;</p><p>\r\nJawaban: B. (1), (2), dan (4)</p>', '(1), (2), dan (3)', '(1), (2), dan (4)', '&nbsp;(1), (3), dan (5)', '&nbsp;(2), (4), dan (5)', '(3), (4), dan (5)', NULL, NULL, NULL, NULL, NULL, 'b', 1729560083, 1729560372, 1, '', 1, 0, 0, '7204532a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
