INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29271, 800, 0, 4, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Jaringan merupakan kumpulan komputer yang saling berhubungan melalui beberapa cara dengan tujuan berbagi data dan transfer informasi. Jaringan komputer dibangun agar informasi yang dibawa pengirim dapat sampai kepada penerima dengan tepat dan akurat. Jaringan komputer memungkinkan penggunanya dapat melakukan komunikasi satu sma lain dengan mudah. Selain itu, peran jaringan komputer sangat diperlukan untuk mengintegrasi data antarkomputer client sehingga diperoleh suatu data yang relevan.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nDalam ilmu komputer biasanya penerima disebut .....</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Receiver', 1729561572, 1729561610, 1, '', 1, 0, 0, '72049f4c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29272, 800, 0, 4, 2, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Jaringan merupakan kumpulan komputer yang saling berhubungan melalui beberapa cara dengan tujuan berbagi data dan transfer informasi. Jaringan komputer dibangun agar informasi yang dibawa pengirim dapat sampai kepada penerima dengan tepat dan akurat. Jaringan komputer memungkinkan penggunanya dapat melakukan komunikasi satu sma lain dengan mudah. Selain itu, peran jaringan komputer sangat diperlukan untuk mengintegrasi data antarkomputer client sehingga diperoleh suatu data yang relevan.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nDalam ilmu komputer biasanya pengirim disebut .....</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Transmitter', 1729561610, 1729561692, 1, '', 1, 0, 0, '7204a37d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
