INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29274, 800, 0, 4, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Menjaga informasi agar tetap up-to-date dan andal. Dengan adanya jaringan komputer melalui sistem penyimpangan data yang terpusat, maka pengguna dapat mengakses data dari berbagai tempat yang berbeda, juga dapat membatasi akses data tertentu sewaktu data tersebut sedang diproses. </span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Sistem penyimpangan data yang terpusat terdapat pada .....</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Komputer Server', 1729561693, 1729561802, 1, '', 1, 0, 0, '7204ad55-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29275, 800, 0, 4, 4, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Orang yang terhubung ke jaringan sering berharap untuk bisa berkomunikasi dengan orang lain yang terhubung ke jaringan lainnya. Keinginan seperti ini memerlukan hubungan antarjaringan yang seringkali tidak kompatibel dan berbeda. Kumpulan jaringan yang saling terhubung. Komunikasi yang tidak bisa dilakukan dengan jaringan yang menggunakan kabel. Jaringan tanpa kabel lebih leluasa bergerak dalam melakukan aktivitas komunikasi.\r\n</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nJenis jaringan yang terdapat dalam uraian diatas disebut ....</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Internet', 1729561802, 1729561940, 1, '', 1, 0, 0, '7204b074-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29276, 755, 0, 3, 1, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"margin-bottom: 18pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Pilhlah&nbsp; Jawaban yang tepat&nbsp; pada pernyataan berikut ini... </p><p class=\"MsoNormal\" style=\"margin-bottom: 18pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Sosiologi klasik yang sangat terkenal yaitu Karl Marx (1818) yang lahir di Jerman dan hidup di berbagai Negara Eropa. Karl marx&nbsp; melahirkan beberapa pemikiran dalam ilmu sosial yang menjelaskan tentang.....</p><p class=\"MsoNormal\" style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 18pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; line-height: normal;\"><font color=\"#111827\" face=\"Arial, sans-serif\"><span style=\"font-size: 18px;\">&nbsp;</span></font></p><p class=\"MsoNormal\" style=\"margin-bottom: 18pt; line-height: normal; backgro