INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29289, 790, 0, 3, 1, NULL, NULL, NULL, '<p style=\"text-align: center;\"><span style=\"font-weight: bolder;\">JATIM PARK</span></p><p style=\"text-align: justify;\">For people in East Java, Jatim Park may have been heard many times as it is one of the famous tourism object in East Java province. Jatim Park offers a recreation place as well as a study center.</p><p style=\"text-align: justify;\">Jatim Park is located at Jl. Kartika 2 Batu, East Java. To reach the location is not too difficult because the object is only 2,5 kilos meters from Batu city. This Jatim Park tourism object is about 22 hectares width.</p><p style=\"text-align: justify;\">Visitor can enjoy at least 36 kinds of facilities which can attract them as well as give new knowledge. Just after the pass gate, the visitors will find an interesting view of&nbsp;<span style=\"font-weight: bolder;\">Galeri Nusantara</span>&nbsp;area. This study offering continues to step on&nbsp;<span style=\"font-weight: bolder;\">Taman Sejarah</span>&nbsp;area, which contains of miniature temple in East Java like Sumberawan temple, customhouse of Kiai Hasan Besari Ponorogo and Sumberawan Statue.</p><p style=\"text-align: justify;\">The other facility which is able to be enjoyed is&nbsp;<span style=\"font-weight: bolder;\">Agro Park</span>&nbsp;area. It presents crop and rareness fruits, animal diorama which consists of unique animals that have been conserved, and supporting games like bowling, throw ball, scooter disco, etc.</p><p style=\"text-align: justify;\">Jatim Park is suitable for family and school recreation. The recreation area sites offer precious tour and can used as alternative media of study.</p><p style=\"text-align: justify;\">Find out the difficult words and write down the meaning?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:11:{i:0;a:11:{i:0;s:9:\"<p>#</p>\n\";i:1;s:17:\"<p>Pengunjung</p>\";i:2;s:14:\"<p>Menarik</p>\";i:3;s:12:\"<p>Panen</p>\";i:4;s:12:\"<p>Waktu</p>\";i:5;s:12:\"<p>Sulit</p>\";i:6;s:19:\"<p>Buah langkah</p>\";i:7;s:15:\"<p>Terkenal</p>\";i:8;s:12:\"<p>Candi</p>\";i:9;s:19:\"<p>Menyenangkan</p>\";i:10;s:18:\"<p>Pengetahuan</p>\";}i:1;a:11:{i:0;s:13:\"<p>Times</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";i:6;s:1:\"0\";i:7;s:1:\"0\";i:8;s:1:\"0\";i:9;s:1:\"0\";i:10;s:1:\"0\";}i:2;a:11:{i:0;s:21:\"<p>Famous</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";i:7;s:1:\"1\";i:8;s:1:\"0\";i:9;s:1:\"0\";i:10;s:1:\"0\";}i:3;a:11:{i:0;s:17:\"<p>Difficult</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";i:6;s:1:\"0\";i:7;s:1:\"0\";i:8;s:1:\"0\";i:9;s:1:\"0\";i:10;s:1:\"0\";}i:4;a:11:{i:0;s:15:\"<p>Visitor</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";i:7;s:1:\"0\";i:8;s:1:\"0\";i:9;s:1:\"0\";i:10;s:1:\"0\";}i:5;a:11:{i:0;s:17:\"<p>Knowledge</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";i:7;s:1:\"0\";i:8;s:1:\"0\";i:9;s:1:\"0\";i:10;s:1:\"1\";}i:6;a:11:{i:0;s:15:\"<p>Attract</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";i:7;s:1:\"0\";i:8;s:1:\"0\";i:9;s:1:\"0\";i:10;s:1:\"0\";}i:7;a:11:{i:0;s:19:\"<p>Interesting</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";i:6;s:1:\"0\";i:7;s:1:\"0\";i:8;s:1:\"0\";i:9;s:1:\"1\";i:10;s:1:\"0\";}i:8;a:11:{i:0;s:12:\"<p>Crop</p>\n\";i:1;s:1:\"0\";i:2;s:1: