INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29342, 788, 0, 1, 16, NULL, NULL, NULL, '<p>Bacalah paragraf berikut.</p><p>\r\nBalai Konservasi Sumber Daya Alam (BKSDA) Sulawesi Tenggara menyurvei dua satwa endemik Sulawesi, yakni anoa dan burung maleo. Aktivitas itu dimaksudkan untuk mengetahui jumlah pasti populasi kedua hewan dilindungi tersebut. Survei menggunakan metode sampling di kawasan suaka margasatwa Tanjung Peropa dan Buton Utara.\r\n</p><p>\r\nPerbedaan penyajian kedua kutipan berita tersebut adalah …</p>', 'Teks berita I diawali dengan apa, sedangkan berita II diawali dengan di mana  ', 'Teks berita I diawali dengan apa, sedangkan berita II diawali dengan siapa', 'Teks berita I diawali dengan kapan, sedangkan berita II diawali dengan siapa', 'Teks berita I diawali dengan kapan, sedangkan berita II diawali dengan apa', 'Teks berita I diawali dengan dimana, sedangkan berita II diawali dengan apa', NULL, NULL, NULL, NULL, NULL, 'b', 1729565411, 1729565779, 1, '', 1, 0, 0, '720552e7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29343, 789, 0, 1, 16, NULL, NULL, NULL, '<p><b>Bacalah teks berikut dengan saksama!\r\n</b></p><p><b><br></b>\r\nSatilawati: (merasa kasihan) Maafkanlah segala perkataanku yang kemarin itu, </p><p>Kartili. Jangan dimasukkan ke dalam hati.\r\n</p><p>\r\nKartili: (tersenyum) Tentu tidak,&nbsp;<span style=\"font-size: 0.875rem;\">Satilawati. Aku mengerti keadaanmu kemarin itu. Sekarang, aku memuji kesetiaanmu terhadap Ishak. Walau telah engkau ketahui bahwa ia ...\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\nSatilawati: Tapi ada sesuatu, suara halusku mengatakan bahwa ia akan baik lagi. Baik buat selama-lamanya.\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\nKartili: Itu yang kuhargakan tinggi, Satilawati, kepercayaanmu kepada diri sendiri.\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\nSatilawati: Biarpun ia tidak baik kembali, aku tidak juga dapat mengikatkan diriku kepada orang lain.&nbsp;</span></p><p><span style=\"font-size: 0.875rem;\">Alur yang terkandung dalam kutipan tersebut adalah ...</span></p>', 'pengenalan', 'munculnya konflik', 'konflik mulai memuncak', 'puncak konflik', 'penyelesaian', NULL, NULL, NULL, NULL, NULL, 'e', 1729565437, 1729749822, 1, '', 1, 0, 0, '720555e7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29344, 789, 0, 1, 17, NULL, NULL, NULL, '<p><b>Bacalah teks berikut dengan saksama!</b>\r\n</p><p>\r\n \r\n\r\n(Panggung menggambarkan sebuah kamar reot. Di dalamnya terdapat sebuah dipan dan dua buah kursi yang sudah rusak pula. Suasana kemiskinanlah yang tampil di situ)\r\n</p><p>\r\n \r\n\r\nIstri: (mengharap) Banyakkah hasil yang kauterima hari ini?\r\n</p><p>\r\nSuami: Bah, kosong sama sekali,s eperempat rupiah pun tak dapat, dan kau bagaimana?\r\n</p><p>\r\nIstri: Ada seorang wanita muda memberi makan kepada kita.\r\n</p><p>\r\nSuami: Terima kasih, moga-moga Tuhan memberkahinya. Apa yang diberikannya?\r\n</p><p>\r\nIstri: Sepotong roti\r\n</p><p>\r\nSuami: Kalau begitu, masih adakah simpanan untuk esok pagi?\r\n</p><p>\r\nIstri: Masih, tetapi hanya untuknya\r\n</p><p>\r\nSuami: Tak ada yang lain? Ah, maksudku selain dari roti itu\r\n</p><p>\r\nIstri: Ada. Sepotong nasihat, supaya jangan membawa anak itu keluar karena udahara terlalu lembap</p><p><span style=\"font-size: 0.875rem;\">Konflik yang diungkapkan dalam kutipan naskah drama tersebut adalah ...</span></p>', 'pekerjaan yang dilakukan setiap hari oleh manusia', 'harapan seorang pengemis terhadap masa depannya', 'penghasilan sepasang pengemis yang tidak memadai', 'pertanyaan seorang suami kepada istri dan anaknya', 'suami istri saling menasihati dan menyayangi', NULL, NULL, NULL, NULL, NULL, 'c', 1729565598, 1729749831, 1, '', 1, 0, 0, '720558d6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29345, 789, 0, 1, 18, NULL, NULL, NULL, '<p><b>Bacalah teks cuplikan drama berikut dengan saksama!</b>\r\n</p><p>\r\n \r\n\r\nSore itu, seorang ibu menggendong anaknya yang berusia sembilan bulan ke tempat praktik Dokter Wira.\r\n</p><p>\r\nDokter: Putra Ibu sakit apa? (menyilakan ibu itu duduk di kursi di hadapannya)\r\n</p><p>\r\nIbu: Tidak sakit, Dok. Hanya perlu imunisasi\r\n</p><p>\r\nDokter: O, imunisasi apa, Bu?\r\n</p><p>\r\nIbu: Campak, Dok, karena anak saya sudah 9 bulan\r\n</p><p>\r\nDokter: Wah, Ibu termasuk ibu yang baik. Selalu memperhatikan kebutuhan putranya\r\n</p><p>\r\nIbu: Ah, Dokter bisa saja!\r\n</p><p>\r\nDokter: Ya, karena kadangan-kadang seorang ibu lupa akan perlunya imunisasi lengkap bagi anaknya, padahal imunisasi itu penting</p><p>Latar kutipan drama tersebut adalah ...</p>', 'posyandu', 'rumah sakit', 'puskesmas', 'tempat praktik dokter', 'Unit Gawat Darurat (UGD)', NULL, NULL, NULL, NULL, NULL, 'd', 1729565726, 1729566171, 1, '', 1, 0, 0, '72055c0a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29346, 788, 0, 1, 17, NULL, NULL, NULL, '<p>Musim kemarau yang cukup panjang tahun ini mulai membawa dampak. Para peternak sapi potong mulai resah karena kesulitan untuk memperoleh rumput. Rumput sulit didapatkan karena kekurangan air yang menyebabkan rumput meranggas. Kekurangan ladang rumput tersebut menjadi penyebab minimnya jumlah populasi sapi potong di Jawa Tengah.\r\n</p><p>\r\nUnsur apa yang disampaikan dalam teks berita di atas adalah ...</p>', 'Musim kemarau yang cukup panjang terjadi di tahun ini', 'Para peternak sapi potong mulai resah karena kesulitan memperoleh rumput', 'Kekurangan air menyebabkan rumput meranggas', 'Jumlah populasi sapi potong semakin menurun', 'Ladang rumput semakin berkurang karena kekurangan air', NULL, NULL, NULL, NULL, NULL, 'b', 1729565830, 1729566257, 1, '', 1, 0, 0, '72055ee7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29347, 790, 0, 3, 4, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Ki Hadjar Dewantoro, original name Raden Mas (Lord) Suwardi Surjaningrat (born May 2, 1889, Yogyakarta, Javadied April 26, 1959, Yogyakarta), founder of the Taman Siswa school system, an influential and widespread network of schools that encouraged modernization but also promoted indigenous Indonesian culture.</p><p style=\"text-align: justify;\">Dewantoro was born into a noble family of Yogyakarta and attended a Dutch-sponsored medical school but failed to complete the course. Active in the nationalist cause, he belonged to a faction favouring direct action and the use of Western methods to destroy the power of the Dutch. He was also a member of the Bandung chapter of Sarekat Islām (Islamic Association) and a founder of the Socialist Indische Partij (Indies Party). An article he wrote during this period, If I Were a Netherlander, published in the Indische Partij De Express, led to his exile to the Netherlands between 1913 and 1918.</p><p style=\"text-align: justify;\">In the Netherlands he became converted to the idea of using Indonesian cultural traditions to cope with the problems posed by Dutch colonial rule. He felt that education was the best means to strengthen Indonesians, and he was deeply influenced by the progressive theories of the Italian educational reformer Maria Montessori and by the Indian poet and philosopher Rabindranath Tagore.</p><p style=\"text-align: justify;\">The first Taman Siswa schools were established in Java in July 1922. Instruction, carried on informally, emphasized traditional skills and values of Javanese life, particularly music and dance. Western subjects were taught, too, in order to help students cope with the demands of modern life. Overcoming initial official hostility, the Taman Siswa schools had spread throughout the archipelago and were by the late 1930s subsidized by the Dutch colonial government. Based on traditional Javanese concepts, the Taman Siswa schools appealed primarily to those segments of Indonesian society termed abangan, in which the Islamic faith is less deeply entrenched. Dewantoro continued his leadership of Taman Siswa after the war and upon his death was acclaimed a national hero.</p><p style=\"text-align: justify;\">Identify where is TRUE or FALSE about Taman Siswa?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:11:\"<p>True</p>\";i:2;s:12:\"<p>False</p>\";}i:1;a:3:{i:0;s:98:\"<p><span style=\"text-align: center;\">Ki Hajar Dewantoro was founder of Taman Siswa</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:103:\"<p><span style=\"text-align: center;\">The 1st Taman Siswa was established in 1922</span><br></p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:113:\"<p><span style=\"text-align: center;\">In 1930 the Dutch colonial government subsidized Taman Siswa</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:99:\"<p><span style=\"text-align: center;\">Western subject was prohibited for Taman Siswa</span><br></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1729565923, 1729570854, 0, '', 1, 0, 0, '720561a1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29348, 789, 0, 1, 19, NULL, NULL, NULL, '<p>Perhatikan dialog berikut dengan saksama!\r\n\r\nDokter: Putra Ibu sakit apa? (menyilakan ibu itu duduk di kursi di hadapannya)</p><p>     Perubahan kalimat langsung tersebut menjadi kalimat tak langsung yang tepat adalah ...</p>', 'Setelah mempersilakan dokter untuk duduk di hadapannya, ibu bertanya kepada dokter, anak dokter sakit apa', 'Dokter menyilakan ibu itu duduk di hadapannya dan bertanya kepada anak dokter', 'Setelah menyilakan ibu itu duduk di hadapannya, dokter bertanya anak ibu itu sakit apa', 'Dokter bertanya kepada anak ibu itu apakah ibunya sakit setelah dipersilakan duduk', 'Ibu bertanya kepada anaknya apakah dirinya sakit setelah dipersilakan duduk oleh dokter saat datang ke klinik', NULL, NULL, NULL, NULL, NULL, 'c', 1729566211, 1729566311, 1, '', 1, 0, 0, '72056515-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29349, 788, 0, 1, 18, NULL, NULL, NULL, '<p><b>Teks A</b></p><p>\r\n\r\nPesawat jenis PAC 750 XL milik PT. Komala Indonesia mengalami kecelakaan saat lepas landas di Bandara Perintis Ninia di Distrik Ninia, Kabupaten Yahukimo, Papua. Kecelakaan terjadi sekitar pukul 08.45, Rabu (11/8/2015). Tidak ada korban jiwa, namun sebanyak lima orang terluka dalam musibah tersebut. Pesawat mengalami masalah saat lepas landas sehingga menabrak rumah warga yang berada di ujung landasan. “Pesawat menabrak rumah warga,” kata Kepala Bidang Humas Polda Papua, Kombes Polisi Patridge Renwarin. Sebanyak empat orang mengalami luka ringan, sedangkan pilot Hermantiono mengalami pingsan. Para korban segera dievakuasi ke RS Wamena dengan menggunakan pesawat Dimoni.\r\n</p><p><b>\r\n \r\n\r\nTeks B\r\n</b></p><p>\r\nJet tempur F-16 milik TNI AU mengalami kecelakaan di Landasan Udara (Lanud) Iswahyudi Madiun, Rabu (24/6/2015). Kecelakaan disebabkan masalah teknis. Badan pesawat mengalami lecet-lecet sehingga masih bisa digunakan. “Hanya emergency saja. Saat mau mendarat sudah normal. Sudah berhenti tapi roda masuk lagi,” ujar Kadispenau Marsma Dwi Badarmanto. Peristiwa tersebut berawal saat pilot sedang menggelar latihan rutin.\r\n\r\nPilot berangkat selepas subuh dan hendak mendarat sekitar pukul 06.30 WIB. Tidak ada korban jiwa dalam musibah ini. Pilot pun dalam kondisi baik. Setelah menyentuh landasan, tiba-tiba roda masuk kembali ke dalam badan pesawat.</p><p>Perbedaan di antara kedua teks berita di atas adalah sebagai berikut, kecuali ...<br></p><p>\r\n\r\n </p>', 'Teks A : kecelakaan pesawat sipil, Teks B : kecelakaan pesawat militer ', 'Teks A : terdapat korban luka, Teks B : tidak terdapat korban luka', 'Teks A : terjadi di Pulau Papua, Teks B : terjadi di Pulau Jawa', 'Teks A : kecelakaan terjadi siang hari, Teks B : kecelakaan terjadi pagi hari', 'Teks A : pilot tidak sadarkan diri, Teks B : pilot sadarkan diri', NULL, NULL, NULL, NULL, NULL, 'd', 1729566261, 1729566474, 1, '', 1, 0, 0, '72056720-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29350, 789, 0, 1, 20, NULL, NULL, NULL, '<p><b>Bacalah teks drama berikut dengan saksama! </b></p><p><b><br></b>(masuk Mintarsih, seorang anak gadis yang tampak riang. Ia membawa sesuatu yang tampaknya untuk keperluan hari nya besok)\r\n</p><p>\r\nMintarsih: Ah! Sudah berbuka puasa semuanya?\r\n</p><p>\r\nIbu: Tadi, kami menunggu kau, tapi lama benar? (Mintarsih bergerak mendekati jendela, lalu melongokkan kepalanya melihat keluar) Makanlah. Apa yang kaulihat di luar?\r\n</p><p>\r\nMintarsih: Waktu saya lewat di situ tadi, (menoleh, melihat Gunarto yang tampak tak acuh saja) Bang Narto, dengarkan dulu\r\n</p><p>\r\nGunarto: (tenang) Ya, aku dengar\r\n</p><p>\r\nMintarsih: Ada orang tua di ujung jalan ini. Dari jembatan sana, ia melihat-lihat ke arah rumah kita. Nampaknya seperti seorang pengemis, (semua diam) Yah, kenapa semua jadi diam? (Gunarto tertunduk membisu)\r\n</p><p>\r\nMaimun: (dengan cepat) Orang tua? Bagaimana rupanya?\r\n</p><p>\r\nMintarsih: Hati agak gelap. Jadi, tidak begitu jelas kelihatannya</p><p>Latar tempat dan waktu dalam teks drama tersebut adalah ...</p>', 'masjid, malam hari', '&nbsp;jembatan, pagi hari', 'rumah, senja hari', 'rumah, pagi hari', 'jembatan, senja hari', NULL, NULL, NULL, NULL, NULL, 'c', 1729566313, 1729566560, 1, '', 1, 0, 0, '72056d57-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29351, 788, 0, 1, 19, NULL, NULL, NULL, '<p><b>Kutipan berita berikut.\r\n</b></p><p>\r\nJadikan UN Seperti Ingin Selfie\r\n</p><p>\r\n1) Metrotvnews.com, Jakarta: Kepala Pusat Penilaian Pendidikan Kemendikbud, Nizam, mengimbau supaya anak-anak tidak menganggap Ujian Nasional (UN) sebagai momok yang menakutkan. Jadikan UN sebagai moment ketika ingin selfie.\r\n</p><p>\r\n2) “Jadi, kita ingin anak-anak tidak menjadikan UN sebagai momok. Akan tetapi, anggap UN itu seperti mau selfie-lah,” kata Nizam dalam program “Trending Topic Metro TV,” Kamis (29/1/2015).\r\n</p><p>\r\n3) Untuk menjadikan moment UN dengan riang sama seperti selfie, UN tahun 2015 tidak lagi dijadikan syarat kelulusan siswa. Namun, semua siswa tetap harus mengikuti pelaksanaan ujian.\r\n</p><p>\r\n4) “Jadi, boleh bergembira sekarang, UN tahun 2015 insyaallah tidak lagi menjadi syarat kelulusan. Pemerintah melakukan pemetaan dari capaian siswa,” imbuh Nizam.\r\n</p><p>\r\n5) Menurut Nizam, UN hanya bertujuan untuk mengukur standar kompetensi kelulusan setiap siswa. Akan tetapi, kelulusan tersebut sepenuhnya diserahkan kepada setiap sekolah. Proses penilaian anak sudah dilakukan sejak awal masuk jenjang sekolah. Jadi, sekolah mengetahui kemampuan anak didiknya. Sementara itu, tugas pemerintah adalah melihat ketercapaian standar dari kemampuan anak tersebut.\r\n</p><p>\r\nInformasi pokok terdapat dalam kepala atau lead berita adalah …</p>', 'Pemetaan terhadap pencapaian belajar siswa', 'Kelulusan siswa ditentukan oleh sekolah terkait', 'Imbauan menjadikan UN sebagai moment ketika ingin selfie.', 'Ajakan menghilangkan rasa takut menghadapi UN.', 'Imbauan menciptakan suasana riang menghadapi UN.', NULL, NULL, NULL, NULL, NULL, 'c', 1729566479, 1729566661, 1, '', 1, 0, 0, '72057038-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
