INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29361, 790, 0, 1, 1, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 1\r\n</p><p style=\"text-align: justify; \">\r\nVenice is a city in northern Italy. It has been known as the Queen of the Adriatic, City of Bridges, and The City of Light. The city stretches across 117 small islands in the marshy Venetian Lagoon along the Adriatic Sea in northeast Italy. Venice is world famous for its canals. It is built on an archipelago of 117 islands formed by about 150 canals in a shallow lagoon. The islands on which the city is built are connected by about 400 bridges. In the old center, the canals serve the function of roads, and every form of transport is on water or on foot. You can ride gondola there. It is the classical Venetian boat which nowadays is mostly used for tourists, or weddings, funerals, or other ceremonies. Now, most Venetians travel by moto rise waterbuses which ply regular routes along the major canals and between the city islands. The city has many private boats. The only gondolas still in common use by Venetians are the Traghetti, foot passenger ferries crossing the Grand Canal at certain points without bridges.\r\n</p><p style=\"text-align: justify; \">\r\nWhat does the text tell you about....</p>', 'Gondola ', 'Traghetti ', 'Venice ', 'Italy', 'Venetian boat ', NULL, NULL, NULL, NULL, NULL, 'c', 1729566908, 1729567049, 1, '', 1, 0, 0, '72058213-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29362, 789, 0, 1, 24, NULL, NULL, NULL, 'Watak Doni yang tercermin dalam dialog tersebut adalah ...', 'kesal', 'sombong', '&nbsp;sedih', 'marah', 'gembira', NULL, NULL, NULL, NULL, NULL, 'e', 1729566953, 1729749883, 1, '', 1, 0, 0, '72058475-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29363, 789, 0, 1, 25, NULL, NULL, NULL, '<p><b>Bacalah dialog berikut dengan saksama!</b>&nbsp;</p><p>(1) Sanusi: Ada yang menganggu pikiranmu, Bung?\r\n</p><p>\r\n(2) Harun: Oh, Pak Sanusi, saya sedang pusing, Pak\r\n</p><p>\r\n(3) Sanusi: Ayolah, kemukakan kepada saya, siapa tahu saya dapat membantu\r\n</p><p>\r\n(4) Harun: Begini Pak, anak saya yang sulung belum juga mendapat pekerjaan. Kasihan dia, sudah satu tahun menganggur, sepertinya sia-sia saja kuliahnya</p><p>    Konflik yang terkandung dalam teks tersebut adalah ...</p>', 'Pak Sanusi menjadi penganggu pikiran bagi pak Harun', 'Pak Harun menjadi penganggu pikiran bagi Pak Sanusi', 'Anak sulung Pak Harun belum mendapatkan pekerjaan', 'Anak sulung Pak Sanusi menyia-nyiakan kuliahnya', '&nbsp;Anak sulung Pak Sanusi belum mendapatkan pekerjaan', NULL, NULL, NULL, NULL, NULL, 'c', 1729567028, 1729749891, 1, '', 1, 0, 0, '720585d4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29364, 788, 0, 1, 21, NULL, NULL, NULL, '<p><span style=\"font-weight: bolder;\">Kutipan berita berikut.</span></p><p>Jadikan UN Seperti Ingin Selfie</p><p>1) Metrotvnews.com, Jakarta: Kepala Pusat Penilaian Pendidikan Kemendikbud, Nizam, mengimbau supaya anak-anak tidak menganggap Ujian Nasional (UN) sebagai momok yang menakutkan. Jadikan UN sebagai moment ketika ingin selfie.</p><p>2) “Jadi, kita ingin anak-anak tidak menjadikan UN sebagai momok. Akan tetapi, anggap UN itu seperti mau selfie-lah,” kata Nizam dalam program “Trending Topic Metro TV,” Kamis (29/1/2015).</p><p>3) Untuk menjadikan moment UN dengan riang sama seperti selfie, UN tahun 2015 tidak lagi dijadikan syarat kelulusan siswa. Namun, semua siswa tetap harus mengikuti pelaksanaan ujian.</p><p>4) “Jadi, boleh bergembira sekarang, UN tahun 2015 insyaallah tidak lagi menjadi syarat kelulusan. Pemerintah melakukan pemetaan dari capaian siswa,” imbuh Nizam.</p><p>5) Menurut Nizam, UN hanya bertujuan untuk mengukur standar kompetensi kelulusan setiap siswa. Akan tetapi, kelulusan tersebut sepenuhnya diserahkan kepada setiap sekolah. Proses penilaian anak sudah dilakukan sejak awal masuk jenjang sekolah. Jadi, sekolah mengetahui kemampuan anak didiknya. Sementara itu, tugas pemerintah adalah melihat ketercapaian standar dari kemampuan anak tersebut.</p><p>Abstraksi tepat berdasarkan kutipan di atas adalah …<br></p>', 'Kamis (29/1/2015), Kepala Pusat Penilaian Pendidikan Kemendikbud, Nizam melakukan program “Trending Topic Metro TV”. Dalam kesempatan tersebut, Nizam mengajak semua siswa untuk melakukan selfie sebelum UN. Beliau menambahkan bahwa saat ini UN bukan penentu kelulusan. UN hanya digunakan sebagai alat ukur pencapaian siswa.', 'Saat ini faktor penentu kelulusan tidak ditentukan oleh nilai UN semata. Pihak sekolah berhak sepenuhnya menentukan kelulusan siswanya. Jadi, siswa diharapkan tidak takut dengan UN. Informasi tersebut disampaikan Menteri Pendidikan dan Kebudayaan dalam program “Trending Topic Metro TV”, Kamis (29/1/2015).', 'Ketakutan siswa dengan UN sudah berlangsung sejak lama. Siswa takut jika mendapat nilai UN rendah dan dinyatakan tidak lulus. Kini ketakutan itu sirna setelah ada keputusan dari Menteri Pendidikan dan Kebudayaan dalam program “Trending Topic Metro TV”, Kamis (29/1/2015).', 'Dalam program “Trending Topic Metro TV”, Kamis (29/1/2015), Nizam mengatakan semua siswa Indonesia untuk mengerjakan Un dengan semangat. Nizam mengimbau semua siswa agar tidak terpengaruh jual beli naskah UN. Nizam menambahkan bahwa saat ini UN bukan penentu kelulusan. UN hanya digunakan sebagai alat ukur pencapaian siswa.', 'Kepala Pusat Penilaian Pendidikan Kemendikbud, Nizam, mengatakan siswa untuk tidak takut menghadapi UN. Saat ini UN bukan penentu kelulusan. UN hanya digunakan sebagai alat ukur pencapaian siswa. Pihak yang menentukan kelulusan adalah sekolah. Informasi tersebut disampaikan Nizam dalam program “Trending Topik Metro TV”, Kamis (29/1/2015)', NULL, NULL, NULL, NULL, NULL, 'e', 1729567056, 1729567209, 1, '', 1, 0, 0, '72058747-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29365, 790, 0, 1, 2, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 1.</p><p style=\"text-align: justify; \">\r\n\r\nVenice is a city in northern Italy. It has been known as the Queen of the Adriatic, City of Bridges, and The City of Light. The city stretches across 117 small islands in the marshy Venetian Lagoon along the Adriatic Sea in northeast Italy. Venice is world famous for its canals. It is built on an archipelago of 117 islands formed by about 150 canals in a shallow lagoon. The islands on which the city is built are connected by about 400 bridges. In the old center, the canals serve the function of roads, and every form of transport is on water or on foot. You can ride gondola there. It is the classical Venetian boat which nowadays is mostly used for tourists, or weddings, funerals, or other ceremonies. Now, most Venetians travel by moto rise waterbuses which ply regular routes along the major canals and between the city islands. The city has many private boats. The only gondolas still in common use by Venetians are the Traghetti, foot passenger ferries crossing the Grand Canal at certain points without bridges.\r\n</p><p style=\"text-align: justify; \">\r\nWhat transport crosses the Grand Canal for foot passengers at certain points without bridges....</p>', 'Gondolas.', 'Traghetti.', 'Waterbuses.', 'Lagoon.', 'Ship', NULL, NULL, NULL, NULL, NULL, 'b', 1729567066, 1729567218, 1, '', 1, 0, 0, '72058986-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29366, 805, 0, 3, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Secara garis besar, bahan pangan dapat dikelompokkan menjadi dua yaitu bahan pangan asal tumbuhan (nabati) dan bahan pangan asal hewan (hewani). Bahan pangan nabati adalah bahan-bahan makanan yang berasal dari tanaman (bisa berupa akar, batang, dahan, daun, bunga, buah atau beberapa bagian dari tanaman bahkan keseluruhannya) atau bahan makanan yang diolah dari bahan dasar dari tanaman. Sumber bahan nabati dapat kita produksi sendiri disekolah maupun dirumah salah satu contohnya adalah dengan berkebun hidroponik disekolah, dengan berkebun hidroponik kita dapat memperoleh bahan nabati seperti sayur dan buah yang segar dan sehat karena tidak menggunakan pestisida. Bahan pangan hewani merupakan bahan-bahan makanan yang berasal dari hewan atau olahan yang bahan dasarnya dari hasil hewan. Kedua bahan pangan ini memiliki karakteristik yang berbeda sehingga memerlukan penanganan dan pengolahan yang berbeda pula. Selanjutnya dalam hal ini yang diuraikan adalah bahan pangan hewani. </span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">\r\nBerikut ini tentukan bahan pangan yang termasuk dalam kelompok nabati dan hewani!</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:8:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:18:\"<p>Nabati <br></p>\";i:2;s:17:\"<p>Hewani<br></p>\";}i:1;a:3:{i:0;s:20836:\"<p><!--[if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:TrackMoves></w:TrackMoves>\r\n  <w:TrackFormatting></w:TrackFormatting>\r\n  <w:PunctuationKerning></w:PunctuationKerning>\r\n  <w:ValidateAgainstSchemas></w:ValidateAgainstSchemas>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:DoNotPromoteQF></w:DoNotPromoteQF>\r\n  <w:LidThemeOther>IN</w:LidThemeOther>\r\n  <w:LidThemeAsian>X-NONE</w:LidThemeAsian>\r\n  <w:LidThemeComplexScript>X-NONE</w:LidThemeComplexScript>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables></w:BreakWrappedTables>\r\n   <w:SnapToGridInCell></w:SnapToGridInCell>\r\n   <w:WrapTextWithPunct></w:WrapTextWithPunct>\r\n   <w:UseAsianBreakRules></w:UseAsianBreakRules>\r\n   <w:DontGrowAutofit></w:DontGrowAutofit>\r\n   <w:SplitPgBreakAndParaMark></w:SplitPgBreakAndParaMark>\r\n   <w:DontVertAlignCellWithSp></w:DontVertAlignCellWithSp>\r\n   <w:DontBreakConstrainedForcedTables></w:DontBreakConstrainedForcedTables>\r\n   <w:DontVertAlignInTxbx></w:DontVertAlignInTxbx>\r\n   <w:Word11KerningPairs></w:Word11KerningPairs>\r\n   <w:CachedColBalance></w:CachedColBalance>\r\n  </w:Compatibility>\r\n  <w:BrowserLevel>MicrosoftInternetExplorer4</w:BrowserLevel>\r\n  <m:mathPr>\r\n   <m:mathFont m:val=\"Cambria Math\"></m:mathFont>\r\n   <m:brkBin m:val=\"before\"></m:brkBin>\r\n   <m:brkBinSub m:val=\"--\"></m:brkBinSub>\r\n   <m:smallFrac m:val=\"off\"></m:smallFrac>\r\n   <m:dispDef></m:dispDef>\r\n   <m:lMargin m:val=\"0\"></m:lMargin>\r\n   <m:rMargin m:val=\"0\"></m:rMargin>\r\n   <m:defJc m:val=\"centerGroup\"></m:defJc>\r\n   <m:wrapIndent m:val=\"1440\"></m:wrapIndent>\r\n   <m:intLim m:val=\"subSup\"></m:intLim>\r\n   <m:naryLim m:val=\"undOvr\"></m:naryLim>\r\n  </m:mathPr></w:WordDocument>\r\n</xml><![endif]-