INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29367, 789, 0, 1, 26, NULL, NULL, NULL, '<p><span style=\"font-weight: bolder;\">Bacalah dialog berikut dengan saksama!</span>&nbsp;</p><p>(1) Sanusi: Ada yang menganggu pikiranmu, Bung?</p><p>(2) Harun: Oh, Pak Sanusi, saya sedang pusing, Pak</p><p>(3) Sanusi: Ayolah, kemukakan kepada saya, siapa tahu saya dapat membantu</p><p>(4) Harun: Begini Pak, anak saya yang sulung belum juga mendapat pekerjaan. Kasihan dia, sudah satu tahun menganggur, sepertinya sia-sia saja kuliahnya</p><p>Gerak-gerik, mimik, dan intonasi yang tepat untuk dialog Sanusi pada nomor (3) adalah ...<br></p>', 'mendekati Harun, mimik tegang, suara meninggi ', 'menjauhi dan membelakangi Harun, mimik sedih, suara meninggi', 'menghampiri dan menepuk pundak Harun, mimik ceria, suara meninggi', '&nbsp;menjauhi Harun, mimik tenang, suara merendah', 'duduk menghadap Harun, mimik tenang, suara merendah', NULL, NULL, NULL, NULL, NULL, 'e', 1729567197, 1729749910, 1, '', 1, 0, 0, '72059e28-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29368, 788, 0, 1, 22, NULL, NULL, NULL, '<p><span style=\"font-weight: bolder;\">Kutipan berita berikut.</span></p><p>Jadikan UN Seperti Ingin Selfie</p><p>1) Metrotvnews.com, Jakarta: Kepala Pusat Penilaian Pendidikan Kemendikbud, Nizam, mengimbau supaya anak-anak tidak menganggap Ujian Nasional (UN) sebagai momok yang menakutkan. Jadikan UN sebagai moment ketika ingin selfie.</p><p>2) “Jadi, kita ingin anak-anak tidak menjadikan UN sebagai momok. Akan tetapi, anggap UN itu seperti mau selfie-lah,” kata Nizam dalam program “Trending Topic Metro TV,” Kamis (29/1/2015).</p><p>3) Untuk menjadikan moment UN dengan riang sama seperti selfie, UN tahun 2015 tidak lagi dijadikan syarat kelulusan siswa. Namun, semua siswa tetap harus mengikuti pelaksanaan ujian.</p><p>4) “Jadi, boleh bergembira sekarang, UN tahun 2015 insyaallah tidak lagi menjadi syarat kelulusan. Pemerintah melakukan pemetaan dari capaian siswa,” imbuh Nizam.</p><p>5) Menurut Nizam, UN hanya bertujuan untuk mengukur standar kompetensi kelulusan setiap siswa. Akan tetapi, kelulusan tersebut sepenuhnya diserahkan kepada setiap sekolah. Proses penilaian anak sudah dilakukan sejak awal masuk jenjang sekolah. Jadi, sekolah mengetahui kemampuan anak didiknya. Sementara itu, tugas pemerintah adalah melihat ketercapaian standar dari kemampuan anak tersebut.</p><p>Verba mental yang tidak terdapat pada paragraf ke-5 adalah ….<br></p>', 'melihat', 'mengetahui', 'mengukur', 'diserahkan', 'dilakukan', NULL, NULL, NULL, NULL, NULL, 'b', 1729567220, 1729567383, 1, '', 1, 0, 0, '7205a5cf-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29369, 790, 0, 1, 3, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 1\r\n</p><p style=\"text-align: justify; \">\r\nVenice is a city in northern Italy. It has been known as the Queen of the Adriatic, City of Bridges, and The City of Light. The city stretches across 117 small islands in the marshy Venetian Lagoon along the Adriatic Sea in northeast Italy. Venice is world famous for its canals. It is built on an archipelago of 117 islands formed by about 150 canals in a shallow lagoon. The islands on which the city is built are connected by about 400 bridges. In the old center, the canals serve the function of roads, and every form of transport is on water or on foot. You can ride gondola there. It is the classical Venetian boat which nowadays is mostly used for tourists, or weddings, funerals, or other ceremonies. Now, most Venetians travel by moto rise waterbuses which ply regular routes along the major canals and between the city islands. The city has many private boats. The only gondolas still in common use by Venetians are the Traghetti, foot passenger ferries crossing the Grand Canal at certain points without bridges.\r\n</p><p style=\"text-align: justify; \">From the text we can say that Venice belongs to a city of …. </p>', 'Water', 'Ceremonies', 'Buses', 'Funerals', 'Gondola', NULL, NULL, NULL, NULL, NULL, 'a', 1729567237, 1729567366, 1, '', 1, 0, 0, '7205a81b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29370, 789, 0, 1, 27, NULL, NULL, NULL, '<p><b>Bacalah teks berikut dengan saksama!</b></p><p>Sebuah ruangan di rumah tuan residen ada pengawas lembaga-lembaga sosial, pengawas sekolah, hakim, kapten polisi, dokter daerah, dan dua orang polisi.\r\n</p><p>\r\n \r\n\r\n(1) Residen: Tuan-tuan, saya undang kemari untuk mendengarkan sebuah berita yang sangat tidak menyenangkan. Seorang governoor djenderal akan datang berkunjung kemari.\r\n</p><p>\r\n(2) Mr. Ruslan: Apa, seorang governoor?\r\n</p><p>\r\n(3) Tn. Dahlan: Apa, seorang governoor?\r\n</p><p>\r\n(4) Residen: Seorang governoor von Batavia incognito dengan tugas rahasia\r\n</p><p>\r\n(5) Mr. Ruslan: Ini baru namanya celaka\r\n</p><p>\r\n(6) Tn. Dahlan: Seolah-olah beban kita belum cukup berat\r\n</p><p>\r\n(7) H. A. Salim: Ya, Tuhan. Tugas rahasia lagi?\r\n</p><p>\r\n(8) Residen: Saya punya firasat. Semalam, saya bermimpi dua ekor tikus yang besar sekali. Betul, belum pernah saya melihat tikus seperti itu, hitam dan besar bukan alang kepalang. Mereka datang mencium-cium di sana-sini lalu pergi lagi.</p><p>    Bentuk kalimat tak langsung dari percakapan awal yang diucapkan oleh tokoh Residen adalah ...</p>', 'Residen memberi tahu bahwa akan datang seorang governoor djenderal untuk berkunjung', 'Residen memberi tahu bahwa dirinya diminta oleh governoor djenderal untuk datang berkunjung', 'Residen memberi tahu bahwa ada kabar buruk yang menimpa governoor djenderal', 'Residen memberi tahu bahwa ada tugas rahasia yang akan disampaikan oleh governoor djenderal&nbsp;', 'Residen diberi tugas rahasia oleh governoor djenderal yang akan berkunjung', NULL, NULL, NULL, NULL, NULL, 'a', 1729567312, 1729749921, 1, '', 1, 0, 0, '7205a97f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29371, 790, 0, 1, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 1.</p><p style=\"text-align: justify; \">\r\n\r\nVenice is a city in northern Italy. It has been known as the Queen of the Adriatic, City of Bridges, and The City of Light. The city stretches across 117 small islands in the marshy Venetian Lagoon along the Adriatic Sea in northeast Italy. Venice is world famous for its canals. It is built on an archipelago of 117 islands formed by about 150 canals in a shallow lagoon. The islands on which the city is built are connected by about 400 bridges. In the old center, the canals serve the function of roads, and every form of transport is on water or on foot. You can ride gondola there. It is the classical Venetian boat which nowadays is mostly used for tourists, or weddings, funerals, or other ceremonies. Now, most Venetians travel by moto rise waterbuses which ply regular routes along the major canals and between the city islands. The city has many private boats. The only gondolas still in common use by Venetians are the Traghetti, foot passenger ferries crossing the Grand Canal at certain points without bridges.\r\n</p><p style=\"text-align: justify; \">\r\nWhat does the second paragraph of the text tell us about....</p>', 'The forms of transport in the world. ', 'The canals and roads that people like to use.  ', 'The archipelago that has a lot of islands. ', 'Venice as the world famous for its canals.  ', 'Venice is the city of light ', NULL, NULL, NULL, NULL, NULL, 'd', 1729567387, 1729567571, 1, '', 1, 0, 0, '7205abca-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
