INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29373, 790, 0, 1, 5, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 2.</p><p style=\"text-align: justify; \">\r\n\r\nMasjid Sultan Suriansyah is a historical mosque. Built 300 years ago, this building is the oldest mosque in South Kalimantan. The mosque is located in the North Kuin Village of Banjarmasin. It was built in the reign of Sultan Suriansyah known as Pangeran Samudera. He was the first Banjarnese King who converted into Islam. This mosque was found on the bank of the Kuin River, near KampungKraton, which was destroyed by the Dutch colonial. The construction of Masjid Sultan Suriansyah was unique. The roof is layered. It took the Banjars past architecture before Islam came. Different from any other old mosques in Banjar, the mihrab has its own roof, separated from the main building.\r\n</p><p style=\"text-align: justify; \">Masjid Sultan Suriansyah was constructed in the era of …. </p>', 'Banjar people', 'Dutch colonial  ', 'Kalimantan King', 'Sultan Suriansyah  ', 'Jokowi', NULL, NULL, NULL, NULL, NULL, 'd', 1729567604, 1729567751, 1, '', 1, 0, 0, '7205af6f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29374, 789, 0, 1, 28, NULL, NULL, NULL, '<p><span style=\"font-weight: bolder;\">Bacalah teks berikut dengan saksama!</span></p><p>Sebuah ruangan di rumah tuan residen ada pengawas lembaga-lembaga sosial, pengawas sekolah, hakim, kapten polisi, dokter daerah, dan dua orang polisi.</p><p>(1) Residen: Tuan-tuan, saya undang kemari untuk mendengarkan sebuah berita yang sangat tidak menyenangkan. Seorang governoor djenderal akan datang berkunjung kemari.</p><p>(2) Mr. Ruslan: Apa, seorang governoor?</p><p>(3) Tn. Dahlan: Apa, seorang governoor?</p><p>(4) Residen: Seorang governoor von Batavia incognito dengan tugas rahasia</p><p>(5) Mr. Ruslan: Ini baru namanya celaka</p><p>(6) Tn. Dahlan: Seolah-olah beban kita belum cukup berat</p><p>(7) H. A. Salim: Ya, Tuhan. Tugas rahasia lagi?</p><p>(8) Residen: Saya punya firasat. Semalam, saya bermimpi dua ekor tikus yang besar sekali. Betul, belum pernah saya melihat tikus seperti itu, hitam dan besar bukan alang kepalang. Mereka datang mencium-cium di sana-sini lalu pergi lagi.</p><p>Ekspresi yang tepat untuk dialog Mr. Ruslan pada nomor (2) adalah ...<br></p>', 'sedih', 'bingung', 'gembira', 'kesal', 'terkejut', NULL, NULL, NULL, NULL, NULL, 'e', 1729567669, 1729749930, 1, '', 1, 0, 0, '7205b100-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
