INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29382, 790, 0, 1, 8, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 3.</p><p style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Angkor Wat was faced a Hindu temple, a man of Buddhist temple completed in Cambodia. It is the largest religious monument in the world. The temple was built by the Khmer King, Suryawarman II in the early twelfth century in Yosadapura, the capital of the Khmer Empire as this temple of eventual moslem. It is dedicated to Wisnu. It is designed to represent Khmer Meru, frame of the Devis in Hindu mythology within the mouth and has an outer wall which is 3 to 7 km long. It has three rectangular galleries which races about the neck. At the center of the temple stand Queen Cap of Tower.\r\n</span></p><p style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">What is the monolog about ....</span></p>', 'Gallery complex. ', 'Buddhist mythology', 'Cambodia', 'Khmer Empire', 'Angkor Wat', NULL, NULL, NULL, NULL, NULL, 'e', 1729568166, 1729568318, 1, '', 1, 0, 0, '7205c067-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
