INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29389, 789, 0, 1, 36, NULL, NULL, NULL, 'Tindakan yang dilakukan pertama kali agar negosiasi berjalan lancar adalah …', 'Membandingkan beberapa pilihan', 'Mengajak membuat kesepakatan', 'Menetapkan dan menegaskan kembali tujuan negosiasi', 'Memberikan alas an mengapa harus dibuat ksepakatan', 'Mengevaluasi kekuatan dan komitmen Bersama', NULL, NULL, NULL, NULL, NULL, 'b', 1729568762, 1729750012, 1, '', 1, 0, 0, '7205cf08-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29390, 790, 0, 1, 10, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 4.</p><p style=\"text-align: justify; \">On the banks of the Chao Phraya, Bangkok River of Kings, lies a hotel that has already set new standards of hospitality for this celebrated city.\r\n</p><p style=\"text-align: justify; \">\r\nSet in magnificently landscaped tropical gardens, the Shangri-La Bangkok provides guests with all the charm and warmth of the orient and, at the same time, unsurpassed range of facilities and leisure activities. There is a choice of 12 superb settings in which to wine and dine, a large free-form swimming pool that overlooks the river, convention and meeting facilities for up to 2000 people, and a 24-hour business center.\r\n</p><p style=\"text-align: justify; \">\r\nAnd, from every single guest room and suite, there is a breathtaking view of all the exotic hustle and bustle of the fabled River of Kings. One might expect such a well-equipped and positioned hotel to be miles away from the city center but, at Shangri-La Bangkok the business district and main shopping areas are mere minutes away.\r\n</p><p style=\"text-align: justify; \">\r\nFrom more than 200 years, Bangkok grandeur has been reflected in the waters of the Chao Phraya. Today, the Shangri-La Bangkok towers beside this majestic river, offers its guests the golden promise of the East.\r\n</p><p style=\"text-align: justify; \">For how many people the meeting facilities are up to .... </p>', '5000 people', '4000 people', '2000 people', '1000 people', '500 people', NULL, NULL, NULL, NULL, NULL, 'c', 1729568786, 1729568964, 1, '', 1, 0, 0, '7205d08e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
