INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29397, 790, 0, 1, 12, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 5.\r\n</p><p style=\"text-align: justify; \">\r\nBale Kambang is a small village in the Southern coast of East Java, seventy kilometers from Malang town and two hours drive from South. It is well known for its long beautiful white sandy beach as well as the similarity of its temple to the one of Tanah Lot in Bali. In Bale Kambang, there are three small rocky islands namely Ismaya Island, Wisanggeni Island, and Anoman Island, those names are taken from wayang figures (Java traditional puppets). These islands are surrounded by Indonesian Ocean which huge waves frighten most overseas cruisers.\r\n</p><p style=\"text-align: justify; \">\r\nWhat makes Bale Kambang famous ....</p>', 'Small rocky islands ', 'Long beautiful beach', 'Huge waves of ocean', 'Overseas cruisers ', 'Three small rocky islands', NULL, NULL, NULL, NULL, NULL, 'b', 1729569163, 1729569270, 1, '', 1, 0, 0, '7205ddfc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29398, 789, 0, 5, 1, NULL, NULL, NULL, '<p><b>Bacalah dialog di bawah ini!</b></p><p>\r\nPembeli: Halo, saya ingin membicarakan tentang barang ekspor yang ingin kami beli.\r\n</p><p>\r\nPenjual: Halo, ini adalah Penjual. Bagaimana saya bisa membantu Anda?\r\n</p><p>\r\nPembeli: Kami ingin membeli produk Anda, namun harga yang ditawarkan terlalu tinggi bagi kami. Apakah ada kesempatan untuk menurunkan harga?\r\n</p><p>\r\nPenjual: Kami memahami masalah Anda, namun harga yang kami tawarkan sudah bersifat kompetitif dan mencakup biaya produksi dan pengiriman.\r\n</p><p>\r\nPembeli: Kami berharap bisa memperoleh harga lebih baik karena kami memiliki volume pembelian yang cukup besar. Apakah Anda bisa mempertimbangkan harga yang lebih rendah?\r\n</p><p>\r\nPenjual: Saya akan mempertimbangkan hal ini dan mencoba menemukan solusi terbaik bagi kedua belah pihak. Berapa volume pembelian yang Anda bicarakan?\r\n</p><p>\r\nPembeli: Kami membutuhkan sebanyak 5.000 unit produk dalam setahun.\r\n</p><p>\r\nPenjual: Baik, kami akan mempertimbangkan volume pembelian tersebut dan mencoba menemukan solusi harga yang terbaik bagi kedua belah pihak.</p><p>    Siapa yang memulai negosiasi dalam dialog di atas?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>Pembeli memulai negosiasi.<br></div></div>', 1729569234, 1729750190, 1, '', 1, 0, 0, '7205df6e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
