INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29406, 790, 0, 1, 14, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 6.\r\n</p><p style=\"text-align: justify; \">\r\nKediri is a name of a town. It is situated in a valley between the Kelud and Willis mountains and inhabited by about 1.3 million people. In the centre of the town there is a large hill which is called the Dathok Mountain. Because of the topography of the region, Kediri is called a chilly town by the locals. There is a big river called Brantas cutting off the centre of the town. Beside the temples, Kediri is also famous for its products like cigarettes and a special kind of tofu or bean curd. This highly nutritious food is delicacy of Kediri and has a distinctive taste. The cigarettes factory dominates the town economy and employs the majority of the women labor force. Kediri and the cigarettes factory are inseparable and it is considered the biggest cigarette factory in Indonesia. Most of the local people work in this factory. Those who do not work here are farmers or traders.\r\n</p><p style=\"text-align: justify; \">\r\nWhat does the above text tell about ....</p>', 'The history of Kediri ', 'The famous products of Kediri', 'The description of Kediri  ', 'The people  ', '1.3 million people ', NULL, NULL, NULL, NULL, NULL, 'c', 1729569740, 1729569993, 1, '', 1, 0, 0, '7205f077-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
