INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29418, 790, 0, 3, 5, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Dialog 1</p><p style=\"text-align: justify;\">dr. Nahda: Hello...</p><p style=\"text-align: justify;\">Fafa: Hello, doctor</p><p style=\"text-align: justify;\">dr. Nahda: You look terrible. What can I do for you?</p><p style=\"text-align: justify;\">Fafa: I cannot go to school today.</p><p style=\"text-align: justify;\">dr. Nahda: Oh, I am sorry to hear that. What is the problem?</p><p style=\"text-align: justify;\">Fafa: My stomach hurts terribly. I think I have a fever as well.</p><p style=\"text-align: justify;\">dr. Nahda: Okay, let me check your stomach. (The doctor puts the stethoscope in Fafa is belly and strikes it lightly). Does it hurt here?</p><p style=\"text-align: justify;\">Fafa: Not that one.</p><p style=\"text-align: justify;\">dr. Nahda: Here?</p><p style=\"text-align: justify;\">Fafa: Yes, that is really terribly.</p><p style=\"text-align: justify;\">dr. Nahd<span style=\"font-size: 0.875rem;\">: Alright then, I will give you a prescription. You have to take the pills three times a day, okay?</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Fafa: Okay, doctor</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">dr. Nahda: Good. get well soon, Fafa. bye.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Fafa: Thanks a lot. bye, doctor</span></p><p style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Determine the correct statement according to the dialogue above.</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:11:\"<p>True</p>\";i:2;s:12:\"<p>False</p>\";}i:1;a:3:{i:0;s:75:\"<p><span style=\"text-align: center;\">What can I do for You?</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:83:\"<p><span style=\"text-align: center;\">My Hands hurts terribly</span><br></p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:102:\"<p><span style=\"text-align: center;\">Oh, I am sorry to hear that. What is the problem?</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:81:\"<p><span style=\"text-align: center;\">Yes, That is really terrible</span><br></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729570879, 1729571094, 0, '', 1, 0, 0, '72060dc5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
