INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29426, 790, 0, 1, 22, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 8.\r\n</p><p style=\"text-align: justify; \">\r\nThe Shard is an 87-storey skyscraper, which sits in the heart of London. It is known as the shard of glass. Construction began in 2009 and was completed three years later in 2012, making it Western European is tallest building. Designed by architect Renzo Piano, The Shart is the second tallest free standing structure in the UK. Its exterior boasts 11,000 glass panels — that is equivalent in area to eight football pitches or two-and-a-half Trafalgar Squares. The building was developed to have multiple uses, describes on the website as a vertical city where people can live, work and relax. This motto was clearly taken on board that was found on the 72nd floor towards the end of construction.\r\n</p><p style=\"text-align: justify; \">\r\nWhat is the text about ....</p>', 'The architect Renzo Piano ', 'The Shard glass panels  ', 'The Shard, building in London ', 'The tallest building in London  ', 'The heart of London ', NULL, NULL, NULL, NULL, NULL, 'd', 1729571192, 1729571290, 1, '', 1, 0, 0, '72062041-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
