INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29436, 788, 0, 1, 34, NULL, NULL, NULL, '<p>Perhatikan kutipan teks berikut.\r\n</p><p>\r\nImbauan akan Gunung Bromo meletus tersebut dituliskan dalam bentuk poster dan ditempel di tempat-tempat strategis agar dapat di baca oleh warga. Isinya berupa langkah-langkah yang harus ditempuh oleh masyarakat desa apabila Gunung Bromo meletus tiba-tiba.\r\n</p><p>\r\nPenulisan kata yang tidak baku adalah ….</p>', 'imbauan', 'Gunung Bromo', 'ditempel', 'di baca', 'di tempat-tempat strategis', NULL, NULL, NULL, NULL, NULL, 'd', 1729571832, 1729571951, 1, '', 1, 0, 0, '720636db-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29437, 790, 0, 5, 2, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>Why did Ronaldo train very hard?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Because he knew that a footballer requires good stamina&nbsp;</span></div>', 1729571870, 1729571925, 0, '', 1, 0, 0, '72063883-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29438, 790, 0, 5, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">What makes Cristiano Ronaldo different from other players in scoring goals?</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">He can use both of his legs efficiently to make goals</span></div>', 1729571933, 1729571977, 0, '', 1, 0, 0, '72063aad-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29439, 788, 0, 1, 35, NULL, NULL, NULL, '<p><b>Bacalah kutipan berikut.\r\n</b></p><p>\r\nPemerintah Siapkan Proses Abdikasi\r\n</p><p>Madrid, Selasa – Pemerintah Spanyol, Selasa (3/6), memulai penggantian raja untuk pertama kalinya dalam sejarah paska Franco. Sementara ribuan orang anti kerajaan turun ke jalan di seluruh negeri mengimbau diadakannya referendum mengenai kerajaan.</p><p><span style=\"font-size: 0.875rem;\">Raja Juan Carlos, Senin, mengumumkan akan turun takhta, membuka jalan bagi putranya, Pangeran Felipe, untuk menggantikannya. Namun, para demonstran tidak menghendaki penyerahan takhta kepada Felipe yang akan bergelar Raja Felipe VI itu. Pengunjuk rasa menuntut sebuah referendum mengenai lembaga raja.\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\nSampai jauh malam setelah pengumuman turun takhta raja itu pada Senin, ribuan orang memenuhi Lapangan Puerta del Sol, Madrid. Serangkaian demonstrasi juga diadakan di kota-kota besar di seluruh negeri.</span></p><p><span style=\"font-size: 0.875rem;\">\r\nSehari setelah pengumuman abdikasi itu, Perdana Menteri Mariano Rajoy memimpin sidang luar biasa kabinet pada tengah hari untuk membuat sebuah undang-undang turun takhta, yang kemudian harus disetujui oleh parlemen. UU itu, yang bisa sampai empat pekan untuk disetujui menurut media Spanyol, akan menutup tirai pemerintahan raja berusia 76 tahun itu, yang terkena skandal pada akhir masa berkuasanya.\r\n</span></p><p><span style=\"font-size: 0.875rem;\">\r\nMakna kata <b>abdikasi </b>pada teks di atas adalah ….</span></p>', 'penyerahan suatu masalah kepada orang banyak ', 'voting', 'naik tahta', 'perebutan kekuasaan ', 'turun tahta', NULL, NULL, NULL, NULL, NULL, 'e', 1729571955, 1729572184, 1, '', 1, 0, 0, '72063e76-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29440, 790, 0, 5, 4, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>“He also challenged himself by playing along with older players.” The word ‘he’ refers to...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cristiano Ronaldo<br>', 1729571985, 1729572022, 0, '', 1, 0, 0, '720640cf-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
