INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29450, 790, 0, 1, 29, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 9.</p><p style=\"text-align: justify; \">\r\n\r\nNatural Bridge National Park is luscious tropical rainforest.\r\n</p><p style=\"text-align: justify; \">\r\nIt is located 110 kilometers from south of Brisbane and is reached by following the Pacific Highway to Nerang and then by travelling through the Numinbah Valley. This scenic roadway lies in the shadow of Lamington National Park.\r\n</p><p style=\"text-align: justify; \">\r\nThe phenomenon of the rock formed into a natural arch and the cave through which a waterfall cascades is a short one-kilometer walk below a dense rainforest canopy from the main picnic area. Swimming is permitted in the rock pools. Night-time visitors to the cave will discover the unique feature of the glow worms. Picnic areas offers toilets, barbeque, shelter sheds, water and fireplaces; however, overnight camping is not permitted.\r\n</p><p style=\"text-align: justify; \">\r\nWhat the visitors will see in the night....</p>', 'a common glow worm ', 'the unique feature of the glow worms ', 'a great dark cave  ', 'the unique rocks  ', 'the fantastic bridge ', NULL, NULL, NULL, NULL, NULL, 'b', 1729572591, 1729572755, 1, '', 1, 0, 0, '72064f77-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29451, 788, 0, 1, 38, NULL, NULL, NULL, 'Abstraksi kutipan berita di atas adalah …', 'Pemerintah Spanyol, Selasa (3/6), memulai penggantian raja untuk pertama kalinya dalam sejarah paska Franco. Raja Juan Carlos, Senin, mengumumkan akan turun takhta, membuka jalan bagi putranya, Pangeran Felipe, untuk menggantikannya. Namun, para demonstran tidak menghendaki penyerahan takhta kepada Felipe yang akan bergelar Raja Felipe VI itu. Pengunjuk rasa menuntut sebuah referendum mengenai lembaga raja', 'Madrid, Selasa – Pemerintah Spanyol, Selasa (3/6), memulai penggantian raja untuk pertama kalinya dalam sejarah paska Franco. Sementara ribuan orang anti kerajaan turun ke jalan di seluruh negeri mengimbau diadakannya referendum mengenai kerajaan', 'Pemerintah Spanyol, Selasa (3/6), memulai penggantian raja untuk pertama kalinya dalam sejarah paska Franco. Namun, para demonstran tidak menghendaki penyerahan takhta kepada Felipe yang akan bergelar Raja Felipe VI itu. Pengunjuk rasa menuntut sebuah referendum mengenai lembaga raja. Ribuan orang memenuhi Lapangan Puerta del Sol, Madrid. Serangkaian demonstrasi juga diadakan di kota-kota besar di seluruh negeri.', 'Madrid, Selasa – Pemerintah Spanyol, Selasa (3/6), memulai penggantian raja untuk pertama kalinya dalam sejarah paska Franco. Raja Juan Carlos, Senin, mengumumkan akan turun takhta. Namun, para demonstran tidak menghendaki penyerahan takhta. Pengunjuk rasa menuntut sebuah referendum mengenai lembaga raja. Perdana Menteri Mariano Rajoy memimpin sidang luar biasa kabinet pada tengah hari untuk membuat sebuah undang-undang turun takhta, yang kemudian harus disetujui oleh parlemen', 'Madrid, Selasa – Pemerintah Spanyol, Selasa (3/6), memulai penggantian raja untuk pertama kalinya dalam sejarah paska Franco. Sementara ribuan orang anti kerajaan turun ke jalan di seluruh negeri mengimbau diadakannya referendum mengenai kerajaan. Namun, para demonstran tidak menghendaki penyerahan takhta kepada Felipe yang akan bergelar Raja Felipe VI itu. Pengunjuk rasa menuntut sebuah referendum mengenai lembaga raja. Sampai jauh malam setelah pengumuman turun takhta raja itu pada Senin, ribuan orang memenuhi Lapangan Puerta del Sol, Madrid. Serangkaian demonstrasi juga diadakan di kota-kota besar di seluruh negeri.', NULL, NULL, NULL, NULL, NULL, 'd', 1729572708, 1729572826, 1, '', 1, 0, 0, '720651c3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29452, 790, 0, 1, 30, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Descriptive Text of Historical Place and Tourism Object 10.</p><p style=\"text-align: justify; \">\r\n\r\nKediri is a name of a town. It is situated in a valley between the Kelud and Willis mountains and inhabited by about 1.3 million people. In the centre of the town there is a large hill which is called the Dathok Mountain. Because of the topography of the region, Kediri is called a chilly town by the locals. There is a big river called Brantas cutting off the centre of the town.\r\n</p><p style=\"text-align: justify; \">\r\nBeside the temples, Kediri is also famous for its products like cigarettes and a special kind of tofu or bean curd. This highly nutritious food is delicacy of Kediri and has a distinctive taste. The cigarettes factory dominates the town economy and employs the majority of the women labor force. Kediri and the cigarettes factory are inseparable and it is considered the biggest cigarette factory in Indonesia. Most of the local people work in this factory. Those who do not work here are farmers or traders.\r\n</p><p style=\"text-align: justify; \">\r\nWhat does the above text tell about.... </p>', 'The history of Kediri ', 'The famous products of Kediri  ', 'The description of Kediri  ', 'The people  ', 'The islands ', NULL, NULL, NULL, NULL, NULL, 'c', 1729572768, 1729572924, 1, '', 1, 0, 0, '7206540d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29453, 788, 0, 1, 39, NULL, NULL, NULL, '<p>Cermati langkah-langkah berikut!\r\n</p><p>(1) Berkunjung ke Perpustakaan dan mengisi daftar hadir pengunjung.\r\n</p><p>\r\n(2) Melihat daftar buku untuk memilih buku yang diperlukan.\r\n</p><p>\r\n(3) Mengambil buku yang dimaksud yang ada di rak perpustakaan.\r\n</p><p>\r\n(4) Menyerahkan buku dan kartu anggota perpustakaan kepada petugas untuk didata\r\n</p><p>\r\n(5) Petugas meng-scan barcode buku, dan memasukkan ke data peminjam.</p><p>\r\n\r\n(6) Petugas menyerahkan buku kepada peminjam.\r\n</p><p>\r\n \r\n\r\nJudul yang tepat untuk teks prosedur berdasarkan langkah-langkah di atas adalah…</p>', 'Cara Berkunjung ke Perpustakaan', 'Cara Membaca Buku di Perpustakaan', 'Cara Mengembalikan Buku di Perpustakaan', 'Cara Meminjam Buku di Perpustakaan&nbsp;', 'Cara Menjadi Pustakawan di Perpustakaan', NULL, NULL, NULL, NULL, NULL, 'd', 1729572835, 1729572947, 1, '', 1, 0, 0, '720655b9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29454, 788, 0, 1, 40, NULL, NULL, NULL, '<p>Langkah-langkah penyusunan teks prosedur :</p><p>\r\n1. Menginventarisasi macam-macam kegiatan yang pernah atau dapat dilakukan.\r\n</p><p>\r\n2. ………………………………………………………\r\n</p><p>\r\n3. Membuat kerangka dalam bentuk topik-topik kegiatan secara garis besar.\r\n</p><p>\r\n4. Mengumpulkan bahan-bahan.\r\n</p><p>\r\n5. Mengembangkan kerangka menjadi sebuah petunjuk yang jelas dan lengkap\r\n</p><p>\r\n \r\n\r\nPernyataan yang tepat untuk melengkapi langkah-langkah penyusunan teks prosedur di atas adalah…\r\n</p><p><br></p>', 'Menentukan alat', 'Menentukan tema/topik ', 'Menentukan bahan ', 'Menentukan judul', 'Mengembangkan tema', NULL, NULL, NULL, NULL, NULL, 'b', 1729572951, 1729573088, 1, '', 1, 0, 0, '7206581c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
