INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29467, 788, 0, 3, 1, NULL, NULL, NULL, 'Tentukan pola pengembangan paragraf.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:96:\"<p>Dalam satu paragraf boleh terdapat dua ide pokok yang dituangkan dalam dua kalimat utama</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:95:\"<p>Hanya terdapat satu kalimat penjelasan dalam satu paragraf untuk menjelaskan ide pokok.</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:128:\"<p>Pola pengembangan paragraf deduksi dimulai dengan pernyataan umum kemudian diakhiri dengan pernyataan-pernyataan khusus.</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:76:\"<p>Kalimat utama pada pengembangan induktif terletak di akhir paragraf.</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:119:\"<p>Pola pengembangan induktif dimulai dengan pernyataan-pernyataan khusus kemudian diakhiri dengan pernyataan umum</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729596645, 1729749317, 1, '', 1, 0, 0, '720671f1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29468, 788, 0, 3, 2, NULL, NULL, NULL, 'Jawablah dengan benar atau salah pernyataan di bawah ini.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:126:\"<p>Berikut adalah kalimat fakta: Pengenalan sagu dan ketela sebagai pengganti beras kepada masyarakat mendesak dilakukan.</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:155:\"<p>Berikut adalah kalimat opini: Ketela mulai ditanam di daerah Kalimantan secara besar-besaran tahun 2017 dan panen raya akan terjadi awal tahun 2019</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:142:\"<p>Berikut adalah kalimat fakta: Pemerintah memberikan bantuan berupa pupuk kepada petani yang mau menanam tanaman selain padi tahun ini.</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:172:\"<p>Berikut adalah kalimat opini: Masyarakat perkotaan terutama di Jakarta, Surabaya, dan Makasar mulai menyukai umbi-umbian sebagai makanan alternatif pengganti beras.</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729596931, 1729749347, 1, '', 1, 0, 0, '72067434-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29469, 788, 0, 3, 3, NULL, NULL, NULL, 'Berilah tanda centang pada table di bawah ini untuk menjelaskan perbedaan antara kalimat fakta dan kalimat opini.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:20:\"<p>Kalimat Fakta</p>\";i:2;s:20:\"<p>Kalimat Opini</p>\";}i:1;a:3:{i:0;s:82:\"<p>Dapat dibuktikan kebenarannya karena berasal dari kejadian yang sebenarnya</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:100:\"<p>Bersifat subjektif dan biasanya disertai dengan pendapat, saran, dan uraian yang menjelaskan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:101:\"<p>Berisi data-data yang bersifat kuantitatif (berupa angka) dan kualitatif (berupa pernyataan).</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:119:\"<p>Berisi pendapat tentang peristiwa yang terjadi yang bisa berupa pikiran atau pendapat seseorang maupun kelompok</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:106:\"<p>Biasanya ditandai dengan penggunaan katakata bisa jadi, sepertinya, mungkin, seharusnya, sebaiknya</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:81:\"<p>Mempunyai data yang akurat, baik waktu, tanggal, tempat, dan peristiwanya</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1729597071, 1729749370, 1, '', 1, 0, 0, '720677ab-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
