INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29475, 790, 0, 5, 9, NULL, NULL, NULL, '<p style=\"text-align: justify; \">A: I feel that children should explore more outdoor activities.\r\n</p><p style=\"text-align: justify; \">B: … Outdoor activity can help develop motoric sensory. It is also beneficial for children.</p><p style=\"text-align: justify; \">Complete the dialog with expression agree or disagree</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'I agree', 1729597993, 1729598452, 0, '', 1, 0, 0, '7206850a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
