INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29477, 788, 0, 5, 3, NULL, NULL, NULL, 'Apa tujuan dari penggunaan poster sebagai jenis teks persuasi?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tujuan dari penggunaan poster sebagai jenis teks persuasi adalah untuk mempengaruhi pandangan dan sikap orang terhadap suatu topik atau isu. Dengan menggunakan gambar atau visual yang kuat dan kata-kata yang meyakinkan, poster berusaha untuk memperkenalkan atau mempromosikan suatu produk, ide, atau kampanye tertentu.<br>', 1729598074, 1729598127, 1, '', 1, 0, 0, '72068978-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:38', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
