INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29538, 613, 0, 1, 26, NULL, NULL, NULL, '<div>Dari beberapa pernyataan&nbsp; berikut&nbsp; ini yang&nbsp; merupakan&nbsp; pengertian&nbsp; akuntansi</div><div>adalah ….</div>', '<div>Pencatatan arus kas dan laba rugi perusahaan.</div>', '<div>Pencatatan transaksi keuangan.</div>', '<div>Sistem<span style=\"white-space: pre;\">	</span>yang<span style=\"white-space: pre;\">	</span>komprehensif<span style=\"white-space: pre;\">	</span>untuk<span style=\"white-space: pre;\">	</span>mengumpulkan,<span style=\"white-space: pre;\">	</span>menganalisis,<span style=\"white-space: pre;\">	</span>dan mengomunikasikan informasi keuangan.</div>', '<div>Sistem&nbsp; yang&nbsp; komprehensif&nbsp; dalam&nbsp; pencatatan&nbsp; arus&nbsp; kas,&nbsp; laba&nbsp; rugi,&nbsp; dan&nbsp; transaksi keuangan.</div>', 'Pencatatan laba rugi perusahaan', NULL, NULL, NULL, NULL, NULL, 'c', 1729720702, 1729720860, 1, '', 1, 0, 0, '72070049-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:39', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29539, 613, 0, 1, 27, NULL, NULL, NULL, '<p><b>STIMULUS:</b></p><p>PT Harmoni Jaya adalah sebuah perusahaan manufaktur yang sedang menghadapi dilema strategis. Penjualan produk utamanya menunjukkan tren penurunan, sementara biaya operasional cenderung meningkat. Untuk mengatasi situasi ini, jajaran direksi membutuhkan data yang akurat dan relevan. Direktur Keuangan, Bapak Rahmat, secara rutin menyajikan laporan keuangan yang tidak hanya memuat angka-angka historis, tetapi juga analisis mendalam mengenai profitabilitas per lini produk, efisiensi rantai pasok, dan proyeksi dampak kebijakan harga baru terhadap pendapatan. Informasi ini krusial bagi dewan direksi untuk mengevaluasi kinerja, mengidentifikasi akar masalah penurunan profitabilitas, merumuskan strategi pemasaran yang lebih tepat sasaran, serta mengambil keputusan alokasi investasi pada riset dan pengembangan produk baru.</p><p>Berdasarkan narasi di atas, definisi akuntansi yang paling relevan untuk menggambarkan kontribusinya dalam mendukung pengambilan keputusan strategis di PT Harmoni Jaya dapat dilihat dari sudut pandang&hellip;.</p></body></html>', '<div>Aspek Proses</div></body></html>', '<div>Aspek Sistem</div></body></html>', '<div>Aspek Fungsi</div></body></html>', '<div>Aspek Kegiatan</div></body></html>', 'Aspek Tugas Akuntansi', NULL, NULL, NULL, NULL, NULL, 'c', 1729720861, 1766479790, 1, '', 1, 0, 0, '720702fc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:39', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29540, 613, 0, 1, 28, NULL, NULL, NULL, '<p><span style=\"font-size: 0.875rem;\">PT Sinar Maju, sebuah perusahaan manufaktur yang bergerak di industri tekstil, baru saja menyelesaikan penyusunan laporan keuangan tahunan untuk periode fiskal 2023. Laporan tersebut mencakup laporan laba rugi, neraca, dan laporan arus kas yang telah diaudit oleh akuntan publik. Sebagai Direktur Operasional, Bapak Budi Santoso bertanggung jawab penuh atas efisiensi produksi, manajemen biaya, dan strategi pengembangan produk. Beliau akan menggunakan data dari laporan keuangan ini sebagai dasar untuk presentasi strategi kinerja dan rencana operasional tahun depan di hadapan dewan direksi, serta untuk mengambil keputusan penting terkait efisiensi dan arah perusahaan.</span></p><p><span style=\"font-size: 0.875rem;\">Dalam konteks tanggung jawab strategisnya sebagai Direktur Operasional, bagaimana laporan keuangan tersebut akan memberikan manfaat paling signifikan bagi Bapak Budi Santoso untuk mengoptimalkan kinerja PT Sinar Maju dan merumuskan kebijakan operasional yang tepat?</span></p></body></html>', '<div>mengetahui perkembangan usaha untuk menentukan kebijakan yang akan diambil</div></body></html>', '<div>dapat memperhitungkan berapa bagian laba atau deviden yang akan diterima</div></body></html>', '<div>mengetahui besar/kecil laba perusahaan untuk menentukan pajak yang akan diterima</div></body></html>', '<div>memperhitungkan prospek usaha perusahaan sebelum menentukan investasi</div></body></html>', 'sebagai masukan untuk pertimbangan sebelum memberikan pinjaman', NULL, NULL, NULL, NULL, NULL, 'a', 1729720940, 1766479855, 1, '', 1, 0, 0, '720705c8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:39', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
