INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29651, 808, 0, 5, 1, NULL, NULL, NULL, 'Sebutkan dan jelaskan tiga nilai Kristen yang penting diterapkan dalam kehidupan remaja!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<ol data-start=\"2253\" data-end=\"2528\"><li data-start=\"2253\" data-end=\"2346\"><p data-start=\"2256\" data-end=\"2346\"><strong data-start=\"2256\" data-end=\"2265\">Kasih</strong> – Mengasihi Tuhan dan sesama melalui perhatian, kepedulian, dan tindakan baik.</p>\r\n</li>\r\n<li data-start=\"2347\" data-end=\"2448\">\r\n<p data-start=\"2350\" data-end=\"2448\"><strong data-start=\"2350\" data-end=\"2363\">Kejujuran</strong> – Berani berkata benar dan menolak kebohongan dalam hal akademik maupun pergaulan.</p>\r\n</li>\r\n<li data-start=\"2449\" data-end=\"2528\">\r\n<p data-start=\"2452\" data-end=\"2528\"><strong data-start=\"2452\" data-end=\"2471\">Kerendahan hati</strong> – Tidak sombong, mau belajar, dan menghargai orang lain.</p>\r\n</li>\r\n</ol>', 1763608791, 1763608824, 1, '', 1, 0, 0, '7207a1f7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:39', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29652, 808, 0, 5, 2, NULL, NULL, NULL, 'Bagaimana peran orang tua dalam menanamkan nilai iman kepada anak menurut ajaran Kristen?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Orang tua berdoa bersama anak, membimbing membaca Alkitab, mengajak beribadah, memberi teladan hidup sesuai firman Tuhan, serta membiasakan anak bersikap jujur, mengasihi, dan bertanggung jawab.', 1763608840, 1763608892, 1, '', 1, 0, 0, '7207a519-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:39', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
