INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29941, 837, 0, 5, 2, NULL, NULL, NULL, 'Apa yang dimaksud offside dalam permainan sepak bola?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div style=\"text-align: justify;\"><p class=\"MsoNoSpacing\"><span lang=\"EN-US\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Dalamolah raga sepak bola, offside terjadi jika seorang pemain diberikan bola ketikaberada lebih dekat dengan garis gawang lawan dibanding posisi pemain lawan.Biasanya offside digunakan para pemain belakang sebagai bagian dari taktik</span>&nbsp;untuk menjebak lawan.<span lang=\"EN-US\" style=\'font-size:12.0pt;font-family:\"Times New Roman\",serif\'><o:p></o:p></span></p></div></div></body></html>', 1763888805, 1765016692, 1, '', 1, 0, 0, '720a58e3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29942, 837, 0, 5, 3, NULL, NULL, NULL, 'Jelaskan apa tugas wasit pertama dalam﻿ permainan sepak bola?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"line-height: 107%;\">Sebuah pertandingan diperintah oleh seorang wasit yangmempunyai &ldquo;wewenang penuh untuk menjalankan pertandingan sesuai PeraturanPermainan dalam suatu pertandingan yang telah diutuskan kepadanya&rdquo;, dankeputusan-keputusan pertandingan yang dikeluarkannya dianggap sudah final. Sangwasit dibantu oleh dua orang asisten wasit (dulu dipanggil hakim/penjaga garis).Dalam banyak pertandingan wasit juga dibantu seorang ofisial keempat yang dapatmenggantikan seorang ofisial lainnya jika diperlukan</span><span lang=\"EN-US\" style=\'font-size:12.0pt;line-height:107%;font-family:\"Times New Roman\",serif\'><o:p></o:p></span></p></div></div></body></html>', 1763888934, 1765016704, 1, '', 1, 0, 0, '720a5b04-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29943, 837, 0, 5, 4, NULL, NULL, NULL, 'Sebutkan teknik dasar menendang bola?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>1. Menendang menggunakan kaki bagian dalam</div><div>2. Menendang menggunakan kaki bagian luar</div><div>3. Menendang menggunakan punggung kaki&nbsp;</div></div></body></html>', 1763889127, 1765016712, 1, '', 1, 0, 0, '720a5c11-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29944, 837, 0, 5, 5, NULL, NULL, NULL, 'Apa yang dimaksud dengan permainan sepak bola?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNoSpacing\" style=\"\">Sepak bola merupakan cabang olah raga yang memakai bola dan dimainkan olehdua tim. Tiap-tiap tim beranggotakan 11 orang pemain inti dan sebagian pemaincadangan dengan tujuan mencetak gol&nbsp;sebanyak-banyaknya&nbsp;ke gawang lawan.</p></div></body></html>', 1763889288, 1765016722, 1, '', 1, 0, 0, '720a5e47-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29945, 837, 0, 5, 6, NULL, NULL, NULL, 'Apa yang dimaksud dengan permainan bola voli?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><div><div><div><div><p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"line-height: 107%;\">O</span><span lang=\"EN-US\" style=\"line-height: 107%;\">lahragaberegu di mana dua tim berlawanan berusaha memukul bola melewati net agar jatuhdi daerah lawan untuk mendapatkan poin<span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"text-align: start;\">. Permainan ini membutuhkan koordinasi, taktik,dan strategi antar pemain dalam satu tim. Setiap tim biasanya terdiri dari enampemain yang beradu strategi dengan menguasai teknik dasar seperti&nbsp;</span></span><span style=\"text-align: start; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">servis, passing,smash,</span><span style=\"text-align: start; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"text-align: start;\">&nbsp;dan&nbsp;</span></span><span style=\"text-align: start; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">blocking</span><span style=\"text-align: start; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"text-align: start;\">.</span></span><span class=\"vkekvd\" style=\"text-align: start;\"><span data-animation-atomic=\"\" style=\"\"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span jsuid=\"KxM8B_a\" jsaction=\"rcuQ6b:&amp;KxM8B_a|npT2md\" data-wiz-attrbind=\"class=KxM8B_a_R4Tih;\" jscontroller=\"udAs2b\" data-wiz-uids=\"KxM8B_a,KxM8B_b,KxM8B_c\" style=\"text-align: start;\">&nbsp;</span></span></span></span><font face=\"Times New Roman, serif\" style=\"text-align: start;\"><span style=\"font-size: 12pt;\"><o:p></o:p></span></font></span></p></div></div></div></div></div></div></body></html>', 1763889422, 1765016730, 1, '', 1, 0, 0, '720a5f9b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29948, 837, 0, 5, 7, NULL, NULL, NULL, 'Apa yang dimaksud dengan permainan bola basket?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><p class=\"MsoNoSpacing\" style=\"\">O<span lang=\"EN-US\" style=\"\">lahragatim yang dimainkan oleh dua tim yang masing-masing beranggotakan lima oranguntuk mencetak poin dengan memasukkan bola ke keranjang lawan<span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">. Tujuan utama permainan iniadalah mencetak skor sebanyak mungkin sambil mencegah tim lawan mencetak skor.Permainan ini menggunakan bola besar, dimainkan dengan tangan, dan melibatkanteknik seperti menggiring, mengoper, dan menembak.<span class=\"vkekvd\" style=\"\"><span data-animation-atomic=\"\" style=\"\"><span jsuid=\"CQgft_8\" jsaction=\"rcuQ6b:&amp;CQgft_8|npT2md\" data-wiz-attrbind=\"class=CQgft_8_R4Tih;\" jscontroller=\"udAs2b\" data-wiz-uids=\"CQgft_8,CQgft_9,CQgft_a\" style=\"text-align: start;\">&nbsp;</span></span></span></span></span><span lang=\"EN-US\" style=\'font-size:12.0pt;font-family:\"Times New Roman\",serif\'><o:p></o:p></span></p></div></div></body></html>', 1763889693, 1765016740, 1, '', 1, 0, 0, '720a62b6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
