INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29966, 839, 0, 1, 9, NULL, NULL, NULL, 'Sebatang isolator panjang mengandung muatan terdistribusi merata. Seorang siswa ingin menghitung gaya Coulomb pada sebuah muatan uji q yang diletakkan dekat salah satu ujung batang. Manakah langkah pemikiran yang <strong data-start=\"3106\" data-end=\"3122\">paling tepat</strong>?', 'Menganggap batang sebagai satu muatan titik<br>', 'Membagi batang menjadi banyak elemen kecil bermuatan<br>', 'Mengabaikan sebagian batang yang jauh dari muatan uji<br>', '&nbsp;Menambah jarak agar gaya mudah dihitung<br>', 'Mengganti batang dengan dua muatan titik di ujungnya', NULL, NULL, NULL, NULL, NULL, 'b', 1763954472, 1763955153, 1, '', 1, 0, 0, '720a8c08-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29967, 839, 0, 1, 10, NULL, NULL, NULL, '<p>Tiga muatan titik berada pada satu garis lurus:<br data-start=\"217\" data-end=\"220\">\r\n• q₁ = +4 μC di titik A<br data-start=\"243\" data-end=\"246\">\r\n• q₂ = −2 μC di titik B (5 cm dari A)<br data-start=\"283\" data-end=\"286\">\r\n• Titik P berada 5 cm di sebelah kanan q₂</p><p data-start=\"331\" data-end=\"379\">Besar <strong data-start=\"337\" data-end=\"371\">hasil medan listrik di titik P</strong> adalah…</p>', 'Menuju A, besar 7,2 × 10⁶ N/C<br>', 'Menuju B, besar 7,2 × 10⁶ N/C<br>', 'Menuju A, besar 3,6 × 10⁶ N/C<br>', '&nbsp;Menuju B, besar 3,6 × 10⁶ N/C<br>', '&nbsp;Nol', NULL, NULL, NULL, NULL, NULL, 'a', 1763954473, 1763955492, 1, '', 1, 0, 0, '720a8ee8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
