INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29989, 810, 0, 1, 12, NULL, NULL, NULL, '<div class=\"mt-2\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Konsep multikulturalisme sangat penting karena erat kaitannya dengan Hak Azasi Manusia, Konsep dimaksud mengandung prinsip ....&nbsp;</span></div></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Keadilan dan kesemena-menaan&nbsp;</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Keadilan dan persamaan&nbsp;</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Persamaan dan kepelbagaian&nbsp;</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem; text-align: left;\">Persamaan dan hegemoni total</span></div>', 'Keadilan dan ketidakteraturan', NULL, NULL, NULL, NULL, NULL, 'b', 1763956987, 1763957081, 1, '', 1, 0, 0, '720abcba-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29990, 810, 0, 1, 13, NULL, NULL, NULL, '<div class=\"mt-2\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Menjadi siswa yang memiliki pandangan multikultural itu sangat penting. Cara untuk selalu berpikir dan bertindak multikultural , ialah dengan ....&nbsp;</span></div></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berpedoman kepada nilai universal&nbsp;</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berpedoman kepada gaya hidup modern&nbsp;</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berpedoman kepada janji siswa&nbsp;</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berpedoman kepada pendangan orang banyak&nbsp;</span></div>', '<span style=\"text-align: justify;\">Berpedoman kepada ajaran firman Tuhan, yaitu Alkitab</span>', NULL, NULL, NULL, NULL, NULL, 'a', 1763957184, 1763957258, 1, '', 1, 0, 0, '720abf5b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (29991, 810, 0, 1, 14, NULL, NULL, NULL, '<div><span style=\"font-size: 0.875rem; text-align: justify;\">Pandangan yang berpangkal pada masyarakyat dan kebudayaannya sendiri dan meremehkan masyarakatnya dan kebudayaan lain, adalah pengertian dari ....&nbsp;</span></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Etnosentrisme&nbsp;</span></div>', '<span style=\"text-align: justify;\">Primordialisme</span>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Diskriminatif</span></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">S</span><span style=\"font-size: 0.875rem; text-align: justify;\">tereotip</span></div>', '<span style=\"text-align: justify;\">Orientative</span>', NULL, NULL, NULL, NULL, NULL, 'a', 1763957282, 1763957387, 1, '', 1, 0, 0, '720ac1e3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
