INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30008, 839, 0, 2, 2, NULL, NULL, NULL, 'Dua benda A dan B awalnya netral. Setelah didekatkan tanpa bersentuhan dengan benda C yang bermuatan negatif, benda A dan B kemudian dipisahkan dan ternyata A bermuatan positif sedangkan B bermuatan negatif. Proses yang paling mungkin terjadi adalah ...', '{\"a\":\"<p class=\\\"MsoNormal\\\"><span lang=\\\"SV\\\">Polarisasipada A dan B kemudian keduanya dipisahkan.<br><p><\\/p><\\/span><\\/p><\\/body><\\/html>\",\"b\":\"<p>Elektron berpindah dari B ke A melalui induksi.<br><\\/p><\\/body><\\/html>\",\"c\":\"<p>Elektron berpindah dari A ke B melalui induksi.<br><\\/p><\\/body><\\/html>\",\"d\":\"<p>Benda C memberikan elektron ke A dan B.<br><\\/p><\\/body><\\/html>\",\"e\":\"<p>Pemisahan muatan terjadi tanpa kontak langsung.<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"c\",\"e\",null]', 1763959078, 1765267368, 1, '', 1, 0, 0, '720add71-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30009, 839, 0, 2, 3, NULL, NULL, NULL, 'Sebuah elektroskop awalnya bermuatan positif. Ketika sebuah batang plastik bermuatan negatif didekatkan tetapi tidak menyentuh, daun-daunnya membuka lebih lebar. Hal ini menunjukkan bahwa…', '{\"a\":\"<p><span lang=\\\"SV\\\" style=\\\"line-height: 115%;\\\" cambria mincho mso-bidi-font-family: new=\\\"\\\" roman mso-ansi-language:sv>Elektronpada elektroskop tertarik naik ke kepala elektroskop.<br><\\/span><\\/p><\\/body><\\/html>\",\"b\":\"<p>Muatan positif terkonsentrasi di bagian daun elektroskop.<br><\\/p><\\/body><\\/html>\",\"c\":\"<p><span style=\\\"font-family: Cambria, serif; font-size: 14.6667px;\\\">&nbsp;<\\/span>Medan listrik batang plastik memperbesar pemisahan muatan pada elektroskop.<br><\\/p><\\/body><\\/html>\",\"d\":\"<p>Terjadi perpindahan elektron dari batang plastik ke elektroskop.<br><\\/p><\\/body><\\/html>\",\"e\":\"<p><span style=\\\"font-family: Cambria, serif; font-size: 14.6667px;\\\">&nbsp;<\\/span>Elektroskop kehilangan sebagian muatannya.<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"b\",\"c\",null]', 1763959080, 1765267405, 1, '', 1, 0, 0, '720adfb4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30010, 839, 0, 2, 4, NULL, NULL, NULL, ' Dua bola konduktor identik bermuatan berbeda: bola X = +6 µC dan bola Y = –2 µC. Keduanya disentuhkan lalu dipisahkan kembali. Kesimpulan yang benar adalah ...', '{\"a\":\"<p><span lang=\\\"SV\\\" style=\\\"line-height: 115%;\\\" cambria mincho mso-bidi-font-family: new=\\\"\\\" roman mso-ansi-language:sv>Total muatan awal sistem adalah +4 &micro;C.<br><\\/span><\\/p><\\/body><\\/html>\",\"b\":\"<p>Setelah disentuhkan, masing-masing bola bermuatan +2 &micro;C.<br><\\/p><\\/body><\\/html>\",\"c\":\"<p>Setelah disentuhkan, masing-masing bola bermuatan +4 &micro;C.<br><\\/p><\\/body><\\/html>\",\"d\":\"<p>Perpindahan elektron terjadi dari Y menuju X.<br><\\/p><\\/body><\\/html>\",\"e\":\"<p>Setelah pemisahan, muatan kedua bola tidak berubah lagi.<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"e\",null]', 1763959082, 1765267441, 1, '', 1, 0, 0, '720ae118-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30011, 839, 0, 2, 5, NULL, NULL, NULL, 'Pada percobaan menggerakkan sisir plastik yang digosok rambut di dekat aliran air tipis dari kran, air akan membelok ke arah sisir. Penjelasan ilmiah yang benar adalah…', '{\"a\":\"<p><span lang=\\\"SV\\\" style=\\\"line-height: 115%;\\\" cambria mincho mso-bidi-font-family: new=\\\"\\\" roman mso-ansi-language:sv>Molekul air mengalami polarisasi sehingga sisi bermuatan positif lebih dekatdengan sisir.<br><\\/span><\\/p><\\/body><\\/html>\",\"b\":\"<p>Gaya elektrostatik antara sisir dan molekul air lebih besar dari gaya gravitasi pada aliran air.<br><\\/p><\\/body><\\/html>\",\"c\":\"<p>Elektron dari sisir berpindah ke molekul air.<br><\\/p><\\/body><\\/html>\",\"d\":\"<p>Fenomena ini membuktikan bahwa air termasuk isolator sempurna.<br><\\/p><\\/body><\\/html>\",\"e\":\"<p>Sudut pembelokan bergantung pada besar muatan pada sisir.<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"e\",null]', 1763959084, 1765267473, 1, '', 1, 0, 0, '720ae34a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
