INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30038, 840, 0, 1, 7, NULL, NULL, NULL, '<p>Bale Kambang is a small village in the Southern coast of East Java, seventy kilometers from Malang town and two hours&rsquo; drive from South. It is well known for its long beautiful white sandy beach as well as the similarity of its temple to the one of Tanah Lot in Bali.In Bale Kambang, there are three small rocky islands namely Ismaya Island, Wisanggeni Island, and Anoman Island, those names are taken from &ldquo;wayang&rdquo; figures (Java traditional puppets). These islands are surrounded by Indonesian Ocean which huge waves frighten most overseas cruisers. </p><p>What makes Bale Kambang famous?</p></body></html>', ' Small rocky islands', 'Long beautiful beach', 'Huge waves of ocean', 'Overseas cruisers', 'three small rocky islands', NULL, NULL, NULL, NULL, NULL, 'b', 1763961046, 1765347592, 1, '', 1, 0, 0, '720b145b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
