INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30043, 840, 0, 1, 9, NULL, NULL, NULL, '<p>Kediri is a name of a town. It is situated in a valley between the Kelud and Willis mountains and inhabited by about 1.3 million peoplE. In the centre of the town there is a large hill which is called the Dathok Mountain. Because of the topography of the region, Kediri is called a chilly town by the locals. There is a big river called Brantas cutting off the centre of the town.Beside the temples, Kediri is also famous for its products like cigarettes and a special kind of tofu or bean curD. This highly nutritious food is delicacy of Kediri and has a distinctive tastE. The cigarettes factory dominates the town economy and employs the majority of the women labor forcE. Kediri and the cigarettes factory are inseparable and it is considered the biggest cigarette factory in IndonesiA. Most of the local people work in this factory. Those who do not work here are farmers or traders. </p><p>What does the above text tell about?</p></body></html>', 'The history of Kediri', 'The famous products of Kediri', 'The description of Kediri', 'The people', '1.3 million people', NULL, NULL, NULL, NULL, NULL, 'c', 1763961749, 1765347737, 1, '', 1, 0, 0, '720b23c3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
