INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30045, 840, 0, 1, 10, NULL, NULL, NULL, '<p>Natural Bridge National Park is luscious tropical rainforest.It is located 110 kilometers from south of Brisbane and is reached by following the Pacific Highway to Nerang and then by travelling through the Numinbah Valley. This scenic roadway lies in the shadow of Lamington National Park.The phenomenon of the rock formed into a natural &lsquo;arch&rsquo; and the cave through which a waterfall cascades is a short one-kilometer walk below a dense rainforest canopy from the main picnic areA. Swimming is permitted in the rock pools. Night-time visitors to the cave will discover the unique feature of the glow worms. Picnic areas offers toilets, barbeque, shelter sheds, water and fireplaces; however, overnight camping is not permitted. </p><p>What is the function of paragraph 1?</p></body></html>', ' as an identification', 'as an orientation', 'as a thesis', 'as a classification', 'as an abstract', NULL, NULL, NULL, NULL, NULL, 'b', 1763961937, 1765347751, 1, '', 1, 0, 0, '720b28af-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
