INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30051, 818, 0, 5, 1, NULL, NULL, NULL, 'Bapak Albert seorang pengusaha yang bergerak di bidang pengolahan pangan lokal yakni pembuatan kripik singkong. Sebelum memulai usahanya&nbsp; ia merencanakan pembiayaan yang terdiri dari biaya tetap dan biaya variabel.&nbsp; Jelaskan yang dimaksud dengan biaya tetap dan biaya variabel!&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>1. Biaya yang tidak mengalami perubahan selama proses produksi.</p><p>2. Biaya yang selalu berubah-ubah selama proses produksi sesuai volume atau tingkatan produksi.</p>', 1763963727, 1763964424, 1, '', 1, 0, 0, '720b32d0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30052, 818, 0, 5, 2, NULL, NULL, NULL, 'Suatu hal yang diperlukan dalam pemasaran produksi adalah promosi. apa yang dimaksud dengan promosi dalam pemasaran hasil produksi?&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Upaya memperkenalkan hasil atau produk yang dihasilkan kepada masyarakat atau khalayak umum.', 1763964428, 1763964834, 1, '', 1, 0, 0, '720b35ec-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30053, 818, 0, 5, 3, NULL, NULL, NULL, 'Produk yang dihasilkan produsen dapat dimanfaatkan baik untuk kepentingan konsumsi atau digunakan&nbsp; maupun untuk pemasaran. Dalam pemasaran hasil produksi yang dimaksud ditempuh dua&nbsp; &nbsp;saluran distribusi yaitu&nbsp; saluran distribusi panjang dan&nbsp; saluran&nbsp; distribusi pendek.&nbsp; Buatlah skema jalur saluran distribusi panjang!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Produsen - pedagang besar - pedagang kecil - pengecer - konsumen</div>', 1763964836, 1763965580, 1, '', 1, 0, 0, '720b3765-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30054, 818, 0, 5, 4, NULL, NULL, NULL, '<p>Bapak Anton&nbsp; seorang petani bergerak di bidang pertanian hortikultura dengan mengeluarkan biaya tetap dan biaya variabel sebagai berikut:</p><p>a. pembelian mesin dinamo air seharga .....................................................RP.5.000.000&nbsp;</p><p>b.pembelian alat-alat pertanian yaitu pacul, linggis, sekop, tali&nbsp; .....Rp. 150.000</p><p>c. tanah untuk usaha ........................................................................................Rp. 2.000.000</p><p>e. pembelian bahan yaitu bibit, pupuk dan obat..................... Rp.200.000</p><p>f. biaya tenaga kerja sebesar ........................................................................Rp. 500.0000</p><p>g. biaya promosi sebesar................................................................................Rp. 100.000</p><p>Berapakah total biaya tetap dan biaya variabel dari kegiatan produksi&nbsp; di atas?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><div>&nbsp;RP. 7.950.000</div></div></div>', 1763965584, 1763968554, 1, '', 1, 0, 0, '720b38d9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30055, 818, 0, 5, 5, NULL, NULL, NULL, '<p>pada awalnya ibu Alo sempat memproduksi kripik pisang sebanyak 180 bungkus&nbsp; dengan total biaya variabel Rp.500.000. Namun permintaan pasar meningkat maka ibu Alo menaikan&nbsp; lagi&nbsp; volume produksi&nbsp; menjadi 400 bungkus kripik pisang dengan biaya sebesar Rp.800.000.</p><p>Berapakah&nbsp; besaran&nbsp; biaya marginal dari kegiatan produksi di atas?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Rp. 300.000</div>', 1763966807, 1763968667, 1, '', 1, 0, 0, '720b3bba-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30057, 840, 0, 1, 11, NULL, NULL, NULL, '<p>Dear Sally,</p><p>Last holiday, my friends and I visited Ponorogo in East Java. Ponorogo is a small city, but it is very natural and beautiful. We spent the night at a villa in Jetis. On the first day, we visited Prigi southern beach. We watched the amazing views of the sea and the white waves. We grilled fish and had \"Nasi Pecel\" for lunch. On the second day, we visited \"Dongko\" mountain resort. There were a lot of plants, especially clove trees. We camped there for a night. I love Ponorogo because the people are very friendly and the prices are cheap.I\'ll bring some pictures for you.</p><p>Love,Anna</p><p>What kind of text is it?</p></body></html>', 'Narrative', 'Procedure', 'Recount', 'Descriptive', 'Explanation', NULL, NULL, NULL, NULL, NULL, 'c', 1764032659, 1765347785, 1, '', 1, 0, 0, '720b3d26-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
