INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30118, 819, 0, 1, 3, NULL, NULL, NULL, 'Ada dua hal yang berbeda antara mencipta dan memodifikasi dalam karya seni. Yang dimaksud dengan memodifikasi adalah.....', 'Kegiatan&nbsp; membuat sesuatu yang baru', 'kegiatan merubah manfaat benda', '&nbsp;kegiatan merubah bentuk dan model&nbsp; sesuatu benda sesuai selera', 'usaha menambah nilai guna suatu benda', 'usaha&nbsp; memperbaiki&nbsp; suatu benda agar menjadi baik dan&nbsp; guna&nbsp;', NULL, NULL, NULL, NULL, NULL, 'c', 1764116013, 1764117487, 1, '', 1, 0, 0, '720bb8f2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30119, 810, 0, 5, 1, NULL, NULL, NULL, '&nbsp;Jelaskan mengapa demokrasi membutuhkan nilai rohani seperti yang diajarkan dalam kitab 1 Raja-raja 21!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>1 Raja-raja 21 memberikan peringatan keras terhadap korupsi dan ketidakadilan. Demokrasi membutuhkan nilai-nilai ini agar tetap berfungsi sebagai sistem yang melindungi HAM, menegakkan keadilan, serta membatasi kekuasaan agar tidak merugikan rakyat.</div>', 1764117335, 1764117842, 1, '', 1, 0, 0, '720bbb30-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30120, 810, 0, 5, 2, NULL, NULL, NULL, '<p>Tuliskanlah nama kota-kota perlindungan yang diperintahkan TUHAN kepada Musa beserta lokasi&nbsp;<span style=\"font-size: 0.875rem;\">Kota-kota perlindungan tersebut berjumlah enam kota&nbsp;</span><span style=\"font-size: 0.875rem;\">tersebut berada!&nbsp;</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><span style=\"font-size: 0.875rem;\">Sebelah Barat Sungai Yordan: Kadesh, Sikhem, dan Hebron, sedangkan Sebelah Timur Sungai Yordan: Golan, Ramor di Gilead, dan Bezer</span></p>', 1764117337, 1764118133, 1, '', 1, 0, 0, '720bbee0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30121, 810, 0, 5, 3, NULL, NULL, NULL, '<p>Jelaskanlah pengertian Hak Asasi Manusia (HAM) dan Demokrasi yang kamu ketahui!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<ol><li>Hak Asasi Manusia (HAM) ialah hak yang dimiliki oleh seseorang sejak lahir, misalnya hak untuk hidup</li><li>Demokrasi ialah Pemerintahan atau kekuasaan yang bertumpu pada rakyat. Pemerintahan yang dari, oleh dan untuk rakyat</li></ol>', 1764117338, 1764117401, 1, '', 1, 0, 0, '720bc279-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30122, 810, 0, 5, 4, NULL, NULL, NULL, 'Dalam memahami Demokrasi dan HAM secara Alkitabiah, maka jelaskanlah secara singkat tentang Mazmur 133!&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Mazmur 133 berbicara tentang suatu masyarakat yang hidup rukun dan bagaikan saudara. Masyarakat yang saling menghargai, dan tidak ada penindasan dan konflik. Masyarakat yang demikian akan selalu dipenuhi dengan Berkat TUHAN', 1764117340, 1764117456, 1, '', 1, 0, 0, '720bc414-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30123, 810, 0, 5, 5, NULL, NULL, NULL, 'Apa arti “hidup sebagai terang dunia” bagi orang percaya? jelaskan!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Hidup sebagai terang dunia berarti menunjukkan karakter Kristus dalam seluruh aspek kehidupan sehingga orang lain dapat melihat kebaikan, kejujuran, dan kasih di dalam diri orang tersebut. Terang berarti membawa kebenaran di tengah kegelapan moral, menjadi contoh yang benar, dan memuliakan Tuhan lewat perilaku.</div>', 1764117341, 1764118581, 1, '', 1, 0, 0, '720bc573-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30124, 812, 0, 3, 3, NULL, NULL, NULL, '<p>Perhatikan tiga peristiwa tumbukan seperti pada gambar berikut ini!</p><p><img src=\"https://usp.ikasmedia.my.id/uploads/bank_soal/file_20251126085304.jpg\" style=\"width: 535px;\"><br></p><p></p><p>Ketiga balok tersebut bergerak dengan kecepatan 3&nbsp;<img src=\"https://usp.ikasmedia.my.id/uploads/bank_soal/file_20251126084201.jpg\" style=\"width: 37px;\"> menumbuk balok lain yang diam. Tumbukan yang terjadi bersifat <b>tidak lenting sama sekali</b>. Pasangan pernyataan berikut yang benar adalah ...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:4:{i:0;a:4:{i:0;s:9:\"<p>#</p>\n\";i:1;s:1971:\"<p><img src=\"data:image/jpeg;base64,\" data-filename=\"2.jpg\" style=\"width: 69px; max-width: 150px;\"><br></p>\";i:2;s:1887:\"<p><img src=\"data:image/jpeg;base64,\" data-filename=\"3.jpg\" style=\"width: 66px; max-width: 150px;\"><br></p>\";i:3;s:1967:\"<p><img src=\"data:image/jpeg;base64,\" data-filename=\"1.jpg\" style=\"width: 66px; max-width: 150px;\"><br></p>\";}i:1;a:4:{i:0;s:61:\"<p>kecepatan benda pada gambar I setelah tumbukan adalah</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";}i:2;a:4:{i:0;s:69:\"<p>kecepatan benda pada gambar II setelah tumbukan adalah</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";}i:3;a:4:{i:0;s:63:\"<p>kecepatan benda pada gambar III setelah tumbukan adalah</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";}}}', 1764117373, 1764118396, 1, '', 1, 0, 0, '720bca65-e8d9-11f0-a465-0a0027000