INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30144, 840, 0, 1, 23, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>“He also challenged himself by playing along with older players.” The word ‘he’ refers to...</p>', 'Cristiano Ronaldo', 'Football players', 'Older players', 'Basketball players', 'The writer', NULL, NULL, NULL, NULL, NULL, 'a', 1764119033, 1764119133, 1, '', 1, 0, 0, '720bee4c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:42', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30145, 840, 0, 1, 24, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>The word “opponent” in paragraph 2 has the closest meaning to …</p>', 'teammate', 'rival&nbsp;', 'friend', 'fans', 'supporter', NULL, NULL, NULL, NULL, NULL, 'b', 1764119140, 1764119241, 1, '', 1, 0, 0, '720bf109-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
