INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30177, 840, 0, 5, 1, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.</p><p>What is the main idea of the text?&nbsp;</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Christiano Ronaldo\'s&nbsp;<span style=\"font-size: 0.875rem;\">skills and determination&nbsp;</span>', 1764120897, 1764120943, 1, '', 1, 0, 0, '720c3ccc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30178, 839, 0, 5, 2, NULL, NULL, NULL, '<p>Sebuah rangkaian listrik terdiri dari baterai 12 V dan hambatan seri 3 &Omega; serta 6 &Omega;.</p><p><span style=\"font-size: 0.875rem;\">Jelaskan mengapa arus yang mengalir pada setiap hambatan sama, dan hitung besar arus total rangkaian.</span></p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><span style=\"line-height: 115%;\">HukumCoulomb: F = k (q&#8321;q&#8322; / r&sup2;)<br>k = 9&times;10&#8313;, q&#8321; = 4&times;10&#8315;&#8310; C, q&#8322; = -6&times;10&#8315;&#8310; C, r = 0,1 m<br>F = 9&times;10&#8313; &times; (24&times;10&#8315;&sup1;&sup2;) / (0,01)<br>F = 21,6 N<br>Gaya bersifat tarik-menarik karena muatan berbeda tanda</span></div></div></body></html>', 1764120914, 1765267600, 1, '', 1, 0, 0, '720c3e13-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
