INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30180, 815, 0, 1, 8, NULL, NULL, NULL, 'Diantara peristiwa berikut yang bukan peristiwa ciri reaksi kimia adalah...', 'Perubahan warna&nbsp;', 'Perubahan Massa&nbsp;', 'Perubahan suhu', 'Pembentukan endapan', 'Pembentukan gas', NULL, NULL, NULL, NULL, NULL, 'b', 1764121005, 1764121647, 1, '', 1, 0, 0, '720c426b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
