INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30182, 840, 0, 5, 3, NULL, NULL, NULL, '<p style=\"text-align: justify;\"><span style=\"font-weight: bolder;\">Descriptive text is a text explains and describe a person, place, or thing.</span></p><p><span style=\"text-align: justify;\">What is the purpose of a descriptive text?</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'To describe a person, place, or thing', 1764121036, 1764121056, 1, '', 1, 0, 0, '720c454f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30183, 840, 0, 5, 4, NULL, NULL, NULL, '<p>Descriptive text is a text that explains and describes a person, place, or thing. It use adjective and adverbs.</p><p>Mention some adjective in the descriptive text!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Beautiful, handsome, humble, honesty', 1764121075, 1764121092, 1, '', 1, 0, 0, '720c4823-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30184, 840, 0, 5, 5, NULL, NULL, NULL, '<p>Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players.</p><p>He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.</p><p>He is also one of the fastest football players in football history. Ronaldo ca run very fast, he can run with a speed of 33.6 kilometers per hour. That is why he is also known as a rocket man. This helps Ronaldo to do his famous free-kick. Ronaldo\'s free-kick speed is approximately 130 kilometers per hour.</p><p>While jumping. Ronaldo\'s, Ronaldo\'s G-force is five times higher than of a cheetah. He can jump up to 78 cm in the air; this jumping height is much more compare to any basketball player. All of these have helped him achieve his success. In his young age, he has won many trophies and broken record including winning the prestigious FIF Ballon d\'Or award five times and created a world record by scoring in the mosr goals in international football in september 2021. Currently his net worth is around $500 million and this makes him one of the richest athletes.</p><p>How did he get known as a rocket man?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Because Christiano Ronaldo can run very fast, he can run with a speed of 33.6 kilometers per hour', 1764121096, 1764121184, 1, '', 1, 0, 0, '720c4994-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30185, 839, 0, 5, 4, NULL, NULL, NULL, '<p>Pada rangkaian paralel terdapat tiga hambatan: 4 &Omega;, 6 &Omega;, dan 12 &Omega; tersambung ke sumber 24 V.</p><p>Jelaskan konsep pembagian arus pada rangkaian paralel, kemudian hitung arus yang melalui masing-masing hambatan.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><div><span style=\'font-size:11.0pt;line-height:115%;font-family:\"Cambria\",serif;mso-ascii-theme-font:minor-latin;mso-fareast-font-family:\"MS Mincho\";mso-fareast-theme-font:minor-fareast;mso-hansi-theme-font:minor-latin;mso-bidi-font-family:\"Times New Roman\";mso-bidi-theme-font:minor-bidi;mso-ansi-language:EN-US;mso-fareast-language:EN-US;mso-bidi-language:AR-SA\'>P</span><span style=\"line-height: 115%;\">adarangkaian paralel, tegangan sama pada setiap cabang. Arus bergantung padahambatan masing-masing cabang<br>I&#8321; = 24 / 4 = 6 A<br>I&#8322; = 24 / 6 = 4 A<br>I&#8323; = 24 / 12 = 2 A<br>Total arus adalah jumlah seluruh arus cabang</span></div></div></div></body></html>', 1764121105, 1765267635, 1, '', 1, 0, 0, '720c4c71-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30186, 834, 0, 2, 2, NULL, NULL, NULL, '<p>Perhatikan zat-zat dibawah ini :</p><ol><li>&nbsp;H</li><li>NO2</li><li>Cl2</li><li>O</li><li>H20</li><li>O3</li><li>CO2</li></ol><p>Yang termasuk dalam Molekul senyawa adalah ...</p>', 'a:5:{s:1:\"a\";s:14:\"<p>1 dan 4</p>\";s:1:\"b\";s:14:\"<p>2 dan 3</p>\";s:1:\"c\";s:14:\"<p>2 dan 5</p>\";s:1:\"d\";s:14:\"<p>5 dan 7</p>\";s:1:\"e\";s:14:\"<p>3 dan 6</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"c\";i:1;s:1:\"d\";i:2;N;}', 1764121114, 1764121155, 1, '', 1, 0, 0, '720c4f14-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30187, 839, 0, 5, 5, NULL, NULL, NULL, '<p>Seorang siswa menggunakan listrik rumah (220 V) untuk menyalakan perangkat elektronik. </p><p>Jelaskan mengapa energi listrik yang digunakan bergantung pada waktu pemakaian dan daya alat, kemudian hitung energi yang digunakan oleh alat listrik 150 W selama 3 jam!</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Energilistrik bergantung pada daya (P) dan waktu pemakaian (t). Semakin lamadigunakan, semakin besar energinya.</span></div><span style=\"line-height: 115%;\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">E = P &times; t = 150 W &times; 3 jam = 150 &times; 3 &times; 3600 = 1.620.000 J = 1,62 MJ.</span></div></span></div></body></html>', 1764121186, 1765267643, 1, '', 1, 0, 0, '720c5216-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30188, 840, 0, 4, 1, NULL, NULL, NULL, '<p>Descriptive text about place</p><p style=\"text-align: justify;\">Kediri is a name of a town. It is situated in a valley between the Kelud and Willis mountains and inhabited by about 1.3 million people. In the Centre of the town there is a large hill which is called the Dathok Mountain. Because of the topography of the region, Kediri is called a chilly town by the locals. There is a big river called Brantas cutting off the Centre of the town. Beside the temples, Kediri is also famous for its products like cigarettes and a special kind of tofu or bean curd. This highly nutritious food is delicacy of Kediri and has a distinctive taste. The cigarettes factory dominates the town economy and employs the majority of the women labor force. Kediri and the cigarettes factory are inseparable and it is considered the biggest cigarette factory in Indonesia. Most of the local people work in this factory. Those who do not work here are farmers or traders.&nbsp;</p><p>What does the above text tell about?&nbsp;</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'description of Kediri', 1764121199, 1764121247, 1, '', 1, 0, 0, '720c552a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30189, 834, 0, 2, 3, NULL, NULL, NULL, '<p>Perhatikan zat-zat dibawah ini :</p><ol><li>&nbsp;H</li><li>NO2</li><li>Cl2</li><li>O</li><li>H20</li><li>O3</li><li>N2</li></ol><p>Yang termasuk dalam Molekul unsur adalah ...</p>', 'a:5:{s:1:\"a\";s:14:\"<p>3 dan 6</p>\";s:1:\"b\";s:14:\"<p>6 dan 7</p>\";s:1:\"c\";s:14:\"<p>1 dan 4</p>\";s:1:\"d\";s:14:\"<p>3 dan 5</p>\";s:1:\"e\";s:14:\"<p>2 dan 4</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1764121204, 1764121272, 1, '', 1, 0, 0, '720c57fc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30190, 840, 0, 4, 2, NULL, NULL, NULL, '<p>Descriptive Text of Historical Place</p><p style=\"text-align: justify;\">Bale Kambang is a small village in the Southern coast of East Java, seventy kilometers from Malang town and two hours’ drive from South. It is well known for its long beautiful white sandy beach as well as the similarity of its temple to the one of Tanah Lot in Bali. In Bale Kambang, there are three small rocky islands namely Ismaya Island, Wisanggeni Island, and Anoman Island, those names are taken from “wayang” figures (Java traditional puppets). These islands are surrounded by Indonesian Ocean which huge waves frighten most overseas cruisers.</p><p><span style=\"font-size: 0.875rem;\">What makes Bale Kambang famous?</span><span style=\"font-size: 0.875rem;\">Long beautiful beach</span><span style=\"font-size: 0.875rem;\">Long beautiful beach</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Long beautiful beach', 1764121272, 1764121299, 1, '', 1, 0, 0, '720c5973-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
