INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30201, 834, 0, 3, 1, NULL, NULL, NULL, '<p>Simaklah contoh penerapan Prinsip kimia Hijau berikut :</p><p>Proses pembuatan kertas putih, dahulu menggunakan soda kaustik NaOH dan Na2S sehingga menghasilkan limbah berbahaya. Dengan adanya kimia hijau pemutihan kertas menggunakan H2O2 dan katalis agar lebih efisien dan tidak berbahaya.</p><p>Termasuk Prinsip manakah contoh penerapan diatas ?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:15:\"<p>Termasuk</p>\";i:2;s:21:\"<p>Tidak Termasuk</p>\";}i:1;a:3:{i:0;s:41:\"<p>Menggunakan bahan baku terbarukan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:52:\"<p>Sintesis kimia yang bahayanya sedikit</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:27:\"<p>Menggunakan katalis</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:74:\"<p>Mendesain bahan kimia dan produk yang tergradasi setelah digunakan</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1764121618, 1764121715, 1, '', 1, 0, 0, '720c7495-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
