INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30382, 857, 0, 3, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Seorang pedagang sepeda ingin membeli 25 sepeda untuk persediaan. Ia ingin membeli sepeda gunung dengan harga Rp. 1.500.000,00 per buah dan sepeda balap dengan harga Rp. 2.000.000,00 per buah. Ia merencanakan tidak akan mengeluarkan uang lebih dari Rp. 42.000.000. Jika keuntungan sebuah sepeda gunung Rp. 500.000,00 dan sebuah sepeda balap Rp. 600.000,00. </span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Benar atau salahkah pernyataan-pernyataan di bawah ini!</span></div></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"<p><span style=\\\"font-size: 0.875rem;\\\">Benar<\\/span><\\/p><\\/body><\\/html>\",\"<p><span style=\\\"font-size: 0.875rem;\\\">Salah<\\/span><\\/p><\\/body><\\/html>\"],[\"<p>x = sepeda gunung dan y = sepeda balap<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p><span style=\\\"font-size: 0.875rem;\\\">Model matematikanya adalah 3x 4y &lt; 84<\\/span><\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p><span style=\\\"font-size: 0.875rem;\\\">Fungsi f(x,y) = 5x 6y<\\/span><\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p><span style=\\\"font-size: 0.875rem;\\\">Keuntungan max 13.400.000<\\/span><\\/p><\\/body><\\/html>\",\"1\",\"0\"]]}', 1764164643, 1765263765, 1, '', 1, 0, 0, '720df96f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
