INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30394, 838, 0, 5, 1, NULL, NULL, NULL, 'Apa yang dimaksud dengan metode penelitian kualitatif dan kuantitatif?&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div style=\"text-align: justify; \">Penelitian kuantitatif&nbsp;memandang realitas bersifat tunggal dan dapat dipilah-pilah dan bersifat nomotetik.&nbsp;Penelitian penelitian kualitatif&nbsp;memandang bahwa realitas bersifat jamak atau holistik dan bersifat ideografik.</div>', 1764165882, 1764724512, 1, '', 1, 0, 0, '720e0cce-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30395, 838, 0, 5, 2, NULL, NULL, NULL, 'Apa yang dimaksud dengan data kualitatif?&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div style=\"text-align: justify;\">&nbsp;Data kualitatif adalah suatu&nbsp;informasi tentang objek atau subjek yang tidak dapat dihitung dengan angka, namun bisa dilihat atau dirasakan. Data ini biasanya dikumpulkan melalui teks, gambar, audio, hingga video.</div>', 1764165987, 1764724520, 1, '', 1, 0, 0, '720e0e13-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30396, 857, 0, 3, 5, NULL, NULL, NULL, '<p><span style=\"line-height: 115%;\">Diberikanmatriks Q&nbsp; =</span><img src=\"uploads/bank_soal/file_20251126220825.png\" style=\"width: 157px;\">Benar atau salah pertanyaan di bawah ini!<br></p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"Benar\",\"Salah\"],[\"<p>Elemen pada baris ke-1 kolom ke-2 adalah 3b<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<span style=\\\"font-size:12.0pt;line-height:115%;font-family:\\\" segoe=\\\"\\\" ui=\\\"\\\" emoji=\\\"\\\" mso-fareast-theme-font:minor-latin=\\\"\\\" new=\\\"\\\" roman=\\\"\\\" mso-ansi-language:en-id=\\\"\\\">Elemenpada baris ke-2 kolom ke-3 adalah 2c<\\/span><p><\\/p>\",\"0\",\"1\"],[\"<p><span style=\\\"font-size:12.0pt;line-height:115%;font-family:\\\" segoe=\\\"\\\" ui=\\\"\\\" emoji=\\\"\\\" mso-fareast-theme-font:minor-latin=\\\"\\\" new=\\\"\\\" roman=\\\"\\\" mso-ansi-language:en-id=\\\"\\\">Elemenpada baris ke-1 kolom ke-3 adalah 4<\\/span><\\/p><\\/body><\\/html>\",\"0\",\"1\"]]}', 1764166071, 1765263832, 1, '', 1, 0, 0, '720e10f2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30397, 838, 0, 5, 3, NULL, NULL, NULL, '<p>Jelaskan secara singkat apa yang dimaksud metode penelitian kuantitatif?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div style=\"text-align: justify; \">Metode kuantitatif&nbsp;adalah sebuah&nbsp;metode penelitian&nbsp;yang di dalamnya menggunakan banyak angka. Mulai dari proses pengumpulan data hingga penafsirannya. Sedangkan&nbsp;Metode penelitian&nbsp;adalah studi mendalam dan penuh dengan kehati-hatian dari segala fakta.</div>', 1764166076, 1764724527, 1, '', 1, 0, 0, '720e1579-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
