INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30461, 861, 0, 3, 3, NULL, NULL, NULL, 'Apakah kalian sudah dapat menerapkan nilai-nilai Pancasila dalam kehidupan sehari-hari? berikut pernyataan kunci yang dapat kalian refleksikan terkait dengan penerapan Pancasila dalam kehidupan sehari-hari.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"Sudah\",\"Belum\"],[\"Telah menjalankan perintah Agama\\/kepercayaan dan menjauhi larangan Agama\",\"1\",\"0\"],[\"Menempatkan bahwa setiap manusia apapun latar belakang dan identitasnya dalam posisi setara\",\"1\",\"0\"],[\"Menempatkan produk dalam negeri sebagai prioritas ketimbang produk luar negeri\",\"1\",\"0\"],[\"Memberikan usul pemikiran dan saran dalam suatu kegiatan musyawarah\",\"1\",\"0\"],[\"Bersikap adil kepada teman tanpa memandang ras, suku, agama, dan bahasa\",\"1\",\"0\"]]}', 1764198004, 1765171926, 1, '', 1, 0, 0, '720eb810-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
