INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30483, 861, 0, 5, 5, NULL, NULL, NULL, 'Jelaskan nilai-nilai yang terkandung dalam Pancasila Sila Ke 3 ....', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Sila ketiga ini memberikan syarat mutlak kepada setiap bangsa Indonesia untuk menjunjung tingggi Persatua.</div></body></html>', 1764198004, 1765172041, 1, '', 1, 0, 0, '720ee662-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30484, 862, 0, 1, 1, NULL, NULL, NULL, '<p>Hak Asasi Manusia (HAM) adalah seperangkat hak yang melekat pada keberadaan manusia sebagai makhluk Tuhan Yang Maha Esa dan merupakan anugrahnya yang wajib dihormati, dijunjung tinggi, dan dilindungi oleh negara. Hal tersebut mengandung arti bahwa .... </p>\n', '<p>negara menjamin hak setiap warga negara</p>\n', '<p>negara menjamin hak setiap warga negara </p>\n', '<p>setiap tindakan harus sesuai dengan hak asasu manusia </p>\n', '<p>persamaan dalam bidang politik, ekonomi, sosial dan budaya </p>\n', '<p>setiap manusia memiliki persamaan kedudukan dalam hukum </p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1764198028, 1764198028, 0, '', 1, 0, 0, '720ee7e1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30485, 862, 0, 1, 2, NULL, NULL, NULL, '<p>Hak asasi manusia berkaitan erat dengan hak kemerdekaan, hak hidup, dam hak untuk mempunyai sesuatu yang tidak boleh diganggu gugat. Hal ini karena HAM merupakan sesuatu yang .... </p>\n', '<p>sudah dibawa manusia sejak lahir</p>\n', '<p>sudah diturunkan dari orang tua </p>\n', '<p>bersifat eksklusif dan sangat pribadi </p>\n', '<p>dibawa manusia sejak lahir sebagai anugrah Tuhan </p>\n', '<p>menunjukan eksistensi manusia yang bermartabat </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1764198028, 1764198028, 0, '', 1, 0, 0, '720eeafd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30486, 862, 0, 1, 3, NULL, NULL, NULL, '<p>NIlai-nilai Pancasila tentunya harus kita terapkan didalam kehidupan sehari-hari. Berikut ini contoh pelaksanaan hak asasi manusia yang sesuai dengan nilai-nilai Pancasila didalam kehidupan sehari-hari adalah .... </p>\n', '<p>memiliki martabat yang luhur</p>\n', '<p>diberi kebebasan dalam memiliki harta </p>\n', '<p>kebebasan dalam mengemukakan pendapat </p>\n', '<p>hak mememluk agama tanpa batasan </p>\n', '<p>melakukan perubahan sesuai ajaran agama </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1764198028, 1764198028, 0, '', 1, 0, 0, '720eec9a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30487, 862, 0, 1, 4, NULL, NULL, NULL, '<p>HAM dalam Pancasila sesungguhnya telah dirumuskan dalam Pembukaan UUD NRI Tahun 1945 yang kemudian diperinci didalam batang tubuhnya yang merupakan hukum dasar, hukum yang konstitusional, dan fundamental bagi Negara Republik Indonesia .... </p>\n', '<p>Melindungi HAM</p>\n', '<p>menghormati hak dan persamaan </p>\n', '<p>meningkatkan patriotisme dalam perjuangan warga negara </p>\n', '<p>mengakui, menghormati dan menegakan HAM </p>\n', '<p>menjamin pelaksanaan HAM </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1764198028, 1764198028, 0, '', 1, 0, 0, '720eef9b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30488, 862, 0, 1, 5, NULL, NULL, NULL, '<p>Perhatikan isi Pasal 28A UUD NRI Tahun 1945 berikut ini!</p><p>Setiap orang berhak untuk hidup serta berhak mempertahankan hidup dan kehidupannya.</p><p>Makna yang terkandung dalam pasal 28A UUD&nbsp; NRI Tahun 1945 adalah ....</p>\n', '<p>setiap orang bebas memeluk agama</p>\n', '<p>setiap warga negara Indonesia memiliki hak yang sama untuk membentuk keluarga dan melanjutkan keturunan melalui perkawinan yang sah </p>\n', '<p>setiap anak sejak dia lahir memiliki hak untuk hidup, tumbuh, berkembang, serta berhak atas perlindungan dari kekerasan dan diskriminasi </p>\n', '<p>tidak ada satu orang pun yang bisa membeli nyawa orang lain atau menghilangkan nyawa orang lain dengan alasan apapun </p>\n', '<p>setiap orang berhak untuk mengembangkan diri dalam hal pendidikan, teknologi dan pengetahun serta seni budaya untuk meningkatkan kualitas hidupnya dan demi kesejahteraan manusia, terutama rakyat Indonesia </p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1764198028, 1764198028, 0, '', 1, 0, 0, '720ef13b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30489, 862, 0, 1, 6, NULL, NULL, NULL, '<p>Perhatikan isi Pasal 29 ayat (2) UUD NRI Tahun 1945 berikut ini!</p><p>Negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan untuk beribadat menurut agamanya dan kepercayaannya itu.</p><p>Makna yang terkandung dalam Pasal 29 ayat (2) UUD NRI Tahun 1945 adalah ....</p>\n', '<p>hanya ada lima agama yang diakui negara</p>\n', '<p>negara berdasarkan atas Ketuhanan Yang Maha Esa </p>\n', '<p>adanya jaminan hukum kebebasan dalam beragama oleh negara </p>\n', '<p>hak hidup dan mempertahankan hidup dan kehidupannya </p>\n', '<p>negara yang rakyatnya beriman dan bertakwa kepada Tuhan Yang Maha Esa </p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1764198028, 1764198028, 0, '', 1, 0, 0, '720ef539-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30490, 862, 0, 1, 7, NULL, NULL, NULL, '<p>Pelanggaran HAM dapat terjadi karena ada faktor yang menjadi penyebabnya, baik itu internal amupun eksternal. Contoh fakta yang tidak menyebabkan pelanggaran HAM adalah .... </p>\n', '<p>terjadinya penyalahgunaan kekuasaan</p>\n', '<p>kurang tegasnya aparat penegak hukum </p>\n', '<p>terjadinya penyalahgunaan teknologi </p>\n', '<p>kesenjangan sosial dan ekonomi yang tinggi </p>\n', '<p>tegasnya aparat penegak hukum dalam menindak pelanggaran </p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1764198028, 1764198028, 0, '', 1, 0, 0, '720ef85a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30491, 862, 0, 1, 8, NULL, NULL, NULL, '<p>Banyak faktor yang menyebabkan pelanggaran HAM, baik faktor internal baik yang disebabkan oleh sang pelaku itu sendiri ataupun faktor eksternal yang disebabkan oleh keluarga, teman, saudara dan lingkungan tempat sipelaku tinggal.</p><p>Contoh faktor internal yang dapat menyebabkan pelanggaran HAM adalah ....</p>\n', '<p>sikap mementingkan kepentingan umum</p>\n', '<p>sikap egois yang tinggi </p>\n', '<p>tingginya sikap toleransi </p>\n', '<p>tingginya kesadaran HAM </p>\n', '<p>tegasnya aparat penegak hukum </p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1764198028, 1764198028, 0, '', 1, 0, 0, '720efb82-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
