INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30560, 862, 0, 4, 7, NULL, NULL, NULL, '<p>Unsur pemersatu diantara warga negara dengan semangat gotong-royong , saling membantu, saling menghormati, rela berkorban, dan menempatkan kepentingan bangsa dan negara diatas kepentingan pribadi dan golongan, hal tersebut merupakan penjabaran Nilai Pancasila dari sila ke - .... </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'Ketiga', 1764198028, 1764198028, 0, '', 1, 0, 0, '720fb13a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30561, 862, 0, 4, 8, NULL, NULL, NULL, '<p>Menghargai hak setiap warga negara untuk&nbsp; bermusyawarah mufakat yang dilakukan tanpa adanya tekanan, paksaan, ataupun intervensi yang membelenggu hak-hak partisipasi masyarakat, hal ini merupakan penjabaran Nilai Pancasila dari sila ke - .... </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'keempat', 1764198028, 1764198028, 0, '', 1, 0, 0, '720fb2f1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30562, 862, 0, 4, 9, NULL, NULL, NULL, '<p>Mengakui hak milik perorangan dan dilindungi pemanfaatannya oleh negara serta memberi kesempatan sebesar-besarnya kepada masyarakat, hal ini merupakan penjabaran Nilai Pancasila dari sila ke - .... </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'kelima', 1764198028, 1764198028, 0, '', 1, 0, 0, '720fb3fb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30563, 862, 0, 4, 10, NULL, NULL, NULL, '<p>Sikap seseorang yang selalu menuntut haknya, sementara kewajibannya sering diabaikan merupakan pelanggaran Hak Asasi Manusia yang disebabkan oleh faktor .... </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'internal', 1764198028, 1764198028, 1, '', 1, 0, 0, '720fb5b4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30564, 862, 0, 5, 1, NULL, NULL, NULL, '<p>Apakah upaya perlindungan dan pemajuan HAM hanya berpedoman pada Pancasila? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Penegakan Hak Asasi Manusia tentu berpedoman pada Pancasila. Namun selain Pancasila hak asasi manusia juga diatur secara lebih dirin didalam peraturan perundang-undangan nasional. Selain itu norma dalam masyarakat pun dapat menjadi pediman dalam penegakan hak asasi manusia, juga dari segi hati nurani dan agama. Jadi pedoman hak asasi manusia Pancasila, peraturan perundang-undangan, norma masyarakat, hingga agama.</p>\n', 1764198028, 1764198028, 0, '', 1, 0, 0, '720fb6c8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30565, 862, 0, 5, 2, NULL, NULL, NULL, '<p>Untuk melindungi, menjamin, dan memajukan hak asasi manusia dibutuhkan instrumen HAM berupa peraturan perundangan dan lembaga penegakan HAM (Seperti KOMNAS HAM). Apa saja 4 fungsi instrumen penegakan HAM? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Fungsi instrumen HAM, diantaranya adalah sebagai berikut :</p><p>Pencegahan pelanggaran HAM</p><p>Jaminan pemajuan HAM</p><p>Perlindungan HAM</p><p>Penegakan HAM</p>\n', 1764198028, 1764198028, 0, '', 1, 0, 0, '720fb8b8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30566, 862, 0, 5, 3, NULL, NULL, NULL, '<p>Upaya Pemerintah dalam membangun supremasi hukum dalam upaya penegakan HAM sangatlah penting. Menurut anda, bagaimanakan kondisi supremasi hukum Indonesia saat ini? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Gambaran Supremasi Hukum di Indonesia diantaranya sebagai berikut:</p><p>masih maraknya budya kekerasan korupsi, kolusi dan nepotisme di institusi penegak hukum</p><p>masih rendahnya budaya hukum yang menghormati HAM</p>\n', 1764198028, 1764198028, 0, '', 1, 0, 0, '720fba5b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30567, 862, 0, 5, 4, NULL, NULL, NULL, '<p>Setelah menerima pengaduan tentang pelanggaran HAM, Komnas&nbsp; HAM kemudian melakukan pemeriksaan. LAngkah seperti apa yang dilakukan oleh Komnas HAM dalam melakukan pemeriksaan? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Tahap pemeriksaan dilakukan dengan memanggil pengadu, saksi atau pihak lain yang terkait. Tujuannya adalah untuk menentukan dilanjutkan atau tidaknya pemeriksaan berdasarkan bukti dalam pemeriksaan.</p>\n', 1764198028, 1764198028, 0, '', 1, 0, 0, '720fbc00-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30568, 862, 0, 5, 5, NULL, NULL, NULL, '<p>Mengapa perlindungan dan penegakan HAM membutuhkan perlindungan ketentuan hukum? </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Supaya keputusan HAM dapat mempunyai kemampuan hukum yang lebih kuat (ada kepastian hukum). Negara bisa melakukan perlindungan, pemenuhan ataupun penegakan HAM pada warganya karena sudah ada dasar hukumnya. Demikian juga orang-orang/ individu bida menikmati maupun menegakkan HAM nya.</p>\n', 1764198028, 1764198028, 0, '', 1, 0, 0, '720fbdf6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30569, 862, 0, 5, 6, NULL, NULL, NULL, '<p>Jelaskan makna HUbungan Internasional! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Sebagai Hubungan yang bersifat global yang meliputi semua hubungan yang terjadi dengan melampaui batas-batas ketatanegaraan.</p>\n', 1764198028, 1764198028, 1, '', 1, 0, 0, '720fc017-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30570, 862, 0, 5, 7, NULL, NULL, NULL, '<p>Jelaskan yang maksud dengan Politik Luar Negeri! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Seperangkat cara/kebijakan yang dilakukan oleh suatu negarauntuk melakukan hubungan dengan negara lain dengan tujuan untuk tercapainya tujuan negara serta kepentingan nasional negara yang bersangkutan.</p>\n', 1764198028, 1764198028, 1, '', 1, 0, 0, '720fc25f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30571, 862, 0, 5, 8, NULL, NULL, NULL, '<p>Jelaskan yang dimaksud dengan Hubungan Luar negeri! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Keseluruhan hubungan yang dijalankan oleh suatu negara dengan semua pihak yang tidak tunduk pada kedaulatannya.</p>\n', 1764198028, 1764198028, 1, '', 1, 0, 0, '720fc46b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30572, 862, 0, 5, 9, NULL, NULL, NULL, '<p>Jelaskan yang dimaksud dengan Politik Internasional! </p>\n', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '<p>Politik antar negara yang mencangkup kepentingan dan tindakan beberapa atau semua negara serta proses interaksi antar negara maupun antar negara dengan organisasi internasional.</p>\n', 1764198028, 1764198028, 1, '', 1, 0, 0, '720fc582-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
