INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30629, 864, 0, 1, 1, NULL, NULL, NULL, 'Ideologi merupakan seperangkat pengetahuan, nilai, keyakinan, dan pandangan dunia yang menjadi landasan pemikiran dan tindakan seseorang atau kelompok dalam bidang politik, sosial, ekonomi, dan budaya. Dalam konteks ini, Pancasila sebagai ideologi negara berfungsi untuk ….', 'Menentukan kebijakan ekonomi dan sosial di Indonesia', 'Menjaga keberagaman budaya Indonesia tanpa ada panduan nilai', 'Menuntun pemahaman dan perilaku warga negara Indonesia terhadap dunia dan sesamanya', 'Menggantikan ideologi lain yang ada di dunia', 'Membatasi kebebasan beragama di Indonesia', NULL, NULL, NULL, NULL, NULL, 'c', 1764198813, 1765172260, 1, '', 1, 0, 0, '721044ed-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30630, 864, 0, 1, 2, NULL, NULL, NULL, 'Koento Wibisono mengidentifikasi tiga unsur esensial dalam ideologi. Salah satu unsur tersebut adalah keyakinan. Dalam konteks ideologi Pancasila, keyakinan ini merujuk pada ….', 'Kepercayaan bahwa Pancasila dapat dijadikan sumber keuntungan ekonomi', 'Gagasan vital yang diyakini kebenarannya sebagai dasar dan strategi mencapai tujuan nasional', 'Mitos bahwa Pancasila adalah ajaran paling kuno di Indonesia', 'Loyalitas tanpa syarat terhadap negara Indonesia', 'Keterlibatan optimal dalam kegiatan politik.', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765172294, 1, '', 1, 0, 0, '721046a0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30631, 864, 0, 1, 3, NULL, NULL, NULL, 'Sebagai bagian dari unsur esensial ideologi, mitos dalam Pancasila diartikan sebagai ….', 'Cerita rakyat yang diwariskan secara turun-temurun', 'Ajaran optimistis bahwa Pancasila akan menjamin tercapainya tujuan melalui cara tertentu', 'Dogma yang tidak dapat diubah oleh generasi berikutnya', 'Kumpulan ritual dan adat istiadat tradisional', 'Simbol-simbol kebudayaan tanpa makna politik', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765172325, 1, '', 1, 0, 0, '721048ac-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30632, 864, 0, 1, 4, NULL, NULL, NULL, 'Pancasila sebagai ideologi negara memberikan pandangan dunia yang konsisten dan menyeluruh mengenai manusia, masyarakat, budaya, ekonomi, agama, dan kekuasaan. Ini berarti Pancasila ….', 'Hanya berfungsi sebagai landasan budaya', 'Hanya diterapkan dalam konteks politik', 'Mengarahkan semua aspek kehidupan masyarakat Indonesia', 'Menjaga agar pemerintah tidak campur tangan dalam urusan agama', 'Membatasi kreativitas dan inovasi masyarakat', NULL, NULL, NULL, NULL, NULL, 'c', 1764198813, 1765172355, 1, '', 1, 0, 0, '72104a14-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
