INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30639, 864, 0, 1, 11, NULL, NULL, NULL, 'Pancasila memiliki ciri sebagai ideologi yang memberikan pandangan dunia secara konsisten dan menyeluruh. Bagaimana implementasi dari pandangan dunia ini bisa dilihat dalam kebijakan pemerintah terkait pluralitas masyarakat Indonesia yang terdiri dari berbagai macam etnis, suku, budaya, bahasa, agama, dan kepercayaan ….', 'Pemerintah menerapkan satu sistem pendidikan yang sama tanpa memperhatikan keberagaman', 'Pemerintah mengembangkan program yang mendorong keberagaman budaya melalui pendidikan, festival, dan peraturan yang menghormati hak asasi manusia', 'Pemerintah mewajibkan semua masyarakat untuk mengikuti satu agama yang diakui negara', 'Pemerintah tidak perlu campur tangan dalam urusan keberagaman budaya dan agama', 'Pemerintah fokus hanya pada pembangunan ekonomi tanpa memperhatikan aspek sosial budaya', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765172576, 1, '', 1, 0, 0, '72105619-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
