INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30647, 864, 0, 1, 19, NULL, NULL, NULL, 'Dalam konteks sebagai leitstar dinamis, Pancasila harus mampu merespons tantangan zaman yang terus berubah. Bagaimana Pancasila dapat beradaptasi dengan perkembangan teknologi informasi dan komunikasi yang pesat ….', 'Pancasila menghambat perkembangan teknologi untuk menjaga nilai tradisional', 'Pancasila menjadi landasan bagi kebijakan yang mendukung pengembangan teknologi secara bertanggung jawab dan etis', 'Pancasila tidak relevan dengan perkembangan teknologi modern', 'Pancasila digunakan untuk membatasi akses masyarakat terhadap informasi global', 'Pancasila hanya berfungsi dalam konteks budaya dan tidak terkait dengan teknologi', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765172870, 1, '', 1, 0, 0, '72106675-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30648, 864, 0, 1, 20, NULL, NULL, NULL, 'Pancasila sebagai dasar negara telah disepakati oleh para pendiri bangsa Indonesia. Bagaimana penerapan nilai-nilai Pancasila dapat membantu Indonesia menghadapi isu global seperti perubahan iklim ….', 'Pancasila hanya mengatur kehidupan politik dan tidak terkait dengan isu lingkungan', 'Pancasila menjadi dasar bagi kebijakan lingkungan yang berkelanjutan dan ramah lingkungan, dengan prinsip gotong-royong dan kesejahteraan Bersama', 'Pancasila tidak relevan dalam konteks globalisasi dan perubahan iklim', 'Pancasila menghambat perkembangan industri demi menjaga lingkungan', 'Pancasila hanya diterapkan pada aspek sosial budaya, bukan lingkungan', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765172902, 1, '', 1, 0, 0, '72106811-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30649, 864, 0, 1, 21, NULL, NULL, NULL, 'Makna yang terkandung dalam sila pertama Pancasila, yaitu Ketuhanan Yang Maha Esa, adalah ....', 'Pengakuan atas kebebasan individu untuk memeluk agama dan kepercayaan masing-masing', 'Kewajiban negara untuk mendirikan agama resmi bagi seluruh rakyat Indonesia', 'Larangan bagi individu untuk menjalankan ibadah sesuai dengan keyakinannya', 'Penekanan pada aspek ritual dan ibadah dalam kehidupan beragama', 'Penegakan nilai-nilai ketuhanan dalam seluruh aspek kehidupan bermasyarakat, berbangsa, dan bernegara', NULL, NULL, NULL, NULL, NULL, 'e', 1764198813, 1765172941, 1, '', 1, 0, 0, '72106a87-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30650, 864, 0, 1, 22, NULL, NULL, NULL, 'Sila kedua Pancasila, yaitu Kemanusiaan yang Adil dan Beradab, mengandung makna ….', 'Pengakuan atas superioritas satu kelompok manusia di atas kelompok lainnya', 'Penolakan terhadap perbedaan suku, agama, ras, dan golongan dalam masyarakat', 'Penegakan hukum yang tegas dan tanpa pandang bulu', 'Perlindungan terhadap hak-hak asasi manusia tanpa terkecuali', 'Penekanan pada aspek materialistik dan hedonistik dalam kehidupan manusia', NULL, NULL, NULL, NULL, NULL, 'd', 1764198813, 1765172981, 1, '', 1, 0, 0, '72106bfd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30651, 864, 0, 1, 23, NULL, NULL, NULL, 'Sila ketiga Pancasila, yaitu Persatuan Indonesia, menekankan pentingnya ....', 'Kebebasan individu untuk mengekspresikan diri tanpa batasan', 'Dominasi budaya dan tradisi satu suku bangsa di atas suku bangsa lainnya', 'Penjagaan keutuhan wilayah dan kedaulatan negara Indonesia', 'Pembubaran organisasi-organisasi yang dianggap mengancam persatuan bangsa', 'Pemaksaan asimilasi budaya dan tradisi bagi seluruh rakyat Indonesia', NULL, NULL, NULL, NULL, NULL, 'c', 1764198813, 1765173025, 1, '', 1, 0, 0, '72106e98-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30652, 864, 0, 1, 24, NULL, NULL, NULL, '<p class=\"MsoNormal\"><span lang=\"IN\">Inti dari\r\nsila keempat Pancasila, yaitu Kerakyatan yang Dipimpin oleh Hikmat\r\nKebijaksanaan dalam Permusyawaratan/Perwakilan, adalah ....</span></p>', '<div><span style=\"font-size: 0.875rem;\">Kebebasan individu untuk bertindak sesuai dengan keinginannya sendiri</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Penyerahan kekuasaan sepenuhnya kepada rakyat tanpa adanya pemimpin</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Pengambilan keputusan berdasarkan suara mayoritas tanpa mempertimbangkan suara minoritas</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Penyelenggaraan pemilihan umum secara berkala untuk memilih pemimpin negara</span><br></div>', '<div><span style=\"font-size: 0.875rem;\">Musyawarah mufakat sebagai cara utama untuk mencapai mufakat dalam pengambilan keputusan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'e', 1764198813, 1764198813, 1, '', 1, 0, 0, '72106ff7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30653, 864, 0, 1, 25, NULL, NULL, NULL, 'Cita-cita yang ingin dicapai oleh bangsa Indonesia melalui pengamalan sila kelima Pancasila, yaitu Keadilan Sosial bagi Seluruh Rakyat Indonesia, adalah ....', 'Membangun masyarakat yang serba kekurangan dan tidak memiliki akses terhadap kebutuhan dasar', 'Menciptakan kesenjangan sosial yang lebar antara kelompok kaya dan kelompok miskin', 'Mewujudkan kehidupan yang adil dan makmur bagi seluruh rakyat Indonesia', 'Memberikan hak istimewa kepada kelompok tertentu dalam masyarakat', 'Membiarkan rakyat Indonesia untuk hidup dalam kemiskinan dan keterbelakangan', NULL, NULL, NULL, NULL, NULL, 'c', 1764198813, 1765173067, 1, '', 1, 0, 0, '72107252-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30654, 864, 0, 1, 26, NULL, NULL, NULL, 'Hubungan antara sila pertama dan sila kedua Pancasila menunjukkan bahwa ....', 'Keberadaan Tuhan Yang Maha Esa tidak relevan dengan kehidupan bermasyarakat', 'Keyakinan terhadap Tuhan Yang Maha Esa mendorong manusia untuk berperilaku adil dan beradab', 'Nilai-nilai kemanusiaan yang adil dan beradab bertentangan dengan ajaran agama', 'Agama tidak memiliki peran dalam mewujudkan keadilan sosial bagi seluruh rakyat Indonesia', 'Sila pertama dan sila kedua Pancasila tidak memiliki keterkaitan satu sama lain', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765173103, 1, '', 1, 0, 0, '72107521-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30655, 864, 0, 1, 27, NULL, NULL, NULL, 'Hubungan antara sila ketiga dan sila keempat Pancasila menunjukkan bahwa ....', 'Persatuan Indonesia dapat dicapai dengan cara memaksakan kehendak mayoritas kepada minoritas', 'Demokrasi di Indonesia harus dijalankan dengan mengedepankan musyawarah mufakat', 'Persatuan Indonesia hanya dapat dicapai dengan cara membubarkan organisasi-organisasi yang dianggap mengancam persatuan bangsa', 'Demokrasi di Indonesia harus dijalankan dengan cara memberikan hak istimewa kepada kelompok tertentu dalam masyarakat', 'Persatuan Indonesia dan demokrasi di Indonesia merupakan dua konsep yang saling bertentangan', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765173137, 1, '', 1, 0, 0, '721077c7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30656, 864, 0, 1, 28, NULL, NULL, NULL, 'Hubungan antara sila keempat dan sila kelima Pancasila menunjukkan bahwa ....', 'Demokrasi di Indonesia hanya dapat dijalankan dengan cara menindas kelompok minoritas', 'Demokrasi di Indonesia harus dijalankan dengan tujuan untuk mewujudkan keadilan sosial bagi seluruh rakyat Indonesia', 'Keadilan sosial bagi seluruh rakyat Indonesia dapat dicapai dengan cara mengabaikan prinsip-prinsip demokrasi', 'Demokrasi di Indonesia dan keadilan sosial bagi seluruh rakyat Indonesia', 'Demokrasi di Indonesia sebagai cara melakukan tindak Korupsi', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765173167, 1, '', 1, 0, 0, '7210792f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30657, 864, 0, 1, 29, NULL, NULL, NULL, 'Bagaimana keterkaitan antara sila pertama (Ketuhanan Yang Maha Esa) dengan sila kedua (Kemanusiaan yang Adil dan Beradab) dalam konteks kehidupan bermasyarakat di Indonesia ….', 'Sila pertama mendorong kehidupan yang adil, sementara sila kedua menekankan pada persatuan Bangsa', 'Pengamalan nilai ketuhanan dalam sila pertama harus terlihat dalam sikap kasih sayang dan keadilan terhadap sesama manusia sebagaimana diatur dalam sila kedua', 'Sila pertama dan kedua tidak memiliki hubungan yang signifikan karena keduanya berdiri sendiri', 'Sila kedua menuntut penghormatan terhadap hak asasi manusia, sedangkan sila pertama menekankan pada pengamalan ajaran agama masing-masing tanpa saling terkait', 'Sila pertama lebih berfokus pada kebebasan beragama, sedangkan sila kedua pada keadilan ekonomi', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1765173204, 1, '', 1, 0, 0, '72107b9e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30658, 864, 0, 1, 30, NULL, NULL, NULL, 'Dalam implementasi sila ketiga (Persatuan Indonesia), apa saja langkah konkret yang bisa dilakukan untuk memperkuat rasa cinta tanah air di tengah keberagaman suku, agama, dan budaya ….', 'Mengadakan festival budaya daerah tanpa melibatkan komunitas lain', 'Membentuk komunitas eksklusif berdasarkan suku atau agama', 'Melakukan kegiatan bersama yang melibatkan seluruh elemen masyarakat dengan latar belakang berbeda untuk memupuk persatuan', 'Menekankan penggunaan bahasa daerah di seluruh instansi pemerintahan', 'Menghindari pembahasan isu-isu kebangsaan yang dapat menimbulkan perdebatan', NULL, NULL, NULL, NULL, NULL, 'c', 1764198813, 1765173237, 1, '', 1, 0, 0, '72107d18-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30659, 864, 0, 1, 31, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Sila\r\nkeempat (Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam\r\nPermusyawaratan/Perwakilan) mengajarkan kita tentang pentingnya prinsip\r\ndemokrasi&nbsp;</span><span style=\"font-size: 0.875rem;\">dalam kehidupan berbangsa dan bernegara. Bagaimana sebaiknya prinsip ini\r\nditerapkan dalam konteks pemilihan pemimpin di sekolah ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengangkat pemimpin sekolah berdasarkan penunjukan langsung oleh guru</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melakukan pemilihan pemimpin melalui musyawarah yang melibatkan seluruh siswa untuk mencapai kesepakatan bersama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memilih pemimpin sekolah berdasarkan popularitas tanpa mempertimbangkan kompetensi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengadakan pemungutan suara tertutup hanya di kalangan guru dan staf sekolah</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menetapkan pemimpin berdasarkan prestasi akademik saja</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1764198813, 0, '', 1, 0, 0, '72107ec3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30660, 864, 0, 1, 32, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Bagaimana\r\nketerkaitan antara sila ketiga (Persatuan Indonesia) dengan sila kelima\r\n(Keadilan Sosial bagi Seluruh Rakyat Indonesia) dalam pembangunan nasional ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia hanya mementingkan kesatuan budaya, sementara keadilan sosial hanya mementingkan aspek ekonomi</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia mendasari upaya bersama seluruh rakyat untuk mencapai kesejahteraan yang merata dan adil bagi semua</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Keadilan sosial hanya dapat dicapai jika tidak ada keberagaman budaya di Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia dan keadilan sosial tidak berhubungan langsung dalam pembangunan nasional</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Persatuan Indonesia lebih berfokus pada aspek politik, sedangkan keadilan sosial pada aspek ekonomi</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1764198813, 0, '', 1, 0, 0, '72108118-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30661, 864, 0, 1, 33, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Dalam\r\nkaitannya dengan sila pertama (Ketuhanan Yang Maha Esa), bagaimana seharusnya\r\nbangsa Indonesia menerapkan nilai-nilai keagamaan dalam menjaga kelestarian\r\nlingkungan hidup ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melarang semua bentuk aktivitas ekonomi yang dapat merusak lingkungan</span></div>', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Menggalakkan kegiatan keagamaan yang juga mengajarkan pentingnya menjaga alam ciptaan Tuhan</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengutamakan pertumbuhan ekonomi tanpa memedulikan dampak lingkungan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menyerahkan sepenuhnya urusan lingkungan kepada pemerintah tanpa melibatkan masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengadakan acara-acara religius di kawasan hutan tanpa memperhatikan dampaknya</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1764198813, 0, '', 1, 0, 0, '721082a0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30662, 864, 0, 1, 34, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Di tengah\r\nmasyarakat yang majemuk, terdapat kelompok-kelompok yang memiliki keyakinan dan\r\ntradisi yang berbeda-beda. Dalam konteks sila pertama Pancasila, sikap yang\r\ntepat untuk mewujudkan toleransi dan kerukunan antarumat beragama adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memaksakan keyakinan pribadi kepada orang lain</span><br></div><div><p></p></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengadakan dialog antarumat beragama untuk saling memahami dan menghargai perbedaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Melarang praktik ibadah agama tertentu yang dianggap bertentangan dengan norma sosial</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membentuk organisasi keagamaan yang ekslusif dan hanya menerima anggota dari satu agama</span><br></div>', '<div><span style=\"font-size: 0.875rem; text-align: justify;\">Mengucilkan individu atau kelompok yang berbeda keyakinan dari kehidupan sosial</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1764198813, 0, '', 1, 0, 0, '721084f5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30663, 864, 0, 1, 35, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">&nbsp;</span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Persatuan\r\nIndonesia merupakan salah satu pilar penting dalam mewujudkan cita-cita\r\nkemerdekaan bangsa. Dalam kehidupan sehari-hari, wujud nyata dari pengamalan\r\nsila ketiga Pancasila adalah ....</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengikuti kegiatan gotong royong membersihkan lingkungan bersama-sama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mempelajari dan melestarikan budaya daerah lain di Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menonton pertandingan sepak bola tim nasional Indonesia dengan penuh semangat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Membeli produk-produk buatan dalam negeri</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Semua jawaban benar</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'e', 1764198813, 1764198813, 0, '', 1, 0, 0, '72108664-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30664, 864, 0, 1, 36, NULL, NULL, NULL, '<p class=\"MsoNormal\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Demokrasi\r\ndi Indonesia merupakan hasil perjuangan para pahlawan dan pendiri bangsa.</span></div><span lang=\"IN\"><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Dalam konteks sila keempat Pancasila, demokrasi yang ideal di Indonesia\r\nharuslah ....</span></div></span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Diterapkan secara langsung oleh rakyat, tanpa melibatkan perwakilan rakyat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Diberlakukan dengan sistem mayoritas absolut, di mana suara mayoritas selalu menentukan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Dilaksanakan dengan mengedepankan musyawarah mufakat untuk mencapai mufakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Diterapkan dengan sistem otoriter, di mana pemimpin memiliki kekuasaan absolut</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Dilaksanakan dengan mengedepankan kepentingan individu di atas kepentingan bersama</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1764198813, 1764198813, 0, '', 1, 0, 0, '72108881-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30665, 864, 0, 1, 37, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Apa yang\r\nterjadi jika salah satu sila Pancasila dihilangkan ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila tetap utuh</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Makna kesatuan Pancasila hilang</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Pancasila menjadi lebih kuat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya sila yang dihilangkan yang berkurang maknanya</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Tidak ada perubahan signifikan</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1764198813, 0, '', 1, 0, 0, '72108a07-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30666, 864, 0, 1, 38, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Apa makna\r\ndari \"Ketuhanan Yang Maha Esa\" dalam konteks Pancasila ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara berdasarkan agama tertentu</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara sekuler tanpa agama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara yang menjamin kebebasan beragama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara yang tidak mempedulikan kepercayaan</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Negara yang hanya mengakui satu agama</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'c', 1764198813, 1764198813, 0, '', 1, 0, 0, '72108c40-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30667, 864, 0, 1, 39, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Apa arti\r\ndari \"Kemanusiaan yang Adil dan Beradab\" ….</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span style=\"font-size: 0.875rem;\">Mengedepankan\r\nkepentingan pribadi</span><br></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memperlakukan semua manusia dengan martabat yang sama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengabaikan norma-norma sosial</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Hanya berlaku untuk kelompok tertentu</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menyebarkan budaya tertentu saja</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1764198813, 0, '', 1, 0, 0, '72108dc3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30668, 864, 0, 1, 40, NULL, NULL, NULL, '<p class=\"MsoNormal\" style=\"text-align: justify; \"><span lang=\"IN\">Apa tujuan\r\ndari sila \"Persatuan Indonesia\" ….</span></p>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mewujudkan perpecahan di antara suku dan agama</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mengembangkan kerukunan hidup dalam masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Memisahkan berbagai budaya di Indonesia</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Mendorong individualisme di kalangan masyarakat</span><br></div>', '<div><span style=\"text-align: justify; font-size: 0.875rem;\">Menyebarkan ideologi asing</span><br></div>', NULL, NULL, NULL, NULL, NULL, 'b', 1764198813, 1764198813, 0, '', 1, 0, 0, '72108f29-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30669, 864, 0, 5, 1, NULL, NULL, NULL, 'Berikan argumentasi yang menjelaskan bahwa sila-sila dalam Pancasila memiliki keterkaitan!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Mohammad Hatta dalam tulisannya berjudul Pengertian Pancasila (1977) menjelaskan bahwa sila-sila Pancasila tidak berdiri sendiri dan saling terpisah. Kelima sila tersebut membentuk satu kesatuan sebagai dasar dan ideologi negara yang makna dan penerapannya tidak bisa dipisah-pisah. Dalam konteks ini, sebagai sila pertama, Ketuhanan Yang Maha Esa hadir menjadi sila yang memimpin atau menjiwai seluruh sila-sila lainnya. Untuk itu, pengamalan sila ketuhanan dalam Pancasila tidak hanya dalam bentuk-bentuk peribadatan agama/keyakinan seseorang, tetapi lebih luas dalam bentuk sikap mengasihi sesama manusia, membangun persatuan bangsa, aktif berdemokrasi, hingga mewujudkan kesejahteraan bersama sebagaimana diajarkan dalam sila kedua sampai kelima.</span><br></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Begitu pun sebaliknya, pengamalan seseorang terhadap sila kemanusiaan, persatuan, kerakyatan, dan keadilan sosial dalam Pancasila, mesti dilihat sebagai bentuk keimanan dan ketakwaannya terhadap Tuhan Yang Maha Esa sebagaimana diajarkan oleh sila pertama.<br></span></p></div></body></html>', 1764198813, 1765173373, 1, '', 1, 0, 0, '7210916d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30670, 864, 0, 5, 2, NULL, NULL, NULL, 'Jelaskan bentuk keterkaitan antara sila pertama dan sila kelima Pancasila!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Keterkaitan antara sila pertama dan kelima melahirkan prinsip ketuhanan yang diamalkan dalam bentuk perilaku adil terhadap sesama serta berempati pada orang lain yang berada dalam kondisi kekurangan atau membutuhkan bantuan, seperti kemiskinan dan sebagainya. Sebaliknya, berbagai perilaku yang mencerminkan empati atau sikap kepedulian sosial tersebut harus dianggap sebagai bentuk perwujudan keimanaan dan ketakwaannya kepada Tuhan Yang Maha Esa.</span></p></div></body></html>', 1764198813, 1765173383, 1, '', 1, 0, 0, '721092d7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30671, 864, 0, 5, 3, NULL, NULL, NULL, 'Jelaskan dan berikan contoh perilaku yang menunjukkan pengamalan Pancasila dalam kehidupan sehari-hari!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Sebagai dasar dan ideologi negara serta pandangan hidup bangsa, Pancasila seharusnya diaktualisasikan oleh setiap individu bangsa Indonesia dalam kehidupan sehari-hari. Namun demikian, dalam realitanya seringkali hal itu sulit praktikkan. Ini membuktikan bahwa terkadang masyarakat masih mengabaikan pengamalan sila-sila Pancasila.</span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Ada beberapa contoh perilaku yang memperlihatkan bentuk pengamalan sila-sila Pancasila dalam kehidupan sehari-hari, yaitu:<p></p></span></p><ul><li style=\"text-align: justify;\"><span lang=\"IN\">Sila pertama, menghormati perbedaaan agama atau keyakinan lain<p></p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Sila kedua, menolong masyarakat yang sedang tertimpa musibah bencana alam<p></p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Sila ketiga, mempergunakan produk-produk buatan dalam negeri<p></p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Sila keempat, menghargai pendapat orang lain saat berdiskusi dalam sebuah rapat<p></p></span></li><li style=\"text-align: justify;\"><span lang=\"IN\">Sila kelima, tidak melakukan tindakan yang bersifat pemborosan dan gaya hidup mewah</span></li></ul></div></div></body></html>', 1764198813, 1765173393, 1, '', 1, 0, 0, '721094e7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30672, 864, 0, 5, 4, NULL, NULL, NULL, 'Mengapa Pancasila berkedudukan sebagai ideologi Negara Republik Indonesia?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pancasila berkedudukan sebagai ideologi Negara Republik Indonesia karena Pancasila merupakan orientasi yang memandu negara Indonesia untuk mencapai tujuannya, yakni merdeka, bersatu, berdaulat, adil, dan Makmur sebagaimana dinyatakan dalam Pembukaan UUD NRI Tahun 1945. Nilai-nilai ketuhanan, kemanusiaan, persatuan, musyawarah mufakat, dan keadilan sosial yang tercermin sebagai ekspresi budaya, corak perekonomian, kehidupan sosial, dan spiritualitas masyarakat yang terdapat di dalam Pancasila merupakan modal sekaligus penuntun bagi terwujudnya cita-cita tersebut.</span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span lang=\"IN\">Jika Pancasila sebagai ideologi negara ditinggalkan, mustahil tujuan atau cita-cita tersebut dapat terwujud. Dengan demikian, Pancasila niscaya berkedudukan sebagai Ideologi Negara Republik Indonesia.</span></p></div></div></body></html>', 1764198813, 1765173401, 1, '', 1, 0, 0, '72109887-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30673, 864, 0, 5, 5, NULL, NULL, NULL, 'Jelaskan apa yang dimaksud dengan Pancasila sebagai Leitstar dinamis!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Pancasila sebagai Leitstar dinamis memiliki maksud bahwa Pancasila merupakan bintang penuntun yang menggerakkan dan mengarahkan bangsa Indonesia dalam merespons dan mengantisipasi tantangan-tantangan setiap zaman yang terus berubah. Pancasila mampu membuat negara Indonesia mengatasi tantangan dan tuntutan yang ada serta mampu membuat negara Indonesia adaptif terhadap tantangan zaman tanpa harus meninggalkan prinsip-prinsip yang mendasarinya dan cita-cita yang ingin dicapai olehnya. Dalam hal ini pula, Pancasila menyediakan cita-cita, kemauan, dan kemampuan untuk mewujudkannya.</span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Nilai ketuhanan mencita-citakan masyarakat yang mengejar kebajikan dan kebaikan serta dapat menjalankan ibadah tanpa hambatan. Nilai kemanusiaan mencita-citakan masyarakat yang memperlakukan sesamanya secara adil dan beradab. Nilai kebangsaan mencita-citakan masyarakat yang berwatak persatuan, gotong-royong, dan mencintai tanah air. Nilai kerakyatan/demokrasi mencita-citakan kedaulatan rakyat dengan asas permusyawaratan melalui lembaga perwakilan. Nilai keadilan sosial mencita-citakan masyarakat yang adil dan makmur.</span></p></div></body></html>', 1764198813, 1765173408, 1, '', 1, 0, 0, '72109a41-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30674, 864, 0, 3, 1, NULL, NULL, NULL, 'Cobalah kalian cocokan Simbol Lambang Negara dengan sila-sila Pancasila.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p><img src=\\\"uploads\\/bank_soal\\/img_86431_4468cb3bacee6a30b0c8.png\\\" data-filename=\\\"Screenshot 2024-10-18 093105.png\\\" style=\\\"width: 224px;\\\"><br><\\/p><\\/body><\\/html>\",\"<p><img src=\\\"uploads\\/bank_soal\\/img_86431_8cb0ea68de768d7a335a.jpg\\\" data-filename=\\\"SILA 5.jpg\\\" style=\\\"width: 227px;\\\"><\\/p><\\/body><\\/html>\",\"<p><img src=\\\"uploads\\/bank_soal\\/img_86431_c932588ed12638e32018.png\\\" data-filename=\\\"Screenshot 2024-10-18 093035.png\\\" style=\\\"width: 226px;\\\"><br><\\/p><\\/body><\\/html>\",\"<p><img src=\\\"uploads\\/bank_soal\\/img_86431_b0a34f4e9c2d19807b54.png\\\" data-filename=\\\"Screenshot 2024-10-18 093621.png\\\" style=\\\"width: 215px;\\\"><br><\\/p><\\/body><\\/html>\",\"<p><img src=\\\"uploads\\/bank_soal\\/img_86431_c0c9bc59b376562d672e.png\\\" data-filename=\\\"Screenshot 2024-10-18 093135.png\\\" style=\\\"width: 224px;\\\"><br><\\/p><\\/body><\\/html>\"],[\"<p>Ketuhanan Yang Maha Esa<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Kemanusiaan Yang Adil dan Beradab<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Persatuan Indonesia<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Kerakyatan Yang Dipimpin Oleh Hikmat Kebijaksanaan Dalam Permusyawaratan Perwakilan<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Keadilan Sosial Bagi Seluruh Rakyat Indonesia<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"]]}', 1764198813, 1765173321, 1, '', 1, 0, 0, '72109cab-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30675, 864, 0, 3, 2, NULL, NULL, NULL, 'Cocokanlah perilaku berikut ini sesuai dengan nilai-nilai Pancasila.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>Menghargai keseimbangan antara kepentingan pribadi dan masyarakat<\\/p><\\/body><\\/html>\",\"Musyawarah merupakan cermin sikap dan pandangan hidup bahwa kemauan rakyat adalah kebenaran dan keabsahan yang tinggi\",\"<p>Mengembangkan kehidupan toleransi baik antar, inter, maupun antar umat beragama<\\/p><\\/body><\\/html>\",\"<p>Setiap rakyat Indonesia diperlakukan secara adil dalam bidang hukum, ekonomi, kebudayaan dan sosial<\\/p><\\/body><\\/html>\",\"<p>Bentuk kesadaran manusia terhadap potensi budi nurani dalam hubungan dengan norma-norma kebudayaan pada umumnya<br><\\/p><\\/body><\\/html>\"],[\"<p>Ketuhanan Yang Maha Esa<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Kemanusiaan Yang Adil dan Beradab<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Persatuan Indonesia<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Kerakyatan Yang Dipimpin Oleh Hikmat Kebijaksanaan Dalam Permusyawaratan Perwakilan<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Keadilan Sosial Bagi Seluruh Rakyat Indonesia<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"]]}', 1764198813, 1765173326, 1, '', 1, 0, 0, '72109eda-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30676, 864, 0, 3, 3, NULL, NULL, NULL, 'Cocokkanlah pernyataan berikut ini sesuai konsep nilai-nilai Pancasila dalam pemahaman metafisis.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>Keadilan dalam kehidupan sosial terutama meliputi bidang ideologi, politik, ekonomi, sosial, kebudayaan dan pertahanan keamanan nasional<\\/p><\\/body><\\/html>\",\"<p>Manusia Indonesia sebagai warga negara dan warga masyarakat Indonesia mempunyai kedudukan, hak dan kewajiban yang sama<\\/p><\\/body><\\/html>\",\"<p>Pengakuan terhadap perbedaan suku bangsa (etnis) dan kebudayaan bangsa yang memberikan arah dalam pembinaan kesatuan bangsa<\\/p><\\/body><\\/html>\",\"<p>Pengertian manusia yang beradab yang memiliki daya cipta, rasa, karsa dan keyakinan sehingga jelas adanya perbedaan antara manusia dan hewan<\\/p><\\/body><\\/html>\",\"<p>Ketakwaan terhadap Tuhan Yang Maha Esa dengan menjalankan semua perintahnya dan menjauhi segala larangannya<\\/p><\\/body><\\/html>\"],[\"<p>NIlai Ketuhanan<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Nilai Kemanusiaan<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Nilai Persatuan<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Nilai Kerakyatan<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Nilai Keadilan<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"]]}', 1764198813, 1765173332, 1, '', 1, 0, 0, '7210a119-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30677, 864, 0, 3, 4, NULL, NULL, NULL, 'Cocokkanlah pernyataan berikut sesuai dengan definisi konsep ideologi Pancasila menurut para ahli.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>Menurut Terminologi<br><\\/p><\\/body><\\/html>\",\"<p>Menurut Notonegoro<br><\\/p><\\/body><\\/html>\",\"<p>Menurut Ir. Soekarno<br><\\/p><\\/body><\\/html>\",\"<p>Menurut Muh. Yamin<br><\\/p><\\/body><\\/html>\"],[\"<p>Pancasila merupakan nilai dasar yang berisi pedoman atau aturan tentang tingkah laku yang penting dan baik<br><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Pancasila adalah isi jiwa bangsa Indonesia yang turun temurun yang sekian abad lamanya terpendam bisu oleh kebudayaan barat. Dengan demikian, Pancasila tidak saja falsafah negara tetapi lebih luas lagi, yakni falsafah bangsa Indonesia.<br><\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Pancasila pada hakikatnya merupakan dasar falsafah dan ideologi negara yang diharapkan menjadi pandangan hidup bangsa Indonesia sebagai dasar pemersatu, lambang persatuan dan kesatuan serta sebagai pertahanan bangsa dan negara Indonesia.<br><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\"],[\"<p><span style=\\\"background-color: rgb(240, 255, 220);\\\">Pancasila memliki arti 5 asas dasar yang digunakan oleh Presiden Soekarno untuk memberi nama lima prinsip dasar negara Indonesia yang diusulkannya.<\\/span><br><\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\"]]}', 1764198813, 1765173336, 1, '', 1, 0, 0, '7210a342-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30678, 864, 0, 3, 5, NULL, NULL, NULL, 'Pasangkanlah definisi berikut ini sesuai dengan nilai dan maknanya.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>Kesejahteraan<\\/p><\\/body><\\/html>\",\"<p>Kebijaksanaan<\\/p><\\/body><\\/html>\",\"<p>Mufakat<\\/p><\\/body><\\/html>\",\"<p>Keberadaban<\\/p><\\/body><\\/html>\",\"<p>Keadilan<\\/p><\\/body><\\/html>\"],[\"<p>Suatu sikap yang mampu menempatkan makhluk dengan segala permasalahannya sesuai dengan hak dan kewajiban serta harkat martabatnya secara proporsional dengan diselaraskan dengan dengan peran, fungsi dan kedudukannya.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Merupakan keadaan yang menggambarkan setiap komponen dalam kehidupan bersama berpegang pada peradaban yang mencerminkan nilai luhur budaya bangsa.&nbsp;<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Suatu sikap terbuka untuk menghasilakan kesepakatan bersama secara musyawarah. Keputusan sebagai hasil mufakat secara musyawah harus dipegang teguh dan wajib dipatuhi dalam kehidupan bersama.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Sikap yang menggambarkan hasil olah pikir dan olah rasa yang bersumber dari hati nurani dan bersendi pada kebenaran, keadilan dan keutamaan.<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Kondisi yang menggambarkan terpenuhinya tuntutan kebutuhan manusia, baik kebutuhan lahiriah maupun batiniah sehingga terwujud rasa puas diri, tentram, damai, dan bahagia.&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"]]}', 1764198813, 1765173341, 1, '', 1, 0, 0, '7210a57b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:43', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
