INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30720, 841, 0, 1, 1, NULL, NULL, NULL, ' She ____ to the library every Saturday', 'go', 'goes', 'going', 'gone', 'went', NULL, NULL, NULL, NULL, NULL, 'b', 1764205517, 1765348502, 1, '', 1, 0, 0, '7210f4d7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:44', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30721, 858, 0, 5, 1, NULL, NULL, NULL, '<p>Sebuah mobil listrik bergerak pada jalan datar dengan kecepatan konstan. Mobil tersebut mengubah energi listrik dari baterai menjadi energi kinetik untuk bergerak. Namun, ketika mobil menuruni bukit, energi kinetik dan energi potensial berubah secara bersamaan.</p><p><strong data-start=\"419\" data-end=\"434\">Pertanyaan:</strong><br data-start=\"434\" data-end=\"437\">\r\na. Jelaskan perubahan bentuk energi yang terjadi saat mobil <strong data-start=\"497\" data-end=\"515\">menuruni bukit</strong>.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Saat mobil menuruni bukit, energi potensial gravitasi <strong data-start=\"810\" data-end=\"823\">berkurang</strong>, dan perubahan tersebut diubah menjadi <strong data-start=\"863\" data-end=\"881\">energi kinetik</strong> (mobil bergerak lebih cepat) dan sebagian menjadi <strong data-start=\"932\" data-end=\"948\">energi panas</strong> akibat gesekan dan hambatan udara.', 1764205596, 1764205820, 1, '', 1, 0, 0, '7210f635-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:44', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30722, 858, 0, 5, 2, NULL, NULL, NULL, '<p data-start=\"1495\" data-end=\"1667\">Seorang atlet mendorong sebuah kereta dorong (trolley) bermassa 40 kg hingga kecepatannya meningkat dari 2 m/s menjadi 6 m/s. Setelah itu kereta melaju tanpa didorong lagi.</p>\r\n<p data-start=\"1669\" data-end=\"1879\"><strong data-start=\"1669\" data-end=\"1684\">Pertanyaan:</strong><br data-start=\"1684\" data-end=\"1687\">\r\na. Hitung perubahan energi kinetik kereta.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ek awal = ½·40·2² = 80 J<br data-start=\"1927\" data-end=\"1930\">\r\nEk akhir = ½·40·6² = 720 J<br data-start=\"1956\" data-end=\"1959\">\r\nΔEk = 720 – 80 = <strong data-start=\"1976\" data-end=\"1985\">640 J</strong>', 1764205598, 1764205880, 1, '', 1, 0, 0, '7210f929-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:44', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30723, 858, 0, 5, 3, NULL, NULL, NULL, '<p data-start=\"2538\" data-end=\"2725\">Seorang insinyur bangunan ingin merancang sistem penampungan air di lantai atas sebuah gedung. Tangki air berada pada ketinggian 25 m di atas tanah dan memiliki massa air maksimum 500 kg.</p>\r\n<p data-start=\"2727\" data-end=\"3028\"><strong data-start=\"2727\" data-end=\"2742\">Pertanyaan:</strong><br data-start=\"2742\" data-end=\"2745\">\r\na. Hitung energi potensial maksimum air dalam tangki (g = 10 m/s²).</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ep = mgh = 500 × 10 × 25 = <strong data-start=\"3079\" data-end=\"3092\">125.000 J</strong>', 1764205599, 1764205938, 1, '', 1, 0, 0, '7210fc07-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:44', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30724, 858, 0, 5, 4, NULL, NULL, NULL, '<p data-start=\"175\" data-end=\"420\">Sebuah rumah menggunakan <strong data-start=\"200\" data-end=\"228\">setrika listrik 400 watt</strong> selama <strong data-start=\"236\" data-end=\"248\">30 menit</strong> untuk menyetrika pakaian.<br data-start=\"274\" data-end=\"277\">\r\nSetelah 10 menit penggunaan, suhu setrika naik sangat cepat sehingga otomatisnya memutus arus, kemudian menyala kembali setelah beberapa menit.</p>\r\n<p data-start=\"422\" data-end=\"705\"><strong data-start=\"422\" data-end=\"437\">Pertanyaan:</strong><br data-start=\"437\" data-end=\"440\">\r\na. Hitung <strong data-start=\"450\" data-end=\"468\">energi listrik</strong> yang digunakan setrika selama 30 menit (dalam joule).</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><div>Energi listrik:<br data-start=\"744\" data-end=\"747\">\r\n<span class=\"katex\"><span class=\"katex-mathml\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo>=</mo><mi>P</mi><mo>×</mo><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">E = P \\times t</annotation></semantics></math></span><span class=\"katex-html\" aria-hidden=\"true\"><span class=\"base\"><span class=\"strut\"></span><span class=\"mord mathnormal\">E</span><span class=\"mspace\"></span><span class=\"mrel\">=</span><span class=\"mspace\"></span></span><span class=\"base\"><span class=\"strut\"></span><span class=\"mord mathnormal\">P</span><span class=\"mspace\"></span><span class=\"mbin\">×</span><span class=\"mspace\"></span></span><span class=\"base\"><span class=\"strut\"></span><span class=\"mord mathnormal\">t</span></span></span></span><br data-start=\"767\" data-end=\"770\">\r\n= 400 W × (30 × 60 s)<br data-start=\"791\" data-end=\"794\">\r\n= 400 × 1800 = <strong data-start=\"809\" data-end=\"822\">720.000 J</strong></div></div></div>', 1764205604, 1764303532, 1, '', 1, 0, 0, '7210fe95-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:44', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30726, 858, 0, 5, 5, NULL, NULL, NULL, '<p data-start=\"1303\" data-end=\"1418\">Sebuah lampu LED membutuhkan daya <strong data-start=\"1337\" data-end=\"1348\">12 watt</strong>, tetapi cahaya yang dihasilkan setara dengan lampu pijar <strong data-start=\"1406\" data-end=\"1417\">60 watt</strong>.</p>\r\n<p data-start=\"1420\" data-end=\"1726\"><strong data-start=\"1420\" data-end=\"1435\">Pertanyaan:</strong><br data-start=\"1435\" data-end=\"1438\">\r\na. Mengapa lampu LED dapat menghasilkan cahaya setara lampu pijar tetapi menggunakan daya lebih kecil?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '&nbsp;LED lebih efisien karena hampir seluruh energi listrik diubah menjadi <strong data-start=\"1818\" data-end=\"1835\">energi cahaya</strong>, tidak banyak terbuang sebagai panas seperti lampu pijar.', 1764205605, 1764206086, 1, '', 1, 0, 0, '72110134-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:44', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
