INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30768, 841, 0, 1, 16, NULL, NULL, NULL, '<p style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Venice is a city in northern Italy. It has been known as the Queen of the Adriatic, City of Bridges, and The City of Light. The city stretches across 117 small islands in the marshy Venetian Lagoon along the Adriatic Sea in northeast Italy. Venice is world famous for its canals. It is built on an archipelago of 117 islands formed by about 150 canals in a shallow lagoon. The islands on which the city is built are connected by about 400 bridges. In the old center, the canals serve the function of roads, and every form of transport is on water or on foot. You can ride gondola there. It is the classical Venetian boat which nowadays is mostly used for tourists, or weddings, funerals, or other ceremonies. Now, most Venetians travel by moto rise waterbuses which ply regular routes along the major canals and between the city islands. The city has many private boats. The only gondolas still in common use by Venetians are the Traghetti, foot passenger ferries crossing the Grand Canal at certain points without bridges.</span></p><p style=\"text-align: justify;\">What does the text tell you about....</p>', 'Gondola', 'Traghetti', 'Venice', 'Italy', 'Venetian boat', NULL, NULL, NULL, NULL, NULL, 'c', 1764211645, 1764225349, 1, '', 1, 0, 0, '72116597-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:47', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30769, 841, 0, 5, 1, NULL, NULL, NULL, '<p>Narrative text is a text that tell a story which aim to entertain the audience. It has elements such as plot, characters, and point of view. It consist of orientation, complication, and resolution. It often uses past tense</p><p>Write a short narrative about your most memorable holiday (5–6 sentences).</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '“Last summer, I went to Bali with my family. We visited the beach and tried surfing. One day, we explored a small village and met local people. I learned how they make traditional crafts. It was a very exciting experience that I will never forget.”', 1764211814, 1764212288, 1, '', 1, 0, 0, '721166f8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:47', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30770, 841, 0, 5, 2, NULL, NULL, NULL, '<p>Descriptive text is a text that explains and describes a person, place, or thing. It uses adjectives and adverbs. It aims to describe a person, place or thing. It consists of the identification of a person, place or thing and their description</p><p><span style=\"font-size: 0.875rem;\">Describe your best friend in 5 sentence!</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '“My best friend is Rina. She is very kind and funny. She always helps me when I am sad. We like to study together. I am happy to have her as my friend.”', 1764212297, 1764217706, 1, '', 1, 0, 0, '721168a2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:47', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
