INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30821, 865, 0, 2, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Secara garis besar, bahan pangan dapat dikelompokkan menjadi dua yaitu bahan pangan asal tumbuhan (nabati) dan bahan pangan asal hewan (hewani). Bahan pangan nabati adalah bahan-bahan makanan yang berasal dari tanaman.\r\nBerikut ini beberapa jenis bahan pangan:</p><ol><li>\r\nIkan, telur dan susu\r\n</li><li> Sayur, daun, dan pisang\r\n</li><li>Kelapa, bunga pepaya, dan daun bawang\r\n</li><li>Susu, ayam, dan telur\r\n</li></ol><p>Dari beberapa jenis pangan di atas yan termasuk dalam kelompok tumbuhan nabati adalah:</p>', 'a:3:{s:1:\"a\";s:288:\"<p class=\"MsoNormal\"><span style=\"color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Ikan, telur dan susu</span><o:p></o:p></p>\";s:1:\"b\";s:28:\"<p>Susu, ikan, dan telur</p>\";s:1:\"c\";s:32:\"<p>Sayur, kelapa, dan pisang</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1764213688, 1764213688, 1, '', 1, 0, 0, '7211d131-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:47', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30822, 865, 0, 2, 5, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Bahan makanan yang berasal dari tanaman (bisa berupa akar, batang, dahan, daun, bunga, buah atau beberapa bagian dari tanaman bahkan keseluruhannya) atau bahan makanan yang diolah dari bahan dasar dari tanaman. Bahan pangan hewani merupakan bahan-bahan makanan yang berasal dari hewan atau olahan yang bahan dasarnya dari hasil hewan.\r\n</p><p>\r\nDari penjelasan diatas merupakan pengertian dari!</p>', 'a:4:{s:1:\"a\";s:13:\"<p>Nabati</p>\";s:1:\"b\";s:13:\"<p>Hewani</p>\";s:1:\"c\";s:26:\"<p>Pertumbuhan makanan</p>\";s:1:\"d\";s:20:\"<p>Bahan makanan</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1764213688, 1764213688, 1, '', 1, 0, 0, '7211d2a9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:47', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
