INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30851, 866, 0, 3, 4, NULL, NULL, NULL, '<p>Perhatikan jenis sayuran dan buah-buahan dibawah ini! </p><p>\r\n\r\n1. Apel\r\n</p><p>\r\n2. Tomat </p><p>\r\n\r\n3. Mangga\r\n</p><p>\r\n4. Wortel\r\n</p><p>\r\nTentukan manakah yang termasuk dalam jenis sayur-sayuran dan buah-buahan!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:7:\"SAYURAN\";i:2;s:11:\"BUAH-BUAHAN\";}i:1;a:3:{i:0;s:4:\"Apel\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:5:\"Tomat\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:6:\"Mangga\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:6:\"Wortel\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1764213829, 1764213829, 1, '', 1, 0, 0, '72120fbe-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:47', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30852, 866, 0, 3, 5, NULL, NULL, NULL, '<p>Secara garis besar, bahan pangan dapat dikelompokkan menjadi dua yaitu bahan pangan asal tumbuhan (nabati) dan bahan pangan asal hewan (hewani). Bahan pangan nabati adalah bahan-bahan makanan yang berasal dari tanaman (bisa berupa akar, batang, dahan, daun, bunga, buah atau beberapa bagian dari tanaman bahkan keseluruhannya) atau bahan makanan yang diolah dari bahan dasar dari tanaman.  Sumber bahan nabati dapat kita produksi sendiri disekolah maupun dirumah salah satu contohnya adalah dengan berkebun hidroponik disekolah, dengan berkebun hidroponik kita dapat memperoleh bahan nabati seperti sayur dan buah yang segar dan sehat karena tidak menggunakan pestisida.\r\n\r\nBahan pangan hewani merupakan bahan-bahan makanan yang berasal dari hewan atau olahan yang bahan dasarnya dari hasil hewan. Kedua bahan pangan ini memiliki karakteristik yang berbeda sehingga memerlukan penanganan dan pengolahan yang berbeda pula. Selanjutnya dalam hal ini yang diuraikan adalah bahan pangan hewani. </p><p>\r\n\r\nDari pembahasan diatas tentukan jenis pangan Nabati dan Hewani sesuai dengan jenis kelompoknya!</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:6:\"Nabati\";i:2;s:6:\"hewani\";}i:1;a:3:{i:0;s:5:\"Sayur\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:4:\"Daun\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:4:\"Susu\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:4:\"Buah\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:4:\"Ikan\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:5:\"Telur\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1764213829, 1764213829, 1, '', 1, 0, 0, '7212112b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:47', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
