INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30953, 821, 0, 1, 17, NULL, NULL, NULL, 'Ukuran panjang dari lapangan sepak bola adalah ...', ' 100 m - 120 m', '100 m - 110 m', '80 m - 90 m', '60 m - 70 m', '75m-70m', NULL, NULL, NULL, NULL, NULL, 'b', 1764221327, 1764993982, 1, '', 1, 0, 0, '72129231-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30954, 841, 0, 3, 3, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Ki Hadjar Dewantoro, original name Raden Mas (Lord) Suwardi Surjaningrat (born May 2, 1889, Yogyakarta, Javadied April 26, 1959, Yogyakarta), founder of the Taman Siswa school system, an influential and widespread network of schools that encouraged modernization but also promoted indigenous Indonesian culture.</p><p style=\"text-align: justify;\">Dewantoro was born into a noble family of Yogyakarta and attended a Dutch-sponsored medical school but failed to complete the course. Active in the nationalist cause, he belonged to a faction favouring direct action and the use of Western methods to destroy the power of the Dutch. He was also a member of the Bandung chapter of Sarekat Islām (Islamic Association) and a founder of the Socialist Indische Partij (Indies Party). An article he wrote during this period, If I Were a Netherlander, published in the Indische Partij De Express, led to his exile to the Netherlands between 1913 and 1918.</p><p style=\"text-align: justify;\">In the Netherlands he became converted to the idea of using Indonesian cultural traditions to cope with the problems posed by Dutch colonial rule. He felt that education was the best means to strengthen Indonesians, and he was deeply influenced by the progressive theories of the Italian educational reformer Maria Montessori and by the Indian poet and philosopher Rabindranath Tagore.</p><p style=\"text-align: justify;\">The first Taman Siswa schools were established in Java in July 1922. Instruction, carried on informally, emphasized traditional skills and values of Javanese life, particularly music and dance. Western subjects were taught, too, in order to help students cope with the demands of modern life. Overcoming initial official hostility, the Taman Siswa schools had spread throughout the archipelago and were by the late 1930s subsidized by the Dutch colonial government. Based on traditional Javanese concepts, the Taman Siswa schools appealed primarily to those segments of Indonesian society termed abangan, in which the Islamic faith is less deeply entrenched. Dewantoro continued his leadership of Taman Siswa after the war and upon his death was acclaimed a national hero.</p><p style=\"text-align: justify;\">Identify where is TRUE or FALSE about Taman Siswa?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:11:\"<p>True</p>\";i:2;s:12:\"<p>False</p>\";}i:1;a:3:{i:0;s:112:\"<p><span style=\"font-weight: 700; text-align: center;\">Ki Hajar Dewantoro was founder of Taman Siswa</span></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:117:\"<p><span style=\"font-weight: 700; text-align: center;\">The 1st Taman Siswa was established in 1922</span></p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:127:\"<p><span style=\"font-weight: 700; text-align: center;\">In 1930 the Dutch colonial government subsidized Taman Siswa</span></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:113:\"<p><span style=\"font-weight: 700; text-align: center;\">Western subject was prohibited for Taman Siswa</span></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1764221385, 1764221546, 1, '', 1, 0, 0, '721293ca-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
