INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30977, 841, 0, 1, 17, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Venice is a city in northern Italy. It has been known as the Queen of the Adriatic, City of Bridges, and The City of Light. The city stretches across 117 small islands in the marshy Venetian Lagoon along the Adriatic Sea in northeast Italy. Venice is world famous for its canals. It is built on an archipelago of 117 islands formed by about 150 canals in a shallow lagoon. The islands on which the city is built are connected by about 400 bridges. In the old center, the canals serve the function of roads, and every form of transport is on water or on foot. You can ride gondola there. It is the classical Venetian boat which nowadays is mostly used for tourists, or weddings, funerals, or other ceremonies. Now, most Venetians travel by moto rise waterbuses which ply regular routes along the major canals and between the city islands. The city has many private boats. The only gondolas still in common use by Venetians are the Traghetti, foot passenger ferries crossing the Grand Canal at certain points without bridges.</p><p style=\"text-align: justify;\">What transport crosses the Grand Canal for foot passengers at certain points without bridges....</p>', 'Gondolas.', 'Traghetti.', 'Waterbuses.', 'Lagoon.', 'Ship', NULL, NULL, NULL, NULL, NULL, 'b', 1764223433, 1764223550, 1, '', 1, 0, 0, '7212abf6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30978, 841, 0, 1, 18, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Venice is a city in northern Italy. It has been known as the Queen of the Adriatic, City of Bridges, and The City of Light. The city stretches across 117 small islands in the marshy Venetian Lagoon along the Adriatic Sea in northeast Italy. Venice is world famous for its canals. It is built on an archipelago of 117 islands formed by about 150 canals in a shallow lagoon. The islands on which the city is built are connected by about 400 bridges. In the old center, the canals serve the function of roads, and every form of transport is on water or on foot. You can ride gondola there. It is the classical Venetian boat which nowadays is mostly used for tourists, or weddings, funerals, or other ceremonies. Now, most Venetians travel by moto rise waterbuses which ply regular routes along the major canals and between the city islands. The city has many private boats. The only gondolas still in common use by Venetians are the Traghetti, foot passenger ferries crossing the Grand Canal at certain points without bridges.</p><p style=\"text-align: justify;\">From the text we can say that Venice belongs to a city of ….</p>', 'Water', 'Ceremonies', 'Buses', 'Funerals', 'Gondola', NULL, NULL, NULL, NULL, NULL, 'a', 1764223554, 1764223764, 1, '', 1, 0, 0, '7212ada8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (30979, 841, 0, 1, 19, NULL, NULL, NULL, '<p>Dear Sally, </p><p>Last holiday, my friends and I visited Ponorogo in East Java. Ponorogo is a small city, but it is very natural and beautiful. We spent the night at a villa in Jetis. On the first day, we visited Prigi southern beach. We watched the amazing views of the sea and the white waves. We grilled fish and had \"Nasi Pecel\" for lunch. On the second day, we visited \"Dongko\" mountain resort. There were a lot of plants, especially clove trees. We camped there for a night. I love Ponorogo because the people are very friendly and the prices are cheap. I\'ll bring some pictures for you. </p><p>Love, Anna </p><p>What kind of text is it?</p></body></html>', 'Narrative', 'Procedure', 'Recount', 'Descriptive', 'Explanation', NULL, NULL, NULL, NULL, NULL, 'c', 1764223770, 1765348751, 1, '', 1, 0, 0, '7212af55-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
