INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31031, 868, 0, 2, 1, NULL, NULL, NULL, '<p data-start=\"322\" data-end=\"654\">Pada suatu percobaan, enzim katalase diuji pada berbagai kondisi. Diketahui bahwa gelembung O₂ yang dihasilkan menurun drastis ketika pH &lt; 5 dan pH &gt; 9. Namun, aktivitas meningkat kembali ketika pH dikembalikan ke 7. Kesimpulan yang tepat adalah ...</p>', 'a:5:{s:1:\"a\";s:213:\"<p data-start=\"488\" data-end=\"758\">Enzim mengalami denaturasi permanen pada pH ekstrem<br></p><p>\r\n</p><p data-start=\"760\" data-end=\"786\"><strong data-start=\"760\" data-end=\"786\">Jawaban benar: B, C, D</strong></p>\";s:1:\"b\";s:62:\"<p>Perubahan pH dapat mengubah bentuk sisi aktif enzim<br></p>\";s:1:\"c\";s:59:\"<p>Aktivitas enzim maksimum terjadi pada pH optimum<br></p>\";s:1:\"d\";s:62:\"<p>Penurunan aktivitas enzim dapat bersifat reversibel<br></p>\";s:1:\"e\";s:49:\"<p>Enzim tidak dipengaruhi oleh pH lingkungan</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"b\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;N;}', 1764238925, 1764239216, 1, '', 1, 0, 0, '7212f4e7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31032, 868, 0, 2, 2, NULL, NULL, NULL, 'Dalam suatu percobaan, enzim katalase diuji pada berbagai kondisi pH. Aktivitas enzim menurun drastis pada pH &lt; 4 dan pH &gt; 10. Dari hasil tersebut, simpulan yang tepat adalah …', 'a:5:{s:1:\"a\";s:57:\"<p>Struktur tersier enzim berubah pada pH ekstrem<br></p>\";s:1:\"b\";s:51:\"<p>Katalase hanya bekerja pada suasana basa<br></p>\";s:1:\"c\";s:71:\"<p>Kecepatan reaksi meningkat jika semakin jauh dari pH optimum<br></p>\";s:1:\"d\";s:70:\"<p>Denaturasi dapat terjadi pada pH terlalu rendah atau tinggi<br></p>\";s:1:\"e\";s:51:\"<p>Enzim bersifat spesifik terhadap pH tertentu</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"d\";i:2;s:1:\"e\";i:3;N;}', 1764238927, 1764288293, 1, '', 1, 0, 0, '7212f68c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31033, 868, 0, 2, 3, NULL, NULL, NULL, 'Sebuah sel mengalami kekurangan ATP. Kondisi ini paling mungkin terjadi karena …', 'a:5:{s:1:\"a\";s:46:\"<p>Rantai transport elektron terhambat<br></p>\";s:1:\"b\";s:38:\"<p>NADH tidak dapat dioksidasi<br></p>\";s:1:\"c\";s:367:\"<p>Aktivitas enzim ATP sintase meningkat<br data-start=\"1087\" data-end=\"1090\"><span data-start=\"1090\" data-end=\"1096\" style=\"font-weight: bolder;\">D.</span>&nbsp;Glikolisis berhenti total<br data-start=\"1122\" data-end=\"1125\"><span data-start=\"1125\" data-end=\"1131\" style=\"font-weight: bolder;\">E.</span>&nbsp;Proton tidak dapat membentuk gradien dalam mitokondria</p>\";s:1:\"d\";s:36:\"<p>Glikolisis berhenti total<br></p>\";s:1:\"e\";s:61:\"<p>Proton tidak dapat membentuk gradien dalam mitokondria</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"e\";i:3;N;}', 1764238928, 1764288443, 1, '', 1, 0, 0, '7212f82a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31034, 868, 0, 2, 4, NULL, NULL, NULL, '<p data-start=\"1375\" data-end=\"1446\">Perhatikan beberapa pernyataan berikut terkait mekanisme kerja enzim:</p>\r\n<ol data-start=\"1447\" data-end=\"1655\">\r\n<li data-start=\"1447\" data-end=\"1484\">\r\n<p data-start=\"1450\" data-end=\"1484\">Enzim menurunkan energi aktivasi</p>\r\n</li>\r\n<li data-start=\"1485\" data-end=\"1526\">\r\n<p data-start=\"1488\" data-end=\"1526\">Enzim menggeser kesetimbangan reaksi</p>\r\n</li>\r\n<li data-start=\"1527\" data-end=\"1577\">\r\n<p data-start=\"1530\" data-end=\"1577\">Enzim bekerja melalui kompleks enzim-substrat</p>\r\n</li>\r\n<li data-start=\"1578\" data-end=\"1623\">\r\n<p data-start=\"1581\" data-end=\"1623\">Enzim dapat bekerja berulang tanpa habis</p>\r\n</li>\r\n<li data-start=\"1624\" data-end=\"1655\">\r\n<p data-start=\"1627\" data-end=\"1655\">Enzim meningkatkan ΔG reaksi</p>\r\n</li>\r\n</ol>\r\n<p data-start=\"1657\" data-end=\"1761\">Pernyataan benar adalah …</p>', 'a:5:{s:1:\"a\";s:18:\"<p>1, 3, 4<br></p>\";s:1:\"b\";s:15:\"<p>2, 4<br></p>\";s:1:\"c\";s:18:\"<p>1, 2, 5<br></p>\";s:1:\"d\";s:18:\"<p>1, 3, 5<br></p>\";s:1:\"e\";s:11:\"<p>3, 4</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"e\";i:2;N;}', 1764238930, 1764288862, 1, '', 1, 0, 0, '7212fa95-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31035, 868, 0, 2, 5, NULL, NULL, NULL, 'Pada proses respirasi sel, ketika oksigen tidak tersedia, beberapa perubahan terjadi:', 'a:5:{s:1:\"a\";s:32:\"<p>Siklus Krebs berhenti<br></p>\";s:1:\"b\";s:39:\"<p>Glikolisis tetap berlangsung<br></p>\";s:1:\"c\";s:62:\"<p>NADH diregenerasi menjadi NAD⁺ melalui fermentasi<br></p>\";s:1:\"d\";s:42:\"<p>Jumlah ATP meningkat signifikan<br></p>\";s:1:\"e\";s:53:\"<p>Rantai transport elektron terus bekerja normal</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"c\";i:3;N;}', 1764238931, 1764288999, 1, '', 1, 0, 0, '7212ff24-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31036, 848, 0, 3, 3, NULL, NULL, NULL, '<p>Berdasarkan ciri dan syarat penyusunan, poster manakah yang telah memenuhi syarat-syarat penyusunan poster yang baik? Berilah tanda centang (√) pada tabel berikut</p><p><img src=\"https://usp.ikasmedia.my.id/uploads/bank_soal/file_20251127183228.jpg\" style=\"width: 50%;\">\r\n\r\n</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:15:\"<p>Poster 1</p>\";i:2;s:8:\"Poster 2\";}i:1;a:3:{i:0;s:141:\"<p>Desain grafis poster harus memuat komposisi yang seimbang antara huruf dan gambar di atas media kertas atau kain yang berukuran besar</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:79:\"<p>Poster pada umumnya dibuat dengan perpaduan warna yang kuat dan kontras</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:86:\"<p>Poster menggunakan bahasa yang singkat, jelas, tidak rancu agar mudah dipahami</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:98:\"<p>Poster menggunakan kalimat ajakan baik berupa ajakan secara langsung maupun tidak langsung</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:84:\"<p>Pesan yang ingin disampaikan sebaiknya disertai dengan gambar yang mendukung</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:86:\"<p>Poster bisa dibaca sambil lalu dan menarik minat khalayak umum atau Masyarakat</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1764239368, 1764904961, 1, '', 1, 0, 0, '72130052-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31038, 848, 0, 3, 4, NULL, NULL, NULL, '<p style=\"text-align: center; \"><b>Bacalah teks argumentasi dan identifikasilah kalimat fakta dan kalimat opini\r\n</b></p><p style=\"text-align: center; \"><b>\r\nKetahanan Pangan pada Masa Pandemi Covid-19</b></p><p style=\"text-align: center; \"><span style=\"font-size: 0.875rem;\">Pandemi Covid-19&nbsp;</span><span style=\"font-size: 0.875rem; text-align: left;\">mengajarkan kepada kita bahwa ketahanan pangan nasional sangat penting ketika negara lain tidak dapat melepas cadangan pangan ke pasar global. Organisasi Pangan dan Pertanian Perserikatan Bangsa-Bangsa (FAO) memperingatkan kepada negara-negara anggotanya untuk menjaga ketersediaan pangan nasional di negara masing-masing.\r\n</span></p><p style=\"text-align: center; \"><span style=\"font-size: 0.875rem; text-align: left;\">\r\nWalaupun stok pangan secara global cukup, karena pandemi Covid-19 mengharuskan karantina total atau sebagian wilayah, setiap negara anggota harus bisa mencukupi kebutuhan pangan rakyatnya. Situas ini memberi tekanan berat pada rantai pasok pangan karena perdagangan global menjadi terbatas karena banyak negara menutup pelabuhan dan perbatasan.\r\n</span></p><p style=\"text-align: center; \"><span style=\"font-size: 0.875rem; text-align: left;\">\r\nDi dalam negeri sendiri, produksi pangan melibatkan jejaring petani, pasokan sarana produksi, pengolahan pascapanen, logistik dan distribusi, hingga perdagangan eceran. Jika salah satu mata rantai terhambat, pasokan pangan juga akan terganggu. </span></p><p style=\"text-align: center; \"><span style=\"font-size: 0.875rem; text-align: left;\">\r\n\r\nKombinasi kedua alasan tersebut di atas menjadi hal yang tidak mudah bagi negara-negara yang mendapatkan pangan dari pasar internasional. Situasi itu menjadi lebih berat bagi negara yang menginpor pangan dalam jumlah besar karena penduduk yang banyak seperti Indonesia.\r\n</span></p><p style=\"text-align: center; \"><span style=\"font-size: 0.875rem; text-align: left;\">\r\nOleh karena itu, pandemi Covid-19 makin menegaskan tentang pemahaman kita bahwa ketahanan pangan harus kita perluas jika Indonesia ingin memiliki kedaulatan pangan khususnya dan kedaulatan negara pada umumnya.</span></p><p style=\"text-align: center; \"><span style=\"text-align: left;\">Berilah tanda (√) pada table di bawah ini untuk menjelaskan perbedaan antara kalimat fakta dan kalimat opini</span><span style=\"font-size: 0.875rem; text-align: left;\"></span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:9:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:13:\"Kalimat Fakta\";i:2;s:13:\"Kalimat Opini\";}i:1;a:3:{i:0;s:82:\"<p>Dapat dibuktikan kebenarannya karena berasal dari kejadian yang sebenarnya</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:100:\"<p>Bersifat subjektif dan biasanya disertai dengan pendapat, saran, dan uraian yang menjelaskan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:100:\"<p>Berisi data-data yang bersifat kuantitatif (berupa angka) dan kualitatif (berupa pernyataan)</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:119:\"<p>Berisi pendapat tentang peristiwa yang terjadi yang bisa berupa pikiran atau pendapat seseorang maupun kelompok</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:5;a:3:{i:0;s:108:\"<p>Biasanya ditandai dengan penggunaan kata- kata bisa jadi, sepertinya, mungkin, seharusnya, sebaiknya</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:81:\"<p>Mempunyai data yang akurat, baik waktu, tanggal, tempat, dan peristiwanya</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:7;a:3:{i:0;s:69:\"<p>Kenyatakan kejadian yang sedang atau telah dan pernah terjadi</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:8;a:3:{i:0;s:83:\"<p>Menunjukkan peristiwa yang belum pasti terjadi atau terjadi dikemudian hari</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1764239765, 1764904975, 1, '', 1, 0, 0, '721301d3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31039, 821, 0, 3, 2, NULL, NULL, NULL, '<p>Keterampilan permainan adalah kemampuan untuk melakukan gerakan dasar dalam olahraga dengan teknik yang efektif dan efisien untuk menghasilkan hasil yang maksimal. Keterampilan permainan juga dapat diartikan sebagai kompetisi yang mengharuskan peserta untuk menerapkan keterampilan tertentu, dan pemenangnya ditentukan berdasarkan metode kualitatif. </p><p>Dari kesimpulan di atas tentukan manakah yang termasuk dalam ketrampilan sepak bola dan bola voli. </p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"1\",\"jawaban\":[[\"PERNYATAAN\",\"<p>Sepak Bola<\\/p><\\/body><\\/html>\",\"<p>Bola voli<\\/p><\\/body><\\/html>\"],[\"<p>ketrampilan mengumpan<\\/p><\\/body><\\/html>\",\"1\",\"1\"],[\"<p>ketrampilan servis<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>ketrampilan menggiring<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>ketrampilan passing<\\/p><\\/body><\\/html>\",\"1\",\"1\"],[\"<p>ketrampilan menyundul<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>ketrampilan smesh<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>ketrampilan mengontrol<\\/p><\\/body><\\/html>\",\"1\",\"1\"],[\"<p>Keterampilan menendang<\\/p><\\/body><\\/html>\",\"1\",\"0\"]]}', 1764240021, 1764992293, 1, '', 1, 0, 0, '72130359-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31040, 848, 0, 3, 5, NULL, NULL, NULL, '<p style=\"text-align: center; \"><b>Ketahanan Pangan pada Masa Pandemi Covid-19\r\n</b></p><p>\r\nPandemi Covid-19 mengajarkan kepada kita bahwa ketahanan pangan nasional sangat penting ketika negara lain tidak dapat melepas cadangan pangan ke pasar global. Organisasi Pangan dan Pertanian Perserikatan Bangsa-Bangsa (FAO) memperingatkan kepada negara-negara anggotanya untuk menjaga ketersediaan pangan nasional di negara masing-masing.\r\n</p><p>\r\nWalaupun stok pangan secara global cukup, karena pandemi Covid-19 mengharuskan karantina total atau sebagian wilayah, setiap negara anggota harus bisa mencukupi kebutuhan pangan rakyatnya. Situas ini memberi tekanan berat pada rantai pasok pangan karena perdagangan global menjadi terbatas karena banyak negara menutup pelabuhan dan perbatasan.\r\n</p><p>\r\nDi dalam negeri sendiri, produksi pangan melibatkan jejaring petani, pasokan sarana produksi, pengolahan pascapanen, logistik dan distribusi, hingga perdagangan eceran. Jika salah satu mata rantai terhambat, pasokan pangan juga akan terganggu. </p><p>\r\n\r\nKombinasi kedua alasan tersebut di atas menjadi hal yang tidak mudah bagi negara-negara yang mendapatkan pangan dari pasar internasional. Situasi itu menjadi lebih berat bagi negara yang menginpor pangan dalam jumlah besar karena penduduk yang banyak seperti Indonesia.\r\n</p><p>\r\nOleh karena itu, pandemi Covid-19 makin menegaskan tentang pemahaman kita bahwa ketahanan pangan harus kita perluas jika Indonesia ingin memiliki kedaulatan pangan khususnya dan kedaulatan negara pada umumnya</p><p><b>Setelah kalian membaca teks di atas, jawablah dengan benar atau salah soal – soal di bawah ini.</b></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:125:\"<p>Berikut adalah kalimat fakta: Pengenalan sagu dan ketela sebagai pengganti beras kepada masyarakat mendesak dilakukan</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:155:\"<p>Berikut adalah kalimat opini: Ketela mulai ditanam di daerah Kalimantan secara besar-besaran tahun 2017 dan panen raya akan terjadi awal tahun 2019</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:141:\"<p>Berikut adalah kalimat fakta: Pemerintah memberikan bantuan berupa pupuk kepada petani yang mau menanam tanaman selain padi tahun ini</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:171:\"<p>Berikut adalah kalimat opini: Masyarakat perkotaan terutama di Jakarta, Surabaya, dan Makasar mulai menyukai umbi-umbian sebagai makanan alternatif pengganti beras</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:121:\"<p>Berikut adalah kalimat fakta: Untuk memenuhi kebutuhan dalam negeri pemerintah melakukan impor beras dari Vietnam</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1764240530, 1764904997, 1, '', 1, 0, 0, '721304be-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31041, 821, 0, 3, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\">Permainan adalah aktivitas yang dilakukan secara sungguh-sungguh, tetapi dalam melakukan permainan bukan merupakan suatu kesungguhan. Dalam hal ini aktivitas jasmani adalah gerak manusia itu sendiri yang berarti salah satu tanda adanya permainan adalah adanya gerak Atau aktivitas jasmani. Filosofi permainan di defnisikan sebagai hasil dari sejarah manusia yang turun temurun tentunya tanpa membedakan ras, kultur, sosial, agama. Permainan ditinjau melalui ilmu filsafat, ada dua analisa. Yang pertama melalui tubuh filsafat yakni dalam permainan ini semua orang terlibat mulai dari usia anak-anak sampai pada orang usia lanjut. </div><div style=\"text-align: justify;\">Dari penjelasan di atas pasangkan pengertian permainan bola voli sesuai dengan pengertiannya.</div></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p> pukulan bola keras di atas&nbsp; net<\\/p><\\/body><\\/html>\",\"memukul bola dengan dua tangan yang disatukan dan di ayun dari bawah ke atas\",\"<p>pukulan permulaan dengan satu tangan oleh pemain<\\/p><\\/body><\\/html>\"],[\"<p>servis<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\"],[\"<p>passing<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\"],[\"<p>smesh<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\"]]}', 1764241108, 1764992335, 1, '', 1, 0, 0, '72130619-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31042, 821, 0, 3, 4, NULL, NULL, NULL, 'Cocokkanlah ukuran lebar dan panjang lapangan berikut ini pada kolom sebelah kiri dengan pengertiannya di kolom sebelah kanan', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"2,24 meter\",\"90\\u2013120 meter\",\"<p>7,32 meter<\\/p><\\/body><\\/html>\",\"<p>2,44 meter<\\/p><\\/body><\\/html>\",\"<p>2,43 meter<\\/p><\\/body><\\/html>\",\"<p>9 meter<\\/p><\\/body><\\/html>\",\"<p>18 meter<\\/p><\\/body><\\/html>\",\"<p>&nbsp;45&ndash;90 meter<\\/p><\\/body><\\/html>\"],[\"<p>Panjang lapangan bola voli<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Lebar lapangan bola voli<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Tinggi net bola voli putra<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Tinggi net bola voli putri<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\",\"0\",\"0\",\"0\"],[\"<div>Panjang lapangan sepak bola<\\/div><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\",\"0\",\"0\",\"0\"],[\"<div>Lebar lapangan sepak bola<\\/div><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<div>Diameter lingkaran tengah lapangan sepak bola<\\/div><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Panjang garis gawang (gawang sepak bola)<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\",\"0\",\"0\",\"0\"]]}', 1764242195, 1764992348, 1, '', 1, 0, 0, '72130773-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31043, 821, 0, 3, 5, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Keterampilan menyundul bola atau heading adalah teknik dasar sepak bola untuk menguasai bola di udara dengan menggunakan kepala. Teknik ini dapat dilakukan untuk mencetak gol, mengoper, atau mematahkan serangan lawan. </span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Dari pernyataan diatas tentukan pasangan masing-masing ketrampilan antara ketrampilan menyundul bola dan mengontrol bola.</span></div></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"Menggiring bola menggunakan kaki sambil bergerak\",\"Mengumpan bola jarak dekat dengan kaki bagian dalam\",\"<p>Menghentikan bola untuk dikuasai<\\/p><\\/body><\\/html>\",\"<p>Menyundul bola untuk mengumpan atau mencetak gol<\\/p><\\/body><\\/html>\",\"<p>Menendang bola keras ke arah gawang<\\/p><\\/body><\\/html>\"],[\"<p>Passing pendek<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Dribbling<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Shooting<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Heading<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Controlling<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"]]}', 1764243471, 1764992362, 1, '', 1, 0, 0, '721308c5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
