INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31080, 848, 0, 5, 3, NULL, NULL, NULL, '<p><b>Lengkapilah paragraf di bawah ini dengan konjungsi yang tepat</b></p><p>Indonesia terkenal sebagai salah satu penghasil kopi paling lezat di dunia. Salah satu jenis kopi yang terkenal adalah kopi luak. ..... diperlukan proses yang panjang untuk menghasilkan kopi luak yang nikmat. Biji kopi yang benar-benar segar dan berwarna merah yang akan digunakan. …...., biji kopi dipilih dengan memisahkan biji kopi yang segar dan busuk dengan cara direndam. Biji kopi yang baik akan tenggelam, ........ yang busuk akan mengapung, ......... biji kopi tersebut diberikan kepada musang atau luak jenis binturong dan bulan (luak pemakan kopi). Dalam proses ini, luak mempunyai peran yang sangat penting karena indra penciumannya hanya akan memilih biji kopi sempurna.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Disamping itu, selanjutnya, sedangkan, lalu</div>', 1764248497, 1764905100, 1, '', 1, 0, 0, '72133907-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
