INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31116, 848, 0, 2, 1, NULL, NULL, NULL, '..... ingin membantu para petani, pemerintah menyarankan ..... membeli produk-produk pangan lokal. Produk pangan lokal yang dihasilkan oleh para petani ternyata memiliki kandungan gizi yang tidak kalah dibandingkan dengan produk pangan hasil impor. ...... mulailah dengan mengonsumsi produk makanan lokal yang dihidangkan di meja makan keluarga-keluarga di Indonesia.\r\n<p></p><p>\r\nKonjungsi yang tepat untuk melengkapi paragraf di atas adalah ….</p>', 'a:5:{s:1:\"a\";s:11:\"<p>Jika</p>\";s:1:\"b\";s:12:\"<p>Untuk</p>\";s:1:\"c\";s:21:\"<p>Di samping itu</p>\";s:1:\"d\";s:18:\"<p>Selanjutnya</p>\";s:1:\"e\";s:13:\"<p>Jadi </p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"e\";i:3;N;}', 1764250366, 1764904583, 1, '', 1, 0, 0, '721375da-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
