INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31118, 870, 0, 2, 5, NULL, NULL, NULL, 'Berikut merupakan ciri dari negara-negara di Benua Eropa. Manakah pernyataan yang benar?', '{\"a\":\"<p>Mayoritas negara menggunakan sistem pemerintahan monarki absolut<\\/p><\\/body><\\/html>\",\"b\":\"<p>Pertumbuhan industri maju dan teknologi tinggi<\\/p><\\/body><\\/html>\",\"c\":\"<p>&nbsp;Wilayahnya memiliki empat musim<\\/p><\\/body><\\/html>\",\"d\":\"<p>Tingkat urbanisasi relatif tinggi&nbsp;<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"b\",\"c\",\"d\",null]', 1764250540, 1765017869, 1, '', 1, 0, 0, '72137952-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31119, 848, 0, 2, 2, NULL, NULL, NULL, 'Konjungsi yang tepat untuk melengkapi paragraf di bawah ini adalah :\r\nIndonesia terkenal sebagai salah satu penghasil kopi paling lezat di dunia. Salah satu jenis kopi yang terkenal adalah kopi luwak. ........ diperlukan proses yang panjang untuk menghasilkan kopi luwak yang nikmat. Biji kopi yang benar-benar segar dan berwarna merah yang akan digunakan. ….............. biji kopi dipilih dengan memisahkan biji kopi yang segar dan busuk dengan cara direndam. Biji kopi yang baik akan tenggelam, ........... yang busuk akan mengapung, .............biji kopi tersebut diberikan kepada musang atau luak jenis binturong dan bulan (luak pemakan kopi). Dalam proses ini, luwak mempunyai peran yang sangat penting karena indra penciumannya hanya akan memilih biji kopi sempurna.', 'a:6:{s:1:\"a\";s:10:\"<p>Dan</p>\";s:1:\"b\";s:20:\"<p>Disamping itu</p>\";s:1:\"c\";s:10:\"<p>Dan</p>\";s:1:\"d\";s:18:\"<p>Selanjutnya</p>\";s:1:\"e\";s:18:\"<p> Sedangkan</p>\";s:1:\"f\";s:11:\"<p>lalu</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"b\";i:1;s:1:\"d\";i:2;s:1:\"e\";i:3;s:1:\"f\";i:4;N;}', 1764250553, 1764904817, 1, '', 1, 0, 0, '72137b22-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
