INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31154, 842, 0, 3, 1, NULL, NULL, NULL, '<p>Secara teoritik menurut&nbsp; Brent G. Wilson dalam bukunya Evaluation Of Learning In Art Education; Apresiasi seni memiliki tiga domain, yakni: perasaan (feeling), dalam konteks ini terkait dengan perasaan keindahan, penilaian (valuing) terkait dengan nilai seni, dan empati (emphatizing), terkait dengan sikap hormat kepada dunia seni rupa, termasuk kepada profesi seniman, yaitu perupa (pelukis, pematung, penggrafis, penggeramik, pendesain, pengriya, dan lain-lain).</p><p>Tentukanlah pernyataan yang tepat dan benar</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:189:\"<p><span style=\"font-weight: 700; text-align: center;\">Apresiasi seni rupa adalah aktivitas mengindra karya seni rupa dengan cara merasakan, menikmati, menghayati dan menghargai</span></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:171:\"<p><span style=\"font-weight: 700; text-align: center;\">Brent G. Wilson adalah seorang penulis buku yang berjudul Evaluation of Learning in Art Education</span></p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:133:\"<p><span style=\"font-weight: 700; text-align: center;\">Seni rupa memiliki 3 unsur yaitu: feeling, valuing dan emphatizing</span></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:127:\"<p><span style=\"font-weight: 700; text-align: center;\">Pematung dan penggrafis bukan termasuk dalam profesi seniman</span></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1764252207, 1764252340, 1, '', 1, 0, 0, '7213afc2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
