INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31171, 870, 0, 3, 3, NULL, NULL, NULL, 'Proses pembelajaran nilai dan budaya suatu masyarakat sejak kecil disebut ?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>Proses pembelajaran nilai dan budaya suatu masyarakat sejak kecil<\\/p><\\/body><\\/html>\",\"<p>Wujud kebudayaan berupa benda fisik seperti rumah adat dan pakaian tradisional<\\/p><\\/body><\\/html>\",\"<p>Aturan yang mengikat perilaku masyarakat, misalnya larangan mencuri<\\/p><\\/body><\\/html>\",\"<p>Penyesuaian dua kebudayaan yang bercampur tanpa menghilangkan unsur asli<\\/p><\\/body><\\/html>\",\"<p>Proses penyebaran unsur budaya dari suatu tempat ke tempat lain<\\/p><\\/body><\\/html>\"],[\"<p>Asimilasi<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Akulturasi<\\/p><p><\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Sosialisasi<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Lembaga sosial<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Nilai sosial<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"]]}', 1764254304, 1765003519, 1, '', 1, 0, 0, '7213c792-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
