INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31178, 870, 0, 3, 5, NULL, NULL, NULL, 'Mengapa pendekatan lingkungan penting dalam perencanaan tata ruang?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>Pendekatan Keruangan<\\/p><\\/body><\\/html>\",\"<p>Pendekatan Kompleks Wilayah<\\/p><\\/body><\\/html>\",\"<p>Pendekatan Ekologi<\\/p><\\/body><\\/html>\",\"<p>Pendekatan Spasial<\\/p><\\/body><\\/html>\",\"<p>Pendekatan Lingkungan<\\/p><\\/body><\\/html>\"],[\"<p>Mengkaji penyebab banjir dengan melihat curah hujan, kondisi tanah, dan bentuk wilayah.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Menjelaskan interaksi antara penduduk kota dan desa, seperti arus komuter setiap hari.<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Meneliti persebaran industri di suatu daerah melalui peta tematik.<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Mengkaji mengapa suhu udara di pegunungan lebih rendah dibandingkan dataran rendah.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Menganalisis hubungan antara jumlah penduduk, ketersediaan lahan, dan permukiman.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"]]}', 1764255335, 1765003569, 1, '', 1, 0, 0, '7213cfc4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31179, 845, 0, 1, 20, NULL, NULL, NULL, '<p>Kelompok sosial adalah kumpulan individu yang memiliki hubungan dan saling berinteraksi. Pernyataan berikut ini yang mencerminkan kelompok sosial adalah...</p>', 'Kelompok sosial adalah kumpulan individu yang memiliki hubungan dan saling berinteraksi', '&nbsp;Jutaan penonton menyaksikan acara musik yang disiarkan oleh sebuah stasiun televisi.', 'Pengunjung di Pasar A<span style=\"font-size: 0.875rem;\">meningkat drastis menjelang perayaan hari besar keagamaan.</span>', 'Pengurus OSIS SMA B sedang menyusun rencana kerja untuk bulan depan.', '&nbsp;Ani dan Ina sedang menunggu giliran membeli tiket bus.', NULL, NULL, NULL, NULL, NULL, 'e', 1764255453, 1764255607, 1, '', 1, 0, 0, '7213d15f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31180, 845, 0, 1, 21, NULL, NULL, NULL, '<p>Perhatikan pernyataan-pernyataan berikut</p><p>\r\n(1) Adanya kesadaran sebagai bagian dari kelompok yang bersangkutan.</p><p>\r\n(2) Pihak yang berinteraksi didefinisikan oleh orang lain sebagai anggota kelompok.</p><p>\r\n(3) Ada suatu faktor pengikat yang dimiliki bersama oleh anggota-anggota kelompok.\r\n</p><p>(4) Memiliki pola interaksi yang dapat dipahami oleh semua orang.\r\n</p><p>(5) Memiliki struktur, kaidah, dan pola perilaku yang sama.</p><p>\r\nPernyataan yang merupakan persyaratan suatu kelompok sosial ditunjukkan oleh nomor....</p>', '(1), (2), dan (3)', '(1), (3), dan (4)', '(1), (3), dan (5)', '(2), (3), dan (4)', '(3), (4), dan (5)', NULL, NULL, NULL, NULL, NULL, 'a', 1764255670, 1764255897, 1, '', 1, 0, 0, '7213d23c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
