INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31186, 845, 0, 1, 26, NULL, NULL, NULL, '<p>Ferdinand Tönnies mengklasifikasikan kelompok di dalam masyarakat menjadi dua, yaitu gemeinschaft dan gesellschaft. Contoh kelompok sosial yang termasuk gemeinschaft adalah keluarga. Alasannya adalah karena...</p>', 'adanya dorongan untuk hidup bersama dalam sebuah keluarga', 'hubungan antaranggota keluarga didasari oleh kesamaan perilaku', 'anggota keluarga memiliki hubungan yang kuat, bersifat alamiah, dan kekal', 'mengacu pada ikatan-ikatan kekerabatan yang memiliki kepentingan yang sama', '&nbsp;keluarga didasari oleh adanya ikatan perkawinan yang memiliki tujuan yang sama', NULL, NULL, NULL, NULL, NULL, 'c', 1764256546, 1764256727, 1, '', 1, 0, 0, '7213d8a6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
