INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31189, 859, 0, 5, 1, NULL, NULL, NULL, 'Jelaskan perbedaan antara sumber sejarah primer dan sumber sejarah sekunder dan berikan contohnya masing-masing', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>Sumber sejarah primer: data utama yang diperoleh langsung dari subyek dan objek penelitian. contoh: foto, vidio, Undang-undang, catatan kedinasan.</p><p>Sumber sejarah sekunder: data pendukung yang ditulis atau dibuat setelah kejadian selesai. contoh: Laporan penelitian yang relevan, surat menyurat dan surat kabar yang tidak sezaman dengan peristiwa.</p>', 1764257243, 1764258106, 1, '', 1, 0, 0, '7213dbcc-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31190, 845, 0, 1, 29, NULL, NULL, NULL, '<p>Perhatikan pernyataan-pernyataan berikut:</p><ol><li>Ada perbedaan paham di antara anggota kelompok</li><li>Ketidakseimbangan kekuatan di dalam kelompok</li><li>Perubahan lingkungan sekitar kelompok</li><li>Adanya perbedaan kepentingan</li><li>Pergantian anggota kelompok\r\n</li></ol><p>\r\nBerdasarkan pernyataan-pernyataan tersebut, faktor internal yang memengaruhi perkembangan atau perubahan kelompok sosial ditunjukkan oleh pernyataan nomor...</p>', '1, 2, dan 3', '1, 2, dan 4', '2, 3, dan 4', '2, 4, dan 5', '3, 4, dan 5', NULL, NULL, NULL, NULL, NULL, 'b', 1764257592, 1764724929, 1, '', 1, 0, 0, '7213dcbb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
