INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31192, 859, 0, 5, 2, NULL, NULL, NULL, 'Jelaskan perbedaan antara masa lalu, masa kini dan masa depan dalam konteks sejarah.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><div><div><div><div style=\"text-align: justify; \">Masa lalu adalah peristiwa yang sudah terjadi.</div><div style=\"text-align: justify;\"> Masa kini adalah realitas yang sedang kita jalani, yang merupakan hasil dari masa lalu.</div><div style=\"text-align: justify;\"> Masa depan adalah peristiwa yang akan terjadi, yang dipengaruhi oleh apa yang kita lakukan dimasa kini.</div></div></div></div></div></div>', 1764258137, 1764308981, 1, '', 1, 0, 0, '7213df0e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31194, 859, 0, 2, 1, NULL, NULL, NULL, 'Berikut ini&nbsp; manfaat mempelajari ilmu sejarah adalah....', 'a:5:{s:1:\"a\";s:65:\"<p>Memahami perilaku manusia dan nilai-nilai suatu masyarakat</p>\";s:1:\"b\";s:67:\"<p>Mengenal siapa diri kita sebagai pribadi dan secara kolektif</p>\";s:1:\"c\";s:51:\"<p>Memprediksi kejadian masa depan dengan tepat</p>\";s:1:\"d\";s:64:\"<p>Menumbuh kembangkan kecakapan berpikir kritis dan kreatif</p>\";s:1:\"e\";s:45:\"<p>Memprediksi diri setiap pelaku sejarah</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"d\";i:3;N;}', 1764258157, 1764394626, 1, '', 1, 0, 0, '7213e03a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31195, 845, 0, 3, 1, NULL, NULL, NULL, '<p>1.Tuhan menciptakan manusia terdiri atas laki-laki dan perempuan yang bersuku- suku dan berbangsa- bangsa untuk saling mengenal. Oleh karena itu manusia sejak awal memiliki perbedaan- perbedaan.</p><p>Salah satu perbedaan antara individu dengan individu adalah cara berinteraksi, misalnya interkasi dalam kelompok sosial. kelompok sosial terbentuk apabila di antara individu yang satu dengan individu yang lain bertemu. Pertemuan antara individu yang menghasilkan kelompok sosial haruslah berupa proses interaksi, seperti adanya kontak, komunikasi, kerja sama, akomodasi, asimilasi dan akulturasi untuk mencapai tujuan bersama, bahkan mungkin mengadakan persaingan, pertikaian, dan konflik.</p><p>Kelompok sosial merupakan bagian dari msyarakat, kelompok sosial terbentuk karena manusia yang satu dengan manusia yang lainnya saling membutuhkan, sehingga terbentuklah kelompok sosial.Faktor -faktor pembentuk kelompok sosial, yaitu ...</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"<p>BENAR<\\/p><\\/body><\\/html>\",\"<p>SALAH<\\/p><\\/body><\\/html>\"],[\"<p>kedekatan&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>kerinduan<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>kesamaan<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>&nbsp;keinginan<\\/p><\\/body><\\/html>\",\"0\",\"1\"]]}', 1764258661, 1764992552, 1, '', 1, 0, 0, '7213e203-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31196, 845, 0, 3, 2, NULL, NULL, NULL, '<p>Partikularisme kelompok</p><p>Bangsa indonesia salah satu bangsa yang dikenal dengan masyarakat multikultur. Hal ini terlihat ketika bangsa kita ini dengan berbagai macam kebudayaan dan keaneka ragaman suku dari sabang sampai merauke. Hal laim yang menandakan bahwa bangsa ini memang sudah di gariskan sebagai bangsa yang ragam budaya dalah dari salah satu sila yang berbunyi persatuan Indonesia.</p><p>Salah satu yang menunjuka bangsa indonesia sebagai bangsa yang beragam adalah dengan adanya pembagian kelompok yang ada di masyarakat, yaitu masyarakat desa dan kota. Pada dasarnya masyarakat desa dan kota merupakan sekumpulan masyarakat ynag tinggal pada wilayah yang berbeda yang dicirikan dengan pembangunan, sistem sosial, dan kultur yang berbeda.</p><p>Eksklusivisme kelompokSelain ada pembagian kelompok sosial dimasyarakat yaitu adanya masyarakat kota yang memiliki ciri partikular, masyarakat desa juga merupakan salah satu ciri dari karakteristik kelompok sosial yang memiliki ciri eksklusiv.</p><p> Eksklusivisme kelompok adalah sebuah sikap atau keadaan adanya kecenderungan untuk memisahkan diri dari masyarakat.salah satu contoh masyarakat ekslusif adalah masyarakat desa.Yang termasuk ciri - ciri yang menonjol pada masyarakat kota, yaitu ...</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"<p>BENAR<\\/p><\\/body><\\/html>\",\"<p>SALAH<\\/p><\\/body><\\/html>\"],[\"<p>Cenderung memikirkan keduniaan&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>Hubungan kekeluargaan dilakukan secara musyawara<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p><br><\\/p><p>Pembagian kerja diantara warga - warga kota harus lebih tegas dan mempunyai batas - batas yang nyata<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>bermata pencaharian di bidang agraris, baik pertanian, perkebunan, perikanan dan peternakan&nbsp;<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>Pada umumnya dapat mengurus diri sendiri tanpa harus bergantung pada orang lain&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"]]}', 1764259035, 1764992586, 1, '', 1, 0, 0, '7213e39c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
