INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31260, 815, 0, 5, 1, NULL, NULL, NULL, 'Mengapa penggunaan bahan baku terbarukan dianggap sebagai salah satu kunci penting dalam kimia hijau? Berikan dua contoh bahan terbarukan yang dapat digunakan dalam industri!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p data-start=\"2234\" data-end=\"2563\">Bahan baku terbarukan berasal dari sumber yang dapat diperbaharui dalam waktu relatif singkat sehingga penggunaannya tidak menghabiskan sumber daya alam. Ini penting dalam kimia hijau karena mengurangi ketergantungan pada bahan fosil, mengurangi dampak lingkungan, serta mendukung keberlanjutan.<br data-start=\"2529\" data-end=\"2532\">Contoh bahan baku terbarukan:</p><ol data-start=\"2564\" data-end=\"2706\"><li data-start=\"2564\" data-end=\"2636\"><p data-start=\"2567\" data-end=\"2636\">Bioetanol dari tebu atau jagung (sebagai bahan bakar atau pelarut).</p></li><li data-start=\"2637\" data-end=\"2706\"><p data-start=\"2640\" data-end=\"2706\">Minyak nabati (sebagai bahan pembuatan bioplastik atau biodiesel).</p></li></ol></div></body></html>', 1764292069, 1765350400, 1, '', 1, 0, 0, '72143431-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
