INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31263, 868, 0, 5, 1, NULL, NULL, NULL, 'Mengapa enzim disebut biokatalis? Jelaskan bagaimana enzim dapat mempercepat reaksi kimia tanpa berubah secara permanen!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Enzim disebut biokatalis karena mempercepat reaksi kimia dalam tubuh makhluk hidup. Enzim menurunkan energi aktivasi, sehingga reaksi berlangsung lebih cepat. Enzim tidak berubah secara permanen karena setelah berikatan dengan substrat dan menghasilkan produk, enzim kembali ke bentuk semula dan dapat digunakan berulang kali.', 1764292300, 1764292357, 1, '', 1, 0, 0, '72143814-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31264, 868, 0, 5, 2, NULL, NULL, NULL, 'Suatu enzim bekerja optimal pada suhu 40°C. Jelaskan apa yang terjadi terhadap struktur enzim jika suhu lingkungan mencapai 70°C dan bagaimana hal itu memengaruhi aktivitas reaksi!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Pada suhu 70°C, struktur tersier enzim mengalami perubahan atau rusak (denaturasi). Denaturasi menyebabkan bentuk sisi aktif berubah sehingga substrat tidak dapat lagi berikatan. Akibatnya, aktivitas enzim menurun drastis atau bahkan berhenti sama sekali.', 1764292302, 1764292403, 1, '', 1, 0, 0, '721438fb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31265, 868, 0, 5, 3, NULL, NULL, NULL, 'Dalam percobaan laboratorium, semakin tinggi konsentrasi substrat, kecepatan reaksi awalnya meningkat tetapi kemudian stabil. Jelaskan penyebab fenomena ini dari sudut pandang mekanisme kerja enzim!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Peningkatan konsentrasi substrat meningkatkan peluang bertemunya enzim dengan substrat, sehingga reaksi meningkat. Namun ketika semua enzim yang tersedia sudah terikat substrat, reaksi mencapai titik jenuh (saturasi). Pada kondisi ini, penambahan substrat tidak lagi meningkatkan kecepatan reaksi karena jumlah enzim pembawa reaksi terbatas.', 1764292305, 1764292441, 1, '', 1, 0, 0, '72143a64-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31266, 868, 0, 5, 4, NULL, NULL, NULL, 'Jelaskan perbedaan peran enzim dalam reaksi katabolisme dan anabolisme, serta berikan masing-masing satu contoh!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<li data-start=\"1869\" data-end=\"2032\"><p data-start=\"1871\" data-end=\"2032\"><strong data-start=\"1871\" data-end=\"1887\">Katabolisme:</strong> Enzim membantu memecah molekul besar menjadi molekul lebih kecil sambil melepaskan energi. Contoh: enzim amilase memecah pati menjadi maltosa.</p>\r\n</li>\r\n<li data-start=\"2033\" data-end=\"2207\">\r\n<p data-start=\"2035\" data-end=\"2207\"><strong data-start=\"2035\" data-end=\"2050\">Anabolisme:</strong> Enzim membantu menyusun molekul kecil menjadi molekul besar dengan membutuhkan energi. Contoh: enzim sintetase membantu pembentukan protein dari asam amino.</p></li>', 1764292307, 1764292486, 1, '', 1, 0, 0, '72143bfb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31267, 868, 0, 5, 5, NULL, NULL, NULL, 'Sebuah enzim tidak dapat bekerja ketika pH lingkungan berubah terlalu asam atau terlalu basa. Jelaskan mengapa perubahan pH dapat menghambat kerja enzim!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Perubahan pH memengaruhi ikatan kimia yang menjaga struktur enzim, terutama struktur tersier. Jika pH terlalu ekstrem, sisi aktif enzim berubah bentuk sehingga substrat tidak cocok lagi. Hal ini menurunkan kemampuan enzim membentuk kompleks enzim-substrat, sehingga aktivitas reaksi menurun atau berhenti.', 1764292309, 1764292526, 1, '', 1, 0, 0, '72143cf3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31268, 815, 0, 5, 2, NULL, NULL, NULL, 'Jelaskan apa yang dimaksud dengan kimia hijau dan mengapa konsep ini penting diterapkan dalam kehidupan sehari-hari.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Kimia hijau adalah pendekatan dalam ilmu kimia yang bertujuan untuk merancang proses dan produk kimia yang ramah lingkungan, aman, dan efisien. Konsep ini penting karena dapat mengurangi limbah berbahaya, meminimalkan penggunaan bahan kimia toksik, menghemat energi, dan mendukung keberlanjutan lingkungan. Dengan menerapkan kimia hijau, dampak negatif aktivitas manusia terhadap bumi dapat dikurangi.</div></body></html>', 1764292395, 1765350411, 1, '', 1, 0, 0, '72143dc8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
