INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31277, 815, 0, 5, 4, NULL, NULL, NULL, 'Suatu percobaan pembentukan air dilakukan dengan mereaksikan 4 g hidrogen dengan 32 g oksigen dan menghasilkan 36 g air. Jelaskan bagaimana data tersebut membuktikan hukum kekekalan massa.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Massa total reaktan = massa H&#8322; + massa O&#8322; = 4 g + 32 g = 36 g<br data-start=\"889\" data-end=\"892\">Massa produk = massa H&#8322;O = 36 g<br data-start=\"923\" data-end=\"926\">Karena massa sebelum dan sesudah reaksi sama, berarti reaksi tersebut mematuhi hukum kekekalan massa.Tidak ada massa yang hilang atau bertambah.</div></body></html>', 1764293112, 1765350433, 1, '', 1, 0, 0, '721449f1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31278, 871, 0, 1, 3, NULL, NULL, NULL, '<p>“Long ago, the sun and the moon lived together in the sky. One day, they had a disagreement, and the sun moved away.</p><p>”What type of narrative text is this?</p>', '&nbsp;Fable', 'Legend', 'Myth', 'Fairy Tale', 'Dongeng', NULL, NULL, NULL, NULL, NULL, 'c', 1764293146, 1764293214, 1, '', 1, 0, 0, '72144b73-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31279, 871, 0, 1, 4, NULL, NULL, NULL, '<p>Once upon a time, there was a clever fox who wanted to eat grapes from a high vine. He tried many times but failed. Finally, he said, “Those grapes are sour,” and walked away.</p><p>Which part of the narrative text introduces the characters and setting?</p>', 'Orientation', 'Complication', 'Resolution', 'Re-orientation', 'Content', NULL, NULL, NULL, NULL, NULL, 'a', 1764293226, 1764293324, 1, '', 1, 0, 0, '72144c6d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31280, 871, 0, 1, 5, NULL, NULL, NULL, '<p>Once upon a time, there was a clever fox who wanted to eat grapes from a high vine. He tried many times but failed. Finally, he said, “Those grapes are sour,” and walked away.&nbsp;</p><p><span style=\"font-size: 0.875rem;\">What is the moral of the story?</span></p>', 'Always tell the truth', 'It is easy to give up', 'Don’t despise what you can’t get', 'Hard work is useless', 'He tried many times', NULL, NULL, NULL, NULL, NULL, 'c', 1764293331, 1764293417, 1, '', 1, 0, 0, '72144d49-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31281, 815, 0, 5, 5, NULL, NULL, NULL, 'Hitunglah Mr dari senyawa berikut: Ca(OH)₂. berilah langkah perhitungannya.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><p data-start=\"733\" data-end=\"794\">Ar Ca = 40, O = 16, H = 1<br data-start=\"758\" data-end=\"761\">Rumus Ca(OH)&#8322; berarti terdapat:</p><ul data-start=\"795\" data-end=\"834\"><li data-start=\"795\" data-end=\"808\"><p data-start=\"797\" data-end=\"808\">1 atom Ca</p></li><li data-start=\"809\" data-end=\"821\"><p data-start=\"811\" data-end=\"821\">2 atom O</p></li><li data-start=\"822\" data-end=\"834\"><p data-start=\"824\" data-end=\"834\">2 atom H</p></li></ul><p data-start=\"836\" data-end=\"903\">Mr = (1 &times; 40) + (2 &times; 16) + (2 &times; 1)<br data-start=\"870\" data-end=\"873\">Mr = 40 + 32 + 2<br data-start=\"889\" data-end=\"892\"><b>Mr = 74</b></p></div></body></html>', 1764293390, 1765350443, 1, '', 1, 0, 0, '72144e22-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31282, 871, 0, 1, 6, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">What makes Cristiano Ronaldo different from other players in scoring goals?</span></div>', 'He can score goals using his head', 'He can use both of his legs efficiently to make goals', 'He has good stamina', 'He has strong determination', 'He doesn\'t have good energy', NULL, NULL, NULL, NULL, NULL, 'b', 1764293424, 1764293616, 1, '', 1, 0, 0, '72144fa4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31283, 871, 0, 1, 7, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>The word “opponent” in paragraph 2 has the closest meaning to …</p>', 'teammate', 'rival&nbsp;', 'friend', 'fans', 'supporter', NULL, NULL, NULL, NULL, NULL, 'b', 1764293426, 1764293706, 1, '', 1, 0, 0, '721450a3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31284, 872, 0, 1, 1, NULL, NULL, NULL, 'Seorang siswa ingin membuat program sederhana untuk mengelompokkan data nilai siswa menjadi tiga kategori: tinggi, sedang, dan rendah. Untuk menyusun langkah sistematis, siswa tersebut perlu menggunakan tahapan berpikir komputasional. Langkah manakah yang paling tepat dilakukan terlebih dahulu?', 'Menulis kode program menggunakan bahasa pemrograman<br>', 'Menguji program dengan berbagai contoh data<br>', 'Menguraikan masalah menjadi bagian-bagian kecil<br>', 'Mendokumentasikan program agar mudah dibaca<br>', '&nbsp;Memperbaiki bug pada algoritma', NULL, NULL, NULL, NULL, NULL, 'c', 1764293484, 1764293803, 1, '', 1, 0, 0, '7214523b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
