INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31289, 815, 0, 3, 1, NULL, NULL, NULL, '<p>Sebuah pabrik farmasi &ldquo;<b>BioCure</b>&rdquo; sedang berupaya memperbaiki proses produksinya agar lebih ramah lingkungan. Selama ini proses sintesis obat yang mereka lakukan menghasilkan limbah organik yang cukup banyak, menggunakan pelarut berbahaya, serta mengonsumsi energi dalam jumlah besar. Manajer produksi ingin menerapkan prinsip-prinsip kimia hijau untuk meningkatkan efisiensi proses sekaligus mengurangi dampak lingkungan.</p><p>Tim riset diberikan beberapa alternatif perbaikan:</p><ol><li>Mengganti pelarut organik berbahaya dengan pelarut berbasis air.</li><li>Menggunakan katalis enzim untuk menurunkan energi aktivasi reaksi.</li><li>Mengubah proses sintesis agar menghasilkan limbah minimal.</li><li>Menggunakan bahan baku yang dapat diperbarui.</li><li>Mendesain produk samping yang dapat terdegradasi secara hayati.</li></ol><p>Tim manajer meminta Anda menganalisis alternatif tersebut dengan menjodohkan tiap tindakan dengan prinsip kimia hijau yang sesuai.</p><p><b>Petunjuk: </b>Jodohkan tindakan pabrik (Kolom A) dengan prinsip kimia hijau yang paling tepat (Kolom B).</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"Penggunaan bahan baku terbarukan.<br>\",\"Pencegahan limbah (waste prevention).\",\"Pelarut dan bahan tambahan yang lebih aman.\",\"<p>Katalisis (catalysis).<\\/p><\\/body><\\/html>\",\"<p>Desain bahan kimia yang dapat terdegradasi.<\\/p><\\/body><\\/html>\"],[\"<p>Mengganti pelarut organik berbahaya dengan pelarut berbasis air.<br><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Menggunakan katalis enzim untuk menurunkan energi aktivasi reaksi.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Mendesain proses sintesis yang menghasilkan limbah minimal.<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<div>Menggunakan bahan baku dari tanaman yang dapat diperbarui.<\\/div><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Menggunakan katalis enzim untuk menurunkan energi aktivasi reaksi.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"]]}', 1764293775, 1765350263, 1, '', 1, 0, 0, '72145731-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31290, 871, 0, 1, 8, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>“He also challenged himself by playing along with older players.” The word ‘he’ refers to...</p>', 'Cristiano Ronaldo', 'Football players', 'Older players', 'Basketball players', 'The writer', NULL, NULL, NULL, NULL, NULL, 'a', 1764293805, 1764293889, 1, '', 1, 0, 0, '721458c8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31291, 871, 0, 1, 9, NULL, NULL, NULL, '<p style=\"text-align: justify;\">The game continued scoreless up until the half time interval, but as the second half of the game started, the intensity of the game increased. In the meanwhile, I was getting nervous in the stadium because my team wasn’t exactly playing up to our expectations. In fact, my team was lucky to survive a few scoring chances from the opponent team. Then, suddenly, the ball was passed to the main “striker” of my favorite team from nowhere, and a goal was scored by my team, leaving the supporters of my team completely ecstatic and crazy with the feeling of a possible victory. And, in the end, we were indeed the victorious team.</p><p>What is the main idea of the text?&nbsp;</p>', 'The writer’s experience watching a football match', 'The writer’s favorite football team', 'The intensity of the football match&nbsp;', 'The writer’s feeling about the match', 'The writer\'s story about the match', NULL, NULL, NULL, NULL, NULL, 'a', 1764293809, 1764294069, 1, '', 1, 0, 0, '721459af-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31292, 871, 0, 1, 10, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>“He also challenged himself by playing along with older players.” The word ‘he’ refers to...</p>', 'Cristiano Ronaldo', 'Older players', 'Basketball players', 'Football players', 'The writer', NULL, NULL, NULL, NULL, NULL, 'a', 1764293899, 1764294281, 1, '', 1, 0, 0, '72145b7c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
