INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31313, 871, 0, 1, 12, NULL, NULL, NULL, '<p><span style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\">Dear Sally,</span><br style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\"><span style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\">Last holiday, my friends and I visited Ponorogo in East Java. Ponorogo is a small city, but it is very natural and beautiful. We spent the night at a villa in Jetis. On the first day, we visited Prigi southern beach. We watched the amazing views of the sea and the white waves. We grilled fish and had \"Nasi Pecel\" for lunch. On the second day, we visited \"Dongko\" mountain resort. There were a lot of plants, especially clove trees. We camped there for a night. I love Ponorogo because the people are very friendly and the prices are cheap.</span><br style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\"><span style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\">I\'ll bring some pictures for you.</span><br style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\"><span style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\">Love,</span><br style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\"><span style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\">Anna</span></p><p><span style=\"color: rgb(0, 0, 62); font-family: &quot;Open Sauce One&quot;, system-ui, -apple-system, BlinkMacSystemFont, Ubuntu, &quot;Segoe UI&quot;, Oxygen-Sans, &quot;Helvetica Neue&quot;, Arial, sans-serif; font-size: 15.001px;\">What kind of text is it?</span></p>', 'Narrative', 'Procedure', 'Recount', 'Descriptive', 'Explanation', NULL, NULL, NULL, NULL, NULL, 'c', 1764294412, 1764294545, 1, '', 1, 0, 0, '72146f48-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
