 lebih aman<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Efisiensi energi<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Penggunaan bahan baku terbarukan<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"]]}', 1764295500, 1765350325, 1, '', 1, 0, 0, '72147cf6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
