INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31347, 871, 0, 1, 23, NULL, NULL, NULL, '<p>Last holiday I went to Paris. I visited museums and sat in public gardens. A friendly waiter taught me a few words of French. Then, he lent me a book. I read a few lines, but I did not understand a word. Every day, I thought about postcards. My holidays passed quickly, but I did not send any cards to my friends. On the last day I made a big decision, I got up early and bought thirty-seven cards. I spent the whole day in my room, but I did not write a single card!&nbsp;</p><p> Whom did the writer meet in Paris?</p>', ' A man that take him to French', '<p>A man that gave him thirty-seven cards</p>', 'A man that lent him a book', 'A man that worked in museum', 'A man that give him a job.', NULL, NULL, NULL, NULL, NULL, 'c', 1764296654, 1764296889, 1, '', 1, 0, 0, '721494be-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
