INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31357, 819, 0, 3, 3, NULL, NULL, NULL, 'Manakah hal-hal berikut yang termasuk unsur-unsur biaya variabel?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"1\",\"jawaban\":[[\"PERNYATAAN\",\"<p>Benar<\\/p><\\/body><\\/html>\",\"<p>salah<\\/p><\\/body><\\/html>\"],[\"<p class=\\\"MsoListParagraphCxSpMiddle\\\" style=\\\"margin-left:90.0pt;mso-add-space:auto;text-indent:-18.0pt;mso-list:l1 level1 lfo2\\\"><span lang=\\\"EN-US\\\"><span style=\\\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \\\" times=\\\"\\\" new=\\\"\\\" roman=\\\"\\\">&nbsp;&nbsp;<\\/span><\\/span><!--[endif]--><span lang=\\\"EN-US\\\">Tanah<\\/span><\\/p><p><\\/p><p><\\/p><p class=\\\"MsoListParagraphCxSpMiddle\\\" style=\\\"margin-left:90.0pt;mso-add-space:auto;text-indent:-18.0pt;mso-list:l1 level1 lfo2\\\">&nbsp;<\\/p>\",\"0\",\"1\"],[\"<p class=\\\"MsoListParagraphCxSpFirst\\\" style=\\\"margin-left:72.0pt;mso-add-space:auto;text-indent:-18.0pt;mso-list:l0 level1 lfo1\\\">&nbsp;<span lang=\\\"EN-US\\\" style=\\\"text-indent: -18pt; font-size: 0.875rem;\\\"><span style=\\\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto