INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31363, 785, 0, 2, 4, NULL, NULL, NULL, '<p data-start=\"2056\" data-end=\"2096\"><b>(PILIHLAH JAWABAN LEBIH DARI SATU)</b></p><p data-start=\"2056\" data-end=\"2096\">Ciri khusus letak geografis Indonesia:</p>\r\n<ol data-start=\"2097\" data-end=\"2248\">\r\n<li data-start=\"2097\" data-end=\"2129\">\r\n<p data-start=\"2100\" data-end=\"2129\">Terletak di wilayah tropis.</p>\r\n</li>\r\n<li data-start=\"2130\" data-end=\"2172\">\r\n<p data-start=\"2133\" data-end=\"2172\">Diapit oleh Benua Asia dan Australia.</p>\r\n</li>\r\n<li data-start=\"2173\" data-end=\"2222\">\r\n<p data-start=\"2176\" data-end=\"2222\">Berada di antara Samudra Pasifik dan Hindia.</p>\r\n</li>\r\n<li data-start=\"2223\" data-end=\"2248\">\r\n<p data-start=\"2226\" data-end=\"2248\">Berada di kutub utara.</p></li></ol>', 'a:4:{s:1:\"a\";s:24:\"<p>1, 2, dan 3 benar</p>\";s:1:\"b\";s:20:\"<p>1 dan 4 benar</p>\";s:1:\"c\";s:20:\"<p>2 dan 3 benar</p>\";s:1:\"d\";s:29:\"<p>Semua pernyataan benar</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;N;}', 1764297751, 1764297859, 1, '', 1, 0, 0, '7214a75d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
