INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31380, 873, 0, 1, 7, NULL, NULL, NULL, '<p style=\"text-align: justify; \">A short time later, in their astonishment, smoke came out of that stone. Corious, Irimiami tried to sit on that stone. Ouch! It’s really hot! He shouted. Becoming more corious, the couple decided to test the stone’s head.How if we put this venison on the stone?said Irimiami. Let’s just try, dear, answered Isoray. Exquisite smells came from the burning meat. As it was ready they ate them up.what a delicious piece of meat or this meat is so delicious,Irimiami said happily. Unsatisfied what they found, they continued testing the stone. Let’s try to put these bamboo stems, said Isoray. Let’s try the grass and leaves, Irimiami added. How about that timber! Shouted Isoray. Day by day, they kept on testing the stone.\r\n</p><p style=\"text-align: justify; \">\r\nBased on the third paragraph of text above, there are the word “Verb” categories, expect....</p>', 'Put', 'Try', 'Ate', 'Meat', 'Kept', NULL, NULL, NULL, NULL, NULL, 'd', 1764298541, 1764902045, 1, '', 1, 0, 0, '7214b8ef-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31381, 871, 0, 5, 3, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>Why did Ronaldo train very hard?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Because he knew that a footballer requires good stamina&nbsp;', 1764298570, 1764298617, 1, '', 1, 0, 0, '7214bafd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
