INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31384, 871, 0, 5, 5, NULL, NULL, NULL, '<p>Descriptive Text of Historical Place</p><p style=\"text-align: justify;\">Bale Kambang is a small village in the Southern coast of East Java, seventy kilometers from Malang town and two hours’ drive from South. It is well known for its long beautiful white sandy beach as well as the similarity of its temple to the one of Tanah Lot in Bali. In Bale Kambang, there are three small rocky islands namely Ismaya Island, Wisanggeni Island, and Anoman Island, those names are taken from “wayang” figures (Java traditional puppets). These islands are surrounded by Indonesian Ocean which huge waves frighten most overseas cruisers.</p><p><span style=\"font-size: 0.875rem;\">What makes Bale Kambang famous?</span><span style=\"font-size: 0.875rem;\">Long beautiful beach</span><span style=\"font-size: 0.875rem;\">Long beautiful beach</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Long beautiful beach</div>', 1764298685, 1764298737, 1, '', 1, 0, 0, '7214bec1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
