INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31393, 871, 0, 4, 1, NULL, NULL, NULL, '<p>Descriptive text about place</p><p style=\"text-align: justify;\">Kediri is a name of a town. It is situated in a valley between the Kelud and Willis mountains and inhabited by about 1.3 million people. In the Centre of the town there is a large hill which is called the Dathok Mountain. Because of the topography of the region, Kediri is called a chilly town by the locals. There is a big river called Brantas cutting off the Centre of the town. Beside the temples, Kediri is also famous for its products like cigarettes and a special kind of tofu or bean curd. This highly nutritious food is delicacy of Kediri and has a distinctive taste. The cigarettes factory dominates the town economy and employs the majority of the women labor force. Kediri and the cigarettes factory are inseparable and it is considered the biggest cigarette factory in Indonesia. Most of the local people work in this factory. Those who do not work here are farmers or traders.&nbsp;</p><p>What does the above text tell about?&nbsp;</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'description of Kediri', 1764298788, 1764298806, 1, '', 1, 0, 0, '7214cad0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31394, 871, 0, 4, 2, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Cristiano Ronaldo has very strong determination. He used to train very hard since his childhood. He knew that a footballer requires good stamina because a football match requires a player to run at least 10 kilometers in a single match. Sometimes, he even trained himself continuously from morning until evening. He also challenged himself by playing along with older players. He becomes so skillful and confident that his opponents cannot figure out how to stop Ronaldo from making a goal. Normal football players will use their single leg of their dominant side body, i.e. players of right-handed or left-handed use their respective legs to score goals but Ronaldo can easily use both of his legs efficiently to make goals. In addition to that, he can use his head to score goals as well.<br></p><p>“He also challenged himself by playing along with older players.” The word ‘he’ refers to...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cristiano Ronaldo', 1764298810, 1764298840, 1, '', 1, 0, 0, '7214ccb7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
