INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31481, 871, 0, 2, 5, NULL, NULL, NULL, '<p>Personal recount text is one type of recount text in addition to factual, autobiographical, biographical, literary, and historical recount. It retells the writer\'s past experiences with the aim to either inform or to entertain the audience.&nbsp; It often consist of orientation, series of events, and reorientation</p><p>Type of recount text in addition...</p>', 'a:7:{s:1:\"a\";s:13:\"<p>person</p>\";s:1:\"b\";s:23:\"<p>autobiographical</p>\";s:1:\"c\";s:14:\"<p>factual</p>\";s:1:\"d\";s:12:\"<p>thing</p>\";s:1:\"e\";s:19:\"<p>biographical</p>\";s:1:\"f\";s:15:\"<p>literary</p>\";s:1:\"g\";s:25:\"<p>historical recount</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:6:{i:0;s:1:\"b\";i:1;s:1:\"c\";i:2;s:1:\"e\";i:3;s:1:\"f\";i:4;s:1:\"g\";i:5;N;}', 1764301413, 1764301685, 1, '', 1, 0, 0, '72154a30-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31482, 824, 0, 2, 1, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Servis dalam bola voli adalah Pukulan awal dari luar garis belakang lapangan untuk memulai reli atau memutar permainan. Servis juga berfungsi sebagai serangan pertama untuk mencetak poin dan mengatur ritme permainan. <b>Menurut Nuril Ahmadi (2007),</b> servis adalah pukulan bola yang dilakukan dari belakang garis akhir lapangan permainan hingga bola melampaui net ke daerah lawan. Tujuan utama servis tidak hanya untuk memulai permainan, tetapi juga sebagai upaya serangan awal dengan mengirimkan bola ke area lawan sedemikian rupa sehingga sulit dikembalikan. </span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Di bawah ini beberapa ketrampilan dalam bola voli, tentukan manakah yang termasuk dalam ketrampilan servis.</span></div></body></html>', '{\"a\":\"<p>Servis bawah<\\/p><\\/body><\\/html>\",\"b\":\"<p>servis atas<\\/p><\\/body><\\/html>\",\"c\":\"<p>servis menyamping<\\/p><\\/body><\\/html>\",\"d\":\"<p>servis melayang<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",null]', 1764301473, 1765002938, 1, '', 1, 0, 0, '72154c6f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31483, 824, 0, 2, 2, NULL, NULL, NULL, '<p>Passing dalam voli adalah teknik dasar untuk menerima dan mengontrol bola dari tim lawan, seperti dari servis atau serangan (smash), dengan tujuan mengirimkan bola ke rekan setim (biasanya tosser/setupper) agar dapat membangun serangan balik. Tujuan utama passing adalah untuk Menerima serangan lawan: Mengantisipasi bola yang datang dengan kecepatan tinggi atau arah yang sulit. Membangun serangan: Memberikan bola yang akurat kepada tosser untuk diumpan ke spiker.</p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206174447.jpg\" style=\"width: 25%;\"><br></p><p>Sesuai penjelasan di atas tentukan dua ketrampilan passing.</p></body></html>', '{\"a\":\"<p>passing menengah<\\/p><\\/body><\\/html>\",\"b\":\"<p>passing bawah<\\/p><\\/body><\\/html>\",\"c\":\"<p>passing atas<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"b\",\"c\",null]', 1764301474, 1765014298, 1, '', 1, 0, 0, '72154de2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31484, 824, 0, 2, 3, NULL, NULL, NULL, '<p>Keterampilan melempar (passing) dan menangkap (menangkap) bola basket adalah dua teknik dasar yang memungkinkan pemain untuk mengoper bola kepada rekan satu tim dan menerima umpan. Melempar adalah tindakan melontarkan bola secara akurat ke arah pemain lain, sementara menangkap adalah gerakan menerima bola dengan tangan secara terkendali. Keterampilan kedua ini krusial untuk membangun tim serangan yang efektif dan menguasai permainan.</p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206174601.jpg\" style=\"width: 25%;\"><br></p><p>Dari pengertian di atas ketrampilan melempar dan menangkap bola dapat dilakukan dengan empat cara ...</p></body></html>', '{\"a\":\"<p><span style=\\\"text-align: justify;\\\">melempar dan menangkap bola di depan dada<\\/span><\\/p><\\/body><\\/html>\",\"b\":\"<p><span style=\\\"text-align: justify;\\\">melempar dan menangkap bola memantul<\\/span><\\/p><\\/body><\\/html>\",\"c\":\"<p><span style=\\\"text-align: justify;\\\">melempar dan menangkap bola di atas kepala<\\/span><\\/p><\\/body><\\/html>\",\"d\":\"<p><span style=\\\"text-align: justify;\\\">melempar dan menangkap bola baseball pass<\\/span><\\/p><\\/body><\\/html>\",\"e\":\"<p><span style=\\\"text-align: justify;\\\">melempar dan menangkap bola rata dada<\\/span><\\/p><\\/body><\\/html>\",\"f\":\"<p><span style=\\\"text-align: justify;\\\">melempar dan menangkap bola menyamping<\\/span><\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"c\",\"d\",null]', 1764301477, 1765014366, 1, '', 1, 0, 0, '72155050-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31485, 824, 0, 2, 4, NULL, NULL, NULL, '<p>Keterampilan menembak bola keranjang adalah gerakan melempar bola ke keranjang lawan untuk mencetak poin. Teknik ini melibatkan koordinasi kompleks antara mata, tangan, dan seluruh tubuh untuk menghasilkan tembakan yang akurat, termasuk mempertimbangkan keseimbangan, posisi tubuh, dan momentum. Ketrampilan menembak (shooting) dapat dilakukan dengan tiga cara.</p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206174720.jpg\" style=\"width: 25%;\"><br></p></body></html>', '{\"a\":\"<p><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">Ketrampilan&nbsp;<\\/span><i style=\\\"font-size: 0.875rem; text-align: justify;\\\">shooting <\\/i><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">dengan sikap berdiri<\\/span><\\/p><\\/body><\\/html>\",\"b\":\"<p><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">Ketrampilan&nbsp;<\\/span><i style=\\\"font-size: 0.875rem; text-align: justify;\\\">shooting&nbsp;<\\/i><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">dengan melompat<\\/span><\\/p><\\/body><\\/html>\",\"c\":\"<p><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">Ketrampilan&nbsp;<\\/span><i style=\\\"font-size: 0.875rem; text-align: justify;\\\">shooting&nbsp;<\\/i><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">dengan kaitan<\\/span><\\/p><\\/body><\\/html>\",\"d\":\"<p><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">Ketrampilan&nbsp;<\\/span><i style=\\\"font-size: 0.875rem; text-align: justify;\\\">shooting&nbsp;<\\/i><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">dengan melayang<\\/span><\\/p><\\/body><\\/html>\",\"e\":\"<p><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">Ketrampilan&nbsp;<\\/span><i style=\\\"font-size: 0.875rem; text-align: justify;\\\">shooting&nbsp;<\\/i><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">dengan bagian kiri<\\/span><\\/p><\\/body><\\/html>\",\"f\":\"<p><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">Ketrampilan&nbsp;<\\/span><i style=\\\"font-size: 0.875rem; text-align: justify;\\\">shooting&nbsp;<\\/i><span style=\\\"font-size: 0.875rem; text-align: justify;\\\">dengan bagian kanan<\\/span><\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"c\",\"d\",null]', 1764301478, 1765014460, 1, '', 1, 0, 0, '7215529d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31486, 824, 0, 2, 5, NULL, NULL, NULL, '<p>Keterampilan passing dalam sepak bola adalah kemampuan dasar untuk mengoper bola dari satu pemain ke pemain lain menggunakan teknik tertentu dengan tujuan untuk mempertahankan penguasaan bola dan membangun serangan. Passing yang baik sangat krusial untuk menciptakan peluang, membuka ruang, dan mengoordinasikan tim agar dapat mencetak gol atau bertahan secara efektif.</p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206174823.jpg\" style=\"width: 25%;\"><br></p><p>Dari pengertian di atas passing di dapat dilakukan dengan tiga cara.</p></body></html>', '{\"a\":\"<p>Passing menggunakan kaki bagian dalam<\\/p><\\/body><\\/html>\",\"b\":\"<p>Passing menggunakan punggung kaki<\\/p><\\/body><\\/html>\",\"c\":\"<p>Passing menggunakan kaki bagian luar<\\/p><\\/body><\\/html>\",\"d\":\"<p>Passing menggunakan kaki bagian tengah<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"c\",null]', 1764301485, 1765014508, 1, '', 1, 0, 0, '7215545f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
