INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31491, 826, 0, 1, 10, NULL, NULL, NULL, 'Kisah Doni mengajarkan bahwa perubahan hidup terjadi melalui .…&nbsp;', 'paksaan orang lain', 'pengalaman yang membuat malu', 'teguran penuh kasih', 'pujian berlebihan', 'tekanan dari lingkungan', NULL, NULL, NULL, NULL, NULL, 'c', 1764301916, 1764302066, 1, '', 1, 0, 0, '72155a70-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31492, 815, 0, 3, 5, NULL, NULL, NULL, '<p>Massa molekul relatif (Mr) adalah jumlah massa atom relatif (Ar) dari seluruh atom penyusun suatu molekul. Kemampuan menghitung Mr sangat penting karena menjadi dasar dalam stoikiometri, kimia larutan, dan perhitungan kuantitatif lainnya. Siswa  mampu menganalisis perbedaan Mr antar-senyawa, memahami pengaruh Ar unsur dan  factor yang membuat suatu Mr lebih besar atau lebih kecil.</p><p>Cocokkan pernyataan pada Kolom A dengan konsep pada Kolom B yang paling tepat.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<li data-start=\\\"1258\\\" data-end=\\\"1287\\\"><p data-start=\\\"1261\\\" data-end=\\\"1287\\\">Perbedaan Ar antar unsur dapat memberikan pengaruh besar terhadap nilai Mr suatu molekul.<br><\\/p><\\/li><\\/body><\\/html>\",\"<p>Mr suatu molekul dihitung dengan menjumlahkan seluruh Ar atom sesuai jumlah atomnya.<\\/p><\\/body><\\/html>\",\"<p>Penambahan satu atom tertentu, terutama yang berat, dapat meningkatkan Mr secara signifikan.<\\/p><\\/body><\\/html>\",\"<p>Penggunaan Ar dari tabel periodik menjadi dasar utama perhitungan Mr dalam berbagai senyawa.<\\/p><\\/body><\\/html>\",\"<p>Kontribusi atom dengan Ar besar dapat menaikkan total Mr secara dominan dibanding unsur yang ringan.<\\/p><\\/body><\\/html>\"],[\"<li data-start=\\\"894\\\" data-end=\\\"1048\\\"><p data-start=\\\"897\\\" data-end=\\\"1048\\\">Seorang siswa menghitung Mr kalsium hidroksida Ca(OH)&#8322; dengan cara menambahkan Ar Ca, O, dan H sesuai jumlah atomnya, sehingga ia memperoleh Mr = 74.<\\/p><\\/li><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Siswa membandingkan Mr H&#8322;O (18) dengan Mr H&#8322;S (34) dan menyimpulkan bahwa perubahan atom pusat (dari O ke S) menyebabkan perbedaan Mr yang cukup besar.<\\/p><p><\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Saat menghitung Mr gliserol C&#8323;H&#8328;O&#8323;, siswa menemukan bahwa keberadaan tiga atom oksigen memberi kontribusi besar pada total Mr.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Dua senyawa, CO&#8322; dan CO, dibandingkan oleh siswa. Ia menemukan bahwa meskipun berasal dari unsur yang sama, penambahan satu atom O membuat Mr CO&#8322; jauh lebih besar.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Siswa menggunakan data Ar dari tabel periodik untuk menghitung Mr aluminium sulfat Al&#8322;(SO&#8324;)&#8323;, kemudian menjumlahkan seluruh Ar atom sesuai jumlahnya untuk mendapat hasil akhir.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"]]}', 1764302067, 1765350374, 1, '', 1, 0, 0, '72155b9b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
