INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31496, 842, 0, 5, 1, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Pelaksanaan aktivitas kreasi seni lukis adalah kegiatan merealisasikan konsep seni sebagai ekspresi. Konsep yang mendasar sumber inspirasi seni dipetik dari kehidupan psikologi pelaku kreatif. jenis&nbsp; seni ini lebih bersifat subjektif, namun sangat penting dalam membentuk keseimbangan antara kehidupan rohani dan jasmani seseorang.</p><p>Proses kreatif berekspresi ini antara lain, memerlukan persiapan: kanvas ukuran 60 x 60 cm, palet, cat minyak atau cat acrylic,kuas, cucian kuas, kain lap dan perlengkapan lain yang dipandang perlu.</p><p>Pengertian dari berekspresi adalah...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Salah satu kebutuhan hidup manusia. realitas internal kehidupan spritual siswa membutuhkan penyaluran agar dapat mencapai keseimbangan kehidupan rohaniah yang sehat.', 1764302249, 1764302284, 1, '', 1, 0, 0, '72156068-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:48', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31497, 826, 0, 1, 13, NULL, NULL, NULL, 'Inti Ulangan 6:4–9 tentang keluarga adalah .…', 'anak harus patuh buta', 'orang tua wajib bekerja keras', 'keluarga dipanggil mengajarkan firman setiap hari', 'keluarga tidak boleh berdiskusi', 'pendidikan hanya dilakukan di gereja', NULL, NULL, NULL, NULL, NULL, 'c', 1764302266, 1764304841, 1, '', 1, 0, 0, '72156238-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31498, 842, 0, 5, 2, NULL, NULL, NULL, '<p>Karya seni rupa tiga dimensi merupakan karya seni yang memiliki ukuran panjang, lebar dan tinggi, sehingga karya dapat dilihat dari segala arah. Simbol merupakan makna yang terkandung dalam karya seni rupa baik dalam wujudnya obyeknya maupun unsur-unsur rupanya.</p><p>Dalam pengklasifikasian seni rupa dapat dibuat berdasarkan...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>1. Jenis</p><p>2. Tema</p><p>3. Fungsi</p><p>4. Nilai estetis</p>', 1764302290, 1764302333, 1, '', 1, 0, 0, '72156315-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31499, 842, 0, 5, 3, NULL, NULL, NULL, '<p>Pengertian analisis dalam konteks apresiasi adalah pengkajian yang cermat terhadap karya seni rupa untuk mengetahui keberadaan yang sebenarnya. penelaah secara mendalam dilakukan dengan cara menguraikan masalah pokok dengan bagian-bagian karya seni, termasuk hubungan antar bagian dengan keseluruhan, sehingga kita memperoleh kesimpulan yang tepat ketika mengkaji karya seni rupa.</p><p>Sebutkan komponen pengamatan dalam menganalisis...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>1.Konsep</p><p>2. Unsur</p><p>3. Prinsip</p><p>4. Bahan</p><p>5. Teknik</p>', 1764302337, 1764302380, 1, '', 1, 0, 0, '721563ed-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31500, 842, 0, 5, 4, NULL, NULL, NULL, '<p>Secara teoritik menurut Brent G. Wilson dalam bukunya Evaluation Of Learning In Art Education; Apresiasi seni memiliki tiga domain, yakni: perasaan (feeling), dalam konteks ini terkait dengan perasaan keindahan, penilaian (valuing) terkait dengan nilai seni, dan empati (emphatizing), terkait dengan sikap hormat kepada dunia seni rupa, termasuk kepada profesi seniman, yaitu perupa (pelukis, pematung, penggrafis, penggeramik, pendesain, pengriya, dan lain-lain).</p><p>Seni memiliki tiga domain yakni...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>1. Perasaan(feeling)</div><div>2. Keindahan, penilaian (valuing)</div><div>3. Empati (emphatizing)</div>', 1764302387, 1764302428, 1, '', 1, 0, 0, '721564c5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31501, 847, 0, 2, 4, NULL, NULL, NULL, '<p class=\"MsoListParagraph\" style=\"margin-left:72.0pt;mso-add-space:auto;\r\ntext-indent:36.0pt\"><b><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\ncolor:#1E293B;mso-fareast-language:EN-ID\">Liburan Kuli Bangunan</span></b></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Assalamu’alaikum warrahmatullahi wabarakatuh.\r\nPerkenalkan, saya Didi. Di sini ada kuli bangunan? Wah, berarti saya\r\nsatu-satunya ya di sini. Ngomong-ngomong soal liburan, buat kebanyakan orang,\r\nliburan itu obat stres, tapi buat saya malah bikin stres. Datang liburan\r\norang-orang sibuk nyiapin rencana mau liburan ke mana. Saya malah sibuk nyari\r\nalasan.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Anak saya minta liburan, “Pak, ingin ke Dufan.”<br>\r\n“Nak, Jakarta banjir.”<br>\r\n“Ya udah Pak, ke Tangkuban Perahu.”<br>\r\n“Nak, perahunya bocor.”<br>\r\n“Ah bilang aja, Bapak gak punya uang.”<br>\r\n“Cerdas!”<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Anak saya itu memang jarang liburan. Saya bawa ke\r\ntempat kerja saja, menurut dia itu tamasya. Dari pagi sampai sore, dia anteng\r\nnyusun lego, pakai batu bata. Kalau orang lain nyusun lego, anakanak, ya jadi\r\nrobot, anak saya jadi pos ronda.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Pulang ke rumah ditanya sama istri saya, “Gimana Nak,\r\nseru main sama Bapak?”<br>\r\n“Mantap, Mah! Pokoknya udah gede aku mau jadi kuli bangunan.”<br>\r\n“Hey, masa perempuan jadi kuli banguan..”<br>\r\n“Gak apa-apa, Mah, emansipasi!”<br>\r\nYa, anak saya itu memang jarang liburan, jadi dia itu norak. Kemarin saja saya\r\nbawa ajak mandi bola, dia bawa handuk.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Istri saya langsung ngomong, “Nak, mandi bola gak usah\r\nbawa handuk, Kan udah disediain.”<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Tapi bukan cuma anak saya, saya juga jarang liburan.\r\nSatu-satunya liburan saya ya di acara ini. Buat saya kompetisi ini liburan.\r\nGimana enggak coba? Saya dapat pergi ke Jakarta, tidur di hotel, kasurnya\r\nempuk, kalau saya tidur langsung terbayang hal indah. Gak kaya di rumah. Saya\r\nketika tidur langsung terbayang cicilan. Tapi, gara-gara itu saya sering\r\ndiprotes sama anak saya.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Dia bilang gini, “Bapak curang. Tidur di hotel, makan\r\nnasi kotak, tiap hari naik lift.”<br>\r\n“Nak, kan Bapak di sana kerja.”<br>\r\n“Apa Pak? Kerja? Preet! Katanya Jakarta banjir.”<br>\r\n“Nak, iya banjir, makanya Bapak ke Jakarta naik tongkang.”<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Anak saya itu sering protes karena dia itu ingin\r\nbanget ke Jakarta, ingin tahu Dufan. Kalau orang lain, anak yang lain, ingin\r\ntahu Dufan dibawa ke Dufan. Anak saya ingin tahu Dufan dibawa ke warnet.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">“Tuh Nak, Dufan, Dufan itu.”<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Tapi saya jadi tahu walaupun dari warnet, ternyata\r\nbanyak wahana di Dufan itu, salah satunya rumah miring. Rumah miring, ini kalau\r\nmandor saya tahu, dibongkar ini. Saya aja masang bata miring dimarahin. Ini\r\norang dengan sadar tanpa pengaruh alkohol ngebangun rumah miring. Ini anak\r\nproyek mana yang bikin? Bikin malu komunitas.<o:p></o:p></span></p><p class=\"MsoListParagraph\" style=\"margin-left:72.0pt;mso-add-space:auto;\r\ntext-indent:36.0pt\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Saya Didi. Terima kasih.</span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\"><span style=\"font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px;\"><b>Identifikasikanlah hal-hal berikut dari lawakan tunggal yang kalian simak</b></span></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\"><span style=\"font-size: 12pt; line-height: 107%;\">Unsur humor yang terdapat dalam teks bacaan Liburan Kuli Bangunan</span><span style=\"font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px;\"><b></b></span></span></p>', 'a:5:{s:1:\"a\";s:54:\"<p>Penyampaian monolog dengan gaya stand-up comedy</p>\";s:1:\"b\";s:124:\"<p>Liburan dapat menjadi sumber stres, terutama bagi mereka yang tidak memiliki cukup uang atau kesempatan untuk liburan</p>\";s:1:\"c\";s:55:\"<p>Pemilihan kata-kata kocak dan twist pada jawaban</p>\";s:1:\"d\";s:35:\"<p>Kurangnya kesempatan liburan</p>\";s:1:\"e\";s:60:\"<p>Penggunaan dialog lucu antara komika, anak, dan istri</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"e\";i:3;N;}', 1764302401, 1764903497, 1, '', 1, 0, 0, '72156630-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31502, 842, 0, 5, 5, NULL, NULL, NULL, '<p>Secara teoritik menurut&nbsp; Brent G. Wilson dalam bukunya Evaluation Of Learning In Art Education; Apresiasi seni memiliki tiga domain, yakni: perasaan (feeling), dalam konteks ini terkait dengan perasaan keindahan, penilaian (valuing) terkait dengan nilai seni, dan empati (emphatizing), terkait dengan sikap hormat kepada dunia seni rupa, termasuk kepada profesi seniman, yaitu perupa (pelukis, pematung, penggrafis, penggeramik, pendesain, pengriya, dan lain-lain).</p><p>Jelaskan pengertian dari seni rupa?</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Seni rupa adalah aktivitas mengindra karya seni rupa, merasakan, menikmati, menghayati dan menghargai nilai-nilai keindahan dalam karya seni serta menghormati keberagaman konsep dan variasi konvensi artistik eksistensi dunia seni rupa.', 1764302433, 1764302467, 1, '', 1, 0, 0, '721567e8-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31503, 842, 0, 4, 1, NULL, NULL, NULL, '<p>Dalam karya tari akan tercermin budaya masyarakat penyayangya. berbagai tari tentunya sudah kita tonton, ada tari nelayan, tari tani, tari berburu dan tari metik teh. Tari tersebut tercipta oleh para seniman dengan stimulus lingkungan sekitarnya, sehingga mendorong untuk meniru gerak-gerak alami, selanjutnya diolah dengan \'\'digayakan\'\' untuk menjadi semua tari.</p><p>Sebuah produk dari masyarakat adalah pengertian dari...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Karya tari', 1764302485, 1764304168, 1, '', 1, 0, 0, '7215691d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31504, 816, 0, 1, 1, NULL, NULL, NULL, 'Elektron dalam atom memiliki energi tertentu dan tersusun dalam kulit. Pernyataan ini sesuai dengan teori…', ' Dalton', 'Bohr', 'Thomson', '&nbsp;Rutherford', 'Schrodinger', NULL, NULL, NULL, NULL, NULL, 'b', 1764303440, 1765350554, 1, '', 1, 0, 0, '72156a05-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31505, 859, 0, 5, 3, NULL, NULL, NULL, 'Sebutkan dan jelaskan dimensi yang sering digunakan untuk memahami dan menganalisis peristiwa sejarah dan berikan contohnya masing-masing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><p>1. Dimensi Ruang: Dimensi ruang atau spasial merujuk pada tempat suatu peristiwa yang terjadi.</p><p>Contohnya: Tumbuhnya kesadaran nasionalisme dalam pergerakan nasionalisme pada suatu daerah.</p><p>2. Dimensi Waktu: Dimensi waktu merujuk pada kapan suatu peristiwa itu terjadi.</p><p>Contohnya: Ada orang yang menandai aktu kelahiran dengan peristiwa lain.</p></div></div>', 1764303588, 1764309021, 1, '', 1, 0, 0, '72156ade-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31506, 816, 0, 1, 2, NULL, NULL, NULL, 'Unsur X&nbsp; memiliki konfigurasi elektron 1s² 2s² 2p⁶ 3s² 3p⁴. Unsur ini berada pada golongan dan periode…', 'Golongan VI A, Periode 3', 'Golongan V A, Periode 3', 'Golongan VII A, Periode 2', 'Golongan II A, Periode 3', '&nbsp;Golongan I A, Periode 3', NULL, NULL, NULL, NULL, NULL, 'a', 1764304026, 1765350566, 1, '', 1, 0, 0, '72156c56-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31507, 847, 0, 2, 5, NULL, NULL, NULL, '<p class=\"MsoListParagraph\" style=\"margin-left:72.0pt;mso-add-space:auto;\r\ntext-indent:36.0pt\"><b><span style=\"font-size:12.0pt;line-height:107%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\ncolor:#1E293B;mso-fareast-language:EN-ID\">Liburan Kuli Bangunan</span></b></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Assalamualaikum warrahmatullahi wabarakatuh.\r\nPerkenalkan, saya Didi. Di sini ada kuli bangunan? Wah, berarti saya\r\nsatu-satunya ya di sini. Ngomong-ngomong soal liburan, buat kebanyakan orang,\r\nliburan itu obat stres, tapi buat saya malah bikin stres. Datang liburan\r\norang-orang sibuk nyiapin rencana mau liburan ke mana. Saya malah sibuk nyari\r\nalasan.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Anak saya minta liburan, “Pak, ingin ke Dufan.”<br>\r\n“Nak, Jakarta banjir.”<br>\r\n“Ya udah Pak, ke Tangkuban Perahu.”<br>\r\n“Nak, perahunya bocor.”<br>\r\n“Ah bilang aja, Bapak gak punya uang.”<br>\r\n“Cerdas!”<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Anak saya itu memang jarang liburan. Saya bawa ke\r\ntempat kerja saja, menurut dia itu tamasya. Dari pagi sampai sore, dia anteng\r\nnyusun lego, pakai batu bata. Kalau orang lain nyusun lego, anakanak, ya jadi\r\nrobot, anak saya jadi pos ronda.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Pulang ke rumah ditanya sama istri saya, “Gimana Nak,\r\nseru main sama Bapak?”<br>\r\n“Mantap, Mah! Pokoknya udah gede aku mau jadi kuli bangunan.”<br>\r\n“Hey, masa perempuan jadi kuli banguan..”<br>\r\n“Gak apa-apa, Mah, emansipasi!”<br>\r\nYa, anak saya itu memang jarang liburan, jadi dia itu norak. Kemarin saja saya\r\nbawa ajak mandi bola, dia bawa handuk.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Istri saya langsung ngomong, “Nak, mandi bola gak usah\r\nbawa handuk, Kan udah disediain.”<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Tapi bukan cuma anak saya, saya juga jarang liburan.\r\nSatu-satunya liburan saya ya di acara ini. Buat saya kompetisi ini liburan.\r\nGimana enggak coba? Saya dapat pergi ke Jakarta, tidur di hotel, kasurnya\r\nempuk, kalau saya tidur langsung terbayang hal indah. Gak kaya di rumah. Saya\r\nketika tidur langsung terbayang cicilan. Tapi, gara-gara itu saya sering\r\ndiprotes sama anak saya.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Dia bilang gini, “Bapak curang. Tidur di hotel, makan\r\nnasi kotak, tiap hari naik lift.”<br>\r\n“Nak, kan Bapak di sana kerja.”<br>\r\n“Apa Pak? Kerja? Preet! Katanya Jakarta banjir.”<br>\r\n“Nak, iya banjir, makanya Bapak ke Jakarta naik tongkang.”<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Anak saya itu sering protes karena dia itu ingin\r\nbanget ke Jakarta, ingin tahu Dufan. Kalau orang lain, anak yang lain, ingin\r\ntahu Dufan dibawa ke Dufan. Anak saya ingin tahu Dufan dibawa ke warnet.<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">“Tuh Nak, Dufan, Dufan itu.”<o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Tapi saya jadi tahu walaupun dari warnet, ternyata\r\nbanyak wahana di Dufan itu, salah satunya rumah miring. Rumah miring, ini kalau\r\nmandor saya tahu, dibongkar ini. Saya aja masang bata miring dimarahin. Ini\r\norang dengan sadar tanpa pengaruh alkohol ngebangun rumah miring. Ini anak\r\nproyek mana yang bikin? Bikin malu komunitas.<o:p></o:p></span></p><p class=\"MsoListParagraph\" style=\"margin-left:72.0pt;mso-add-space:auto;\r\ntext-indent:36.0pt\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\r\n&quot;Times New Roman&quot;,serif\">Saya Didi. Terima kasih.</span></p><p class=\"MsoNormal\">Identifikasikanlah hal-hal berikut dari lawakan tunggal yang kalian simak.</p><p class=\"MsoNormal\">Tema yang terdapat dalam teks bacaan Liburan Kuli</p>', 'a:4:{s:1:\"a\";s:44:\"<p> Keinginan anak untuk pergi ke Dufan</p>\";s:1:\"b\";s:43:\"<p>Tidak punya cukup uang untuk liburan</p>\";s:1:\"c\";s:33:\"<p>Noraknya anak dan keluarga</p>\";s:1:\"d\";s:48:\"<p>Sulitnya menyusun rencana liburan Liburan</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;N;}', 1764304137, 1764903518, 1, '', 1, 0, 0, '72156d42-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31508, 842, 0, 4, 2, NULL, NULL, NULL, '<p>Dari pengamatan terhadap tari diatas, kita bisa memahami bahwa tari tercipta karena berbagai asal stimulus (penglihatan, pendengaran, perasaan) yang tercurahkan dalam bentuk tari dengan konsep:</p><p>1. peniruan terhadap perilaku alam, manusia dan binatang</p><p>2.&nbsp; perwujudan tokoh cerita dan</p><p>3. mengacu lagu atau guru lagu</p><p>Salah satu teknik berkarya tari kreasi adalah...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Teknik gerak kepala', 1764304188, 1764304886, 1, '', 1, 0, 0, '72156ec4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
