INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31624, 842, 0, 2, 3, NULL, NULL, NULL, '<p style=\"text-align: center;\"><span style=\"font-size: 0.875rem;\"><span style=\"font-weight: bolder;\">TIPS MERAWAT PITA SUARA</span></span></p><p><span style=\"font-size: 0.875rem;\">Pita suara sangat viral untuk bernyanyi, oleh karena itu, pita suara perlu dijaga dan dirawat kesehatannya. berikut ini adalah tips untuk merawat pita suara 1. bernyanyi dengan nada yang pas sesuai rentang suara nada mu. bila sering menyanyikan nada-nada tinggi yang belum kamu kuasai, pita suara ini bisa aus. 2. tidak dianjurkan minum minuman yang terlalu dingin atau terlalu panas 3. bila sedang sakit, batuk, pilek baiknya jangan menyanyi 4. hindari makanan berminyak dan pedas sebelum menyanyi 5. jangan menyanyi dalam keadaan perut kosong atau terlalu kenyang. ini mempengaruhi rongga perut, diafragma, dan kualitas pernapasan 6. untuk menjaga pernapasan agar tetap prima, hindari minuman kopi, alkohol, dan merokok 7. ketika bangun tidur biasakan minum segelas air putih dan senam pagi sambil menghirup udara bersih sebanyak-banyaknya</span></p><p><span style=\"font-size: 0.875rem;\">Agar dihasilkan pelafalan lagu dengan baik, yang perlu dilatih adalah...</span></p>', 'a:5:{s:1:\"a\";s:19:\"<p>rahang bawah</p>\";s:1:\"b\";s:12:\"<p>bibir</p>\";s:1:\"c\";s:12:\"<p>lidah</p>\";s:1:\"d\";s:19:\"<p>kerongkongan</p>\";s:1:\"e\";s:13:\"<p>hidung</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"c\";i:3;N;}', 1764320303, 1764320543, 1, '', 1, 0, 0, '721626f4-e8d9-11f0-a465-0a0027000004', 