INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31626, 842, 0, 2, 4, NULL, NULL, NULL, '<p>Karya seni rupa tiga dimensi merupakan karya seni yang memiliki ukuran panjang, lebar dan tinggi, sehingga karya dapat dilihat dari segala arah. Simbol merupakan makna yang terkandung dalam karya seni rupa baik dalam wujudnya obyeknya maupun unsur-unsur rupanya.</p><p>Dalam pengklasifikasian seni rupa dapat dibuat berdasarkan...</p>', 'a:5:{s:1:\"a\";s:15:\"<p>1. Jenis</p>\";s:1:\"b\";s:11:\"<p>Tema</p>\";s:1:\"c\";s:13:\"<p>Fungsi</p>\";s:1:\"d\";s:20:\"<p>Nilai estetis</p>\";s:1:\"e\";s:6:\"bentuk\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"c\";i:3;s:1:\"d\";i:4;N;}', 1764320549, 1764332015, 1, '', 1, 0, 0, '72162973-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
