INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31669, 816, 0, 2, 1, NULL, NULL, NULL, '<p>Perhatikan pernyataan berikut tentang teori atom:</p><ol><li><span style=\"font-size: 0.875rem;\">Model Thomson menggambarkan atom sebagai bola positif berisi elektron</span></li><li>Rutherford menemukan bahwa inti atom bermuatan positif dan sangat kecil</li><li>Model Bohr menyatakan elektron memiliki tingkat energi tertentu</li><li>Model Mekanika Kuantum menyatakan posisi elektron dapat ditentukan secara pasti.\r\n</li></ol><p>\r\nPernyataan yang benar  adalah …</p>', 'a:5:{s:1:\"a\";s:14:\"<p>1 dan 2</p>\";s:1:\"b\";s:16:\"<p>1,2 dan 3</p>\";s:1:\"c\";s:16:\"<p>2,3 dan 4</p>\";s:1:\"d\";s:16:\"<p>1,3 dan 4</p>\";s:1:\"e\";s:20:\"<p>semua benar </p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1764322941, 1764646543, 1, '', 1, 0, 0, '72165fad-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31670, 872, 0, 5, 1, NULL, NULL, NULL, 'Sebuah sekolah ingin membuat sistem absensi otomatis menggunakan kartu RFID. Jelaskan langkah-langkah berpikir komputasional yang diperlukan untuk merancang solusi tersebut.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p data-start=\"347\" data-end=\"383\">Langkah-langkahnya:</p>\r\n<ul data-start=\"384\" data-end=\"908\">\r\n<li data-start=\"384\" data-end=\"522\">\r\n<p data-start=\"386\" data-end=\"522\"><strong data-start=\"386\" data-end=\"404\">Decomposition:</strong> Memecah masalah menjadi bagian kecil (pencatatan absensi, identifikasi siswa, penyimpanan data, pembuatan laporan).</p>\r\n</li>\r\n<li data-start=\"523\" data-end=\"644\">\r\n<p data-start=\"525\" data-end=\"644\"><strong data-start=\"525\" data-end=\"549\">Pattern Recognition:</strong> Mengidentifikasi pola penggunaan kartu setiap pagi dan kebutuhan data yang sama setiap hari.</p>\r\n</li>\r\n<li data-start=\"645\" data-end=\"753\">\r\n<p data-start=\"647\" data-end=\"753\"><strong data-start=\"647\" data-end=\"663\">Abstraction:</strong> Mengabaikan detail yang tidak penting seperti warna kartu dan hanya fokus pada ID unik.</p>\r\n</li>\r\n<li data-start=\"754\" data-end=\"908\">\r\n<p data-start=\"756\" data-end=\"908\"><strong data-start=\"756\" data-end=\"777\">Algorithm Design:</strong> Merancang langkah-langkah sistem seperti: siswa tap → sistem membaca ID → dicocokkan ke database → waktu direkam → laporan dibuat.</p></li></ul>', 1764322988, 1764323037, 1, '', 1, 0, 0, '7216618d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31671, 872, 0, 5, 2, NULL, NULL, NULL, 'Sebuah perusahaan ingin membuat poster digital promosi. Jelaskan bagaimana keterampilan berpikir kreatif dan kolaboratif dibutuhkan dalam proses ini.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<li data-start=\"1094\" data-end=\"1223\"><p data-start=\"1096\" data-end=\"1223\"><strong data-start=\"1096\" data-end=\"1117\">Berpikir kreatif:</strong> Dibutuhkan untuk menentukan konsep visual, memilih desain, warna, ikon, dan pesan promosi yang menarik.</p>\r\n</li>\r\n<li data-start=\"1224\" data-end=\"1444\">\r\n<p data-start=\"1226\" data-end=\"1444\"><strong data-start=\"1226\" data-end=\"1242\">Kolaboratif:</strong> Tim perlu bekerja sama antara desainer, penulis konten, dan pemasar agar poster memenuhi tujuan promosi. Kolaborasi membantu memastikan pesan jelas, desain estetis, dan informasi sesuai target audiens.</p></li>', 1764322990, 1764323083, 1, '', 1, 0, 0, '72166347-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31672, 872, 0, 5, 3, NULL, NULL, NULL, 'Dalam sebuah proyek informatika, seorang siswa diminta membuat presentasi mengenai keamanan siber. Jelaskan bagaimana keterampilan komunikasi efektif memengaruhi keberhasilan presentasi tersebut.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Komunikasi efektif membantu siswa menyampaikan informasi secara jelas, runtut, dan mudah dipahami. Penggunaan bahasa yang tepat, visual yang informatif, serta kemampuan menjawab pertanyaan audiens akan membuat presentasi lebih meyakinkan. Tanpa komunikasi efektif, konten yang sebenarnya bagus dapat sulit dipahami.', 1764322992, 1764323125, 1, '', 1, 0, 0, '721664f5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31673, 872, 0, 5, 4, NULL, NULL, NULL, 'Anda diminta menganalisis data nilai ujian dari tiga kelas untuk menentukan strategi pembelajaran baru. Jelaskan bagaimana keterampilan literasi data digunakan dalam situasi ini.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p data-start=\"2191\" data-end=\"2238\">Literasi data digunakan untuk:</p>\r\n<ul data-start=\"2239\" data-end=\"2524\">\r\n<li data-start=\"2239\" data-end=\"2279\">\r\n<p data-start=\"2241\" data-end=\"2279\">Mengumpulkan dan membaca data nilai.</p>\r\n</li>\r\n<li data-start=\"2280\" data-end=\"2348\">\r\n<p data-start=\"2282\" data-end=\"2348\">Mengidentifikasi pola seperti nilai rendah pada materi tertentu.</p>\r\n</li>\r\n<li data-start=\"2349\" data-end=\"2395\">\r\n<p data-start=\"2351\" data-end=\"2395\">Membandingkan antar kelas secara objektif.</p>\r\n</li>\r\n<li data-start=\"2396\" data-end=\"2470\">\r\n<p data-start=\"2398\" data-end=\"2470\">Menarik kesimpulan tentang aspek pembelajaran yang perlu ditingkatkan.</p>\r\n</li>\r\n<li data-start=\"2471\" data-end=\"2524\">\r\n<p data-start=\"2473\" data-end=\"2524\">Merumuskan rekomendasi berbasis data, bukan asumsi.</p></li></ul>', 1764322994, 1764323176, 1, '', 1, 0, 0, '72166695-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
