INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31701, 816, 0, 5, 1, NULL, NULL, NULL, 'Jelaskan perbedaan antara isotop, isoton, dan isobar!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<li data-start=\"829\" data-end=\"900\"><p data-start=\"831\" data-end=\"900\"><strong data-start=\"831\" data-end=\"842\">Isotop:</strong> Atom dengan nomor atom sama tetapi nomor massa berbeda.</p>\r\n</li>\r\n<li data-start=\"901\" data-end=\"975\">\r\n<p data-start=\"903\" data-end=\"975\"><strong data-start=\"903\" data-end=\"914\">Isoton:</strong> Atom dengan jumlah neutron sama tetapi nomor atom berbeda.</p>\r\n</li>\r\n<li data-start=\"976\" data-end=\"1045\">\r\n<p data-start=\"978\" data-end=\"1045\"><strong data-start=\"978\" data-end=\"989\">Isobar:</strong> Atom dengan nomor massa sama tetapi nomor atom berbeda.</p></li>', 1764325638, 1764325880, 1, '', 1, 0, 0, '72168e46-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31702, 843, 0, 4, 2, NULL, NULL, NULL, '<p>Karya seni rupa tiga dimensi beraneka jenis dan ragamnya. karya seni rupa tiga dimensi dapat dikelompokan berdasarkan bahan, teknik pembuatan, gaya perwujudan, tema, fungsi, dan sebagainya.</p><p style=\"text-align: justify;\">Nilai estetis karya seni rupa tiga dimensi tampak secara visual dari wujud karya seni rupa tersebut. nilai objektif terdapat pada karya seni rupa itu sendiri, sedangkan nilai subjektif berada pada penikmatnya.</p><p style=\"text-align: justify;\"><span style=\"text-align: left;\">Jenis benda yang termasuk ke dalam karya tiga dimensi adalah ...</span></p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'patung', 1764325766, 1765349522, 1, '', 1, 0, 0, '72168fcf-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31703, 816, 0, 5, 2, NULL, NULL, NULL, 'Tuliskan konfigurasi elektron unsur berikut dan tentukan golongan serta periodenya:a) Z = 8 dan b) Z = 17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a) <strong data-start=\"1661\" data-end=\"1680\">Z = 8 (Oksigen)</strong> → 1s² 2s² 2p⁴ → Golongan VIA, Periode 2<br data-start=\"1720\" data-end=\"1723\">\r\nb) <strong data-start=\"1726\" data-end=\"1745\">Z = 17 (Klorin)</strong> → 1s² 2s² 2p⁶ 3s² 3p⁵ → Golongan VIIA, Periode 3', 1764325887, 1764325998, 1, '', 1, 0, 0, '72169228-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31704, 873, 0, 2, 1, NULL, NULL, NULL, '<p style=\"text-align: center;\">The Legend of the Holy stone.</p><p style=\"text-align: justify; \">\r\n\r\nA long time ago, up on the Kamboi Rama mountain, there were two villages, kamboi Rama and Aroempu. Komboi Rama was a residence for Kamboi people and Aroempu was a sago plantation owned by God Iriwonawani, who also owned a Tifa. Whenever the tifa is played, the Komboi people would gather. Every day, the Kombai women would go to Aroempu to cut sago for their meals. As time passed by, the sago trees were becoming scarced.God Iriwonawani got really anggry, Get ot of here! Don’t just cut but saw and plant! Because they were scared , the Kamboy people moved to the coastal area and named themselves Randuayaivi. However upon the mountain, there still lived a couple of husband and wife, Irimiami and Isoray.\r\n</p><p style=\"text-align: justify; \">\r\nBased on the text above, there are Verbs Categories!</p>', 'a:6:{s:1:\"a\";s:20:\"<p>Mountain <br></p>\";s:1:\"b\";s:17:\"<p>Owned <br></p>\";s:1:\"c\";s:14:\"<p>God<br></p>\";s:1:\"d\";s:14:\"<p>Get<br></p>\";s:1:\"e\";s:16:\"<p>Moved<br></p>\";s:1:\"f\";s:18:\"<p>Husband<br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"b\";i:1;s:1:\"d\";i:2;s:1:\"e\";i:3;N;}', 1764325907, 1764904855, 1, '', 1, 0, 0, '72169326-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31705, 843, 0, 4, 3, NULL, NULL, NULL, '<p><span style=\"text-align: justify;\">Berkarya seni rupa dua dimensi adalah kegiatan(proses) menggunakan alat dan bahan tertentu melaui ketrampilan teknik berkarya seni rupa untuk memvisualisasikan gagasan, pikiran dan atau perasaan seorang perupa pada bidang dua dimensi. nilai estetis, identik dengan keindahan dan keunikan sebuah karya seni rupa. nilai estetis sebiah karya seni rupa terutama dipengaruhi oleh keharmonisan dan keselarasan penataan unsur-unsur rupanya.</span></p><p>Unsur bentuk diterapkan dalam menciptakan karya seni ...<span style=\"text-align: justify;\"></span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'interior', 1764325910, 1764325950, 1, '', 1, 0, 0, '721694c2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31706, 843, 0, 4, 4, NULL, NULL, NULL, '<p><span style=\"text-align: justify;\">Nilai estetis atau keindahan sebuah karya seni rupa tersusun dari komposisi yang baik, perpaduan warna yang sesuai, penempatan objek yang membentuk kesatuan dan sebagainya.</span></p><p><span style=\"text-align: justify;\"> Keselarasan dalam menata unsur-unsur visual dapat mewujudkan sebuah karya seni rupa, disebut keindahan bersifat ....</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'objektif', 1764325956, 1764326073, 1, '', 1, 0, 0, '7216964f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31707, 816, 0, 5, 3, NULL, NULL, NULL, 'Jelaskan pengertian atom menurut model Dalton, Thomson, Rutherford, dan Bohr!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<li data-start=\"306\" data-end=\"398\"><p data-start=\"308\" data-end=\"398\"><strong data-start=\"308\" data-end=\"319\">Dalton:</strong> Atom adalah partikel terkecil yang tidak bisa dibagi, menyusun semua materi.</p>\r\n</li>\r\n<li data-start=\"399\" data-end=\"511\">\r\n<p data-start=\"401\" data-end=\"511\"><strong data-start=\"401\" data-end=\"413\">Thomson:</strong> Atom berbentuk bola bermuatan positif dengan elektron tersebar di dalamnya (model roti kismis).</p>\r\n</li>\r\n<li data-start=\"512\" data-end=\"623\">\r\n<p data-start=\"514\" data-end=\"623\"><strong data-start=\"514\" data-end=\"529\">Rutherford:</strong> Atom terdiri dari inti kecil bermuatan positif dikelilingi elektron bergerak di sekitarnya.</p>\r\n</li>\r\n<li data-start=\"624\" data-end=\"740\">\r\n<p data-start=\"626\" data-end=\"740\"><strong data-start=\"626\" data-end=\"635\">Bohr:</strong> Elektron bergerak mengelilingi inti pada lintasan tertentu dengan energi tetap (tingkat energi kuantum).</p></li>', 1764326003, 1764326099, 1, '', 1, 0, 0, '72169744-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31708, 843, 0, 4, 5, NULL, NULL, NULL, '<p>Karya seni rupa tiga dimensi beraneka jenis dan ragamnya. karya seni rupa tiga dimensi dapat dikelompokan berdasarkan bahan, teknik pembuatan, gaya perwujudan, tema, fungsi, dan sebagainya.</p><p style=\"text-align: justify;\">Nilai estetis karya seni rupa tiga dimensi tampak secara visual dari wujud karya seni rupa tersebut. nilai objektif terdapat pada karya seni rupa itu sendiri, sedangkan nilai subjektif berada pada penikmatnya.</p><p style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berikut yang merupakan karya seni terapan tiga dimensi adalah ...</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'gerabah', 1764326095, 1764326184, 1, '', 1, 0, 0, '72169958-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31709, 816, 0, 5, 4, NULL, NULL, NULL, 'Jelaskan perbedaan ikatan ion, ikatan kovalen, dan ikatan logam!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<li data-start=\"241\" data-end=\"381\"><p data-start=\"243\" data-end=\"381\"><strong data-start=\"243\" data-end=\"258\">Ikatan ion:</strong> Terjadi antara logam dan nonlogam; elektron berpindah dari logam ke nonlogam sehingga terbentuk ion positif dan negatif.</p>\r\n</li>\r\n<li data-start=\"382\" data-end=\"471\">\r\n<p data-start=\"384\" data-end=\"471\"><strong data-start=\"384\" data-end=\"403\">Ikatan kovalen:</strong> Terjadi antara dua nonlogam; elektron dibagi secara bersama-sama.</p>\r\n</li>\r\n<li data-start=\"472\" data-end=\"574\">\r\n<p data-start=\"474\" data-end=\"574\"><strong data-start=\"474\" data-end=\"491\">Ikatan logam:</strong> Terjadi antara logam; elektron valensi bergerak bebas membentuk “lautan elektron”.</p></li>', 1764326105, 1764326237, 1, '', 1, 0, 0, '72169a32-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31710, 816, 0, 5, 5, NULL, NULL, NULL, 'Sebutkan dan jelaskan dua jenis ikatan kovalen!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<li data-start=\"657\" data-end=\"728\"><p data-start=\"659\" data-end=\"728\"><strong data-start=\"659\" data-end=\"679\">Kovalen tunggal:</strong> Satu pasangan elektron dibagi antara dua atom.</p>\r\n</li>\r\n<li data-start=\"729\" data-end=\"864\">\r\n<p data-start=\"731\" data-end=\"864\"><strong data-start=\"731\" data-end=\"751\">Kovalen rangkap:</strong> Dua atau tiga pasang elektron dibagi (rangkap dua = satu sigma + satu pi; rangkap tiga = satu sigma + dua pi).</p>\r\n</li>\r\n<li data-start=\"865\" data-end=\"962\">\r\n<p data-start=\"867\" data-end=\"962\"><strong data-start=\"867\" data-end=\"899\">Kovalen koordinasi (dative):</strong> Satu atom menyumbangkan kedua elektron untuk pasangan bersama.</p></li>', 1764326240, 1764326320, 1, '', 1, 0, 0, '72169c2a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31711, 847, 0, 1, 23, NULL, NULL, NULL, 'Salah satu contoh pola pengembangan teks eksposisi adalah analogi. Yang dimaksud eksposisi analogi adalah....', 'memaparkan sesuatu dengan jelas', 'menjelaskan tata cara melakukan sesuatu', 'menguraikan maksud dan tujuan', 'menilai penyajian teks eksposisi', 'memaparkan sesuatu dengan menggunakan penyamaan atau perbandingan agar lebih jelas', NULL, NULL, NULL, NULL, NULL, 'c', 1764326279, 1764326421, 1, '', 1, 0, 0, '72169d06-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31712, 816, 0, 2, 3, NULL, NULL, NULL, '<p>Perhatikan pernyataan berikut:\r\n</p><ol><li>\r\nBilangan kuantum utama (n) menunjukkan tingkat energi elektron.\r\n</li><li>\r\nBilangan kuantum azimut (l) menentukan bentuk orbital.\r\n</li><li>\r\nBilangan kuantum magnetik (m) menunjukkan orientasi orbital.\r\n</li><li>\r\nBilangan kuantum spin (s) bernilai +½ dan –½.\r\n</li><li>\r\nNilai l selalu sama dengan n.\r\n</li></ol><p>\r\nPernyataan yang benar adalah:</p>', 'a:5:{s:1:\"a\";s:22:\"<p>1, 2, dan 3<br></p>\";s:1:\"b\";s:21:\"<p>1, 2, 3, dan 4</p>\";s:1:\"c\";s:18:\"<p>2, 3, dan 5</p>\";s:1:\"d\";s:18:\"<p>1, 3, dan 4</p>\";s:1:\"e\";s:18:\"<p>1,2,4 dan 5</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"d\";i:3;N;}', 1764326374, 1764646940, 1, '', 1, 0, 0, '72169f09-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
