INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31753, 849, 0, 3, 3, NULL, NULL, NULL, '<p style=\"text-align: center; \"><b>Kehidupan Chairil Anwar</b>\r\n</p><p>\r\nChairil Anwar dilahirkan di Medan, Sumatera Utara pada 26 Juli 1922. Dia merupakan anak satu-satunya dari pasangan Toeloes dan Saleha, keduanya berasal dari Kabupaten Lima Puluh Kota, Sumatera Barat. Ayahnya merupakan Bupati Indragiri, Riau yang tewas dalam Pembantaian Rengat. Dia masih memiliki pertalian keluarga dengan Soetan Sjahrir, Perdana Menteri pertama Indonesia.[1] Sebagai anak tunggal, orang tuanya selalu memanjakannya,[2] tetapi Chairil cenderung bersikap keras kepala dan tidak ingin kehilangan apapun; yang sedikit mirip dengan kepribadian orang tuanya.\r\n\r\nChairil Anwar mulai mengenyam pendidikan di Hollandsch-Inlandsche School (HIS), sekolah dasar untuk orang-orang pribumi pada masa penjajahan Belanda. Dia kemudian meneruskan pendidikannya di Meer Uitgebreid Lager Onderwijs (MULO). Saat usianya mencapai 18 tahun, dia tidak lagi bersekolah.[3] Chairil mengatakan bahwa sejak usia 15 tahun, dia telah bertekad menjadi seorang seniman.[4]\r\n\r\nPada usia 19 tahun, setelah perceraian orang tuanya, Chairil bersama ibunya pindah ke Batavia (sekarang Jakarta) di mana dia berkenalan dengan dunia sastra. Walau telah bercerai, ayahnya tetap menafkahinya dan ibunya.[5] Meskipun tidak dapat menyelesaikan sekolahnya, ia dapat menguasai berbagai bahasa asing seperti Inggris, Belanda, dan Jerman.[6] Ia juga mengisi jam-jamnya dengan membaca karya-karya pengarang internasional ternama, seperti: Rainer Maria Rilke, W.H. Auden, Archibald MacLeish, Hendrik Marsman, J. Slaurhoff, dan Edgar du Perron. Penulis-penulis tersebut sangat memengaruhi tulisannya secara langsung dan tatanan kesusasteraan Indonesia secara tidak langsung.</p><p>Dari Riwayat hidup si Chairil Anwar di atas. </p><p>Tentukan apakah pernyataan berikut <b>benar</b> atau <b>salah</b>.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:7:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:75:\"<p>Chairil Anwar dilahirkan di Medan, Sumatera Utara pada 26 Juli 1922</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:123:\"<p>Pernah menjadi staf redaktur harian Merdeka (surat kabar), majalah Keluarga dan majalah Amanah, semuanya di Jakarta</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:163:\"<p>Pada usia 19 tahun, setelah perceraian orang tuanya, Chairil bersama ibunya pindah ke Batavia (sekarang Jakarta) di mana dia berkenalan dengan dunia sastra</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:156:\"<p>Chairil Anwar mulai mengenyam pendidikan di Hollandsch-Inlandsche School (HIS), sekolah dasar untuk orang-orang pribumi pada masa penjajahan Belanda</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:139:\"<p>Novel yang diterbitkan tahun 1982 berkisah tentang pergulatan penari tayub di dusun kecil, Dukuh Paruk pada masa pergolakan komunis</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:6;a:3:{i:0;s:137:\"<p>Dia merupakan anak satu-satunya dari pasangan Toeloes dan Saleha, keduanya berasal dari Kabupaten Lima Puluh Kota, Sumatera Barat</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1764331424, 1764905898, 1, '', 1, 0, 0, '7216d8a1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31754, 843, 0, 5, 1, NULL, NULL, NULL, '<p>Karya seni rupa tiga dimensi beraneka jenis dan ragamnya. karya seni rupa tiga dimensi dapat dikelompokan berdasarkan bahan, teknik pembuatan, gaya perwujudan, tema, fungsi, dan sebagainya.</p><p style=\"text-align: justify;\">Nilai estetis karya seni rupa tiga dimensi tampak secara visual dari wujud karya seni rupa tersebut. nilai objektif terdapat pada karya seni rupa itu sendiri, sedangkan nilai subjektif berada pada penikmatnya.</p><p>Nilai estetis karya seni rupa bersifat...</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>objektif dan subjektif</div></body></html>', 1764331475, 1765349560, 1, '', 1, 0, 0, '7216da4b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31755, 843, 0, 5, 2, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Karya seni rupa tiga dimensi merupakan karya seni yang memiliki ukuran panjang, lebar dan tinggi, sehingga karya dapat dilihat dari segala arah. Simbol merupakan makna yang dikandung dalam karya seni rupa baik dalam wujudnya obyeknya maupun unsur-unsur rupanya. salah satu karya seni rupa tiga dimensi adalah patung. karya seni patung memiliki berbagai ragam dan jenis yang tersusun dari berbagai medium pula.</p><p>Langkah - langkah mewujudkan karya seni rupa tiga dimensi adalah...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div style=\"text-align: justify;\">1. mencari dan menemukan ide</div><div>2. membuat sketsa</div><div>3. memilih alat dan bahan</div><div>4. berkarya patung</div>', 1764331537, 1764331589, 1, '', 1, 0, 0, '7216db30-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31756, 843, 0, 5, 3, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Karya seni rupa tiga dimensi merupakan karya seni yang memiliki ukuran panjang, lebar dan tinggi, sehingga karya dapat dilihat dari segala arah. Simbol merupakan makna yang dikandung dalam karya seni rupa baik dalam wujudnya obyeknya maupun unsur-unsur rupanya.</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Berdasarkan fungsinya, karya seni rupa tiga dimensi dibedakan menjadi 2 yaitu...</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>1. karya yang memiliki fungsi pakai (seni rupa terapan - applied art) dan</div><div style=\"text-align: justify;\">2. karya seni rupa yang hanya memiliki fungsi ekspresi saja (seni rupa murni - pure art)</div>', 1764331595, 1764331640, 1, '', 1, 0, 0, '7216dcac-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31757, 843, 0, 5, 4, NULL, NULL, NULL, '<p style=\"text-align: justify;\">Berkarya seni rupa dua dimensi adalah kegiatan(proses) menggunakan alat dan bahan tertentu melaui ketrampilan teknik berkarya seni rupa untuk memvisualisasikan gagasan, pikiran dan atau perasaan seorang perupa pada bidang dua dimensi.</p><p>Sebutkan sketsa proses berkarya...</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>1. mencari ide atau gagasan berkarya</div><div>2. menemukan ide atau gagasan berkarya</div><div>3. menuangkan ide atau gagasan berkarya ke dalam sketsa</div><div style=\"text-align: justify;\">4. memindahkan sketsa ke atas kanvas</div><div>5. mempresentasikan karya seni</div>', 1764331646, 1764331689, 1, '', 1, 0, 0, '7216de13-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31758, 843, 0, 5, 5, NULL, NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Nilai estetis</span><span style=\"font-size: 0.875rem;\">, identik dengan keindahan dan keunikan sebuah karya seni rupa. nilai estetis sebuah karya seni rupa terutama dipengaruhi oleh keharmonisan dan keselarasan penataan unsur-unsur rupanya. nilai estetis dapat juga bersifat subjektif sesuai dengan selera orang melihatnya. pengalaman pribadi, lingkungan dan budaya di mana seseorang tinggal dapat menyebabkan nilai estetis sebuah karya seni rupa berbeda antara satu orang dengan orang lainnya.</span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\"><br></span></div><div style=\"text-align: justify;\"><span style=\"font-size: 0.875rem;\">Sebuah karya seni rupa menjadi indah dan unik karena...</span></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<span style=\"text-align: justify;\">kemampuan perupanya memilih dan memvisualisasikan objek pada bidang garapannya melalui pengolahan unsur-unsur</span>', 1764331694, 1764331739, 1, '', 1, 0, 0, '7216df72-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31759, 843, 0, 2, 1, NULL, NULL, NULL, '<p>Karya seni rupa tiga dimensi merupakan karya seni yang memiliki ukuran panjang, lebar dan tinggi, sehingga karya dapat dilihat dari segala arah. Simbol merupakan makna yang terkandung dalam karya seni rupa baik dalam wujudnya obyeknya maupun unsur-unsur rupanya.</p><p>Dalam pengklasifikasian seni rupa dapat dibuat berdasarkan...</p>', 'a:5:{s:1:\"a\";s:12:\"<p>Jenis</p>\";s:1:\"b\";s:11:\"<p>Tema</p>\";s:1:\"c\";s:13:\"<p>Fungsi</p>\";s:1:\"d\";s:20:\"<p>Nilai estetis</p>\";s:1:\"e\";s:13:\"<p>Bentuk</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"c\";i:3;s:1:\"d\";i:4;N;}', 1764331899, 1764332077, 1, '', 1, 0, 0, '7216e0d9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31760, 849, 0, 5, 1, NULL, NULL, NULL, 'Apa hubungan H. B. Jassin dan Chairil Anwar?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>terbentuk melalui interaksi mereka sebagai kritikus sastra dan penyair, serta peran penting H.B. Jassin dalam mengakui dan mendokumentasikan karya Chairil Anwar.</div>', 1764332024, 1764907132, 1, '', 1, 0, 0, '7216e23b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
