INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31762, 843, 0, 2, 2, NULL, NULL, NULL, '<p style=\"text-align: center;\"><span style=\"font-size: 0.875rem;\"><span style=\"font-weight: bolder;\">TIPS MERAWAT PITA SUARA</span></span></p><p><span style=\"font-size: 0.875rem;\">Pita suara sangat viral untuk bernyanyi, oleh karena itu, pita suara perlu dijaga dan dirawat kesehatannya. berikut ini adalah tips untuk merawat pita suara 1. bernyanyi dengan nada yang pas sesuai rentang suara nada mu. bila sering menyanyikan nada-nada tinggi yang belum kamu kuasai, pita suara ini bisa aus. 2. tidak dianjurkan minum minuman yang terlalu dingin atau terlalu panas 3. bila sedang sakit, batuk, pilek baiknya jangan menyanyi 4. hindari makanan berminyak dan pedas sebelum menyanyi 5. jangan menyanyi dalam keadaan perut kosong atau terlalu kenyang. ini mempengaruhi rongga perut, diafragma, dan kualitas pernapasan 6. untuk menjaga pernapasan agar tetap prima, hindari minuman kopi, alkohol, dan merokok 7. ketika bangun tidur biasakan minum segelas air putih dan senam pagi sambil menghirup udara bersih sebanyak-banyaknya.&nbsp;</span></p><p><span style=\"font-size: 0.875rem;\">Hal yang perlu diperhatikan agar kita dapat membawa lagu dengan merdu dan benar adalah...</span></p>', 'a:4:{s:1:\"a\";s:30:\"<p>ketepatan membidik nada</p>\";s:1:\"b\";s:24:\"<p>interpretasi lagu</p>\";s:1:\"c\";s:21:\"<p>penjiwaan lagu</p>\";s:1:\"d\";s:36:\"<p>tidak bernyanyi terlalu keras</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"c\";i:3;N;}', 1764332085, 1764332215, 1, '', 1, 0, 0, '7216e3f7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
