INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31770, 843, 0, 2, 5, NULL, NULL, NULL, '<p><span style=\"font-size: 0.875rem;\">Pita suara sangat viral untuk bernyanyi, oleh karena itu, pita suara perlu dijaga dan dirawat kesehatannya. berikut ini adalah tips untuk merawat pita suara 1. bernyanyi dengan nada yang pas sesuai rentang suara nada mu. bila sering menyanyikan nada-nada tinggi yang belum kamu kuasai, pita suara ini bisa aus. 2. tidak dianjurkan minum minuman yang terlalu dingin atau terlalu panas 3. bila sedang sakit, batuk, pilek baiknya jangan menyanyi 4. hindari makanan berminyak dan pedas sebelum menyanyi 5. jangan menyanyi dalam keadaan perut kosong atau terlalu kenyang. ini mempengaruhi rongga perut, diafragma, dan kualitas pernapasan 6. untuk menjaga pernapasan agar tetap prima, hindari minuman kopi, alkohol, dan merokok 7. ketika bangun tidur biasakan minum segelas air putih dan senam pagi sambil menghirup udara bersih sebanyak-banyaknya</span></p><p><span style=\"font-size: 0.875rem;\">Selain untuk menyampaikan pesan, lagu juga diciptakan untuk mengungkapkan rasa seperti....</span></p>', 'a:5:{s:1:\"a\";s:18:\"<p>rasa syukur</p>\";s:1:\"b\";s:19:\"<p>rasa gembira</p>\";s:1:\"c\";s:20:\"<p>rasa semangat</p>\";s:1:\"d\";s:18:\"<p>rasa hormat</p>\";s:1:\"e\";s:17:\"<p>rasa biasa</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"c\";i:3;s:1:\"d\";i:4;N;}', 1764332488, 1764332612, 1, '', 1, 0, 0, '7216ec93-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
