INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31775, 849, 0, 3, 5, NULL, NULL, NULL, 'Perhatikan informasi tambahan tentang H. B. Jassin\r\n\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"1\";s:7:\"jawaban\";a:6:{i:0;a:3:{i:0;s:9:\"<p>#</p>\n\";i:1;s:12:\"<p>Benar</p>\";i:2;s:12:\"<p>Salah</p>\";}i:1;a:3:{i:0;s:157:\"<p>Chairil Anwar mulai mengenyam pendidikan di Hollandsch-Inlandsche School (HIS), sekolah dasar untuk orang-orang pribumi pada masa penjajahan Belanda.</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:2;a:3:{i:0;s:128:\"<p>HIS Balikpapan (1927&ndash;1929): Sejak masa sekolahnya di HIS, Jassin sudah terbiasa menyimpan buku-bukunya dengan rapi</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:3;a:3:{i:0;s:71:\"<p>Sejak usia 15 tahun, dia telah bertekad menjadi seorang seniman</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:4;a:3:{i:0;s:149:\"<p>Yayasan Dokumentasi Sastra H.B. Jassin (1977): Mendirikan lembaga ini untuk mengelola koleksi dokumentasi sastra Indonesia secara menyeluruh.</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:5;a:3:{i:0;s:85:\"<p>Sejak usia muda, Jassin sudah terinspirasi oleh perpustakaan pribadi ayahnya.</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";}}}', 1764335307, 1764905975, 1, '', 1, 0, 0, '7216f2d1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
