INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31780, 849, 0, 2, 5, NULL, NULL, NULL, '<p style=\"text-align: center; \"><b>Kehidupan Chairil Anwar</b>\r\n</p><p>\r\nChairil Anwar dilahirkan di Medan, Sumatera Utara pada 26 Juli 1922. Dia merupakan anak satu-satunya dari pasangan Toeloes dan Saleha, keduanya berasal dari Kabupaten Lima Puluh Kota, Sumatera Barat. Ayahnya merupakan Bupati Indragiri, Riau yang tewas dalam Pembantaian Rengat. Dia masih memiliki pertalian keluarga dengan Soetan Sjahrir, Perdana Menteri pertama Indonesia. Sebagai anak tunggal, orang tuanya selalu memanjakannya, tetapi Chairil cenderung bersikap keras kepala dan tidak ingin kehilangan apapun; yang sedikit mirip dengan kepribadian orang tuanya.\r\n\r\nChairil Anwar mulai mengenyam pendidikan di Hollandsch-Inlandsche School (HIS), sekolah dasar untuk orang-orang pribumi pada masa penjajahan Belanda. Dia kemudian meneruskan pendidikannya di Meer Uitgebreid Lager Onderwijs (MULO). Saat usianya mencapai 18 tahun, dia tidak lagi bersekolah. Chairil mengatakan bahwa sejak usia 15 tahun, dia telah bertekad menjadi seorang seniman. Pada usia 19 tahun, setelah perceraian orang tuanya, Chairil bersama ibunya pindah ke Batavia (sekarang Jakarta) di mana dia berkenalan dengan dunia sastra. Walau telah bercerai, ayahnya tetap menafkahinya dan ibunya. Meskipun tidak dapat menyelesaikan sekolahnya, ia dapat menguasai berbagai bahasa asing seperti Inggris, Belanda, dan Jerman. Ia juga mengisi jam-jamnya dengan membaca karya-karya pengarang internasional ternama, seperti: Rainer Maria Rilke, W.H. Auden, Archibald MacLeish, Hendrik Marsman, J. Slaurhoff, dan Edgar du Perron. Penulis-penulis tersebut sangat memengaruhi tulisannya secara langsung dan tatanan kesusasteraan Indonesia secara tidak langsung.</p><p>Dari Riwayat hidup si Chairil Anwar di atas. </p><p>Tentukan apakah pernyataan berikut benar atau salah.</p>', 'a:6:{s:1:\"a\";s:74:\"<p>Chairil Anwar dilahirkan di Medan, Sumatera Utara pada 26 Juli 1922</p>\";s:1:\"b\";s:122:\"<p>Pernah menjadi staf redaktur harian Merdeka (surat kabar), majalah Keluarga dan majalah Amanah, semuanya di Jakarta</p>\";s:1:\"c\";s:162:\"<p>Pada usia 19 tahun, setelah perceraian orang tuanya, Chairil bersama ibunya pindah ke Batavia (sekarang Jakarta) di mana dia berkenalan dengan dunia sastra</p>\";s:1:\"d\";s:155:\"<p>Chairil Anwar mulai mengenyam pendidikan di Hollandsch-Inlandsche School (HIS), sekolah dasar untuk orang-orang pribumi pada masa penjajahan Belanda</p>\";s:1:\"e\";s:138:\"<p>Novel yang diterbitkan tahun 1982 berkisah tentang pergulatan penari tayub di dusun kecil, Dukuh Paruk pada masa pergolakan komunis</p>\";s:1:\"f\";s:136:\"<p>Dia merupakan anak satu-satunya dari pasangan Toeloes dan Saleha, keduanya berasal dari Kabupaten Lima Puluh Kota, Sumatera Barat</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;s:1:\"f\";i:4;N;}', 1764340575, 1764905769, 1, '', 1, 0, 0, '7216fb25-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:49', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
