INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31820, 846, 0, 1, 16, NULL, NULL, NULL, '<p>Cermatilah pernyataan berikut ini!</p><p>\r\n1) Pengaruh kebudayaan masyarakat lain\r\n</p><p>2) Berkembangnya ilmu pengetahuan</p><p>\r\n3) Peperangan\r\n</p><p>4) Pertentangan dan pemberontakan\r\n</p><p>5) Terjadinya bencana alam\r\n</p><p>6) Jumlah penduduk</p><p>\r\nBerdasarkan pernyataan di atas yang menunjukkan faktor penyebab perubahan sosial yang berasal dari dalam masyarakat ditunjukkan oleh nomor ....</p><p>\r\n</p>', '1,2 dan 3', '1,3 dan 5', '2,3 dan 4', '2,3 dan 5', '2,4 dan 6', NULL, NULL, NULL, NULL, NULL, 'e', 1764370007, 1764370258, 1, '', 1, 0, 0, '72173a39-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
