INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31840, 848, 0, 1, 16, NULL, NULL, NULL, 'Kalimat dalam teks prosedur tidak membingungkan dan mudah diikuti berarti kalimat tersebut ….', 'logis', 'jelas', 'baku', '&nbsp;singkat', 'ejektif', NULL, NULL, NULL, NULL, NULL, 'a', 1764376138, 1764376205, 1, '', 1, 0, 0, '72174c7a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31841, 816, 0, 3, 1, NULL, NULL, NULL, '<p>Bilangan kuantum (n, l, m, s) digunakan untuk menggambarkan posisi dan sifat elektron dalam atom. Larangan Pauli menyatakan dua elektron dalam atom tidak dapat memiliki empat bilangan kuantum yang sama. Prinsip Hund menyebutkan bahwa elektron mengisi orbital yang setara energi secara tunggal terlebih dahulu sebelum berpasangan. Prinsip Aufbau menjelaskan elektron mengisi orbital dari energi paling rendah menuju energi lebih tinggi. Model mekanika kuantum Schr&ouml;dinger memandang elektron sebagai gelombang dan keberadaannya dinyatakan dalam bentuk probabilitas, bukan lintasan pasti.</p><p>Bilangan kuantum (n, l, m, s) digunakan untuk menggambarkan posisi dan sifat elektron dalam atom.</p><p>Larangan Pauli menyatakan dua elektron dalam atom tidak dapat memiliki empat bilangan kuantum yang sama.</p><p>Prinsip Hund menyebutkan bahwa elektron mengisi orbital yang setara energi secara tunggal terlebih dahulu sebelum berpasangan.</p><p>Prinsip Aufbau menjelaskan elektron mengisi orbital dari energi paling rendah menuju energi lebih tinggi.Model mekanika kuantum Schr&ouml;dinger memandang elektron sebagai gelombang dan keberadaannya dinyatakan dalam bentuk probabilitas, bukan lintasan pasti.</p><p>Pasangkan pernyataan yang sesuai untuk pasangan yang tepat.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>&nbsp;Prinsip Aufbau<br><\\/p><\\/body><\\/html>\",\"<p>Prinsip Hund<\\/p><\\/body><\\/html>\",\"<p>Larangan Pauli<\\/p><\\/body><\\/html>\",\"<p>Bilangan kuantum l dan bentuk orbital<\\/p><\\/body><\\/html>\",\"<p>Model mekanika kuantum Schr&ouml;dinger<\\/p><\\/body><\\/html>\"],[\"<li data-start=\\\"1854\\\" data-end=\\\"1996\\\"><p data-start=\\\"1857\\\" data-end=\\\"1996\\\">Menjelaskan bahwa dua elektron dalam satu orbital harus memiliki spin berlawanan karena tidak boleh memiliki identitas kuantum yang sama.<\\/p><\\/li><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<li data-start=\\\"479\\\" data-end=\\\"569\\\"><p data-start=\\\"482\\\" data-end=\\\"569\\\">Menentukan bentuk orbital elektron dalam atom berdasarkan nilai bilangan kuantum azimut (l).<\\/p><\\/li><p><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Menjelaskan fenomena pengisian elektron pada unsur nitrogen yang mengisi orbital 2p secara tunggal sebelum berpasangan.<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Menganalisis perilaku elektron yang keberadaannya hanya dapat diprediksi melalui peluang, bukan lintasan pasti.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>Menentukan konfigurasi elektron stabil pada ion S&sup2;&#8315; yang mengikuti aturan pengisian energi dari orbital terendah.<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"]]}', 1764376267, 1765350674, 1, '', 1, 0, 0, '72174d4d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31842, 856, 0, 2, 3, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Titik&nbsp;<img src=\"uploads/bank_soal/file_20251129083223.png\" style=\"width: 62px;\">diputar<img src=\"uploads/bank_soal/file_20251129083235.png\" style=\"width: 32px;\">&nbsp;&nbsp;terhadap titik asal, lalu dimasukkan ke fungsi transformasi<img src=\"uploads/bank_soal/file_20251129083246.png\" style=\"width: 180px;\"><span style=\"text-indent: -18pt;\">Koordinat akhir yang mungkinbenar adalah&hellip;</span></p><p class=\"MsoListParagraph\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;margin-left:54.0pt;mso-add-space:auto;text-indent:-18.0pt;line-height:normal;mso-list:l0 level1 lfo1\"><span style=\'font-size:11.0pt;font-family:\"Segoe UI Emoji\",sans-serif;mso-fareast-font-family:\"Times New Roman\";mso-bidi-font-family:\"Times New Roman\";mso-font-kerning:0pt;mso-ligatures:none;mso-fareast-language:EN-ID\'><p></p></span></p></body></html>', '{\"a\":\"<p><img src=\\\"uploads\\/bank_soal\\/img_85623_5c2fdd2fe9d789ccdd56.png\\\" style=\\\"width: 60px;\\\" data-filename=\\\"image.png\\\"><br><\\/p><\\/body><\\/html>\",\"b\":\"<p><img src=\\\"uploads\\/bank_soal\\/img_85623_f2f76c8936d402304762.png\\\" style=\\\"width: 49px;\\\" data-filename=\\\"image.png\\\"><br><\\/p><\\/body><\\/html>\",\"c\":\"<p><img src=\\\"uploads\\/bank_soal\\/img_85623_b50f530e1947c49da1ce.png\\\" style=\\\"width: 54px;\\\" data-filename=\\\"image.png\\\"><br><\\/p><\\/body><\\/html>\",\"d\":\"<p><img src=\\\"uploads\\/bank_soal\\/img_85623_c50874ad01c5725a117d.png\\\" style=\\\"width: 56px;\\\" data-filename=\\\"image.png\\\"><br><\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"d\",null]', 1764376298, 1765262551, 1, '', 1, 0, 0, '72174f5b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31843, 824, 0, 3, 1, NULL, NULL, NULL, '<p>Servis dalam bola voli adalah pukulan atau penyajian bola pertama yang menandai dimulainya sebuah pertandingan atau reli, dilakukan dari area belakang garis permainan, melintasi net ke area lawan. Tujuan utama servis tidak hanya untuk memulai permainan, tetapi juga sebagai kesempatan pertama untuk melancarkan serangan ke daerah lawan, mencuri poin, dan mengatur ritme pertandingan.</p><p><br><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206173432.jpg\" style=\"width: 250px;\"></p><p>Dalam permainan bola voli servis yang kamu ketahui di bagi menjadi berapa teknik, tentukanlah benar dan salah di bawah ini.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"<p>servis atas<\\/p><\\/body><\\/html>\",\"<p>servis point<\\/p><\\/body><\\/html>\",\"<p>servis berpasangan<\\/p><\\/body><\\/html>\",\"<p>servis bawah<\\/p><\\/body><\\/html>\",\"<p>servis reli point<\\/p><\\/body><\\/html>\"],[\"<p>Benar<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Salah<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"1\",\"0\",\"1\"]]}', 1764376301, 1765013676, 1, '', 1, 0, 0, '72175059-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31844, 824, 0, 3, 2, NULL, NULL, NULL, '<p>Dalam permainan sepak bola dibutuhkan teknik ketrampilan dasar yang kuat. Teknik dasar dalam permainan sepak bola menggunakan bola di antaranya mengumpan bola<b><i> (passing)</i></b>, menendang <b><i>(shooting)</i></b> menahan dan menghentikan bola<b><i> (control dan stop)</i></b>, menyundul bola <b><i>(heading)</i></b>, menggiring bola<b><i> (dribbling).</i></b></p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206173612.jpg\" style=\"width: 205.5px; height: 259.766px;\"><br></p><p>Sesuai lima teknik permainan sepak bola di atas. Siswa diharapkan menentukan 5 teknik permainan sesuai pengertian masing-masing.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"kemampuan untuk mengendalikan bola saat bergerak untuk melewati lawan atau menavigasi lapangan.\",\"Tindakan memindahkan bola kepada rekan satu tim yang bertujuan untuk menjaga penguasaan bola dan memungkinkan permainan bergerak maju. Teknik ini merupakan salah satu dasar penting dalam permainan sepak bola dan dapat dilakukan dengan berbagai cara, seperti umpan pendek (mendatar) untuk jarak dekat dan umpan lambung untuk jarak jauh. \",\"gerakan dasar yang dominan dengan menggunakan kaki untuk memberikan dorongan pada bola agar bergerak sesuai arah yang diinginkan. Gerakan ini mendasar untuk berbagai teknik, seperti mengoper bola (passing), menembak ke gawang (shooting), dan menggiring bola (dribbling).\",\"bertujuan untuk mengendalikan bola yang datang agar tidak keluar dari penguasaan pemain untuk kemudian dapat dioper, digiring, atau ditendang.\",\"Teknik ini bisa dilakukan sambil berdiri, melompat, atau bahkan menunduk, dan membutuhkan koordinasi antara gerakan tubuh, leher, dan mata yang harus terbuka agar bola dapat diarahkan ke sasaran yang dituju. \"],[\"<p>Menggiring Bola<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Mengumpan bola<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Menendang bola<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Menghentikan bola<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Menyundul bola<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"]]}', 1764376302, 1765013792, 1, '', 1, 0, 0, '721751c0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31845, 824, 0, 3, 3, NULL, NULL, NULL, '<p>Mengumpan adalah teknik memindahkan bola kepada rekan setim dengan menendang, sedangkan menendang adalah tindakan memindahkan bola menggunakan kaki atau bagian kaki, yang bisa termasuk mengumpan atau menembak ke gawang lawan. Dalam konteks sepak bola, mengumpan <b><i>(passing)</i></b> fokus pada kerja sama tim, sedangkan kicking (kicking) adalah istilah yang lebih umum untuk setiap aksi memindahkan bola dengan kaki, termasuk saat menembak<b><i> (shooting)</i></b>.</p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206173744.jpg\" style=\"width: 389px;\"><br></p><p>Dari penjelasan kedua ketrampilan di atas, ketrampilan mengumpan dan menendang memiliki cara pelaksanaan masing-masing. </p><p>Di bawah ini ada teknik pelaksanaan dari kedua ketrampilan tersebut, tentukan sesuai ketrampilan tersebut.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"<p>Kaki bagian dalam<\\/p><\\/body><\\/html>\",\"<p>kaki bagian luar<\\/p><\\/body><\\/html>\",\"<p>punggung kaki<\\/p><\\/body><\\/html>\"],[\"<p>ketrampilan mengumpan<\\/p><\\/body><\\/html>\",\"1\",\"1\",\"1\"],[\"<p>ketrampilan menendang<\\/p><p><\\/p><\\/body><\\/html>\",\"1\",\"1\",\"1\"]]}', 1764376303, 1765013996, 1, '', 1, 0, 0, '7217532f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31846, 824, 0, 3, 4, NULL, NULL, NULL, '<p>Keterampilan smash<b><i> (spike) </i></b>bola voli adalah teknik serangan dengan cara memukul bola secara keras dan cepat ke area lawan melalui lompatan, dengan tujuan agar bola sulit dikembalikan dan menghasilkan poin. Teknik ini melibatkan serangkaian gerakan mulai dari awal, guncangan, pukulan di udara, hingga pendaratan, serta membutuhkan kekuatan, akurasi, dan koordinasi yang baik.</p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206173922.jpg\" style=\"width: 394px;\"><br></p><p>Sesuai penjelasan di atas ketrampilan smash dapat dilakukan dengan empat cara, tentukan di bawah ini manakah yang <b>benar</b> dan <b>salah</b> dalam melakukan ketrampilan smash.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"<p>open smash<\\/p><\\/body><\\/html>\",\"<p>smash cepat<\\/p><\\/body><\\/html>\",\"<p>qiuck smash<\\/p><\\/body><\\/html>\",\"<p>black smash<\\/p><\\/body><\\/html>\",\"<p>back smash<\\/p><\\/body><\\/html>\"],[\"<p>Benar<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"1\",\"0\",\"1\"],[\"<p>Salah<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"1\",\"0\"]]}', 1764376304, 1765013966, 1, '', 1, 0, 0, '7217540f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31847, 824, 0, 3, 5, NULL, NULL, NULL, '<p>Keterampilan dasar bola voli mencakup servis , passing (forearm dan overhand), smash (smash), blocking (menahan serangan lawan), digging (menyelamatkan bola dari serangan), dan setting (mengatur serangan). Menguasai keterampilan-keterampilan ini, ditambah dengan positioning dan rotasi yang benar, akan meningkatkan kualitas permainan individu maupun tim.</p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206174044.jpg\" style=\"width: 240px;\"><br></p><p>Dari penjelasan di atas tentukan pengertian ketrampilan di bawah ini manakah yang termasuk dalam pengertian servis dan passing.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"pukulan awal yang dilakukan untuk memulai permainan atau reli. Layanan ini merupakan serangan pertama yang diarahkan ke daerah lawan untuk memulai permainan.\",\"teknik dasar dalam olahraga bola voli untuk mengoper bola ke rekan satu tim sebagai langkah awal menyusun pola serangan atau bertahan.\"],[\"<p>servis<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>passing<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\"]]}', 1764376305, 1765014059, 1, '', 1, 0, 0, '72175575-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
