INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31865, 816, 0, 3, 3, NULL, NULL, NULL, 'Untuk membuat konfigurasi elektron, langkah pertama yang harus dipahami adalah unsur itu sendiri, terutama nomor atom (Z), jumlah elektronnya, serta posisi unsur dalam tabel periodik. Dengan mengetahui Nomor atom Muatan ion (jika ada) Letak pada tabel periodik Jenis subkulit yang boleh diisi Maka penyusunan konfigurasi elektron. Nomor atom Maka penyusunan konfigurasi elektron  menjadi mudah dan akurat. Cocok kanlah unsur dari  hasil Konfigurasi Elektron ...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>&nbsp;Cl<br><\\/p><\\/body><\\/html>\",\"<p>Mg<\\/p><\\/body><\\/html>\",\"<p>F<\\/p><\\/body><\\/html>\",\"<p>Na<\\/p><\\/body><\\/html>\",\"<p>He<\\/p><\\/body><\\/html>\"],[\"<li data-start=\\\"1112\\\" data-end=\\\"1129\\\"><p data-start=\\\"1115\\\" data-end=\\\"1129\\\">1s&sup2; &rarr; unsur<span style=\\\"font-size: 0.875rem;\\\">.<\\/span><\\/p><\\/li><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"0\",\"1\"],[\"<p>1s&sup2; 2s&sup2; 2p&#8309; &rarr; unsur<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\",\"0\",\"0\"],[\"<p>Unsur golongan IA periode 3.<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"0\",\"1\",\"0\"],[\"<p>Unsur golongan VIIA periode 3.<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Unsur golongan IIA periode 2.<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"]]}', 1764377831, 1765350728, 1, '', 1, 0, 0, '72176723-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85