INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31866, 849, 0, 1, 1, NULL, NULL, NULL, 'Pada bulan Desember 1949, semua tentara Belanda ditarik, dan masuklah tentara Indonesia dari sekian banyak markas daruratnya, kebanyakan di daerah Gunung Muria. \r\nGito mendengar, penarikan tentara Belanda adalah hasil Konferensi Meja Bundar di Belanda, antara wakil Indonesia dan wakil Belanda. \r\nPasukan Belanda harus meninggalkan Indonesia, kecuali Irian Barat (sekarang Papua).\r\nPenggalan cerita tersebut menggambarkan latar...', 'Waktu', 'Tempat', 'Suasana', 'Sosial', 'Sejarah', NULL, NULL, NULL, NULL, NULL, 'a', 1764378121, 1764905422, 1, '', 1, 0, 0, '72176884-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31867, 816, 0, 3, 4, NULL, NULL, NULL, '<p data-start=\"2928\" data-end=\"3029\">Letak unsur dalam SPU sangat dipengaruhi oleh <span data-start=\"2974\" data-end=\"3001\" style=\"\">konfigurasi elektronnya</span>, terutama elektron valensi.&nbsp;<span style=\"font-size: 0.875rem;\">Golongan A ditentukan oleh </span><span data-start=\"3060\" data-end=\"3087\" style=\"font-size: 0.875rem;\">jumlah elektron valensi dan&nbsp;</span><span style=\"font-size: 0.875rem;\">Periode ditentukan oleh </span><span data-start=\"3117\" data-end=\"3142\" style=\"font-size: 0.875rem;\">jumlah kulit elektron</span><span style=\"font-size: 0.875rem;\">.&nbsp;</span><span style=\"font-size: 0.875rem;\">Unsur adalah dasar penyusunan tabel periodik dan seluruh ilmu kimia. Dalam sistem periodik, unsur diatur berdasarkan nomor atom, sifat kimia, dan konfigurasi elektron sehingga menghasilkan pola sifat tertentu. Pemahaman tentang unsur sangat penting untuk menganalisis reaksi kimia, pembentukan ion, ikatan kimia, hingga sifat-sifat periodiknya.&nbsp;</span><span style=\"font-size: 0.875rem;\">Tariklah garis untuk pasangan yang tepat.</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:6:{i:0;s:9:\"<p>#</p>\n\";i:1;s:19:\"<p>&nbsp;Ar<br></p>\";i:2;s:8:\"<p>F</p>\";i:3;s:9:\"<p>Cl</p>\";i:4;s:15:\"<p>&nbsp;Na</p>\";i:5;s:9:\"<p>Fr</p>\";}i:1;a:6:{i:0;s:113:\"<li data-start=\"1410\" data-end=\"1443\"><p data-start=\"1413\" data-end=\"1443\">Unsur paling elektronegatif.</p></li>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:2;a:6:{i:0;s:48:\"<p>Unsur paling reaktif golongan IA.</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";}i:3;a:6:{i:0;s:56:\"<p>Unsur paling besar jari-jarinya dalam periode 3.</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";}i:4;a:6:{i:0;s:47:\"<p>Unsur dengan energi ionisasi tertinggi.</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:5;a:6:{i:0;s:27:\"<p>Unsur paling stabil</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}}}', 1764378576, 1764922359, 1, '', 1, 0, 0, '72176a37-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31868, 849, 0, 1, 2, NULL, NULL, NULL, '<p>Cara pengarang menggunakan bahasa yang tepat sehingga bisa menampilkan suasana, seperti sedih, gembira, menyeramkan, romantis, atau suasana penuh sindiran. </p><p>\r\nPenggunaan bahasa yang tepat akan membuat penggambaran suasana yang mendukung jalan cerita disebut...</p>', 'Majas', 'Gaya bahasa', 'Diksi', 'Sudut pandang', 'Penokohan', NULL, NULL, NULL, NULL, NULL, 'b', 1764379136, 1764379355, 1, '', 1, 0, 0, '72176c20-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31869, 816, 0, 3, 5, NULL, NULL, NULL, '<p>Ion adalah atom atau kelompok atom (gugus) yang bermuatan listrik karena kehilangan atau menerima elektron. Senyawa kovalen adalah senyawa yang terbentuk ketika dua atom saling berbagi pasangan elektron. Jenis ikatan kovalen ini terjadi pada atom-atom nonlogam yang memiliki kecenderungan menarik elektron, sehingga tidak mau melepas elektron seperti logam. Ketika dua atom nonlogam mendekat, mereka membutuhkan elektron untuk memenuhi oktet. Mereka lalu berbagi elektron, dan pasangan elektron bersama itu dihitung sebagai milik keduanya. </p><p>Cocokkan pernyataan dari sifat senyawa ion dan kovalen untuk pasangan yang tepat.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>Kovalen<br><\\/p><\\/body><\\/html>\",\"<p>Ion<\\/p><\\/body><\\/html>\",\"<p>Sebagian ion<\\/p><\\/body><\\/html>\",\"<p>&nbsp;Garam<br><\\/p><\\/body><\\/html>\",\"<p>Logam<\\/p><\\/body><\\/html>\"],[\"<li data-start=\\\"5034\\\" data-end=\\\"5057\\\"><p data-start=\\\"5037\\\" data-end=\\\"5057\\\">Titik didih tinggi<\\/p><\\/li><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Tidak menghantarkan listrik dalam keadaan padat<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Mudah menguap<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"],[\"<p>Bersifat rapuh<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\",\"0\",\"0\"],[\"<p>Larut baik dalam pelarut organik<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\",\"0\",\"0\"]]}', 1764379205,