INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31888, 837, 0, 2, 2, NULL, NULL, NULL, '<p>Bola basket adalaholahraga tim yang dimainkan oleh dua tim yang masing-masing beranggotakan lima orang. Tujuannya adalah mencetak poin dengan memasukkan bola ke keranjang lawan dan mencegah tim lawan mencetak poin ke keranjang sendiri. </p><p>Permainan ini melibatkan teknik-teknik dasar seperti ...</p></body></html>', '{\"a\":\"<p>mengiring<\\/p><\\/body><\\/html>\",\"b\":\"<p>mengoper<\\/p><\\/body><\\/html>\",\"c\":\"<p>melempar<\\/p><\\/body><\\/html>\",\"d\":\"<p>menyundul<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"b\",\"c\",null]', 1764381073, 1765015956, 1, '', 1, 0, 0, '72178044-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31889, 837, 0, 2, 3, NULL, NULL, NULL, '<p>Bola voli adalah olahraga tim yang dimainkan oleh dua regu yang saling berhadapan di lapangan yang dipisahkan oleh net. Tujuan utama permainan ini adalah memukul bola melewati net agar jatuh di area lawan, sekaligus mencegah bola jatuh di area sendiri. Setiap tim terdiri dari enam pemain.</p><p>Untuk memainkan bola voli, diperlukan penguasaan beberapa teknik dasar seperti ...</p></body></html>', '{\"a\":\"<p>servis<\\/p><\\/body><\\/html>\",\"b\":\"<p>menahan<\\/p><\\/body><\\/html>\",\"c\":\"<p>smash<\\/p><\\/body><\\/html>\",\"d\":\"<p>menahan<\\/p><\\/body><\\/html>\",\"e\":\"<p>passing<\\/p><\\/body><\\/html>\",\"f\":\"<p>block<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"c\",\"e\",\"f\",null]', 1764381074, 1765016009, 1, '', 1, 0, 0, '721781e5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31890, 837, 0, 2, 4, NULL, NULL, NULL, 'Tujuan menggunakan perlengkapan dalam sepak bola adalah untuk melindungi pemain dari cedera, meningkatkan performa dan kenyamanan di lapangan, serta mengidentifikasi waktu antar pemain. Perlengkapan yang dibutuhkan seorang pemain sepak bola adalah ...', '{\"a\":\"<p>kostum<\\/p><\\/body><\\/html>\",\"b\":\"<p>sepatu<\\/p><\\/body><\\/html>\",\"c\":\"<p>kaus kaki<\\/p><\\/body><\\/html>\",\"d\":\"<p>kaca mata<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"c\",null]', 1764381075, 1765016040, 1, '', 1, 0, 0, '721782c9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31891, 837, 0, 2, 5, NULL, NULL, NULL, '<p>Bola voli adalah olahraga tim yang dimainkan oleh dua regu yang saling berhadapan di lapangan yang dipisahkan oleh net. Tujuan utama permainan ini adalah memukul bola melewati net agar jatuh di area lawan, sekaligus mencegah bola jatuh di area sendiri. Setiap tim terdiri dari enam pemain, meskipun ada variasi seperti voli pantai yang hanya memiliki dua pemain per tim. </p><p>Untuk memainkan bola voli, diperlukan penguasaan beberapa teknik dasar seperti ...</p></body></html>', '{\"a\":\"<p>passing<\\/p><\\/body><\\/html>\",\"b\":\"<p>servis&nbsp;<\\/p><\\/body><\\/html>\",\"c\":\"<p>smash<\\/p><\\/body><\\/html>\",\"d\":\"<p>reli point<\\/p><\\/body><\\/html>\",\"e\":\"<p>game point<\\/p><\\/body><\\/html>\",\"f\":\"<p>block<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"c\",\"f\",null]', 1764381077, 1765016066, 1, '', 1, 0, 0, '7217850d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31892, 849, 0, 1, 16, NULL, NULL, NULL, '<p><b>Perhatikanlah kutipan puisi berikut dengan saksama!</b></p><p>\r\nMENYESAL Pagiku hilang sudah melayang\r\n</p><p>\r\nHari mudaku sudah pergi\r\n</p><p>\r\nSekarang petang datang membayang\r\n</p><p>\r\nBatang usiaku sudah tinggi\r\n</p><p>\r\nAku lalai di hari pagi\r\n</p><p>\r\nBeta lengah di masa muda\r\n\r\nKini hidup meracun hati\r\n</p><p>\r\nMiskin ilmu, miskin harta\r\n\r\n…. </p><p>\r\n\r\nMaksud bait kedua puisi tersebut adalah ….</p>', 'Seseorang yang lengah di pagi hari sehingga hidupnya sangat menderita di usia muda', 'Seseorang yang menderita hidupnya karena tidak punya ilmu dan harta', 'Seseorang yang miskin harta dan miskin ilmu pada masa muda karena ia lupa waktu', 'Seseorang yang telah menyia-nyiakan masa mudanya dalam menuntut ilmu sehingga hidup menderita di hari tua', 'Seseorang yang melalaikan waktu di masa muda karena dia tidak memiliki ilmu dan harta', NULL, NULL, NULL, NULL, NULL, 'd', 1764381083, 1764381308, 1, '', 1, 0, 0, '721785ef-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
