INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31897, 849, 0, 1, 18, NULL, NULL, NULL, '<p><b>Bacalah paragraf berikut dengan saksama!</b>\r\n</p><p>\r\nKendati tetap mempertahankan diri mereka dengan lirik-lirik yang puitis, album yang digarap sejak Februari itu memang berbeda dengan album Padi sebelumnya yang penuh dinamika. \r\nLagu “Seandainya Bisa Memilih” dan “Semua Tak Sama” misalnya, sangat membantu kemampuan vocal Fadly dalam menyesuaikan tempo musik yang berubah-ubah. \r\nNuansa harpa dari Maya Hassan serta paduan suara Ingimto Trisakti Choir turut memperkaya kesan orkestra musik mereka. \r\nOleh karena itu….\r\n</p><p>Simpulan yang tepat untuk melengkapi kalimat terakhir paragraf tersebut adalah ….</p>', 'Musik padi kali ini sangat terkenal dan digemari orang', 'Musik Padi kali ini terdengar makin progresif dengan nuansa yang lebih variatif', 'Musik Padi masih tetap mempertahankan lirik-lirik lagu yang puitis', 'Musik Padi masih tetap mempertahankan lirik-lirik lagu yang puitis', 'Dua lagu musik Padi sangat membantu kemampuan vocal Fadly e. Nuansa harpa serta paduan suara Ingimto memperkaya kesan orkestra musickPadi', NULL, NULL, NULL, NULL, NULL, 'b', 1764381554, 1764381845, 1, '', 1, 0, 0, '72178ae5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
