INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31916, 849, 0, 1, 26, NULL, NULL, NULL, '<p><b>Bacalah paragraf sebab-akibat berikut!</b>\r\n</p><p>Antara bekerja dan kesehatan manusia saling berhubungan bahkan saling berpengaruh. \r\nHal ini terbukti, misalnya dari kenyataan bahwa seseorang menjadi lebih sehat apabila ia bekerja daripada tidak bekerja.\r\nAtau kenyataan yang lain sebaliknya, yaitu seseorang yang bekerja malah menjadi sakit karena kondisi pekerjaannya tidak sesuai dengan karakteristik orang itu.\r\n</p><p>Kalimat yang tepat untuk melengkapi paragraf sebab-akibat di atas adalah ….&nbsp;</p>', 'Oleh karena itu, dalam memilih pekerjaan harus sesuai dengan karakter dan kemampuan yang dimiiki', 'Hal itu akan menjadi jika bekerja tidak sesuai dengan imbalan atau upah yang diharapkan', 'Memang, setiap orang berhak memiliki karakter dan kemampuan yang berbeda-beda dalam memilih pekerjaan', 'Jadi pekerjaan yang tidak sesuai dengan karakter yang dimiliki akan menimbulkan berbagai dampak', 'Tentu saja setiap orang mengharapkan agar dengan bekerja ia bisa hidup sehat', NULL, NULL, NULL, NULL, NULL, 'd', 1764383596, 1764383726, 1, '', 1, 0, 0, '72179fdb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
