INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31922, 817, 0, 4, 2, NULL, NULL, NULL, 'Menurut teori Brønsted–Lowry, basa adalah zat yang dapat menerima ---&nbsp;', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Proton (H⁺)', 1764384231, 1764384295, 1, '', 1, 0, 0, '7217a742-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31923, 849, 0, 1, 29, NULL, NULL, NULL, 'Yang bukan merupakan contoh kalimat fakta adalah...', 'Salah satu daerah penghasil beras terbesar di Pulau Jawa adalah Jawa Barat', 'Sekitar 70 persen penduduk Indonesia mengkonsumsi beras sebagai sumber makanan pokok', 'Sagu dikonsumsi oleh masyarakat di wilayah Papua dan sebagian Maluku', 'Budaya di Sunda sepertinya sudah mulai dilupakan masyarakat', 'Menurut data Badan Pusat Statistik (BPS), tingkat pengangguran terbuka pada Agustus 2022 adalah sebesar 5,86 persen', NULL, NULL, NULL, NULL, NULL, 'd', 1764384234, 1764384377, 1, '', 1, 0, 0, '7217a824-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31924, 837, 0, 3, 1, NULL, NULL, NULL, '<p>Keterampilan dasar permainan bola besar meliputi mengoper <b><i>(passing)</i></b>, menendang <b><i>(shooting)</i></b>, menggiring bola, mengontrol/menghentikan bola, menyyundul <b><i>(heading)</i></b>, dan bertahan<b><i> (tackling atau Blocking)</i></b>. Keterampilan ini bervariasi tergantung pada permainannya, seperti menembak dan menyundul di sepak bola, atau smash dan block di bola voli. </p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206181608.jpg\" style=\"width: 25%;\"><br></p><p>Dari penjelasan pengertian bola besar di atas tentukan para penemu permainan bola besar di bawah ini sesuai cabang olah raga.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"Ebenezer Cobb Morley\",\" William G. Morgan\",\"Dr. James Naismith \"],[\"<p>Sepak bola<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\"],[\"<p>Bola voli<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\"],[\"<p>Bola basket<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\"]]}', 1764384251, 1765016175, 1, '', 1, 0, 0, '7217a9cb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31925, 837, 0, 3, 2, NULL, NULL, NULL, '<p>Motto olahraga ada banyak, baik yang bersifat global seperti motto Olimpiade<b> \"Citius, Altius, Fortius &ndash; Communiter\"</b> (Lebih Cepat, Lebih Tinggi, Lebih Kuat &ndash; Bersama), maupun yang lebih umum seperti <b>\"Mens sana in corpore sano\"</b> (Di dalam tubuh yang sehat, terdapat jiwa yang kuat). Motto olahraga juga bisa berupa kalimat motivasi, seperti \"Latihan keras, hasil gemilang\" atau \"Kalah bukanlah akhir dari segalanya, tetapi sebuah kesempatan untuk bangkit lagi\". </p><p>motto olahraga di atas menunjukan bahwa olahraga sudah dikenal sebelum masehi. Dari penjelasan tersebut olahraga permainan bola besar yaitu : sepak bola, bola voli dan bolah basket pertama kali di temukan pada tahun.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"<p>tahun 1891<\\/p><\\/body><\\/html>\",\"<p>tahun 1863<\\/p><\\/body><\\/html>\",\"<p>tahun 1895<\\/p><\\/body><\\/html>\"],[\"<p>sepak bola<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\"],[\"<p>bola voli<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\"],[\"<p>bola basket<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\"]]}', 1764384253, 1765016218, 1, '', 1, 0, 0, '7217ab76-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31926, 846, 0, 1, 18, NULL, NULL, NULL, '<p>Aktivitas banyak orang di stasiun kereta api lebih tepat masuk kategori kerumunan karena.....</p>', 'jumlah anggotanya relatif besar', '&nbsp;tidak memiliki kesamaan tujuan', '&nbsp;keberadaannya bersifat sementara', 'tidak memiliki nilai dan norma sosial', 'terbentuk karena pengaruh dari luar', NULL, NULL, NULL, NULL, NULL, 'c', 1764384255, 1764384647, 1, '', 1, 0, 0, '7217ad20-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31927, 837, 0, 3, 3, NULL, NULL, NULL, '<p>Ukuran lapangan bola besar berfungsi untuk memastikan keadilan kompetisi , mempengaruhi strategi dan taktik permainan , serta menjamin konsistensi kinerja pemain karena mereka bermain di lingkungan yang standar di mana pun. Ukuran yang ditetapkan juga memfasilitasi pembangunan dan standarisasi fasilitas di seluruh dunia, memastikan keseragaman dalam pertandingan internasional maupun lokal . </p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206181840.jpg\" style=\"width: 25%;\"><br></p><p>Dari penjelasan di atas setiap permainan bola besar mempunyai ukuran masing-masing, oleh karena itu siswa dapat menentukan ukuran setiap permainan bola besar di bawah ini sesuai cabang olahraganya.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"Panjang: 100-110 meterLebar: 64-75 meter\",\"Panjang: 18 meterLebar: 9 meter\",\"panjang 28,5 meter x lebar 15 meter\"],[\"<p>sepak bola<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\"],[\"<p>bola voli<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\"],[\"<p>bola basket<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\"]]}', 1764384256, 1765016341, 1, '', 1, 0, 0, '7217aed1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31928, 837, 0, 3, 4, NULL, NULL, NULL, '<p>Tujuan sportivitas dalam olahraga bola besar adalah untuk menumbuhkan sikap saling menghormati, adil, dan jujur &#8203;&#8203;di antara pemain, pelatih, dan penonton. Selain itu, sportivitas juga bertujuan untuk melatih penerimaan kekalahan atau kemenangan secara lapang dada, membangun karakter yang positif, dan menciptakan lingkungan pertandingan yang sehat dan menyenangkan. </p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206182004.jpg\" style=\"width: 25%;\"><br></p><p>Dari penjelasan di atas menunjukan bahwa setiap cabang olahraga menjunjung tinggi nilai sportivitas dalam permainan. Setiap cabang olahraga bola besar dibentuk dengan aturan-aturan yang mengikat sehingga dapat terlaksana setiap pertandingan. Cabang olahraga bola besar yaitu: Sepak bola, bola voli dan bola basket pertama kali ditemukan dinegara.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"Amerika Serikat\",\"Inggris\",\"<p>Argentina<\\/p><\\/body><\\/html>\"],[\"<p>Sepak bola<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\"],[\"<p>bola voli<\\/p><p><\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\"],[\"<p>bola basket<\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\"]]}', 1764384258, 1765016409, 1, '', 1, 0, 0, '7217b2f4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31929, 837, 0, 3, 5, NULL, NULL, NULL, '<p>Tujuan organisasi olahraga meliputi peningkatan prestasi olahraga nasional dan internasional, pembinaan atlet, peningkatan kesehatan dan kebugaran masyarakat, serta pembentukan karakter dan nilai-nilai positif seperti kerja sama, disiplin, dan sportivitas. Organisasi olahraga juga berperan dalam mempromosikan olahraga di seluruh lapisan masyarakat dan melestarikan kekayaan budaya olahraga tradisional. </p><p><img src=\"http://192.168.10.6/uploads/bank_soal/file_20251206182108.jpg\" style=\"width: 25%;\"><br></p><p>Dari penjelasan di atas tentukan nama organisasi internasional setiap cabang olahraga bola besar.</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"2\",\"jawaban\":[[\"#\",\"FIVB\",\"FIFA\",\"FIBA\"],[\"<p>sepak bola<\\/p><\\/body><\\/html>\",\"0\",\"1\",\"0\"],[\"<p>bola voli<\\/p><p><\\/p><\\/body><\\/html>\",\"1\",\"0\",\"0\"],[\"<p>bola basket<\\/p><\\/body><\\/html>\",\"0\",\"0\",\"1\"]]}', 1764384259, 1765016472, 1, '', 1, 0, 0, '7217b401-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
