INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31932, 849, 0, 1, 30, NULL, NULL, NULL, 'Yang bukan merupakan contoh kalimat opini adalah....', 'Apabila dikembangkan dengan baik, sagu dapat menggantikan beras sebagai makanan pokok di Indonesia', 'Sebagian warga negara Jepang mulai menyukai ubi ungu sebagai makanan pokok pengganti nasi', 'Jika memungkinkan, dalam waktu dekat Indonesia bisa mengekspor umbi ke beberapa negara di Eropa', 'Pemanfaatan posyandu bisa menjadi cara paling utama dalam mencegah stunting', 'Tingkat konsumsi buah lokal masyarakat Indonesia belum mencapai 40 kg per kapita setiap tahun', NULL, NULL, NULL, NULL, NULL, 'e', 1764384380, 1764384557, 1, '', 1, 0, 0, '7217b6a2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
