INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31934, 817, 0, 5, 1, NULL, NULL, NULL, 'Jelaskan perbedaan konsep asam menurut Arrhenius, Brønsted–Lowry, dan Lewis.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<li data-start=\"326\" data-end=\"403\"><p data-start=\"328\" data-end=\"403\"><strong data-start=\"328\" data-end=\"342\">Arrhenius:</strong> Asam menghasilkan ion H⁺ dalam air; basa menghasilkan OH⁻.</p>\r\n</li>\r\n<li data-start=\"404\" data-end=\"489\">\r\n<p data-start=\"406\" data-end=\"489\"><strong data-start=\"406\" data-end=\"425\">Brønsted–Lowry:</strong> Asam sebagai donor proton (H⁺), basa sebagai penerima proton.</p>\r\n</li>\r\n<li data-start=\"490\" data-end=\"583\">\r\n<p data-start=\"492\" data-end=\"583\"><strong data-start=\"492\" data-end=\"502\">Lewis:</strong> Asam sebagai penerima pasangan elektron, basa sebagai donor pasangan elektron.</p></li>', 1764384560, 1764384733, 1, '', 1, 0, 0, '7217b88f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31935, 846, 0, 1, 19, NULL, NULL, NULL, '<p>Dasar kategorisasi kelompok dalam (in-group) dan kelompok luar (out-group) ialah......</p>', 'besar kecilnya jumlah keanggotaan', 'identitas yang dimiliki antaranggota', 'kekuatan atau pengaruh yang diberikan', 'tingkat keeratan hubungan antaranggota', '&nbsp;pembagian kerja atau peran antaranggota', NULL, NULL, NULL, NULL, NULL, 'b', 1764384651, 1764384817, 1, '', 1, 0, 0, '7217ba41-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31936, 817, 0, 5, 2, NULL, NULL, NULL, 'Jelaskan mengapa NH₃ disebut basa lemah berdasarkan teori Brønsted–Lowry...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NH₃ hanya sebagian bereaksi dengan H₂O membentuk NH₄⁺ dan OH⁻, sehingga terionisasi sebagian → basa lemah.', 1764384737, 1764384813, 1, '', 1, 0, 0, '7217bb15-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31937, 817, 0, 5, 3, NULL, NULL, NULL, 'Hitung pH larutan dari&nbsp; NaOH 0,01 M...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[OH⁻] = 0,01 M → pOH = −log[OH⁻] = 2 → pH = 14 − 2 = 12', 1764384820, 1764384988, 1, '', 1, 0, 0, '7217bbe9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31938, 846, 0, 1, 20, NULL, NULL, NULL, '<p>Organisasi merupakan kelompok sekunder yang memiliki birokrasi mengikat. Badan Usaha Milik Desa (BUMDES) dapat dikategorikan sebagai organisasi karena terdapat.....</p>', 'nilai, norma, dan sistem kerja yang terstruktur.', 'Modal besar', 'kantor tempat berkumpul pegawai', 'tugas dan fungsi', 'Kantor tempat berkumpul pegawai', NULL, NULL, NULL, NULL, NULL, 'a', 1764384839, 1764385025, 1, '', 1, 0, 0, '7217bcb7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31939, 817, 0, 5, 4, NULL, NULL, NULL, 'Jelaskan mengapa larutan HCl bersifat asam kuat sedangkan CH₃COOH bersifat asam lemah.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<li data-start=\"2362\" data-end=\"2437\"><p data-start=\"2364\" data-end=\"2437\">HCl terionisasi sempurna → semua molekul HCl melepaskan H⁺ → asam kuat.</p>\r\n</li>\r\n<li data-start=\"2438\" data-end=\"2523\">\r\n<p data-start=\"2440\" data-end=\"2523\">CH₃COOH hanya terionisasi sebagian → sebagian molekul melepaskan H⁺ → asam lemah.</p></li>', 1764384997, 1764385094, 1, '', 1, 0, 0, '7217bd8d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31940, 846, 0, 1, 21, NULL, NULL, NULL, '<p>Penelitian dalam pemecahan masalah sosial dapat dilakukan melalui penelitian sosial yang terdiri atas langkah-langkah.....</p>', 'mendesain langkah, merumuskan tujuan, mengambil data, analisis, dan merumuskan rekomendasi', 'merumuskan tujuan, mendesain langkah, mengambil data, analisis, dan merumuskan rekomendasi', 'mendesain langkah, merumuskan tujuan, analisis, mengambil, data, dan merumuskan rekomendasi', 'merumuskan tujuan, analisis, mendesain langkah, mengambil, data, dan merumuskan rekomendasi', 'merumuskan tujuan, analisis, mengambil data, mendesain, langkah, dan merumuskan rekomendasi', NULL, NULL, NULL, NULL, NULL, 'b', 1764385046, 1764385160, 1, '', 1, 0, 0, '7217be65-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
