INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31954, 846, 0, 1, 29, NULL, NULL, NULL, '<p>Contoh adanya saling ketergantungan pasar dan produksi ekonomi di negara-negara yang berbeda pada era globalisasi adalah...</p>', 'Industrialisasi di negara maju menggunakan bahan mentah dan pangsa pasar dari negara yang sedang berkembang', 'Masuknya teknologi canggih ke negara dunia ketiga menghasilkan pengangguran di kawasan industri', 'Kerusakan lingkungan di negara sedang berkembang sebagai akibat eksploitasi besar-besaran pemilik modal', 'Kontrak bersama antara perusahaan asing dengan perusahaan nasional di bidang tenaga kerja', 'Berkurangnya bahan dasar industri pertanian sebagai akibat dari alih fungsi lahan pertanian ke bidang', NULL, NULL, NULL, NULL, NULL, 'a', 1764386588, 1764386760, 1, '', 1, 0, 0, '7217ce10-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31955, 846, 0, 1, 30, NULL, NULL, NULL, '<p>Pendidikan merupakan jembatan emas menuju masyarakat bermoral, artinya dalam menghadapi tantangan global, bangsa Indonesia harus...</p>', 'Mempunyai keahlian agar bisa bersaing dengan bangsa lain', 'Memiliki cita-cita hidup untuk bekal hidup di masa depan', 'Mempunyai kemampuan dan kebebasan berpikir secara rasional', 'Dapat mengembangkan sumber daya alam di wilayahnya', 'Berperilaku sesuai dengan nilai-nilai sosial dan kaidah-kaidah hukum', NULL, NULL, NULL, NULL, NULL, 'a', 1764386779, 1764386960, 1, '', 1, 0, 0, '7217ceed-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31956, 817, 0, 3, 1, NULL, NULL, NULL, '<p data-start=\"3258\" data-end=\"3320\">Sifat dan peran larutan dalam asam–basa sangat penting karena&nbsp;<span style=\"font-size: 0.875rem;\">Asam dan basa hanya menunjukkan sifatnya ketika berada dalam larutan,&nbsp;</span><span style=\"font-size: 0.875rem;\">Ionisasi/disosiasi terjadi di dalam pelarut,&nbsp;</span><span style=\"font-size: 0.875rem;\">pH hanya bisa ditentukan dalam larutan,&nbsp;</span><span style=\"font-size: 0.875rem;\">Reaksi asam–basa (netralisasi) terjadi dalam larutan,&nbsp;</span><span style=\"font-size: 0.875rem;\">Larutan menentukan kekuatan asam atau basa.</span></p><p data-start=\"769\" data-end=\"792\"><span data-start=\"769\" data-end=\"792\">Sifat larutan asam:</span></p><ul data-start=\"793\" data-end=\"987\">\r\n<li data-start=\"793\" data-end=\"837\">\r\n<p data-start=\"795\" data-end=\"837\">Rasa masam (tidak boleh diuji langsung!)</p>\r\n</li>\r\n<li data-start=\"838\" data-end=\"876\">\r\n<p data-start=\"840\" data-end=\"876\">Mengubah lakmus biru menjadi merah</p>\r\n</li>\r\n<li data-start=\"877\" data-end=\"928\">\r\n<p data-start=\"879\" data-end=\"928\">Menghantarkan listrik (karena menghasilkan ion)</p>\r\n</li>\r\n<li data-start=\"929\" data-end=\"940\">\r\n<p data-start=\"931\" data-end=\"940\">Korosif</p>\r\n</li>\r\n<li data-start=\"941\" data-end=\"987\">\r\n<p data-start=\"943\" data-end=\"987\">Reaktif terhadap logam (menghasilkan gas H₂)</p></li></ul><p data-start=\"3258\" data-end=\"3320\">\r\n<span data-start=\"1165\" data-end=\"1188\" style=\"font-size: 0.875rem;\">Sifat larutan basa:</span></p>\r\n<ul data-start=\"1189\" data-end=\"1381\">\r\n<li data-start=\"1189\" data-end=\"1213\">\r\n<p data-start=\"1191\" data-end=\"1213\">Rasa pahit dan licin</p>\r\n</li>\r\n<li data-start=\"1214\" data-end=\"1252\">\r\n<p data-start=\"1216\" data-end=\"1252\">Mengubah lakmus merah menjadi biru</p>\r\n</li>\r\n<li data-start=\"1253\" data-end=\"1278\">\r\n<p data-start=\"1255\" data-end=\"1278\">Menghantarkan listrik</p>\r\n</li>\r\n<li data-start=\"1279\" data-end=\"1315\">\r\n<p data-start=\"1281\" data-end=\"1315\">Bersifat kaustik (merusak kulit)</p>\r\n</li>\r\n<li data-start=\"1316\" data-end=\"1381\">\r\n<p data-start=\"1318\" data-end=\"1381\">Bereaksi dengan asam membentuk garam + air (reaksi netralisasi)</p></li></ul><p data-start=\"3258\" data-end=\"3320\"><span style=\"font-size: 0.875rem;\">Tariklah garis untuk pasanagan yang tepat ! pada&nbsp;</span><span style=\"font-size: 0.875rem;\">&nbsp;(Zat/Larutan) dan Sifat/Peran) pada asam dan basa.</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:6:{i:0;s:9:\"<p>#</p>\n\";i:1;s:20:\"<p>Asam kuat<br></p>\";i:2;s:16:\"<p>Basa kuat</p>\";i:3;s:23:\"<p>&nbsp;Asam lemah</p>\";i:4;s:17:\"<p>Basa lemah</p>\";i:5;s:14:\"<p>Amfoter</p>\";}i:1;a:6:{i:0;s:84:\"<li data-start=\"355\" data-end=\"363\"><p data-start=\"358\" data-end=\"363\">HCl</p></li>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:2;a:6:{i:0;s:24:\"<p>NH&#8323;</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";}i:3;a:6:{i:0;s:17:\"<p>H&#8322;O</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";}i:4;a:6:{i:0;s:12:\"<p>NaOH</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:5;a:6:{i:0;s:21:\"<p>CH&#8323;COOH</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"0\";}}}', 1764386881, 1764924780, 1, '', 1, 0, 0, '7217d083-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31957, 846, 0, 3, 1, NULL, NULL, NULL, '<p>Faktor penyebab terjadinya perubahan sosial dapat disebabkan oleh karena pengaruh dari dalam dan dari luar masyarakat.Berikut ini tentukanlah pilihan mu  yang merupakan faktor penyebab dari dalam masyarakat</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"<p>BENAR<\\/p><\\/body><\\/html>\",\"<p>SALAH<\\/p><\\/body><\\/html>\"],[\"<p>&nbsp;Bertambah atau berkurangnya penduduk<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>dari lingkungan alam<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>Penemuan-penemuan baru<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>&nbsp;peperangan dengan negara lain<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>Pertentangan masyarakat<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>Pengaruh kebudayaan masyarakat lain<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>Terjadinya pemberontakan&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"]]}', 1764387071, 1764994013, 1, '', 1, 0, 0, '7217d203-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31958, 817, 0, 3, 2, NULL, NULL, NULL, '<p>Asam dan basa adalah konsep dasar dalam kimia yang menjelaskan sifat dan reaktivitas banyak zat. Kedua jenis zat ini memainkan peran penting dalam kehidupan sehari-hari, mulai dari proses pencernaan, pertanian, industri, hingga obat-obatan.<span style=\"font-size: 0.875rem;\">Secara sederhana, </span><span data-start=\"415\" data-end=\"423\" style=\"font-size: 0.875rem;\">asam</span><span style=\"font-size: 0.875rem;\"> adalah zat yang dapat </span><span data-start=\"446\" data-end=\"467\" style=\"font-size: 0.875rem;\">melepaskan ion H⁺</span><span style=\"font-size: 0.875rem;\"> ketika dilarutkan dalam air, sedangkan </span><span data-start=\"507\" data-end=\"515\" style=\"font-size: 0.875rem;\">basa</span><span style=\"font-size: 0.875rem;\"> adalah zat yang dapat </span><span data-start=\"538\" data-end=\"560\" style=\"font-size: 0.875rem;\">melepaskan ion OH⁻</span><span style=\"font-size: 0.875rem;\"> atau menerima ion H⁺ dalam larutan.</span></p>\r\n<p data-start=\"600\" data-end=\"916\">Perilaku asam dan basa dapat dipahami melalui <span data-start=\"646\" data-end=\"678\">sifat-sifatnya dalam larutan</span>. Larutan asam biasanya bersifat masam, dapat mengubah lakmus biru menjadi merah, dan bersifat korosif terhadap logam tertentu. Sementara itu, larutan basa bersifat pahit, licin, mengubah lakmus merah menjadi biru, dan bersifat kaustik.<span style=\"font-size: 0.875rem;\">Berbagai teori telah dikembangkan untuk menjelaskan asam dan basa:</span></p>\r\n<ul data-start=\"987\" data-end=\"1287\">\r\n<li data-start=\"987\" data-end=\"1072\">\r\n<p data-start=\"989\" data-end=\"1072\"><span data-start=\"989\" data-end=\"1008\">Teori Arrhenius</span> menekankan pelepasan ion H⁺ (asam) atau OH⁻ (basa) dalam air.</p>\r\n</li>\r\n<li data-start=\"1073\" data-end=\"1173\">\r\n<p data-start=\"1075\" data-end=\"1173\"><span data-start=\"1075\" data-end=\"1099\">Teori Brønsted-Lowry</span> menjelaskan asam sebagai donor proton dan basa sebagai akseptor proton.</p>\r\n</li>\r\n<li data-start=\"1174\" data-end=\"1287\">\r\n<p data-start=\"1176\" data-end=\"1287\"><span data-start=\"1176\" data-end=\"1191\" style=\"\">Teori Lewis</span> menjelaskan asam sebagai penerima pasangan elektron dan basa sebagai donor pasangan elektron.</p></li></ul><p data-start=\"600\" data-end=\"916\"> Berdasarkan penjelasan di atas tariklah garis untuk pasanagan yang tepat!</p><p><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:6:{i:0;s:9:\"<p>#</p>\n\";i:1;s:38:\"<p>Basa menurut bonsted -lowry<br></p>\";i:2;s:10:\"<p>HCl</p>\";i:3;s:19:\"<p>Fenolftalein</p>\";i:4;s:14:\"<p>Amfoter</p>\";i:5;s:23:\"<p>&nbsp;asam&nbsp;</p>\";}i:1;a:6:{i:0;s:105:\"<li data-start=\"319\" data-end=\"345\"><p data-start=\"322\" data-end=\"345\">Larutan dengan pH &lt; 7</p></li>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";}i:2;a:6:{i:0;s:60:\"<p>Senyawa yang dapat menerima proton (H&#8314;)</p><p></p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:3;a:6:{i:0;s:24:\"<p>Contoh asam kuat</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:4;a:6:{i:0;s:25:\"<p>Contoh basa lemah</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:5;a:6:{i:0;s:56:\"<p>Indikator yang berwarna merah dalam larutan asam</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";}}}', 1764387611, 1764924329, 1, '', 1, 0, 0, '7217d629-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31959, 846, 0, 3, 2, NULL, NULL, NULL, '<p>2.Tentukan pilihan pernyataan- pernyataan berikut ini dengan tepat.Akomodasi dapat berarti keadaan atau proses. sebagai suatu keadaan, akomodasi menunjukan pada adanya keseimbangan dalam interaksi dengan individu dan kelompok sehubungan dengan norma-norma dan nilai-nilai yang berlaku di masyarakat. Tujuan akomodasi menurut Soerjono Soekanto adalah  .. . . . .</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"<p>BENAR<\\/p><\\/body><\\/html>\",\"<p>SALAH<\\/p><\\/body><\\/html>\"],[\"<p>Memperkeruh suasana<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>Mengurangi pertentangan<\\/p><p><\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>Menambah masalah<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>Mencegah meledaknya suatu pertentangan<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>&nbsp;Memungkinkan terjadinya kerja sama<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>Memungkinkan terjadinya Permusuhan<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>Mengusahakan terjadinya asimilasi<\\/p><\\/body><\\/html>\",\"0\",\"1\"]]}', 1764387858, 1764994060, 1, '', 1, 0, 0, '7217d7b0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31960, 846, 0, 3, 3, NULL, NULL, NULL, 'Tentukanlah pernyataan berikut ini dengan tepat yang merupakan bentuk -bentuk akomodasi adalah . . . .', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"<p>Benar<\\/p><\\/body><\\/html>\",\"<p>Salah<\\/p><\\/body><\\/html>\"],[\"<p>Konsiliasi<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>Konduksi&nbsp;<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>&nbsp;Mediasi&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>Disintekrasi&nbsp;<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>&nbsp;Arbitrase&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>&nbsp;Konflik&nbsp;<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>Kompromi<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>&nbsp;Koersi&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"]]}', 1764388189, 1764994090, 1, '', 1, 0, 0, '7217d8ed-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31961, 846, 0, 3, 4, NULL, NULL, NULL, '<p>Tuhan menciptakan manusia terdiri atas laki-laki dan perempuan yang bersuku- suku dan berbangsa- bangsa untuk saling mengenal. Oleh karena itu manusia sejak awal memiliki perbedaan- perbedaan.</p><p>salah satu perbedaan antara individu dengan individu adalah cara berinteraksi, misalnya interkasi dalam kelompok sosial. kelompok sosial terbentuk apabila di antara individu yang satu dengan individu yang lain bertemu. Pertemuan antara individu yang menghasilkan kelompok sosial haruslah berupa proses interaksi, seperti adanya kontak, komunikasi, kerja sama, akomodasi, asimilasi dan akulturasi untuk mencapai tujuan bersama, bahkan mungkin mengadakan persaingan, pertikaian, dan konflik. Kelompok sosial merupakan bagian dari msyarakat,</p><p>kelompok sosial terbentuk karena manusia yang satu dengan manusia yang lainnya saling membutuhkan, sehingga terbentuklah kelompok sosial.</p><p>Tentukan benar atau salah Faktor - faktor pendorong dinamika kelompok sosial yang berasal dari luar di bawah ini</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"<p>BENAR&nbsp;<\\/p><\\/body><\\/html>\",\"<p>SALAH<\\/p><\\/body><\\/html>\"],[\"<p>adanya konflik antar anggota kelompok&nbsp;<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>&nbsp;perubahan situasi sosial<\\/p><p><\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>&nbsp;perubahan situasi ekonomi&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>adanya perbedaan paham<\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>&nbsp;perubahan situasi politik&nbsp;<\\/p><\\/body><\\/html>\",\"1\",\"0\"]]}', 1764388447, 1764994141, 1, '', 1, 0, 0, '7217d9d6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31962, 846, 0, 3, 5, NULL, NULL, NULL, '<p>Tuhan menciptakan manusia terdiri atas laki-laki dan perempuan yang bersuku- suku dan berbangsa- bangsa untuk saling mengenal. Oleh karena itu manusia sejak awal memiliki perbedaan- perbedaan.</p><p>Salah satu perbedaan antara individu dengan individu adalah cara berinteraksi, misalnya interkasi dalam kelompok sosial. kelompok sosial terbentuk apabila di antara individu yang satu dengan individu yang lain bertemu. Pertemuan antara individu yang menghasilkan kelompok sosial haruslah berupa proses interaksi, seperti adanya kontak, komunikasi, kerja sama, akomodasi, asimilasi dan akulturasi untuk mencapai tujuan bersama, bahkan mungkin mengadakan persaingan, pertikaian, dan konflik. Kelompok sosial merupakan bagian dari msyarakat,</p><p><span style=\"font-size: 0.875rem;\">kelompok sosial terbentuk karena manusia yang satu dengan manusia yang lainnya saling membutuhkan, sehingga terbentuklah kelompok sosial.Faktor -faktor pembentuk kelompok sosial, yaitu ...</span></p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"<p>Benar<\\/p><\\/body><\\/html>\",\"<p>Salah<\\/p><\\/body><\\/html>\"],[\"<p>kedekatan<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>&nbsp;kerinduan<\\/p><p><\\/p><\\/body><\\/html>\",\"0\",\"1\"],[\"<p>kesamaan<\\/p><\\/body><\\/html>\",\"1\",\"0\"],[\"<p>Kemunafikan<\\/p><\\/body><\\/html>\",\"0\",\"1\"]]}', 1764388862, 1764994169, 1, '', 1, 0, 0, '7217dafe-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31963, 817, 0, 3, 3, NULL, NULL, NULL, '<p data-start=\"3258\" data-end=\"3320\">Sifat dan peran larutan dalam asam–basa sangat penting karena&nbsp;<span style=\"font-size: 0.875rem;\">Asam dan basa hanya menunjukkan sifatnya ketika berada dalam larutan,&nbsp;</span><span style=\"font-size: 0.875rem;\">Ionisasi/disosiasi terjadi di dalam pelarut,&nbsp;</span><span style=\"font-size: 0.875rem;\">pH hanya bisa ditentukan dalam larutan,&nbsp;</span><span style=\"font-size: 0.875rem;\">Reaksi asam–basa (netralisasi) terjadi dalam larutan,&nbsp;</span><span style=\"font-size: 0.875rem;\">Larutan menentukan kekuatan asam atau basa.</span></p><p data-start=\"769\" data-end=\"792\"><span data-start=\"769\" data-end=\"792\">Sifat larutan asam:</span></p><ul data-start=\"793\" data-end=\"987\"><li data-start=\"793\" data-end=\"837\"><p data-start=\"795\" data-end=\"837\">Rasa masam (tidak boleh diuji langsung!)</p></li><li data-start=\"929\" data-end=\"940\"><p data-start=\"931\" data-end=\"940\">Korosif</p></li><li data-start=\"941\" data-end=\"987\"><p data-start=\"943\" data-end=\"987\">Reaktif terhadap logam (menghasilkan gas H₂)</p></li></ul><p data-start=\"3258\" data-end=\"3320\"><span data-start=\"1165\" data-end=\"1188\" style=\"font-size: 0.875rem;\">Sifat larutan basa:</span></p><ul data-start=\"1189\" data-end=\"1381\"><li data-start=\"1253\" data-end=\"1278\"><p data-start=\"1255\" data-end=\"1278\">Menghantarkan listrik</p></li><li data-start=\"1279\" data-end=\"1315\"><p data-start=\"1281\" data-end=\"1315\">Bersifat kaustik (merusak kulit)</p></li><li data-start=\"1316\" data-end=\"1381\"><p data-start=\"1318\" data-end=\"1381\">Bereaksi dengan asam membentuk garam + air (reaksi netralisasi)</p></li></ul><p data-start=\"3258\" data-end=\"3320\"><span style=\"font-size: 0.875rem;\">Tariklah garis untuk pasanagan yang tepat ! pada&nbsp;</span><span style=\"font-size: 0.875rem;\">&nbsp;(Zat/Larutan) dan Sifat/Peran) pada asam dan basa.</span></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"1\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:6:{i:0;a:6:{i:0;s:9:\"<p>#</p>\n\";i:1;s:15:\"<p>Basa<br></p>\";i:2;s:11:\"<p>Asam</p>\";i:3;s:23:\"<p>Sifat elektrolit</p>\";i:4;s:22:\"<p>&nbsp;Rasa asam</p>\";i:5;s:14:\"<p>pH asam</p>\";}i:1;a:6:{i:0;s:100:\"<li data-start=\"261\" data-end=\"285\"><p data-start=\"264\" data-end=\"285\">Memiliki rasa masam</p></li>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";i:5;s:1:\"0\";}i:2;a:6:{i:0;s:49:\"<p>Mengubah lakmus merah menjadi biru</p><p></p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"1\";}i:3;a:6:{i:0;s:29:\"<p>pH lebih kecil dari 7</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:4;a:6:{i:0;s:40:\"<p>Dapat menghantarkan arus listrik</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";i:5;s:1:\"0\";}i:5;a:6:{i:0;s:36:\"<p>Bersifat licin jika disentuh</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";i:5;s:1:\"0\";}}}', 1764392819, 1764924733, 1, '', 1, 0, 0, '7217dc35-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:52', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
