INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31991, 845, 0, 2, 1, NULL, NULL, NULL, 'Kelompok sosial merupakan bagian dari masyarakat, kelompok sosial terbentuk karena manusia yang satu dengan manusia yang lainnya saling membutuhkan, sehingga terbentuklah kelompok sosial. Faktor -faktor pembentuk kelompok sosial, yaitu ...&nbsp;', '{\"a\":\"<p>&nbsp;kedekatan<\\/p><\\/body><\\/html>\",\"b\":\"<p>kerinduan<\\/p><\\/body><\\/html>\",\"c\":\"<p>kesamaan&nbsp;<\\/p><\\/body><\\/html>\",\"d\":\"<p>keinginan<\\/p><\\/body><\\/html>\",\"e\":\"<p>kemunafikan<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"c\",null]', 1764401835, 1764992354, 1, '', 1, 0, 0, '7217fe9c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31992, 845, 0, 2, 2, NULL, NULL, NULL, '<p>Salah satu perbedaan antara individu dengan individu adalah cara berinteraksi, misalnya interkasi dalam kelompok sosial. kelompok sosial terbentuk apabila di antara individu yang satu dengan individu yang lain bertemu. Pertemuan antara individu yang menghasilkan kelompok sosial haruslah berupa proses interaksi, seperti adanya kontak, komunikasi, kerja sama, akomodasi, asimilasi dan akulturasi untuk mencapai tujuan bersama, bahkan mungkin mengadakan persaingan, pertikaian, dan konflik.Kelompok sosial merupakan bagian dari masyarakat, kelompok sosial terbentuk karena manusia yang satu dengan manusia yang lainnya saling membutuhkan, sehingga terbentuklah kelompok sosial.</p><p>Tentukan benar atau salah Faktor - faktor pendorong dinamika kelompok sosial yang berasal dari luar berikut ini .&nbsp;</p></body></html>', '{\"a\":\"<p>Adanya konflik antar anggota kelompok&nbsp;<\\/p><\\/body><\\/html>\",\"b\":\"<p>Perubahan situasi sosial&nbsp;<\\/p><\\/body><\\/html>\",\"c\":\"<p>Perubahan situasi ekonomi&nbsp;<\\/p><\\/body><\\/html>\",\"d\":\"<p>&nbsp;Adanya perbedaan paham<\\/p><\\/body><\\/html>\",\"e\":\"<p>perubahan situasi politik&nbsp;<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"b\",\"c\",\"e\",null]', 1764401949, 1764992418, 1, '', 1, 0, 0, '72180052-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
