INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (31994, 845, 0, 2, 4, NULL, NULL, NULL, 'Salah satu sosiolog, yaitu Emile Durkheim (1859-1917), melakukan penelitian tentang bunuh diri. Melalui Karyanya Suicide (1897), Durkheim mmenjelaskan latar belakang mengapa individu melakukan bunuh diri. Dalam penelitianya, Durkheim membagi dalam empat tipe bunuh diri. Berikut ini pilihlah dengan tepat 4 tipe bunuh diri dari Durkheim&nbsp;', '{\"a\":\"<p>Egoistik<\\/p><\\/body><\\/html>\",\"b\":\"<p>&nbsp;Anomik<\\/p><\\/body><\\/html>\",\"c\":\"<p>Ekonomik<\\/p><\\/body><\\/html>\",\"d\":\"<p>Altruistik<\\/p><\\/body><\\/html>\",\"e\":\"<p>Munafikis<\\/p><\\/body><\\/html>\",\"f\":\"<p>Fatalistik<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"d\",\"f\",null]', 1764402685, 1764992488, 1, '', 1, 0, 0, '721802e1-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
