INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32038, 875, 0, 2, 3, NULL, NULL, NULL, '<p>Jenis-jenis tanaman pangan\r\n</p><ol><li>Jagung\r\n</li><li>Kacang\r\n</li><li>Tomat\r\n</li><li>Pisang\r\n</li><li>Kelapa\r\n</li></ol><p>Tentukan tanaman diatas yang proses perkembangbiakan dengan biji!</p>', 'a:3:{s:1:\"a\";s:23:\"<p>Jagung dan tomat</p>\";s:1:\"b\";s:22:\"<p>Kacang dan padi</p>\";s:1:\"c\";s:21:\"<p>Ubi dan kelapa</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1764403629, 1764403629, 1, '', 1, 0, 0, '7218417b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32039, 875, 0, 2, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Secara garis besar, bahan pangan dapat dikelompokkan menjadi dua yaitu bahan pangan asal tumbuhan (nabati) dan bahan pangan asal hewan (hewani). Bahan pangan nabati adalah bahan-bahan makanan yang berasal dari tanaman.\r\nBerikut ini beberapa jenis bahan pangan:</p><ol><li>\r\nIkan, telur dan susu\r\n</li><li> Sayur, daun, dan pisang\r\n</li><li>Kelapa, bunga pepaya, dan daun bawang\r\n</li><li>Susu, ayam, dan telur\r\n</li></ol><p>Dari beberapa jenis pangan di atas yan termasuk dalam kelompok tumbuhan nabati adalah:</p>', 'a:3:{s:1:\"a\";s:288:\"<p class=\"MsoNormal\"><span style=\"color: black; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Ikan, telur dan susu</span><o:p></o:p></p>\";s:1:\"b\";s:28:\"<p>Susu, ikan, dan telur</p>\";s:1:\"c\";s:32:\"<p>Sayur, kelapa, dan pisang</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1764403629, 1764403629, 1, '', 1, 0, 0, '7218433e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32040, 875, 0, 2, 5, NULL, NULL, NULL, '<p style=\"text-align: justify; \">Bahan makanan yang berasal dari tanaman (bisa berupa akar, batang, dahan, daun, bunga, buah atau beberapa bagian dari tanaman bahkan keseluruhannya) atau bahan makanan yang diolah dari bahan dasar dari tanaman. Bahan pangan hewani merupakan bahan-bahan makanan yang berasal dari hewan atau olahan yang bahan dasarnya dari hasil hewan.\r\n</p><p>\r\nDari penjelasan diatas merupakan pengertian dari!</p>', 'a:4:{s:1:\"a\";s:13:\"<p>Nabati</p>\";s:1:\"b\";s:13:\"<p>Hewani</p>\";s:1:\"c\";s:26:\"<p>Pertumbuhan makanan</p>\";s:1:\"d\";s:20:\"<p>Bahan makanan</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;N;}', 1764403629, 1764403629, 1, '', 1, 0, 0, '7218442f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32041, 873, 0, 2, 3, NULL, NULL, NULL, 'Please find out \"TOBE\" ....', 'a:5:{s:1:\"a\";s:23:\"<p>Am, is, Are <br></p>\";s:1:\"b\";s:19:\"<p>She, He <br></p>\";s:1:\"c\";s:19:\"<p>Was,Were<br></p>\";s:1:\"d\";s:20:\"<p>We, They <br></p>\";s:1:\"e\";s:17:\"<p>I, You<br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;N;}', 1764405966, 1764904928, 1, '', 1, 0, 0, '721845ba-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32042, 873, 0, 2, 4, NULL, NULL, NULL, '<p style=\"text-align: justify; \">A short time later, in their astonishment, smoke came out of that stone. Corious, Irimiami tried to sit on that stone. Ouch! It’s really hot! He shouted. Becoming more corious, the couple decided to test the stone’s head.How if we put this venison on the stone?said Irimiami. Let’s just try, dear, answered Isoray. Exquisite smells came from the burning meat. As it was ready they ate them up.what a delicious piece of meat or this meat is so delicious,Irimiami said happily. Unsatisfied what they found, they continued testing the stone. Let’s try to put these bamboo stems, said Isoray. Let’s try the grass and leaves, Irimiami added. How about that timber! Shouted Isoray. Day by day, they kept on testing the stone.\r\n</p><p style=\"text-align: justify; \">\r\nBased on this paragraph, please find out the \"verb\" category.</p>', 'a:6:{s:1:\"a\";s:23:\"<p>Astonishment<br></p>\";s:1:\"b\";s:16:\"<p>Came <br></p>\";s:1:\"c\";s:17:\"<p>Stone <br></p>\";s:1:\"d\";s:14:\"<p>Sit<br></p>\";s:1:\"e\";s:14:\"<p>Ate<br></p>\";s:1:\"f\";s:16:\"<p>Kept <br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"b\";i:1;s:1:\"d\";i:2;s:1:\"e\";i:3;s:1:\"f\";i:4;N;}', 1764406218, 1764905000, 1, '', 1, 0, 0, '7218468b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32043, 873, 0, 2, 5, NULL, NULL, NULL, 'The following day, all Randuayaivi people come back to the mountain bringing food items. All those food items were put on the holly stone and the traditional feast took place for three days and night. All the people chanted and dance around the holly stone, worth sipping it and passing the holly stone the holy stone story. People in Papua, particulery those of Yepen Islands, sanctify the fire stone Hitherto. The stone has become a sacred stone that they worship annually.\r\n\r\nBased on the paragraph above, there are the words of \"Noun\" category.', 'a:6:{s:1:\"a\";s:18:\"<p>People <br></p>\";s:1:\"b\";s:16:\"<p>Food <br></p>\";s:1:\"c\";s:16:\"<p>Took <br></p>\";s:1:\"d\";s:22:\"<p>Holly stone<br></p>\";s:1:\"e\";s:18:\"<p>Island <br></p>\";s:1:\"f\";s:18:\"<p>Become <br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:5:{i:0;s:1:\"a\";i:1;s:1:\"b\";i:2;s:1:\"d\";i:3;s:1:\"e\";i:4;N;}', 1764406684, 1764905081, 1, '', 1, 0, 0, '7218480f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32044, 876, 0, 1, 1, NULL, NULL, NULL, '<p style=\"text-align: justify; \"> Complete the dialogue using by Past tense\r\n</p><p style=\"text-align: justify; \">Ando : Good morning, Cha.</p><p style=\"text-align: justify; \">\r\n\r\n       Cha: Good morning, Ando.</p><p style=\"text-align: justify; \">\r\n\r\n       Ando : We arrived at school in the morning and found that somebody …. Into the office during the night. So we called the police.\r\n</p><p style=\"text-align: justify; \">\r\n       Cha: Ok. It is a good idea.</p>', 'Have broken', 'Broken', 'Have been broken', 'Had been broken', 'Will have broken', NULL, NULL, NULL, NULL, NULL, 'b', 1764408060, 1764906609, 1, '', 1, 0, 0, '72184901-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32045, 876, 0, 1, 2, NULL, NULL, NULL, '<p>Complete the dialogue using Past tense</p><p>\r\n\r\nTika : Good Morning,Friend.\r\n</p><p>\r\nRena : Good Morning,too.\r\n</p><p>\r\nTika: Had you followed the wedding party of “Novri and Maxi”?\r\n</p><p>\r\nRena : Yes I had.\r\n</p><p>\r\nTika: Was Ani at the party when you arrived?\r\n</p><p>\r\nRena : No, she ….. home</p>', 'Had already goneHad already gone', 'Has already gone', 'Already went', 'Already goes', 'Was already going', NULL, NULL, NULL, NULL, NULL, 'c', 1764408590, 1764907001, 1, '', 1, 0, 0, '72184a8b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32046, 876, 0, 1, 3, NULL, NULL, NULL, '<p>Complete the dialogue using Present tense\r\n</p><p>\r\nHarpen : Hy, Sua\r\n</p><p>\r\nSua       : Hy friend. What was you back from the party?</p><p>\r\n\r\nHarpen  : I was back to home at 01:00 o’clock and you know, my house was very quiet when I got home. Everybody …. to bed.</p>', 'Already go', 'Was already gone', 'Will already gone', 'Has  already gone', 'Had already gone', NULL, NULL, NULL, NULL, NULL, 'a', 1764408826, 1764907291, 1, '', 1, 0, 0, '72184b65-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32047, 876, 0, 1, 4, NULL, NULL, NULL, '<p>Complete the dialogue bellow using future tense!</p><p>Ani     : Hello, Aco. What are you doing?\r\n</p><p>\r\nAco : Hello, Ani. I’m so sorry because I am so bussy today. What can I help for you?</p><p>\r\n\r\nAni  : I have a problem.</p><p>\r\nAco  : Ok Ani. Phone me after 5 o’clock. We …… working with them.\r\n\r\n</p>', 'Finished', 'Will be Finishing', 'Will  Finish', 'Have Finished', 'Had Finished', NULL, NULL, NULL, NULL, NULL, 'c', 1764409768, 1764907420, 1, '', 1, 0, 0, '72184c3f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
