INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32154, 877, 0, 5, 3, NULL, NULL, NULL, 'Manusia memiliki kelebihan dan kekurangan yang diberikan Tuhan kepadanya. Kekurangan itu diupayakan untuk dilengkapi atau dipenuhi untuk membangun diri dan orang lain, bukan&nbsp; tetap dalam kelemahan.&nbsp; &nbsp;Bagaimana caranya agar anda memiliki kemampuan?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>belajar dan berlatih agar memiliki kemampuan. sebagai contoh seorang siswa yang tidak bisa bermain bola voli,&nbsp; ia&nbsp; &nbsp;berlatih agar bisa bermain bola voli dengan baik.</div>', 1764491214, 1764497469, 1, '', 1, 0, 0, '7218d75c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
