INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32258, 878, 0, 2, 4, NULL, NULL, NULL, '<p>Permasalahan&nbsp;<span style=\"font-size: 0.875rem;\">tidak dihindari dari kehidupan manusia&nbsp;</span><span style=\"font-size: 0.875rem;\">baik masalah sosial maupun masalah alam yang terus menerus&nbsp;</span><span style=\"font-size: 0.875rem;\">menghanttui kehidupaan manusia dari waktu ke wakttu yang memicu ketakutan. dan kegelisahan. Masalah sosial yang&nbsp;</span><span style=\"font-size: 0.875rem;\">sering terjadi adalah&hellip;.</span></p></body></html>', '{\"a\":\"<p>&nbsp;masalah peperangan,&nbsp; konflik antara suku dan agama<\\/p><\\/body><\\/html>\",\"b\":\"<p>&nbsp;penggunaan bahan-bahan kimia yang berlebihan yang&nbsp;<span style=\\\"font-size: 0.875rem;\\\">merusak struktur tanah<\\/span><\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"c\":\"<p>&nbsp;&nbsp;&nbsp;masalah polusi atau kecemaran udara<\\/p><\\/body><\\/html>\",\"d\":\"<p>&nbsp;masalah badai yang merusak taanaman dan&nbsp;<span style=\\\"font-size: 0.875rem;\\\">bangunan-bangunan rumah<\\/span><\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"e\":\"<p>masalah kekeringan dan rendahnya curah hujan<\\/p><\\/body><\\/html>\",\"f\":\"<p>masalah perkelahian antara&nbsp; pelajar<\\/p><\\/body><\\/html>\",\"g\":\"<p>masalah konflik antara suku, agama dan ras<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"f\",\"g\",null]', 1764934986, 1766477475, 1, '', 1, 0, 0, '72196ba6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32259, 878, 0, 2, 5, NULL, NULL, NULL, '<p>Berbagai permasalahan dihadapi dunia dewasa ini baik masalah sosial maupun masalah alam yang berdampak pada umat manusia. Masalah alam yang sering dihadapi manusia adalah sebagai berikut&hellip;.</p></body></html>', '{\"a\":\"<p>&nbsp;masalah peperangan,&nbsp; konflik antara suku dan agama<\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"b\":\"<p>&nbsp;penggunaan bahan-bahan kimia yang berlebihan yang&nbsp;merusak struktur tanah<\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"c\":\"<p>&nbsp;masalah polusi atau kecemaran udara<\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"d\":\"<p>Masalah badai yang merusak taanaman dan&nbsp;bangunan-bangunan rumah&nbsp;<\\/p><\\/body><\\/html>\",\"e\":\"<p>&nbsp;maslah kekeringan dan rendahnya curah hujan<\\/p><\\/body><\\/html>\",\"f\":\"<p>Masalah konflik anatara suku,gama dan ras<\\/p><\\/body><\\/html>\",\"g\":\"<p>Masalah perkelahian antara pelajar<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"b\",\"d\",\"e\",null]', 1764935723, 1766477645, 1, '', 1, 0, 0, '72196c8f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32260, 878, 0, 2, 6, NULL, NULL, NULL, '<p>Pelbagai masalah itu diharapkan untuk diselesaikan scara baik agar tidak berimbas kepada masyarakat lain. Adapun Upaya-upaya yang dilakukan untuk menyelesaikan&nbsp;<span style=\"font-size: 0.875rem;\">Masalah sosial tersebut...</span></p></body></html>', '{\"a\":\"<p>&nbsp;merajut perdamaian dan tali persaudaraan yang&nbsp;<span style=\\\"font-size: 0.875rem;\\\">Erat antara sesama anggota masyarakat.<\\/span><\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"b\":\"<p>&nbsp;menanam Kembali daerah-daerah yang gundul atau r<span style=\\\"font-size: 0.875rem;\\\">eboisasi<\\/span><\\/p><\\/body><\\/html>\",\"c\":\"<p>&nbsp;menanam pohon-pohonan di daerah daerah&nbsp; aliran sungai<\\/p><\\/body><\\/html>\",\"d\":\"<p>Membuang sampah pada tempatnya<\\/p><\\/body><\\/html>\",\"e\":\"<p>Mengurangi penggunaan bahan kimia&nbsp; pada sektor pertanian.<\\/p><\\/body><\\/html>\",\"f\":\"<p>Sosialisasi tentang kehidupan masyarakat yang nyaman dan tenang oleh pihak berwewenang yakni kepolisian<\\/p><\\/body><\\/html>\",\"g\":\"<p>Meningkatkan ketegasaan melalui aturan untuk menertibkan masyarakat<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"f\",\"g\",null]', 1764936270, 1766477837, 1, '', 1, 0, 0, '72196df6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32261, 878, 0, 2, 7, NULL, NULL, NULL, '<p>Lingkungan alam adalah habitat manusia sekaligus sebagai unsur yang menjamin kehidupan manusia. Oleh sebab itu dijaga dan dipelihara demi manusia. berikut adalah hal-hal yang dilakukan untuk menyelesaikan&nbsp;<span style=\"font-size: 0.875rem;\">Masalah lingkungan alam tersebut&hellip;.</span></p></body></html>', '{\"a\":\"<p>Merajut perdamaian dan persaudaraan diantara&nbsp;<span style=\\\"font-size: 0.875rem;\\\">sesama anggota masyarakat.<\\/span><\\/p><\\/body><\\/html>\",\"b\":\"<p>Menanam kembali pohon-pohon di daerah-daerah yang gundul<\\/p><p>.<\\/p><\\/body><\\/html>\",\"c\":\"<p>Menyelesaikan masalah antara warga<\\/p><\\/body><\\/html>\",\"d\":\"<p>Membuang sampah pada tempatnya<\\/p><\\/body><\\/html>\",\"e\":\"<p>Sosialisasi hukum kepada masyarakat sewaktu-waktu<\\/p><\\/body><\\/html>\",\"f\":\"<p>Tidak menebang pohon secara sembarangan terlebih di daerah aliran sungai<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"b\",\"f\",null]', 1764937008, 1766477875, 1, '', 1, 0, 0, '72196eed-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32262, 878, 0, 2, 8, NULL, NULL, NULL, '<p>Berbagai fenomena ketidakadilan di masyarakat. sering menyebabkan banyak pihak dirugikan.</p><p>Berikut beberapa fenomena ketidakadilan &hellip;.</p></body></html>', '{\"a\":\"<p>Pemerintah memperhatikan para lanjut usia dan p<span style=\\\"font-size: 0.875rem;\\\">enyandang cacat<\\/span><\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"b\":\"<p>Pasal 28 UUD 1945 berbunyi: setiap warga negara b<span style=\\\"font-size: 0.875rem;\\\">erhak mendapatkan pekerjaan yang layak bagi kehidupannya.<\\/span><\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"c\":\"<p>&nbsp;Siswa memenuhi kewajibannya dengan baik membayar SPP.&nbsp;<\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"d\":\"<p>Penyediaan sarana&nbsp; dan prasarana tidak merata bagi masyarakat<\\/p><\\/body><\\/html>\",\"e\":\"<p>Pemerintah masa bodoh terhadap korban b<span style=\\\"font-size: 0.875rem;\\\">encana&nbsp;<\\/span><\\/p><\\/body><\\/html>\",\"f\":\"<p>Korupsi meraja lela di seluruh tanah air<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"d\",\"e\",\"f\",null]', 1764938089, 1766477918, 1, '', 1, 0, 0, '72196fca-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32263, 878, 0, 2, 9, NULL, NULL, NULL, '<p>Apa dan&nbsp;<span style=\"font-size: 0.875rem;\">Bagaimana tentang dunia? Konsili Vatikan memandang&hellip;.</span></p></body></html>', '{\"a\":\"<p>Kerja sama gereja yang tulus untuk membangun&nbsp;<span style=\\\"font-size: 0.875rem;\\\">Persaudaraan semua orang<\\/span><\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"b\":\"<p>&nbsp;semua manusia sama di hadapan Allah, untuk saling&nbsp;<span style=\\\"font-size: 0.875rem;\\\">Menghargai dan menghormati<\\/span><\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"c\":\"<p>Perlunya semua&nbsp;&nbsp;<span style=\\\"font-size: 0.875rem;\\\">Pemeluk agama di dunia beribadat sesuai agama dan&nbsp;<\\/span><span style=\\\"font-size: 0.875rem;\\\">Kepercayaan nya masing- masing.<\\/span><\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"d\":\"<p>&nbsp;&nbsp;perlu menghargai perbedaan<\\/p><p>&nbsp;<\\/p><\\/body><\\/html>\",\"e\":\"<p>Perlu kerja sama semua unsur baik pemerintah&nbsp;<span style=\\\"font-size: 0.875rem;\\\">Maupun tokoh-tokoh agama untuk memerangi&nbsp;&nbsp;<\\/span><span style=\\\"font-size: 0.875rem;\\\">Sex bebas dan perjudian yang tidak sehat.<\\/span><\\/p><\\/body><\\/html>\",\"f\":\"<p>Hindari konflik antara umat beragama<\\/p><\\/body><\\/html>\",\"g\":\"<p>Membangun&nbsp; &nbsp;kehidupan yang rukun&nbsp; dan damai antara umat beragama<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"f\",\"g\",null]', 1764939182, 1766477973, 1, '', 1, 0, 0, '72197113-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32264, 878, 0, 2, 10, NULL, NULL, NULL, '<p>Berkenaan dengan berbagai kasus kekerasan di tanah air yang dialami para tenaga buruh yang diperlakukan tidak adil, maka gereja perlu memandang hal ini dan menjadi perhatian serius&nbsp;<span style=\"font-size: 0.875rem;\">Melalui ajaran sosial gereja. Ajaran&nbsp;</span><span style=\"font-size: 0.875rem;\">Sosial gereja yang berkaitan&nbsp;</span><span style=\"font-size: 0.875rem;\">Dengan berbagai kasus kekerasan dan ketidakadilan adalah...</span></p></body></html>', '{\"a\":\"<p>&nbsp;menghargai dan menghormati&nbsp; orang lian seperti diri sendiri.<\\/p><\\/body><\\/html>\",\"b\":\"<p>Bersikap adil terhadap orang lain<\\/p><\\/body><\\/html>\",\"c\":\"<p>Tidak semena-mena terhadap orang lain<\\/p><\\/body><\\/html>\",\"d\":\"<p>menghukum seberat-beratnya pelaku&nbsp; apabila&nbsp; diketahui melakukaan kesalahan&nbsp;<\\/p><\\/body><\\/html>\",\"e\":\"<p>&nbsp;diberlakukan hukuman mati bagi yang membuat kesalahan berat<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"c\",null]', 1764940001, 1766478261, 1, '', 1, 0, 0, '721972b0-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32265, 878, 0, 2, 11, NULL, NULL, NULL, '<p>Panggilan hidup umat Allah meliputi panggilan hidup&nbsp;<span style=\"font-size: 0.875rem;\">Religius dan panggilan hidup sebagai awam. Tujuan dari pada kedua panggilan ini adalah untuk &hellip;..</span></p></body></html>', '{\"a\":\"<p>Menjadi garam bagi &nbsp;sesama&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp;<\\/p><\\/body><\\/html>\",\"b\":\"<p>Menjadi terang bagi sesama<\\/p><\\/body><\\/html>\",\"c\":\"<p>Mempersatukan&nbsp; umat Allah &nbsp;<\\/p><\\/body><\\/html>\",\"d\":\"<p>Memilah mana yang benar dan mana yang salah<\\/p><\\/body><\\/html>\",\"e\":\"<p>Mempersiapkan gereja menghadapi tantangan masa yang akan datang<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",null]', 1764940927, 1766478297, 1, '', 1, 0, 0, '72197401-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32266, 878, 0, 2, 12, NULL, NULL, NULL, '<p>Berkeluarga&nbsp;<span style=\"font-size: 0.875rem;\">Merupakan panggilan manusia untuk&nbsp;</span><span style=\"font-size: 0.875rem;\">Hidup bersatu antara seorang laki-laki&nbsp;</span><span style=\"font-size: 0.875rem;\">Dan seorang perempuan untuk saling membahagiakan, Kitab suci mempertegas&nbsp;</span><span style=\"font-size: 0.875rem;\">Tentang hal perkawinan dimaksud yaitu&hellip;.</span></p></body></html>', '{\"a\":\"<p>&nbsp;Perkawinan diperbolekan antara dua jenis kelamin Yang berbeda laki-laki dan perempuan.<\\/p><\\/body><\\/html>\",\"b\":\"<p>Perkawinan Antara umat&nbsp; beragama diperbolehkan&nbsp; &nbsp;<\\/p><\\/body><\\/html>\",\"c\":\"<p>Perkawinan&nbsp; Dalam satu garis keturunan tidak diperbolehkan &nbsp;<\\/p><\\/body><\\/html>\",\"d\":\"<p>Perkawinan Indogami maupun exogami wajar bagi setiap orang &nbsp;.<\\/p><\\/body><\\/html>\",\"e\":\"<p>Perkawinan yang dilakukan adalah suci&nbsp; .<\\/p><\\/body><\\/html>\",\"f\":\"<p>Perkawinan&nbsp; tidak boleh dipisahkan<\\/p><\\/body><\\/html>\",\"g\":\"<p>Perkawinan seumur hhidup<\\/p><\\/body><\\/html>\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"e\",\"f\",\"g\",null]', 1764941698, 1766478338, 1, '', 1, 0, 0, '721974e4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
