INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32333, 879, 0, 1, 19, NULL, NULL, NULL, 'Saat ini permintaan gula pasir meningkat di pasaran sehingga harga gula pasir meningkat tajam menjangkau Rp.20.000/kg. Sementara di propinsi Maluku Utara ketersediaan bahan baku cukup besar (100.000) hektar tebu yang siap diproses menjadi gula pasir . Namun kendala yang dihadapi petani tebu di propinsi tersebut  adalah keterbatasan alat pemeras tebu, Saat ini baru tersedia  2 unit mesin. Masalah yang dihadapi petani Maluku Utara  untuk memproses tebu menjadi gula pasir untuk didistribusikan  ke pasaran  adalah unsur….', 'manusia', 'mesin', 'metode', 'bahan baku', 'kemampuan keuangan', NULL, NULL, NULL, NULL, NULL, 'b', 1765264398, 1765264398, 1, '', 1, 0, 0, '7219cd2a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
