INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32356, 493, 13, 4, 11, NULL, NULL, NULL, 'Klorin (Cl) adalah salah satu unsur penting yang digunakan dalam berbagai aplikasi, mulai dari disinfektan hingga produksi plastik. Unsur ini memiliki dua isotop stabil utama: Klorin-35 (mengandung 17 proton dan 18 neutron) dan Klorin-37 (mengandung 17 proton dan 20 neutron). Berdasarkan data ini, partikel subatomik apa yang menjadi penentu utama perbedaan massa atom antara kedua isotop klorin tersebut?', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'Neutron', 1766341040, 1766341040, 0, '', 1, 0, 0, '7219cf18-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32357, 493, 13, 4, 12, NULL, NULL, NULL, 'Sebuah unsur X ditemukan memiliki konfigurasi elektron valensi 3s<sup>2</sup> 3p<sup>5</sup>. Berdasarkan konfigurasi ini, tentukan golongan dan periode unsur X dalam tabel periodik. (Tuliskan dengan format: Golongan XA, Periode Y)', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'Golongan VIIA, Periode 3', 1766341040, 1766341040, 0, '', 1, 0, 0, '7219cff4-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32358, 493, 13, 4, 13, NULL, NULL, NULL, 'Neon (Ne) adalah gas mulia yang banyak digunakan dalam lampu neon karena sifatnya yang sangat tidak reaktif. Berbeda dengan natrium (Na) yang sangat reaktif dan mudah membentuk senyawa. Jelaskan mengapa Neon menunjukkan sifat inert (tidak reaktif) berdasarkan konsep konfigurasi elektron valensi dan kaitannya dengan kestabilan atom.', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'Memiliki kulit valensi penuh (8 elektron valensi)', 1766341040, 1766341040, 0, '', 1, 0, 0, '7219d5de-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32359, 493, 13, 4, 14, NULL, NULL, NULL, 'Dalam satu periode yang sama pada tabel periodik, seiring pergerakan dari kiri ke kanan, jari-jari atom cenderung semakin mengecil. Namun, energi ionisasi pertama (energi yang dibutuhkan untuk melepaskan elektron terluar) cenderung meningkat. Mengapa terjadi tren peningkatan energi ionisasi ini seiring pergeseran dari kiri ke kanan dalam satu periode?', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'Gaya tarik inti terhadap elektron valensi semakin kuat', 1766341040, 1766341040, 0, '', 1, 0, 0, '7219d7ec-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32360, 493, 13, 4, 15, NULL, NULL, NULL, 'Litium adalah unsur logam ringan yang banyak digunakan dalam baterai isi ulang. Atom Litium biasanya memiliki 3 proton dan 4 neutron. Jika secara hipotetis, seluruh neutron dalam inti atom Litium tiba-tiba menghilang, namun jumlah proton dan elektronnya tetap sama, apa dampak paling signifikan yang akan terjadi pada massa atom Litium tersebut?', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, 'Massa atom akan berkurang secara signifikan', 1766341040, 1766341040, 0, '', 1, 0, 0, '7219d8ff-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32361, 493, 13, 3, 6, NULL, NULL, NULL, 'Dalam perkembangan teknologi material, pemahaman mendalam tentang struktur atom sangat krusial. Beberapa elemen dimodifikasi atau dipilih berdasarkan karakteristik partikel subatomiknya untuk aplikasi spesifik, misalnya dalam semikonduktor, katalis, atau perangkat medis. Analisislah deskripsi karakteristik atom atau aplikasinya di \'Kolom Kiri\' dan jodohkan dengan penjelasan partikel subatomik, konfigurasi elektron, atau posisinya di tabel periodik yang paling tepat di \'Kolom Kanan\'.', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Termasuk golongan transisi, konfigurasi elektron valensi 4s\\u00b93d\\u00b9\\u2070 yang relatif stabil, menghasilkan sifat logam ulet.\",\"Memiliki 6 proton dan 8 neutron, menunjukkan kelebihan neutron dibanding C-12 yang stabil (6 proton, 6 neutron).\",\"Berada di golongan 17, memiliki 7 elektron valensi (ns\\u00b2np\\u2075) dan memiliki kecenderungan tinggi untuk mencapai oktet.\",\"Berada di golongan 14 (Karbon), memiliki 4 elektron valensi (ns\\u00b2np\\u00b2), membentuk ikatan kovalen yang dapat dimodifikasi.\"],[\"Elemen M dengan 29 proton, memiliki sifat konduktivitas listrik yang sangat tinggi dan mudah ditempa, sering digunakan sebagai kabel.\",\"1\",\"0\",\"0\",\"0\"],[\"Isotop X dari karbon (Z=6) yang digunakan untuk penentuan usia artefak purbakala, memiliki massa atom lebih besar dari isotop karbon paling umum.\",\"0\",\"1\",\"0\",\"0\"],[\"Unsur non-logam P, bersifat sangat elektronegatif dan reaktif, cenderung menarik elektron, penting dalam pembentukan senyawa ionik kuat.\",\"0\",\"0\",\"1\",\"0\"],[\"Elemen Q dengan nomor atom 14, menunjukkan sifat semikonduktor, artinya konduktivitasnya dapat diatur dengan doping.\",\"0\",\"0\",\"0\",\"1\"]]}', 1766341160, 1766341160, 0, '', 1, 0, 0, '7219daaa-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32362, 493, 13, 3, 7, NULL, NULL, NULL, 'Konfigurasi elektron adalah kunci untuk memahami reaktivitas kimia suatu unsur dan tren sifat dalam tabel periodik. Dengan menerapkan prinsip Aufbau, aturan Hund, dan larangan Pauli, kita dapat memprediksi perilaku unsur dalam berbagai reaksi. Telaah informasi di \'Kolom Kiri\' yang menggambarkan karakteristik unsur atau sifat elektron, kemudian jodohkan dengan penjelasan konfigurasi elektron atau prinsip yang mendasarinya di \'Kolom Kanan\'.', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Elektron tersebut berada pada orbital 3p, dengan orientasi spesifik pada sumbu y atau z, dan spin tertentu.\",\"Konfigurasi elektron valensi berakhir di 4s\\u00b9, sangat mudah melepaskan satu elektron untuk mencapai konfigurasi gas mulia sebelumnya.\",\"Ini adalah perwujudan dari aturan Hund, yang meminimalkan tolakan antar elektron dalam orbital-orbital degenerasi.\",\"Ini adalah asas larangan Pauli, yang menjelaskan keunikan setiap elektron dalam atom dan batasan jumlah elektron per orbital.\"],[\"Sebuah elektron dalam atom X memiliki nilai bilangan kuantum n=3, l=1, m_l=0, m_s=+1\\/2. Ini menunjukkan lokasi spesifiknya.\",\"1\",\"0\",\"0\",\"0\"],[\"Suatu unsur Y dengan nomor atom 19 dikenal sangat reaktif dan mudah membentuk ion positif dalam senyawa, menjadikannya agen pereduksi kuat.\",\"0\",\"1\",\"0\",\"0\"],[\"Ketika mengisi orbital-orbital degenerasi (memiliki energi yang sama) dalam satu subkulit, elektron cenderung menempati orbital secara terpisah dengan spin paralel sebelum berpasangan.\",\"0\",\"0\",\"1\",\"0\"],[\"Tidak ada dua elektron dalam satu atom yang dapat memiliki keempat bilangan kuantum (n, l, m_l, m_s) yang persis sama.\",\"0\",\"0\",\"0\",\"1\"]]}', 1766341160, 1766341160, 0, '', 1, 0, 0, '7219de14-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32363, 493, 13, 3, 8, NULL, NULL, NULL, 'Sifat-sifat periodik unsur seperti jari-jari atom, energi ionisasi, afinitas elektron, dan elektronegativitas sangat memengaruhi cara unsur berinteraksi dan membentuk senyawa, serta menentukan sifat makroskopis material. Analisislah skenario atau deskripsi sifat di \'Kolom Kiri\' yang mencerminkan tren periodik, lalu jodohkan dengan konsep atau penjelasan yang paling tepat terkait posisi unsur atau perbandingan sifat di \'Kolom Kanan\'.', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Hal ini karena peningkatan muatan inti efektif yang menarik elektron terluar lebih kuat, menyebabkan elektronegativitas meningkat.\",\"Karena memiliki dua elektron valensi, mereka membentuk ikatan logam yang lebih kuat dengan energi ikatan yang lebih besar.\",\"Ini disebabkan oleh konfigurasi elektron yang stabil (oktet penuh), sehingga energi ionisasi pertama sangat tinggi.\",\"Karena penambahan kulit elektron baru seiring bertambahnya nomor periode, menyebabkan ukuran atom membesar.\"],[\"Dalam satu periode dari kiri ke kanan, kecenderungan atom untuk menarik pasangan elektron dalam ikatan kovalen umumnya meningkat.\",\"1\",\"0\",\"0\",\"0\"],[\"Unsur golongan alkali tanah seperti Mg dan Ca memiliki titik leleh yang lebih tinggi dan kepadatan yang lebih besar dibandingkan unsur alkali pada periode yang sama.\",\"0\",\"1\",\"0\",\"0\"],[\"Dibutuhkan energi yang relatif besar untuk melepaskan elektron pertama dari atom gas mulia, bahkan lebih besar daripada unsur-unsur di sampingnya dalam satu periode.\",\"0\",\"0\",\"1\",\"0\"],[\"Jari-jari atom unsur-unsur dalam satu golongan (dari atas ke bawah) cenderung bertambah secara signifikan.\",\"0\",\"0\",\"0\",\"1\"]]}', 1766341160, 1766341160, 0, '', 1, 0, 0, '7219e12b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32364, 493, 13, 3, 9, NULL, NULL, NULL, 'Penemuan partikel subatomik dan model atom telah merevolusi pemahaman kita tentang materi, membuka jalan bagi aplikasi inovatif mulai dari energi nuklir hingga pencitraan medis. Setiap partikel memiliki peran krusial dalam menentukan identitas dan sifat atom. Analisislah pernyataan di \'Kolom Kiri\' yang mengacu pada karakteristik atau peran partikel subatomik, dan jodohkan dengan deskripsi yang paling akurat di \'Kolom Kanan\'.', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Ini adalah definisi dari isotop, yang memiliki nomor atom sama tetapi nomor massa berbeda.\",\"Elektron, yang mengelilingi inti dalam orbital dan menentukan reaktivitas kimia suatu unsur.\",\"Nomor massa (A), yang merupakan jumlah proton (Z) dan neutron (N).\",\"...defek massa inti yang dikonversi menjadi energi ikat inti, serta keberadaan isotop dengan kelimpahan berbeda.\"],[\"Sebuah inti atom yang memiliki jumlah proton sama tetapi jumlah neutron berbeda dengan inti atom lain dari unsur yang sama.\",\"1\",\"0\",\"0\",\"0\"],[\"Partikel subatomik bermuatan negatif yang menentukan sebagian besar volume atom dan terlibat langsung dalam pembentukan ikatan kimia.\",\"0\",\"1\",\"0\",\"0\"],[\"Jumlah total partikel bermuatan positif dan partikel netral di dalam inti atom, yang berkontribusi signifikan terhadap massa atom.\",\"0\",\"0\",\"1\",\"0\"],[\"Perbedaan massa atom relatif suatu unsur dengan nomor massanya selalu dapat dijelaskan oleh dua faktor utama, yaitu massa elektron yang sangat kecil dan...\",\"0\",\"0\",\"0\",\"1\"]]}', 1766341160, 1766341160, 0, '', 1, 0, 0, '7219e4d3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32365, 493, 13, 3, 10, NULL, NULL, NULL, 'Dalam kimia material modern, perancangan material baru sering kali dimulai dengan memprediksi sifatnya berdasarkan struktur atom dan konfigurasi elektron unsur-unsur penyusunnya. Misalnya, pemilihan material untuk semikonduktor, superkonduktor, atau katalis. Cermati karakteristik material atau elemen di \'Kolom Kiri\' yang menuntut pemahaman konseptual mendalam, kemudian jodohkan dengan penjelasan terkait konfigurasi elektron, posisi tabel periodik, atau sifat dasar atom di \'Kolom Kanan\'.', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Ketersediaan orbital kosong memungkinkan pembentukan pasangan Cooper yang bergerak tanpa hambatan.\",\"Ini adalah rubidium (Rb), unsur alkali dengan satu elektron tidak berpasangan di 5s\\u00b9.\",\"Orbital d yang belum terisi penuh memungkinkan pembentukan ikatan sementara dengan molekul reaktan, memfasilitasi jalur reaksi.\",\"Ini adalah Brom (Br), halogen yang terletak di Golongan 17, memiliki elektronegativitas tinggi, dan cenderung menerima elektron.\"],[\"Material yang berfungsi sebagai superkonduktor pada suhu sangat rendah seringkali melibatkan unsur-unsur dengan subkulit d atau f yang belum penuh.\",\"1\",\"0\",\"0\",\"0\"],[\"Unsur Z memiliki konfigurasi elektron 1s\\u00b22s\\u00b22p\\u20763s\\u00b23p\\u20764s\\u00b23d\\u00b9\\u20704p\\u20765s\\u00b9 dan memiliki sifat paramagnetik lemah, menjadikannya stabil namun reaktif.\",\"0\",\"1\",\"0\",\"0\"],[\"Katalis heterogeneous, yang mempercepat reaksi kimia tanpa ikut bereaksi, seringkali terbuat dari logam transisi (blok d) karena kemampuannya menyediakan banyak situs aktif.\",\"0\",\"0\",\"1\",\"0\"],[\"Unsur X memiliki nomor atom 35. Dalam bentuk molekul diatomiknya, ia sangat reaktif dan merupakan oksidator kuat, bereaksi dengan sebagian besar logam.\",\"0\",\"0\",\"0\",\"1\"]]}', 1766341160, 1766341160, 0, '', 1, 0, 0, '7219e69d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32366, 605, 17, 3, 7, NULL, NULL, NULL, 'Perhatikan narasi berikut. Kemudian, jodohkan pernyataan di kolom kiri dengan konsep atau implikasi yang paling sesuai di kolom kanan.', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Indikator utama kelangkaan kebutuhan pokok yang mendesak.\",\"Penyebab kelangkaan faktor produksi yang vital dalam pertanian.\",\"Tindakan mitigasi untuk mengatasi dampak kelangkaan dan memastikan pemerataan.\",\"Ilustrasi konkret dari masalah kelangkaan sumber daya ekonomi.\"],[\"Penurunan hasil panen padi hingga 40% yang memicu kenaikan harga beras sebesar 25%.\",\"1\",\"0\",\"0\",\"0\"],[\"Keterbatasan pasokan dan kenaikan harga pupuk bersubsidi sebesar 15%.\",\"0\",\"1\",\"0\",\"0\"],[\"Peran pemerintah daerah dalam menyusun kebijakan distribusi beras dan pupuk.\",\"0\",\"0\",\"1\",\"0\"],[\"Kondisi menyeluruh yang dihadapi oleh Desa Makmur terkait kebutuhan pangan dan pertanian.\",\"0\",\"0\",\"0\",\"1\"]]}', 1766342183, 1766342183, 1, '', 1, 0, 0, '7219e8e3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32367, 605, 17, 3, 8, NULL, NULL, NULL, '<p>Kantin SMA Merdeka berupaya mengelola persediaan makanan agar sesuai dengan kebutuhan siswa dan meminimalkan pemborosan.&nbsp;<span style=\"font-size: 0.875rem;\">Berikut adalah data rata-rata penjualan harian dan biaya produksi empat menu utama selama satu bulan terakhir. Total kapasitas produksi kantin adalah 200 porsi per hari, dengan bahan baku yang terbatas.</span></p><p><span style=\"font-size: 0.875rem;\">| Menu Makanan | Penjualan Rata-rata (Porsi/hari) | Biaya Produksi/Porsi (Rp) |</span></p><p><span style=\"font-size: 0.875rem;\">| Nasi Goreng  | 80                               | 12.000                    |</span></p><p><span style=\"font-size: 0.875rem;\">| Mie Ayam     | 60                               | 10.000                    |</span></p><p><span style=\"font-size: 0.875rem;\">| Soto Ayam    | 40                               | 15.000                    |</span></p><p><span style=\"font-size: 0.875rem;\">| Bakso        | 20                               | 13.000                    |</span></p><p><span style=\"font-size: 0.875rem;\">Jodohkan observasi di kolom kiri dengan implikasi atau rekomendasi yang paling tepat di kolom kanan.</span></p></body></html>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Menu ini harus menjadi prioritas utama dalam alokasi bahan baku dan produksi harian.\",\"Kantin perlu mengevaluasi kembali popularitas menu ini atau mempertimbangkan inovasi.\",\"Kantin harus jeli dalam mengelola ketersediaan bahan baku agar tidak terjadi kekurangan atau kelebihan produksi.\",\"Membutuhkan pertimbangan strategi harga atau efisiensi produksi untuk menjaga profitabilitas kantin.\"],[\"Nasi Goreng memiliki penjualan rata-rata tertinggi sebesar 80 porsi\\/hari.\",\"1\",\"0\",\"0\",\"0\"],[\"Bakso menunjukkan penjualan rata-rata terendah, yaitu 20 porsi\\/hari.\",\"0\",\"1\",\"0\",\"0\"],[\"Jika semua permintaan keempat menu terpenuhi, total porsi yang dibutuhkan adalah 200 porsi\\/hari.\",\"0\",\"0\",\"1\",\"0\"],[\"Biaya produksi Soto Ayam paling tinggi (Rp 15.000\\/porsi) di antara semua menu.\",\"0\",\"0\",\"0\",\"1\"]]}', 1766342183, 1766342352, 1, '', 1, 0, 0, '7219ec0c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32368, 493, 13, 3, 11, NULL, NULL, NULL, '<p><strong>Data/Situasi:</strong> Suatu negara sedang menghadapi dilema dalam pengembangan energi nuklir. Mereka mempertimbangkan penggunaan Uranium-235 ($^{235}_{92}$U) sebagai bahan bakar utama karena sifatnya yang fisil, tetapi menyadari limbah yang dihasilkan memiliki waktu paruh sangat panjang. Di sisi lain, ada penelitian tentang penggunaan Thorium-232 ($^{232}_{90}$Th) yang lebih melimpah dan menghasilkan limbah dengan waktu paruh lebih pendek, namun membutuhkan inisiator neutron eksternal. Sementara itu, isotop Argon-40 ($^{40}_{18}$Ar) digunakan dalam detektor radiasi karena stabilitasnya yang tinggi.</p><p>Jodohkanlah premis berikut dengan pasangannya yang tepat berdasarkan data di atas:</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Memiliki 143 neutron dan merupakan inti yang mudah mengalami fisi nuklir.\",\"Potensial sebagai bahan bakar alternatif karena kelimpahannya dan hasil limbah dengan waktu paruh lebih pendek.\",\"Digunakan sebagai gas inert dalam peralatan, menunjukkan stabilitas inti yang sangat tinggi.\"],[\"Isotop $^{235}_{92}$U\",\"1\",\"0\",\"0\"],[\"Isotop $^{232}_{90}$Th\",\"0\",\"1\",\"0\"],[\"Isotop $^{40}_{18}$Ar\",\"0\",\"0\",\"1\"]]}', 1766364915, 1766364915, 0, '', 1, 0, 0, '7219eeb2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32369, 493, 13, 3, 12, NULL, NULL, NULL, '<p><strong>Data/Situasi:</strong> Tim peneliti kimia sintetis berhasil mengisolasi dua senyawa dari material ekstraterestrial. Analisis awal menunjukkan bahwa unsur utama dalam senyawa pertama, kita sebut \'A\', memiliki kecenderungan kuat untuk melepaskan dua elektron terluarnya, membentuk ion +2, dan menunjukkan sifat logam yang sangat reaktif. Sementara itu, unsur utama dalam senyawa kedua, kita sebut \'B\', memiliki daya tarik elektron yang sangat tinggi dan cenderung menarik satu elektron untuk membentuk ion -1, serta merupakan non-logam yang reaktif. Para peneliti ingin memahami konfigurasi elektron valensi dan posisi relatif kedua unsur ini di tabel periodik.</p><p>Jodohkanlah premis berikut dengan pasangannya yang tepat berdasarkan data di atas:</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Berakhir pada subkulit s dengan 2 elektron (ns$^2$), menunjukkan golongan logam alkali tanah.\",\"Memiliki 7 elektron valensi, mudah menerima 1 elektron untuk mencapai konfigurasi gas mulia.\",\"Terletak pada Golongan IIA, menunjukkan sifat logam yang elektropositif.\"],[\"Konfigurasi elektron valensi unsur \'A\'\",\"1\",\"0\",\"0\"],[\"Kecenderungan unsur \'B\'\",\"0\",\"1\",\"0\"],[\"Posisi unsur \'A\' di tabel periodik\",\"0\",\"0\",\"1\"]]}', 1766364915, 1766364915, 0, '', 1, 0, 0, '7219effb-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32370, 493, 13, 3, 13, NULL, NULL, NULL, '<p><strong>Data/Situasi:</strong> Dalam sebuah simulasi sejarah sains, siswa diminta untuk menganalisis serangkaian temuan eksperimen kunci yang mengubah pemahaman kita tentang struktur atom. Mereka disajikan dengan data hasil dari beberapa percobaan penting dan harus mencocokkan setiap temuan dengan implikasi terbesarnya terhadap model atom yang berlaku pada masanya. Ini bukan sekadar mengingat, melainkan memahami bagaimana bukti empiris memformulasikan teori.</p><p>Jodohkanlah premis berikut dengan pasangannya yang tepat berdasarkan data di atas:</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Menunjukkan adanya inti atom yang padat, bermuatan positif, dan sangat kecil, mendasari model atom Rutherford.\",\"Membuktikan bahwa elektron menempati tingkat energi tertentu yang terkuantisasi di sekitar inti, bukan bergerak secara acak.\",\"Menegaskan bahwa atom bukanlah partikel tak terbagi dan mengandung partikel subatomik universal (elektron).\"],[\"Defleksi partikel alfa yang signifikan oleh sebagian kecil atom emas pada eksperimen Rutherford.\",\"1\",\"0\",\"0\"],[\"Spektrum emisi atom hidrogen yang bersifat diskrit (garis-garis spesifik) pada eksperimen Bohr.\",\"0\",\"1\",\"0\"],[\"Adanya partikel bermuatan negatif yang identik dari berbagai jenis gas dalam tabung sinar katoda Thomson.\",\"0\",\"0\",\"1\"]]}', 1766364915, 1766364915, 0, '', 1, 0, 0, '7219f143-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32371, 493, 13, 3, 14, NULL, NULL, NULL, '<p><strong>Data/Situasi:</strong> Sebuah perusahaan teknologi kuantum sedang mengembangkan komputer yang memanfaatkan spin elektron dan tingkat energi orbital untuk menyimpan dan memproses informasi. Untuk itu, mereka perlu memahami dengan sangat presisi bagaimana elektron didistribusikan dalam atom dan bagaimana setiap orbital memengaruhi perilakunya. Parameter-parameter kuantum (n, l, m$_l$, m$_s$) menjadi sangat krusial dalam desain mereka.</p><p>Jodohkanlah premis berikut dengan pasangannya yang tepat berdasarkan data di atas:</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Elektron berada di subkulit d pada kulit ketiga, yang secara teoritis dapat menampung hingga 10 elektron.\",\"Tiga orbital berbentuk dumbbell (p$_x$, p$_y$, p$_z$) yang saling tegak lurus dalam ruang.\",\"Menentukan orientasi spesifik dari orbital atom dalam ruang tiga dimensi.\"],[\"Keadaan elektron dengan bilangan kuantum utama (n) = 3 dan azimut (l) = 2.\",\"1\",\"0\",\"0\"],[\"Perbedaan orientasi spatial yang mungkin untuk subkulit dengan bilangan kuantum azimut (l) = 1.\",\"0\",\"1\",\"0\"],[\"Fungsi dari bilangan kuantum magnetik (m$_l$).\",\"0\",\"0\",\"1\"]]}', 1766364915, 1766364915, 0, '', 1, 0, 0, '7219f27e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32372, 493, 13, 3, 15, NULL, NULL, NULL, '<p><strong>Data/Situasi:</strong> Seorang ahli kimia forensik sedang menganalisis sampel dari TKP menggunakan spektrometri massa untuk mengidentifikasi elemen dan isotop yang ada. Analisis ini sangat sensitif dan dapat membedakan partikel berdasarkan rasio massa-muatan (m/z). Untuk menafsirkan spektrum dengan benar, ahli harus memiliki pemahaman yang kuat tentang bagaimana notasi atom dan ion berkaitan dengan jumlah partikel subatomik yang menyusunnya.</p><p>Jodohkanlah premis berikut dengan pasangannya yang tepat berdasarkan data di atas:</p></body></html>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Merupakan ion besi(II), $^{56}_{26}$Fe$^{2+}$, karena memiliki 2 elektron lebih sedikit dari jumlah protonnya.\",\"Memiliki 35 proton (Nomor Atom Br), 45 neutron (80-35), dan 36 elektron (35+1).\",\"Kedua isotop memiliki jumlah proton dan elektron yang sama (masing-masing 6), tetapi berbeda 2 neutron.\"],[\"Partikel dengan 26 proton, 30 neutron, dan 24 elektron.\",\"1\",\"0\",\"0\"],[\"Ion Bromida dengan nomor massa 80 dan muatan -1.\",\"0\",\"1\",\"0\"],[\"Perbandingan antara isotop karbon-14 ($^{14}_{6}$C) dan karbon-12 ($^{12}_{6}$C).\",\"0\",\"0\",\"1\"]]}', 1766364915, 1766384025, 0, '', 1, 0, 0, '7219f4aa-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32374, 605, 17, 3, 9, NULL, NULL, NULL, '<p><strong>Data/Situasi:</strong> Desa Harmoni, sebuah desa kecil di pinggiran kota, menghadapi dilema dalam alokasi anggaran tahunan sebesar Rp500 juta. Dana tersebut berasal dari pemerintah daerah dan swadaya masyarakat. Desa ini memiliki dua kebutuhan mendesak: (1) Membangun sarana pengolahan limbah komunal untuk mengatasi pencemaran sungai yang berdampak pada kesehatan warga dan ekosistem lokal, dan (2) Membangun balai pertemuan serbaguna untuk kegiatan sosial dan ekonomi yang dapat meningkatkan kohesi warga dan potensi pendapatan dari penyewaan. Kedua proyek ini memiliki perkiraan biaya sekitar Rp400 juta masing-masing. Jika satu proyek dipilih, proyek lainnya harus ditunda atau dibatalkan.</p><p>Jodohkanlah premis berikut dengan pasangannya yang tepat berdasarkan data di atas:</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Mencerminkan esensi kelangkaan sumber daya finansial yang memaksa desa untuk membuat pilihan prioritas.\",\"Mengorbankan kesempatan untuk memiliki balai pertemuan yang dapat meningkatkan interaksi sosial dan pendapatan desa.\",\"Menyoroti urgensi kebutuhan dasar yang harus diprioritaskan dalam menghadapi kelangkaan sumber daya.\",\"Merupakan manfaat yang hilang (biaya peluang) jika desa memilih pembangunan sarana pengolahan limbah.\"],[\"Keterbatasan anggaran sebesar Rp500 juta untuk dua proyek senilai total Rp800 juta\",\"1\",\"0\",\"0\",\"0\"],[\"Keputusan untuk membangun sarana pengolahan limbah komunal\",\"0\",\"1\",\"0\",\"0\"],[\"Dampak pencemaran sungai terhadap kesehatan warga dan ekosistem\",\"0\",\"0\",\"1\",\"0\"],[\"Potensi peningkatan kohesi warga dan pendapatan dari penyewaan balai pertemuan\",\"0\",\"0\",\"0\",\"1\"]]}', 1766367017, 1766367017, 1, '', 1, 0, 0, '7219f5e3-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32375, 605, 17, 3, 10, NULL, NULL, NULL, '<p><strong>Data/Situasi:</strong> Laporan PBB tahun 2023 memproyeksikan bahwa pada tahun 2050, sekitar 60% populasi dunia akan menghadapi kelangkaan air bersih yang parah, terutama di wilayah Asia Selatan dan Afrika Sub-Sahara. Sementara itu, kebutuhan energi global diperkirakan meningkat 50% pada periode yang sama. Untuk mengatasi tantangan ini, beberapa negara mengusulkan strategi: (A) Desalinasi air laut skala besar dengan teknologi canggih, (B) Investasi masif pada energi nuklir sebagai alternatif bahan bakar fosil, (C) Penerapan kebijakan konservasi sumber daya secara ketat disertai pengembangan pertanian berkelanjutan yang hemat air, dan (D) Peningkatan impor sumber daya dari negara yang surplus.</p><p>Jodohkanlah premis berikut dengan pasangannya yang tepat berdasarkan data di atas:</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"model\":\"1\",\"type\":\"1\",\"jawaban\":[[\"#\",\"Menggarisbawahi sifat kelangkaan yang bersifat universal dan dinamis, memerlukan respons adaptif dari berbagai sektor.\",\"Menunjukkan upaya mengatasi kelangkaan melalui inovasi teknologi yang membutuhkan biaya kapital sangat tinggi dan potensi risiko lingkungan.\",\"Merefleksikan pendekatan manajemen kelangkaan yang berfokus pada efisiensi penggunaan dan keberlanjutan, namun menuntut perubahan perilaku dan sistem.\",\"Merupakan solusi jangka pendek yang menciptakan ketergantungan ekonomi dan tidak mengatasi akar masalah kelangkaan global secara fundamental.\"],[\"Proyeksi kelangkaan air bersih dan peningkatan kebutuhan energi global di masa depan\",\"1\",\"0\",\"0\",\"0\"],[\"Strategi desalinasi air laut skala besar dan investasi energi nuklir\",\"0\",\"1\",\"0\",\"0\"],[\"Penerapan kebijakan konservasi sumber daya dan pertanian berkelanjutan yang hemat air\",\"0\",\"0\",\"1\",\"0\"],[\"Peningkatan impor sumber daya dari negara surplus\",\"0\",\"0\",\"0\",\"1\"]]}', 1766367017, 1766367017, 1, '', 1, 0, 0, '7219f72b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32386, 605, 17, 2, 11, NULL, NULL, NULL, '<p><strong>Wacana:</strong></p><p>Dewan Perwakilan Siswa (DPS) SMA Tunas Bangsa menerima alokasi dana kegiatan sebesar Rp 50.000.000 untuk satu semester. Dari hasil survei dan rapat koordinasi, DPS mengidentifikasi empat program prioritas yang sangat diinginkan oleh mayoritas siswa, beserta estimasi biayanya:</p><ol><li>Renovasi perpustakaan menjadi \'Pojok Digital\' yang modern dan nyaman (estimasi biaya: Rp 30.000.000).</li><li>Pengadaan peralatan olahraga baru untuk cabang basket, futsal, dan voli yang sudah usang (estimasi biaya: Rp 25.000.000).</li><li>Penyelenggaraan acara \'Pentas Seni Tahunan\' skala besar yang melibatkan semua ekstrakurikuler (estimasi biaya: Rp 20.000.000).</li><li>Program bimbingan belajar intensif untuk mata pelajaran sulit seperti Matematika dan Fisika dengan pengajar profesional (estimasi biaya: Rp 15.000.000).</li></ol><p>DPS harus menyusun rencana kerja dan alokasi dana secara cermat untuk satu semester ke depan.</p><p><strong>Pertanyaan:</strong></p><p>Berdasarkan wacana di atas, manakah pernyataan berikut yang paling tepat menggambarkan prinsip kelangkaan sebagai inti masalah ekonomi yang dihadapi DPS?</p></body></html>', '{\"a\":\"1\",\"b\":\"2\",\"c\":\"3\",\"d\":\"4\"}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"d\",null]', 1766368078, 1766368825, 1, '', 1, 0, 0, '7219f862-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32387, 605, 17, 2, 12, NULL, NULL, NULL, '<p><strong>Wacana:</strong></p><p>Sekolah Menengah Atas \'Bintang Harapan\' setiap tahun menghadapi tantangan dalam mengelola alokasi dana untuk kegiatan ekstrakurikuler. Berbagai klub, mulai dari klub olahraga (seperti sepak bola, basket), klub seni (teater, musik), hingga klub ilmiah (robotik, karya ilmiah remaja), mengajukan proposal dengan kebutuhan yang beragam, mulai dari pembelian peralatan baru, biaya pendaftaran kompetisi, hingga penyelenggaraan acara. Meskipun sekolah berupaya maksimal, anggaran total yang tersedia untuk semua kegiatan ekstrakurikuler jumlahnya tetap terbatas. Permintaan dana dari semua klub selalu jauh melebihi ketersediaan anggaran. Situasi ini memaksa panitia sekolah untuk mengadakan diskusi panjang dan membuat keputusan sulit tentang klub mana yang akan mendapatkan prioritas dan seberapa besar alokasi dana yang akan diberikan, yang berarti tidak semua permintaan dapat dipenuhi secara penuh.</p><p><strong>Pertanyaan:</strong></p><p>Berdasarkan skenario di SMA \'Bintang Harapan\' tersebut, manakah pernyataan berikut yang paling tepat menggambarkan inti dari masalah kelangkaan dalam ilmu ekonomi?</p>', '{\"a\":\"Jumlah anggaran dana yang terbatas milik sekolah harus dialokasikan untuk memenuhi beragam kebutuhan dan keinginan klub yang seolah tanpa batas.\",\"b\":\"Panitia sekolah harus membuat pilihan alokasi dana karena tidak semua kebutuhan dan keinginan klub dapat dipenuhi secara bersamaan dan penuh.\",\"c\":\"Keterbatasan jumlah guru pembimbing yang kompeten untuk semua jenis kegiatan ekstrakurikuler yang ada di sekolah.\"}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\"]', 1766368925, 1766368925, 1, '', 1, 0, 0, '7219f9aa-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32388, 605, 17, 2, 13, NULL, NULL, NULL, '<p><strong>Wacana:</strong></p><p>Desa Harapan, sebuah komunitas agraris di wilayah pegunungan, secara tradisional mengandalkan hasil panen kopi dan sayuran untuk mata pencarian dan pemenuhan kebutuhan. Namun, dalam tujuh tahun terakhir, pola curah hujan yang semakin tidak menentu akibat perubahan iklim global telah menyebabkan penurunan signifikan pada kualitas dan kuantitas hasil panen. Produksi kopi turun rata-rata 35% dan sayuran 20%. Di sisi lain, jumlah penduduk Desa Harapan terus bertambah 1,5% setiap tahun, meningkatkan kebutuhan akan pangan yang lebih beragam, air bersih yang memadai, serta akses pendidikan dan kesehatan yang lebih baik. Pemerintah desa memiliki anggaran yang sangat terbatas dan dihadapkan pada pilihan sulit: mengalokasikan dana untuk perbaikan irigasi agar produksi pertanian kembali meningkat, atau membangun fasilitas pengolahan air bersih dan menambah beasiswa pendidikan untuk anak-anak.</p><p>Berdasarkan wacana tersebut, identifikasi pernyataan-pernyataan berikut yang secara tepat menggambarkan inti masalah kelangkaan dalam ilmu ekonomi dan implikasinya terhadap Desa Harapan.</p>', '{\"a\":\"Penurunan produksi kopi dan sayuran, bersamaan dengan peningkatan kebutuhan penduduk, secara jelas menunjukkan adanya kelangkaan sumber daya alam (tanah subur, air) dan barang ekonomi (pangan) dibandingkan keinginan dan kebutuhan masyarakat.\",\"b\":\"Masalah utama Desa Harapan adalah kegagalan pemerintah dalam mengimplementasikan teknologi pertanian modern; jika teknologi diterapkan, kelangkaan tidak akan terjadi.\",\"c\":\"Situasi di Desa Harapan adalah contoh klasik inti masalah ekonomi, di mana keinginan dan kebutuhan manusia tidak terbatas, sementara alat pemuas kebutuhan (sumber daya dan barang\\/jasa) yang tersedia sangat terbatas, sehingga memaksa adanya pilihan (trade-off) dan skala prioritas.\",\"d\":\"Kelangkaan hanya terjadi karena faktor alam murni; ini tidak memiliki kaitan langsung dengan ilmu ekonomi karena tidak ada keputusan alokasi sumber daya yang perlu diambil.\"}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '[\"a\",\"c\"]', 1766369177, 1766369177, 1, '', 1, 0, 0, '7219fae6-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32389, 493, 13, 2, 6, NULL, NULL, NULL, '<p><strong>Wacana:</strong></p><p>Sebuah perusahaan teknologi terkemuka, \'Inovasi Material Global\', sedang dalam tahap riset dan pengembangan untuk menciptakan material semikonduktor generasi terbaru yang memiliki efisiensi energi sangat tinggi dan stabilitas termal superior. Mereka menyadari bahwa kunci keberhasilan terletak pada pemilihan unsur dengan konfigurasi elektron valensi yang tepat, yang memungkinkan pembentukan ikatan kovalen kuat dalam struktur kristal. Spesifikasi yang mereka cari adalah unsur yang mampu membentuk empat ikatan kovalen dan berada pada Blok p, tepatnya di periode 3 atau 4, di mana stabilitas termal dapat dioptimalkan.</p><p>Berdasarkan kriteria yang ditetapkan oleh Inovasi Material Global dan pemahaman Anda tentang struktur atom serta tabel periodik, analisis dan pilihlah pernyataan-pernyataan berikut yang TEPAT mengenai karakteristik unsur ideal tersebut.</p>', '{\"a\":\"Unsur tersebut pastilah memiliki 4 elektron valensi dan berada pada Golongan 14 (IVA) di tabel periodik.\",\"b\":\"Jika unsur yang dipilih berasal dari Periode 3, maka inti atomnya akan memiliki 14 proton dan konfigurasi elektronnya berakhir pada subkulit 3s\\u00b23p\\u00b2.\",\"c\":\"Unsur dari Periode 4 yang memenuhi kriteria ini akan cenderung membentuk ion bermuatan +4 dengan mudah untuk mencapai konfigurasi gas mulia.\"}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\"]', 1766369256, 1766369256, 0, '', 1, 0, 0, '7219fbff-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32390, 605, 17, 2, 14, NULL, NULL, NULL, '<p><strong>Wacana:</strong></p><p>Klub Pecinta Alam SMAN Harapan Bangsa berencana mengadakan kegiatan \'Jelajah Alam Akhir Pekan\' untuk 30 anggotanya. Untuk mewujudkan rencana ini, mereka dihadapkan pada beberapa kendala yang melibatkan sumber daya dan pilihan:</p><ul><li><strong>Anggaran Klub Terbatas:</strong> Hanya tersedia Rp1.500.000, dengan iuran maksimal dari setiap anggota Rp50.000.</li><li><strong>Waktu Terbatas:</strong> Kegiatan harus dilaksanakan dalam 2 hari 1 malam (akhir pekan), dengan persiapan hanya 1 bulan.</li><li><strong>Transportasi Terbatas:</strong> Klub hanya memiliki akses ke 1 bus sekolah kecil berkapasitas 25 orang. Jika lebih dari 25 anggota ikut, perlu menyewa bus lain atau menggunakan mobil pribadi dengan biaya bensin ditanggung masing-masing.</li><li><strong>Pilihan Destinasi Beragam:</strong> Anggota memiliki preferensi yang kuat terhadap tiga opsi:</li><ol><li><strong>Pendakian Gunung:</strong> Biaya transportasi tinggi, butuh perlengkapan khusus (sewa/beli), membutuhkan kondisi fisik prima, waktu tempuh lama, dan hanya bisa menampung jumlah terbatas.</li><li><strong>Wisata Pantai:</strong> Biaya transportasi sedang, tidak butuh perlengkapan khusus, waktu tempuh relatif singkat, bisa menampung banyak orang, dan cocok untuk relaksasi.</li><li><strong>Eksplorasi Air Terjun & Hutan Lindung:</strong> Biaya transportasi sedang, butuh izin khusus dari dinas kehutanan, medan sedang, waktu eksplorasi terbatas karena aturan kawasan, dan kegiatan edukatif.</li></ol></ul><p>Mengingat kondisi tersebut, pengurus klub harus membuat keputusan yang tepat agar kegiatan tetap terlaksana dengan optimal dan anggota merasa puas, meskipun tidak semua keinginan bisa terpenuhi.</p><p>Berdasarkan wacana di atas, identifikasi pernyataan-pernyataan yang secara tepat menggambarkan inti masalah kelangkaan dalam ilmu ekonomi yang dihadapi oleh Klub Pecinta Alam SMAN Harapan Bangsa. (Pilih semua yang benar)</p>', '{\"a\":\"Keterbatasan anggaran (dana) dan kapasitas transportasi (bus) merupakan manifestasi langsung dari kelangkaan sumber daya yang memaksa klub untuk membuat pilihan dan prioritas.\",\"b\":\"Adanya berbagai pilihan destinasi yang menarik bagi anggota menunjukkan bahwa kebutuhan dan keinginan manusia tidak terbatas, sementara alat pemuasnya (sumber daya klub) terbatas.\",\"c\":\"Keputusan akhir yang akan diambil oleh pengurus klub, tidak peduli pilihan manapun, pada dasarnya adalah pengorbanan (trade-off) dari manfaat atau keuntungan opsi destinasi lain yang tidak terpilih.\",\"d\":\"Jika pengurus klub berhasil meyakinkan semua anggota untuk patungan lebih besar, maka masalah kelangkaan sumber daya akan sepenuhnya teratasi dan semua opsi destinasi dapat diwujudkan secara bersamaan.\",\"e\":\"Masalah kelangkaan yang dihadapi klub ini terutama disebabkan oleh kurangnya kemampuan promosi untuk menarik lebih banyak sponsor dan dukungan eksternal.\"}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '[\"a\",\"b\",\"c\"]', 1766369757, 1766369757, 1, '', 1, 0, 0, '7219fd4e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32391, 769, 0, 6, 1, NULL, NULL, NULL, '<p><b>STIMULUS: Pertumbuhan Pengguna Aplikasi EcoRide</b></p><p>EcoRide, sebuah <i>startup</i> penyedia layanan penyewaan skuter listrik, baru saja meluncurkan operasinya di Kota Maju. Sebagai bagian dari strategi pengembangan bisnis, tim manajemen EcoRide sangat fokus pada pertumbuhan jumlah pengguna aktif mingguan. Setelah empat minggu pertama beroperasi, data yang terkumpul menunjukkan pola pertumbuhan pengguna sebagai berikut:</p><ul>    <li>Minggu ke-1: 100 pengguna</li>    <li>Minggu ke-2: 150 pengguna</li>    <li>Minggu ke-3: 200 pengguna</li>    <li>Minggu ke-4: 250 pengguna</li></ul><p>Manajer operasional ingin membuat proyeksi kapan jumlah pengguna akan mencapai target 1.000 pengguna aktif mingguan agar dapat merencanakan penambahan armada skuter listrik dan ekspansi area layanan.</p><p><b>SOAL:</b></p><p>Berdasarkan data pertumbuhan pengguna EcoRide yang konsisten di Kota Maju, pada minggu ke berapa perusahaan tersebut diproyeksikan akan mencapai target 1.000 pengguna aktif mingguan?</p></body></html>', '{\"items\":[\"Minggu ke-1\",\"Minggu ke-2\",\"Minggu ke-3\",\"Minggu ke-4\"],\"correct_order\":[0,1,2,3]}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[0,1,2,3]', 1767108641, 1767113383, 0, '', 1, 0, 0, '7219fea9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
