INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32488, 601, 24, 6, 1, NULL, NULL, NULL, '<p><strong>Stimulus:</strong> Sebuah Usaha Mikro, Kecil, dan Menengah (UMKM) yang bergerak di bidang kerajinan ingin meluncurkan produk tas jinjing unik yang terbuat dari bahan daur ulang kain perca. Mereka ingin memastikan produk ini tidak hanya ramah lingkungan, tetapi juga diminati pasar. Untuk mencapai tujuan tersebut, UMKM ini perlu merencanakan langkah-langkah produksi secara sistematis dari awal hingga produk siap sampai ke tangan konsumen.</p><p><strong>Instruksi:</strong> Urutkanlah langkah-langkah utama yang harus dilakukan oleh UMKM tersebut dalam proses produksi dan persiapan pemasaran produk tas jinjing daur ulang mereka!</p>', '{\"items\":[\"Melakukan riset pasar untuk mengidentifikasi tren desain, preferensi warna, dan segmen harga yang diminati konsumen potensial.\",\"Mengumpulkan dan mengolah kain perca bekas menjadi bahan baku siap pakai, serta mendesain prototipe tas jinjing.\",\"Melaksanakan produksi massal tas jinjing dengan pengawasan kualitas yang ketat pada setiap tahapan.\",\"Menentukan strategi penetapan harga, mengembangkan kemasan yang menarik, dan memilih saluran distribusi yang sesuai (misalnya, toko daring atau butik lokal).\",\"Mendistribusikan produk tas jinjing ke titik penjualan dan meluncurkan kampanye promosi untuk menarik minat pembeli.\"]}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '', 1767348669, 1767348669, 1, '', 1, 0, 0, '721a04c7-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32489, 601, 24, 6, 2, NULL, NULL, NULL, '<p><strong>Stimulus:</strong> Petani buah naga di daerah terpencil sering menghadapi tantangan dalam mendistribusikan hasil panennya ke kota-kota besar. Buah naga adalah komoditas yang mudah rusak dan memerlukan penanganan khusus agar kualitasnya tetap terjaga saat sampai ke konsumen. Sebuah koperasi petani berinisiatif untuk memperbaiki rantai distribusi agar buah naga mereka bisa sampai ke konsumen di kota dalam kondisi prima dan dengan harga yang kompetitif.</p><p><strong>Instruksi:</strong> Urutkanlah tahapan logis dalam proses distribusi buah naga dari petani hingga sampai ke konsumen akhir di perkotaan, dengan mempertimbangkan efisiensi dan kualitas produk!</p>', '{\"items\":[\"Petani memanen buah naga secara selektif dan melakukan sortasi awal berdasarkan kualitas.\",\"Buah naga dikemas dalam wadah khusus yang melindungi dari benturan dan menjaga kesegaran, kemudian diangkut ke pusat pengumpul koperasi.\",\"Koperasi mengatur pengiriman buah naga dalam jumlah besar menggunakan transportasi berpendingin menuju pasar induk atau distributor besar di kota.\",\"Pengecer (misalnya, supermarket atau pedagang pasar tradisional) membeli buah naga dari pasar induk\\/distributor dan memajangnya.\",\"Konsumen membeli buah naga segar dari pengecer di pasar atau supermarket untuk dikonsumsi.\"]}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '', 1767348669, 1767348669, 1, '', 1, 0, 0, '721a05af-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32490, 601, 24, 6, 3, NULL, NULL, NULL, '<p><strong>Stimulus:</strong> Rina adalah seorang siswa SMA yang sangat gemar bermain game. Ponsel lamanya mulai menunjukkan tanda-tanda kerusakan parah, seperti baterai cepat habis dan sering macet. Ia berencana untuk membeli ponsel pintar baru yang lebih canggih, terutama yang memiliki performa gaming yang baik dan daya tahan baterai yang lama. Namun, ia memiliki anggaran terbatas dan banyak pilihan merek di pasar.</p><p><strong>Instruksi:</strong> Urutkanlah tahapan proses pengambilan keputusan yang kemungkinan besar akan dilakukan oleh Rina sebagai seorang konsumen rasional dalam memilih dan membeli ponsel pintar barunya!</p>', '{\"items\":[\"Rina menyadari adanya masalah (kebutuhan ponsel baru) karena ponsel lama rusak dan tidak memadai untuk bermain game.\",\"Mencari informasi secara ekstensif dari berbagai sumber (ulasan online, teman, toko) mengenai ponsel pintar yang memenuhi kriteria gaming dan daya tahan baterai.\",\"Membandingkan spesifikasi, harga, garansi, dan ulasan pengguna dari beberapa pilihan ponsel yang paling sesuai dengan anggaran dan kebutuhannya.\",\"Memilih merek dan model ponsel tertentu, kemudian melakukan pembelian di toko fisik atau platform e-commerce yang terpercaya.\",\"Menggunakan ponsel baru dan mengevaluasi apakah ponsel tersebut memenuhi ekspektasinya dalam hal performa gaming dan daya tahan baterai.\"]}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '', 1767348669, 1767348669, 1, '', 1, 0, 0, '721a0707-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32491, 601, 24, 6, 4, NULL, NULL, NULL, '<p><strong>Stimulus:</strong> Sebuah perusahaan minuman kemasan \'Segar Selalu\' selama ini terkenal dengan produk teh manis botolan. Namun, data riset pasar terbaru menunjukkan adanya pergeseran signifikan dalam preferensi konsumen; semakin banyak orang yang mencari minuman rendah gula atau tanpa gula karena kesadaran akan kesehatan yang meningkat. Penjualan teh manis tradisional mulai stagnan, sementara produk alternatif dari kompetitor yang menawarkan minuman tanpa gula menunjukkan pertumbuhan pesat.</p><p><strong>Instruksi:</strong> Sebagai manajer produksi, urutkanlah langkah-langkah strategis yang harus diambil oleh perusahaan \'Segar Selalu\' untuk merespons perubahan pola konsumsi dan menjaga daya saing di pasar!</p>', '{\"items\":[\"Menganalisis data penjualan dan melakukan survei konsumen lebih mendalam untuk memahami secara spesifik preferensi minuman rendah\\/tanpa gula.\",\"Mengembangkan formula baru untuk produk teh tanpa gula atau minuman sehat lainnya yang sesuai dengan tren, dan melakukan uji coba produk.\",\"Menyesuaikan kapasitas produksi, mengelola rantai pasok bahan baku baru (misalnya, pemanis alami), dan melatih karyawan untuk proses produksi produk baru.\",\"Meluncurkan produk baru dengan strategi pemasaran yang menyoroti manfaat kesehatan dan posisi produk di pasar sebagai alternatif sehat.\",\"Memantau penjualan produk baru, mengumpulkan umpan balik konsumen, dan melakukan penyesuaian strategi produk atau pemasaran jika diperlukan.\"]}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '', 1767348669, 1767348669, 1, '', 1, 0, 0, '721a0869-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32492, 601, 24, 6, 5, NULL, NULL, NULL, '<p><strong>Stimulus:</strong> Restoran \'Rasa Juara\' yang terkenal dengan hidangan khas daerahnya, sebelumnya hanya melayani pelanggan yang makan di tempat. Namun, untuk beradaptasi dengan era digital dan memperluas jangkauan pasar, \'Rasa Juara\' memutuskan untuk bergabung dengan beberapa platform layanan pesan antar makanan <em>online</em>. Ini merupakan perubahan besar yang akan mengubah cara pelanggan berinteraksi dan mengkonsumsi produk mereka.</p><p><strong>Instruksi:</strong> Urutkanlah tahapan yang akan dilalui oleh seorang pelanggan baru yang ingin menikmati hidangan \'Rasa Juara\' melalui layanan pesan antar <em>online</em> tersebut!</p>', '{\"items\":[\"Pelanggan mengetahui bahwa Restoran \'Rasa Juara\' kini tersedia di aplikasi atau platform pesan antar makanan <em>online<\\/em> melalui promosi atau rekomendasi.\",\"Membuka aplikasi pesan antar, mencari restoran \'Rasa Juara\', dan menelusuri daftar menu yang ditawarkan.\",\"Memilih hidangan yang diinginkan, menambahkan ke keranjang, dan melanjutkan ke proses pembayaran yang biasanya terintegrasi dalam aplikasi.\",\"Menunggu pesanan disiapkan oleh restoran dan diantar oleh kurir ke alamat tujuan yang telah ditentukan.\",\"Menerima hidangan, menikmati makanan \'Rasa Juara\', dan kemungkinan memberikan ulasan atau penilaian terhadap pengalaman layanan di aplikasi.\"]}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '', 1767348669, 1767348669, 1, '', 1, 0, 0, '721a09f2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32494, 601, 24, 7, 1, NULL, NULL, NULL, '<p><b>Stimulus:</b> Sebuah sekolah menengah atas memiliki alokasi anggaran dan fasilitas yang terbatas untuk kegiatan ekstrakurikuler. Meskipun banyak siswa memiliki minat beragam seperti robotik, musik, futsal, dan bahasa asing, sekolah hanya mampu membuka tiga jenis ekstrakurikuler setiap tahun ajaran. Hal ini menyebabkan banyak siswa harus memilih di antara pilihan yang ada, dan tidak semua minat dapat diakomodasi.</p><p>Situasi di sekolah yang menunjukkan adanya keterbatasan sumber daya untuk memenuhi berbagai keinginan siswa bergabung dengan ekskul ini mencerminkan adanya fenomena [[kelangkaan]]. Para siswa dihadapkan pada berbagai [[kebutuhan]] untuk mengembangkan minat dan bakat, namun keterbatasan tersebut memaksa mereka untuk melakukan [[tindakan ekonomi]] berupa pemilihan ekskul terbaik sesuai prioritas mereka.</p><div class=\"cloze-content\">Stimulus: Sebuah sekolah menengah atas memiliki alokasi anggaran dan fasilitas yang terbatas untuk kegiatan ekstrakurikuler. Meskipun banyak siswa memiliki minat beragam seperti robotik, musik, futsal, dan bahasa asing, sekolah hanya mampu membuka tiga jenis ekstrakurikuler setiap tahun ajaran. Hal ini menyebabkan banyak siswa harus memilih di antara pilihan yang ada, dan tidak semua minat dapat diakomodasi.Situasi di sekolah yang menunjukkan adanya keterbatasan sumber daya untuk memenuhi berbagai keinginan siswa bergabung dengan ekskul ini mencerminkan adanya fenomena [[kelangkaan]]. Para siswa dihadapkan pada berbagai [[kebutuhan]] untuk mengembangkan minat dan bakat, namun keterbatasan tersebut memaksa mereka untuk melakukan [[tindakan ekonomi]] berupa pemilihan ekskul terbaik sesuai prioritas mereka.</div></body></html>', '{\"blanks\":{\"kelangkaan\":{\"answer\":\"Kelangkaan\",\"case_sensitive\":false},\"kebutuhan\":{\"answer\":\"Kebutuhan\",\"case_sensitive\":false},\"tindakan ekonomi\":{\"answer\":\"Tindakan Ekonomi\",\"case_sensitive\":false}}}', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"kelangkaan\":\"Kelangkaan\",\"kebutuhan\":\"Kebutuhan\",\"tindakan ekonomi\":\"Tindakan Ekonomi\"}', 1767348727, 1767352742, 1, '', 1, 0, 0, '721a0b3f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32495, 601, 24, 7, 2, NULL, NULL, NULL, '<p><b>Stimulus:</b> Nadia, seorang siswi kelas X, menerima uang saku lebih dari orang tuanya. Ia memiliki dua pilihan utama: membeli sepatu olahraga model terbaru yang sedang tren atau menggunakan uang tersebut untuk mengikuti les tambahan persiapan olimpiade matematika yang biayanya cukup mahal. Setelah berpikir, Nadia memutuskan untuk membeli sepatu olahraga.</p><p>Keputusan Nadia untuk membeli sepatu olahraga tersebut berarti ia harus melepaskan kesempatan untuk mengikuti les tambahan. Konsep ini dalam ilmu ekonomi dikenal sebagai [[biaya peluang]]. Pilihan yang diambil Nadia merupakan salah satu bentuk [[tindakan ekonomi]] yang didasari oleh prioritas dan preferensi pribadinya.</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"1\":\"biaya peluang\",\"2\":\"tindakan ekonomi\"}', 1767348727, 1767348727, 1, '', 1, 0, 0, '721a0c80-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32496, 601, 24, 7, 3, NULL, NULL, NULL, '<p><b>Stimulus:</b> Pak Arman adalah pemilik warung makan \'Nusantara\' yang terkenal dengan hidangan otentik daerah. Ia selalu berusaha membeli bahan baku sayuran dan daging langsung dari petani lokal, meskipun harganya terkadang sedikit lebih tinggi dibandingkan pemasok besar. Tujuannya adalah untuk menjaga kualitas rasa, mendukung ekonomi lokal, dan membangun loyalitas pelanggan melalui produk berkualitas dan cerita di baliknya, yang pada akhirnya diharapkan dapat meningkatkan penjualan dan keuntungan jangka panjang.</p><p>Tindakan Pak Arman dalam memilih pemasok lokal dan mempertahankan kualitas, yang pada akhirnya bertujuan untuk mencapai keuntungan berkelanjutan, menunjukkan penerapan [[prinsip ekonomi]]. Keputusannya ini didorong oleh beberapa [[motif ekonomi]], tidak hanya sekadar mencari keuntungan finansial sesaat, tetapi juga membangun hubungan baik dengan komunitas dan citra positif usahanya.</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"1\":\"prinsip ekonomi\",\"2\":\"motif ekonomi\"}', 1767348727, 1767348727, 1, '', 1, 0, 0, '721a0d63-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32497, 601, 24, 7, 4, NULL, NULL, NULL, '<p><b>Stimulus:</b> Sebuah desa terpencil di kaki gunung baru saja dilanda banjir bandang yang merusak sebagian besar rumah dan lahan pertanian. Bantuan dari pemerintah dan organisasi kemanusiaan segera dikirimkan. Prioritas utama bantuan adalah penyediaan makanan pokok, air bersih, obat-obatan, dan tempat penampungan sementara, dibandingkan dengan barang-barang seperti televisi atau kendaraan pribadi.</p><p>Kondisi pasca-bencana yang mengakibatkan keterbatasan akut terhadap sumber daya esensial tersebut menunjukkan adanya [[kelangkaan]] ekstrem. Dalam konteks ini, masyarakat dan pihak pemberi bantuan berfokus untuk memenuhi [[kebutuhan primer]] seperti pangan, sandang, dan papan terlebih dahulu, mengingat urgensi dan dampaknya terhadap kelangsungan hidup.</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"1\":\"kelangkaan\",\"2\":\"kebutuhan primer\"}', 1767348727, 1767348727, 1, '', 1, 0, 0, '721a0e9a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32498, 601, 24, 7, 5, NULL, NULL, NULL, '<p><b>Stimulus:</b> Pemerintah Kabupaten Maju menghadapi tantangan dalam alokasi anggaran pembangunan tahunan. Mereka memiliki daftar panjang proyek yang membutuhkan dana, mulai dari pembangunan jalan baru, peningkatan fasilitas kesehatan di puskesmas, hingga program beasiswa pendidikan untuk siswa berprestasi. Karena keterbatasan dana, tidak semua proyek dapat direalisasikan secara bersamaan, sehingga pemerintah harus membuat pilihan prioritas yang strategis.</p><p>Situasi yang dihadapi oleh Pemerintah Kabupaten Maju merupakan contoh nyata adanya [[kelangkaan]] anggaran. Oleh karena itu, pemerintah perlu melakukan [[tindakan ekonomi]] secara bijaksana dalam menentukan alokasi dana. Setiap keputusan untuk mendanai satu proyek akan selalu menimbulkan [[biaya peluang]] berupa manfaat yang mungkin hilang dari proyek lain yang tidak terpilih atau tertunda pelaksanaannya.</p>', '', '', '', '', '', NULL, NULL, NULL, NULL, NULL, '{\"1\":\"kelangkaan\",\"2\":\"tindakan ekonomi\",\"3\":\"biaya peluang\"}', 1767348727, 1767348727, 1, '', 1, 0, 0, '721a0f8c-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32499, 882, 0, 1, 1, NULL, NULL, NULL, '<p><img class=\"img-fluid\" src=\"http://akm.test/uploads/bank_soal/file_20220303090946.png\"></p><p>Badan Geologi, Kementerian ESDM dan Mitigasi Bencana Geologi Sumatra Utara sedang mengamati ketinggian letusan awan panas gunung Sinabung pada hari tersebut. Puncak gunung terlihat pada sudut elevasi 30&deg; sedangkan puncak letusan awan panas terlihat pada sudut elevasi 60&deg;.</p><p>Jika tinggi gunung Sinabung adalah 2.460 meter, maka tinggi letusan awan panas gunung tersebut dari puncak gunung adalah ......</p></body></html>', '<p>1.796 meter</p></body></html>', '<p>4.256 meter</p></body></html>', '<p>4.260 meter</p></body></html>', '<p>4.320 meter</p></body></html>', '<p>4.920 meter</p></body></html>', NULL, NULL, NULL, NULL, NULL, 'e', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a10b2-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32500, 882, 0, 5, 1, NULL, NULL, NULL, '<p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303091037.png\" style=\"width: 466px;\"><br></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Badan Geologi, Kementerian ESDM dan Mitigasi Bencana Geologi Sumatra Utara sedang mengamati ketinggian letusan awan panas gunung&nbsp;Sinabung pada hari tersebut. Puncak gunung terlihat pada&nbsp;sudut elevasi 30° sedangkan puncak letusan awan panas terlihat pada sudut elevasi 60°.</p><br style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Diketahui tinggi gunung Sinabung adalah 2.460 meter dan terjadi kesalahan dalam mengukur sudut elevasi. Besar sudut elevasi untuk melihat tinggi erupsi seharusnya adalah 50<span style=\"position: relative; font-size: 12px; line-height: 0; vertical-align: baseline; top: -0.5em;\">o</span>.&nbsp;Akibat kesalahan ini, bagaimanakah tinggi erupsi gunung sebenarnya? Apakah lebih tinggi atau lebih rendah bila dibandingkan dengan tinggi erupsi yang didapatkan dari sudut elevasi semula? Beri alasannya!</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><br></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><b>Jawab :</b></p>\r\n\r\nTinggi erupsi sebenarnya lebih rendah bila dibandingkan dengan perkiraan tinggi erupsi semula karena nilai tan 50 &lt; tan 60.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div>Tinggi erupsi sebenarnya lebih rendah bila dibandingkan dengan perkiraan tinggi erupsi semula karena nilai tan 50 < tan></div></div>', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a118b-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32501, 882, 0, 4, 1, NULL, NULL, NULL, '<p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Sistem penyelenggaraan telekomunikasi di Indonesia terbagi menjadi jaringan tetap (kabel dan nirkabel) dan jaringan bergerak (selular). Dalam perkembangannya, telah terjadi pergeseran pada sektor telekomunikasi di Indonesia.&nbsp;Awalnya masyarakat Indonesia menggunakan jaringan telekomunikasi yang berbasis pada kabel.&nbsp;Namun mobilitas yang tinggi serta kebutuhan akan akses informasi yang cepat dan akurat telah menggeser pilihan moda telekomunikasi yang digunakan masyarakat Indonesia.</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Grafik berikut menunjukkan pertumbuhan&nbsp;pengguna&nbsp;telepon seluler, nirkabel dan kabel di Indonesia (dalam pembulatan puluhan juta terdekat).</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><img src=\"http://pts1.id/siswa/uploads/bank_soal/file_20220303091130.png\" style=\"width: 479px;\"></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Namun demikian, dari tahun 2000 sampai 2007, banyak&nbsp;pengguna telepon seluler (dalam juta)&nbsp;dapat didekati dengan model fungsi&nbsp;<em>f(x)&nbsp;</em>= 1,3<em>x</em><span style=\"position: relative; font-size: 12px; line-height: 0; vertical-align: baseline; top: -0.5em;\">2</span>&nbsp;+ 1,6<em>x</em>&nbsp;+ 3,7&nbsp;dengan&nbsp;<em>x</em>&nbsp;= 0 merepresentasikan tahun 2000.</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Banyak pengguna telepon seluler di Indonesia akan mencapai angka 78,6 juta pada tahun...</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><br></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><b>Jawab :</b></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">2007</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2007', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a1360-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32502, 882, 0, 3, 1, NULL, NULL, NULL, '<p style=\"\">Sistem penyelenggaraan telekomunikasi di Indonesia terbagi menjadi jaringan tetap (kabel dan nirkabel) dan jaringan bergerak (selular). Dalam perkembangannya, telah terjadi pergeseran pada sektor telekomunikasi di Indonesia.&nbsp;Awalnya masyarakat Indonesia menggunakan jaringan telekomunikasi yang berbasis pada kabel.&nbsp;Namun mobilitas yang tinggi serta kebutuhan akan akses informasi yang cepat dan akurat telah menggeser pilihan moda telekomunikasi yang digunakan masyarakat Indonesia.</p><br style=\"\"><p style=\"\">Grafik berikut menunjukkan pertumbuhan&nbsp;pengguna&nbsp;telepon seluler, nirkabel dan kabel di Indonesia (dalam pembulatan puluhan juta terdekat).</p><p style=\"\"><img src=\"http://akm.test/uploads/bank_soal/file_20220303091300.png\" style=\"width: 479px;\"></p><p style=\"\">Namun demikian, dari tahun 2000 sampai 2007, banyak&nbsp;pengguna telepon seluler (dalam juta)&nbsp;dapat didekati dengan model fungsi&nbsp;f(x)&nbsp;= 1,3x<span style=\"position: relative; line-height: 0; vertical-align: baseline; top: -0.5em;\">2</span>&nbsp;+ 1,6x&nbsp;+ 3,7&nbsp;dengan&nbsp;x&nbsp;= 0 merepresentasikan tahun 2000.</p><p style=\"\"><br></p><p style=\"\">Berdasarkan grafik dan pendekatan model fungsi yang diberikan, tentukan Benar atau Salah untuk setiap pernyataan berikut!</p></body></html>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"model\":\"2\",\"type\":\"2\",\"jawaban\":[[\"PERNYATAAN\",\"Benar\",\"Salah\"],[\"Pengguna telepon nirkabel diperkirakan akan dapat melampaui pengguna telepon kabel pada tahun 2010.\",\"1\",\"0\"],[\"Banyak pengguna telepon seluler akan terus bertambah menjadi 302,2 juta pada tahun 2015.\",\"0\",\"1\"],[\"Banyak pengguna telepon kabel setiap tahunnya cenderung statis.\",\"1\",\"0\"],[\"Dengan menggunakan pendekatan model fungsi yang dibuat, pertambahan pengguna telepon seluler di Indonesia diperkirakan akan melambat setelah tahun 2007.\",\"0\",\"1\"]]}', 1767461630, 1767462322, 1, '', 1, 0, 0, '721a14cd-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32503, 882, 0, 2, 1, NULL, NULL, NULL, '<p class=\"MsoNormal\" align=\"center\" style=\"line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">FINAL PIALA DUNIA DAN PELUANGNYA<o:p></o:p></p>\r\n\r\n<p style=\"\"><span style=\"text-align: left;\">Amel mengunduh bagan\r\npertandingan sepak bola piala dunia yang dimulai dari babak perempat final.\r\nBerikut adalah bagan yang berhasil didapatkan Amel.</span></p><p style=\"\"><img src=\"http://localhost/akm/uploads/bank_soal/file_20220303092739.png\" style=\"text-align: left; width: 536px;\"><br></p><p class=\"MsoNormal\" style=\"line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Kemudian Amel menyebarkan survei kepada teman-temannya yang menyukai sepak\r\nbola dan selalu menonton pertandingan sepak bola pada tahun-tahun sebelumnya.\r\nBerikut adalah tabel peluang tim-tim di atas untuk menang babak perempat final\r\nyang berhasil disimpulkan oleh Amel berdasarkan survei yang dibuatnya.\r\nSedangkan untuk babak selanjutnya, yaitu semifinal dan final semua tim memiliki\r\npeluang menang yang sama yaitu 50%.<o:p></o:p></p><p style=\"\"><img src=\"http://localhost/akm/uploads/bank_soal/file_20220303092800.png\" style=\"width: 528px;\"></p><p style=\"\"><b><font color=\"#000000\" style=\"background-color: rgb(255, 255, 0);\">Manakah pernyataan yang benar berdasarkan bagan pertandingan piala dunia yang diunduh Amel dan juga tabel peluang hasil survei Amel? Berilah tanda centang (√) pada setiap pernyataan yang benar!</font></b><br></p>', 'a:4:{s:1:\"a\";s:306:\"<p><span style=\"\" segoe=\"\" ui\",=\"\" roboto,=\"\" \"helvetica=\"\" neue\",=\"\" arial,=\"\" \"noto=\"\" sans\",=\"\" sans-serif,=\"\" \"apple=\"\" color=\"\" emoji\",=\"\" \"segoe=\"\" ui=\"\" symbol\",=\"\" emoji\";=\"\" font-size:=\"\" 16px;\"=\"\">Peluang tim Uruguay dan Kroasia untuk menang babak perempat final adalah sama besar.</span><br></p>\";s:1:\"b\";s:317:\"<p><span style=\"\" segoe=\"\" ui\",=\"\" roboto,=\"\" \"helvetica=\"\" neue\",=\"\" arial,=\"\" \"noto=\"\" sans\",=\"\" sans-serif,=\"\" \"apple=\"\" color=\"\" emoji\",=\"\" \"segoe=\"\" ui=\"\" symbol\",=\"\" emoji\";=\"\" font-size:=\"\" 16px;\"=\"\">Peluang tim Prancis untuk menang babak perempat final lebih besar bila dibandingkan tim Brazil.</span><br></p>\";s:1:\"c\";s:291:\"<p><span style=\"\" segoe=\"\" ui\",=\"\" roboto,=\"\" \"helvetica=\"\" neue\",=\"\" arial,=\"\" \"noto=\"\" sans\",=\"\" sans-serif,=\"\" \"apple=\"\" color=\"\" emoji\",=\"\" \"segoe=\"\" ui=\"\" symbol\",=\"\" emoji\";=\"\" font-size:=\"\" 16px;\"=\"\">Jumlah peluang menang untuk setiap tahapan pertandingan berbeda-beda.</span><br></p>\";s:1:\"d\";s:409:\"<p><span style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, \"Noto Sans\", sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\", \"Segoe UI Symbol\", \"Noto Color Emoji\"; font-size: 16px;\">Di antara semua tim yang akan bertanding di babak perempat final, Inggris mempunyai peluang yang terbesar untuk menang babak perempat final.</span><br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"b\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;N;}', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a161d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32504, 882, 0, 1, 2, NULL, NULL, NULL, '<p style=\"text-align: center; \"><b>FINAL PIALA DUNIA DAN PELUANGNYA</b></p><p>Amel mengunduh bagan pertandingan sepak bola piala dunia yang dimulai dari babak perempat final. Berikut adalah bagan yang berhasil didapatkan Amel.</p><p><img class=\"img-fluid\" src=\"http://akm.test/uploads/bank_soal/file_20220303092739.png\"></p><p>Kemudian Amel menyebarkan survei kepada teman-temannya yang menyukai sepak bola dan selalu menonton pertandingan sepak bola pada tahun-tahun sebelumnya. Berikut adalah tabel peluang tim-tim di atas untuk menang babak perempat final yang berhasil disimpulkan oleh Amel berdasarkan survei yang dibuatnya. Sedangkan untuk babak selanjutnya, yaitu semifinal dan final semua tim memiliki peluang menang yang sama yaitu 50%.</p><p><img class=\"img-fluid\" src=\"http://akm.test/uploads/bank_soal/file_20220303092800.png\"></p><p>Berdasarkan data pada bagan pertandingan piala dunia dan tabel peluang yang dikumpulkan Amel, peluang Perancis untuk menjadi juara dunia adalah &hellip;.</p></body></html>', '<p>0,125</p></body></html>', '<p>0,175</p></body></html>', '<p>0,343</p></body></html>', '<p>0,95</p></body></html>', '<p>1</p></body></html>', NULL, NULL, NULL, NULL, NULL, 'b', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a174d-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32505, 882, 0, 5, 2, NULL, NULL, NULL, '<p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><span style=\"font-weight: bolder; text-align: center;\">FINAL PIALA DUNIA DAN PELUANGNYA</span><br></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Amel mengunduh bagan pertandingan sepak bola piala dunia yang dimulai dari babak perempat final. Berikut adalah bagan yang berhasil didapatkan Amel.<img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303092739.png\" style=\"width: 536px;\"></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Kemudian Amel menyebarkan survei kepada teman-temannya yang menyukai sepak bola dan selalu menonton pertandingan sepak bola pada tahun-tahun sebelumnya. Berikut adalah tabel peluang tim-tim di atas untuk menang babak perempat final yang berhasil disimpulkan oleh Amel berdasarkan survei yang dibuatnya. Sedangkan untuk babak selanjutnya, yaitu semifinal dan final semua tim memiliki peluang menang yang sama yaitu 50%.</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303092800.png\" style=\"width: 528px;\"></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Seorang teman yang membaca hasil survei memprediksi bahwa Brazil akan menjadi juara.&nbsp;Benarkah prediksi tersebut?&nbsp;Jelaskan alasanmu!</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><b>Jawaban :&nbsp;</b></p>\r\nPeluang brazil menang dan menjadi juara dunia adalah = 0.6*0.5*0.5 = 0.15, sedangkan peluang tidak juara = 1- 0.15 = 0.85. maka rasio menang dan tidak menang untuk brazil adalah 15 : 85 = 3 : 17.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div>Peluang brazil menang dan menjadi juara dunia adalah = 0.6*0.5*0.5 = 0.15, sedangkan peluang tidak juara = 1- 0.15 = 0.85. maka rasio menang dan tidak menang untuk brazil adalah 15 : 85 = 3 : 17.<br></div>', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a183a-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32506, 882, 0, 4, 2, NULL, NULL, NULL, '<p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Anita, seorang seniman muda dari Sumatera berencana membuat pameran tunggal untuk menunjukkan rancangan karyanya yang disusun dari&nbsp;tumpukan bola-bola tanah. Bola-bola tersebut dibuat dari campuran tanah liat dan sampah daur ulang. Polanya&nbsp;seperti gambar berikut.<br><img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303091621.png\" style=\"width: 204px;\"><br>Untuk memenuhi ruangan yang disediakan, Anita akan membuat 10 susunan bola tersebut. (Asumsi ada penambahan 10% bola tanah untuk persediaan/penggantian bola tanah yang rusak selama masa pameran di setiap susunan bola).</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Jumlah bola tanah pada susunan ke 7 adalah ............&nbsp;bola tanah.</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><br></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><b>Jawaban :</b></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">36</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '36', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a1968-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32507, 882, 0, 3, 2, NULL, NULL, NULL, '<p style=\"\">Anita, seorang seniman muda dari Sumatera berencana membuat pameran tunggal untuk menunjukkan rancangan karyanya yang disusun dari&nbsp;tumpukan bola-bola tanah. Bola-bola tersebut dibuat dari campuran tanah liat dan sampah daur ulang. Polanya&nbsp;seperti gambar berikut.<br><img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303091743.png\" style=\"width: 204px;\"><br>Untuk memenuhi ruangan yang disediakan, Anita akan membuat 10 susunan bola tersebut. (Asumsi ada penambahan 10% bola tanah untuk persediaan/penggantian bola tanah yang rusak selama masa pameran di setiap susunan bola).</p><br style=\"\"><p style=\"\">Anita juga akan mewarnai susunan bola tanah tersebut dengan 1 bola warna kuning dan sisanya warna merah (di setiap susunan) seperti gambar berikut.<br><img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303091827.png\" style=\"width: 208px;\"><br>Berdasarkan pengalaman sebelumnya, banyak cat kuning yang dibutuhkan diperkirakan sebanyak 1 kaleng.&nbsp;Jika dianggap&nbsp;ukuran dan isi 1 kaleng cat merah sama dengan 1 kaleng cat kuning, tentukan&nbsp;Benar&nbsp;atau&nbsp;Salah&nbsp;setiap pernyataan berikut!</p><div><br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:3:{i:0;s:1:\"#\";i:1;s:5:\"Benar\";i:2;s:5:\"Salah\";}i:1;a:3:{i:0;s:51:\"Banyak bola tanah yang akan dicat merah adalah 275.\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:2;a:3:{i:0;s:50:\"Banyak cat merah yang dibutuhkan adalah 265 kaleng\";i:1;s:1:\"0\";i:2;s:1:\"1\";}i:3;a:3:{i:0;s:111:\"Apabila bola tanah cadangan akan dicat dengan warna merah semua, maka cat merah yang dibutuhkan adalah 3 kaleng\";i:1;s:1:\"1\";i:2;s:1:\"0\";}i:4;a:3:{i:0;s:137:\"Apabila dari setiap susunan ada dua bola yang dicat kuning dan yang lainnya merah, maka jumlah cat merah yang dibutuhkan hanya 255 kaleng\";i:1;s:1:\"0\";i:2;s:1:\"1\";}}}', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a1d25-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32508, 882, 0, 2, 2, NULL, NULL, NULL, '<p style=\"\"><img src=\"http://localhost/akm/uploads/bank_soal/file_20220303095353.png\" style=\"width: 500px;\"><br></p><p style=\"\">Peran Usaha Mikro Kecil dan Menengah (UMKM) sangat besar bagi perekonomian Indonesia. Pada saat usaha besar sedang dalam tren melambat, pertumbuhan produk domestik bruto (PDB) UMKM cukup stabil. Tidak memandang latar belakang dan pendidikan seseorang, setiap orang memiliki kesempatan yang sama dalam memulai bisnis usaha UMKM. Agar masyarakat tertarik dalam usaha UMKM, pemerintah menurunkan Pph final dari 1% menjadi 0,5% sehingga pelaku usaha UMKM tidak merasa terlalu dibebani pajak.</p><p><br style=\"\"></p><p style=\"\">Nah, Sobat, bagi kamu yang berencana untuk memiliki UMKM sendiri, kamu bisa memulainya dengan modal kecil, lho. Terdapat banyak jenis UMKM yang bisa kamu jadikan referensi untuk merintis usaha. Bidang kuliner merupakan salah satu jenis UMKM yang menguntungkan dan selalu laris. Bisnis kuliner juga memiliki banyak kategori, seperti makanan ringan, minuman, sampai dengan makanan pokok. Semua usaha kuliner memiliki potensi yang bagus karena kuliner banyak dicari oleh masyarakat, terlebih yang tinggal di kota besar. Walaupun demikian, keberhasilan menjalankan UMKM tetap tergantung pada bagaimana kamu memasarkan produk dan berinovasi.</p><p><br style=\"\"></p><p style=\"\">Sobat, dari infografik di atas kita tahu bahwa UMKM sangat penting untuk pertumbuhan ekonomi Indonesia sehingga keberlangsungan UMKM harus terus didorong. Agar UMKM terus berkembang, sumber daya manusianya pun perlu memiliki kemampuan yang sesuai untuk menjalankan usaha. Cara yang efektif untuk meningkatkan kemampuan berbisnis adalah dengan mengikuti pelatihan bisnis. Pelatihan tersebut biasanya mendatangkan para pelaku bisnis yang sukses dan yang dapat membantu peserta melihat peluang mendapat keuntungan terbaik. Salah satu program pelatihan bisnis yang dapat kamu ikuti adalah Business Leadership Workshop yang diselenggarakan GELCE. Pelatihan ini selalu mendatangkan pelatih yang berkompeten di bidangnya dan memberi kesempatan pemilik bisnis untuk bekerja sama untuk meningkatkan bisnisnya.</p><p><br style=\"\"></p><p style=\"\">(Sumber: www.indonesiabaik.id, https://ajaib.co.id/selain-modal-ini-cara-memulai-bisnis-ukm/, dan https://glcworld.co.id/pelatihan-usaha-kecil-mengengah)</p><div>Berikan tanda ceklis ( √ ) pada alasan yang sesuai dengan pemahamanmu!</div>', 'a:4:{s:1:\"a\";s:57:\"<p>UMKM dapat menyerap tenaga kerja sangat banyak<br></p>\";s:1:\"b\";s:59:\"<p>Untuk merintis UMKM diperlukan modal yang besar.<br></p>\";s:1:\"c\";s:67:\"<p>Bisnis UMKM mendominasi perekonomian di Indonesia.&nbsp;<br></p>\";s:1:\"d\";s:63:\"<p>Pelaku UMKM harus memiliki keterampilan profesional.<br></p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:4:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;s:1:\"d\";i:3;N;}', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a1ec9-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32509, 882, 0, 3, 3, NULL, NULL, NULL, '<p style=\"\">Anita, seorang seniman muda dari Sumatera berencana membuat pameran tunggal untuk menunjukkan rancangan karyanya yang disusun dari&nbsp;tumpukan bola-bola tanah. Bola-bola tersebut dibuat dari campuran tanah liat dan sampah daur ulang. Polanya&nbsp;seperti gambar berikut.<br><img src=\"http://pas.id/siswa/uploads/bank_soal/file_20220303092132.png\" style=\"width: 204px;\"><br>Untuk memenuhi ruangan yang disediakan, Anita akan membuat 10 susunan bola tersebut. (Asumsi ada penambahan 10% bola tanah untuk persediaan/penggantian bola tanah yang rusak selama masa pameran di setiap susunan bola).</p><br style=\"\"><p style=\"\">Atas pertimbangan beberapa faktor, Anita masih mempertimbangkan banyaknya susunan bola yang akan dibentuk dan berapa banyak bola tanah yang harus disediakan. Dengan asumsi jumlah penambahan bola yang sama, bantulah Anita untuk menghitung dan memasangkan banyaknya bola tanah dan jumlah susunan maksimal yang dapat dibentuk!</p><div><br></div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{s:5:\"model\";s:1:\"2\";s:4:\"type\";s:1:\"2\";s:7:\"jawaban\";a:5:{i:0;a:5:{i:0;s:9:\"<p>#</p>\n\";i:1;s:1:\"7\";i:2;s:1:\"8\";i:3;s:1:\"9\";i:4;s:2:\"10\";}i:1;a:5:{i:0;s:11:\"<p>100</p>\n\";i:1;s:1:\"1\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"0\";}i:2;a:5:{i:0;s:11:\"<p>200</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"1\";i:3;s:1:\"0\";i:4;s:1:\"0\";}i:3;a:5:{i:0;s:11:\"<p>300</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"1\";i:4;s:1:\"0\";}i:4;a:5:{i:0;s:11:\"<p>400</p>\n\";i:1;s:1:\"0\";i:2;s:1:\"0\";i:3;s:1:\"0\";i:4;s:1:\"1\";}}}', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a201f-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32510, 882, 0, 4, 3, NULL, NULL, NULL, '<p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px; text-align: center;\"><span style=\"font-weight: bolder;\">FINAL PIALA DUNIA DAN PELUANGNYA</span></p><br style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Amel mengunduh bagan pertandingan sepak bola piala dunia yang dimulai dari babak perempat final. Berikut adalah bagan yang berhasil didapatkan Amel.<img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303092739.png\" style=\"width: 536px;\"></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Kemudian Amel menyebarkan survei kepada teman-temannya yang menyukai sepak bola dan selalu menonton pertandingan sepak bola pada tahun-tahun sebelumnya. Berikut adalah tabel peluang tim-tim di atas untuk menang babak perempat final yang berhasil disimpulkan oleh Amel berdasarkan survei yang dibuatnya. Sedangkan untuk babak selanjutnya, yaitu semifinal dan final semua tim memiliki peluang menang yang sama yaitu 50%.</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303092800.png\" style=\"width: 528px;\"></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Andi, Budi, dan Candra adalah teman Amel yang menyukai sepak bola dan selalu menonton pertandingannya. Berdasarkan tabel hasil survei yang diperlihatkan Amel, ketiga teman Amel tersebut memiliki prediksi yang berbeda tentang siapa yang akan menjadi juara tahun ini. Andi memprediksi Brazil, Budi memprediksi Prancis, dan Candra memprediksi Inggris. Prediksi siapakah yang paling berpeluang benar?</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><b>Jawaban :&nbsp;</b></p><p style=\"\"><font color=\"#212529\" face=\"-apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, Noto Sans, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol, Noto Color Emoji\"><span style=\"font-size: 16px;\">Candra</span></font><br></p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Candra', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a213e-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32511, 882, 0, 5, 3, NULL, NULL, NULL, '<p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"><img src=\"https://pustaka-smandu.net/pts_2022_ganjil/uploads/bank_soal/file_20220303095353.png\" style=\"width: 500px;\"><br></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Peran Usaha Mikro Kecil dan Menengah (UMKM) sangat besar bagi perekonomian Indonesia. Pada saat usaha besar sedang dalam tren melambat, pertumbuhan produk domestik bruto (PDB) UMKM cukup stabil. Tidak memandang latar belakang dan pendidikan seseorang, setiap orang memiliki kesempatan yang sama dalam memulai bisnis usaha UMKM. Agar masyarakat tertarik dalam usaha UMKM, pemerintah menurunkan Pph final dari 1% menjadi 0,5% sehingga pelaku usaha UMKM tidak merasa terlalu dibebani pajak.</p><p><br style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Nah, Sobat, bagi kamu yang berencana untuk memiliki UMKM sendiri, kamu bisa memulainya dengan modal kecil, lho. Terdapat banyak jenis UMKM yang bisa kamu jadikan referensi untuk merintis usaha. Bidang kuliner merupakan salah satu jenis UMKM yang menguntungkan dan selalu laris. Bisnis kuliner juga memiliki banyak kategori, seperti makanan ringan, minuman, sampai dengan makanan pokok. Semua usaha kuliner memiliki potensi yang bagus karena kuliner banyak dicari oleh masyarakat, terlebih yang tinggal di kota besar. Walaupun demikian, keberhasilan menjalankan UMKM tetap tergantung pada bagaimana kamu memasarkan produk dan berinovasi.</p><p><br style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Sobat, dari infografik di atas kita tahu bahwa UMKM sangat penting untuk pertumbuhan ekonomi Indonesia sehingga keberlangsungan UMKM harus terus didorong. Agar UMKM terus berkembang, sumber daya manusianya pun perlu memiliki kemampuan yang sesuai untuk menjalankan usaha. Cara yang efektif untuk meningkatkan kemampuan berbisnis adalah dengan mengikuti pelatihan bisnis. Pelatihan tersebut biasanya mendatangkan para pelaku bisnis yang sukses dan yang dapat membantu peserta melihat peluang mendapat keuntungan terbaik. Salah satu program pelatihan bisnis yang dapat kamu ikuti adalah Business Leadership Workshop yang diselenggarakan GELCE. Pelatihan ini selalu mendatangkan pelatih yang berkompeten di bidangnya dan memberi kesempatan pemilik bisnis untuk bekerja sama untuk meningkatkan bisnisnya.</p><p><br style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\"></p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">(Sumber: www.indonesiabaik.id, https://ajaib.co.id/selain-modal-ini-cara-memulai-bisnis-ukm/, dan https://glcworld.co.id/pelatihan-usaha-kecil-mengengah)</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Berdasarkan teks, terdapat pernyataan bahwa UMKM di bidang kuliner adalah salah satu jenis usaha yang menguntungkan dan selalu laris. Apakah pernyataan itu dapat dikatakan akurat? Jelaskan pendapatmu!</p><p style=\"color: rgb(33, 37, 41); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px;\">Jawaban :</p>\r\n\r\nTidak akurat karena usaha kuliner bisa saja tidak laris jika tidak dikemas dengan kreatif dan inovatif. jika terlalu banyak orang yang berbisnis kuliner, persaingan makin ketat sehingga perlu cara lain untuk membuat makanan tersebut laris. selain itu, terdapat bisnis lain yang juga berpotensi laris, yaitu yang berhubungan dengan kebutuhan mendasar, seperti pakaian dan peralatan rumah tangga.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<div><div><div>Tidak akurat karena usaha kuliner bisa saja tidak laris jika tidak dikemas dengan kreatif dan inovatif. jika terlalu banyak orang yang berbisnis kuliner, persaingan makin ketat sehingga perlu cara lain untuk membuat makanan tersebut laris. selain itu, terdapat bisnis lain yang juga berpotensi laris, yaitu yang berhubungan dengan kebutuhan mendasar, seperti pakaian dan peralatan rumah tangga.</div></div></div>', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a2268-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32512, 882, 0, 2, 3, NULL, NULL, NULL, '<p style=\"\">Ramin Tak Kunjung Pulang</p><br style=\"\"><p style=\"\">Ramin nyaris menjerit, tangannya tertumbuk dahan hanyut saat buru-buru sembunyi di dalam pelukan akar, untung ia segera melihat dahan itu. Hampir ia mengira dahan itu adalah mulut buaya yang siap menelan lengannya.</p><br style=\"\"><p style=\"\">Teringat lagi ia pada Aco, sejak semusim lalu ia ikut Dadan karena hasil cengkehnya tak bagus, sementara tengkulaknya minta selalu dibayar. Aco tertangkap petugas saat adu mulut di warung nasi lemak lantaran ia mengumpat pada preman yang menutupi jalan.</p><br style=\"\"><p style=\"\">Hari itu memang perpaduan nasib sial jatuh di hadapan Aco. Umpatannya didengar preman, adu mulut terjadi, dan petugas sedang lewat. Apes. Aco lalu dibawa petugas, digiring bagai ternak ke tengah lapangan, dipukuli dengan bengis saat mencoba kabur, ditanyai macam-macam, didenda hingga ia tak sanggup bayar, diambil hasil kerjanya satu musim, dideportasi, pulang ke rumah dengan tangan hampa, ditunggu tengkulak pula. Bah! Hilang sudah satu kebun cengkeh dirundung sial.</p><br style=\"\"><p style=\"\">Gara-gara Aco juga, petugas kini memburu Ramin dan Dadan. Ternyata Dadan memang sudah dicari-cari petugas karena beberapa kali memasukkan tenaga kerja tanpa izin. Ramin memang tak berpikir panjang saat berangkat kerja dengan Dadan, yang penting ia bisa membawa pulang uang untuk menikahkan anaknya, buat pengobatan sakit gula ayahnya, dan sisanya bisa ia belikan mesin cuci yang saban hari diminta istrinya.</p><br style=\"\"><p style=\"\">Ramin tak mau nasib nahas Aco terjadi pada dirinya. Wajah sumringah anak gadisnya sudah terbayang girang menyambutnya dengan ransel penuh uang.</p><br style=\"\"><p style=\"\">Bunyi langkah mendekat, pelan, Ramin membeku, sekuat-kuatnya menahan napas. Baginya lebih baik tak bernapas daripada tertangkap petugas-petugas berwajah garang itu. Bisik-bisik makin kencang. Ramin memutar otak. Kalau mereka melihat rumput-rumput rebah itu, atau kalau ada satu dua orang cukup jitu tebakannya, mungkin mereka bisa yakin kalau pelarian yang mereka kejar bersembunyi di antara akar pohon.</p><br style=\"\"><p style=\"\">(Karya: Lina PW, Kompas, 8 Desember 2019)</p><br style=\"\"><p style=\"\">Pada paragraf terakhir, apa perasaan yang digambarkan oleh penulis tentang tokoh Ramin? Jawaban bisa lebih dari satu.</p>', 'a:4:{s:1:\"a\";s:16:\"<p>Ketakutan</p>\";s:1:\"b\";s:16:\"<p>Ragu-ragu</p>\";s:1:\"c\";s:15:\"<p>Khawatir</p>\";s:1:\"d\";s:12:\"<p>Marah</p>\";}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a:3:{i:0;s:1:\"a\";i:1;s:1:\"c\";i:2;N;}', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a23f5-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`, `sync_uuid`, `sync_status`, `sync_at`, `sync_origin`, `sync_school_uuid`, `deleted_at`) VALUES (32513, 882, 0, 1, 3, NULL, NULL, NULL, '<p><img class=\"img-fluid\" src=\"http://akm.test/uploads/bank_soal/file_20220303095353.png\"></p><p>Peran Usaha Mikro Kecil dan Menengah (UMKM) sangat besar bagi perekonomian Indonesia. Pada saat usaha besar sedang dalam tren melambat, pertumbuhan produk domestik bruto (PDB) UMKM cukup stabil. Tidak memandang latar belakang dan pendidikan seseorang, setiap orang memiliki kesempatan yang sama dalam memulai bisnis usaha UMKM. Agar masyarakat tertarik dalam usaha UMKM, pemerintah menurunkan Pph final dari 1% menjadi 0,5% sehingga pelaku usaha UMKM tidak merasa terlalu dibebani pajak.</p><p>Nah, Sobat, bagi kamu yang berencana untuk memiliki UMKM sendiri, kamu bisa memulainya dengan modal kecil, lho. Terdapat banyak jenis UMKM yang bisa kamu jadikan referensi untuk merintis usaha. Bidang kuliner merupakan salah satu jenis UMKM yang menguntungkan dan selalu laris. Bisnis kuliner juga memiliki banyak kategori, seperti makanan ringan, minuman, sampai dengan makanan pokok. Semua usaha kuliner memiliki potensi yang bagus karena kuliner banyak dicari oleh masyarakat, terlebih yang tinggal di kota besar. Walaupun demikian, keberhasilan menjalankan UMKM tetap tergantung pada bagaimana kamu memasarkan produk dan berinovasi.</p><p>Sobat, dari infografik di atas kita tahu bahwa UMKM sangat penting untuk pertumbuhan ekonomi Indonesia sehingga keberlangsungan UMKM harus terus didorong. Agar UMKM terus berkembang, sumber daya manusianya pun perlu memiliki kemampuan yang sesuai untuk menjalankan usaha. Cara yang efektif untuk meningkatkan kemampuan berbisnis adalah dengan mengikuti pelatihan bisnis. Pelatihan tersebut biasanya mendatangkan para pelaku bisnis yang sukses dan yang dapat membantu peserta melihat peluang mendapat keuntungan terbaik. Salah satu program pelatihan bisnis yang dapat kamu ikuti adalah Business Leadership Workshop yang diselenggarakan GELCE. Pelatihan ini selalu mendatangkan pelatih yang berkompeten di bidangnya dan memberi kesempatan pemilik bisnis untuk bekerja sama untuk meningkatkan bisnisnya.</p><p><span style=\"font-size: 10px;\">(Sumber: www.indonesiabaik.id, https://ajaib.co.id/selain-modal-ini-cara-memulai-bisnis-ukm/, dan https://glcworld.co.id/pelatihan-usaha-kecil-mengengah)</span></p><p>UMKM perlu didukung oleh sumber daya manusia yang memiliki kemampuan untuk menjalankan usaha karena &hellip;.</p></body></html>', '<p>Pengembangan UMKM sangat penting dalam mendorong perekonomian</p></body></html>', '<p>Indonesia kemampuan yang baik dapat diperoleh oleh pelatihan-pelatihan yang disediakan pemerintah</p></body></html>', '<p>Mengembangkan kualitas sumber daya manusia adalah hal yang perlu diprioritaskan</p></body></html>', '<p>Diperlukan keterampilan agar usaha yang dijalankan dapat bertahan dan berkembang</p></body></html>', '<p>Semua pernyataan benar</p></body></html>', NULL, NULL, NULL, NULL, NULL, 'd', 1767461630, 1767461630, 1, '', 1, 0, 0, '721a2786-e8d9-11f0-a465-0a0027000004', 'synced', '2026-01-04 14:12:53', 'lokal', 'ece44576-9051-4b66-9b7e-1b85e3666b1b', NULL);
